window.DEFAULT_VOCAB = [{"id":"n1-redbook-0001","seq":1,"level":"N1","type":"主词条","word":"相容れない","kana":"あいいれない","pos":"[連語]","accent":"①","meaning":"不相容，互不两立","example":"表面上は協力関係を保っていても、利益を最優先する姿勢と安全を重んじる姿勢は根本的に相容れない。","exampleZh":"即使表面上维持着合作关系，将利益置于首位的态度与重视安全的态度从根本上也无法相容。","note":"例：\n表面上は協力関係を保っていても、利益を最優先する姿勢と安全を重んじる姿勢は根本的に相容れない。\n译：即使表面上维持着合作关系，将利益置于首位的态度与重视安全的态度从根本上也无法相容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0002","seq":2,"level":"N1","type":"主词条","word":"相方","kana":"あいかた","pos":"[名]","accent":"⓪","meaning":"伙伴，搭档","example":"舞台に上がる直前、相方が小さくうなずいただけで、彼は緊張よりも安心感のほうが大きくなった。","exampleZh":"登台前一刻，搭档只是轻轻点了点头，他心中的安心感便逐渐超过了紧张。","note":"例：\n舞台に上がる直前、相方が小さくうなずいただけで、彼は緊張よりも安心感のほうが大きくなった。\n译：登台前一刻，搭档只是轻轻点了点头，他心中的安心感便逐渐超过了紧张。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0003","seq":3,"level":"N1","type":"主词条","word":"愛嬌","kana":"あいきょう","pos":"[名]","accent":"③","meaning":"可爱之处；好感，亲切","example":"受付の女性には自然な愛嬌があり、初めて訪れた人でも緊張せずに用件を伝えることができた。","exampleZh":"接待处的女性带着自然的亲切感，即使是第一次来的人也能不紧张地说明来意。","note":"例：\n受付の女性には自然な愛嬌があり、初めて訪れた人でも緊張せずに用件を伝えることができた。\n译：接待处的女性带着自然的亲切感，即使是第一次来的人也能不紧张地说明来意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0004","seq":4,"level":"N1","type":"主词条","word":"愛くるしい","kana":"あいくるしい","pos":"[イ形]","accent":"⑤","meaning":"非常可爱的","example":"子どもが見せた愛くるしい表情に、緊張していた会場の空気が一気に和らいだ。","exampleZh":"孩子露出的可爱表情，让原本紧张的会场气氛一下子缓和了下来。","note":"例：\n子どもが見せた愛くるしい表情に、緊張していた会場の空気が一気に和らいだ。\n译：孩子露出的可爱表情，让原本紧张的会场气氛一下子缓和了下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0005","seq":5,"level":"N1","type":"主词条","word":"愛顧","kana":"あいこ","pos":"[名·他動3]","accent":"①","meaning":"关照，惠顾","example":"地元の人々がこの店を長年愛顧してきたのは、店主が小さな要望にも誠実に応えてきたからだ。","exampleZh":"当地人之所以多年惠顾这家店，是因为店主总能诚恳回应哪怕很小的需求。","note":"例：\n地元の人々がこの店を長年愛顧してきたのは、店主が小さな要望にも誠実に応えてきたからだ。\n译：当地人之所以多年惠顾这家店，是因为店主总能诚恳回应哪怕很小的需求。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0006","seq":6,"level":"N1","type":"主词条","word":"相性","kana":"あいしょう","pos":"[名]","accent":"⓪","meaning":"性格相合","example":"能力が高い二人でも相性が合わなければ、共同作業では細かな確認に余計な時間がかかってしまう。","exampleZh":"即使两人能力都很强，若彼此合不来，在共同作业中也会因细节确认而耗费额外时间。","note":"例：\n能力が高い二人でも相性が合わなければ、共同作業では細かな確認に余計な時間がかかってしまう。\n译：即使两人能力都很强，若彼此合不来，在共同作业中也会因细节确认而耗费额外时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0007","seq":7,"level":"N1","type":"主词条","word":"相席","kana":"あいせき","pos":"[名·自動3]","accent":"⓪","meaning":"（在餐厅）拼桌","example":"混雑した食堂で相席を頼まれた彼は、相手が食事に集中できるよう静かに席を分け合った。","exampleZh":"在拥挤的食堂被请求拼桌时，他安静地与对方共用座位，好让对方能专心用餐。","note":"例：\n混雑した食堂で相席を頼まれた彼は、相手が食事に集中できるよう静かに席を分け合った。\n译：在拥挤的食堂被请求拼桌时，他安静地与对方共用座位，好让对方能专心用餐。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0008","seq":8,"level":"N1","type":"主词条","word":"愛想","kana":"あいそう","pos":"[名]","accent":"③","meaning":"亲切，和蔼","example":"苦情を受けたときこそ愛想よく対応することで、相手の怒りを少しずつ和らげることができる。","exampleZh":"越是在接到投诉的时候，越要以和善态度应对，这样才能一点点缓和对方的怒气。","note":"例：\n苦情を受けたときこそ愛想よく対応することで、相手の怒りを少しずつ和らげることができる。\n译：越是在接到投诉的时候，越要以和善态度应对，这样才能一点点缓和对方的怒气。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0009","seq":9,"level":"N1","type":"主词条","word":"間柄","kana":"あいだがら","pos":"[名]","accent":"⓪","meaning":"关系","example":"親しい間柄であっても、仕事の約束は曖昧にせず、日時と役割をはっきり確認しておくべきだ。","exampleZh":"即便关系亲近，工作上的约定也不应含糊，而应明确确认日期、时间和各自职责。","note":"例：\n親しい間柄であっても、仕事の約束は曖昧にせず、日時と役割をはっきり確認しておくべきだ。\n译：即便关系亲近，工作上的约定也不应含糊，而应明确确认日期、时间和各自职责。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0010","seq":10,"level":"N1","type":"主词条","word":"相次ぐ","kana":"あいつぐ","pos":"[自動1]","accent":"①","meaning":"相继发生，接连不断","example":"設備の不具合が相次ぐなか、責任者は原因を一つに決めつけず、点検記録を最初から見直した。","exampleZh":"在设备故障接连发生的情况下，负责人没有武断地把原因归结为一个，而是从头核查了点检记录。","note":"例：\n設備の不具合が相次ぐなか、責任者は原因を一つに決めつけず、点検記録を最初から見直した。\n译：在设备故障接连发生的情况下，负责人没有武断地把原因归结为一个，而是从头核查了点检记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0011","seq":11,"level":"N1","type":"主词条","word":"相槌","kana":"あいづち","pos":"[名]","accent":"⓪③","meaning":"随声附和","example":"彼女は相槌を打ちながら相手の話を最後まで聞き、急いで助言せず気持ちを受け止めた。","exampleZh":"她一边适时附和，一边把对方的话听到最后，没有急着给建议，而是先接住了对方的情绪。","note":"例：\n彼女は相槌を打ちながら相手の話を最後まで聞き、急いで助言せず気持ちを受け止めた。\n译：她一边适时附和，一边把对方的话听到最后，没有急着给建议，而是先接住了对方的情绪。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0012","seq":12,"level":"N1","type":"主词条","word":"相手取る","kana":"あいてどる","pos":"[他動1]","accent":"④","meaning":"以……为对手发生争执","example":"住民たちは工事の周知が不十分だったとして、施工会社を相手取る訴訟の準備を進めた。","exampleZh":"居民认为工程告知不充分，因而开始准备以施工公司为对象提起诉讼。","note":"例：\n住民たちは工事の周知が不十分だったとして、施工会社を相手取る訴訟の準備を進めた。\n译：居民认为工程告知不充分，因而开始准备以施工公司为对象提起诉讼。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0013","seq":13,"level":"N1","type":"主词条","word":"アイドル","kana":"あいどる (idol)","pos":"[名]","accent":"①","meaning":"偶像","example":"人気アイドルの発言は若者の行動に影響を与えるため、事務所は情報発信の内容を慎重に確認した。","exampleZh":"人气偶像的发言会影响年轻人的行动，因此事务所慎重确认了对外发布的内容。","note":"例：\n人気アイドルの発言は若者の行動に影響を与えるため、事務所は情報発信の内容を慎重に確認した。\n译：人气偶像的发言会影响年轻人的行动，因此事务所慎重确认了对外发布的内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0014","seq":14,"level":"N1","type":"主词条","word":"合間","kana":"あいま","pos":"[名]","accent":"⓪","meaning":"空闲时间，余暇","example":"締め切りに追われる一日だったが、仕事の合間に短い散歩をしたことで集中力が少し戻った。","exampleZh":"那是被截止日期追赶的一天，但在工作的间隙短暂散步后，他的注意力稍微恢复了一些。","note":"例：\n締め切りに追われる一日だったが、仕事の合間に短い散歩をしたことで集中力が少し戻った。\n译：那是被截止日期追赶的一天，但在工作的间隙短暂散步后，他的注意力稍微恢复了一些。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0015","seq":15,"level":"N1","type":"主词条","word":"あえて","kana":"あえて","pos":"[副]","accent":"①","meaning":"敢于，硬要；（后接否定）并不（不）","example":"批判を受ける可能性を承知のうえで、彼はあえて厳しい意見を述べ、議論の先送りを避けた。","exampleZh":"明知可能受到批评，他仍敢于提出严厉意见，避免讨论被继续拖延。","note":"例：\n批判を受ける可能性を承知のうえで、彼はあえて厳しい意見を述べ、議論の先送りを避けた。\n译：明知可能受到批评，他仍敢于提出严厉意见，避免讨论被继续拖延。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0016","seq":16,"level":"N1","type":"主词条","word":"仰ぐ","kana":"あおぐ","pos":"[自他動1]","accent":"②","meaning":"尊敬；请教，请示","example":"判断に迷った担当者は、独断で進めるのではなく、専門家の意見を仰いで方針を見直した。","exampleZh":"负责人员在难以判断时，没有擅自推进，而是请教专家意见后重新审视方针。","note":"例：\n判断に迷った担当者は、独断で進めるのではなく、専門家の意見を仰いで方針を見直した。\n译：负责人员在难以判断时，没有擅自推进，而是请教专家意见后重新审视方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0017","seq":17,"level":"N1","type":"主词条","word":"青写真","kana":"あおじゃしん","pos":"[名]","accent":"③","meaning":"蓝图；初步计划","example":"新事業の青写真を描くだけでは不十分で、実行に必要な人材と資金を具体的に確保しなければならない。","exampleZh":"仅仅描绘新事业的蓝图还不够，还必须具体确保执行所需的人才和资金。","note":"例：\n新事業の青写真を描くだけでは不十分で、実行に必要な人材と資金を具体的に確保しなければならない。\n译：仅仅描绘新事业的蓝图还不够，还必须具体确保执行所需的人才和资金。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0018","seq":18,"level":"N1","type":"主词条","word":"青二才","kana":"あおにさい","pos":"[名]","accent":"③","meaning":"小毛孩儿","example":"経験の浅い青二才だと笑われても、彼は現場で学んだ事実をもとに堂々と改善案を示した。","exampleZh":"即使被笑作经验不足的小毛孩，他仍依据现场学到的事实，堂堂正正地提出了改善方案。","note":"例：\n経験の浅い青二才だと笑われても、彼は現場で学んだ事実をもとに堂々と改善案を示した。\n译：即使被笑作经验不足的小毛孩，他仍依据现场学到的事实，堂堂正正地提出了改善方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0019","seq":19,"level":"N1","type":"主词条","word":"仰向け","kana":"あおむけ","pos":"[名]","accent":"⓪","meaning":"仰面朝天","example":"救助隊は倒れている人を仰向けにする前に、呼吸と周囲の安全を慎重に確認した。","exampleZh":"救援队在把倒下的人翻成仰卧姿势前，谨慎确认了呼吸状况和周围安全。","note":"例：\n救助隊は倒れている人を仰向けにする前に、呼吸と周囲の安全を慎重に確認した。\n译：救援队在把倒下的人翻成仰卧姿势前，谨慎确认了呼吸状况和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0020","seq":20,"level":"N1","type":"主词条","word":"垢","kana":"あか","pos":"[名]","accent":"②","meaning":"水垢，污垢","example":"風呂場の隅にたまった垢を放置すると落ちにくくなるため、彼は週末ごとに換気しながら掃除している。","exampleZh":"浴室角落积下的污垢若放任不管会越来越难清除，所以他每个周末都会一边通风一边打扫。","note":"例：\n風呂場の隅にたまった垢を放置すると落ちにくくなるため、彼は週末ごとに換気しながら掃除している。\n译：浴室角落积下的污垢若放任不管会越来越难清除，所以他每个周末都会一边通风一边打扫。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0021","seq":21,"level":"N1","type":"主词条","word":"証","kana":"あかし","pos":"[名]","accent":"⓪","meaning":"证明","example":"深夜まで積み重ねた練習の証として、彼のノートには細かな修正点がびっしり書き込まれていた。","exampleZh":"作为深夜反复练习的证明，他的笔记本上密密麻麻写满了细小的修改点。","note":"例：\n深夜まで積み重ねた練習の証として、彼のノートには細かな修正点がびっしり書き込まれていた。\n译：作为深夜反复练习的证明，他的笔记本上密密麻麻写满了细小的修改点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0022","seq":22,"level":"N1","type":"主词条","word":"明かす","kana":"あかす","pos":"[他動1]","accent":"⓪","meaning":"揭露；过夜（通宵）","example":"彼は長く隠していた事実を明かす前に、家族が受ける衝撃と伝える順番を慎重に考えた。","exampleZh":"在揭露长期隐瞒的事实之前，他慎重考虑了家人可能受到的冲击以及告知的顺序。","note":"例：\n彼は長く隠していた事実を明かす前に、家族が受ける衝撃と伝える順番を慎重に考えた。\n译：在揭露长期隐瞒的事实之前，他慎重考虑了家人可能受到的冲击以及告知的顺序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0023","seq":23,"level":"N1","type":"主词条","word":"アカデミック","kana":"あかでみっく (academic)","pos":"[ナ形]","accent":"④","meaning":"学术的；墨守成规的","example":"アカデミックな文章でも、具体例と図表を添えることで、専門外の読者にも内容が伝わりやすくなる。","exampleZh":"即便是学术性文章，只要配上具体例子和图表，也能让非专业读者更容易理解内容。","note":"例：\nアカデミックな文章でも、具体例と図表を添えることで、専門外の読者にも内容が伝わりやすくなる。\n译：即便是学术性文章，只要配上具体例子和图表，也能让非专业读者更容易理解内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0024","seq":24,"level":"N1","type":"主词条","word":"赤らむ","kana":"あからむ","pos":"[自動1]","accent":"③⓪","meaning":"发红；脸红","example":"急に名前を呼ばれて頬が赤らむ彼女を見て、周囲はからかわず温かく拍手を送った。","exampleZh":"看到她突然被叫到名字后脸颊发红，周围的人没有取笑，而是温和地鼓掌鼓励。","note":"例：\n急に名前を呼ばれて頬が赤らむ彼女を見て、周囲はからかわず温かく拍手を送った。\n译：看到她突然被叫到名字后脸颊发红，周围的人没有取笑，而是温和地鼓掌鼓励。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0025","seq":25,"level":"N1","type":"主词条","word":"上がり","kana":"あがり","pos":"[名]","accent":"⓪","meaning":"告一段落；收益；出身","example":"雨の日でも店の上がりが落ちなかったのは、常連客が電話で予約して商品を取りに来てくれたからだ。","exampleZh":"即使在雨天店里的收入也没有下降，是因为熟客会打电话预约后再来取货。","note":"例：\n雨の日でも店の上がりが落ちなかったのは、常連客が電話で予約して商品を取りに来てくれたからだ。\n译：即使在雨天店里的收入也没有下降，是因为熟客会打电话预约后再来取货。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0026","seq":26,"level":"N1","type":"主词条","word":"空き巣","kana":"あきす","pos":"[名]","accent":"⓪","meaning":"（没有人的）空宅，空房","example":"旅行中に空き巣に入られないよう、彼は新聞を止め、近所の人に郵便受けの確認を頼んだ。","exampleZh":"为了避免旅行期间家中遭遇空巢盗窃，他暂停了报纸投递，并请邻居帮忙查看信箱。","note":"例：\n旅行中に空き巣に入られないよう、彼は新聞を止め、近所の人に郵便受けの確認を頼んだ。\n译：为了避免旅行期间家中遭遇空巢盗窃，他暂停了报纸投递，并请邻居帮忙查看信箱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0027","seq":27,"level":"N1","type":"主词条","word":"商い","kana":"あきない","pos":"[名]","accent":"②","meaning":"买卖，生意","example":"祖父は小さな商いを続けながら、客との何気ない会話を何より大切にしてきた。","exampleZh":"祖父一边维持着小本生意，一边始终把与客人之间随意的交谈看得比什么都重要。","note":"例：\n祖父は小さな商いを続けながら、客との何気ない会話を何より大切にしてきた。\n译：祖父一边维持着小本生意，一边始终把与客人之间随意的交谈看得比什么都重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0028","seq":28,"level":"N1","type":"主词条","word":"秋晴れ","kana":"あきばれ","pos":"[名]","accent":"⓪","meaning":"秋天的晴天","example":"雲一つない秋晴れの朝、町内会の人々は早めに集まり、延期されていた運動会の準備を始めた。","exampleZh":"在万里无云的秋日晴晨，町内会的人们早早集合，开始准备延期举行的运动会。","note":"例：\n雲一つない秋晴れの朝、町内会の人々は早めに集まり、延期されていた運動会の準備を始めた。\n译：在万里无云的秋日晴晨，町内会的人们早早集合，开始准备延期举行的运动会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0029","seq":29,"level":"N1","type":"主词条","word":"諦め","kana":"あきらめ","pos":"[名]","accent":"⓪④","meaning":"断念，达观","example":"何度も失敗した後でも、彼の表情には諦めではなく、別の方法を探そうとする粘りが残っていた。","exampleZh":"多次失败之后，他的表情中留下的不是放弃，而是继续寻找其他方法的韧劲。","note":"例：\n何度も失敗した後でも、彼の表情には諦めではなく、別の方法を探そうとする粘りが残っていた。\n译：多次失败之后，他的表情中留下的不是放弃，而是继续寻找其他方法的韧劲。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0030","seq":30,"level":"N1","type":"主词条","word":"悪〜","kana":"あく〜","pos":"[接頭]","accent":"","meaning":"恶性……，坏……","example":"悪質な業者に個人情報を渡してしまわないよう、自治体は相談窓口と確認手順を分かりやすく周知した。","exampleZh":"为了不把个人信息交给恶劣商家，地方政府用易懂方式宣传了咨询窗口和确认步骤。","note":"例：\n悪質な業者に個人情報を渡してしまわないよう、自治体は相談窓口と確認手順を分かりやすく周知した。\n译：为了不把个人信息交给恶劣商家，地方政府用易懂方式宣传了咨询窗口和确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0031","seq":31,"level":"N1","type":"主词条","word":"悪質","kana":"あくしつ","pos":"[名·ナ形]","accent":"⓪","meaning":"性质恶劣","example":"悪質な嫌がらせを放置すれば被害者だけでなく職場全体の信頼も傷つくため、管理者は早急に対応した。","exampleZh":"如果放任恶劣骚扰，不仅受害者会受伤，整个职场的信任也会受损，因此管理者迅速采取了应对措施。","note":"例：\n悪質な嫌がらせを放置すれば被害者だけでなく職場全体の信頼も傷つくため、管理者は早急に対応した。\n译：如果放任恶劣骚扰，不仅受害者会受伤，整个职场的信任也会受损，因此管理者迅速采取了应对措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0032","seq":32,"level":"N1","type":"主词条","word":"アクセス","kana":"あくせす (access)","pos":"[名·自動3]","accent":"①","meaning":"网站登录；交通","example":"山間部の集落では病院へのアクセスが悪く、自治体は予約制の乗合タクシーを導入した。","exampleZh":"山区村落去医院很不方便，地方政府因此引入了预约制的拼车出租车。","note":"例：\n山間部の集落では病院へのアクセスが悪く、自治体は予約制の乗合タクシーを導入した。\n译：山区村落去医院很不方便，地方政府因此引入了预约制的拼车出租车。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0033","seq":33,"level":"N1","type":"主词条","word":"アクセル","kana":"あくせる","pos":"[名]","accent":"①","meaning":"加速器，油门","example":"雨の日に急にアクセルを踏み込むと車体が滑りやすくなるため、教官は発進時の力加減を丁寧に指導した。","exampleZh":"雨天突然踩下油门会使车身容易打滑，因此教练细致指导了起步时的力度控制。","note":"例：\n雨の日に急にアクセルを踏み込むと車体が滑りやすくなるため、教官は発進時の力加減を丁寧に指導した。\n译：雨天突然踩下油门会使车身容易打滑，因此教练细致指导了起步时的力度控制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0034","seq":34,"level":"N1","type":"主词条","word":"あくどい","kana":"あくどい","pos":"[イ形]","accent":"③","meaning":"（颜色）过艳；（味道）过浓；（手段）恶劣","example":"あくどいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。","exampleZh":"即便用恶劣手段获得利益，只要失去对方的信任，从长远看就会造成巨大损失。","note":"例：\nあくどいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。\n译：即便用恶劣手段获得利益，只要失去对方的信任，从长远看就会造成巨大损失。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0035","seq":35,"level":"N1","type":"主词条","word":"悪徳","kana":"あくとく","pos":"[名]","accent":"⓪","meaning":"缺德，不道德","example":"悪徳商法の被害を防ぐには、契約を急がせる相手にその場で返事をしないことが大切だ。","exampleZh":"要防止恶德商法受害，重要的是不要当场答复那些催促签约的人。","note":"例：\n悪徳商法の被害を防ぐには、契約を急がせる相手にその場で返事をしないことが大切だ。\n译：要防止恶德商法受害，重要的是不要当场答复那些催促签约的人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0036","seq":36,"level":"N1","type":"主词条","word":"悪人","kana":"あくにん","pos":"[名]","accent":"⓪","meaning":"坏人，恶人","example":"物語に登場する悪人にも過去や事情が描かれているため、読者は単純に憎むだけではいられない。","exampleZh":"故事中的恶人也被描写了过去和处境，因此读者无法只是单纯地憎恨他。","note":"例：\n物語に登場する悪人にも過去や事情が描かれているため、読者は単純に憎むだけではいられない。\n译：故事中的恶人也被描写了过去和处境，因此读者无法只是单纯地憎恨他。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0037","seq":37,"level":"N1","type":"主词条","word":"明け暮れる","kana":"あけくれる","pos":"[自動2]","accent":"④","meaning":"日子一天天流逝；埋头于","example":"彼は試験前の数か月を研究と資料整理に明け暮れ、友人との誘いもほとんど断っていた。","exampleZh":"考试前的几个月里，他埋头于研究和整理资料，几乎拒绝了朋友的所有邀请。","note":"例：\n彼は試験前の数か月を研究と資料整理に明け暮れ、友人との誘いもほとんど断っていた。\n译：考试前的几个月里，他埋头于研究和整理资料，几乎拒绝了朋友的所有邀请。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0038","seq":38,"level":"N1","type":"主词条","word":"憧れる","kana":"あこがれる","pos":"[自動2]","accent":"⓪","meaning":"憧憬，向往","example":"将来に憧れるばかりで現実の準備を怠らないよう、彼は小さな目標から毎日積み重ねている。","exampleZh":"他并没有只顾憧憬未来而怠于现实准备，而是每天从小目标开始一点点积累。","note":"例：\n将来に憧れるばかりで現実の準備を怠らないよう、彼は小さな目標から毎日積み重ねている。\n译：他并没有只顾憧憬未来而怠于现实准备，而是每天从小目标开始一点点积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0039","seq":39,"level":"N1","type":"主词条","word":"麻","kana":"あさ","pos":"[名]","accent":"②","meaning":"亚麻，麻","example":"麻で織られた上着は風をよく通すため、蒸し暑い季節でも比較的涼しく着られる。","exampleZh":"用麻织成的外套透风性很好，因此即使在闷热季节也相对凉爽。","note":"例：\n麻で織られた上着は風をよく通すため、蒸し暑い季節でも比較的涼しく着られる。\n译：用麻织成的外套透风性很好，因此即使在闷热季节也相对凉爽。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0040","seq":40,"level":"N1","type":"主词条","word":"朝市","kana":"あさいち","pos":"[名]","accent":"②③","meaning":"早市","example":"旅先の朝市では、観光客向けの商品だけでなく、地元の人が普段買う野菜や魚も並んでいた。","exampleZh":"旅途中的早市上，不仅摆着面向游客的商品，也有当地人平日购买的蔬菜和鱼。","note":"例：\n旅先の朝市では、観光客向けの商品だけでなく、地元の人が普段買う野菜や魚も並んでいた。\n译：旅途中的早市上，不仅摆着面向游客的商品，也有当地人平日购买的蔬菜和鱼。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0041","seq":41,"level":"N1","type":"主词条","word":"朝方","kana":"あさがた","pos":"[名]","accent":"⓪②","meaning":"清晨","example":"朝方まで作業を続けた彼は、眠気で判断が鈍らないよう、重要な確認だけ翌日に回した。","exampleZh":"他一直工作到清晨，为了不因困倦而判断迟钝，只把最重要的确认事项推到第二天处理。","note":"例：\n朝方まで作業を続けた彼は、眠気で判断が鈍らないよう、重要な確認だけ翌日に回した。\n译：他一直工作到清晨，为了不因困倦而判断迟钝，只把最重要的确认事项推到第二天处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0042","seq":42,"level":"N1","type":"主词条","word":"浅はか","kana":"あさはか","pos":"[ナ形]","accent":"②","meaning":"肤浅，浅薄","example":"浅はかな判断で相手を責めれば、後になって事実関係を知ったときに取り返しがつかない。","exampleZh":"若因肤浅判断而责备对方，等后来了解事实关系时，可能已经无法挽回。","note":"例：\n浅はかな判断で相手を責めれば、後になって事実関係を知ったときに取り返しがつかない。\n译：若因肤浅判断而责备对方，等后来了解事实关系时，可能已经无法挽回。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0043","seq":43,"level":"N1","type":"主词条","word":"浅ましい","kana":"あさましい","pos":"[イ形]","accent":"④","meaning":"卑鄙的；贪婪的；凄惨的","example":"困っている人の弱みにつけ込んで利益を得ようとする浅ましい考えに、彼は強い嫌悪感を覚えた。","exampleZh":"对那种趁人之危牟利的卑劣想法，他感到强烈的厌恶。","note":"例：\n困っている人の弱みにつけ込んで利益を得ようとする浅ましい考えに、彼は強い嫌悪感を覚えた。\n译：对那种趁人之危牟利的卑劣想法，他感到强烈的厌恶。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0044","seq":44,"level":"N1","type":"主词条","word":"欺く","kana":"あざむく","pos":"[他動1]","accent":"③","meaning":"欺骗；胜过","example":"相手を欺くような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用欺骗对方的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を欺くような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用欺骗对方的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0045","seq":45,"level":"N1","type":"主词条","word":"朝飯前","kana":"あさめしまえ","pos":"[名·ナ形]","accent":"⑤","meaning":"极其容易的","example":"その修理は熟練の技師にとって朝飯前だったが、彼は新人にも手順が分かるよう一つずつ実演した。","exampleZh":"那项修理对熟练技师来说极其容易，但他仍一步步示范，好让新人也能理解流程。","note":"例：\nその修理は熟練の技師にとって朝飯前だったが、彼は新人にも手順が分かるよう一つずつ実演した。\n译：那项修理对熟练技师来说极其容易，但他仍一步步示范，好让新人也能理解流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0046","seq":46,"level":"N1","type":"主词条","word":"鮮やか","kana":"あざやか","pos":"[ナ形]","accent":"②","meaning":"鲜艳；熟练，巧妙","example":"料理人の包丁さばきは鮮やかで、硬い魚の骨まで無駄なく切り分けていった。","exampleZh":"厨师的刀工十分利落，连坚硬的鱼骨也被毫不浪费地切分开来。","note":"例：\n料理人の包丁さばきは鮮やかで、硬い魚の骨まで無駄なく切り分けていった。\n译：厨师的刀工十分利落，连坚硬的鱼骨也被毫不浪费地切分开来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0047","seq":47,"level":"N1","type":"主词条","word":"あざ笑う","kana":"あざわらう","pos":"[他動1]","accent":"④","meaning":"嘲笑","example":"相手をあざ笑うような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用嘲笑对方的方式即使能一时占便宜，从长远看也会失去信用。","note":"例：\n相手をあざ笑うような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用嘲笑对方的方式即使能一时占便宜，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0048","seq":48,"level":"N1","type":"主词条","word":"足跡","kana":"あしあと","pos":"[名]","accent":"③","meaning":"足迹，脚印；踪迹","example":"雪の上に残った足跡をたどると、迷子になった犬が公園の奥へ向かったことが分かった。","exampleZh":"沿着雪地上留下的足迹追踪，才知道走失的狗朝公园深处去了。","note":"例：\n雪の上に残った足跡をたどると、迷子になった犬が公園の奥へ向かったことが分かった。\n译：沿着雪地上留下的足迹追踪，才知道走失的狗朝公园深处去了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0049","seq":49,"level":"N1","type":"主词条","word":"足がかり","kana":"あしがかり","pos":"[名]","accent":"③","meaning":"立脚点，线索","example":"海外進出の足がかりを得るため、会社はまず小規模な展示会で現地の反応を確かめた。","exampleZh":"为了获得进军海外的立足点，公司首先在小规模展会上确认了当地反应。","note":"例：\n海外進出の足がかりを得るため、会社はまず小規模な展示会で現地の反応を確かめた。\n译：为了获得进军海外的立足点，公司首先在小规模展会上确认了当地反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0050","seq":50,"level":"N1","type":"主词条","word":"足固め","kana":"あしがため","pos":"[名]","accent":"③","meaning":"做好准备，打好基础","example":"新規事業を成功させるには、資金調達と人材確保という足固めを怠ってはならない。","exampleZh":"要让新业务取得成功，就不能忽视资金筹措和人才配备这两项基础准备。","note":"例：\n新規事業を成功させるには、資金調達と人材確保という足固めを怠ってはならない。\n译：要让新业务取得成功，就不能忽视资金筹措和人才配备这两项基础准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0051","seq":51,"level":"N1","type":"主词条","word":"悪しからず","kana":"あしからず","pos":"[副]","accent":"③","meaning":"请不要见怪，请原谅","example":"今回の変更でご不便をおかけしますが、悪しからずご理解くださいますようお願い申し上げます。","exampleZh":"这次变更会给各位带来不便，还请见谅并予以理解。","note":"例：\n今回の変更でご不便をおかけしますが、悪しからずご理解くださいますようお願い申し上げます。\n译：这次变更会给各位带来不便，还请见谅并予以理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0052","seq":52,"level":"N1","type":"主词条","word":"足取り","kana":"あしどり","pos":"[名]","accent":"⓪④","meaning":"脚步，步伐；行踪","example":"防犯カメラの映像をつなぎ合わせることで、事件当日の容疑者の足取りが少しずつ明らかになった。","exampleZh":"通过拼接防盗摄像头的影像，案发当天嫌疑人的行踪逐渐清晰起来。","note":"例：\n防犯カメラの映像をつなぎ合わせることで、事件当日の容疑者の足取りが少しずつ明らかになった。\n译：通过拼接防盗摄像头的影像，案发当天嫌疑人的行踪逐渐清晰起来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0053","seq":53,"level":"N1","type":"主词条","word":"足場","kana":"あしば","pos":"[名]","accent":"③","meaning":"立足点，基础；交通","example":"工事現場の足場が不安定なままでは危険なため、作業員は朝の点検を欠かさなかった。","exampleZh":"工地脚手架若仍不稳定就很危险，因此作业人员从不缺少早晨的检查。","note":"例：\n工事現場の足場が不安定なままでは危険なため、作業員は朝の点検を欠かさなかった。\n译：工地脚手架若仍不稳定就很危险，因此作业人员从不缺少早晨的检查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0054","seq":54,"level":"N1","type":"主词条","word":"足踏み","kana":"あしぶみ","pos":"[名·自動3]","accent":"③⓪","meaning":"原地踏步，停滞不前","example":"交渉は条件面で足踏みしていたが、双方が譲れない点を整理したことで再び前に進み始めた。","exampleZh":"谈判在条件方面一度停滞不前，但双方整理出不能让步的要点后，又开始向前推进。","note":"例：\n交渉は条件面で足踏みしていたが、双方が譲れない点を整理したことで再び前に進み始めた。\n译：谈判在条件方面一度停滞不前，但双方整理出不能让步的要点后，又开始向前推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0055","seq":55,"level":"N1","type":"主词条","word":"味わい","kana":"あじわい","pos":"[名]","accent":"③⓪","meaning":"味道；趣味","example":"この古い町並みには、便利さだけでは測れない独特の味わいが残っている。","exampleZh":"这片古老街景中，仍保留着一种不能只用便利性衡量的独特韵味。","note":"例：\nこの古い町並みには、便利さだけでは測れない独特の味わいが残っている。\n译：这片古老街景中，仍保留着一种不能只用便利性衡量的独特韵味。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0056","seq":56,"level":"N1","type":"主词条","word":"与る","kana":"あずかる","pos":"[自動1]","accent":"③","meaning":"参与；承蒙，受到","example":"この計画の成功に与った多くの人々へ、責任者は式典の場で一人ずつ感謝を伝えた。","exampleZh":"负责人在典礼上逐一向参与这项计划成功的许多人表达了感谢。","note":"例：\nこの計画の成功に与った多くの人々へ、責任者は式典の場で一人ずつ感謝を伝えた。\n译：负责人在典礼上逐一向参与这项计划成功的许多人表达了感谢。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0057","seq":57,"level":"N1","type":"主词条","word":"褪せる","kana":"あせる","pos":"[自動2]","accent":"②","meaning":"褪色；减弱，衰退","example":"何年も窓辺に飾っていた写真は色が褪せても、家族にとって大切な思い出であることに変わりはない。","exampleZh":"窗边摆放多年的照片即使褪了色，对家人而言仍然是珍贵回忆这一点没有改变。","note":"例：\n何年も窓辺に飾っていた写真は色が褪せても、家族にとって大切な思い出であることに変わりはない。\n译：窗边摆放多年的照片即使褪了色，对家人而言仍然是珍贵回忆这一点没有改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0058","seq":58,"level":"N1","type":"主词条","word":"焦る","kana":"あせる","pos":"[自他動1]","accent":"②","meaning":"着急","example":"結果を焦るあまり基礎をおろそかにすると、かえって遠回りになることがある。","exampleZh":"若过于急着追求结果而忽视基础，反而可能走更远的弯路。","note":"例：\n結果を焦るあまり基礎をおろそかにすると、かえって遠回りになることがある。\n译：若过于急着追求结果而忽视基础，反而可能走更远的弯路。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0059","seq":59,"level":"N1","type":"主词条","word":"仇","kana":"あだ","pos":"[名]","accent":"②","meaning":"仇人；仇恨","example":"昔の仇を討つことだけにこだわれば、今そばにいる人まで不幸にしてしまう。","exampleZh":"如果只执着于报旧仇，连如今身边的人也会被卷入不幸。","note":"例：\n昔の仇を討つことだけにこだわれば、今そばにいる人まで不幸にしてしまう。\n译：如果只执着于报旧仇，连如今身边的人也会被卷入不幸。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0060","seq":60,"level":"N1","type":"主词条","word":"値","kana":"あたい","pos":"[名]","accent":"⓪","meaning":"价格，价钱；价值","example":"担当者は値を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断价格，而是同时比较了与客户之间的信任关系和未来风险。","note":"例：\n担当者は値を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断价格，而是同时比较了与客户之间的信任关系和未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0061","seq":61,"level":"N1","type":"主词条","word":"値する","kana":"あたいする","pos":"[自動3]","accent":"⓪","meaning":"值得","example":"彼の行動は厳しい批判に値するが、同じ失敗を防ぐ仕組みづくりも同時に考えるべきだ。","exampleZh":"他的行为值得严厉批评，但也应同时思考防止同类失败再次发生的机制。","note":"例：\n彼の行動は厳しい批判に値するが、同じ失敗を防ぐ仕組みづくりも同時に考えるべきだ。\n译：他的行为值得严厉批评，但也应同时思考防止同类失败再次发生的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0062","seq":62,"level":"N1","type":"主词条","word":"あたかも","kana":"あたかも","pos":"[副]","accent":"①","meaning":"宛如；正是","example":"彼はあたかも何も知らないかのように振る舞ったが、実際には議事録を細かく読み込んでいた。","exampleZh":"他表现得仿佛什么都不知道，实际上却已经仔细读过会议记录。","note":"例：\n彼はあたかも何も知らないかのように振る舞ったが、実際には議事録を細かく読み込んでいた。\n译：他表现得仿佛什么都不知道，实际上却已经仔细读过会议记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0063","seq":63,"level":"N1","type":"主词条","word":"アタック","kana":"あたっく (attack)","pos":"[名·自動3]","accent":"②","meaning":"攻击；挑战","example":"新しい市場にアタックするなら、勢いだけでなく、現地の習慣や競合の強みも調べなければならない。","exampleZh":"若要进军新的市场，就不能只凭气势，还必须调查当地习惯和竞争对手的优势。","note":"例：\n新しい市場にアタックするなら、勢いだけでなく、現地の習慣や競合の強みも調べなければならない。\n译：若要进军新的市场，就不能只凭气势，还必须调查当地习惯和竞争对手的优势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0064","seq":64,"level":"N1","type":"主词条","word":"あだな","kana":"あだな","pos":"[名]","accent":"⓪","meaning":"绰号，外号","example":"本人が嫌がるあだなを面白がって呼び続ければ、冗談のつもりでも相手を深く傷つける。","exampleZh":"如果把本人讨厌的绰号当作好玩一直叫下去，即使只是开玩笑，也会深深伤害对方。","note":"例：\n本人が嫌がるあだなを面白がって呼び続ければ、冗談のつもりでも相手を深く傷つける。\n译：如果把本人讨厌的绰号当作好玩一直叫下去，即使只是开玩笑，也会深深伤害对方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0065","seq":65,"level":"N1","type":"主词条","word":"当たり","kana":"あたり","pos":"[名]","accent":"⓪","meaning":"命中，中奖","example":"宝くじの当たりを期待して大金を使うより、彼は毎月少しずつ貯金する道を選んだ。","exampleZh":"与其期待彩票中奖而花掉大笔钱，他选择了每个月一点点储蓄。","note":"例：\n宝くじの当たりを期待して大金を使うより、彼は毎月少しずつ貯金する道を選んだ。\n译：与其期待彩票中奖而花掉大笔钱，他选择了每个月一点点储蓄。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0066","seq":66,"level":"N1","type":"主词条","word":"扱い","kana":"あつかい","pos":"[名]","accent":"⓪","meaning":"操作，处理；对待","example":"新人だからといって軽い扱いを受け続ければ、意欲のある人材ほど早く職場を離れてしまう。","exampleZh":"如果因为是新人就一直受到轻视，越有干劲的人才越可能很快离开职场。","note":"例：\n新人だからといって軽い扱いを受け続ければ、意欲のある人材ほど早く職場を離れてしまう。\n译：如果因为是新人就一直受到轻视，越有干劲的人才越可能很快离开职场。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0067","seq":67,"level":"N1","type":"主词条","word":"〜扱い","kana":"〜あつかい","pos":"[接尾]","accent":"","meaning":"当成……看待","example":"入社三年目になっても会議で新人扱いされるため、彼は自分の企画書を提出して評価を変えようとした。","exampleZh":"入职第三年仍在会议中被当成新人对待，所以他提交了自己的企划书，想改变评价。","note":"例：\n入社三年目になっても会議で新人扱いされるため、彼は自分の企画書を提出して評価を変えようとした。\n译：入职第三年仍在会议中被当成新人对待，所以他提交了自己的企划书，想改变评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0068","seq":68,"level":"N1","type":"主词条","word":"あっけない","kana":"あっけない","pos":"[イ形]","accent":"④","meaning":"不尽兴，没劲","example":"優勝候補の敗退はあっけない幕切れだったが、選手たちは相手の準備の徹底ぶりを認めた。","exampleZh":"夺冠热门的出局虽然收场得很突然，选手们仍承认了对手准备得十分彻底。","note":"例：\n優勝候補の敗退はあっけない幕切れだったが、選手たちは相手の準備の徹底ぶりを認めた。\n译：夺冠热门的出局虽然收场得很突然，选手们仍承认了对手准备得十分彻底。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0069","seq":69,"level":"N1","type":"主词条","word":"あっさり","kana":"あっさり","pos":"[副·自動3]","accent":"③","meaning":"简单；（口味）清淡；爽快，干脆","example":"彼は厳しい条件をあっさり受け入れたように見えたが、裏では家族と何度も話し合っていた。","exampleZh":"他看似爽快地接受了苛刻条件，背后却已经和家人反复商量过多次。","note":"例：\n彼は厳しい条件をあっさり受け入れたように見えたが、裏では家族と何度も話し合っていた。\n译：他看似爽快地接受了苛刻条件，背后却已经和家人反复商量过多次。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0070","seq":70,"level":"N1","type":"主词条","word":"圧勝","kana":"あっしょう","pos":"[名·自動3]","accent":"⓪","meaning":"以压倒性优势获胜","example":"予想以上の圧勝に終わったが、監督は相手の弱点よりも自分たちの準備が実ったことを強調した。","exampleZh":"比赛以超出预想的压倒性胜利告终，但教练强调的不是对手弱点，而是自己的准备终于开花结果。","note":"例：\n予想以上の圧勝に終わったが、監督は相手の弱点よりも自分たちの準備が実ったことを強調した。\n译：比赛以超出预想的压倒性胜利告终，但教练强调的不是对手弱点，而是自己的准备终于开花结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0071","seq":71,"level":"N1","type":"主词条","word":"斡旋","kana":"あっせん","pos":"[名·他動3]","accent":"⓪","meaning":"介绍，周旋","example":"市は仕事を失った若者に就職先を斡旋するだけでなく、面接練習や生活相談の場も用意した。","exampleZh":"市政府不仅为失业青年介绍就业单位，也准备了面试练习和生活咨询的场所。","note":"例：\n市は仕事を失った若者に就職先を斡旋するだけでなく、面接練習や生活相談の場も用意した。\n译：市政府不仅为失业青年介绍就业单位，也准备了面试练习和生活咨询的场所。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0072","seq":72,"level":"N1","type":"主词条","word":"圧倒","kana":"あっとう","pos":"[名·他動3]","accent":"⓪","meaning":"压过，压倒","example":"相手を力で圧倒しても、本当に納得させたことにはならないと彼は考えている。","exampleZh":"即使用力量压倒对方，也不等于真正让对方心服口服，他是这样认为的。","note":"例：\n相手を力で圧倒しても、本当に納得させたことにはならないと彼は考えている。\n译：即使用力量压倒对方，也不等于真正让对方心服口服，他是这样认为的。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0073","seq":73,"level":"N1","type":"主词条","word":"圧倒的","kana":"あっとうてき","pos":"[ナ形]","accent":"⓪","meaning":"绝对的（处于优势）","example":"圧倒的な支持を得たからこそ、指導者には反対意見にも耳を傾ける責任がある。","exampleZh":"正因为获得了压倒性支持，领导者才有责任倾听反对意见。","note":"例：\n圧倒的な支持を得たからこそ、指導者には反対意見にも耳を傾ける責任がある。\n译：正因为获得了压倒性支持，领导者才有责任倾听反对意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0074","seq":74,"level":"N1","type":"主词条","word":"アットホーム","kana":"あっとほーむ (at home)","pos":"[ナ形]","accent":"④","meaning":"（像在家里一样）自在，无拘束","example":"その小さな宿はアットホームな雰囲気で、初めて訪れた客にも地元の店を丁寧に紹介してくれた。","exampleZh":"那家小旅馆氛围像家一样自在，即使对第一次来访的客人，也会细致介绍当地店铺。","note":"例：\nその小さな宿はアットホームな雰囲気で、初めて訪れた客にも地元の店を丁寧に紹介してくれた。\n译：那家小旅馆氛围像家一样自在，即使对第一次来访的客人，也会细致介绍当地店铺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0075","seq":75,"level":"N1","type":"主词条","word":"圧迫","kana":"あっぱく","pos":"[名·他動3]","accent":"⓪","meaning":"压迫，压制","example":"相手を圧迫するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯压迫对方只会加深对立，因此她决定先确认对方主张背后的原因。","note":"例：\n相手を圧迫するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯压迫对方只会加深对立，因此她决定先确认对方主张背后的原因。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0076","seq":76,"level":"N1","type":"主词条","word":"アップ","kana":"あっぷ (up)","pos":"[名·自他動3]","accent":"①","meaning":"提高，增高","example":"動画をアップする前に、彼女は映り込んだ人の顔や個人情報が見えないかを確認した。","exampleZh":"上传视频之前，她确认了画面中是否拍到他人的脸或个人信息。","note":"例：\n動画をアップする前に、彼女は映り込んだ人の顔や個人情報が見えないかを確認した。\n译：上传视频之前，她确认了画面中是否拍到他人的脸或个人信息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0077","seq":77,"level":"N1","type":"主词条","word":"誂える","kana":"あつらえる","pos":"[他動2]","accent":"④③","meaning":"定做","example":"服を誂えるなら、見た目の好みだけでなく、長く着られる生地や動きやすさも考えたい。","exampleZh":"如果要定做衣服，不仅要考虑外观喜好，也要考虑能否长期穿着的布料和活动方便度。","note":"例：\n服を誂えるなら、見た目の好みだけでなく、長く着られる生地や動きやすさも考えたい。\n译：如果要定做衣服，不仅要考虑外观喜好，也要考虑能否长期穿着的布料和活动方便度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0078","seq":78,"level":"N1","type":"主词条","word":"当て","kana":"あて","pos":"[名]","accent":"⓪","meaning":"目标；期待，指望","example":"確かな当てもなく転職を決める前に、彼は生活費と必要な資格を冷静に計算した。","exampleZh":"在没有可靠指望的情况下决定跳槽之前，他冷静计算了生活费和所需资格。","note":"例：\n確かな当てもなく転職を決める前に、彼は生活費と必要な資格を冷静に計算した。\n译：在没有可靠指望的情况下决定跳槽之前，他冷静计算了生活费和所需资格。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0079","seq":79,"level":"N1","type":"主词条","word":"宛てる","kana":"あてる","pos":"[他動2]","accent":"⓪","meaning":"发送，寄给，投递","example":"大切な手紙を相手に宛てる前に、彼女は名前と住所を何度も確認した。","exampleZh":"在把重要信件寄给对方之前，她反复确认了姓名和地址。","note":"例：\n大切な手紙を相手に宛てる前に、彼女は名前と住所を何度も確認した。\n译：在把重要信件寄给对方之前，她反复确认了姓名和地址。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0080","seq":80,"level":"N1","type":"主词条","word":"後始末","kana":"あとしまつ","pos":"[名]","accent":"③","meaning":"善后，收拾","example":"イベントの後始末を任された彼は、会場の清掃だけでなく、忘れ物の連絡まで丁寧に行った。","exampleZh":"负责活动善后的他，不仅打扫会场，还细致联系失物招领事宜。","note":"例：\nイベントの後始末を任された彼は、会場の清掃だけでなく、忘れ物の連絡まで丁寧に行った。\n译：负责活动善后的他，不仅打扫会场，还细致联系失物招领事宜。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0081","seq":81,"level":"N1","type":"主词条","word":"跡継ぎ","kana":"あとつぎ","pos":"[名]","accent":"②","meaning":"接班人，继承人","example":"老舗旅館の跡継ぎとして育った彼は、伝統を守りながら新しい客層を開拓しようとしている。","exampleZh":"作为老字号旅馆的继承人长大的他，正试图在守护传统的同时开拓新的客群。","note":"例：\n老舗旅館の跡継ぎとして育った彼は、伝統を守りながら新しい客層を開拓しようとしている。\n译：作为老字号旅馆的继承人长大的他，正试图在守护传统的同时开拓新的客群。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0082","seq":82,"level":"N1","type":"主词条","word":"後回し","kana":"あとまわし","pos":"[名]","accent":"③","meaning":"推迟","example":"面倒な確認を後回しにした結果、締め切り直前に大きな誤りが見つかってしまった。","exampleZh":"把麻烦的确认往后拖，结果在截止日期前夕发现了重大错误。","note":"例：\n面倒な確認を後回しにした結果、締め切り直前に大きな誤りが見つかってしまった。\n译：把麻烦的确认往后拖，结果在截止日期前夕发现了重大错误。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0083","seq":83,"level":"N1","type":"主词条","word":"穴埋め","kana":"あなうめ","pos":"[名·他動3]","accent":"⓪④","meaning":"填空；填补，弥补","example":"欠員の穴埋めとして入った彼だったが、前任者のやり方をただ真似るのではなく改善案も出した。","exampleZh":"他虽是作为空缺补位进入团队的人，却没有只是模仿前任做法，还提出了改善方案。","note":"例：\n欠員の穴埋めとして入った彼だったが、前任者のやり方をただ真似るのではなく改善案も出した。\n译：他虽是作为空缺补位进入团队的人，却没有只是模仿前任做法，还提出了改善方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0084","seq":84,"level":"N1","type":"主词条","word":"あながち","kana":"あながち","pos":"[副]","accent":"⓪","meaning":"（常与否定相应）不见得，未必","example":"彼の指摘は厳しいが、あながち的外れとも言えず、改善の余地を考えさせられた。","exampleZh":"他的指摘虽然严厉，但也不能说完全不着边际，让人不得不思考改进的余地。","note":"例：\n彼の指摘は厳しいが、あながち的外れとも言えず、改善の余地を考えさせられた。\n译：他的指摘虽然严厉，但也不能说完全不着边际，让人不得不思考改进的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0085","seq":85,"level":"N1","type":"主词条","word":"暴く","kana":"あばく","pos":"[他動1]","accent":"②","meaning":"揭发，揭露","example":"事実を暴く前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在揭发事实之前，他慎重考虑了相关人员会受到的影响以及传达的时机。","note":"例：\n事実を暴く前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在揭发事实之前，他慎重考虑了相关人员会受到的影响以及传达的时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0086","seq":86,"level":"N1","type":"主词条","word":"アピール","kana":"あぴーる (appeal)","pos":"[名·自他動3]","accent":"②","meaning":"呼吁；（有）吸引力","example":"商品の便利さをアピールするなら、派手な言葉よりも実際に使う場面を具体的に示すほうが効果的だ。","exampleZh":"若要宣传商品的便利性，与其用夸张措辞，不如具体展示实际使用场景更有效。","note":"例：\n商品の便利さをアピールするなら、派手な言葉よりも実際に使う場面を具体的に示すほうが効果的だ。\n译：若要宣传商品的便利性，与其用夸张措辞，不如具体展示实际使用场景更有效。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0087","seq":87,"level":"N1","type":"主词条","word":"アフターケア","kana":"あふたーけあ (aftercare)","pos":"[名]","accent":"⑤","meaning":"病后调养；售后服务","example":"手術後のアフターケアが不十分だと、治療そのものが成功しても患者の不安は残ってしまう。","exampleZh":"如果术后护理不充分，即使治疗本身成功，患者的不安也会残留下来。","note":"例：\n手術後のアフターケアが不十分だと、治療そのものが成功しても患者の不安は残ってしまう。\n译：如果术后护理不充分，即使治疗本身成功，患者的不安也会残留下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0088","seq":88,"level":"N1","type":"主词条","word":"アフターサービス","kana":"あふたーさーびす","pos":"[名]","accent":"⑤","meaning":"售后服务","example":"家電を選ぶ際、彼は価格だけでなく、故障したときのアフターサービスの評判も確認した。","exampleZh":"选择家电时，他不仅看价格，也确认了故障时售后服务的口碑。","note":"例：\n家電を選ぶ際、彼は価格だけでなく、故障したときのアフターサービスの評判も確認した。\n译：选择家电时，他不仅看价格，也确认了故障时售后服务的口碑。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0089","seq":89,"level":"N1","type":"主词条","word":"危なげない","kana":"あぶなげない","pos":"[イ形]","accent":"⑤","meaning":"有把握的","example":"彼の発表は危なげない進行だったが、その裏には何度も練習を重ねた地道な準備があった。","exampleZh":"他的发表过程看似稳妥无虞，背后却有多次反复练习的踏实准备。","note":"例：\n彼の発表は危なげない進行だったが、その裏には何度も練習を重ねた地道な準備があった。\n译：他的发表过程看似稳妥无虞，背后却有多次反复练习的踏实准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0090","seq":90,"level":"N1","type":"主词条","word":"油絵","kana":"あぶらえ","pos":"[名]","accent":"③","meaning":"油画","example":"新しい油絵を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的油画元素，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しい油絵を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的油画元素，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0091","seq":91,"level":"N1","type":"主词条","word":"アプローチ","kana":"あぷろーち (approach)","pos":"[名·自動3]","accent":"③","meaning":"接近；探讨，研究","example":"問題へのアプローチを変えたことで、対立していた部署同士が同じ資料を見ながら話せるようになった。","exampleZh":"改变解决问题的切入方式后，原本对立的部门也能一边看同一份资料一边讨论了。","note":"例：\n問題へのアプローチを変えたことで、対立していた部署同士が同じ資料を見ながら話せるようになった。\n译：改变解决问题的切入方式后，原本对立的部门也能一边看同一份资料一边讨论了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0092","seq":92,"level":"N1","type":"主词条","word":"あべこべ","kana":"あべこべ","pos":"[名·ナ形]","accent":"⓪","meaning":"颠倒，相反","example":"作業の順番があべこべになると、簡単な確認までやり直しになり、全体の予定が大きく遅れる。","exampleZh":"作业顺序一旦颠倒，连简单确认都要重做，整体计划也会大幅延迟。","note":"例：\n作業の順番があべこべになると、簡単な確認までやり直しになり、全体の予定が大きく遅れる。\n译：作业顺序一旦颠倒，连简单确认都要重做，整体计划也会大幅延迟。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0093","seq":93,"level":"N1","type":"主词条","word":"アポ/アポイント/アポイントメント","kana":"アポ/アポイント/アポイントメント","pos":"[名]","accent":"②","meaning":"预约，联系","example":"取引先に急な訪問をするのではなく、彼は事前にアポを取り、相手の都合に合わせて資料を用意した。","exampleZh":"他没有突然拜访客户，而是事先预约，并按对方方便的时间准备资料。","note":"例：\n取引先に急な訪問をするのではなく、彼は事前にアポを取り、相手の都合に合わせて資料を用意した。\n译：他没有突然拜访客户，而是事先预约，并按对方方便的时间准备资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0094","seq":94,"level":"N1","type":"主词条","word":"雨足","kana":"あまあし","pos":"[名]","accent":"⓪","meaning":"雨势","example":"夕方から雨足が急に強まり、駅前の店は看板をしまって客に足元への注意を呼びかけた。","exampleZh":"傍晚起雨势突然增强，车站前的店铺收起招牌，并提醒顾客注意脚下。","note":"例：\n夕方から雨足が急に強まり、駅前の店は看板をしまって客に足元への注意を呼びかけた。\n译：傍晚起雨势突然增强，车站前的店铺收起招牌，并提醒顾客注意脚下。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0095","seq":95,"level":"N1","type":"主词条","word":"甘える","kana":"あまえる","pos":"[自動2]","accent":"⓪","meaning":"撒娇，任性；承蒙","example":"親切な相手に甘えるばかりでは信頼を失うため、彼は自分でできる準備を先に済ませた。","exampleZh":"若一味依赖好心的对方，会失去信任，所以他先完成了自己能够准备的事项。","note":"例：\n親切な相手に甘えるばかりでは信頼を失うため、彼は自分でできる準備を先に済ませた。\n译：若一味依赖好心的对方，会失去信任，所以他先完成了自己能够准备的事项。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0096","seq":96,"level":"N1","type":"主词条","word":"雨具","kana":"あまぐ","pos":"[名]","accent":"②","meaning":"雨具","example":"山では天気が急に変わるため、晴れていても雨具を荷物から外さないほうがよい。","exampleZh":"山里天气容易突然变化，因此即使晴天也最好不要把雨具从行李中拿出去。","note":"例：\n山では天気が急に変わるため、晴れていても雨具を荷物から外さないほうがよい。\n译：山里天气容易突然变化，因此即使晴天也最好不要把雨具从行李中拿出去。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0097","seq":97,"level":"N1","type":"主词条","word":"甘口","kana":"あまくち","pos":"[名·ナ形]","accent":"⓪","meaning":"甜味的；喜欢吃甜食的（人）；甜言蜜语","example":"甘口の評価ばかりでは成長できないと考え、彼女は厳しい意見も最後まで聞くことにした。","exampleZh":"她认为一味宽松的评价无法促人成长，因此决定把严厉意见也听到最后。","note":"例：\n甘口の評価ばかりでは成長できないと考え、彼女は厳しい意見も最後まで聞くことにした。\n译：她认为一味宽松的评价无法促人成长，因此决定把严厉意见也听到最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0098","seq":98,"level":"N1","type":"主词条","word":"甘んじる","kana":"あまんじる","pos":"[自動2]","accent":"④①","meaning":"甘愿，满足","example":"不利な条件に甘んじるのではなく、彼は交渉の余地を探し、少しでも状況を改善しようとした。","exampleZh":"他没有甘于不利条件，而是寻找谈判余地，试图哪怕一点也好地改善状况。","note":"例：\n不利な条件に甘んじるのではなく、彼は交渉の余地を探し、少しでも状況を改善しようとした。\n译：他没有甘于不利条件，而是寻找谈判余地，试图哪怕一点也好地改善状况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0099","seq":99,"level":"N1","type":"主词条","word":"あやかる","kana":"あやかる","pos":"[自動1]","accent":"③","meaning":"相似，效仿；跟着沾光","example":"先輩の成功にあやかるつもりで、彼は同じ神社に参拝し、努力を続ける決意を新たにした。","exampleZh":"他抱着沾前辈成功之光的想法去了同一座神社参拜，并重新下定决心继续努力。","note":"例：\n先輩の成功にあやかるつもりで、彼は同じ神社に参拝し、努力を続ける決意を新たにした。\n译：他抱着沾前辈成功之光的想法去了同一座神社参拜，并重新下定决心继续努力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0100","seq":100,"level":"N1","type":"主词条","word":"操る","kana":"あやつる","pos":"[他動1]","accent":"③","meaning":"（灵活地）操作；暗中控制","example":"彼は複数の言語を自在に操り、交渉の場で相手の微妙な本音まで引き出した。","exampleZh":"他能够自如运用多种语言，在谈判场合甚至引出了对方微妙的真实想法。","note":"例：\n彼は複数の言語を自在に操り、交渉の場で相手の微妙な本音まで引き出した。\n译：他能够自如运用多种语言，在谈判场合甚至引出了对方微妙的真实想法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0101","seq":101,"level":"N1","type":"主词条","word":"危ぶむ","kana":"あやぶむ","pos":"[他動1]","accent":"③","meaning":"感到危险，担忧","example":"計画の遅れを危ぶむだけでなく、彼は原因を分けて考え、実行できる対策を提案した。","exampleZh":"他没有只是担心计划延误，而是把原因分开思考，并提出了可执行的对策。","note":"例：\n計画の遅れを危ぶむだけでなく、彼は原因を分けて考え、実行できる対策を提案した。\n译：他没有只是担心计划延误，而是把原因分开思考，并提出了可执行的对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0102","seq":102,"level":"N1","type":"主词条","word":"あやふや","kana":"あやふや","pos":"[ナ形]","accent":"⓪","meaning":"含糊不清，模棱两可","example":"あやふやな記憶だけで証言すると誤解を招くため、彼は記録を確認してから話した。","exampleZh":"若只凭含糊记忆作证会招致误解，因此他先确认记录后才开口。","note":"例：\nあやふやな記憶だけで証言すると誤解を招くため、彼は記録を確認してから話した。\n译：若只凭含糊记忆作证会招致误解，因此他先确认记录后才开口。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0103","seq":103,"level":"N1","type":"主词条","word":"過ち","kana":"あやまち","pos":"[名]","accent":"④③⓪","meaning":"错误，过失","example":"一つの過ちを隠そうとすれば、事実を認めて修正するよりもはるかに大きな信頼を失うことになる。","exampleZh":"若想隐瞒一个错误，最终会比承认事实并修正时失去更大的信任。","note":"例：\n一つの過ちを隠そうとすれば、事実を認めて修正するよりもはるかに大きな信頼を失うことになる。\n译：若想隐瞒一个错误，最终会比承认事实并修正时失去更大的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0104","seq":104,"level":"N1","type":"主词条","word":"誤る","kana":"あやまる","pos":"[自他動1]","accent":"③","meaning":"弄错","example":"入力する数字を一桁誤るだけで請求額が変わるため、彼女は送信前に必ず二度確認している。","exampleZh":"只要输入数字错一位，账单金额就会改变，因此她发送前一定会确认两遍。","note":"例：\n入力する数字を一桁誤るだけで請求額が変わるため、彼女は送信前に必ず二度確認している。\n译：只要输入数字错一位，账单金额就会改变，因此她发送前一定会确认两遍。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0105","seq":105,"level":"N1","type":"主词条","word":"歩む","kana":"あゆむ","pos":"[自動1]","accent":"②","meaning":"走；发展，进步","example":"彼は派手な成功を急がず、失敗から学びながら自分の道を少しずつ歩んできた。","exampleZh":"他没有急于追求耀眼成功，而是一边从失败中学习，一边慢慢走出自己的道路。","note":"例：\n彼は派手な成功を急がず、失敗から学びながら自分の道を少しずつ歩んできた。\n译：他没有急于追求耀眼成功，而是一边从失败中学习，一边慢慢走出自己的道路。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0106","seq":106,"level":"N1","type":"主词条","word":"あらかじめ","kana":"あらかじめ","pos":"[副]","accent":"⓪","meaning":"预先，事先","example":"会議で慌てないよう、彼はあらかじめ資料に目を通し、疑問点を付箋に書き出しておいた。","exampleZh":"为了避免在会议上慌乱，他事先浏览了资料，并把疑问点写在便签上。","note":"例：\n会議で慌てないよう、彼はあらかじめ資料に目を通し、疑問点を付箋に書き出しておいた。\n译：为了避免在会议上慌乱，他事先浏览了资料，并把疑问点写在便签上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0107","seq":107,"level":"N1","type":"主词条","word":"あらかた","kana":"あらかた","pos":"[副]","accent":"⓪","meaning":"大致，大体上","example":"資料はあらかたそろったが、数字の根拠だけはもう一度担当部署に確認する必要がある。","exampleZh":"资料大致已经齐全，但数字依据仍有必要再向负责部门确认一次。","note":"例：\n資料はあらかたそろったが、数字の根拠だけはもう一度担当部署に確認する必要がある。\n译：资料大致已经齐全，但数字依据仍有必要再向负责部门确认一次。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0108","seq":108,"level":"N1","type":"主词条","word":"荒らす","kana":"あらす","pos":"[他動1]","accent":"⓪","meaning":"糟蹋，破坏；偷盗","example":"匿名の書き込みで掲示板を荒らす人が増え、管理者は投稿ルールと確認体制を見直した。","exampleZh":"匿名发帖扰乱公告板的人增多，管理员因此重新审视了发帖规则和确认体制。","note":"例：\n匿名の書き込みで掲示板を荒らす人が増え、管理者は投稿ルールと確認体制を見直した。\n译：匿名发帖扰乱公告板的人增多，管理员因此重新审视了发帖规则和确认体制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0109","seq":109,"level":"N1","type":"主词条","word":"粗筋","kana":"あらすじ","pos":"[名]","accent":"⓪","meaning":"概要，大纲","example":"小説の粗筋だけを読んで評価するのではなく、登場人物の変化や文章の余韻にも目を向けたい。","exampleZh":"不应只读小说梗概就作评价，也要关注人物变化和文字留下的余韵。","note":"例：\n小説の粗筋だけを読んで評価するのではなく、登場人物の変化や文章の余韻にも目を向けたい。\n译：不应只读小说梗概就作评价，也要关注人物变化和文字留下的余韵。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0110","seq":110,"level":"N1","type":"主词条","word":"改まる","kana":"あらたまる","pos":"[自動1]","accent":"④","meaning":"改变；变好；郑重，端正","example":"上司の前で急に改まった口調になった彼を見て、同僚は相談が深刻なのだと気づいた。","exampleZh":"看到他在上司面前突然换成郑重的语气，同事意识到这次商量的事情很严重。","note":"例：\n上司の前で急に改まった口調になった彼を見て、同僚は相談が深刻なのだと気づいた。\n译：看到他在上司面前突然换成郑重的语气，同事意识到这次商量的事情很严重。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0111","seq":111,"level":"N1","type":"主词条","word":"荒っぽい","kana":"あらっぽい","pos":"[イ形]","accent":"④⓪","meaning":"粗暴的，粗鲁的","example":"荒っぽい言い方をすれば正しい指摘でも反発を招くため、彼女は表現を選んで伝えた。","exampleZh":"如果说话粗鲁，即使指出的是正确问题也会招致反感，因此她斟酌了表达方式后再传达。","note":"例：\n荒っぽい言い方をすれば正しい指摘でも反発を招くため、彼女は表現を選んで伝えた。\n译：如果说话粗鲁，即使指出的是正确问题也会招致反感，因此她斟酌了表达方式后再传达。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0112","seq":112,"level":"N1","type":"主词条","word":"霰","kana":"あられ","pos":"[名]","accent":"⓪","meaning":"小冰雹，雪粒","example":"突然の霰で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的霰使交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の霰で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的霰使交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0113","seq":113,"level":"N1","type":"主词条","word":"あり方","kana":"ありかた","pos":"[名]","accent":"③④","meaning":"现有的状态，理想的状态","example":"働き方のあり方を見直すなら、制度だけでなく、現場で実際に困っている人の声を聞く必要がある。","exampleZh":"若要重新审视工作方式的理想状态，就不能只看制度，还需要倾听现场真正困扰的人。","note":"例：\n働き方のあり方を見直すなら、制度だけでなく、現場で実際に困っている人の声を聞く必要がある。\n译：若要重新审视工作方式的理想状态，就不能只看制度，还需要倾听现场真正困扰的人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0114","seq":114,"level":"N1","type":"主词条","word":"ありきたり","kana":"ありきたり","pos":"[名·ナ形]","accent":"⓪","meaning":"一般，普通","example":"ありきたりな提案に見えても、現場の負担を正確に減らせるなら十分に検討する価値がある。","exampleZh":"即使看起来只是普通提案，只要能准确减少现场负担，也值得充分讨论。","note":"例：\nありきたりな提案に見えても、現場の負担を正確に減らせるなら十分に検討する価値がある。\n译：即使看起来只是普通提案，只要能准确减少现场负担，也值得充分讨论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0115","seq":115,"level":"N1","type":"主词条","word":"有様","kana":"ありさま","pos":"[名]","accent":"②⓪","meaning":"样子，状态","example":"台風が去った後の町の有様を見て、住民たちは復旧に長い時間がかかることを覚悟した。","exampleZh":"看到台风过后城镇的样子，居民们做好了复旧需要很长时间的心理准备。","note":"例：\n台風が去った後の町の有様を見て、住民たちは復旧に長い時間がかかることを覚悟した。\n译：看到台风过后城镇的样子，居民们做好了复旧需要很长时间的心理准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0116","seq":116,"level":"N1","type":"主词条","word":"ありとあらゆる","kana":"ありとあらゆる","pos":"[連体]","accent":"①⑥","meaning":"所有的","example":"彼はありとあらゆる方法を試したが、最後には基本に戻って原因を一つずつ確認した。","exampleZh":"他尝试了所有方法，但最后还是回到基础，逐一确认原因。","note":"例：\n彼はありとあらゆる方法を試したが、最後には基本に戻って原因を一つずつ確認した。\n译：他尝试了所有方法，但最后还是回到基础，逐一确认原因。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0117","seq":117,"level":"N1","type":"主词条","word":"ありのまま","kana":"ありのまま","pos":"[名·ナ形·副]","accent":"⑤","meaning":"如实","example":"失敗をありのままに認めたことで、彼は責任を問われた一方、周囲からの信頼も少し取り戻した。","exampleZh":"因为如实承认失败，他一方面被追究责任，另一方面也稍微重新赢回了周围的信任。","note":"例：\n失敗をありのままに認めたことで、彼は責任を問われた一方、周囲からの信頼も少し取り戻した。\n译：因为如实承认失败，他一方面被追究责任，另一方面也稍微重新赢回了周围的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0118","seq":118,"level":"N1","type":"主词条","word":"ありふれた","kana":"ありふれた","pos":"[連体]","accent":"⓪③","meaning":"常见的","example":"ありふれた日常の中にも、後から思い返すと二度と戻らない大切な瞬間が隠れている。","exampleZh":"在平凡日常之中，也隐藏着事后回想才发现再也回不去的珍贵瞬间。","note":"例：\nありふれた日常の中にも、後から思い返すと二度と戻らない大切な瞬間が隠れている。\n译：在平凡日常之中，也隐藏着事后回想才发现再也回不去的珍贵瞬间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0119","seq":119,"level":"N1","type":"主词条","word":"アルコール","kana":"あるこーる (alcohol)","pos":"[名]","accent":"⓪","meaning":"酒精；酒","example":"アルコールを扱う店では、味や雰囲気だけでなく、飲み過ぎを防ぐ声かけや安全な帰宅手段も重要になる。","exampleZh":"经营酒精饮品的店铺中，不仅味道和氛围重要，防止饮酒过量的提醒和安全回家方式也很重要。","note":"例：\nアルコールを扱う店では、味や雰囲気だけでなく、飲み過ぎを防ぐ声かけや安全な帰宅手段も重要になる。\n译：经营酒精饮品的店铺中，不仅味道和氛围重要，防止饮酒过量的提醒和安全回家方式也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0120","seq":120,"level":"N1","type":"主词条","word":"アルファベット","kana":"あるふぁべっと (alphabet)","pos":"[名]","accent":"④","meaning":"希腊字母；初步，入门","example":"子どもたちはアルファベットをただ暗記するのではなく、看板や絵本の中から探して覚えていった。","exampleZh":"孩子们并不是单纯死记字母，而是在招牌和绘本中寻找它们来记住。","note":"例：\n子どもたちはアルファベットをただ暗記するのではなく、看板や絵本の中から探して覚えていった。\n译：孩子们并不是单纯死记字母，而是在招牌和绘本中寻找它们来记住。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0121","seq":121,"level":"N1","type":"主词条","word":"アレンジ","kana":"あれんじ (arrange)","pos":"[名·他動3]","accent":"②","meaning":"布置；改编；安排","example":"古い民謡を現代風にアレンジしたことで、若い観客にも歌詞の魅力が伝わりやすくなった。","exampleZh":"由于把古老民谣改编成现代风格，年轻观众也更容易感受到歌词的魅力。","note":"例：\n古い民謡を現代風にアレンジしたことで、若い観客にも歌詞の魅力が伝わりやすくなった。\n译：由于把古老民谣改编成现代风格，年轻观众也更容易感受到歌词的魅力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0122","seq":122,"level":"N1","type":"主词条","word":"合わす","kana":"あわす","pos":"[他動1]","accent":"②","meaning":"并；配合；核对","example":"参加者の予定に合わすため、主催者は開始時間を一時間遅らせることにした。","exampleZh":"为了配合参加者的日程，主办方决定把开始时间推迟一小时。","note":"例：\n参加者の予定に合わすため、主催者は開始時間を一時間遅らせることにした。\n译：为了配合参加者的日程，主办方决定把开始时间推迟一小时。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0123","seq":123,"level":"N1","type":"主词条","word":"合わせて","kana":"あわせて","pos":"[副]","accent":"②","meaning":"共计","example":"参加費と資料代を合わせて一万円を超えるため、主催者は学生向けの割引制度を用意した。","exampleZh":"参加费和资料费合计超过一万日元，因此主办方准备了面向学生的折扣制度。","note":"例：\n参加費と資料代を合わせて一万円を超えるため、主催者は学生向けの割引制度を用意した。\n译：参加费和资料费合计超过一万日元，因此主办方准备了面向学生的折扣制度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0124","seq":124,"level":"N1","type":"主词条","word":"暗雲","kana":"あんうん","pos":"[名]","accent":"⓪","meaning":"乌云；形势险恶","example":"順調に見えた交渉に暗雲が立ちこめ、担当者は最悪の場合の代替案を準備し始めた。","exampleZh":"看似顺利的谈判笼罩上阴云，负责人开始准备最坏情况下的替代方案。","note":"例：\n順調に見えた交渉に暗雲が立ちこめ、担当者は最悪の場合の代替案を準備し始めた。\n译：看似顺利的谈判笼罩上阴云，负责人开始准备最坏情况下的替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0125","seq":125,"level":"N1","type":"主词条","word":"アンコール","kana":"あんこーる (encore)","pos":"[名·他動3]","accent":"③","meaning":"要求重演","example":"観客のアンコールに応えて、演奏者は予定になかった静かな曲を最後に一曲だけ披露した。","exampleZh":"应观众安可要求，演奏者最后临时演奏了一首原计划外的安静曲子。","note":"例：\n観客のアンコールに応えて、演奏者は予定になかった静かな曲を最後に一曲だけ披露した。\n译：应观众安可要求，演奏者最后临时演奏了一首原计划外的安静曲子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0126","seq":126,"level":"N1","type":"主词条","word":"暗殺","kana":"あんさつ","pos":"[名·他動3]","accent":"⓪","meaning":"暗杀","example":"政治家の暗殺は一人の命を奪うだけでなく、社会全体に深い不安と不信を残す。","exampleZh":"政治家的暗杀不仅夺走一个人的生命，也会给整个社会留下深重的不安与不信任。","note":"例：\n政治家の暗殺は一人の命を奪うだけでなく、社会全体に深い不安と不信を残す。\n译：政治家的暗杀不仅夺走一个人的生命，也会给整个社会留下深重的不安与不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0127","seq":127,"level":"N1","type":"主词条","word":"暗算","kana":"あんざん","pos":"[名·他動3]","accent":"⓪","meaning":"心算","example":"彼は暗算が得意だが、契約書の金額だけは必ず電卓で確認するようにしている。","exampleZh":"他很擅长心算，但合同上的金额一定会用计算器再次确认。","note":"例：\n彼は暗算が得意だが、契約書の金額だけは必ず電卓で確認するようにしている。\n译：他很擅长心算，但合同上的金额一定会用计算器再次确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0128","seq":128,"level":"N1","type":"主词条","word":"暗示","kana":"あんじ","pos":"[名·他動3]","accent":"⓪","meaning":"提示，暗示","example":"上司の短い一言は方針転換を暗示しており、担当者たちは次の会議に向けて準備を始めた。","exampleZh":"上司短短一句话暗示了方针转变，负责人们开始为下一次会议做准备。","note":"例：\n上司の短い一言は方針転換を暗示しており、担当者たちは次の会議に向けて準備を始めた。\n译：上司短短一句话暗示了方针转变，负责人们开始为下一次会议做准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0129","seq":129,"level":"N1","type":"主词条","word":"案じる","kana":"あんじる","pos":"[他動2]","accent":"③⓪","meaning":"担心，挂念","example":"遠方に暮らす母を案じるあまり、彼は毎晩のように電話をかけて体調を確かめている。","exampleZh":"他过于挂念远方生活的母亲，几乎每晚都会打电话确认她的身体状况。","note":"例：\n遠方に暮らす母を案じるあまり、彼は毎晩のように電話をかけて体調を確かめている。\n译：他过于挂念远方生活的母亲，几乎每晚都会打电话确认她的身体状况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0130","seq":130,"level":"N1","type":"主词条","word":"安静","kana":"あんせい","pos":"[名·ナ形]","accent":"⓪","meaning":"（病人）静养","example":"医師から数日は安静にするよう言われたため、彼は無理に出社せず自宅で回復を待った。","exampleZh":"医生叮嘱他这几天静养，所以他没有勉强去公司，而是在家等待恢复。","note":"例：\n医師から数日は安静にするよう言われたため、彼は無理に出社せず自宅で回復を待った。\n译：医生叮嘱他这几天静养，所以他没有勉强去公司，而是在家等待恢复。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0131","seq":131,"level":"N1","type":"主词条","word":"案の定","kana":"あんのじょう","pos":"[副]","accent":"③","meaning":"果然","example":"朝から空が重く曇っていたが、案の定、式が始まる直前に強い雨が降り出した。","exampleZh":"从早上起天空就阴沉沉的，果然，仪式开始前一刻下起了大雨。","note":"例：\n朝から空が重く曇っていたが、案の定、式が始まる直前に強い雨が降り出した。\n译：从早上起天空就阴沉沉的，果然，仪式开始前一刻下起了大雨。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0132","seq":132,"level":"N1","type":"主词条","word":"安楽死","kana":"あんらくし","pos":"[名]","accent":"④③","meaning":"安乐死","example":"安楽死の是非を考える際には、本人の意思だけでなく、家族や医療現場が抱える葛藤も避けて通れない。","exampleZh":"思考安乐死的是非时，不能只看本人意愿，也绕不开家属和医疗现场所承受的矛盾。","note":"例：\n安楽死の是非を考える際には、本人の意思だけでなく、家族や医療現場が抱える葛藤も避けて通れない。\n译：思考安乐死的是非时，不能只看本人意愿，也绕不开家属和医疗现场所承受的矛盾。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0133","seq":133,"level":"N1","type":"主词条","word":"言いそびれる","kana":"いいそびれる","pos":"[他動2]","accent":"⑤","meaning":"（失去机会）没能说出","example":"感謝の言葉を言いそびれると後悔が残るため、彼は帰り際に短くても気持ちを伝えることにした。","exampleZh":"如果错过表达感谢的机会，就会留下后悔，所以他决定临走时哪怕简短也要传达心意。","note":"例：\n感謝の言葉を言いそびれると後悔が残るため、彼は帰り際に短くても気持ちを伝えることにした。\n译：如果错过表达感谢的机会，就会留下后悔，所以他决定临走时哪怕简短也要传达心意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0134","seq":134,"level":"N1","type":"主词条","word":"言い張る","kana":"いいはる","pos":"[他動1]","accent":"③","meaning":"坚持主张，固执己见","example":"自分だけが正しいと言い張るのではなく、彼は反対意見の根拠も聞いてから結論を出した。","exampleZh":"他没有一味坚持只有自己正确，而是在听取反对意见的依据后才作出结论。","note":"例：\n自分だけが正しいと言い張るのではなく、彼は反対意見の根拠も聞いてから結論を出した。\n译：他没有一味坚持只有自己正确，而是在听取反对意见的依据后才作出结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0135","seq":135,"level":"N1","type":"主词条","word":"言い分","kana":"いいぶん","pos":"[名]","accent":"⓪","meaning":"主张，想法；不满","example":"相手の言い分を最後まで聞くと、単なるわがままではなく現場の負担が背景にあることが分かった。","exampleZh":"听完对方的主张后才明白，那并非单纯任性，背后还有现场负担的问题。","note":"例：\n相手の言い分を最後まで聞くと、単なるわがままではなく現場の負担が背景にあることが分かった。\n译：听完对方的主张后才明白，那并非单纯任性，背后还有现场负担的问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0136","seq":136,"level":"N1","type":"主词条","word":"言いよどむ","kana":"いいよどむ","pos":"[他動1]","accent":"④","meaning":"吞吞吐吐地说","example":"重要な点で言いよどむ彼を見て、上司はまだ隠している事情があるのではないかと感じた。","exampleZh":"看到他在关键点上吞吞吐吐，上司觉得他也许还有隐瞒的情况。","note":"例：\n重要な点で言いよどむ彼を見て、上司はまだ隠している事情があるのではないかと感じた。\n译：看到他在关键点上吞吞吐吐，上司觉得他也许还有隐瞒的情况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0137","seq":137,"level":"N1","type":"主词条","word":"言い渡す","kana":"いいわたす","pos":"[他動1]","accent":"④","meaning":"宣告，宣判；告知；命令","example":"解雇を言い渡す場面では、会社側にも相手の生活を考えた誠実な対応が求められる。","exampleZh":"在宣告解雇的场面中，公司一方也需要顾及对方生活，作出诚恳应对。","note":"例：\n解雇を言い渡す場面では、会社側にも相手の生活を考えた誠実な対応が求められる。\n译：在宣告解雇的场面中，公司一方也需要顾及对方生活，作出诚恳应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0138","seq":138,"level":"N1","type":"主词条","word":"家路","kana":"いえじ","pos":"[名]","accent":"⓪","meaning":"回家的路","example":"遅い会議を終えて家路につく頃には雨が上がり、駅前の通りに街灯が静かに光っていた。","exampleZh":"结束很晚的会议踏上归途时，雨已经停了，车站前的街灯静静亮着。","note":"例：\n遅い会議を終えて家路につく頃には雨が上がり、駅前の通りに街灯が静かに光っていた。\n译：结束很晚的会议踏上归途时，雨已经停了，车站前的街灯静静亮着。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0139","seq":139,"level":"N1","type":"主词条","word":"家出","kana":"いえで","pos":"[名·自動3]","accent":"⓪","meaning":"离家出走","example":"家出した少年を責める前に、相談員は家で何が起きていたのかを時間をかけて聞き取った。","exampleZh":"在责备离家出走的少年之前，咨询员花时间询问家里究竟发生了什么。","note":"例：\n家出した少年を責める前に、相談員は家で何が起きていたのかを時間をかけて聞き取った。\n译：在责备离家出走的少年之前，咨询员花时间询问家里究竟发生了什么。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0140","seq":140,"level":"N1","type":"主词条","word":"威嚇","kana":"いかく","pos":"[名·他動3]","accent":"⓪","meaning":"威吓","example":"大声で威嚇して相手を黙らせても、根本的な不満が消えるわけではない。","exampleZh":"即使用大声威吓迫使对方沉默，也并不意味着根本性的不满会消失。","note":"例：\n大声で威嚇して相手を黙らせても、根本的な不満が消えるわけではない。\n译：即使用大声威吓迫使对方沉默，也并不意味着根本性的不满会消失。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0141","seq":141,"level":"N1","type":"主词条","word":"生かす/活かす","kana":"いかす","pos":"[他動1]","accent":"②","meaning":"留性命，让……活着；发挥，有效利用","example":"生かす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“留性命，让活着；发挥，有效利用”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n生かす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“留性命，让活着；发挥，有效利用”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0142","seq":142,"level":"N1","type":"主词条","word":"いかなる","kana":"いかなる","pos":"[連体]","accent":"②","meaning":"如何的，怎样的","example":"いかなる事情があっても、命に関わる確認だけは省略してはならない。","exampleZh":"无论有什么情况，关系到生命安全的确认都绝不能省略。","note":"例：\nいかなる事情があっても、命に関わる確認だけは省略してはならない。\n译：无论有什么情况，关系到生命安全的确认都绝不能省略。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0143","seq":143,"level":"N1","type":"主词条","word":"いかに","kana":"いかに","pos":"[副]","accent":"②","meaning":"如何；无论怎么；多么","example":"経験が豊富でも、いかに冷静に状況を見極められるかで、緊急時の判断は大きく変わる。","exampleZh":"即使经验丰富，紧急时的判断也会因能否冷静看清状况而大不相同。","note":"例：\n経験が豊富でも、いかに冷静に状況を見極められるかで、緊急時の判断は大きく変わる。\n译：即使经验丰富，紧急时的判断也会因能否冷静看清状况而大不相同。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0144","seq":144,"level":"N1","type":"主词条","word":"いかにも","kana":"いかにも","pos":"[副]","accent":"②","meaning":"简直，实在是","example":"その店構えはいかにも老舗らしく、入口の古い木札からも長い歴史が感じられた。","exampleZh":"那家店的门面一看就很有老字号气派，从入口处的旧木牌也能感到悠久历史。","note":"例：\nその店構えはいかにも老舗らしく、入口の古い木札からも長い歴史が感じられた。\n译：那家店的门面一看就很有老字号气派，从入口处的旧木牌也能感到悠久历史。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0145","seq":145,"level":"N1","type":"主词条","word":"遺憾","kana":"いかん","pos":"[名·ナ形]","accent":"⓪①","meaning":"遗憾","example":"事前の周知が不足していた点は遺憾であり、担当者は改めて経緯を公開することにした。","exampleZh":"事前通知不足这一点令人遗憾，负责人决定重新公开事情经过。","note":"例：\n事前の周知が不足していた点は遺憾であり、担当者は改めて経緯を公開することにした。\n译：事前通知不足这一点令人遗憾，负责人决定重新公开事情经过。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0146","seq":146,"level":"N1","type":"主词条","word":"粋","kana":"いき","pos":"[名·ナ形]","accent":"⓪","meaning":"漂亮，时髦；通情达理","example":"粋な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“漂亮，时髦；通情达理”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n粋な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“漂亮，时髦；通情达理”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0147","seq":147,"level":"N1","type":"主词条","word":"遺棄","kana":"いき","pos":"[名·他動3]","accent":"①","meaning":"遗弃","example":"山林にごみを遺棄する行為は、景観だけでなく水質や野生動物にも悪影響を与える。","exampleZh":"在山林中丢弃垃圾的行为，不仅破坏景观，也会对水质和野生动物造成恶劣影响。","note":"例：\n山林にごみを遺棄する行為は、景観だけでなく水質や野生動物にも悪影響を与える。\n译：在山林中丢弃垃圾的行为，不仅破坏景观，也会对水质和野生动物造成恶劣影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0148","seq":148,"level":"N1","type":"主词条","word":"異議","kana":"いぎ","pos":"[名]","accent":"①","meaning":"异议","example":"会議で異議が出たおかげで、担当者は計画の弱点を早い段階で見直すことができた。","exampleZh":"会议上有人提出异议，负责人因此得以在早期重新审视计划的弱点。","note":"例：\n会議で異議が出たおかげで、担当者は計画の弱点を早い段階で見直すことができた。\n译：会议上有人提出异议，负责人因此得以在早期重新审视计划的弱点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0149","seq":149,"level":"N1","type":"主词条","word":"行き当たりばったり","kana":"いきあたりばったり","pos":"[名·ナ形]","accent":"⑥⑧","meaning":"漫无目的，没有准谱","example":"一度行き当たりばったりだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“漫无目的，没有准谱”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度行き当たりばったりだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“漫无目的，没有准谱”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0150","seq":150,"level":"N1","type":"主词条","word":"意気込み","kana":"いきごみ","pos":"[名]","accent":"⓪③","meaning":"干劲，热情","example":"入社式で語った彼の意気込みは立派だったが、上司は言葉より日々の行動で示してほしいと伝えた。","exampleZh":"他在入职仪式上表达的干劲很出色，但上司告诉他，比起语言，更希望他用日常行动来证明。","note":"例：\n入社式で語った彼の意気込みは立派だったが、上司は言葉より日々の行動で示してほしいと伝えた。\n译：他在入职仪式上表达的干劲很出色，但上司告诉他，比起语言，更希望他用日常行动来证明。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0151","seq":151,"level":"N1","type":"主词条","word":"意気込む","kana":"いきごむ","pos":"[自動1]","accent":"③","meaning":"振奋，鼓起干劲","example":"新しい企画に意気込むのはよいが、実現までの手順を冷静に確認しなければ空回りしてしまう。","exampleZh":"对新企划充满干劲固然很好，但若不冷静确认实现步骤，就会空转。","note":"例：\n新しい企画に意気込むのはよいが、実現までの手順を冷静に確認しなければ空回りしてしまう。\n译：对新企划充满干劲固然很好，但若不冷静确认实现步骤，就会空转。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0152","seq":152,"level":"N1","type":"主词条","word":"経緯","kana":"いきさつ","pos":"[名]","accent":"⓪","meaning":"事情的经过，原委","example":"トラブルの経緯を整理すると、最初の連絡不足が後の大きな誤解につながっていたことが分かった。","exampleZh":"整理纠纷的经过后，才发现最初联络不足导致了后来严重的误解。","note":"例：\nトラブルの経緯を整理すると、最初の連絡不足が後の大きな誤解につながっていたことが分かった。\n译：整理纠纷的经过后，才发现最初联络不足导致了后来严重的误解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0153","seq":153,"level":"N1","type":"主词条","word":"行き違う","kana":"いきちがう","pos":"[自動1]","accent":"④","meaning":"错过，走岔；失和，误会","example":"自分の道を行き違うなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“错过，走岔；失和，误会”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を行き違うなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“错过，走岔；失和，误会”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0154","seq":154,"level":"N1","type":"主词条","word":"行き詰まる","kana":"いきづまる","pos":"[自動1]","accent":"④","meaning":"行不通，走投无路；陷入僵局","example":"自分の道を行き詰まるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“行不通，走投无路；陷入僵局”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を行き詰まるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“行不通，走投无路；陷入僵局”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0155","seq":155,"level":"N1","type":"主词条","word":"憤り","kana":"いきどおり","pos":"[名]","accent":"⓪⑤","meaning":"愤怒","example":"不公平な評価への憤りを感じても、彼女は感情的に訴える前に事実と記録をそろえた。","exampleZh":"即使对不公平评价感到愤怒，她也没有先情绪化申诉，而是备齐了事实和记录。","note":"例：\n不公平な評価への憤りを感じても、彼女は感情的に訴える前に事実と記録をそろえた。\n译：即使对不公平评价感到愤怒，她也没有先情绪化申诉，而是备齐了事实和记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0156","seq":156,"level":"N1","type":"主词条","word":"息抜き","kana":"いきぬき","pos":"[名·自動3]","accent":"③④","meaning":"休息一下，歇口气","example":"長時間の作業では適度な息抜きを入れることで、集中力と判断の正確さを保ちやすくなる。","exampleZh":"长时间作业中适度休息一下，更容易保持专注力和判断的准确性。","note":"例：\n長時間の作業では適度な息抜きを入れることで、集中力と判断の正確さを保ちやすくなる。\n译：长时间作业中适度休息一下，更容易保持专注力和判断的准确性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0157","seq":157,"level":"N1","type":"主词条","word":"育成","kana":"いくせい","pos":"[名·他動3]","accent":"⓪","meaning":"培育，培养","example":"若手の育成には、失敗を叱るだけでなく、挑戦できる仕事を段階的に任せる工夫が必要だ。","exampleZh":"培养年轻员工不能只是责备失败，还需要分阶段交给他们能够挑战的工作。","note":"例：\n若手の育成には、失敗を叱るだけでなく、挑戦できる仕事を段階的に任せる工夫が必要だ。\n译：培养年轻员工不能只是责备失败，还需要分阶段交给他们能够挑战的工作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0158","seq":158,"level":"N1","type":"主词条","word":"幾多","kana":"いくた","pos":"[名·副]","accent":"①","meaning":"多少，许多","example":"幾多の失敗を乗り越えて完成した技術だからこそ、開発者たちは簡単には妥協しなかった。","exampleZh":"正因为这项技术是跨越无数失败后才完成的，开发者们才不肯轻易妥协。","note":"例：\n幾多の失敗を乗り越えて完成した技術だからこそ、開発者たちは簡単には妥協しなかった。\n译：正因为这项技术是跨越无数失败后才完成的，开发者们才不肯轻易妥协。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0159","seq":159,"level":"N1","type":"主词条","word":"異見","kana":"いけん","pos":"[名]","accent":"⓪","meaning":"异议","example":"異見を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“异议”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\n異見を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“异议”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0160","seq":160,"level":"N1","type":"主词条","word":"憩い","kana":"いこい","pos":"[名]","accent":"⓪","meaning":"休息，休憩","example":"公園は近隣住民にとって憩いの場であり、子どもから高齢者まで安心して過ごせる。","exampleZh":"公园是附近居民休憩的场所，从孩子到老人都能安心度过时光。","note":"例：\n公園は近隣住民にとって憩いの場であり、子どもから高齢者まで安心して過ごせる。\n译：公园是附近居民休憩的场所，从孩子到老人都能安心度过时光。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0161","seq":161,"level":"N1","type":"主词条","word":"移行","kana":"いこう","pos":"[名·自動3]","accent":"⓪","meaning":"转移，过渡","example":"新しいシステムへの移行を急ぎすぎると、現場が操作に慣れず、かえって混乱が広がる。","exampleZh":"如果过于急切地迁移到新系统，现场尚未习惯操作，反而会扩大混乱。","note":"例：\n新しいシステムへの移行を急ぎすぎると、現場が操作に慣れず、かえって混乱が広がる。\n译：如果过于急切地迁移到新系统，现场尚未习惯操作，反而会扩大混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0162","seq":162,"level":"N1","type":"主词条","word":"意向","kana":"いこう","pos":"[名]","accent":"⓪","meaning":"意向，打算","example":"住民の意向を確認せずに計画を進めれば、完成後も反発が残り、地域との信頼関係が損なわれる。","exampleZh":"如果不确认居民意向就推进计划，即使完成后也会留下反对，损害与地区之间的信任关系。","note":"例：\n住民の意向を確認せずに計画を進めれば、完成後も反発が残り、地域との信頼関係が損なわれる。\n译：如果不确认居民意向就推进计划，即使完成后也会留下反对，损害与地区之间的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0163","seq":163,"level":"N1","type":"主词条","word":"いざ","kana":"いざ","pos":"[嘆]","accent":"①","meaning":"到了关键时刻","example":"いざ本番となると緊張で手が震えたが、彼は深呼吸をして練習どおり最初の一文を読み上げた。","exampleZh":"一到正式上场时，他紧张得手发抖，但还是深呼吸后按练习那样读出了开头第一句。","note":"例：\nいざ本番となると緊張で手が震えたが、彼は深呼吸をして練習どおり最初の一文を読み上げた。\n译：一到正式上场时，他紧张得手发抖，但还是深呼吸后按练习那样读出了开头第一句。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0164","seq":164,"level":"N1","type":"主词条","word":"潔い","kana":"いさぎよい","pos":"[イ形]","accent":"④","meaning":"果断，痛快","example":"潔い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“果断，痛快”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n潔い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“果断，痛快”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0165","seq":165,"level":"N1","type":"主词条","word":"いささか","kana":"いささか","pos":"[副]","accent":"②","meaning":"有点，稍微；（与否定相呼应）丝毫不（不）","example":"彼の話はいささか長かったが、初めて参加した人にも背景が分かるよう丁寧に組み立てられていた。","exampleZh":"他的话稍微有些长，但为了让初次参加的人也理解背景，内容被组织得很细致。","note":"例：\n彼の話はいささか長かったが、初めて参加した人にも背景が分かるよう丁寧に組み立てられていた。\n译：他的话稍微有些长，但为了让初次参加的人也理解背景，内容被组织得很细致。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0166","seq":166,"level":"N1","type":"主词条","word":"意地","kana":"いじ","pos":"[名]","accent":"②","meaning":"用心，心术；固执，倔强","example":"つまらない意地を張ったせいで謝る機会を失い、彼は友人との関係を長くこじらせてしまった。","exampleZh":"因为无聊的固执而失去了道歉机会，他和朋友的关系长期陷入僵局。","note":"例：\nつまらない意地を張ったせいで謝る機会を失い、彼は友人との関係を長くこじらせてしまった。\n译：因为无聊的固执而失去了道歉机会，他和朋友的关系长期陷入僵局。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0167","seq":167,"level":"N1","type":"主词条","word":"移住","kana":"いじゅう","pos":"[名·自動3]","accent":"⓪","meaning":"移居","example":"移住する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“移居”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n移住する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“移居”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0168","seq":168,"level":"N1","type":"主词条","word":"萎縮","kana":"いしゅく","pos":"[名·自動3]","accent":"⓪","meaning":"萎缩","example":"上司が強く叱りすぎると部下は萎縮し、必要な報告まで遅れるようになってしまう。","exampleZh":"上司训斥得过于严厉，部下就会畏缩，甚至连必要报告都会变得迟缓。","note":"例：\n上司が強く叱りすぎると部下は萎縮し、必要な報告まで遅れるようになってしまう。\n译：上司训斥得过于严厉，部下就会畏缩，甚至连必要报告都会变得迟缓。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0169","seq":169,"level":"N1","type":"主词条","word":"衣装","kana":"いしょう","pos":"[名]","accent":"①","meaning":"（特殊）衣裳，服装","example":"式典に着ていく衣装を選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“衣裳，服装”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていく衣装を選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“衣裳，服装”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0170","seq":170,"level":"N1","type":"主词条","word":"移植","kana":"いしょく","pos":"[名·他動3]","accent":"⓪","meaning":"移植","example":"臓器の移植には高度な技術だけでなく、本人や家族の意思を丁寧に確認する過程が欠かせない。","exampleZh":"器官移植不仅需要高超技术，也少不了细致确认本人和家属意愿的过程。","note":"例：\n臓器の移植には高度な技術だけでなく、本人や家族の意思を丁寧に確認する過程が欠かせない。\n译：器官移植不仅需要高超技术，也少不了细致确认本人和家属意愿的过程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0171","seq":171,"level":"N1","type":"主词条","word":"弄る","kana":"いじる","pos":"[他動1]","accent":"②","meaning":"摆弄，摆弄；玩赏；随意改动","example":"自分の道を弄るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“摆弄，摆弄；玩赏”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を弄るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“摆弄，摆弄；玩赏”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0172","seq":172,"level":"N1","type":"主词条","word":"居座る","kana":"いすわる","pos":"[自動1]","accent":"③","meaning":"赖着不走；留任","example":"閉店時間を過ぎても客が店に居座るため、店員は丁寧に退店を促した。","exampleZh":"客人过了闭店时间还赖着不走，店员只好礼貌地催促其离店。","note":"例：\n閉店時間を過ぎても客が店に居座るため、店員は丁寧に退店を促した。\n译：客人过了闭店时间还赖着不走，店员只好礼貌地催促其离店。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0173","seq":173,"level":"N1","type":"主词条","word":"移籍","kana":"いせき","pos":"[名·自動3]","accent":"⓪","meaning":"转移户籍；（运动员）转会","example":"有力選手の移籍が決まると、チームの戦術だけでなくファンの期待も大きく揺れ動いた。","exampleZh":"有实力的选手决定转会后，不仅球队战术，连粉丝的期待也大幅动摇。","note":"例：\n有力選手の移籍が決まると、チームの戦術だけでなくファンの期待も大きく揺れ動いた。\n译：有实力的选手决定转会后，不仅球队战术，连粉丝的期待也大幅动摇。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0174","seq":174,"level":"N1","type":"主词条","word":"遺跡","kana":"いせき","pos":"[名]","accent":"⓪","meaning":"遗址，遗迹","example":"観光客が増えた遺跡では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“遗址，遗迹”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた遺跡では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“遗址，遗迹”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0175","seq":175,"level":"N1","type":"主词条","word":"依然","kana":"いぜん","pos":"[副]","accent":"⓪","meaning":"依然","example":"交渉は依然として難航しており、双方がどこまで譲歩できるかが最大の焦点になっている。","exampleZh":"谈判依然进展艰难，双方究竟能让步到什么程度成了最大焦点。","note":"例：\n交渉は依然として難航しており、双方がどこまで譲歩できるかが最大の焦点になっている。\n译：谈判依然进展艰难，双方究竟能让步到什么程度成了最大焦点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0176","seq":176,"level":"N1","type":"主词条","word":"いそいそ","kana":"いそいそ","pos":"[副·自動3]","accent":"①③","meaning":"高兴地，兴冲冲地","example":"彼女は久しぶりに会う友人への土産を包み、いそいそと駅へ向かった。","exampleZh":"她包好给久违见面的朋友的伴手礼，兴冲冲地前往车站。","note":"例：\n彼女は久しぶりに会う友人への土産を包み、いそいそと駅へ向かった。\n译：她包好给久违见面的朋友的伴手礼，兴冲冲地前往车站。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0177","seq":177,"level":"N1","type":"主词条","word":"依存","kana":"いそん","pos":"[名·自動3]","accent":"⓪","meaning":"依存，依靠","example":"一つの取引先に依存しすぎると、相手の事情だけで会社全体の経営が不安定になる。","exampleZh":"如果过度依赖单一客户，公司整体经营就会因对方情况而变得不稳定。","note":"例：\n一つの取引先に依存しすぎると、相手の事情だけで会社全体の経営が不安定になる。\n译：如果过度依赖单一客户，公司整体经营就会因对方情况而变得不稳定。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0178","seq":178,"level":"N1","type":"主词条","word":"委託","kana":"いたく","pos":"[名·他動3]","accent":"⓪","meaning":"委托","example":"業務を外部に委託する場合でも、責任の所在と情報管理の方法を曖昧にしてはいけない。","exampleZh":"即使把业务委托给外部，也不能把责任所在和信息管理方法弄得含糊不清。","note":"例：\n業務を外部に委託する場合でも、責任の所在と情報管理の方法を曖昧にしてはいけない。\n译：即使把业务委托给外部，也不能把责任所在和信息管理方法弄得含糊不清。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0179","seq":179,"level":"N1","type":"主词条","word":"致し方ない","kana":"いたしかたない","pos":"[連語]","accent":"⑥","meaning":"没有办法","example":"悪天候で船が欠航したのなら、日程変更も致し方ない。","exampleZh":"如果因为恶劣天气船只停航，那么更改日程也无可奈何。","note":"例：\n悪天候で船が欠航したのなら、日程変更も致し方ない。\n译：如果因为恶劣天气船只停航，那么更改日程也无可奈何。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0180","seq":180,"level":"N1","type":"主词条","word":"至って","kana":"いたって","pos":"[副]","accent":"⓪②","meaning":"极其","example":"彼の口調は至って穏やかだったが、発言の内容には計画への強い懸念が込められていた。","exampleZh":"他的语气极其温和，但发言内容中包含着对计划的强烈担忧。","note":"例：\n彼の口調は至って穏やかだったが、発言の内容には計画への強い懸念が込められていた。\n译：他的语气极其温和，但发言内容中包含着对计划的强烈担忧。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0181","seq":181,"level":"N1","type":"主词条","word":"痛手","kana":"いたで","pos":"[名]","accent":"⓪","meaning":"重伤；重创","example":"その痛手は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“重伤；重创”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその痛手は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“重伤；重创”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0182","seq":182,"level":"N1","type":"主词条","word":"板挟み","kana":"いたばさみ","pos":"[名]","accent":"③","meaning":"两头受气","example":"上司と部下の板挟みになった彼は、どちらかを責める前に互いの不満を整理して伝えた。","exampleZh":"夹在上司和部下之间的他，没有先责备任何一方，而是整理并传达了彼此的不满。","note":"例：\n上司と部下の板挟みになった彼は、どちらかを責める前に互いの不満を整理して伝えた。\n译：夹在上司和部下之间的他，没有先责备任何一方，而是整理并传达了彼此的不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0183","seq":183,"level":"N1","type":"主词条","word":"痛ましい","kana":"いたましい","pos":"[イ形]","accent":"④","meaning":"令人痛心，惨不忍睹","example":"痛ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“令人痛心，惨不忍睹”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n痛ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“令人痛心，惨不忍睹”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0184","seq":184,"level":"N1","type":"主词条","word":"悼む","kana":"いたむ","pos":"[他動1]","accent":"②","meaning":"悼念","example":"無理に悼むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“悼念”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に悼むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“悼念”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0185","seq":185,"level":"N1","type":"主词条","word":"痛める","kana":"いためる","pos":"[他動2]","accent":"③","meaning":"使疼痛，损伤","example":"相手に何かを痛めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“使疼痛，损伤”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを痛めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“使疼痛，损伤”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0186","seq":186,"level":"N1","type":"主词条","word":"炒める","kana":"いためる","pos":"[他動2]","accent":"③","meaning":"炒（食物）","example":"炒める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“炒”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n炒める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“炒”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0187","seq":187,"level":"N1","type":"主词条","word":"至れり尽くせり","kana":"いたれりつくせり","pos":"[名]","accent":"③⑦","meaning":"无微不至，尽善尽美","example":"その旅館のサービスは至れり尽くせりで、客が頼む前に必要なものがさりげなく用意されていた。","exampleZh":"那家旅馆的服务无微不至，客人还没开口，需要的东西就已被自然地准备好了。","note":"例：\nその旅館のサービスは至れり尽くせりで、客が頼む前に必要なものがさりげなく用意されていた。\n译：那家旅馆的服务无微不至，客人还没开口，需要的东西就已被自然地准备好了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0188","seq":188,"level":"N1","type":"主词条","word":"労わる","kana":"いたわる","pos":"[他動1]","accent":"③","meaning":"体贴，慰劳，关心","example":"無理に労わるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“体贴，慰劳，关心”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に労わるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“体贴，慰劳，关心”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0189","seq":189,"level":"N1","type":"主词条","word":"異端児","kana":"いたんじ","pos":"[名]","accent":"②","meaning":"异端分子","example":"その異端児は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“异端分子”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその異端児は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“异端分子”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0190","seq":190,"level":"N1","type":"主词条","word":"一概に","kana":"いちがいに","pos":"[副]","accent":"⓪②","meaning":"（后接否定）一概","example":"数字だけを見て一概に失敗とは言えず、現場では利用者の満足度も丁寧に確認する必要がある。","exampleZh":"不能只看数字就一概说是失败，现场还需要细致确认使用者的满意度。","note":"例：\n数字だけを見て一概に失敗とは言えず、現場では利用者の満足度も丁寧に確認する必要がある。\n译：不能只看数字就一概说是失败，现场还需要细致确认使用者的满意度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0191","seq":191,"level":"N1","type":"主词条","word":"一か八か","kana":"いちかばちか","pos":"[副]","accent":"","meaning":"碰运气，听天由命","example":"一か八かで新しい案を出すのではなく、彼は失敗した場合の代替策まで準備してから提案した。","exampleZh":"他没有抱着碰运气的心态提出新方案，而是在准备好失败时的替代方案后才提案。","note":"例：\n一か八かで新しい案を出すのではなく、彼は失敗した場合の代替策まで準備してから提案した。\n译：他没有抱着碰运气的心态提出新方案，而是在准备好失败时的替代方案后才提案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0192","seq":192,"level":"N1","type":"主词条","word":"一眼レフ","kana":"いちがんれふ","pos":"[名]","accent":"⑤","meaning":"单反相机","example":"古い一眼レフを不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“单反相机”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い一眼レフを不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“单反相机”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0193","seq":193,"level":"N1","type":"主词条","word":"著しい","kana":"いちじるしい","pos":"[イ形]","accent":"⑤","meaning":"明显的，显著的","example":"著しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“明显的，显著的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n著しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“明显的，显著的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0194","seq":194,"level":"N1","type":"主词条","word":"一大事","kana":"いちだいじ","pos":"[名]","accent":"③","meaning":"一件大事","example":"小さな確認漏れに見えても、安全に関わるなら一大事になるため、責任者はすぐに作業を止めた。","exampleZh":"即使看似只是小小确认遗漏，只要关系到安全就会成为大事，因此负责人立即停止了作业。","note":"例：\n小さな確認漏れに見えても、安全に関わるなら一大事になるため、責任者はすぐに作業を止めた。\n译：即使看似只是小小确认遗漏，只要关系到安全就会成为大事，因此负责人立即停止了作业。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0195","seq":195,"level":"N1","type":"主词条","word":"一同","kana":"いちどう","pos":"[名]","accent":"③","meaning":"全体人员，大家","example":"一同として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“全体人员，大家”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n一同として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“全体人员，大家”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0196","seq":196,"level":"N1","type":"主词条","word":"一番乗り","kana":"いちばんのり","pos":"[名·自動3]","accent":"③","meaning":"最先到场","example":"新商品の発売日に一番乗りしようと、彼は始発電車で店へ向かった。","exampleZh":"为了在新商品发售日第一个到场，他乘首班电车去了店里。","note":"例：\n新商品の発売日に一番乗りしようと、彼は始発電車で店へ向かった。\n译：为了在新商品发售日第一个到场，他乘首班电车去了店里。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0197","seq":197,"level":"N1","type":"主词条","word":"一抹","kana":"いちまつ","pos":"[名]","accent":"⓪","meaning":"一丝，些许","example":"一抹だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。","exampleZh":"如果只凭“一丝，些许”评价一个人，就会忽视其努力过程和对周围的贡献。","note":"例：\n一抹だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。\n译：如果只凭“一丝，些许”评价一个人，就会忽视其努力过程和对周围的贡献。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0198","seq":198,"level":"N1","type":"主词条","word":"一面","kana":"いちめん","pos":"[名·副]","accent":"①②","meaning":"整个，全体；另一面","example":"彼の発言には厳しい一面もあるが、部下を成長させたいという思いが根底にある。","exampleZh":"他的发言也有严厉的一面，但根底里是希望部下成长的心意。","note":"例：\n彼の発言には厳しい一面もあるが、部下を成長させたいという思いが根底にある。\n译：他的发言也有严厉的一面，但根底里是希望部下成长的心意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0199","seq":199,"level":"N1","type":"主词条","word":"一目","kana":"いちもく","pos":"[名·自動3]","accent":"⓪②","meaning":"一眼，略看一下；一目（围棋的一个棋子）","example":"資料を一目見ただけで問題点を見抜いた彼は、数字の並びに長年の経験を感じ取っていた。","exampleZh":"他只看了一眼资料就看出问题点，从数字排列中感受到了多年经验。","note":"例：\n資料を一目見ただけで問題点を見抜いた彼は、数字の並びに長年の経験を感じ取っていた。\n译：他只看了一眼资料就看出问题点，从数字排列中感受到了多年经验。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0200","seq":200,"level":"N1","type":"主词条","word":"一目散に","kana":"いちもくさんに","pos":"[副]","accent":"③","meaning":"一溜烟地","example":"警報が鳴った瞬間、子どもたちは先生の指示に従って一目散に校庭へ避難した。","exampleZh":"警报响起的一瞬间，孩子们按照老师指示飞快地跑到操场避难。","note":"例：\n警報が鳴った瞬間、子どもたちは先生の指示に従って一目散に校庭へ避難した。\n译：警报响起的一瞬间，孩子们按照老师指示飞快地跑到操场避难。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0201","seq":201,"level":"N1","type":"主词条","word":"一様","kana":"いちよう","pos":"[名·ナ形]","accent":"⓪","meaning":"同样；普通，平常","example":"参加者の反応は一様ではなく、改革を歓迎する人もいれば不安を訴える人もいた。","exampleZh":"参加者的反应并不一致，有人欢迎改革，也有人表达不安。","note":"例：\n参加者の反応は一様ではなく、改革を歓迎する人もいれば不安を訴える人もいた。\n译：参加者的反应并不一致，有人欢迎改革，也有人表达不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0202","seq":202,"level":"N1","type":"主词条","word":"一律","kana":"いちりつ","pos":"[名·ナ形]","accent":"⓪","meaning":"一律","example":"一律な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“一律”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n一律な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“一律”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0203","seq":203,"level":"N1","type":"主词条","word":"一連","kana":"いちれん","pos":"[名]","accent":"⓪","meaning":"一系列，一连串","example":"一連だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。","exampleZh":"如果只凭“一系列，一连串”评价一个人，就会忽视其努力过程和对周围的贡献。","note":"例：\n一連だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。\n译：如果只凭“一系列，一连串”评价一个人，就会忽视其努力过程和对周围的贡献。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0204","seq":204,"level":"N1","type":"主词条","word":"一括","kana":"いっかつ","pos":"[名·他動3]","accent":"⓪","meaning":"统一，总括起来","example":"情報を一括する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。","exampleZh":"在“统一，总括起来”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","note":"例：\n情報を一括する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。\n译：在“统一，总括起来”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0205","seq":205,"level":"N1","type":"主词条","word":"一気に","kana":"いっきに","pos":"[副]","accent":"①","meaning":"一口气，一下子","example":"補助金の制度が始まると申請件数が一気に増え、窓口では臨時の担当者を配置することになった。","exampleZh":"补助金制度一开始，申请件数一下子增加，窗口不得不临时安排负责人。","note":"例：\n補助金の制度が始まると申請件数が一気に増え、窓口では臨時の担当者を配置することになった。\n译：补助金制度一开始，申请件数一下子增加，窗口不得不临时安排负责人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0206","seq":206,"level":"N1","type":"主词条","word":"一挙に","kana":"いっきょに","pos":"[副]","accent":"①","meaning":"一举","example":"新しいシステムを導入したことで、手作業で行っていた集計を一挙に自動化できるようになった。","exampleZh":"导入新系统后，原本手工进行的统计一下子实现了自动化。","note":"例：\n新しいシステムを導入したことで、手作業で行っていた集計を一挙に自動化できるようになった。\n译：导入新系统后，原本手工进行的统计一下子实现了自动化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0207","seq":207,"level":"N1","type":"主词条","word":"一見","kana":"いっけん","pos":"[名·他動3·副]","accent":"⓪","meaning":"看一眼，乍一看","example":"一見単純な手続きに見えるが、実際には複数の部署の確認が必要だ。","exampleZh":"乍看像是简单手续，实际上需要多个部门确认。","note":"例：\n一見単純な手続きに見えるが、実際には複数の部署の確認が必要だ。\n译：乍看像是简单手续，实际上需要多个部门确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0208","seq":208,"level":"N1","type":"主词条","word":"一刻も早く","kana":"いっこくもはやく","pos":"[副]","accent":"⑤","meaning":"尽快；火速","example":"被害が広がらないよう、責任者は一刻も早く原因を特定し、利用者へ正確な情報を知らせようとした。","exampleZh":"为了不让损害扩大，负责人想尽快查明原因，并向使用者传达准确信息。","note":"例：\n被害が広がらないよう、責任者は一刻も早く原因を特定し、利用者へ正確な情報を知らせようとした。\n译：为了不让损害扩大，负责人想尽快查明原因，并向使用者传达准确信息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0209","seq":209,"level":"N1","type":"主词条","word":"一切","kana":"いっさい","pos":"[名·副]","accent":"⓪","meaning":"全部；一概","example":"個人情報を扱う書類は、担当者以外には一切見せないという規則が徹底されている。","exampleZh":"处理个人信息的文件，规定必须彻底做到除负责人外一律不让他人查看。","note":"例：\n個人情報を扱う書類は、担当者以外には一切見せないという規則が徹底されている。\n译：处理个人信息的文件，规定必须彻底做到除负责人外一律不让他人查看。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0210","seq":210,"level":"N1","type":"主词条","word":"逸材","kana":"いつざい","pos":"[名]","accent":"⓪","meaning":"卓越的人才","example":"逸材として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“卓越的人才”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n逸材として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“卓越的人才”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0211","seq":211,"level":"N1","type":"主词条","word":"一心","kana":"いっしん","pos":"[名·副]","accent":"③","meaning":"齐心，同心；一心，专心致志","example":"彼女は雑音の多い会場でも一心に資料を読み込み、発表直前まで内容を確認していた。","exampleZh":"她即使在嘈杂的会场中也专心阅读资料，一直到发表前都在确认内容。","note":"例：\n彼女は雑音の多い会場でも一心に資料を読み込み、発表直前まで内容を確認していた。\n译：她即使在嘈杂的会场中也专心阅读资料，一直到发表前都在确认内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0212","seq":212,"level":"N1","type":"主词条","word":"いっそ","kana":"いっそ","pos":"[副]","accent":"⓪","meaning":"干脆，索性","example":"中途半端に修正を重ねるくらいなら、いっそ最初から設計を見直したほうが早いかもしれない。","exampleZh":"与其半途而废地反复修正，不如干脆从最初的设计开始重新审视，也许更快。","note":"例：\n中途半端に修正を重ねるくらいなら、いっそ最初から設計を見直したほうが早いかもしれない。\n译：与其半途而废地反复修正，不如干脆从最初的设计开始重新审视，也许更快。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0213","seq":213,"level":"N1","type":"主词条","word":"一掃","kana":"いっそう","pos":"[名·他動3]","accent":"⓪","meaning":"扫除，清除","example":"古い書類を一掃したことで、必要な契約書をすぐ取り出せるようになり、確認作業の時間が大幅に減った。","exampleZh":"清除旧文件后，必要的合同能够立刻取出，确认作业的时间大幅减少。","note":"例：\n古い書類を一掃したことで、必要な契約書をすぐ取り出せるようになり、確認作業の時間が大幅に減った。\n译：清除旧文件后，必要的合同能够立刻取出，确认作业的时间大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0214","seq":214,"level":"N1","type":"主词条","word":"一帯","kana":"いったい","pos":"[名]","accent":"⓪","meaning":"一带","example":"駅前一帯では再開発が進み、昔からの商店街と新しい商業施設が共存する形を模索している。","exampleZh":"车站前一带正在推进再开发，老商店街与新商业设施正在摸索共存方式。","note":"例：\n駅前一帯では再開発が進み、昔からの商店街と新しい商業施設が共存する形を模索している。\n译：车站前一带正在推进再开发，老商店街与新商业设施正在摸索共存方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0215","seq":215,"level":"N1","type":"主词条","word":"一変","kana":"いっぺん","pos":"[名·自他動3]","accent":"⓪","meaning":"突然改变，完全改变","example":"新しい交通網が整備されると、駅前の人の流れは一変し、古い商店街にも若い客が戻り始めた。","exampleZh":"新的交通网络建成后，车站前的人流完全改变，老商店街也开始重新迎来年轻顾客。","note":"例：\n新しい交通網が整備されると、駅前の人の流れは一変し、古い商店街にも若い客が戻り始めた。\n译：新的交通网络建成后，车站前的人流完全改变，老商店街也开始重新迎来年轻顾客。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0216","seq":216,"level":"N1","type":"主词条","word":"偽る","kana":"いつわる","pos":"[他動1]","accent":"③","meaning":"冒充","example":"相手に何かを偽るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“冒充”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを偽るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“冒充”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0217","seq":217,"level":"N1","type":"主词条","word":"意図","kana":"いと","pos":"[名·他動3]","accent":"①","meaning":"动机，意图；试图，打算","example":"発言の意図が伝わらなければ、同じ言葉でも相手には批判や命令のように聞こえてしまう。","exampleZh":"如果发言意图没有传达到，同样的话在对方听来就可能像批评或命令。","note":"例：\n発言の意図が伝わらなければ、同じ言葉でも相手には批判や命令のように聞こえてしまう。\n译：如果发言意图没有传达到，同样的话在对方听来就可能像批评或命令。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0218","seq":218,"level":"N1","type":"主词条","word":"異動","kana":"いどう","pos":"[名·自動3]","accent":"⓪","meaning":"变动，调动","example":"突然の異動で不安もあったが、彼は新しい部署で学べることを前向きに考えるようにした。","exampleZh":"突然调动让他也有些不安，但他开始积极思考在新部门能够学到什么。","note":"例：\n突然の異動で不安もあったが、彼は新しい部署で学べることを前向きに考えるようにした。\n译：突然调动让他也有些不安，但他开始积极思考在新部门能够学到什么。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0219","seq":219,"level":"N1","type":"主词条","word":"愛しい","kana":"いとしい","pos":"[イ形]","accent":"③","meaning":"可怜的；可爱的","example":"愛しい表情を見せる子どもに、緊張していた参加者たちの表情も自然と和らいだ。","exampleZh":"孩子露出惹人怜爱的表情，原本紧张的参加者们神情也自然柔和下来。","note":"例：\n愛しい表情を見せる子どもに、緊張していた参加者たちの表情も自然と和らいだ。\n译：孩子露出惹人怜爱的表情，原本紧张的参加者们神情也自然柔和下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0220","seq":220,"level":"N1","type":"主词条","word":"営む","kana":"いとなむ","pos":"[他動1]","accent":"③","meaning":"营（生）；经营（事业）；打（巢等）","example":"営むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“营；经营”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n営むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“营；经营”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0221","seq":221,"level":"N1","type":"主词条","word":"挑む","kana":"いどむ","pos":"[自他動1]","accent":"②","meaning":"挑衅，挑战","example":"相手に何かを挑むなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“挑衅，挑战”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを挑むなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“挑衅，挑战”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0222","seq":222,"level":"N1","type":"主词条","word":"稲光","kana":"いなびかり","pos":"[名]","accent":"③","meaning":"闪电","example":"突然の稲光で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“闪电”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の稲光で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“闪电”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0223","seq":223,"level":"N1","type":"主词条","word":"否めない","kana":"いなめない","pos":"[イ形]","accent":"③","meaning":"不可否认","example":"否めない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“不可否认”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n否めない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“不可否认”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0224","seq":224,"level":"N1","type":"主词条","word":"居残る","kana":"いのこる","pos":"[自動1]","accent":"③","meaning":"不走，留下加班","example":"自分の道を居残るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“不走，留下加班”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を居残るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“不走，留下加班”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0225","seq":225,"level":"N1","type":"主词条","word":"命取り","kana":"いのちとり","pos":"[名]","accent":"③⑤","meaning":"致命伤","example":"小さな命取りを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“致命伤”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな命取りを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“致命伤”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0226","seq":226,"level":"N1","type":"主词条","word":"イベント","kana":"いべんと (event)","pos":"[名]","accent":"⓪","meaning":"活动，节目","example":"イベントを受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“活动，节目”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\nイベントを受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“活动，节目”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0227","seq":227,"level":"N1","type":"主词条","word":"今更","kana":"いまさら","pos":"[副]","accent":"⓪①","meaning":"事到如今","example":"今更責任を押しつけ合っても仕方がないので、まずは利用者への影響を最小限に抑えるべきだ。","exampleZh":"事到如今再互相推卸责任也没有意义，首先应该把对使用者的影响压到最低。","note":"例：\n今更責任を押しつけ合っても仕方がないので、まずは利用者への影響を最小限に抑えるべきだ。\n译：事到如今再互相推卸责任也没有意义，首先应该把对使用者的影响压到最低。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0228","seq":228,"level":"N1","type":"主词条","word":"戒める","kana":"いましめる","pos":"[他動2]","accent":"④⓪","meaning":"训诫，教训；惩戒","example":"無理に戒めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“训诫，教训；惩戒”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に戒めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“训诫，教训；惩戒”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0229","seq":229,"level":"N1","type":"主词条","word":"いましも","kana":"いましも","pos":"[副]","accent":"①","meaning":"正是现在","example":"いましも会議が始まろうとしていたとき、担当者の携帯に重要な訂正の連絡が入った。","exampleZh":"正当会议就要开始时，负责人的手机收到了重要更正的联络。","note":"例：\nいましも会議が始まろうとしていたとき、担当者の携帯に重要な訂正の連絡が入った。\n译：正当会议就要开始时，负责人的手机收到了重要更正的联络。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0230","seq":230,"level":"N1","type":"主词条","word":"未だ","kana":"いまだ","pos":"[副]","accent":"⓪①","meaning":"（后多接否定）尚（未）","example":"事故の詳しい原因は未だ明らかになっておらず、調査委員会は関係者への聞き取りを続けている。","exampleZh":"事故的详细原因尚未查明，调查委员会仍在继续听取相关人员的情况。","note":"例：\n事故の詳しい原因は未だ明らかになっておらず、調査委員会は関係者への聞き取りを続けている。\n译：事故的详细原因尚未查明，调查委员会仍在继续听取相关人员的情况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0231","seq":231,"level":"N1","type":"主词条","word":"未だに","kana":"いまだに","pos":"[副]","accent":"⓪","meaning":"（后多接否定）至今仍然（未）","example":"十年前の小さな約束を彼が未だに覚えていたことに、彼女は驚きながらも深く感謝した。","exampleZh":"他至今还记得十年前那个小小的约定，这让她惊讶之余也深深感激。","note":"例：\n十年前の小さな約束を彼が未だに覚えていたことに、彼女は驚きながらも深く感謝した。\n译：他至今还记得十年前那个小小的约定，这让她惊讶之余也深深感激。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0232","seq":232,"level":"N1","type":"主词条","word":"今時","kana":"いまどき","pos":"[名]","accent":"⓪","meaning":"现如今，现在","example":"今時の若者という一言で片づけず、彼は世代ごとの価値観や働き方の違いを丁寧に聞き取った。","exampleZh":"他没有用一句“现在的年轻人”简单概括，而是细致询问各世代价值观和工作方式的差异。","note":"例：\n今時の若者という一言で片づけず、彼は世代ごとの価値観や働き方の違いを丁寧に聞き取った。\n译：他没有用一句“现在的年轻人”简单概括，而是细致询问各世代价值观和工作方式的差异。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0233","seq":233,"level":"N1","type":"主词条","word":"今にして","kana":"いまにして","pos":"[連語]","accent":"①","meaning":"现在，如今","example":"今にして思えば、あのとき反対意見を聞いておいたことが後の失敗を防いだのだと思う。","exampleZh":"现在回想起来，我觉得当时听取反对意见，才防止了后来的失败。","note":"例：\n今にして思えば、あのとき反対意見を聞いておいたことが後の失敗を防いだのだと思う。\n译：现在回想起来，我觉得当时听取反对意见，才防止了后来的失败。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0234","seq":234,"level":"N1","type":"主词条","word":"今や","kana":"いまや","pos":"[副]","accent":"①","meaning":"如今，现在正是","example":"この小さな技術は、今や医療や交通の分野でも欠かせない仕組みとして広く使われている。","exampleZh":"这项小技术如今已作为医疗和交通领域不可或缺的机制被广泛使用。","note":"例：\nこの小さな技術は、今や医療や交通の分野でも欠かせない仕組みとして広く使われている。\n译：这项小技术如今已作为医疗和交通领域不可或缺的机制被广泛使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0235","seq":235,"level":"N1","type":"主词条","word":"いやいや","kana":"いやいや","pos":"[副]","accent":"⓪①","meaning":"不情愿，勉强","example":"彼はいやいや引き受けた仕事だったが、現場を知るうちにその重要性を少しずつ理解していった。","exampleZh":"那份工作是他勉强接下的，但在了解现场的过程中，他逐渐理解了它的重要性。","note":"例：\n彼はいやいや引き受けた仕事だったが、現場を知るうちにその重要性を少しずつ理解していった。\n译：那份工作是他勉强接下的，但在了解现场的过程中，他逐渐理解了它的重要性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0236","seq":236,"level":"N1","type":"主词条","word":"嫌がらせ","kana":"いやがらせ","pos":"[名]","accent":"⓪","meaning":"故意讨人嫌","example":"匿名の嫌がらせが続いたため、彼女は証拠を保存し、学校と警察に相談した。","exampleZh":"匿名骚扰持续发生，她于是保存证据，并向学校和警方咨询。","note":"例：\n匿名の嫌がらせが続いたため、彼女は証拠を保存し、学校と警察に相談した。\n译：匿名骚扰持续发生，她于是保存证据，并向学校和警方咨询。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0237","seq":237,"level":"N1","type":"主词条","word":"嫌気","kana":"いやけ","pos":"[名]","accent":"⓪③","meaning":"讨厌，厌烦","example":"同じミスの繰り返しに嫌気が差した彼は、感情をぶつける代わりに手順書を作り直した。","exampleZh":"对同样错误一再发生感到厌烦后，他没有发泄情绪，而是重新制作了操作手册。","note":"例：\n同じミスの繰り返しに嫌気が差した彼は、感情をぶつける代わりに手順書を作り直した。\n译：对同样错误一再发生感到厌烦后，他没有发泄情绪，而是重新制作了操作手册。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0238","seq":238,"level":"N1","type":"主词条","word":"卑しい","kana":"いやしい","pos":"[イ形]","accent":"③⓪","meaning":"卑贱的，低贱的；贪婪的；寒酸的","example":"卑しいと感じた時点で無理を続けず、彼は予定を調整して早めに休むことにした。","exampleZh":"在感到自己状态低落难堪时，他没有继续勉强，而是调整日程，决定早点休息。","note":"例：\n卑しいと感じた時点で無理を続けず、彼は予定を調整して早めに休むことにした。\n译：在感到自己状态低落难堪时，他没有继续勉强，而是调整日程，决定早点休息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0239","seq":239,"level":"N1","type":"主词条","word":"癒す","kana":"いやす","pos":"[他動1]","accent":"②","meaning":"医治；解除（疲劳、痛苦等）","example":"無理に癒すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“医治；解除”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に癒すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“医治；解除”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0240","seq":240,"level":"N1","type":"主词条","word":"いやに","kana":"いやに","pos":"[副]","accent":"②","meaning":"特别，异常","example":"今日は駅前がいやに静かで、いつもなら聞こえる店員の声もほとんど聞こえなかった。","exampleZh":"今天车站前异常安静，平时能听到的店员声音也几乎听不见。","note":"例：\n今日は駅前がいやに静かで、いつもなら聞こえる店員の声もほとんど聞こえなかった。\n译：今天车站前异常安静，平时能听到的店员声音也几乎听不见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0241","seq":241,"level":"N1","type":"主词条","word":"嫌味","kana":"いやみ","pos":"[名·ナ形]","accent":"③⓪","meaning":"令人不快的（言谈、态度），挖苦（的话）","example":"上司の嫌味な言い方に腹が立ったが、彼は感情的に反論せず、必要な点だけを冷静に確認した。","exampleZh":"上司挖苦的说法让他很生气，但他没有情绪化反驳，只冷静确认了必要事项。","note":"例：\n上司の嫌味な言い方に腹が立ったが、彼は感情的に反論せず、必要な点だけを冷静に確認した。\n译：上司挖苦的说法让他很生气，但他没有情绪化反驳，只冷静确认了必要事项。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0242","seq":242,"level":"N1","type":"主词条","word":"嫌らしい","kana":"いやらしい","pos":"[イ形]","accent":"④","meaning":"讨厌的，让人不舒服的","example":"嫌らしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“讨厌的，让人不舒服的”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n嫌らしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“讨厌的，让人不舒服的”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0243","seq":243,"level":"N1","type":"主词条","word":"意欲","kana":"いよく","pos":"[名]","accent":"①","meaning":"热情，积极性","example":"新しい仕事への意欲を失わないよう、彼は小さな成果でも記録し、自分の成長を確かめている。","exampleZh":"为了不失去对新工作的热情，他哪怕是小小成果也会记录下来，确认自己的成长。","note":"例：\n新しい仕事への意欲を失わないよう、彼は小さな成果でも記録し、自分の成長を確かめている。\n译：为了不失去对新工作的热情，他哪怕是小小成果也会记录下来，确认自己的成长。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0244","seq":244,"level":"N1","type":"主词条","word":"イラスト","kana":"いらすと","pos":"[名]","accent":"⓪","meaning":"插图","example":"文章だけでは伝わりにくい手順も、イラストを添えることで初めての人に理解しやすくなる。","exampleZh":"单靠文字难以传达的步骤，只要配上插图，就会让初次接触的人更容易理解。","note":"例：\n文章だけでは伝わりにくい手順も、イラストを添えることで初めての人に理解しやすくなる。\n译：单靠文字难以传达的步骤，只要配上插图，就会让初次接触的人更容易理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0245","seq":245,"level":"N1","type":"主词条","word":"入り","kana":"いり","pos":"[名]","accent":"⓪","meaning":"收入，进项；入场人数","example":"週末の映画館は客の入りがよく、支配人は追加上映を急いで検討した。","exampleZh":"周末电影院入场人数很多，经理急忙研究追加放映。","note":"例：\n週末の映画館は客の入りがよく、支配人は追加上映を急いで検討した。\n译：周末电影院入场人数很多，经理急忙研究追加放映。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0246","seq":246,"level":"N1","type":"主词条","word":"慰留","kana":"いりゅう","pos":"[名·他動3]","accent":"⓪","meaning":"挽留","example":"会社は退職を決めた技術者を慰留したが、本人が抱えていた不満を十分に聞けていなかった。","exampleZh":"公司挽留了决定辞职的技术人员，但并没有充分听取本人所抱有的不满。","note":"例：\n会社は退職を決めた技術者を慰留したが、本人が抱えていた不満を十分に聞けていなかった。\n译：公司挽留了决定辞职的技术人员，但并没有充分听取本人所抱有的不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0247","seq":247,"level":"N1","type":"主词条","word":"入り用","kana":"いりよう","pos":"[名·ナ形]","accent":"⓪","meaning":"必要的，需要的","example":"入り用な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“必要的，需要的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n入り用な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“必要的，需要的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0248","seq":248,"level":"N1","type":"主词条","word":"居留守","kana":"いるす","pos":"[名]","accent":"⓪②","meaning":"假装不在家","example":"借金の催促を避けるために居留守を使っても、問題の解決を先延ばしにするだけだった。","exampleZh":"为了躲避催债而假装不在家，也只是把问题的解决继续往后拖。","note":"例：\n借金の催促を避けるために居留守を使っても、問題の解決を先延ばしにするだけだった。\n译：为了躲避催债而假装不在家，也只是把问题的解决继续往后拖。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0249","seq":249,"level":"N1","type":"主词条","word":"色合い","kana":"いろあい","pos":"[名]","accent":"⓪","meaning":"色调，色彩","example":"その作品では色合いが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。","exampleZh":"那部作品中“色调，色彩”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","note":"例：\nその作品では色合いが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。\n译：那部作品中“色调，色彩”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0250","seq":250,"level":"N1","type":"主词条","word":"色直し","kana":"いろなおし","pos":"[名·自動3]","accent":"③","meaning":"婚礼上换衣服","example":"披露宴の色直しの間、司会者は二人の学生時代の思い出を紹介して会場を和ませた。","exampleZh":"婚宴换装期间，主持人介绍了两人学生时代的回忆，使会场气氛缓和下来。","note":"例：\n披露宴の色直しの間、司会者は二人の学生時代の思い出を紹介して会場を和ませた。\n译：婚宴换装期间，主持人介绍了两人学生时代的回忆，使会场气氛缓和下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0251","seq":251,"level":"N1","type":"主词条","word":"異論","kana":"いろん","pos":"[名]","accent":"⓪","meaning":"异议","example":"異論の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“异议”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n異論の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“异议”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0252","seq":252,"level":"N1","type":"主词条","word":"違和感","kana":"いわかん","pos":"[名]","accent":"②","meaning":"不协调的感觉，异样的感觉","example":"違和感を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。","exampleZh":"如果重视“不协调的感觉，异样的感觉”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","note":"例：\n違和感を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。\n译：如果重视“不协调的感觉，异样的感觉”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0253","seq":253,"level":"N1","type":"主词条","word":"陰気","kana":"いんき","pos":"[名·ナ形]","accent":"⓪","meaning":"阴暗，阴郁","example":"陰気な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“阴暗，阴郁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n陰気な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“阴暗，阴郁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0254","seq":254,"level":"N1","type":"主词条","word":"陰湿","kana":"いんしつ","pos":"[名·ナ形]","accent":"⓪","meaning":"阴暗潮湿；阴毒","example":"周囲から陰湿だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“阴暗潮湿；阴毒”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から陰湿だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“阴暗潮湿；阴毒”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0255","seq":255,"level":"N1","type":"主词条","word":"インスピレーション","kana":"いんすぴれーしょん (inspiration)","pos":"[名]","accent":"⑤","meaning":"灵感","example":"その作品ではインスピレーションが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。","exampleZh":"那部作品中“灵感”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","note":"例：\nその作品ではインスピレーションが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。\n译：那部作品中“灵感”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0256","seq":256,"level":"N1","type":"主词条","word":"インターチェンジ","kana":"いんたーちぇんじ (interchange)","pos":"[名]","accent":"⑤","meaning":"立交桥，高速公路出入口","example":"新しいインターチェンジができたことで物流は便利になったが、周辺道路の渋滞対策も急務となった。","exampleZh":"新的高速公路出入口建成后，物流变得便利，但周边道路的拥堵对策也成了当务之急。","note":"例：\n新しいインターチェンジができたことで物流は便利になったが、周辺道路の渋滞対策も急務となった。\n译：新的高速公路出入口建成后，物流变得便利，但周边道路的拥堵对策也成了当务之急。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0257","seq":257,"level":"N1","type":"主词条","word":"インターフォン","kana":"いんたーふぉん (interphone)","pos":"[名]","accent":"③","meaning":"对讲机","example":"インターフォンの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“对讲机”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\nインターフォンの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“对讲机”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0258","seq":258,"level":"N1","type":"主词条","word":"インテリ","kana":"いんてり","pos":"[名]","accent":"⓪","meaning":"知识分子","example":"インテリぶった言い方を避け、彼は難しい理論を現場の人にも分かる言葉で伝えた。","exampleZh":"他避免装作知识分子的说话方式，而是用现场人员也能理解的语言传达复杂理论。","note":"例：\nインテリぶった言い方を避け、彼は難しい理論を現場の人にも分かる言葉で伝えた。\n译：他避免装作知识分子的说话方式，而是用现场人员也能理解的语言传达复杂理论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0259","seq":259,"level":"N1","type":"主词条","word":"インフォメーション","kana":"いんふぉめーしょん (information)","pos":"[名]","accent":"④","meaning":"情报，信息","example":"会場のインフォメーションを確認せずに歩き回ったため、彼は受付の場所を見つけるまで時間がかかった。","exampleZh":"没有确认会场信息就到处走，他花了很长时间才找到接待处的位置。","note":"例：\n会場のインフォメーションを確認せずに歩き回ったため、彼は受付の場所を見つけるまで時間がかかった。\n译：没有确认会场信息就到处走，他花了很长时间才找到接待处的位置。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0260","seq":260,"level":"N1","type":"主词条","word":"インフレ","kana":"いんふれ","pos":"[名]","accent":"⓪","meaning":"通货膨胀","example":"新規事業ではインフレの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“通货膨胀”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業ではインフレの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“通货膨胀”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0261","seq":261,"level":"N1","type":"主词条","word":"隠蔽","kana":"いんぺい","pos":"[名·他動3]","accent":"⓪","meaning":"掩盖","example":"事故の原因を隠蔽しようとした結果、会社は被害そのものよりも深刻な信用の失墜に直面した。","exampleZh":"试图掩盖事故原因的结果是，公司面对的信用崩塌比损害本身更严重。","note":"例：\n事故の原因を隠蔽しようとした結果、会社は被害そのものよりも深刻な信用の失墜に直面した。\n译：试图掩盖事故原因的结果是，公司面对的信用崩塌比损害本身更严重。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0262","seq":262,"level":"N1","type":"主词条","word":"飲用","kana":"いんよう","pos":"[名·他動3]","accent":"⓪","meaning":"饮用","example":"井戸水を飲用に使う前に、自治体は水質検査を行い、安全性を確認した。","exampleZh":"在把井水用于饮用之前，地方政府进行了水质检查，确认了安全性。","note":"例：\n井戸水を飲用に使う前に、自治体は水質検査を行い、安全性を確認した。\n译：在把井水用于饮用之前，地方政府进行了水质检查，确认了安全性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0263","seq":263,"level":"N1","type":"主词条","word":"ウィークデー","kana":"うぃーくでー (weekday)","pos":"[名]","accent":"④②","meaning":"工作日，平日","example":"ウィークデーの昼間は来店客が少ないため、店主は高齢者向けの割引サービスを始めた。","exampleZh":"工作日白天来店顾客较少，因此店主开始提供面向老年人的折扣服务。","note":"例：\nウィークデーの昼間は来店客が少ないため、店主は高齢者向けの割引サービスを始めた。\n译：工作日白天来店顾客较少，因此店主开始提供面向老年人的折扣服务。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0264","seq":264,"level":"N1","type":"主词条","word":"ウィット","kana":"うぃっと (wit)","pos":"[名]","accent":"②","meaning":"机智；妙语","example":"ウィットの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“机智；妙语”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\nウィットの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“机智；妙语”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0265","seq":265,"level":"N1","type":"主词条","word":"ウイルス","kana":"ういるす (virus)","pos":"[名]","accent":"②①","meaning":"病毒","example":"過労が続くとウイルスに小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。","exampleZh":"过劳持续后，“病毒”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","note":"例：\n過労が続くとウイルスに小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。\n译：过劳持续后，“病毒”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0266","seq":266,"level":"N1","type":"主词条","word":"ウエット","kana":"うえっと (wet)","pos":"[ナ形]","accent":"②","meaning":"有人情味的，多愁善感的","example":"ウエットな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“有人情味的，多愁善感的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nウエットな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“有人情味的，多愁善感的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0267","seq":267,"level":"N1","type":"主词条","word":"迂回","kana":"うかい","pos":"[名·自動3]","accent":"⓪","meaning":"绕远路","example":"事故で幹線道路が通れなくなったため、運転手は細い山道を迂回して目的地へ向かった。","exampleZh":"由于事故导致主干道无法通行，司机绕行狭窄山路前往目的地。","note":"例：\n事故で幹線道路が通れなくなったため、運転手は細い山道を迂回して目的地へ向かった。\n译：由于事故导致主干道无法通行，司机绕行狭窄山路前往目的地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0268","seq":268,"level":"N1","type":"主词条","word":"迂闊","kana":"うかつ","pos":"[名·ナ形]","accent":"⓪","meaning":"愚蠢；马虎，大意","example":"迂闊な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“愚蠢；马虎，大意”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n迂闊な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“愚蠢；马虎，大意”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0269","seq":269,"level":"N1","type":"主词条","word":"うきうき","kana":"うきうき","pos":"[副·自動3]","accent":"①","meaning":"高兴，兴奋","example":"旅行の前日、彼女はうきうきして眠れなかったが、忘れ物がないよう荷物を何度も確認した。","exampleZh":"旅行前一天，她兴奋得睡不着，但仍反复确认行李，避免遗漏东西。","note":"例：\n旅行の前日、彼女はうきうきして眠れなかったが、忘れ物がないよう荷物を何度も確認した。\n译：旅行前一天，她兴奋得睡不着，但仍反复确认行李，避免遗漏东西。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0270","seq":270,"level":"N1","type":"主词条","word":"請け合う","kana":"うけあう","pos":"[他動1]","accent":"③","meaning":"承担，负责；保证","example":"請け合う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“承担，负责；保证”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n請け合う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“承担，负责；保证”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0271","seq":271,"level":"N1","type":"主词条","word":"受け入れる","kana":"うけいれる","pos":"[他動2]","accent":"④⓪","meaning":"接纳，接受","example":"無理に受け入れるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“接纳，接受”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に受け入れるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“接纳，接受”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0272","seq":272,"level":"N1","type":"主词条","word":"請け負う","kana":"うけおう","pos":"[他動1]","accent":"③","meaning":"承担责任，承包（工程等）","example":"無理に請け負うよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“承担责任，承包”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に請け負うよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“承担责任，承包”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0273","seq":273,"level":"N1","type":"主词条","word":"受け継ぐ","kana":"うけつぐ","pos":"[他動1]","accent":"⓪③","meaning":"继承，传承","example":"受け継ぐことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“继承，传承”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n受け継ぐことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“继承，传承”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0274","seq":274,"level":"N1","type":"主词条","word":"受け止める","kana":"うけとめる","pos":"[他動2]","accent":"④⓪","meaning":"接住；理解","example":"受け止める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“接住；理解”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n受け止める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“接住；理解”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0275","seq":275,"level":"N1","type":"主词条","word":"受け身","kana":"うけみ","pos":"[名]","accent":"⓪③②","meaning":"被动，消极","example":"受け身な態度を取り続ければ、正しい意見を述べていても周囲の協力は得にくくなる。","exampleZh":"如果一直采取被动态度，即使提出正确意见，也很难得到周围人的协作。","note":"例：\n受け身な態度を取り続ければ、正しい意見を述べていても周囲の協力は得にくくなる。\n译：如果一直采取被动态度，即使提出正确意见，也很难得到周围人的协作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0276","seq":276,"level":"N1","type":"主词条","word":"受ける","kana":"うける","pos":"[自他動2]","accent":"②","meaning":"接受；受欢迎","example":"受ける場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“接受；受欢迎”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n受ける場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“接受；受欢迎”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0277","seq":277,"level":"N1","type":"主词条","word":"後ろ盾","kana":"うしろだて","pos":"[名]","accent":"⓪","meaning":"后盾，靠山","example":"研究者は後ろ盾の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“后盾，靠山”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は後ろ盾の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“后盾，靠山”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0278","seq":278,"level":"N1","type":"主词条","word":"後ろ向き","kana":"うしろむき","pos":"[名·ナ形]","accent":"⓪","meaning":"背对着；消极","example":"後ろ向きな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“背对着；消极”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n後ろ向きな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“背对着；消极”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0279","seq":279,"level":"N1","type":"主词条","word":"後ろめたい","kana":"うしろめたい","pos":"[イ形]","accent":"⑤","meaning":"内疚","example":"後ろめたいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“内疚”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n後ろめたいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“内疚”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0280","seq":280,"level":"N1","type":"主词条","word":"埋める","kana":"うずめる","pos":"[他動2]","accent":"⓪","meaning":"埋，掩埋；挤满","example":"無理に埋めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“埋，掩埋；挤满”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に埋めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“埋，掩埋；挤满”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0281","seq":281,"level":"N1","type":"主词条","word":"右折","kana":"うせつ","pos":"[名·自動3]","accent":"⓪","meaning":"右转弯","example":"交通量の多い交差点で右折する際には、対向車だけでなく横断歩道の歩行者にも注意が必要だ。","exampleZh":"在交通量大的十字路口右转时，不仅要注意对向车辆，也要注意人行横道上的行人。","note":"例：\n交通量の多い交差点で右折する際には、対向車だけでなく横断歩道の歩行者にも注意が必要だ。\n译：在交通量大的十字路口右转时，不仅要注意对向车辆，也要注意人行横道上的行人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0282","seq":282,"level":"N1","type":"主词条","word":"疑わしい","kana":"うたがわしい","pos":"[イ形]","accent":"⑤①","meaning":"可疑","example":"疑わしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“可疑”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n疑わしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“可疑”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0283","seq":283,"level":"N1","type":"主词条","word":"転寝","kana":"うたたね","pos":"[名·自動3]","accent":"⓪","meaning":"打盹儿，打瞌睡","example":"電車で転寝してしまった彼は、乗り過ごす寸前に目を覚まし、慌てて駅で降りた。","exampleZh":"在电车上打盹的他，差一点坐过站时醒来，慌忙在车站下了车。","note":"例：\n電車で転寝してしまった彼は、乗り過ごす寸前に目を覚まし、慌てて駅で降りた。\n译：在电车上打盹的他，差一点坐过站时醒来，慌忙在车站下了车。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0284","seq":284,"level":"N1","type":"主词条","word":"打ち上げ","kana":"うちあげ","pos":"[名]","accent":"⓪","meaning":"放（烟花等）；结束，终了","example":"打ち上げが進むにつれて、当初は小さく見えた不安が関係者全体の課題として共有されるようになった。","exampleZh":"随着庆功会推进，起初看似很小的不安逐渐成为相关人员共同面对的课题。","note":"例：\n打ち上げが進むにつれて、当初は小さく見えた不安が関係者全体の課題として共有されるようになった。\n译：随着庆功会推进，起初看似很小的不安逐渐成为相关人员共同面对的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0285","seq":285,"level":"N1","type":"主词条","word":"打ち明ける","kana":"うちあける","pos":"[他動2]","accent":"⓪④","meaning":"如实说出","example":"事実を打ち明ける前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“如实说出”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を打ち明ける前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“如实说出”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0286","seq":286,"level":"N1","type":"主词条","word":"内気","kana":"うちき","pos":"[名·ナ形]","accent":"⓪","meaning":"内向，腼腆","example":"一度内気だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“内向，腼腆”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度内気だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“内向，腼腆”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0287","seq":287,"level":"N1","type":"主词条","word":"打ち切る","kana":"うちきる","pos":"[他動1]","accent":"③⓪","meaning":"（中途）停止","example":"無理に打ち切るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“停止”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に打ち切るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“停止”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0288","seq":288,"level":"N1","type":"主词条","word":"打ち消し","kana":"うちけし","pos":"[名]","accent":"⓪","meaning":"否定，否认","example":"彼はうわさの打ち消しに追われるより、正確な情報を先に公開するべきだと判断した。","exampleZh":"与其忙着否认传闻，他判断应该先公开准确的信息。","note":"例：\n彼はうわさの打ち消しに追われるより、正確な情報を先に公開するべきだと判断した。\n译：与其忙着否认传闻，他判断应该先公开准确的信息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0289","seq":289,"level":"N1","type":"主词条","word":"打ち込む","kana":"うちこむ","pos":"[自他動1]","accent":"③⓪","meaning":"打进；埋头，专心致志","example":"無理に打ち込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“打进；埋头，专心致志”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に打ち込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“打进；埋头，专心致志”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0290","seq":290,"level":"N1","type":"主词条","word":"打ち解ける","kana":"うちとける","pos":"[自動2]","accent":"⓪④","meaning":"亲密，融洽","example":"初対面の相手とも少しずつ打ち解けるよう、彼女は共通の話題を探しながら会話を続けた。","exampleZh":"为了和初次见面的人也逐渐熟络起来，她一边寻找共同话题一边继续交谈。","note":"例：\n初対面の相手とも少しずつ打ち解けるよう、彼女は共通の話題を探しながら会話を続けた。\n译：为了和初次见面的人也逐渐熟络起来，她一边寻找共同话题一边继续交谈。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0291","seq":291,"level":"N1","type":"主词条","word":"内幕","kana":"うちまく","pos":"[名]","accent":"⓪","meaning":"内幕，内情","example":"業界の内幕を知るにつれて、華やかな広告の裏で多くの人が厳しい条件で働いていることが分かった。","exampleZh":"随着了解行业内幕，才知道华丽广告背后有许多人在严苛条件下工作。","note":"例：\n業界の内幕を知るにつれて、華やかな広告の裏で多くの人が厳しい条件で働いていることが分かった。\n译：随着了解行业内幕，才知道华丽广告背后有许多人在严苛条件下工作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0292","seq":292,"level":"N1","type":"主词条","word":"打ち破る","kana":"うちやぶる","pos":"[他動1]","accent":"④⓪","meaning":"打破；打败","example":"既存の評価を打ち破るには、勢いだけでなく、誰もが納得できる根拠と結果が必要だ。","exampleZh":"要打破既有评价，不能只靠气势，还需要人人都能接受的依据和结果。","note":"例：\n既存の評価を打ち破るには、勢いだけでなく、誰もが納得できる根拠と結果が必要だ。\n译：要打破既有评价，不能只靠气势，还需要人人都能接受的依据和结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0293","seq":293,"level":"N1","type":"主词条","word":"内訳","kana":"うちわけ","pos":"[名]","accent":"⓪","meaning":"明细，细目","example":"内訳の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“明细，细目”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n内訳の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“明细，细目”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0294","seq":294,"level":"N1","type":"主词条","word":"うっとうしい","kana":"うっとうしい","pos":"[イ形]","accent":"⑤","meaning":"阴沉，郁闷；嫌烦","example":"うっとうしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“阴沉，郁闷；嫌烦”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\nうっとうしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“阴沉，郁闷；嫌烦”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0295","seq":295,"level":"N1","type":"主词条","word":"うつ病","kana":"うつびょう","pos":"[名]","accent":"⓪","meaning":"抑郁症","example":"うつ病は気の持ちようだけで治るものではなく、休養と専門的な支援が必要になることが多い。","exampleZh":"抑郁症并不是只靠心态就能治好的，很多时候需要休养和专业支持。","note":"例：\nうつ病は気の持ちようだけで治るものではなく、休養と専門的な支援が必要になることが多い。\n译：抑郁症并不是只靠心态就能治好的，很多时候需要休养和专业支持。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0296","seq":296,"level":"N1","type":"主词条","word":"うつ伏せ","kana":"うつぶせ","pos":"[名]","accent":"⓪","meaning":"脸朝下或东西倒扣","example":"医師はうつ伏せの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“脸朝下或东西倒扣”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師はうつ伏せの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“脸朝下或东西倒扣”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0297","seq":297,"level":"N1","type":"主词条","word":"俯く","kana":"うつむく","pos":"[自動1]","accent":"③⓪","meaning":"低头，脸朝下","example":"失敗を責められて俯く部下に、上司は原因を一緒に考えようと声をかけた。","exampleZh":"面对因被责备失败而低头的部下，上司开口说要一起思考原因。","note":"例：\n失敗を責められて俯く部下に、上司は原因を一緒に考えようと声をかけた。\n译：面对因被责备失败而低头的部下，上司开口说要一起思考原因。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0298","seq":298,"level":"N1","type":"主词条","word":"移り変わり","kana":"うつりかわり","pos":"[名]","accent":"⓪","meaning":"推移，变迁","example":"移り変わりが進むにつれて、当初は小さく見えた不安が関係者全体の課題として共有されるようになった。","exampleZh":"随着变迁不断推进，起初看似很小的不安逐渐被相关人员整体作为课题共享。","note":"例：\n移り変わりが進むにつれて、当初は小さく見えた不安が関係者全体の課題として共有されるようになった。\n译：随着变迁不断推进，起初看似很小的不安逐渐被相关人员整体作为课题共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0299","seq":299,"level":"N1","type":"主词条","word":"空ろ","kana":"うつろ","pos":"[ナ形]","accent":"⓪","meaning":"空洞；空虚","example":"周囲から空ろだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“空洞；空虚”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から空ろだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“空洞；空虚”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0300","seq":300,"level":"N1","type":"主词条","word":"器","kana":"うつわ","pos":"[名]","accent":"⓪","meaning":"容器；（与某项工作或地位相称的）才能，材料","example":"リーダーの器があるかどうかは、順調なときよりも問題が起きたときの態度に表れる。","exampleZh":"是否具备领导者的器量，比起顺利时，更会体现在出现问题时的态度上。","note":"例：\nリーダーの器があるかどうかは、順調なときよりも問題が起きたときの態度に表れる。\n译：是否具备领导者的器量，比起顺利时，更会体现在出现问题时的态度上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0301","seq":301,"level":"N1","type":"主词条","word":"腕前","kana":"うでまえ","pos":"[名]","accent":"⓪③","meaning":"本领，才能","example":"腕前を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“本领，才能”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\n腕前を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“本领，才能”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0302","seq":302,"level":"N1","type":"主词条","word":"疎い","kana":"うとい","pos":"[イ形]","accent":"②","meaning":"不太了解，不熟悉","example":"疎いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“不太了解，不熟悉”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n疎いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“不太了解，不熟悉”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0303","seq":303,"level":"N1","type":"主词条","word":"促す","kana":"うながす","pos":"[他動1]","accent":"③⓪","meaning":"催促；促进","example":"相手の成長を促すには、結果を急かすだけでなく、自分で考える余白を残す必要がある。","exampleZh":"要促进对方成长，不能只催促结果，也需要留下让其自己思考的余地。","note":"例：\n相手の成長を促すには、結果を急かすだけでなく、自分で考える余白を残す必要がある。\n译：要促进对方成长，不能只催促结果，也需要留下让其自己思考的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0304","seq":304,"level":"N1","type":"主词条","word":"うぬぼれる","kana":"うぬぼれる","pos":"[自動2]","accent":"⓪④","meaning":"自负，骄傲自大","example":"少し成果が出たからといってうぬぼれると、周囲の助言を聞けなくなり成長が止まってしまう。","exampleZh":"只因为稍微有了成果就自负起来，就会听不进周围建议，成长也会停止。","note":"例：\n少し成果が出たからといってうぬぼれると、周囲の助言を聞けなくなり成長が止まってしまう。\n译：只因为稍微有了成果就自负起来，就会听不进周围建议，成长也会停止。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0305","seq":305,"level":"N1","type":"主词条","word":"鵜呑み","kana":"うのみ","pos":"[名]","accent":"③⓪","meaning":"囫囵吞枣","example":"鵜呑みが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“囫囵吞枣”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n鵜呑みが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“囫囵吞枣”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0306","seq":306,"level":"N1","type":"主词条","word":"生まれつき","kana":"うまれつき","pos":"[名·副]","accent":"⓪","meaning":"天生","example":"彼は生まれつき耳がよく、小さな音の違いから機械の不調まで聞き分けることができる。","exampleZh":"他天生听力敏锐，能从细小声音差异中分辨出机器故障。","note":"例：\n彼は生まれつき耳がよく、小さな音の違いから機械の不調まで聞き分けることができる。\n译：他天生听力敏锐，能从细小声音差异中分辨出机器故障。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0307","seq":307,"level":"N1","type":"主词条","word":"埋め込む","kana":"うめこむ","pos":"[他動1]","accent":"③","meaning":"埋入，埋进","example":"無理に埋め込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“埋入，埋进”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に埋め込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“埋入，埋进”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0308","seq":308,"level":"N1","type":"主词条","word":"埋め立てる","kana":"うめたてる","pos":"[他動2]","accent":"④","meaning":"填河、湖、海等造地","example":"相手に何かを埋め立てるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“填河，湖，海等造地”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを埋め立てるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“填河，湖，海等造地”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0309","seq":309,"level":"N1","type":"主词条","word":"梅干","kana":"うめぼし","pos":"[名]","accent":"⓪","meaning":"梅干","example":"祖母は弁当に梅干を一つ入れ、暑い日でも食欲が落ちないよう小さな工夫を欠かさなかった。","exampleZh":"祖母会在便当里放一颗梅干，即使在炎热日子也不忘这种防止食欲下降的小用心。","note":"例：\n祖母は弁当に梅干を一つ入れ、暑い日でも食欲が落ちないよう小さな工夫を欠かさなかった。\n译：祖母会在便当里放一颗梅干，即使在炎热日子也不忘这种防止食欲下降的小用心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0310","seq":310,"level":"N1","type":"主词条","word":"恭しい","kana":"うやうやしい","pos":"[イ形]","accent":"⑤","meaning":"毕恭毕敬的","example":"恭しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“毕恭毕敬的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n恭しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“毕恭毕敬的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0311","seq":311,"level":"N1","type":"主词条","word":"紆余曲折","kana":"うよきょくせつ","pos":"[名·自動3]","accent":"①","meaning":"弯曲；周折","example":"紆余曲折するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“弯曲；周折”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n紆余曲折するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“弯曲；周折”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0312","seq":312,"level":"N1","type":"主词条","word":"裏返し","kana":"うらがえし","pos":"[名]","accent":"③","meaning":"翻过来；反证，写照","example":"裏返しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“翻过来；反证，写照”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n裏返しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“翻过来；反证，写照”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0313","seq":313,"level":"N1","type":"主词条","word":"潤う","kana":"うるおう","pos":"[自動1]","accent":"③","meaning":"湿润；宽绰起来，获益","example":"潤う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“湿润；宽绰起来，获益”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n潤う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“湿润；宽绰起来，获益”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0314","seq":314,"level":"N1","type":"主词条","word":"麗しい","kana":"うるわしい","pos":"[イ形]","accent":"④","meaning":"优美的；心情好的","example":"麗しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“优美的；心情好的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n麗しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“优美的；心情好的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0315","seq":315,"level":"N1","type":"主词条","word":"憂い/愁い","kana":"うれい","pos":"[名]","accent":"②③","meaning":"忧虑，忧愁","example":"憂いが強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“忧虑，忧愁”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n憂いが強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“忧虑，忧愁”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0316","seq":316,"level":"N1","type":"主词条","word":"憂える/愁える","kana":"うれえる","pos":"[他動2]","accent":"③","meaning":"忧虑，担心","example":"憂える場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“忧虑，担心”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n憂える場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“忧虑，担心”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0317","seq":317,"level":"N1","type":"主词条","word":"上書き","kana":"うわがき","pos":"[名·自他動3]","accent":"⓪","meaning":"写在上面；覆盖（电脑用语）","example":"上書きする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“写在上面；覆盖”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n上書きする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“写在上面；覆盖”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0318","seq":318,"level":"N1","type":"主词条","word":"浮気","kana":"うわき","pos":"[名·ナ形·自動3]","accent":"⓪","meaning":"花心，出轨","example":"浮気するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“花心，出轨”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n浮気するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“花心，出轨”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0319","seq":319,"level":"N1","type":"主词条","word":"上向く","kana":"うわむく","pos":"[自動1]","accent":"③⓪","meaning":"状况变好","example":"勢いが少しずつ上向く前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“状况变好”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ上向く前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“状况变好”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0320","seq":320,"level":"N1","type":"主词条","word":"上役","kana":"うわやく","pos":"[名]","accent":"⓪","meaning":"上级，上司","example":"経験豊かな上役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“上级，上司”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな上役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“上级，上司”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0321","seq":321,"level":"N1","type":"主词条","word":"運営","kana":"うんえい","pos":"[名·他動3]","accent":"⓪","meaning":"运营，运作","example":"運営した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“运营，运作”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n運営した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“运营，运作”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0322","seq":322,"level":"N1","type":"主词条","word":"運行","kana":"うんこう","pos":"[名·自動3]","accent":"⓪","meaning":"运行，行驶","example":"運行する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“运行，行驶”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n運行する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“运行，行驶”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0323","seq":323,"level":"N1","type":"主词条","word":"うんざり","kana":"うんざり","pos":"[副·自動3]","accent":"③","meaning":"厌倦，厌烦","example":"同じ注意を何度も聞かされてうんざりした彼は、反発する前に自分の作業手順を見直してみた。","exampleZh":"对反复听到同样提醒感到厌烦后，他没有先反抗，而是试着重新审视自己的作业步骤。","note":"例：\n同じ注意を何度も聞かされてうんざりした彼は、反発する前に自分の作業手順を見直してみた。\n译：对反复听到同样提醒感到厌烦后，他没有先反抗，而是试着重新审视自己的作业步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0324","seq":324,"level":"N1","type":"主词条","word":"運送","kana":"うんそう","pos":"[名·他動3]","accent":"⓪","meaning":"运送，运输","example":"彼は運送を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“运送，运输”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は運送を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“运送，运输”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0325","seq":325,"level":"N1","type":"主词条","word":"運賃","kana":"うんちん","pos":"[名]","accent":"①","meaning":"运费","example":"運賃を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“运费”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\n運賃を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“运费”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0326","seq":326,"level":"N1","type":"主词条","word":"云々","kana":"うんぬん","pos":"[名·他動3]","accent":"⓪","meaning":"（这样那样地）评论，说长道短","example":"云々する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“评论，说长道短”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n云々する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“评论，说长道短”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0327","seq":327,"level":"N1","type":"主词条","word":"運搬","kana":"うんぱん","pos":"[名·他動3]","accent":"⓪","meaning":"搬运，运输","example":"運搬する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“搬运，运输”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n運搬する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“搬运，运输”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0328","seq":328,"level":"N1","type":"主词条","word":"運用","kana":"うんよう","pos":"[名·他動3]","accent":"⓪","meaning":"运用","example":"チームは運用する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“运用”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは運用する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“运用”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0329","seq":329,"level":"N1","type":"主词条","word":"柄","kana":"え","pos":"[名]","accent":"⓪","meaning":"手柄，把手","example":"柄の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“手柄，把手”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n柄の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“手柄，把手”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0330","seq":330,"level":"N1","type":"主词条","word":"英字","kana":"えいじ","pos":"[名]","accent":"⓪","meaning":"英语文字","example":"英字を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“英语文字”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\n英字を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“英语文字”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0331","seq":331,"level":"N1","type":"主词条","word":"映写","kana":"えいしゃ","pos":"[名·他動3]","accent":"⓪","meaning":"放映","example":"映写の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“放映”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n映写の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“放映”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0332","seq":332,"level":"N1","type":"主词条","word":"英雄","kana":"えいゆう","pos":"[名]","accent":"⓪","meaning":"英雄","example":"経験豊かな英雄の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“英雄”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな英雄の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“英雄”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0333","seq":333,"level":"N1","type":"主词条","word":"液晶","kana":"えきしょう","pos":"[名]","accent":"⓪","meaning":"液晶","example":"修繕計画では液晶の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。","exampleZh":"修缮计划不仅考虑了“液晶”的费用，也考虑了施工期间对周边居民的影响。","note":"例：\n修繕計画では液晶の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。\n译：修缮计划不仅考虑了“液晶”的费用，也考虑了施工期间对周边居民的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0334","seq":334,"level":"N1","type":"主词条","word":"エキス","kana":"えきす","pos":"[名]","accent":"①","meaning":"（药和食物的）提取物，精华","example":"店主はエキスの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“提取物，精华”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主はエキスの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“提取物，精华”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0335","seq":335,"level":"N1","type":"主词条","word":"エキストラ","kana":"えきすとら (extra)","pos":"[名]","accent":"③②","meaning":"群众演员；临时增刊","example":"経験豊かなエキストラの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“群众演员；临时增刊”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなエキストラの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“群众演员；临时增刊”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0336","seq":336,"level":"N1","type":"主词条","word":"エキゾチック","kana":"えきぞちっく (exotic)","pos":"[ナ形]","accent":"④","meaning":"异国情调的","example":"エキゾチックな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“异国情调的”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nエキゾチックな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“异国情调的”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0337","seq":337,"level":"N1","type":"主词条","word":"抉る","kana":"えぐる","pos":"[他動1]","accent":"②","meaning":"挖，用刀剜；揭示（社会问题）","example":"抉る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“挖，用刀剜；揭示”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n抉る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“挖，用刀剜；揭示”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0338","seq":338,"level":"N1","type":"主词条","word":"エコ","kana":"えこ (eco)","pos":"[名]","accent":"①","meaning":"生态，环境","example":"エコを意識した商品でも、長く使えなければ結果的に資源の無駄になってしまう。","exampleZh":"即便是注重环保的商品，如果不能长期使用，结果也会造成资源浪费。","note":"例：\nエコを意識した商品でも、長く使えなければ結果的に資源の無駄になってしまう。\n译：即便是注重环保的商品，如果不能长期使用，结果也会造成资源浪费。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0339","seq":339,"level":"N1","type":"主词条","word":"会釈","kana":"えしゃく","pos":"[名·自動3]","accent":"①","meaning":"点头致意","example":"予期せず会釈した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“点头致意”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず会釈した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“点头致意”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0340","seq":340,"level":"N1","type":"主词条","word":"SF小説","kana":"えすえふしょうせつ","pos":"[名]","accent":"⑤","meaning":"科幻小说","example":"SF小説を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“科幻小说”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\nSF小説を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“科幻小说”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0341","seq":341,"level":"N1","type":"主词条","word":"エスカレート","kana":"えすかれーと (escalate)","pos":"[名·自動3]","accent":"④","meaning":"逐步升级","example":"小さな口論がエスカレートする前に、周囲の人が間に入って話を落ち着かせた。","exampleZh":"在小小争执升级之前，周围的人介入其中，让谈话冷静了下来。","note":"例：\n小さな口論がエスカレートする前に、周囲の人が間に入って話を落ち着かせた。\n译：在小小争执升级之前，周围的人介入其中，让谈话冷静了下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0342","seq":342,"level":"N1","type":"主词条","word":"エステ","kana":"えすて","pos":"[名]","accent":"①","meaning":"美容店","example":"エステをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“美容店”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nエステをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“美容店”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0343","seq":343,"level":"N1","type":"主词条","word":"エッセー","kana":"えっせー (essay)","pos":"[名]","accent":"①","meaning":"随笔","example":"短いエッセーの中に、作者の人生観と日常を見つめる温かな視線が表れている。","exampleZh":"短短一篇随笔中，流露出作者的人生观以及温柔注视日常的目光。","note":"例：\n短いエッセーの中に、作者の人生観と日常を見つめる温かな視線が表れている。\n译：短短一篇随笔中，流露出作者的人生观以及温柔注视日常的目光。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0344","seq":344,"level":"N1","type":"主词条","word":"閲覧","kana":"えつらん","pos":"[名·他動3]","accent":"⓪","meaning":"阅览","example":"閲覧するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。","exampleZh":"他没有只满足于“阅览”本身，而是进一步思考结果如何连接到现场改善。","note":"例：\n閲覧するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。\n译：他没有只满足于“阅览”本身，而是进一步思考结果如何连接到现场改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0345","seq":345,"level":"N1","type":"主词条","word":"得手","kana":"えて","pos":"[名·ナ形]","accent":"②","meaning":"擅长","example":"得手な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“擅长”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n得手な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“擅长”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0346","seq":346,"level":"N1","type":"主词条","word":"会得","kana":"えとく","pos":"[名·他動3]","accent":"⓪①","meaning":"掌握，领会","example":"技術を会得するには、手順を覚えるだけでなく、失敗したときの原因を自分で考える必要がある。","exampleZh":"要掌握技术，不能只记住步骤，还需要在失败时自己思考原因。","note":"例：\n技術を会得するには、手順を覚えるだけでなく、失敗したときの原因を自分で考える必要がある。\n译：要掌握技术，不能只记住步骤，还需要在失败时自己思考原因。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0347","seq":347,"level":"N1","type":"主词条","word":"エピソード","kana":"えぴそーど (episode)","pos":"[名]","accent":"①③","meaning":"插曲，轶事","example":"エピソードの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“插曲，轶事”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\nエピソードの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“插曲，轶事”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0348","seq":348,"level":"N1","type":"主词条","word":"獲物","kana":"えもの","pos":"[名]","accent":"③⓪","meaning":"猎物；战利品","example":"狩人は獲物を見つけてもすぐには動かず、風向きと周囲の安全を確かめてから近づいた。","exampleZh":"猎人即使发现猎物也没有立刻行动，而是在确认风向和周围安全后才靠近。","note":"例：\n狩人は獲物を見つけてもすぐには動かず、風向きと周囲の安全を確かめてから近づいた。\n译：猎人即使发现猎物也没有立刻行动，而是在确认风向和周围安全后才靠近。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0349","seq":349,"level":"N1","type":"主词条","word":"エリート","kana":"えりーと","pos":"[名]","accent":"②","meaning":"精英","example":"エリートとして期待されていても、現場の苦労を知らなければ部下の信頼は得られない。","exampleZh":"即使被期待为精英，如果不了解现场的辛苦，也无法得到部下的信任。","note":"例：\nエリートとして期待されていても、現場の苦労を知らなければ部下の信頼は得られない。\n译：即使被期待为精英，如果不了解现场的辛苦，也无法得到部下的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0350","seq":350,"level":"N1","type":"主词条","word":"エレガント","kana":"えれがんと (elegant)","pos":"[ナ形]","accent":"①","meaning":"高雅，优雅","example":"エレガントな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“高雅，优雅”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nエレガントな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“高雅，优雅”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0351","seq":351,"level":"N1","type":"主词条","word":"縁","kana":"えん","pos":"[名]","accent":"①","meaning":"缘分，关系","example":"長く続いた縁でも、一度失われた信頼を取り戻すには、小さな約束を守り続けるしかない。","exampleZh":"即便是长久延续的缘分，一旦失去信任，也只能靠持续遵守小小约定来重新挽回。","note":"例：\n長く続いた縁でも、一度失われた信頼を取り戻すには、小さな約束を守り続けるしかない。\n译：即便是长久延续的缘分，一旦失去信任，也只能靠持续遵守小小约定来重新挽回。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0352","seq":352,"level":"N1","type":"主词条","word":"円滑","kana":"えんかつ","pos":"[名·ナ形]","accent":"⓪","meaning":"圆滑，顺利","example":"計画を円滑に進めるには、問題が起きてから連絡するのではなく、早めに情報を共有する必要がある。","exampleZh":"要让计划顺利推进，不能等问题发生后才联络，而需要尽早共享信息。","note":"例：\n計画を円滑に進めるには、問題が起きてから連絡するのではなく、早めに情報を共有する必要がある。\n译：要让计划顺利推进，不能等问题发生后才联络，而需要尽早共享信息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0353","seq":353,"level":"N1","type":"主词条","word":"縁起","kana":"えんぎ","pos":"[名]","accent":"⓪","meaning":"兆头","example":"試験の朝に茶柱が立ったのを見て、彼女は縁起がいいと笑い、少し緊張がほぐれた。","exampleZh":"考试当天早上看到茶柱立起，她笑着说这是好兆头，紧张也稍微缓解了。","note":"例：\n試験の朝に茶柱が立ったのを見て、彼女は縁起がいいと笑い、少し緊張がほぐれた。\n译：考试当天早上看到茶柱立起，她笑着说这是好兆头，紧张也稍微缓解了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0354","seq":354,"level":"N1","type":"主词条","word":"縁起物","kana":"えんぎもの","pos":"[名]","accent":"⓪","meaning":"吉祥物","example":"縁起物の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“吉祥物”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n縁起物の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“吉祥物”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0355","seq":355,"level":"N1","type":"主词条","word":"婉曲","kana":"えんきょく","pos":"[ナ形]","accent":"⓪","meaning":"委婉","example":"婉曲な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“委婉”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n婉曲な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“委婉”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0356","seq":356,"level":"N1","type":"主词条","word":"エンジニア","kana":"えんじにあ (engineer)","pos":"[名]","accent":"③","meaning":"工程师","example":"経験豊かなエンジニアの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“工程师”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなエンジニアの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“工程师”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0357","seq":357,"level":"N1","type":"主词条","word":"演出","kana":"えんしゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"导演；组织，安排","example":"舞台の演出は派手さを抑えていたが、照明の変化だけで登場人物の孤独が鮮明に伝わってきた。","exampleZh":"舞台演出压低了华丽感，但只凭灯光变化就鲜明传达出登场人物的孤独。","note":"例：\n舞台の演出は派手さを抑えていたが、照明の変化だけで登場人物の孤独が鮮明に伝わってきた。\n译：舞台演出压低了华丽感，但只凭灯光变化就鲜明传达出登场人物的孤独。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0358","seq":358,"level":"N1","type":"主词条","word":"炎症","kana":"えんしょう","pos":"[名]","accent":"⓪","meaning":"炎症","example":"喉の炎症が長引いているため、医師は薬だけでなく声を出しすぎない生活上の注意も伝えた。","exampleZh":"喉咙炎症久拖不愈，医生不仅给药，也提醒他生活上不要过度用嗓。","note":"例：\n喉の炎症が長引いているため、医師は薬だけでなく声を出しすぎない生活上の注意も伝えた。\n译：喉咙炎症久拖不愈，医生不仅给药，也提醒他生活上不要过度用嗓。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0359","seq":359,"level":"N1","type":"主词条","word":"演じる","kana":"えんじる","pos":"[他動2]","accent":"③⓪","meaning":"扮演；造成，表现","example":"彼は厳しい父親の役を演じるため、声の出し方だけでなく沈黙の間まで細かく研究した。","exampleZh":"为了扮演严厉父亲的角色，他不仅研究发声方式，连沉默的间隔也细致琢磨。","note":"例：\n彼は厳しい父親の役を演じるため、声の出し方だけでなく沈黙の間まで細かく研究した。\n译：为了扮演严厉父亲的角色，他不仅研究发声方式，连沉默的间隔也细致琢磨。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0360","seq":360,"level":"N1","type":"主词条","word":"円高","kana":"えんだか","pos":"[名]","accent":"⓪","meaning":"日元升值","example":"円高をきっかけに、それまで曖昧だった責任の所在が問われ、組織の対応方針が見直された。","exampleZh":"以日元升值为契机，此前含糊的责任所在受到追问，组织的应对方针也被重新审视。","note":"例：\n円高をきっかけに、それまで曖昧だった責任の所在が問われ、組織の対応方針が見直された。\n译：以日元升值为契机，此前含糊的责任所在受到追问，组织的应对方针也被重新审视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0361","seq":361,"level":"N1","type":"主词条","word":"縁談","kana":"えんだん","pos":"[名]","accent":"⓪","meaning":"说媒，婚事","example":"縁談を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。","exampleZh":"如果重视“说媒，婚事”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","note":"例：\n縁談を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。\n译：如果重视“说媒，婚事”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0362","seq":362,"level":"N1","type":"主词条","word":"演壇","kana":"えんだん","pos":"[名]","accent":"⓪","meaning":"（演）讲台","example":"演壇をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“讲台”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n演壇をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“讲台”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0363","seq":363,"level":"N1","type":"主词条","word":"遠方","kana":"えんぽう","pos":"[名]","accent":"⓪","meaning":"远方","example":"観光客が増えた遠方では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“远方”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた遠方では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“远方”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0364","seq":364,"level":"N1","type":"主词条","word":"円満","kana":"えんまん","pos":"[名·ナ形]","accent":"⓪","meaning":"美满；圆满","example":"一見円満な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“美满；圆满”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見円満な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“美满；圆满”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0365","seq":365,"level":"N1","type":"主词条","word":"円安","kana":"えんやす","pos":"[名]","accent":"⓪","meaning":"日元贬值","example":"円安の流れを正確に把握しておけば、問題が大きくなる前に手を打つことができる。","exampleZh":"如果能准确把握日元贬值的趋势，就能在问题扩大前采取措施。","note":"例：\n円安の流れを正確に把握しておけば、問題が大きくなる前に手を打つことができる。\n译：如果能准确把握日元贬值的趋势，就能在问题扩大前采取措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0366","seq":366,"level":"N1","type":"主词条","word":"追い込む","kana":"おいこむ","pos":"[他動1]","accent":"③","meaning":"逼进，使陷入","example":"追い込む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“逼进，使陷入”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n追い込む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“逼进，使陷入”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0367","seq":367,"level":"N1","type":"主词条","word":"追い出す","kana":"おいだす","pos":"[他動1]","accent":"③","meaning":"赶出，撵出","example":"無理に追い出すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“赶出，撵出”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に追い出すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“赶出，撵出”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0368","seq":368,"level":"N1","type":"主词条","word":"老いる","kana":"おいる","pos":"[自動2]","accent":"②","meaning":"上年纪；衰老","example":"老いる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“上年纪；衰老”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n老いる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“上年纪；衰老”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0369","seq":369,"level":"N1","type":"主词条","word":"負う","kana":"おう","pos":"[自他動1]","accent":"⓪","meaning":"承担；遭受；仰赖","example":"無理に負うよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“承担；遭受”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に負うよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“承担；遭受”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0370","seq":370,"level":"N1","type":"主词条","word":"応急","kana":"おうきゅう","pos":"[名]","accent":"⓪","meaning":"应急","example":"応急が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“应急”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n応急が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“应急”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0371","seq":371,"level":"N1","type":"主词条","word":"横行","kana":"おうこう","pos":"[名·自動3]","accent":"⓪","meaning":"横行，风行","example":"横行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“横行，风行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n横行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“横行，风行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0372","seq":372,"level":"N1","type":"主词条","word":"王者","kana":"おうじゃ","pos":"[名]","accent":"①","meaning":"王者；最有实力的人","example":"王者らしい落ち着きで試合を進めた選手は、終盤の苦しい場面でも表情を変えなかった。","exampleZh":"那名选手以王者般的沉着推进比赛，即使在终盘艰难场面也没有改变表情。","note":"例：\n王者らしい落ち着きで試合を進めた選手は、終盤の苦しい場面でも表情を変えなかった。\n译：那名选手以王者般的沉着推进比赛，即使在终盘艰难场面也没有改变表情。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0373","seq":373,"level":"N1","type":"主词条","word":"往診","kana":"おうしん","pos":"[名·自動3]","accent":"⓪","meaning":"出诊","example":"往診するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“出诊”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n往診するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“出诊”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0374","seq":374,"level":"N1","type":"主词条","word":"旺盛","kana":"おうせい","pos":"[名·ナ形]","accent":"⓪","meaning":"旺盛，充沛","example":"周囲から旺盛だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“旺盛，充沛”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から旺盛だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“旺盛，充沛”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0375","seq":375,"level":"N1","type":"主词条","word":"横着","kana":"おうちゃく","pos":"[名·ナ形·自動3]","accent":"③④","meaning":"偷懒，耍滑头","example":"横着してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“偷懒，耍滑头”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n横着してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“偷懒，耍滑头”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0376","seq":376,"level":"N1","type":"主词条","word":"横転","kana":"おうてん","pos":"[名·自動3]","accent":"⓪","meaning":"横向倒下，翻车","example":"強風でトラックが横転したため、警察は道路を封鎖し、後続車に迂回を呼びかけた。","exampleZh":"强风导致卡车翻车，警方封锁道路，并呼吁后续车辆绕行。","note":"例：\n強風でトラックが横転したため、警察は道路を封鎖し、後続車に迂回を呼びかけた。\n译：强风导致卡车翻车，警方封锁道路，并呼吁后续车辆绕行。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0377","seq":377,"level":"N1","type":"主词条","word":"横領","kana":"おうりょう","pos":"[名·他動3]","accent":"⓪","meaning":"侵吞，贪污","example":"横領した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“侵吞，贪污”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n横領した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“侵吞，贪污”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0378","seq":378,"level":"N1","type":"主词条","word":"大方","kana":"おおかた","pos":"[名·副]","accent":"⓪","meaning":"一般人；大致","example":"大方の予想に反して、古い商店街を生かした再開発案は若い住民からも支持を集めた。","exampleZh":"与多数人的预想相反，活用老商店街的再开发方案也获得了年轻居民的支持。","note":"例：\n大方の予想に反して、古い商店街を生かした再開発案は若い住民からも支持を集めた。\n译：与多数人的预想相反，活用老商店街的再开发方案也获得了年轻居民的支持。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0379","seq":379,"level":"N1","type":"主词条","word":"大柄","kana":"おおがら","pos":"[名·ナ形]","accent":"⓪","meaning":"身材高大；大花纹","example":"周囲から大柄だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“身材高大；大花纹”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から大柄だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“身材高大；大花纹”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0380","seq":380,"level":"N1","type":"主词条","word":"大口","kana":"おおぐち","pos":"[名]","accent":"⓪","meaning":"大宗，大批（订货等）","example":"大口の注文が入ったため、工場は納期に遅れないよう原材料の確保と人員配置を急いだ。","exampleZh":"由于收到大宗订单，工厂为避免延误交货期，急忙确保原材料并安排人员。","note":"例：\n大口の注文が入ったため、工場は納期に遅れないよう原材料の確保と人員配置を急いだ。\n译：由于收到大宗订单，工厂为避免延误交货期，急忙确保原材料并安排人员。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0381","seq":381,"level":"N1","type":"主词条","word":"大げさ","kana":"おおげさ","pos":"[ナ形]","accent":"⓪","meaning":"夸张","example":"大げさな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“夸张”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n大げさな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“夸张”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0382","seq":382,"level":"N1","type":"主词条","word":"大御所","kana":"おおごしょ","pos":"[名]","accent":"③⓪","meaning":"权威，泰斗","example":"経験豊かな大御所の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“权威，泰斗”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな大御所の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“权威，泰斗”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0383","seq":383,"level":"N1","type":"主词条","word":"大筋","kana":"おおすじ","pos":"[名]","accent":"⓪","meaning":"梗概","example":"交渉の大筋が固まっても、細部の条件を曖昧にすれば、後になって関係者の不満が噴き出す。","exampleZh":"即使谈判的大致框架已经确定，如果细节条件含糊，之后相关人员的不满也会爆发。","note":"例：\n交渉の大筋が固まっても、細部の条件を曖昧にすれば、後になって関係者の不満が噴き出す。\n译：即使谈判的大致框架已经确定，如果细节条件含糊，之后相关人员的不满也会爆发。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0384","seq":384,"level":"N1","type":"主词条","word":"オーソドックス","kana":"おーそどっくす (orthodox)","pos":"[ナ形]","accent":"④","meaning":"正统的","example":"周囲からオーソドックスだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“正统的”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲からオーソドックスだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“正统的”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0385","seq":385,"level":"N1","type":"主词条","word":"大空","kana":"おおぞら","pos":"[名]","accent":"③","meaning":"天空","example":"久しぶりに見上げた大空は広く、追い込まれていた彼の気持ちを少しだけ軽くしてくれた。","exampleZh":"久违地仰望辽阔天空，让被逼得喘不过气的他心情稍微轻松了一些。","note":"例：\n久しぶりに見上げた大空は広く、追い込まれていた彼の気持ちを少しだけ軽くしてくれた。\n译：久违地仰望辽阔天空，让被逼得喘不过气的他心情稍微轻松了一些。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0386","seq":386,"level":"N1","type":"主词条","word":"オーダーメイド","kana":"おーだーめいど","pos":"[名]","accent":"⑤","meaning":"定做","example":"オーダーメイドの家具は値段が高いが、部屋の寸法や使う人の癖に合わせて細かく調整できる。","exampleZh":"定做家具虽然价格高，但可以配合房间尺寸和使用者习惯进行细致调整。","note":"例：\nオーダーメイドの家具は値段が高いが、部屋の寸法や使う人の癖に合わせて細かく調整できる。\n译：定做家具虽然价格高，但可以配合房间尺寸和使用者习惯进行细致调整。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0387","seq":387,"level":"N1","type":"主词条","word":"大台","kana":"おおだい","pos":"[名]","accent":"⓪","meaning":"（金额、数量的）大关","example":"担当者は大台の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。","exampleZh":"负责人明确了“大关”的标准，并留下记录，以便任何人查看时都能作出相同判断。","note":"例：\n担当者は大台の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。\n译：负责人明确了“大关”的标准，并留下记录，以便任何人查看时都能作出相同判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0388","seq":388,"level":"N1","type":"主词条","word":"大手","kana":"おおて","pos":"[名]","accent":"①","meaning":"大公司，大企业","example":"新規事業では大手の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“大公司，大企业”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では大手の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“大公司，大企业”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0389","seq":389,"level":"N1","type":"主词条","word":"オートマチック","kana":"おーとまちっく (automatic)","pos":"[名·ナ形]","accent":"⑤④","meaning":"自动","example":"オートマチックの車は操作が簡単に見えるが、緊急時の判断まで機械任せにすることはできない。","exampleZh":"自动挡汽车看起来操作简单，但紧急时的判断不能全都交给机器。","note":"例：\nオートマチックの車は操作が簡単に見えるが、緊急時の判断まで機械任せにすることはできない。\n译：自动挡汽车看起来操作简单，但紧急时的判断不能全都交给机器。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0390","seq":390,"level":"N1","type":"主词条","word":"オートメーション","kana":"おーとめーしょん (automation)","pos":"[名]","accent":"④","meaning":"自动化","example":"オートメーションに頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。","exampleZh":"如果过度依赖“自动化”，可能忽视细小异常，因此现场仍保留人工确认。","note":"例：\nオートメーションに頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。\n译：如果过度依赖“自动化”，可能忽视细小异常，因此现场仍保留人工确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0391","seq":391,"level":"N1","type":"主词条","word":"オーナー","kana":"おーなー (owner)","pos":"[名]","accent":"①","meaning":"物主，业主","example":"オーナーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“物主，业主”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nオーナーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“物主，业主”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0392","seq":392,"level":"N1","type":"主词条","word":"大幅","kana":"おおはば","pos":"[名·ナ形]","accent":"⓪④","meaning":"大幅度","example":"大幅な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“大幅度”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n大幅な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“大幅度”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0393","seq":393,"level":"N1","type":"主词条","word":"オープン","kana":"おーぷん (open)","pos":"[名·ナ形·自動3]","accent":"①","meaning":"开张；开放","example":"オープンしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“开张；开放”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\nオープンしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“开张；开放”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0394","seq":394,"level":"N1","type":"主词条","word":"大まか","kana":"おおまか","pos":"[ナ形]","accent":"⓪","meaning":"粗略，粗枝大叶","example":"大まかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“粗略，粗枝大叶”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n大まかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“粗略，粗枝大叶”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0395","seq":395,"level":"N1","type":"主词条","word":"概ね","kana":"おおむね","pos":"[名·副]","accent":"⓪","meaning":"梗概；大致","example":"調査結果は概ね良好だったが、一部の地域では利用者への周知がまだ十分とは言えなかった。","exampleZh":"调查结果大致良好，但部分地区对使用者的告知仍不能说足够充分。","note":"例：\n調査結果は概ね良好だったが、一部の地域では利用者への周知がまだ十分とは言えなかった。\n译：调查结果大致良好，但部分地区对使用者的告知仍不能说足够充分。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0396","seq":396,"level":"N1","type":"主词条","word":"大物","kana":"おおもの","pos":"[名]","accent":"⓪","meaning":"大人物","example":"大物として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“大人物”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n大物として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“大人物”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0397","seq":397,"level":"N1","type":"主词条","word":"公","kana":"おおやけ","pos":"[名]","accent":"①","meaning":"公共，（政府的）正式；公开","example":"公の場で発言する以上、彼は個人的な感情ではなく、根拠のある情報に基づいて話すべきだった。","exampleZh":"既然要在公开场合发言，他就不该基于个人情绪，而应根据有依据的信息讲话。","note":"例：\n公の場で発言する以上、彼は個人的な感情ではなく、根拠のある情報に基づいて話すべきだった。\n译：既然要在公开场合发言，他就不该基于个人情绪，而应根据有依据的信息讲话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0398","seq":398,"level":"N1","type":"主词条","word":"大らか","kana":"おおらか","pos":"[ナ形]","accent":"②③","meaning":"性格开朗，豁达","example":"周囲から大らかだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“性格开朗，豁达”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から大らかだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“性格开朗，豁达”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0399","seq":399,"level":"N1","type":"主词条","word":"お返し","kana":"おかえし","pos":"[名]","accent":"⓪","meaning":"回礼；报复；找头","example":"新規事業ではお返しの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“回礼；报复”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業ではお返しの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“回礼；报复”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0400","seq":400,"level":"N1","type":"主词条","word":"冒す","kana":"おかす","pos":"[他動1]","accent":"②⓪","meaning":"冒，不顾；冒称","example":"冒すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“冒，不顾；冒称”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n冒すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“冒，不顾；冒称”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0401","seq":401,"level":"N1","type":"主词条","word":"侵す","kana":"おかす","pos":"[他動1]","accent":"②⓪","meaning":"侵犯","example":"相手を侵すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用让对方感到“侵犯”的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を侵すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用让对方感到“侵犯”的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0402","seq":402,"level":"N1","type":"主词条","word":"おかみさん","kana":"おかみさん","pos":"[名]","accent":"⓪","meaning":"老板娘","example":"おかみさんとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“老板娘”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\nおかみさんとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“老板娘”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0403","seq":403,"level":"N1","type":"主词条","word":"臆病","kana":"おくびょう","pos":"[名·ナ形]","accent":"③","meaning":"胆小，胆怯","example":"臆病な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“胆小，胆怯”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n臆病な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“胆小，胆怯”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0404","seq":404,"level":"N1","type":"主词条","word":"奥深い","kana":"おくぶかい","pos":"[イ形]","accent":"④","meaning":"意义深的，深奥的","example":"茶道の作法は一見単純に見えるが、学べば学ぶほど奥深い世界が広がっている。","exampleZh":"茶道礼法乍看简单，但越学越会发现其中展开着深奥的世界。","note":"例：\n茶道の作法は一見単純に見えるが、学べば学ぶほど奥深い世界が広がっている。\n译：茶道礼法乍看简单，但越学越会发现其中展开着深奥的世界。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0405","seq":405,"level":"N1","type":"主词条","word":"遅らせる","kana":"おくらせる","pos":"[他動2]","accent":"⓪","meaning":"延缓，推迟","example":"締め切りを遅らせるには、都合のよい理由だけでなく、関係者が納得できる根拠を示さなければならない。","exampleZh":"要推迟截止日期，不能只给出对自己方便的理由，还必须提出相关人员能够接受的依据。","note":"例：\n締め切りを遅らせるには、都合のよい理由だけでなく、関係者が納得できる根拠を示さなければならない。\n译：要推迟截止日期，不能只给出对自己方便的理由，还必须提出相关人员能够接受的依据。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0406","seq":406,"level":"N1","type":"主词条","word":"送り状","kana":"おくりじょう","pos":"[名]","accent":"⓪","meaning":"发货单","example":"担当者は送り状を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“发货单”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は送り状を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“发货单”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0407","seq":407,"level":"N1","type":"主词条","word":"厳か","kana":"おごそか","pos":"[ナ形]","accent":"②","meaning":"庄严，庄重","example":"厳かな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“庄严，庄重”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n厳かな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“庄严，庄重”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0408","seq":408,"level":"N1","type":"主词条","word":"怠る","kana":"おこたる","pos":"[自他動1]","accent":"③⓪","meaning":"怠慢，懈怠","example":"怠る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“怠慢，懈怠”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n怠る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“怠慢，懈怠”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0409","seq":409,"level":"N1","type":"主词条","word":"驕る/おごる","kana":"おごる","pos":"[自動1]","accent":"⓪","meaning":"骄傲，傲慢","example":"驕る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“骄傲，傲慢”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n驕る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“骄傲，傲慢”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0410","seq":410,"level":"N1","type":"主词条","word":"押さえ込む","kana":"おさえこむ","pos":"[他動1]","accent":"④","meaning":"压住，按住；控制住","example":"無理に押さえ込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“压住，按住；控制住”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に押さえ込むと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“压住，按住；控制住”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0411","seq":411,"level":"N1","type":"主词条","word":"幼馴染","kana":"おさななじみ","pos":"[名]","accent":"④","meaning":"青梅竹马之交","example":"幼馴染の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“青梅竹马之交”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n幼馴染の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“青梅竹马之交”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0412","seq":412,"level":"N1","type":"主词条","word":"納める","kana":"おさめる","pos":"[他動2]","accent":"③","meaning":"缴纳；收，接受","example":"納める前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“缴纳；收，接受”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n納める前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“缴纳；收，接受”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0413","seq":413,"level":"N1","type":"主词条","word":"押し上げる","kana":"おしあげる","pos":"[他動2]","accent":"④","meaning":"往上推；抬高；提升","example":"数字を無理に押し上げるだけでは長続きしないため、彼は品質と働き方の改善にも目を向けた。","exampleZh":"单纯勉强拉高数字无法长久，因此他也开始关注品质和工作方式的改善。","note":"例：\n数字を無理に押し上げるだけでは長続きしないため、彼は品質と働き方の改善にも目を向けた。\n译：单纯勉强拉高数字无法长久，因此他也开始关注品质和工作方式的改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0414","seq":414,"level":"N1","type":"主词条","word":"押し切る","kana":"おしきる","pos":"[他動1]","accent":"③","meaning":"切断；不顾，坚持到底","example":"無理に押し切ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“切断；不顾，坚持到底”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に押し切ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“切断；不顾，坚持到底”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0415","seq":415,"level":"N1","type":"主词条","word":"押し込む","kana":"おしこむ","pos":"[自動1]","accent":"③","meaning":"闯入；硬塞","example":"押し込む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“闯入；硬塞”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n押し込む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“闯入；硬塞”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0416","seq":416,"level":"N1","type":"主词条","word":"推し進める","kana":"おしすすめる","pos":"[他動2]","accent":"⑤","meaning":"推进","example":"無理に推し進めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“推进”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に推し進めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“推进”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0417","seq":417,"level":"N1","type":"主词条","word":"押し出す","kana":"おしだす","pos":"[自動1]","accent":"③","meaning":"推出去；突出，强调","example":"押し出す前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“推出去；突出，强调”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n押し出す前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“推出去；突出，强调”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0418","seq":418,"level":"N1","type":"主词条","word":"押し付けがましい","kana":"おしつけがましい","pos":"[イ形]","accent":"⑦","meaning":"强加于人","example":"押し付けがましい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“强加于人”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n押し付けがましい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“强加于人”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0419","seq":419,"level":"N1","type":"主词条","word":"押し付ける","kana":"おしつける","pos":"[他動2]","accent":"④","meaning":"推；强加于人","example":"上司が自分の考えを部下に押し付けるだけでは、現場から主体的な提案は生まれにくい。","exampleZh":"上司如果只是把自己的想法强加给部下，现场就很难产生自主性提案。","note":"例：\n上司が自分の考えを部下に押し付けるだけでは、現場から主体的な提案は生まれにくい。\n译：上司如果只是把自己的想法强加给部下，现场就很难产生自主性提案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0420","seq":420,"level":"N1","type":"主词条","word":"惜しむ","kana":"おしむ","pos":"[他動1]","accent":"②","meaning":"珍惜；舍不得；惋惜","example":"相手に何かを惜しむなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“珍惜；舍不得”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを惜しむなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“珍惜；舍不得”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0421","seq":421,"level":"N1","type":"主词条","word":"汚職","kana":"おしょく","pos":"[名]","accent":"⓪","meaning":"贪污","example":"小さな汚職を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“贪污”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな汚職を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“贪污”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0422","seq":422,"level":"N1","type":"主词条","word":"押し寄せる","kana":"おしよせる","pos":"[自動2]","accent":"④","meaning":"涌来；蜂拥而至","example":"押し寄せる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“涌来；蜂拥而至”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n押し寄せる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“涌来；蜂拥而至”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0423","seq":423,"level":"N1","type":"主词条","word":"お節介","kana":"おせっかい","pos":"[名·ナ形]","accent":"②","meaning":"好管闲事","example":"周囲からお節介だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“好管闲事”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲からお節介だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“好管闲事”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0424","seq":424,"level":"N1","type":"主词条","word":"遅番","kana":"おそばん","pos":"[名]","accent":"⓪","meaning":"晚班，夜班","example":"限られた遅番の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“晚班，夜班”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた遅番の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“晚班，夜班”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0425","seq":425,"level":"N1","type":"主词条","word":"煽てる","kana":"おだてる","pos":"[他動2]","accent":"⓪","meaning":"煽动，怂恿；奉承","example":"自分の道を煽てるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“煽动，怂恿；奉承”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を煽てるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“煽动，怂恿；奉承”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0426","seq":426,"level":"N1","type":"主词条","word":"陥る","kana":"おちいる","pos":"[自動1]","accent":"③⓪","meaning":"掉进，陷入","example":"陥るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“掉进，陷入”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n陥るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“掉进，陷入”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0427","seq":427,"level":"N1","type":"主词条","word":"落ち度","kana":"おちど","pos":"[名]","accent":"①","meaning":"过错，过失","example":"落ち度が表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。","exampleZh":"当“过错，过失”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","note":"例：\n落ち度が表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。\n译：当“过错，过失”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0428","seq":428,"level":"N1","type":"主词条","word":"おっかない","kana":"おっかない","pos":"[イ形]","accent":"④","meaning":"可怕的","example":"おっかない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“可怕的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nおっかない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“可怕的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0429","seq":429,"level":"N1","type":"主词条","word":"億劫","kana":"おっくう","pos":"[名·ナ形]","accent":"③","meaning":"嫌麻烦，懒得","example":"周囲から億劫だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“嫌麻烦，懒得”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から億劫だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“嫌麻烦，懒得”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0430","seq":430,"level":"N1","type":"主词条","word":"おっちょこちょい","kana":"おっちょこちょい","pos":"[名·ナ形]","accent":"⑤","meaning":"毛手毛脚，冒失鬼","example":"一度おっちょこちょいだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“毛手毛脚，冒失鬼”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度おっちょこちょいだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“毛手毛脚，冒失鬼”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0431","seq":431,"level":"N1","type":"主词条","word":"お手上げ","kana":"おてあげ","pos":"[名]","accent":"⓪","meaning":"束手无策，毫无办法","example":"小さなお手上げを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“束手无策，毫无办法”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さなお手上げを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“束手无策，毫无办法”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0432","seq":432,"level":"N1","type":"主词条","word":"おどおど","kana":"おどおど","pos":"[副·自動3]","accent":"①","meaning":"战战兢兢，提心吊胆","example":"新人は上司の前でおどおどしていたが、準備してきた内容は落ち着いて説明できた。","exampleZh":"新人在上司面前有些战战兢兢，但仍能冷静说明自己准备的内容。","note":"例：\n新人は上司の前でおどおどしていたが、準備してきた内容は落ち着いて説明できた。\n译：新人在上司面前有些战战兢兢，但仍能冷静说明自己准备的内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0433","seq":433,"level":"N1","type":"主词条","word":"脅す","kana":"おどす","pos":"[他動1]","accent":"⓪","meaning":"威胁，恐吓，吓唬","example":"相手を脅すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用让对方感到“威胁，恐吓，吓唬”的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を脅すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用让对方感到“威胁，恐吓，吓唬”的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0434","seq":434,"level":"N1","type":"主词条","word":"お供","kana":"おとも","pos":"[名·自動3]","accent":"②","meaning":"陪同，陪伴","example":"社長のお供で訪問先に向かった新人は、商談中の言葉遣いや気配りを間近で学んだ。","exampleZh":"跟随社长前往拜访地点的新人，就近学习了商务谈判中的措辞和体贴。","note":"例：\n社長のお供で訪問先に向かった新人は、商談中の言葉遣いや気配りを間近で学んだ。\n译：跟随社长前往拜访地点的新人，就近学习了商务谈判中的措辞和体贴。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0435","seq":435,"level":"N1","type":"主词条","word":"衰える","kana":"おとろえる","pos":"[自動2]","accent":"④③","meaning":"衰弱，衰退","example":"勢いが少しずつ衰える前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“衰弱，衰退”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ衰える前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“衰弱，衰退”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0436","seq":436,"level":"N1","type":"主词条","word":"自ずから","kana":"おのずから","pos":"[副]","accent":"⓪②","meaning":"自然地，自动地","example":"責任の所在を明確にすれば、解決に向けて取るべき手順は自ずから見えてくる。","exampleZh":"只要明确责任所在，面向解决问题应采取的步骤自然就会浮现出来。","note":"例：\n責任の所在を明確にすれば、解決に向けて取るべき手順は自ずから見えてくる。\n译：只要明确责任所在，面向解决问题应采取的步骤自然就会浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0437","seq":437,"level":"N1","type":"主词条","word":"自ずと","kana":"おのずと","pos":"[副]","accent":"⓪","meaning":"自然而然地","example":"毎日同じ時間に机へ向かう習慣を続けていると、集中するリズムも自ずと身についていく。","exampleZh":"每天同一时间坐到书桌前的习惯持续下去后，集中注意力的节奏也会自然而然地养成。","note":"例：\n毎日同じ時間に机へ向かう習慣を続けていると、集中するリズムも自ずと身についていく。\n译：每天同一时间坐到书桌前的习惯持续下去后，集中注意力的节奏也会自然而然地养成。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0438","seq":438,"level":"N1","type":"主词条","word":"怯える","kana":"おびえる","pos":"[自動2]","accent":"⓪③","meaning":"胆怯，恐惧","example":"怯える前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“胆怯，恐惧”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n怯える前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“胆怯，恐惧”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0439","seq":439,"level":"N1","type":"主词条","word":"夥しい","kana":"おびただしい","pos":"[イ形]","accent":"⑤","meaning":"大量；非常","example":"夥しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“大量；非常”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n夥しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“大量；非常”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0440","seq":440,"level":"N1","type":"主词条","word":"脅かす","kana":"おびやかす","pos":"[他動1]","accent":"④","meaning":"威胁","example":"相手を脅かすような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用让对方感到“威胁”的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を脅かすような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用让对方感到“威胁”的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0441","seq":441,"level":"N1","type":"主词条","word":"帯びる","kana":"おびる","pos":"[他動2]","accent":"②⓪","meaning":"带有；承担，肩负","example":"帯びる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“带有；承担，肩负”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n帯びる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“带有；承担，肩负”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0442","seq":442,"level":"N1","type":"主词条","word":"オファー","kana":"おふぁー (offer)","pos":"[名]","accent":"①","meaning":"提供；报价；录用通知","example":"海外企業から魅力的なオファーを受けたが、彼は家族の生活や将来の研究環境も含めて考えた。","exampleZh":"他收到了海外企业很有吸引力的录用邀请，但也把家人的生活和未来研究环境一起纳入考虑。","note":"例：\n海外企業から魅力的なオファーを受けたが、彼は家族の生活や将来の研究環境も含めて考えた。\n译：他收到了海外企业很有吸引力的录用邀请，但也把家人的生活和未来研究环境一起纳入考虑。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0443","seq":443,"level":"N1","type":"主词条","word":"お袋","kana":"おふくろ","pos":"[名]","accent":"⓪","meaning":"老娘，母亲（中年以上男子对母亲的称呼）","example":"久しぶりに帰省すると、お袋は何も言わずに彼の好物を食卓に並べてくれた。","exampleZh":"久违地回老家时，母亲什么也没说，就把他爱吃的东西摆上了餐桌。","note":"例：\n久しぶりに帰省すると、お袋は何も言わずに彼の好物を食卓に並べてくれた。\n译：久违地回老家时，母亲什么也没说，就把他爱吃的东西摆上了餐桌。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0444","seq":444,"level":"N1","type":"主词条","word":"オプション","kana":"おぷしょん (option)","pos":"[名]","accent":"①","meaning":"选择，选择权","example":"オプションをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“选择，选择权”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nオプションをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“选择，选择权”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0445","seq":445,"level":"N1","type":"主词条","word":"おべっか","kana":"おべっか","pos":"[名]","accent":"②","meaning":"奉承，恭维","example":"彼はおべっかな印象を与えないよう、反対意見を述べる前に相手の事情を丁寧に確認した。","exampleZh":"为了不让人觉得是在奉承，他在提出反对意见前，仔细确认了对方的处境。","note":"例：\n彼はおべっかな印象を与えないよう、反対意見を述べる前に相手の事情を丁寧に確認した。\n译：为了不让人觉得是在奉承，他在提出反对意见前，仔细确认了对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0446","seq":446,"level":"N1","type":"主词条","word":"オペラ","kana":"おぺら (opera)","pos":"[名]","accent":"①","meaning":"歌剧，戏剧","example":"新しいオペラを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的“歌剧，戏剧”，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しいオペラを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的“歌剧，戏剧”，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0447","seq":447,"level":"N1","type":"主词条","word":"覚え","kana":"おぼえ","pos":"[名]","accent":"③②","meaning":"记忆；理解；信心","example":"手順を一度聞いただけでは覚えがあやふやだったため、彼は重要な点をメモに残した。","exampleZh":"步骤只听一遍还记得不清楚，所以他把重要点记在了备忘录上。","note":"例：\n手順を一度聞いただけでは覚えがあやふやだったため、彼は重要な点をメモに残した。\n译：步骤只听一遍还记得不清楚，所以他把重要点记在了备忘录上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0448","seq":448,"level":"N1","type":"主词条","word":"覚束ない","kana":"おぼつかない","pos":"[イ形]","accent":"⓪④","meaning":"靠不住，没有把握；令人放心不下","example":"覚束ないと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“靠不住，没有把握；令人放心不下”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n覚束ないと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“靠不住，没有把握；令人放心不下”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0449","seq":449,"level":"N1","type":"主词条","word":"おまけに","kana":"おまけに","pos":"[接]","accent":"⓪","meaning":"加之，而且，何况","example":"朝から雨が降っていた。おまけに電車まで遅れ、彼は予定より三十分遅れて会場に着いた。","exampleZh":"从早上开始就下雨，而且连电车也晚点，他比预定晚三十分钟到达会场。","note":"例：\n朝から雨が降っていた。おまけに電車まで遅れ、彼は予定より三十分遅れて会場に着いた。\n译：从早上开始就下雨，而且连电车也晚点，他比预定晚三十分钟到达会场。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0450","seq":450,"level":"N1","type":"主词条","word":"思い付き","kana":"おもいつき","pos":"[名]","accent":"⓪","meaning":"偶然的想法","example":"思い付きの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“偶然的想法”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n思い付きの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“偶然的想法”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0451","seq":451,"level":"N1","type":"主词条","word":"思いやり","kana":"おもいやり","pos":"[名]","accent":"⓪","meaning":"体谅，体贴","example":"思いやりが強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“体谅，体贴”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n思いやりが強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“体谅，体贴”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0452","seq":452,"level":"N1","type":"主词条","word":"思う存分","kana":"おもうぞんぶん","pos":"[副]","accent":"②","meaning":"尽情地","example":"長い準備期間を経て迎えた舞台で、彼女は思う存分歌い、観客から大きな拍手を受けた。","exampleZh":"在经过漫长准备期后迎来的舞台上，她尽情歌唱，赢得了观众热烈掌声。","note":"例：\n長い準備期間を経て迎えた舞台で、彼女は思う存分歌い、観客から大きな拍手を受けた。\n译：在经过漫长准备期后迎来的舞台上，她尽情歌唱，赢得了观众热烈掌声。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0453","seq":453,"level":"N1","type":"主词条","word":"面影","kana":"おもかげ","pos":"[名]","accent":"⓪③","meaning":"面貌；风貌","example":"突然の面影で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“面貌；风貌”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の面影で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“面貌；风貌”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0454","seq":454,"level":"N1","type":"主词条","word":"重苦しい","kana":"おもくるしい","pos":"[イ形]","accent":"⑤","meaning":"郁闷，沉闷","example":"重苦しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“郁闷，沉闷”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n重苦しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“郁闷，沉闷”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0455","seq":455,"level":"N1","type":"主词条","word":"重み","kana":"おもみ","pos":"[名]","accent":"⓪","meaning":"重量，分量；威信","example":"重みを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“重量，分量；威信”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n重みを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“重量，分量；威信”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0456","seq":456,"level":"N1","type":"主词条","word":"趣","kana":"おもむき","pos":"[名]","accent":"⓪④","meaning":"大致内容，旨趣；情趣","example":"趣を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。","exampleZh":"负责“大致内容，旨趣；情趣”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","note":"例：\n趣を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。\n译：负责“大致内容，旨趣；情趣”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0457","seq":457,"level":"N1","type":"主词条","word":"赴く","kana":"おもむく","pos":"[自動1]","accent":"③","meaning":"前往；趋于","example":"被災地へ赴く前に、記者は現地の交通状況と安全確保の手順を入念に確認した。","exampleZh":"记者在前往受灾地之前，仔细确认了当地交通状况和确保安全的流程。","note":"例：\n被災地へ赴く前に、記者は現地の交通状況と安全確保の手順を入念に確認した。\n译：记者在前往受灾地之前，仔细确认了当地交通状况和确保安全的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0458","seq":458,"level":"N1","type":"主词条","word":"思惑","kana":"おもわく","pos":"[名]","accent":"⓪","meaning":"企图，意图","example":"立派な思惑でも、現場の制約を無視すれば実行段階で必ず行き詰まる。","exampleZh":"即使是出色的“企图，意图”，若无视现场限制，在执行阶段也一定会受阻。","note":"例：\n立派な思惑でも、現場の制約を無視すれば実行段階で必ず行き詰まる。\n译：即使是出色的“企图，意图”，若无视现场限制，在执行阶段也一定会受阻。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0459","seq":459,"level":"N1","type":"主词条","word":"思わしい","kana":"おもわしい","pos":"[イ形]","accent":"④","meaning":"令人满意，称心","example":"思わしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“令人满意，称心”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n思わしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“令人满意，称心”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0460","seq":460,"level":"N1","type":"主词条","word":"親〜","kana":"おや〜","pos":"[接頭]","accent":"","meaning":"主要的，大的","example":"親会社の方針が突然変わったため、子会社の現場でも人員配置と予算計画を見直すことになった。","exampleZh":"母公司方针突然改变，子公司现场也不得不重新审视人员配置和预算计划。","note":"例：\n親会社の方針が突然変わったため、子会社の現場でも人員配置と予算計画を見直すことになった。\n译：母公司方针突然改变，子公司现场也不得不重新审视人员配置和预算计划。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0461","seq":461,"level":"N1","type":"主词条","word":"親方","kana":"おやかた","pos":"[名]","accent":"③④","meaning":"老板，工头","example":"親方を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“老板，工头”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n親方を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“老板，工头”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0462","seq":462,"level":"N1","type":"主词条","word":"親兄弟","kana":"おやきょうだい","pos":"[名]","accent":"③","meaning":"父母和兄弟姐妹","example":"親兄弟をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“父母和兄弟姐妹”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n親兄弟をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“父母和兄弟姐妹”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0463","seq":463,"level":"N1","type":"主词条","word":"親孝行","kana":"おやこうこう","pos":"[名·ナ形·自動3]","accent":"③","meaning":"孝顺父母","example":"予期せず親孝行した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“孝顺父母”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず親孝行した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“孝顺父母”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0464","seq":464,"level":"N1","type":"主词条","word":"親心","kana":"おやごころ","pos":"[名]","accent":"③","meaning":"父母的慈爱","example":"胸に残る親心を無理に隠すより、彼女は事実と感情を分けて整理しようとした。","exampleZh":"与其勉强隐藏心中残留的“父母的慈爱”，她更想把事实和情绪分开整理。","note":"例：\n胸に残る親心を無理に隠すより、彼女は事実と感情を分けて整理しようとした。\n译：与其勉强隐藏心中残留的“父母的慈爱”，她更想把事实和情绪分开整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0465","seq":465,"level":"N1","type":"主词条","word":"及ぶ","kana":"およぶ","pos":"[自動1]","accent":"⓪","meaning":"达到；波及；匹配","example":"及ぶ場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“达到；波及”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n及ぶ場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“达到；波及”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0466","seq":466,"level":"N1","type":"主词条","word":"折","kana":"おり","pos":"[名]","accent":"②","meaning":"时机，机会；时候","example":"折が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。","exampleZh":"越接近“时机，机会；时候”，相关人员越细致地共享彼此作业进度，试图防止返工。","note":"例：\n折が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。\n译：越接近“时机，机会；时候”，相关人员越细致地共享彼此作业进度，试图防止返工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0467","seq":467,"level":"N1","type":"主词条","word":"オリエンテーション","kana":"おりえんてーしょん (orientation)","pos":"[名]","accent":"⑤","meaning":"新员工培训，入学说明会","example":"オリエンテーションとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“新员工培训，入学说明会”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\nオリエンテーションとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“新员工培训，入学说明会”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0468","seq":468,"level":"N1","type":"主词条","word":"折り返し","kana":"おりかえし","pos":"[名·副]","accent":"⓪","meaning":"折回；立即","example":"担当者が席を外していたため、受付は折り返し連絡すると伝え、相手の番号を丁寧に確認した。","exampleZh":"负责人离席不在，前台告知会回电，并仔细确认了对方号码。","note":"例：\n担当者が席を外していたため、受付は折り返し連絡すると伝え、相手の番号を丁寧に確認した。\n译：负责人离席不在，前台告知会回电，并仔细确认了对方号码。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0469","seq":469,"level":"N1","type":"主词条","word":"折り返す","kana":"おりかえす","pos":"[自他動1]","accent":"③⓪","meaning":"翻折；折回","example":"不在着信に気づいた彼は、会議が終わってすぐに相手へ折り返すことにした。","exampleZh":"注意到未接来电后，他决定会议一结束就立刻回拨给对方。","note":"例：\n不在着信に気づいた彼は、会議が終わってすぐに相手へ折り返すことにした。\n译：注意到未接来电后，他决定会议一结束就立刻回拨给对方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0470","seq":470,"level":"N1","type":"主词条","word":"オリジナル","kana":"おりじなる (original)","pos":"[名·ナ形]","accent":"②","meaning":"原创；独创","example":"オリジナルな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“原创；独创”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nオリジナルな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“原创；独创”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0471","seq":471,"level":"N1","type":"主词条","word":"織る","kana":"おる","pos":"[他動1]","accent":"①","meaning":"织，编织；编","example":"相手に何かを織るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“织，编织；编”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを織るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“织，编织；编”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0472","seq":472,"level":"N1","type":"主词条","word":"愚か","kana":"おろか","pos":"[ナ形]","accent":"①","meaning":"愚蠢","example":"愚かな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“愚蠢”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n愚かな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“愚蠢”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0473","seq":473,"level":"N1","type":"主词条","word":"おろそか","kana":"おろそか","pos":"[ナ形]","accent":"②","meaning":"敷衍，马虎，疏忽","example":"おろそかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“敷衍，马虎，疏忽”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nおろそかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“敷衍，马虎，疏忽”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0474","seq":474,"level":"N1","type":"主词条","word":"オンライン","kana":"おんらいん (online)","pos":"[名]","accent":"③","meaning":"在线","example":"オンラインに頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。","exampleZh":"如果过度依赖“在线”，可能忽视细小异常，因此现场仍保留人工确认。","note":"例：\nオンラインに頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。\n译：如果过度依赖“在线”，可能忽视细小异常，因此现场仍保留人工确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0475","seq":475,"level":"N1","type":"主词条","word":"温和","kana":"おんわ","pos":"[名·ナ形]","accent":"⓪","meaning":"气候温暖稳定；稳重","example":"温和な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“气候温暖稳定；稳重”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n温和な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“气候温暖稳定；稳重”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0476","seq":476,"level":"N1","type":"主词条","word":"〜画","kana":"〜が","pos":"[接尾]","accent":"","meaning":"……画","example":"次の展示では水彩画を中心に紹介し、作品ごとに画家が込めた意図や時代背景も丁寧に示す。","exampleZh":"下一次展览将以水彩画为中心介绍，并细致展示每件作品中画家寄托的意图和时代背景。","note":"例：\n次の展示では水彩画を中心に紹介し、作品ごとに画家が込めた意図や時代背景も丁寧に示す。\n译：下一次展览将以水彩画为中心介绍，并细致展示每件作品中画家寄托的意图和时代背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0477","seq":477,"level":"N1","type":"主词条","word":"ガーゼ","kana":"がーぜ","pos":"[名]","accent":"①","meaning":"纱布","example":"式典に着ていくガーゼを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“纱布”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていくガーゼを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“纱布”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0478","seq":478,"level":"N1","type":"主词条","word":"カーソル","kana":"かーそる (cursor)","pos":"[名]","accent":"①⓪","meaning":"光标","example":"カーソルを守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“光标”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\nカーソルを守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“光标”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0479","seq":479,"level":"N1","type":"主词条","word":"カーペット","kana":"かーぺっと (carpet)","pos":"[名]","accent":"①③","meaning":"地毯","example":"カーペットの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。","exampleZh":"“地毯”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","note":"例：\nカーペットの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。\n译：“地毯”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0480","seq":480,"level":"N1","type":"主词条","word":"改悪","kana":"かいあく","pos":"[名·他動3]","accent":"⓪","meaning":"越改越坏","example":"チームは改悪する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“越改越坏”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは改悪する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“越改越坏”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0481","seq":481,"level":"N1","type":"主词条","word":"外貨","kana":"がいか","pos":"[名]","accent":"①","meaning":"外币，外汇；进口货","example":"新規事業では外貨の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“外币，外汇；进口货”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では外貨の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“外币，外汇；进口货”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0482","seq":482,"level":"N1","type":"主词条","word":"改革","kana":"かいかく","pos":"[名·他動3]","accent":"⓪","meaning":"改革","example":"初めて改革する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“改革”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて改革する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“改革”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0483","seq":483,"level":"N1","type":"主词条","word":"外観","kana":"がいかん","pos":"[名]","accent":"⓪","meaning":"外观，外表","example":"建物の外観は古びているが、内部は耐震補強が行われ、地域の交流施設として使われている。","exampleZh":"建筑外观虽然显得陈旧，内部却已进行抗震加固，并作为地区交流设施使用。","note":"例：\n建物の外観は古びているが、内部は耐震補強が行われ、地域の交流施設として使われている。\n译：建筑外观虽然显得陈旧，内部却已进行抗震加固，并作为地区交流设施使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0484","seq":484,"level":"N1","type":"主词条","word":"階級","kana":"かいきゅう","pos":"[名]","accent":"⓪","meaning":"阶级","example":"新しい階級を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。","exampleZh":"运用新的“阶级”时，需要反映当事人的声音，避免负担只偏向一部分人。","note":"例：\n新しい階級を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。\n译：运用新的“阶级”时，需要反映当事人的声音，避免负担只偏向一部分人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0485","seq":485,"level":"N1","type":"主词条","word":"海峡","kana":"かいきょう","pos":"[名]","accent":"⓪","meaning":"海峡","example":"研究者は海峡の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“海峡”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は海峡の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“海峡”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0486","seq":486,"level":"N1","type":"主词条","word":"改行","kana":"かいぎょう","pos":"[名·自動3]","accent":"⓪","meaning":"换行，另起一行","example":"改行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“换行，另起一行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n改行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“换行，另起一行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0487","seq":487,"level":"N1","type":"主词条","word":"会計","kana":"かいけい","pos":"[名]","accent":"⓪","meaning":"结账，付款；会计","example":"新規事業では会計の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“结账，付款；会计”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では会計の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“结账，付款；会计”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0488","seq":488,"level":"N1","type":"主词条","word":"会見","kana":"かいけん","pos":"[名·自動3]","accent":"⓪","meaning":"会见","example":"会見するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。","exampleZh":"他没有只满足于“会见”本身，而是进一步思考结果如何连接到现场改善。","note":"例：\n会見するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。\n译：他没有只满足于“会见”本身，而是进一步思考结果如何连接到现场改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0489","seq":489,"level":"N1","type":"主词条","word":"介護","kana":"かいご","pos":"[名·他動3]","accent":"①","meaning":"护理","example":"介護した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“护理”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n介護した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“护理”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0490","seq":490,"level":"N1","type":"主词条","word":"回収","kana":"かいしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"回收；收回","example":"初めて回収する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“回收；收回”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて回収する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“回收；收回”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0491","seq":491,"level":"N1","type":"主词条","word":"改修","kana":"かいしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"改建，修复","example":"改修の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“改建，修复”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n改修の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“改建，修复”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0492","seq":492,"level":"N1","type":"主词条","word":"解除","kana":"かいじょ","pos":"[名·他動3]","accent":"①","meaning":"解除","example":"彼は解除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“解除”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は解除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“解除”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0493","seq":493,"level":"N1","type":"主词条","word":"会心","kana":"かいしん","pos":"[名]","accent":"⓪","meaning":"满意，得意","example":"会心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“满意，得意”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n会心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“满意，得意”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0494","seq":494,"level":"N1","type":"主词条","word":"害する","kana":"がいする","pos":"[他動3]","accent":"③","meaning":"伤害，损害；妨碍","example":"相手を害するような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用让对方感到“伤害，损害；妨碍”的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を害するような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用让对方感到“伤害，损害；妨碍”的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0495","seq":495,"level":"N1","type":"主词条","word":"快晴","kana":"かいせい","pos":"[名]","accent":"⓪","meaning":"天空晴朗，大晴天","example":"突然の快晴で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“天空晴朗，大晴天”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の快晴で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“天空晴朗，大晴天”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0496","seq":496,"level":"N1","type":"主词条","word":"概説","kana":"がいせつ","pos":"[名·他動3]","accent":"⓪","meaning":"概述，概要","example":"チームは概説する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“概述，概要”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは概説する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“概述，概要”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0497","seq":497,"level":"N1","type":"主词条","word":"階層","kana":"かいそう","pos":"[名]","accent":"⓪","meaning":"阶层","example":"社会の階層によって教育機会に差が出ないよう、自治体は奨学金制度の拡充を検討している。","exampleZh":"为避免社会阶层导致教育机会差异，地方政府正在研究扩大助学金制度。","note":"例：\n社会の階層によって教育機会に差が出ないよう、自治体は奨学金制度の拡充を検討している。\n译：为避免社会阶层导致教育机会差异，地方政府正在研究扩大助学金制度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0498","seq":498,"level":"N1","type":"主词条","word":"回送","kana":"かいそう","pos":"[名·他動3]","accent":"⓪","meaning":"转送，转寄；（开空车）回车库","example":"初めて回送する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“转送，转寄；回车库”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて回送する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“转送，转寄；回车库”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0499","seq":499,"level":"N1","type":"主词条","word":"海賊版","kana":"かいぞくばん","pos":"[名]","accent":"⓪","meaning":"盗版","example":"海賊版の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“盗版”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n海賊版の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“盗版”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0500","seq":500,"level":"N1","type":"主词条","word":"開拓","kana":"かいたく","pos":"[名·他動3]","accent":"⓪","meaning":"开垦；开拓","example":"地方の小さな企業が海外市場を開拓するには、現地の文化を理解した人材が欠かせない。","exampleZh":"地方小企业要开拓海外市场，熟悉当地文化的人才不可或缺。","note":"例：\n地方の小さな企業が海外市場を開拓するには、現地の文化を理解した人材が欠かせない。\n译：地方小企业要开拓海外市场，熟悉当地文化的人才不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0501","seq":501,"level":"N1","type":"主词条","word":"快諾","kana":"かいだく","pos":"[名·他動3]","accent":"⓪","meaning":"欣然允诺","example":"急な登壇依頼にも、教授は学生のためになるならと快諾してくれた。","exampleZh":"面对突然的上台请求，教授说只要对学生有帮助就欣然答应了。","note":"例：\n急な登壇依頼にも、教授は学生のためになるならと快諾してくれた。\n译：面对突然的上台请求，教授说只要对学生有帮助就欣然答应了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0502","seq":502,"level":"N1","type":"主词条","word":"改定","kana":"かいてい","pos":"[名·他動3]","accent":"⓪","meaning":"重新规定","example":"改定する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“重新规定”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n改定する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“重新规定”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0503","seq":503,"level":"N1","type":"主词条","word":"改訂","kana":"かいてい","pos":"[名·他動3]","accent":"⓪","meaning":"修订","example":"改訂する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“修订”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n改訂する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“修订”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0504","seq":504,"level":"N1","type":"主词条","word":"街道","kana":"かいどう","pos":"[名]","accent":"⓪③","meaning":"大道，主要道路","example":"担当者は街道の位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。","exampleZh":"负责人不仅确认“大道，主要道路”的位置，也确认了使用者行走路线和夜间安全性。","note":"例：\n担当者は街道の位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。\n译：负责人不仅确认“大道，主要道路”的位置，也确认了使用者行走路线和夜间安全性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0505","seq":505,"level":"N1","type":"主词条","word":"該当","kana":"がいとう","pos":"[名·自動3]","accent":"⓪","meaning":"符合","example":"該当してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“符合”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n該当してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“符合”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0506","seq":506,"level":"N1","type":"主词条","word":"介入","kana":"かいにゅう","pos":"[名·自動3]","accent":"⓪","meaning":"介入，干涉","example":"介入した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“介入，干涉”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n介入した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“介入，干涉”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0507","seq":507,"level":"N1","type":"主词条","word":"概念","kana":"がいねん","pos":"[名]","accent":"①","meaning":"概念","example":"概念が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“概念”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n概念が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“概念”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0508","seq":508,"level":"N1","type":"主词条","word":"外泊","kana":"がいはく","pos":"[名·自動3]","accent":"⓪","meaning":"外宿，夜不归宿","example":"無断で外泊した学生に対し、寮の管理人は規則だけでなく安全面の理由も丁寧に伝えた。","exampleZh":"对于未经许可外宿的学生，宿舍管理员不仅讲明规章，也细致说明了安全方面的理由。","note":"例：\n無断で外泊した学生に対し、寮の管理人は規則だけでなく安全面の理由も丁寧に伝えた。\n译：对于未经许可外宿的学生，宿舍管理员不仅讲明规章，也细致说明了安全方面的理由。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0509","seq":509,"level":"N1","type":"主词条","word":"回避","kana":"かいひ","pos":"[名·他動3]","accent":"①⓪","meaning":"回避；推卸","example":"事故を回避するには、慣れた作業ほど手順を声に出して確認することが重要だ。","exampleZh":"为了避免事故，越是熟悉的作业越要出声确认步骤。","note":"例：\n事故を回避するには、慣れた作業ほど手順を声に出して確認することが重要だ。\n译：为了避免事故，越是熟悉的作业越要出声确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0510","seq":510,"level":"N1","type":"主词条","word":"介抱","kana":"かいほう","pos":"[名·他動3]","accent":"①","meaning":"看护，照顾","example":"介抱する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“看护，照顾”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n介抱する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“看护，照顾”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0511","seq":511,"level":"N1","type":"主词条","word":"解剖","kana":"かいぼう","pos":"[名·他動3]","accent":"⓪","meaning":"解剖","example":"解剖する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“解剖”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n解剖する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“解剖”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0512","seq":512,"level":"N1","type":"主词条","word":"垣間見る","kana":"かいまみる","pos":"[他動2]","accent":"④","meaning":"窥视，偷看","example":"無理に垣間見るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“窥视，偷看”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に垣間見るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“窥视，偷看”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0513","seq":513,"level":"N1","type":"主词条","word":"皆無","kana":"かいむ","pos":"[名·ナ形]","accent":"①","meaning":"毫无","example":"皆無な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“毫无”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n皆無な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“毫无”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0514","seq":514,"level":"N1","type":"主词条","word":"買い求める","kana":"かいもとめる","pos":"[他動2]","accent":"⑤","meaning":"购买，收购，求购","example":"買い求める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“购买，收购，求购”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n買い求める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“购买，收购，求购”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0515","seq":515,"level":"N1","type":"主词条","word":"概要","kana":"がいよう","pos":"[名]","accent":"⓪","meaning":"概要","example":"概要の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“概要”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n概要の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“概要”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0516","seq":516,"level":"N1","type":"主词条","word":"快楽","kana":"かいらく","pos":"[名]","accent":"⓪①","meaning":"快乐","example":"快楽の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“快乐”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n快楽の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“快乐”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0517","seq":517,"level":"N1","type":"主词条","word":"回覧","kana":"かいらん","pos":"[名·他動3]","accent":"⓪","meaning":"传阅","example":"重要な通知は全員が確認できるよう、紙の資料と電子版の両方で回覧した。","exampleZh":"为了让所有人都能确认，重要通知同时用纸质资料和电子版传阅。","note":"例：\n重要な通知は全員が確認できるよう、紙の資料と電子版の両方で回覧した。\n译：为了让所有人都能确认，重要通知同时用纸质资料和电子版传阅。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0518","seq":518,"level":"N1","type":"主词条","word":"改良","kana":"かいりょう","pos":"[名·他動3]","accent":"⓪","meaning":"改良","example":"誤りを改良する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。","exampleZh":"在“改良”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","note":"例：\n誤りを改良する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。\n译：在“改良”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0519","seq":519,"level":"N1","type":"主词条","word":"回路","kana":"かいろ","pos":"[名]","accent":"①","meaning":"回路，线路","example":"回路をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“回路，线路”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n回路をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“回路，线路”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0520","seq":520,"level":"N1","type":"主词条","word":"〜交う","kana":"〜かう","pos":"[接尾]","accent":"","meaning":"相互","example":"朝の駅前では会社員や学生が行き交い、狭い歩道では誘導員が事故を防ぐために声をかけている。","exampleZh":"早晨的车站前，公司职员和学生来往穿梭，狭窄人行道上引导员为防止事故不断提醒。","note":"例：\n朝の駅前では会社員や学生が行き交い、狭い歩道では誘導員が事故を防ぐために声をかけている。\n译：早晨的车站前，公司职员和学生来往穿梭，狭窄人行道上引导员为防止事故不断提醒。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0521","seq":521,"level":"N1","type":"主词条","word":"カウンセラー","kana":"かうんせらー (counselor)","pos":"[名]","accent":"②①","meaning":"心理咨询师","example":"カウンセラーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“心理咨询师”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nカウンセラーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“心理咨询师”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0522","seq":522,"level":"N1","type":"主词条","word":"顧みる","kana":"かえりみる","pos":"[他動2]","accent":"④","meaning":"回头看；回顾，反省","example":"顧みる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“回头看；回顾，反省”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n顧みる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“回头看；回顾，反省”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0523","seq":523,"level":"N1","type":"主词条","word":"省みる","kana":"かえりみる","pos":"[他動2]","accent":"④","meaning":"反省，自问","example":"無理に省みるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“反省，自问”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に省みるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“反省，自问”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0524","seq":524,"level":"N1","type":"主词条","word":"顔立ち","kana":"かおだち","pos":"[名]","accent":"⓪","meaning":"容貌，五官","example":"顔立ちとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“容貌，五官”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n顔立ちとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“容貌，五官”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0525","seq":525,"level":"N1","type":"主词条","word":"顔負け","kana":"かおまけ","pos":"[名·自動3]","accent":"⓪","meaning":"相形见绌，甘拜下风","example":"顔負けした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“相形见绌，甘拜下风”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n顔負けした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“相形见绌，甘拜下风”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0526","seq":526,"level":"N1","type":"主词条","word":"掲げる","kana":"かかげる","pos":"[他動2]","accent":"⓪③","meaning":"高举；刊登；提出","example":"掲げる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“高举；刊登”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n掲げる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“高举；刊登”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0527","seq":527,"level":"N1","type":"主词条","word":"屈む","kana":"かがむ","pos":"[自動1]","accent":"⓪","meaning":"弯曲，蹲下","example":"屈む前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“弯曲，蹲下”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n屈む前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“弯曲，蹲下”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0528","seq":528,"level":"N1","type":"主词条","word":"屈める","kana":"かがめる","pos":"[他動2]","accent":"⓪","meaning":"弯腰","example":"無理に屈めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“弯腰”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に屈めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“弯腰”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0529","seq":529,"level":"N1","type":"主词条","word":"輝かしい","kana":"かがやかしい","pos":"[イ形]","accent":"⑤","meaning":"辉煌","example":"彼の輝かしい実績の陰には、失敗を記録し続けた地道な努力があった。","exampleZh":"他辉煌实绩的背后，是不断记录失败的踏实努力。","note":"例：\n彼の輝かしい実績の陰には、失敗を記録し続けた地道な努力があった。\n译：他辉煌实绩的背后，是不断记录失败的踏实努力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0530","seq":530,"level":"N1","type":"主词条","word":"果敢","kana":"かかん","pos":"[名·ナ形]","accent":"⓪","meaning":"果敢，勇敢","example":"果敢な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“果敢，勇敢”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n果敢な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“果敢，勇敢”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0531","seq":531,"level":"N1","type":"主词条","word":"掻き回す","kana":"かきまわす","pos":"[他動1]","accent":"⓪④","meaning":"搅拌；搅乱","example":"掻き回す前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“搅拌；搅乱”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n掻き回す前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“搅拌；搅乱”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0532","seq":532,"level":"N1","type":"主词条","word":"かき乱す","kana":"かきみだす","pos":"[他動1]","accent":"④⓪","meaning":"搅乱，弄乱；扰乱","example":"無理にかき乱すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“搅乱，弄乱；扰乱”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理にかき乱すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“搅乱，弄乱；扰乱”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0533","seq":533,"level":"N1","type":"主词条","word":"格上げ","kana":"かくあげ","pos":"[名·他動3]","accent":"⓪","meaning":"升级，升格","example":"格上げする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“升级，升格”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n格上げする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“升级，升格”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0534","seq":534,"level":"N1","type":"主词条","word":"核家族","kana":"かくかぞく","pos":"[名]","accent":"③","meaning":"小家庭（由父母和未婚子女组成的）","example":"核家族が増えるにつれて、地域で子育てを支える仕組みの重要性が改めて見直されている。","exampleZh":"随着小家庭增多，地区共同支援育儿机制的重要性再次被重新审视。","note":"例：\n核家族が増えるにつれて、地域で子育てを支える仕組みの重要性が改めて見直されている。\n译：随着小家庭增多，地区共同支援育儿机制的重要性再次被重新审视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0535","seq":535,"level":"N1","type":"主词条","word":"学芸","kana":"がくげい","pos":"[名]","accent":"⓪②","meaning":"学艺，学问","example":"学芸をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“学艺，学问”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n学芸をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“学艺，学问”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0536","seq":536,"level":"N1","type":"主词条","word":"格差","kana":"かくさ","pos":"[名]","accent":"①","meaning":"差距，差别","example":"格差を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“差距，差别”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n格差を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“差距，差别”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0537","seq":537,"level":"N1","type":"主词条","word":"画策","kana":"かくさく","pos":"[名·他動3]","accent":"⓪","meaning":"策划，策动","example":"画策した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“策划，策动”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n画策した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“策划，策动”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0538","seq":538,"level":"N1","type":"主词条","word":"拡散","kana":"かくさん","pos":"[名·自動3]","accent":"⓪","meaning":"扩散","example":"拡散するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“扩散”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n拡散するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“扩散”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0539","seq":539,"level":"N1","type":"主词条","word":"隔日","kana":"かくじつ","pos":"[名]","accent":"⓪","meaning":"隔日","example":"隔日を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“隔日”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n隔日を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“隔日”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0540","seq":540,"level":"N1","type":"主词条","word":"確信","kana":"かくしん","pos":"[名·他動3]","accent":"⓪","meaning":"确信","example":"彼は確信を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“确信”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は確信を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“确信”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0541","seq":541,"level":"N1","type":"主词条","word":"革新","kana":"かくしん","pos":"[名·他動3]","accent":"⓪","meaning":"革新","example":"伝統産業を守るには、古い技術を受け継ぐだけでなく、生産方法の革新も欠かせない。","exampleZh":"要守护传统产业，不仅要继承旧技术，也离不开生产方式的革新。","note":"例：\n伝統産業を守るには、古い技術を受け継ぐだけでなく、生産方法の革新も欠かせない。\n译：要守护传统产业，不仅要继承旧技术，也离不开生产方式的革新。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0542","seq":542,"level":"N1","type":"主词条","word":"覚醒剤","kana":"かくせいざい","pos":"[名]","accent":"③⓪","meaning":"兴奋剂","example":"覚醒剤をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“兴奋剂”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n覚醒剤をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“兴奋剂”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0543","seq":543,"level":"N1","type":"主词条","word":"確たる","kana":"かくたる","pos":"[連体]","accent":"①","meaning":"确凿","example":"確たる証拠がないまま相手を責めれば、組織全体の信頼を失いかねない。","exampleZh":"若在没有确凿证据的情况下责备对方，可能会损害整个组织的信任。","note":"例：\n確たる証拠がないまま相手を責めれば、組織全体の信頼を失いかねない。\n译：若在没有确凿证据的情况下责备对方，可能会损害整个组织的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0544","seq":544,"level":"N1","type":"主词条","word":"格段","kana":"かくだん","pos":"[名·ナ形]","accent":"⓪","meaning":"格外，特别","example":"周囲から格段だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“格外，特别”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から格段だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“格外，特别”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0545","seq":545,"level":"N1","type":"主词条","word":"楽団","kana":"がくだん","pos":"[名]","accent":"⓪","meaning":"乐团","example":"楽団を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“乐团”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n楽団を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“乐团”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0546","seq":546,"level":"N1","type":"主词条","word":"確定","kana":"かくてい","pos":"[名·自動3]","accent":"⓪","meaning":"确定","example":"確定した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“确定”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n確定した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“确定”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0547","seq":547,"level":"N1","type":"主词条","word":"カクテル","kana":"かくてる (cocktail)","pos":"[名]","accent":"①","meaning":"鸡尾酒","example":"カクテルを選ぶとき、彼女は値段の安さだけでなく、材料の産地や保存方法も確かめるようにしている。","exampleZh":"选择鸡尾酒时，她不仅看价格是否便宜，也会确认原料产地和保存方法。","note":"例：\nカクテルを選ぶとき、彼女は値段の安さだけでなく、材料の産地や保存方法も確かめるようにしている。\n译：选择鸡尾酒时，她不仅看价格是否便宜，也会确认原料产地和保存方法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0548","seq":548,"level":"N1","type":"主词条","word":"格別","kana":"かくべつ","pos":"[副·ナ形]","accent":"⓪","meaning":"特别，格外","example":"この料理は格別においしく、旬の素材を惜しまず使っていることが一口で伝わってくる。","exampleZh":"这道菜格外美味，只尝一口就能感受到它毫不吝惜地使用了当季食材。","note":"例：\nこの料理は格別においしく、旬の素材を惜しまず使っていることが一口で伝わってくる。\n译：这道菜格外美味，只尝一口就能感受到它毫不吝惜地使用了当季食材。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0549","seq":549,"level":"N1","type":"主词条","word":"確保","kana":"かくほ","pos":"[名·他動3]","accent":"①","meaning":"确保","example":"災害時に水と電源を確保できるよう、自治体は避難所の設備を見直した。","exampleZh":"为了在灾害时确保水和电源，自治体重新审视了避难所设备。","note":"例：\n災害時に水と電源を確保できるよう、自治体は避難所の設備を見直した。\n译：为了在灾害时确保水和电源，自治体重新审视了避难所设备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0550","seq":550,"level":"N1","type":"主词条","word":"確立","kana":"かくりつ","pos":"[名·他動3]","accent":"⓪","meaning":"确立","example":"確立する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“确立”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n確立する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“确立”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0551","seq":551,"level":"N1","type":"主词条","word":"隠れ家","kana":"かくれが","pos":"[名]","accent":"③","meaning":"隐居之处；隐匿处","example":"都会の片隅にある小さな喫茶店は、彼にとって仕事の悩みを一度忘れられる隠れ家のような場所だった。","exampleZh":"位于都市角落的小咖啡馆，对他来说像是能暂时忘记工作烦恼的隐秘居所。","note":"例：\n都会の片隅にある小さな喫茶店は、彼にとって仕事の悩みを一度忘れられる隠れ家のような場所だった。\n译：位于都市角落的小咖啡馆，对他来说像是能暂时忘记工作烦恼的隐秘居所。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0552","seq":552,"level":"N1","type":"主词条","word":"掛け〜","kana":"かけ〜","pos":"[接頭]","accent":"","meaning":"借","example":"掛け金を毎月少しずつ積み立てておけば、急な出費が必要になったときにも慌てず対応できる。","exampleZh":"如果每月一点点积攒保险费或保证金，即使突然需要支出，也能不慌张地应对。","note":"例：\n掛け金を毎月少しずつ積み立てておけば、急な出費が必要になったときにも慌てず対応できる。\n译：如果每月一点点积攒保险费或保证金，即使突然需要支出，也能不慌张地应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0553","seq":553,"level":"N1","type":"主词条","word":"駆け足","kana":"かけあし","pos":"[名·自動3]","accent":"②","meaning":"快跑","example":"予期せず駆け足した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“快跑”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず駆け足した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“快跑”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0554","seq":554,"level":"N1","type":"主词条","word":"過激","kana":"かげき","pos":"[名·ナ形]","accent":"⓪","meaning":"过激，激进","example":"周囲から過激だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“过激，激进”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から過激だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“过激，激进”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0555","seq":555,"level":"N1","type":"主词条","word":"架け橋","kana":"かけばし","pos":"[名]","accent":"②","meaning":"桥梁","example":"架け橋を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“桥梁”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\n架け橋を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“桥梁”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0556","seq":556,"level":"N1","type":"主词条","word":"賭ける","kana":"かける","pos":"[他動2]","accent":"②","meaning":"赌博；冒险做，豁上","example":"賭ける場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“赌博；冒险做，豁上”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n賭ける場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“赌博；冒险做，豁上”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0557","seq":557,"level":"N1","type":"主词条","word":"加工","kana":"かこう","pos":"[名·他動3]","accent":"⓪","meaning":"加工","example":"加工する前に、彼は材料や手順を確認し、仕上がりにばらつきが出ないよう作業を進めた。","exampleZh":"加工之前，他确认了材料和步骤，并推进作业，以免成品质量出现差异。","note":"例：\n加工する前に、彼は材料や手順を確認し、仕上がりにばらつきが出ないよう作業を進めた。\n译：加工之前，他确认了材料和步骤，并推进作业，以免成品质量出现差异。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0558","seq":558,"level":"N1","type":"主词条","word":"囲う","kana":"かこう","pos":"[他動1]","accent":"⓪","meaning":"围起来；贮藏","example":"囲う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“围起来；贮藏”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n囲う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“围起来；贮藏”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0559","seq":559,"level":"N1","type":"主词条","word":"過酷","kana":"かこく","pos":"[名·ナ形]","accent":"⓪","meaning":"过于苛刻，过于残酷","example":"周囲から過酷だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“过于苛刻，过于残酷”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から過酷だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“过于苛刻，过于残酷”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0560","seq":560,"level":"N1","type":"主词条","word":"託ける","kana":"かこつける","pos":"[自動2]","accent":"⓪④","meaning":"找借口","example":"忙しさに託けて連絡を怠れば、相手は軽んじられたと感じてしまう。","exampleZh":"如果借口忙碌而怠于联络，对方会觉得自己被轻视。","note":"例：\n忙しさに託けて連絡を怠れば、相手は軽んじられたと感じてしまう。\n译：如果借口忙碌而怠于联络，对方会觉得自己被轻视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0561","seq":561,"level":"N1","type":"主词条","word":"嵩張る","kana":"かさばる","pos":"[自動1]","accent":"③","meaning":"体积大","example":"嵩張るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“体积大”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n嵩張るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“体积大”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0562","seq":562,"level":"N1","type":"主词条","word":"嵩む","kana":"かさむ","pos":"[自動1]","accent":"⓪②","meaning":"（体积）增大；（费用）增多","example":"嵩むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“增大；增多”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n嵩むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“增大；增多”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0563","seq":563,"level":"N1","type":"主词条","word":"姦しい","kana":"かしましい","pos":"[イ形]","accent":"④","meaning":"吵闹的，嘈杂的","example":"姦しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“吵闹的，嘈杂的”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n姦しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“吵闹的，嘈杂的”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0564","seq":564,"level":"N1","type":"主词条","word":"箇条書き","kana":"かじょうがき","pos":"[名]","accent":"⓪","meaning":"分条写","example":"箇条書きをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“分条写”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n箇条書きをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“分条写”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0565","seq":565,"level":"N1","type":"主词条","word":"頭","kana":"かしら","pos":"[名]","accent":"③","meaning":"头目，首领；第一，最初","example":"頭の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“头目，首领；第一，最初”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n頭の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“头目，首领；第一，最初”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0566","seq":566,"level":"N1","type":"主词条","word":"かすか","kana":"かすか","pos":"[ナ形]","accent":"①","meaning":"模糊；略微","example":"かすかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“模糊；略微”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nかすかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“模糊；略微”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0567","seq":567,"level":"N1","type":"主词条","word":"霞む","kana":"かすむ","pos":"[自動1]","accent":"①","meaning":"朦胧，看不清；不显眼","example":"霞む前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“朦胧，看不清；不显眼”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n霞む前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“朦胧，看不清；不显眼”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0568","seq":568,"level":"N1","type":"主词条","word":"掠る","kana":"かする","pos":"[他動1]","accent":"②","meaning":"擦过","example":"掠る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“擦过”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n掠る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“擦过”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0569","seq":569,"level":"N1","type":"主词条","word":"課する","kana":"かする","pos":"[他動3]","accent":"②","meaning":"课，使负担","example":"課することの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“课，使负担”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n課することの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“课，使负担”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0570","seq":570,"level":"N1","type":"主词条","word":"仮説","kana":"かせつ","pos":"[名]","accent":"⓪","meaning":"假说","example":"仮説が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“假说”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n仮説が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“假说”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0571","seq":571,"level":"N1","type":"主词条","word":"河川","kana":"かせん","pos":"[名]","accent":"①","meaning":"河川","example":"河川の水位が急に上がったため、自治体は夜のうちに避難情報を出し、住民に警戒を呼びかけた。","exampleZh":"河流水位突然上升，地方政府连夜发布避难信息，呼吁居民提高警惕。","note":"例：\n河川の水位が急に上がったため、自治体は夜のうちに避難情報を出し、住民に警戒を呼びかけた。\n译：河流水位突然上升，地方政府连夜发布避难信息，呼吁居民提高警惕。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0572","seq":572,"level":"N1","type":"主词条","word":"過疎","kana":"かそ","pos":"[名·ナ形]","accent":"①","meaning":"（人口）过于稀少","example":"過疎が進む地域では、交通手段の不足が通院や買い物の大きな負担になっている。","exampleZh":"在人口稀少不断加剧的地区，交通手段不足成了就医和购物的巨大负担。","note":"例：\n過疎が進む地域では、交通手段の不足が通院や買い物の大きな負担になっている。\n译：在人口稀少不断加剧的地区，交通手段不足成了就医和购物的巨大负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0573","seq":573,"level":"N1","type":"主词条","word":"片〜","kana":"かた〜","pos":"[接頭]","accent":"","meaning":"一方；一点，稍许","example":"片手で荷物を支えながら資料を渡そうとしたため、彼はうっかり大事な書類を落としてしまった。","exampleZh":"他一边单手撑着行李一边试图递资料，结果不小心把重要文件掉了。","note":"例：\n片手で荷物を支えながら資料を渡そうとしたため、彼はうっかり大事な書類を落としてしまった。\n译：他一边单手撑着行李一边试图递资料，结果不小心把重要文件掉了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0574","seq":574,"level":"N1","type":"主词条","word":"片思い","kana":"かたおもい","pos":"[名]","accent":"③","meaning":"单相思","example":"片思いを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“单相思”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n片思いを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“单相思”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0575","seq":575,"level":"N1","type":"主词条","word":"肩書き","kana":"かたがき","pos":"[名]","accent":"⓪","meaning":"头衔，职位","example":"肩書きの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“头衔，职位”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n肩書きの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“头衔，职位”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0576","seq":576,"level":"N1","type":"主词条","word":"肩代わり","kana":"かたがわり","pos":"[名·他動3]","accent":"③","meaning":"债务、负担等转移","example":"初めて肩代わりする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“债务，负担等转移”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて肩代わりする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“债务，负担等转移”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0577","seq":577,"level":"N1","type":"主词条","word":"頑な","kana":"かたくな","pos":"[ナ形]","accent":"⓪","meaning":"顽固，固执","example":"頑なな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“顽固，固执”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n頑なな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“顽固，固执”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0578","seq":578,"level":"N1","type":"主词条","word":"形作る","kana":"かたちづくる","pos":"[他動1]","accent":"⑤","meaning":"形成，构成","example":"無理に形作るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“形成，构成”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に形作るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“形成，构成”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0579","seq":579,"level":"N1","type":"主词条","word":"傍ら","kana":"かたわら","pos":"[名]","accent":"⓪④","meaning":"旁边；一边……一边……","example":"傍らをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“旁边；一边一边”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n傍らをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“旁边；一边一边”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0580","seq":580,"level":"N1","type":"主词条","word":"勝ち組","kana":"かちぐみ","pos":"[名]","accent":"⓪","meaning":"赢家，获胜方","example":"勝ち組を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“赢家，获胜方”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n勝ち組を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“赢家，获胜方”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0581","seq":581,"level":"N1","type":"主词条","word":"かつ","kana":"かつ","pos":"[副]","accent":"①","meaning":"并且，而且","example":"報告書は正確でかつ読みやすくまとめられており、初めて案件に触れる人にも全体像がつかみやすい。","exampleZh":"报告书准确且整理得易读，即使是第一次接触案件的人也容易把握整体情况。","note":"例：\n報告書は正確でかつ読みやすくまとめられており、初めて案件に触れる人にも全体像がつかみやすい。\n译：报告书准确且整理得易读，即使是第一次接触案件的人也容易把握整体情况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0582","seq":582,"level":"N1","type":"主词条","word":"画期的","kana":"かっきてき","pos":"[ナ形]","accent":"⓪","meaning":"划时代的","example":"画期的な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“划时代的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n画期的な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“划时代的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0583","seq":583,"level":"N1","type":"主词条","word":"がっくり","kana":"がっくり","pos":"[副·自動3]","accent":"③","meaning":"突然无力的弯曲；失望，颓丧","example":"最終面接で落ちたと聞いて彼はがっくり肩を落としたが、翌日には次の応募先を探し始めた。","exampleZh":"听说最终面试落选后，他失望地垂下肩膀，但第二天就开始寻找下一个应聘单位。","note":"例：\n最終面接で落ちたと聞いて彼はがっくり肩を落としたが、翌日には次の応募先を探し始めた。\n译：听说最终面试落选后，他失望地垂下肩膀，但第二天就开始寻找下一个应聘单位。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0584","seq":584,"level":"N1","type":"主词条","word":"がっしり","kana":"がっしり","pos":"[副·自動3]","accent":"③","meaning":"结实，健壮","example":"彼はがっしりした体格で、重い機材を運ぶ現場でも周囲に安心感を与えている。","exampleZh":"他体格结实，即使在搬运沉重器材的现场也能给周围人安心感。","note":"例：\n彼はがっしりした体格で、重い機材を運ぶ現場でも周囲に安心感を与えている。\n译：他体格结实，即使在搬运沉重器材的现场也能给周围人安心感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0585","seq":585,"level":"N1","type":"主词条","word":"活性化","kana":"かっせいか","pos":"[名·他動3]","accent":"⓪","meaning":"激活","example":"初めて活性化する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“激活”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて活性化する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“激活”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0586","seq":586,"level":"N1","type":"主词条","word":"合致","kana":"がっち","pos":"[名·自動3]","accent":"⓪","meaning":"合乎，符合","example":"合致した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“合乎，符合”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n合致した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“合乎，符合”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0587","seq":587,"level":"N1","type":"主词条","word":"がっちり","kana":"がっちり","pos":"[副·自動3]","accent":"③","meaning":"结实，坚固；精明","example":"彼は大切な書類をがっちり抱え、混雑した駅の中でも決して手放さなかった。","exampleZh":"他紧紧抱着重要文件，即使在拥挤的车站里也绝不松手。","note":"例：\n彼は大切な書類をがっちり抱え、混雑した駅の中でも決して手放さなかった。\n译：他紧紧抱着重要文件，即使在拥挤的车站里也绝不松手。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0588","seq":588,"level":"N1","type":"主词条","word":"かつて","kana":"かつて","pos":"[副]","accent":"①","meaning":"曾经，过去","example":"かつて工場だった建物は、改修を経て地域の交流施設として再び人々に使われるようになった。","exampleZh":"曾经是工厂的建筑经过改修后，再次作为地区交流设施为人们所使用。","note":"例：\nかつて工場だった建物は、改修を経て地域の交流施設として再び人々に使われるようになった。\n译：曾经是工厂的建筑经过改修后，再次作为地区交流设施为人们所使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0589","seq":589,"level":"N1","type":"主词条","word":"かつてない","kana":"かつてない","pos":"[イ形]","accent":"④","meaning":"未曾有过的","example":"かつてない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“未曾有过的”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nかつてない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“未曾有过的”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0590","seq":590,"level":"N1","type":"主词条","word":"合点","kana":"がってん","pos":"[名·自動3]","accent":"③","meaning":"认可，同意","example":"合点してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“认可，同意”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n合点してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“认可，同意”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0591","seq":591,"level":"N1","type":"主词条","word":"活発","kana":"かっぱつ","pos":"[名·ナ形]","accent":"⓪","meaning":"活泼，活跃","example":"一度活発だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“活泼，活跃”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度活発だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“活泼，活跃”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0592","seq":592,"level":"N1","type":"主词条","word":"カップル","kana":"かっぷる (couple)","pos":"[名]","accent":"①","meaning":"情侣；一对男女","example":"カップルが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“情侣；一对男女”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nカップルが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“情侣；一对男女”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0593","seq":593,"level":"N1","type":"主词条","word":"合併","kana":"がっぺい","pos":"[名·自他動3]","accent":"⓪","meaning":"合并","example":"合併した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“合并”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n合併した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“合并”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0594","seq":594,"level":"N1","type":"主词条","word":"カテゴリー","kana":"かてごりー","pos":"[名]","accent":"②","meaning":"范畴，种类","example":"カテゴリーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“范畴，种类”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nカテゴリーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“范畴，种类”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0595","seq":595,"level":"N1","type":"主词条","word":"稼働","kana":"かどう","pos":"[名·自動3]","accent":"⓪","meaning":"劳动；（机器）运转","example":"稼働してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“劳动；运转”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n稼働してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“劳动；运转”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0596","seq":596,"level":"N1","type":"主词条","word":"適う","kana":"かなう","pos":"[自動1]","accent":"②","meaning":"符合，合乎","example":"適うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“符合，合乎”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n適うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“符合，合乎”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0597","seq":597,"level":"N1","type":"主词条","word":"敵う","kana":"かなう","pos":"[自動1]","accent":"②","meaning":"做得到；比得上","example":"敵う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“做得到；比得上”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n敵う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“做得到；比得上”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0598","seq":598,"level":"N1","type":"主词条","word":"叶う","kana":"かなう","pos":"[自動1]","accent":"②","meaning":"实现，达到","example":"叶うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“实现，达到”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n叶うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“实现，达到”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0599","seq":599,"level":"N1","type":"主词条","word":"叶える","kana":"かなえる","pos":"[他動2]","accent":"③","meaning":"实现","example":"叶えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“实现”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n叶えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“实现”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0600","seq":600,"level":"N1","type":"主词条","word":"金槌","kana":"かなづち","pos":"[名]","accent":"③⓪","meaning":"铁锤；不会游泳的人","example":"金槌として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“铁锤；不会游泳的人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n金槌として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“铁锤；不会游泳的人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0601","seq":601,"level":"N1","type":"主词条","word":"かなわない","kana":"かなわない","pos":"[イ形]","accent":"③","meaning":"不能实现；受不了，经不起","example":"かなわない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“不能实现；受不了，经不起”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nかなわない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“不能实现；受不了，经不起”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0602","seq":602,"level":"N1","type":"主词条","word":"加入","kana":"かにゅう","pos":"[名·自動3]","accent":"⓪","meaning":"加入，参加","example":"加入する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“加入，参加”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n加入する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“加入，参加”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0603","seq":603,"level":"N1","type":"主词条","word":"兼ね備える","kana":"かねそなえる","pos":"[他動2]","accent":"⑤","meaning":"兼备","example":"相手に何かを兼ね備えるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“兼备”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを兼ね備えるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“兼备”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0604","seq":604,"level":"N1","type":"主词条","word":"かねて","kana":"かねて","pos":"[副]","accent":"①","meaning":"老早；早先","example":"かねてから問題視されていた通学路の安全対策が、住民の要望を受けてようやく実施された。","exampleZh":"早就被视为问题的通学路安全对策，在居民提出要求后终于得以实施。","note":"例：\nかねてから問題視されていた通学路の安全対策が、住民の要望を受けてようやく実施された。\n译：早就被视为问题的通学路安全对策，在居民提出要求后终于得以实施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0605","seq":605,"level":"N1","type":"主词条","word":"庇う","kana":"かばう","pos":"[他動1]","accent":"②","meaning":"保护；包庇","example":"庇うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“保护；包庇”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n庇うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“保护；包庇”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0606","seq":606,"level":"N1","type":"主词条","word":"過敏","kana":"かびん","pos":"[名·ナ形]","accent":"⓪","meaning":"过敏，过于敏感","example":"一度過敏だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“过敏，过于敏感”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度過敏だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“过敏，过于敏感”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0607","seq":607,"level":"N1","type":"主词条","word":"〜気触れ","kana":"〜かぶれ","pos":"[接尾]","accent":"","meaning":"受……强烈影响","example":"彼は西洋かぶれの服装を好むだけでなく、考え方まで周囲に押しつけようとして反発を招いた。","exampleZh":"他不仅喜欢西化的服装，甚至还想把思维方式强加给周围人，因而招致反感。","note":"例：\n彼は西洋かぶれの服装を好むだけでなく、考え方まで周囲に押しつけようとして反発を招いた。\n译：他不仅喜欢西化的服装，甚至还想把思维方式强加给周围人，因而招致反感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0608","seq":608,"level":"N1","type":"主词条","word":"気触れる","kana":"かぶれる","pos":"[自動2]","accent":"⓪","meaning":"皮肤红肿；沾染坏习惯，受影响","example":"気触れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“皮肤红肿；沾染坏习惯，受影响”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n気触れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“皮肤红肿；沾染坏习惯，受影响”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0609","seq":609,"level":"N1","type":"主词条","word":"花粉","kana":"かふん","pos":"[名]","accent":"⓪","meaning":"花粉","example":"花粉を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“花粉”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n花粉を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“花粉”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0610","seq":610,"level":"N1","type":"主词条","word":"花粉症","kana":"かふんしょう","pos":"[名]","accent":"⓪②","meaning":"花粉症","example":"研究者は花粉症の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“花粉症”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は花粉症の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“花粉症”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0611","seq":611,"level":"N1","type":"主词条","word":"過保護","kana":"かほご","pos":"[名]","accent":"②","meaning":"过度的保护","example":"過保護の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“过度的保护”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n過保護の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“过度的保护”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0612","seq":612,"level":"N1","type":"主词条","word":"カボチャ","kana":"かぼちゃ","pos":"[名]","accent":"⓪","meaning":"南瓜","example":"カボチャをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“南瓜”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nカボチャをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“南瓜”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0613","seq":613,"level":"N1","type":"主词条","word":"構え","kana":"かまえ","pos":"[名]","accent":"②③","meaning":"姿势，架势；构造，外观","example":"構えの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“姿势，架势；构造，外观”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n構えの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“姿势，架势；构造，外观”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0614","seq":614,"level":"N1","type":"主词条","word":"構える","kana":"かまえる","pos":"[他動2]","accent":"③","meaning":"成家，开店；摆出（某种态度或姿势）；捏造","example":"構えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“成家，开店；摆出”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n構えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“成家，开店；摆出”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0615","seq":615,"level":"N1","type":"主词条","word":"〜がましい","kana":"〜がましい","pos":"[接尾]","accent":"","meaning":"……似的","example":"言い訳がましい態度を続けるより、まず自分の確認不足を認めたほうが周囲の信頼を取り戻しやすい。","exampleZh":"与其一直摆出像是在找借口的态度，不如先承认自己确认不足，这样更容易重新赢得周围信任。","note":"例：\n言い訳がましい態度を続けるより、まず自分の確認不足を認めたほうが周囲の信頼を取り戻しやすい。\n译：与其一直摆出像是在找借口的态度，不如先承认自己确认不足，这样更容易重新赢得周围信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0616","seq":616,"level":"N1","type":"主词条","word":"加味","kana":"かみ","pos":"[名·他動3]","accent":"①","meaning":"加佐料；采纳","example":"チームは加味する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“加佐料；采纳”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは加味する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“加佐料；采纳”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0617","seq":617,"level":"N1","type":"主词条","word":"過密","kana":"かみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"过于密集","example":"過密な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“过于密集”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n過密な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“过于密集”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0618","seq":618,"level":"N1","type":"主词条","word":"カムバック","kana":"かむばっく (comeback)","pos":"[名·自動3]","accent":"③①","meaning":"复归，东山再起","example":"カムバックした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“复归，东山再起”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\nカムバックした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“复归，东山再起”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0619","seq":619,"level":"N1","type":"主词条","word":"加盟","kana":"かめい","pos":"[名·自動3]","accent":"⓪","meaning":"加盟","example":"予期せず加盟した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“加盟”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず加盟した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“加盟”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0620","seq":620,"level":"N1","type":"主词条","word":"醸し出す","kana":"かもしだす","pos":"[他動1]","accent":"④⓪","meaning":"造成，酿成，营造","example":"醸し出す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“造成，酿成，营造”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n醸し出す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“造成，酿成，营造”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0621","seq":621,"level":"N1","type":"主词条","word":"絡む","kana":"からむ","pos":"[自動1]","accent":"②","meaning":"牵涉","example":"絡む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“牵涉”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n絡む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“牵涉”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0622","seq":622,"level":"N1","type":"主词条","word":"駆られる","kana":"かられる","pos":"[自動2]","accent":"④⓪","meaning":"受……驱使","example":"駆られるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“受驱使”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n駆られるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“受驱使”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0623","seq":623,"level":"N1","type":"主词条","word":"仮","kana":"かり","pos":"[名]","accent":"⓪","meaning":"临时；虚假；假设","example":"まだ仮の予定なので、正式な日程が決まり次第、参加者全員に改めて連絡することになっている。","exampleZh":"目前还只是临时日程，所以正式日期一确定，就会再次通知全体参加者。","note":"例：\nまだ仮の予定なので、正式な日程が決まり次第、参加者全員に改めて連絡することになっている。\n译：目前还只是临时日程，所以正式日期一确定，就会再次通知全体参加者。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0624","seq":624,"level":"N1","type":"主词条","word":"カリスマ","kana":"かりすま","pos":"[名]","accent":"⓪","meaning":"领袖人物的感召力","example":"カリスマの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。","exampleZh":"“领袖人物的感召力”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","note":"例：\nカリスマの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。\n译：“领袖人物的感召力”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0625","seq":625,"level":"N1","type":"主词条","word":"仮に","kana":"かりに","pos":"[副]","accent":"⓪","meaning":"假如；姑且，暂时","example":"仮に計画が予定どおり進まなかったとしても、代替案を用意しておけば混乱は最小限に抑えられる。","exampleZh":"假如计划没有按预定推进，只要准备好替代方案，就能把混乱压到最低。","note":"例：\n仮に計画が予定どおり進まなかったとしても、代替案を用意しておけば混乱は最小限に抑えられる。\n译：假如计划没有按预定推进，只要准备好替代方案，就能把混乱压到最低。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0626","seq":626,"level":"N1","type":"主词条","word":"火力","kana":"かりょく","pos":"[名]","accent":"⓪①","meaning":"火力","example":"研究者は火力の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“火力”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は火力の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“火力”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0627","seq":627,"level":"N1","type":"主词条","word":"カルテ","kana":"かるて","pos":"[名]","accent":"①","meaning":"病历卡，诊断记录","example":"医師はカルテの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“病历卡，诊断记录”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師はカルテの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“病历卡，诊断记录”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0628","seq":628,"level":"N1","type":"主词条","word":"ガレージ","kana":"がれーじ (garage)","pos":"[名]","accent":"②①","meaning":"车库","example":"担当者はガレージの位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。","exampleZh":"负责人不仅确认“车库”的位置，也确认了使用者行走路线和夜间安全性。","note":"例：\n担当者はガレージの位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。\n译：负责人不仅确认“车库”的位置，也确认了使用者行走路线和夜间安全性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0629","seq":629,"level":"N1","type":"主词条","word":"かれこれ","kana":"かれこれ","pos":"[副]","accent":"①","meaning":"这呀那呀地；差不多","example":"この地域で暮らし始めてかれこれ十年になるが、祭りの前のにぎわいには今でも心が躍る。","exampleZh":"在这个地区生活差不多十年了，但节日前的热闹至今仍让人心潮跃动。","note":"例：\nこの地域で暮らし始めてかれこれ十年になるが、祭りの前のにぎわいには今でも心が躍る。\n译：在这个地区生活差不多十年了，但节日前的热闹至今仍让人心潮跃动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0630","seq":630,"level":"N1","type":"主词条","word":"嗄れる","kana":"かれる","pos":"[自動2]","accent":"⓪","meaning":"声音嘶哑","example":"嗄れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“声音嘶哑”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n嗄れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“声音嘶哑”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0631","seq":631,"level":"N1","type":"主词条","word":"涸れる","kana":"かれる","pos":"[自動2]","accent":"⓪","meaning":"干涸；（能力等）枯竭","example":"涸れるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“干涸；枯竭”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n涸れるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“干涸；枯竭”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0632","seq":632,"level":"N1","type":"主词条","word":"辛うじて","kana":"かろうじて","pos":"[副]","accent":"②⓪","meaning":"好不容易才，勉强","example":"終電には辛うじて間に合ったものの、彼は次から余裕を持って行動しようと反省した。","exampleZh":"虽然好不容易赶上了末班电车，但他反省说下次要留出余裕行动。","note":"例：\n終電には辛うじて間に合ったものの、彼は次から余裕を持って行動しようと反省した。\n译：虽然好不容易赶上了末班电车，但他反省说下次要留出余裕行动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0633","seq":633,"level":"N1","type":"主词条","word":"軽んじる","kana":"かろんじる","pos":"[他動2]","accent":"④","meaning":"轻视；不珍惜","example":"軽んじることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“轻视；不珍惜”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n軽んじることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“轻视；不珍惜”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0634","seq":634,"level":"N1","type":"主词条","word":"交わす","kana":"かわす","pos":"[他動1]","accent":"⓪","meaning":"交换；交叉；相互","example":"交わすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“交换；交叉”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n交わすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“交换；交叉”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0635","seq":635,"level":"N1","type":"主词条","word":"代わる代わる","kana":"かわるがわる","pos":"[副]","accent":"④","meaning":"交替，轮流","example":"参加者は代わる代わる意見を述べ、短い会議の中でも多角的な視点を出し合った。","exampleZh":"参加者轮流发表意见，即使会议时间很短，也提出了多角度的看法。","note":"例：\n参加者は代わる代わる意見を述べ、短い会議の中でも多角的な視点を出し合った。\n译：参加者轮流发表意见，即使会议时间很短，也提出了多角度的看法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0636","seq":636,"level":"N1","type":"主词条","word":"〜観","kana":"〜かん","pos":"[接尾]","accent":"","meaning":"……观","example":"彼の人生観は長い海外生活によって大きく変わり、仕事よりも家族との時間を重んじるようになった。","exampleZh":"他的人生观因长期海外生活发生很大变化，变得比工作更重视与家人相处的时间。","note":"例：\n彼の人生観は長い海外生活によって大きく変わり、仕事よりも家族との時間を重んじるようになった。\n译：他的人生观因长期海外生活发生很大变化，变得比工作更重视与家人相处的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0637","seq":637,"level":"N1","type":"主词条","word":"簡易","kana":"かんい","pos":"[名·ナ形]","accent":"⓪①","meaning":"简易，简便","example":"簡易な検査で異常が見つかったため、医師は念のため詳しい検査を受けるよう勧めた。","exampleZh":"简易检查发现异常后，医生建议他为保险起见接受详细检查。","note":"例：\n簡易な検査で異常が見つかったため、医師は念のため詳しい検査を受けるよう勧めた。\n译：简易检查发现异常后，医生建议他为保险起见接受详细检查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0638","seq":638,"level":"N1","type":"主词条","word":"眼科","kana":"がんか","pos":"[名]","accent":"⓪①","meaning":"眼科","example":"眼科をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“眼科”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n眼科をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“眼科”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0639","seq":639,"level":"N1","type":"主词条","word":"かんかん","kana":"かんかん","pos":"[副]","accent":"⓪","meaning":"（太阳）火辣辣地；大发雷霆","example":"真夏の太陽がかんかん照りつける中、作業員たちはこまめに休憩を取りながら工事を進めた。","exampleZh":"盛夏太阳火辣辣地照着，作业人员一边频繁休息一边推进工程。","note":"例：\n真夏の太陽がかんかん照りつける中、作業員たちはこまめに休憩を取りながら工事を進めた。\n译：盛夏太阳火辣辣地照着，作业人员一边频繁休息一边推进工程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0640","seq":640,"level":"N1","type":"主词条","word":"がんがん","kana":"がんがん","pos":"[副]","accent":"①","meaning":"当当（响）；（头）剧痛","example":"頭ががんがん痛むほど疲れていたが、彼は締め切り前の確認だけは最後までやり遂げた。","exampleZh":"他累得头阵阵作痛，但仍坚持把截止日期前的确认做到最后。","note":"例：\n頭ががんがん痛むほど疲れていたが、彼は締め切り前の確認だけは最後までやり遂げた。\n译：他累得头阵阵作痛，但仍坚持把截止日期前的确认做到最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0641","seq":641,"level":"N1","type":"主词条","word":"勘ぐる","kana":"かんぐる","pos":"[他動1]","accent":"③","meaning":"往坏处推测，瞎猜","example":"無理に勘ぐると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“往坏处推测，瞎猜”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に勘ぐると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“往坏处推测，瞎猜”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0642","seq":642,"level":"N1","type":"主词条","word":"完結","kana":"かんけつ","pos":"[名·自動3]","accent":"⓪","meaning":"完结，结束","example":"完結する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“完结，结束”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n完結する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“完结，结束”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0643","seq":643,"level":"N1","type":"主词条","word":"簡潔","kana":"かんけつ","pos":"[名·ナ形]","accent":"⓪","meaning":"简洁","example":"簡潔な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“简洁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n簡潔な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“简洁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0644","seq":644,"level":"N1","type":"主词条","word":"還元","kana":"かんげん","pos":"[名·自他動3]","accent":"⓪","meaning":"还原，复原","example":"彼は還元を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“还原，复原”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は還元を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“还原，复原”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0645","seq":645,"level":"N1","type":"主词条","word":"頑固","kana":"がんこ","pos":"[名·ナ形]","accent":"①","meaning":"顽固；不容易弄掉","example":"頑固な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“顽固；不容易弄掉”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n頑固な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“顽固；不容易弄掉”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0646","seq":646,"level":"N1","type":"主词条","word":"看護","kana":"かんご","pos":"[名·他動3]","accent":"①","meaning":"看护，护理","example":"夜勤で患者を看護する看護師は、わずかな表情の変化にも注意を払っている。","exampleZh":"夜班看护患者的护士，连细微的表情变化也会留心。","note":"例：\n夜勤で患者を看護する看護師は、わずかな表情の変化にも注意を払っている。\n译：夜班看护患者的护士，连细微的表情变化也会留心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0647","seq":647,"level":"N1","type":"主词条","word":"完工","kana":"かんこう","pos":"[名·自動3]","accent":"⓪","meaning":"完工","example":"完工する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“完工”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n完工する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“完工”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0648","seq":648,"level":"N1","type":"主词条","word":"刊行","kana":"かんこう","pos":"[名·他動3]","accent":"⓪","meaning":"出版发行","example":"チームは刊行する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“出版发行”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは刊行する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“出版发行”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0649","seq":649,"level":"N1","type":"主词条","word":"慣行","kana":"かんこう","pos":"[名]","accent":"⓪","meaning":"惯例","example":"長年の慣行だからといって続けるのではなく、今の働き方に合っているかを見直す必要がある。","exampleZh":"不能因为是多年惯例就继续沿用，而需要重新审视它是否适合当下的工作方式。","note":"例：\n長年の慣行だからといって続けるのではなく、今の働き方に合っているかを見直す必要がある。\n译：不能因为是多年惯例就继续沿用，而需要重新审视它是否适合当下的工作方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0650","seq":650,"level":"N1","type":"主词条","word":"勧告","kana":"かんこく","pos":"[名·他動3]","accent":"⓪","meaning":"劝告","example":"初めて勧告する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“劝告”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて勧告する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“劝告”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0651","seq":651,"level":"N1","type":"主词条","word":"閑古鳥","kana":"かんこどり","pos":"[名]","accent":"③","meaning":"郭公鸟","example":"閑古鳥の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“郭公鸟”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n閑古鳥の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“郭公鸟”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0652","seq":652,"level":"N1","type":"主词条","word":"冠婚葬祭","kana":"かんこんそうさい","pos":"[名]","accent":"⓪","meaning":"红白喜事","example":"冠婚葬祭が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“红白喜事”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n冠婚葬祭が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“红白喜事”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0653","seq":653,"level":"N1","type":"主词条","word":"換算","kana":"かんさん","pos":"[名·他動3]","accent":"⓪","meaning":"换算，折合","example":"海外の料金を円に換算してみると、表示価格より手数料の負担が大きいことが分かった。","exampleZh":"把海外费用换算成日元后才发现，手续费的负担比标价更大。","note":"例：\n海外の料金を円に換算してみると、表示価格より手数料の負担が大きいことが分かった。\n译：把海外费用换算成日元后才发现，手续费的负担比标价更大。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0654","seq":654,"level":"N1","type":"主词条","word":"慣習","kana":"かんしゅう","pos":"[名]","accent":"⓪","meaning":"习惯，习俗","example":"地域に根づいた慣習を変えるには、外から正論を押しつけるのではなく、住民同士の対話が欠かせない。","exampleZh":"要改变根植于地区的习俗，不能从外部强加正确道理，居民之间的对话不可或缺。","note":"例：\n地域に根づいた慣習を変えるには、外から正論を押しつけるのではなく、住民同士の対話が欠かせない。\n译：要改变根植于地区的习俗，不能从外部强加正确道理，居民之间的对话不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0655","seq":655,"level":"N1","type":"主词条","word":"完勝","kana":"かんしょう","pos":"[名·自動3]","accent":"⓪","meaning":"彻底胜利","example":"完勝してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“彻底胜利”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n完勝してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“彻底胜利”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0656","seq":656,"level":"N1","type":"主词条","word":"干渉","kana":"かんしょう","pos":"[名·自動3]","accent":"⓪","meaning":"干涉，干预","example":"干渉した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“干涉，干预”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n干渉した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“干涉，干预”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0657","seq":657,"level":"N1","type":"主词条","word":"勘定","kana":"かんじょう","pos":"[名·他動3]","accent":"③","meaning":"结账","example":"勘定した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“结账”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n勘定した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“结账”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0658","seq":658,"level":"N1","type":"主词条","word":"頑丈","kana":"がんじょう","pos":"[ナ形]","accent":"⓪","meaning":"健壮，坚固，结实","example":"頑丈な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“健壮，坚固，结实”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n頑丈な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“健壮，坚固，结实”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0659","seq":659,"level":"N1","type":"主词条","word":"感触","kana":"かんしょく","pos":"[名]","accent":"⓪","meaning":"感觉，感触","example":"感触を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“感觉，感触”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n感触を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“感觉，感触”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0660","seq":660,"level":"N1","type":"主词条","word":"肝心","kana":"かんじん","pos":"[名·ナ形]","accent":"⓪","meaning":"特别重要，紧要","example":"肝心な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“特别重要，紧要”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n肝心な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“特别重要，紧要”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0661","seq":661,"level":"N1","type":"主词条","word":"感性","kana":"かんせい","pos":"[名]","accent":"①⓪","meaning":"感受性","example":"豊かな感性を育てるには、美しいものを見るだけでなく、不快に感じた理由を考えることも大切だ。","exampleZh":"要培养丰富的感受性，不仅要看美的事物，思考自己为何感到不快也很重要。","note":"例：\n豊かな感性を育てるには、美しいものを見るだけでなく、不快に感じた理由を考えることも大切だ。\n译：要培养丰富的感受性，不仅要看美的事物，思考自己为何感到不快也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0662","seq":662,"level":"N1","type":"主词条","word":"閑静","kana":"かんせい","pos":"[名·ナ形]","accent":"①","meaning":"清净，幽静","example":"閑静な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“清净，幽静”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n閑静な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“清净，幽静”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0663","seq":663,"level":"N1","type":"主词条","word":"慣性","kana":"かんせい","pos":"[名]","accent":"⓪","meaning":"惯性","example":"慣性をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“惯性”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n慣性をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“惯性”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0664","seq":664,"level":"N1","type":"主词条","word":"関税","kana":"かんぜい","pos":"[名]","accent":"⓪","meaning":"关税","example":"新しい関税を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。","exampleZh":"运用新的“关税”时，需要反映当事人的声音，避免负担只偏向一部分人。","note":"例：\n新しい関税を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。\n译：运用新的“关税”时，需要反映当事人的声音，避免负担只偏向一部分人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0665","seq":665,"level":"N1","type":"主词条","word":"岩石","kana":"がんせき","pos":"[名]","accent":"①","meaning":"岩石","example":"研究者は岩石の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“岩石”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は岩石の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“岩石”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0666","seq":666,"level":"N1","type":"主词条","word":"関節","kana":"かんせつ","pos":"[名]","accent":"⓪","meaning":"关节","example":"関節が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“关节”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n関節が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“关节”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0667","seq":667,"level":"N1","type":"主词条","word":"幹線","kana":"かんせん","pos":"[名]","accent":"⓪","meaning":"干线，主线","example":"幹線をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“干线，主线”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n幹線をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“干线，主线”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0668","seq":668,"level":"N1","type":"主词条","word":"簡素","kana":"かんそ","pos":"[名·ナ形]","accent":"⓪","meaning":"简朴","example":"簡素な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“简朴”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n簡素な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“简朴”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0669","seq":669,"level":"N1","type":"主词条","word":"完走","kana":"かんそう","pos":"[名·自他動3]","accent":"⓪","meaning":"跑完全程","example":"彼は途中で足を痛めたが、沿道の声援に支えられて何とか完走した。","exampleZh":"他中途脚受了伤，但在沿途加油声的鼓励下总算跑完全程。","note":"例：\n彼は途中で足を痛めたが、沿道の声援に支えられて何とか完走した。\n译：他中途脚受了伤，但在沿途加油声的鼓励下总算跑完全程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0670","seq":670,"level":"N1","type":"主词条","word":"関知","kana":"かんち","pos":"[名·自動3]","accent":"⓪","meaning":"相关","example":"関知してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“相关”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n関知してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“相关”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0671","seq":671,"level":"N1","type":"主词条","word":"観点","kana":"かんてん","pos":"[名]","accent":"①③","meaning":"观点","example":"費用だけの観点で判断すると、利用者の安全や長期的な維持費を見落としてしまうおそれがある。","exampleZh":"如果只从费用角度判断，可能会忽视使用者安全和长期维护成本。","note":"例：\n費用だけの観点で判断すると、利用者の安全や長期的な維持費を見落としてしまうおそれがある。\n译：如果只从费用角度判断，可能会忽视使用者安全和长期维护成本。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0672","seq":672,"level":"N1","type":"主词条","word":"感電","kana":"かんでん","pos":"[名·自動3]","accent":"⓪","meaning":"触电","example":"感電する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“触电”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n感電する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“触电”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0673","seq":673,"level":"N1","type":"主词条","word":"勘当","kana":"かんどう","pos":"[名·他動3]","accent":"⓪","meaning":"断绝父子、师徒关系","example":"勘当した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“断绝父子，师徒关系”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n勘当した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“断绝父子，师徒关系”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0674","seq":674,"level":"N1","type":"主词条","word":"カンニング","kana":"かんにんぐ (cunning)","pos":"[名·自動3]","accent":"⓪","meaning":"考试作弊","example":"カンニングで一時的に点を取っても、信頼を失えば次の試験や人間関係に大きく響く。","exampleZh":"即使通过作弊暂时拿到分数，一旦失去信任，也会严重影响下一次考试和人际关系。","note":"例：\nカンニングで一時的に点を取っても、信頼を失えば次の試験や人間関係に大きく響く。\n译：即使通过作弊暂时拿到分数，一旦失去信任，也会严重影响下一次考试和人际关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0675","seq":675,"level":"N1","type":"主词条","word":"元年","kana":"がんねん","pos":"[名]","accent":"①","meaning":"元年","example":"元年をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“元年”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n元年をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“元年”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0676","seq":676,"level":"N1","type":"主词条","word":"芳しい","kana":"かんばしい","pos":"[イ形]","accent":"④","meaning":"芳香；优秀，出色","example":"芳しい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“芳香；优秀，出色”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n芳しい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“芳香；优秀，出色”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0677","seq":677,"level":"N1","type":"主词条","word":"甲板","kana":"かんぱん","pos":"[名]","accent":"⓪③","meaning":"甲板","example":"甲板を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“甲板”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n甲板を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“甲板”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0678","seq":678,"level":"N1","type":"主词条","word":"完備","kana":"かんび","pos":"[名·自動3]","accent":"⓪","meaning":"完备，完善","example":"完備するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“完备，完善”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n完備するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“完备，完善”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0679","seq":679,"level":"N1","type":"主词条","word":"幹部","kana":"かんぶ","pos":"[名]","accent":"①","meaning":"干部","example":"幹部をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“干部”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n幹部をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“干部”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0680","seq":680,"level":"N1","type":"主词条","word":"完璧","kana":"かんぺき","pos":"[名·ナ形]","accent":"⓪","meaning":"完美","example":"一見完璧な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“完美”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見完璧な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“完美”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0681","seq":681,"level":"N1","type":"主词条","word":"勘弁","kana":"かんべん","pos":"[名·他動3]","accent":"⓪","meaning":"饶恕，容忍","example":"一度の遅刻なら勘弁できても、理由を言わずに繰り返されれば信頼は失われる。","exampleZh":"一次迟到也许还能原谅，但若不说明理由反复发生，信任就会失去。","note":"例：\n一度の遅刻なら勘弁できても、理由を言わずに繰り返されれば信頼は失われる。\n译：一次迟到也许还能原谅，但若不说明理由反复发生，信任就会失去。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0682","seq":682,"level":"N1","type":"主词条","word":"漢方薬","kana":"かんぽうやく","pos":"[名]","accent":"③","meaning":"中药","example":"漢方薬に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。","exampleZh":"他感到“中药”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","note":"例：\n漢方薬に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。\n译：他感到“中药”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0683","seq":683,"level":"N1","type":"主词条","word":"感無量","kana":"かんむりょう","pos":"[ナ形]","accent":"⓪","meaning":"感慨万千","example":"周囲から感無量だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“感慨万千”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から感無量だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“感慨万千”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0684","seq":684,"level":"N1","type":"主词条","word":"勧誘","kana":"かんゆう","pos":"[名·他動3]","accent":"⓪","meaning":"劝诱，劝说","example":"彼は勧誘を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“劝诱，劝说”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は勧誘を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“劝诱，劝说”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0685","seq":685,"level":"N1","type":"主词条","word":"関与","kana":"かんよ","pos":"[名·自動3]","accent":"①","meaning":"参与，涉嫌","example":"関与してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“参与，涉嫌”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n関与してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“参与，涉嫌”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0686","seq":686,"level":"N1","type":"主词条","word":"肝要","kana":"かんよう","pos":"[名·ナ形]","accent":"⓪","meaning":"重要，关键","example":"一度肝要だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“重要，关键”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度肝要だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“重要，关键”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0687","seq":687,"level":"N1","type":"主词条","word":"慣用","kana":"かんよう","pos":"[名·他動3]","accent":"⓪","meaning":"惯用","example":"慣用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“惯用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n慣用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“惯用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0688","seq":688,"level":"N1","type":"主词条","word":"寛容","kana":"かんよう","pos":"[名·ナ形]","accent":"⓪","meaning":"宽容，宽宏大量","example":"寛容な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“宽容，宽宏大量”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n寛容な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“宽容，宽宏大量”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0689","seq":689,"level":"N1","type":"主词条","word":"元来","kana":"がんらい","pos":"[副]","accent":"①","meaning":"原来，原本","example":"元来この制度は弱い立場の人を支えるために作られたもので、効率だけで判断すべきではない。","exampleZh":"这个制度原本是为了支援弱势立场的人而建立的，不应只用效率来判断。","note":"例：\n元来この制度は弱い立場の人を支えるために作られたもので、効率だけで判断すべきではない。\n译：这个制度原本是为了支援弱势立场的人而建立的，不应只用效率来判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0690","seq":690,"level":"N1","type":"主词条","word":"陥落","kana":"かんらく","pos":"[名·自動3]","accent":"⓪","meaning":"塌陷；被攻下，被说服","example":"陥落してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“塌陷；被攻下，被说服”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n陥落してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“塌陷；被攻下，被说服”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0691","seq":691,"level":"N1","type":"主词条","word":"観覧","kana":"かんらん","pos":"[名·他動3]","accent":"⓪","meaning":"观看，参观","example":"観覧の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“观看，参观”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n観覧の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“观看，参观”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0692","seq":692,"level":"N1","type":"主词条","word":"簡略","kana":"かんりゃく","pos":"[名·ナ形]","accent":"⓪","meaning":"简略，简单","example":"簡略な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“简略，简单”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n簡略な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“简略，简单”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0693","seq":693,"level":"N1","type":"主词条","word":"慣例","kana":"かんれい","pos":"[名]","accent":"⓪","meaning":"惯例","example":"慣例に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“惯例”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n慣例に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“惯例”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0694","seq":694,"level":"N1","type":"主词条","word":"還暦","kana":"かんれき","pos":"[名]","accent":"⓪","meaning":"花甲，60岁","example":"還暦の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“花甲，60岁”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n還暦の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“花甲，60岁”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0695","seq":695,"level":"N1","type":"主词条","word":"貫禄","kana":"かんろく","pos":"[名]","accent":"⓪","meaning":"威严，气派","example":"貫禄を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“威严，气派”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n貫禄を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“威严，气派”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0696","seq":696,"level":"N1","type":"主词条","word":"緩和","kana":"かんわ","pos":"[名·自他動3]","accent":"⓪","meaning":"缓和，缓解","example":"チームは緩和する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“缓和，缓解”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは緩和する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“缓和，缓解”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0697","seq":697,"level":"N1","type":"主词条","word":"ギア","kana":"ぎあ (gear)","pos":"[名]","accent":"①","meaning":"齿轮，（车）挡位","example":"ギアを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“齿轮，挡位”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nギアを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“齿轮，挡位”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0698","seq":698,"level":"N1","type":"主词条","word":"気合","kana":"きあい","pos":"[名]","accent":"⓪","meaning":"气势；精神，注意力","example":"気合をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“气势；精神，注意力”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n気合をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“气势；精神，注意力”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0699","seq":699,"level":"N1","type":"主词条","word":"キープ","kana":"きーぷ (keep)","pos":"[名·他動3]","accent":"①","meaning":"保持；保留，留出","example":"彼はキープを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“保持；保留，留出”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼はキープを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“保持；保留，留出”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0700","seq":700,"level":"N1","type":"主词条","word":"危害","kana":"きがい","pos":"[名]","accent":"①","meaning":"危害","example":"危害の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“危害”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n危害の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“危害”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0701","seq":701,"level":"N1","type":"主词条","word":"規格","kana":"きかく","pos":"[名]","accent":"⓪","meaning":"规格","example":"規格を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“规格”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n規格を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“规格”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0702","seq":702,"level":"N1","type":"主词条","word":"着飾る","kana":"きかざる","pos":"[他動1]","accent":"③","meaning":"盛装打扮","example":"無理に着飾ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“盛装打扮”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に着飾ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“盛装打扮”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0703","seq":703,"level":"N1","type":"主词条","word":"気兼ね","kana":"きがね","pos":"[名·自動3]","accent":"⓪","meaning":"顾虑，客气","example":"予期せず気兼ねした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“顾虑，客气”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず気兼ねした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“顾虑，客气”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0704","seq":704,"level":"N1","type":"主词条","word":"季刊","kana":"きかん","pos":"[名]","accent":"⓪","meaning":"季刊","example":"季刊を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“季刊”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n季刊を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“季刊”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0705","seq":705,"level":"N1","type":"主词条","word":"聞き逃す","kana":"ききのがす","pos":"[他動1]","accent":"④⓪","meaning":"听漏","example":"重要な案内を聞き逃すと後の作業に影響するため、彼は会議を録音して確認した。","exampleZh":"如果漏听重要通知，会影响之后的作业，所以他录下会议以便确认。","note":"例：\n重要な案内を聞き逃すと後の作業に影響するため、彼は会議を録音して確認した。\n译：如果漏听重要通知，会影响之后的作业，所以他录下会议以便确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0706","seq":706,"level":"N1","type":"主词条","word":"帰京","kana":"ききょう","pos":"[名·自動3]","accent":"⓪","meaning":"回京","example":"帰京した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“回京”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n帰京した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“回京”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0707","seq":707,"level":"N1","type":"主词条","word":"戯曲","kana":"ぎきょく","pos":"[名]","accent":"⓪","meaning":"剧本","example":"戯曲を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。","exampleZh":"负责“剧本”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","note":"例：\n戯曲を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。\n译：负责“剧本”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0708","seq":708,"level":"N1","type":"主词条","word":"基金","kana":"ききん","pos":"[名]","accent":"①②","meaning":"基金","example":"市場環境が変わるなかで基金をどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“基金”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかで基金をどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“基金”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0709","seq":709,"level":"N1","type":"主词条","word":"飢饉","kana":"ききん","pos":"[名]","accent":"②①","meaning":"饥荒；不足，缺乏","example":"医師は飢饉の状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“饥荒；不足，缺乏”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師は飢饉の状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“饥荒；不足，缺乏”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0710","seq":710,"level":"N1","type":"主词条","word":"木耳","kana":"きくらげ","pos":"[名]","accent":"②","meaning":"木耳","example":"木耳に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。","exampleZh":"他感到“木耳”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","note":"例：\n木耳に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。\n译：他感到“木耳”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0711","seq":711,"level":"N1","type":"主词条","word":"議決","kana":"ぎけつ","pos":"[名·他動3]","accent":"⓪","meaning":"议决，表决","example":"議決する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“议决，表决”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n議決する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“议决，表决”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0712","seq":712,"level":"N1","type":"主词条","word":"棄権","kana":"きけん","pos":"[名·他動3]","accent":"⓪","meaning":"弃权","example":"チームは棄権する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“弃权”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは棄権する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“弃权”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0713","seq":713,"level":"N1","type":"主词条","word":"起源","kana":"きげん","pos":"[名]","accent":"①","meaning":"起源","example":"起源を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“起源”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n起源を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“起源”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0714","seq":714,"level":"N1","type":"主词条","word":"機構","kana":"きこう","pos":"[名]","accent":"⓪","meaning":"机构，组织","example":"機構が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“机构，组织”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n機構が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“机构，组织”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0715","seq":715,"level":"N1","type":"主词条","word":"気心","kana":"きごころ","pos":"[名]","accent":"②","meaning":"心情，脾气","example":"気心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“心情，脾气”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n気心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“心情，脾气”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0716","seq":716,"level":"N1","type":"主词条","word":"ぎこちない","kana":"ぎこちない","pos":"[イ形]","accent":"④","meaning":"笨拙；生硬，不通顺","example":"ぎこちない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“笨拙；生硬，不通顺”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nぎこちない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“笨拙；生硬，不通顺”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0717","seq":717,"level":"N1","type":"主词条","word":"既婚","kana":"きこん","pos":"[名]","accent":"⓪","meaning":"已婚","example":"既婚に甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。","exampleZh":"如果仗着“已婚”而怠于确认，小小误解有时会变成很大的不满。","note":"例：\n既婚に甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。\n译：如果仗着“已婚”而怠于确认，小小误解有时会变成很大的不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0718","seq":718,"level":"N1","type":"主词条","word":"気障","kana":"きざ","pos":"[名·ナ形]","accent":"①","meaning":"装模作样，令人作呕","example":"気障な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“装模作样，令人作呕”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n気障な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“装模作样，令人作呕”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0719","seq":719,"level":"N1","type":"主词条","word":"記載","kana":"きさい","pos":"[名·他動3]","accent":"⓪","meaning":"记载，刊载","example":"記載する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“记载，刊载”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n記載する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“记载，刊载”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0720","seq":720,"level":"N1","type":"主词条","word":"気さく","kana":"きさく","pos":"[ナ形]","accent":"⓪","meaning":"坦率，直爽","example":"一度気さくだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“坦率，直爽”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度気さくだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“坦率，直爽”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0721","seq":721,"level":"N1","type":"主词条","word":"兆し","kana":"きざし","pos":"[名]","accent":"⓪","meaning":"预兆，兆头","example":"兆しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“预兆，兆头”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n兆しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“预兆，兆头”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0722","seq":722,"level":"N1","type":"主词条","word":"気質","kana":"きしつ","pos":"[名]","accent":"⓪","meaning":"气质，性格","example":"気質をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“气质，性格”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n気質をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“气质，性格”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0723","seq":723,"level":"N1","type":"主词条","word":"期日","kana":"きじつ","pos":"[名]","accent":"①","meaning":"日期，期限","example":"期日が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。","exampleZh":"越接近“日期，期限”，相关人员越细致地共享彼此作业进度，试图防止返工。","note":"例：\n期日が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。\n译：越接近“日期，期限”，相关人员越细致地共享彼此作业进度，试图防止返工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0724","seq":724,"level":"N1","type":"主词条","word":"議事堂","kana":"ぎじどう","pos":"[名]","accent":"⓪","meaning":"议事堂","example":"議事堂の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“议事堂”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n議事堂の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“议事堂”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0725","seq":725,"level":"N1","type":"主词条","word":"軋む","kana":"きしむ","pos":"[自動1]","accent":"②","meaning":"摩擦（嘎吱嘎吱作响）","example":"軋む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“摩擦”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n軋む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“摩擦”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0726","seq":726,"level":"N1","type":"主词条","word":"機種","kana":"きしゅ","pos":"[名]","accent":"①②","meaning":"机种，种类","example":"担当者は機種の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。","exampleZh":"负责人明确了“机种，种类”的标准，并留下记录，以便任何人查看时都能作出相同判断。","note":"例：\n担当者は機種の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。\n译：负责人明确了“机种，种类”的标准，并留下记录，以便任何人查看时都能作出相同判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0727","seq":727,"level":"N1","type":"主词条","word":"記述","kana":"きじゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"叙述","example":"記述する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“叙述”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n記述する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“叙述”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0728","seq":728,"level":"N1","type":"主词条","word":"気性","kana":"きしょう","pos":"[名]","accent":"⓪","meaning":"（与生俱来的）性格，脾气","example":"気性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“性格，脾气”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n気性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“性格，脾气”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0729","seq":729,"level":"N1","type":"主词条","word":"築く","kana":"きずく","pos":"[他動1]","accent":"②","meaning":"修筑，构筑；确立，建立","example":"無理に築くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“修筑，构筑；确立，建立”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に築くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“修筑，构筑；确立，建立”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0730","seq":730,"level":"N1","type":"主词条","word":"絆","kana":"きずな","pos":"[名]","accent":"⓪①","meaning":"纽带，羁绊","example":"絆に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“纽带，羁绊”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n絆に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“纽带，羁绊”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0731","seq":731,"level":"N1","type":"主词条","word":"規制","kana":"きせい","pos":"[名·他動3]","accent":"⓪","meaning":"限制，规定","example":"規制の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“限制，规定”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n規制の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“限制，规定”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0732","seq":732,"level":"N1","type":"主词条","word":"既成","kana":"きせい","pos":"[名]","accent":"⓪","meaning":"既成","example":"既成の考え方にとらわれず、彼女は現場で本当に必要とされる仕組みを探った。","exampleZh":"她不受既成想法束缚，探寻现场真正需要的机制。","note":"例：\n既成の考え方にとらわれず、彼女は現場で本当に必要とされる仕組みを探った。\n译：她不受既成想法束缚，探寻现场真正需要的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0733","seq":733,"level":"N1","type":"主词条","word":"帰省","kana":"きせい","pos":"[名·自動3]","accent":"⓪","meaning":"回乡探亲","example":"帰省するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“回乡探亲”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n帰省するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“回乡探亲”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0734","seq":734,"level":"N1","type":"主词条","word":"犠牲","kana":"ぎせい","pos":"[名]","accent":"⓪","meaning":"牺牲，伤亡","example":"犠牲をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“牺牲，伤亡”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n犠牲をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“牺牲，伤亡”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0735","seq":735,"level":"N1","type":"主词条","word":"競う","kana":"きそう","pos":"[自動1]","accent":"②","meaning":"竞争","example":"競う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“竞争”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n競う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“竞争”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0736","seq":736,"level":"N1","type":"主词条","word":"寄贈","kana":"きぞう","pos":"[名·他動3]","accent":"⓪","meaning":"赠予","example":"チームは寄贈する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“赠予”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは寄贈する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“赠予”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0737","seq":737,"level":"N1","type":"主词条","word":"偽造","kana":"ぎぞう","pos":"[名·他動3]","accent":"⓪","meaning":"伪造，假造","example":"偽造した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“伪造，假造”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n偽造した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“伪造，假造”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0738","seq":738,"level":"N1","type":"主词条","word":"鍛える","kana":"きたえる","pos":"[他動2]","accent":"③","meaning":"锤炼，锻炼","example":"無理に鍛えるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“锤炼，锻炼”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に鍛えるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“锤炼，锻炼”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0739","seq":739,"level":"N1","type":"主词条","word":"気立て","kana":"きだて","pos":"[名]","accent":"⓪","meaning":"性情，脾气","example":"気立てを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“性情，脾气”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n気立てを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“性情，脾气”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0740","seq":740,"level":"N1","type":"主词条","word":"几帳面","kana":"きちょうめん","pos":"[ナ形]","accent":"④⓪","meaning":"认真，一丝不苟","example":"一度几帳面だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“认真，一丝不苟”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度几帳面だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“认真，一丝不苟”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0741","seq":741,"level":"N1","type":"主词条","word":"気遣う","kana":"きづかう","pos":"[他動1]","accent":"③","meaning":"担心，挂念","example":"気遣う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“担心，挂念”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n気遣う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“担心，挂念”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0742","seq":742,"level":"N1","type":"主词条","word":"きっかり","kana":"きっかり","pos":"[副]","accent":"③","meaning":"整，正好","example":"会議は午後三時きっかりに始まり、進行役は最初に議題と終了時刻を全員に確認した。","exampleZh":"会议下午三点整开始，主持人一开始就向全员确认了议题和结束时间。","note":"例：\n会議は午後三時きっかりに始まり、進行役は最初に議題と終了時刻を全員に確認した。\n译：会议下午三点整开始，主持人一开始就向全员确认了议题和结束时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0743","seq":743,"level":"N1","type":"主词条","word":"きっちり","kana":"きっちり","pos":"[副]","accent":"③","meaning":"紧紧，没有空隙；正好，正合适","example":"彼は提出期限をきっちり守るだけでなく、資料の根拠まで分かりやすく整理している。","exampleZh":"他不仅严格遵守提交期限，还把资料依据也整理得清楚易懂。","note":"例：\n彼は提出期限をきっちり守るだけでなく、資料の根拠まで分かりやすく整理している。\n译：他不仅严格遵守提交期限，还把资料依据也整理得清楚易懂。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0744","seq":744,"level":"N1","type":"主词条","word":"きっぱり","kana":"きっぱり","pos":"[副]","accent":"③","meaning":"断然，干脆","example":"彼女は無理な要求をきっぱり断り、その代わり実行可能な範囲で別の案を示した。","exampleZh":"她干脆地拒绝了不合理要求，同时在可执行范围内提出了另一方案。","note":"例：\n彼女は無理な要求をきっぱり断り、その代わり実行可能な範囲で別の案を示した。\n译：她干脆地拒绝了不合理要求，同时在可执行范围内提出了另一方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0745","seq":745,"level":"N1","type":"主词条","word":"規定","kana":"きてい","pos":"[名·他動3]","accent":"⓪","meaning":"规定，规章","example":"社内規定を変えるなら、例外的なケースまで想定し、現場が迷わない基準を示す必要がある。","exampleZh":"如果要改变公司内部规定，就需要连例外情况也预先设想，并提出现场不会迷惑的标准。","note":"例：\n社内規定を変えるなら、例外的なケースまで想定し、現場が迷わない基準を示す必要がある。\n译：如果要改变公司内部规定，就需要连例外情况也预先设想，并提出现场不会迷惑的标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0746","seq":746,"level":"N1","type":"主词条","word":"機転","kana":"きてん","pos":"[名]","accent":"⓪","meaning":"机智","example":"停電で会場が混乱しかけたが、司会者の機転で参加者は落ち着いて避難できた。","exampleZh":"停电使会场几乎陷入混乱，但多亏主持人的机智，参加者得以冷静避难。","note":"例：\n停電で会場が混乱しかけたが、司会者の機転で参加者は落ち着いて避難できた。\n译：停电使会场几乎陷入混乱，但多亏主持人的机智，参加者得以冷静避难。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0747","seq":747,"level":"N1","type":"主词条","word":"軌道","kana":"きどう","pos":"[名]","accent":"⓪","meaning":"轨道","example":"観光客が増えた軌道では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“轨道”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた軌道では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“轨道”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0748","seq":748,"level":"N1","type":"主词条","word":"気取る","kana":"きどる","pos":"[自動1]","accent":"⓪","meaning":"装腔作势；假装","example":"気取る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“装腔作势；假装”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n気取る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“装腔作势；假装”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0749","seq":749,"level":"N1","type":"主词条","word":"技能","kana":"ぎのう","pos":"[名]","accent":"①","meaning":"技能","example":"彼は技能を深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。","exampleZh":"为了加深对“技能”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","note":"例：\n彼は技能を深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。\n译：为了加深对“技能”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0750","seq":750,"level":"N1","type":"主词条","word":"希薄","kana":"きはく","pos":"[名·ナ形]","accent":"⓪","meaning":"稀薄；淡薄","example":"希薄な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“稀薄；淡薄”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n希薄な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“稀薄；淡薄”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0751","seq":751,"level":"N1","type":"主词条","word":"規範","kana":"きはん","pos":"[名]","accent":"⓪","meaning":"规范，标准","example":"規範をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“规范，标准”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n規範をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“规范，标准”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0752","seq":752,"level":"N1","type":"主词条","word":"気品","kana":"きひん","pos":"[名]","accent":"⓪","meaning":"优雅，风度，气派","example":"気品の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。","exampleZh":"在“优雅，风度，气派”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","note":"例：\n気品の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。\n译：在“优雅，风度，气派”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0753","seq":753,"level":"N1","type":"主词条","word":"気風","kana":"きふう","pos":"[名]","accent":"⓪","meaning":"风气，习气","example":"突然の気風で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“风气，习气”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の気風で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“风气，习气”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0754","seq":754,"level":"N1","type":"主词条","word":"起伏","kana":"きふく","pos":"[名·自動3]","accent":"⓪①","meaning":"起伏，跌宕","example":"予期せず起伏した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“起伏，跌宕”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず起伏した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“起伏，跌宕”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0755","seq":755,"level":"N1","type":"主词条","word":"ギフト券","kana":"ぎふとけん","pos":"[名]","accent":"③","meaning":"礼品券","example":"ギフト券が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“礼品券”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nギフト券が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“礼品券”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0756","seq":756,"level":"N1","type":"主词条","word":"気まぐれ","kana":"きまぐれ","pos":"[名·ナ形]","accent":"⓪","meaning":"反复无常；没准脾气","example":"気まぐれな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“反复无常；没准脾气”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n気まぐれな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“反复无常；没准脾气”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0757","seq":757,"level":"N1","type":"主词条","word":"生真面目","kana":"きまじめ","pos":"[名·ナ形]","accent":"②","meaning":"过于认真，一本正经","example":"生真面目な彼は冗談まで真剣に受け止めてしまうが、その誠実さが周囲に信頼されている。","exampleZh":"他过于认真，连玩笑都会认真接受，但那份诚实也受到周围信任。","note":"例：\n生真面目な彼は冗談まで真剣に受け止めてしまうが、その誠実さが周囲に信頼されている。\n译：他过于认真，连玩笑都会认真接受，但那份诚实也受到周围信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0758","seq":758,"level":"N1","type":"主词条","word":"気まずい","kana":"きまずい","pos":"[イ形]","accent":"⓪③","meaning":"不融洽，不愉快","example":"気まずい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“不融洽，不愉快”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n気まずい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“不融洽，不愉快”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0759","seq":759,"level":"N1","type":"主词条","word":"決まって","kana":"きまって","pos":"[副]","accent":"⓪","meaning":"一定，总是","example":"月末になると決まって問い合わせが増えるため、窓口では臨時の担当者を増やして対応している。","exampleZh":"一到月底咨询就总会增加，因此窗口临时增派负责人来应对。","note":"例：\n月末になると決まって問い合わせが増えるため、窓口では臨時の担当者を増やして対応している。\n译：一到月底咨询就总会增加，因此窗口临时增派负责人来应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0760","seq":760,"level":"N1","type":"主词条","word":"決まり文句","kana":"きまりもんく","pos":"[名]","accent":"④","meaning":"口头禅，套话","example":"決まり文句をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“口头禅，套话”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n決まり文句をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“口头禅，套话”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0761","seq":761,"level":"N1","type":"主词条","word":"決まり悪い","kana":"きまりわるい","pos":"[イ形]","accent":"⑤","meaning":"难为情，不好意思","example":"決まり悪い状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“难为情，不好意思”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n決まり悪い状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“难为情，不好意思”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0762","seq":762,"level":"N1","type":"主词条","word":"気味悪い","kana":"きみわるい","pos":"[イ形]","accent":"④","meaning":"令人不快的；可怕的","example":"廊下の奥から気味悪い音が聞こえたが、彼女は慌てず管理人に連絡して状況を確認した。","exampleZh":"走廊深处传来令人毛骨悚然的声音，但她没有慌张，而是联系管理员确认情况。","note":"例：\n廊下の奥から気味悪い音が聞こえたが、彼女は慌てず管理人に連絡して状況を確認した。\n译：走廊深处传来令人毛骨悚然的声音，但她没有慌张，而是联系管理员确认情况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0763","seq":763,"level":"N1","type":"主词条","word":"気難しい","kana":"きむずかしい","pos":"[イ形]","accent":"⓪⑤","meaning":"难以取悦的，挑剔的","example":"気難しい上司に提案を通すには、感情に訴えるよりも根拠を丁寧に示すほうが効果的だ。","exampleZh":"要让挑剔的上司通过提案，与其诉诸情感，不如细致展示依据更有效。","note":"例：\n気難しい上司に提案を通すには、感情に訴えるよりも根拠を丁寧に示すほうが効果的だ。\n译：要让挑剔的上司通过提案，与其诉诸情感，不如细致展示依据更有效。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0764","seq":764,"level":"N1","type":"主词条","word":"記名","kana":"きめい","pos":"[名·自動3]","accent":"⓪","meaning":"记名，写上姓名","example":"予期せず記名した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“记名，写上姓名”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず記名した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“记名，写上姓名”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0765","seq":765,"level":"N1","type":"主词条","word":"決め付ける","kana":"きめつける","pos":"[他動2]","accent":"④⓪","meaning":"不容分说地断定","example":"事実を決め付ける前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“不容分说地断定”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を決め付ける前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“不容分说地断定”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0766","seq":766,"level":"N1","type":"主词条","word":"規約","kana":"きやく","pos":"[名]","accent":"⓪","meaning":"规章，章程","example":"規約が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“规章，章程”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n規約が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“规章，章程”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0767","seq":767,"level":"N1","type":"主词条","word":"逆上","kana":"ぎゃくじょう","pos":"[名·自動3]","accent":"⓪","meaning":"勃然大怒","example":"逆上する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“勃然大怒”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n逆上する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“勃然大怒”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0768","seq":768,"level":"N1","type":"主词条","word":"脚色","kana":"きゃくしょく","pos":"[名·他動3]","accent":"⓪","meaning":"改写，改编；夸张","example":"チームは脚色する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“改写，改编；夸张”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは脚色する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“改写，改编；夸张”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0769","seq":769,"level":"N1","type":"主词条","word":"虐待","kana":"ぎゃくたい","pos":"[名·他動3]","accent":"⓪","meaning":"虐待","example":"虐待した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“虐待”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n虐待した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“虐待”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0770","seq":770,"level":"N1","type":"主词条","word":"脚本","kana":"きゃくほん","pos":"[名]","accent":"⓪","meaning":"脚本，剧本","example":"脚本を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。","exampleZh":"负责“脚本，剧本”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","note":"例：\n脚本を担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。\n译：负责“脚本，剧本”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0771","seq":771,"level":"N1","type":"主词条","word":"華奢","kana":"きゃしゃ","pos":"[名·ナ形]","accent":"⓪","meaning":"纤弱，娇小，苗条","example":"一度華奢だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“纤弱，娇小，苗条”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度華奢だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“纤弱，娇小，苗条”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0772","seq":772,"level":"N1","type":"主词条","word":"脚立","kana":"きゃたつ","pos":"[名]","accent":"⓪","meaning":"双梯","example":"脚立の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“双梯”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n脚立の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“双梯”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0773","seq":773,"level":"N1","type":"主词条","word":"キャッチ","kana":"きゃっち (catch)","pos":"[名·他動3]","accent":"①","meaning":"捕捉，接收；接球","example":"キャッチする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“捕捉，接收；接球”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\nキャッチする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“捕捉，接收；接球”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0774","seq":774,"level":"N1","type":"主词条","word":"ギャップ","kana":"ぎゃっぷ (gap)","pos":"[名]","accent":"①","meaning":"隔阂","example":"ギャップを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“隔阂”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\nギャップを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“隔阂”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0775","seq":775,"level":"N1","type":"主词条","word":"ギャラ","kana":"ぎゃら","pos":"[名]","accent":"①","meaning":"出场费，保证金","example":"ギャラを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“出场费，保证金”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\nギャラを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“出场费，保证金”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0776","seq":776,"level":"N1","type":"主词条","word":"キャラクター","kana":"きゃらくたー (character)","pos":"[名]","accent":"①②","meaning":"个性；角色，人物","example":"キャラクターとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“个性；角色，人物”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\nキャラクターとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“个性；角色，人物”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0777","seq":777,"level":"N1","type":"主词条","word":"キャリア","kana":"きゃりあ (career)","pos":"[名]","accent":"①","meaning":"经历，经验；职业生涯","example":"彼はキャリアを深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。","exampleZh":"为了加深对“经历，经验；职业生涯”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","note":"例：\n彼はキャリアを深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。\n译：为了加深对“经历，经验；职业生涯”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0778","seq":778,"level":"N1","type":"主词条","word":"キャンペーン","kana":"きゃんぺーん (campaign)","pos":"[名]","accent":"③","meaning":"宣传运动，竞选运动","example":"新商品のキャンペーンでは割引だけでなく、実際に使う場面が想像できる動画も公開された。","exampleZh":"新商品宣传活动中不仅有折扣，还公开了能让人想象实际使用场景的视频。","note":"例：\n新商品のキャンペーンでは割引だけでなく、実際に使う場面が想像できる動画も公開された。\n译：新商品宣传活动中不仅有折扣，还公开了能让人想象实际使用场景的视频。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0779","seq":779,"level":"N1","type":"主词条","word":"嗅覚","kana":"きゅうかく","pos":"[名]","accent":"⓪①","meaning":"嗅觉","example":"記者には社会の小さな変化を感じ取る嗅覚があり、まだ誰も注目していない問題を追い続けた。","exampleZh":"记者具有察觉社会细小变化的敏锐嗅觉，一直追踪尚未受到任何人关注的问题。","note":"例：\n記者には社会の小さな変化を感じ取る嗅覚があり、まだ誰も注目していない問題を追い続けた。\n译：记者具有察觉社会细小变化的敏锐嗅觉，一直追踪尚未受到任何人关注的问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0780","seq":780,"level":"N1","type":"主词条","word":"究極","kana":"きゅうきょく","pos":"[名·自動3]","accent":"⓪","meaning":"究竟，最终","example":"究極の目標は勝つことではなく、負けても次に進める力を身につけることだ。","exampleZh":"最终目标不是获胜，而是获得即使失败也能继续前进的力量。","note":"例：\n究極の目標は勝つことではなく、負けても次に進める力を身につけることだ。\n译：最终目标不是获胜，而是获得即使失败也能继续前进的力量。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0781","seq":781,"level":"N1","type":"主词条","word":"窮屈","kana":"きゅうくつ","pos":"[名·ナ形]","accent":"①","meaning":"狭小；受拘束，不自在；缺乏，局促","example":"一見窮屈な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“狭小；受拘束，不自在”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見窮屈な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“狭小；受拘束，不自在”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0782","seq":782,"level":"N1","type":"主词条","word":"急減","kana":"きゅうげん","pos":"[名·自動3]","accent":"⓪","meaning":"骤减，急剧下降","example":"急減する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“骤减，急剧下降”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n急減する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“骤减，急剧下降”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0783","seq":783,"level":"N1","type":"主词条","word":"救済","kana":"きゅうさい","pos":"[名·他動3]","accent":"⓪","meaning":"救济","example":"救済する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“救济”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n救済する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“救济”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0784","seq":784,"level":"N1","type":"主词条","word":"休止","kana":"きゅうし","pos":"[名·自他動3]","accent":"⓪","meaning":"休止，停止","example":"老朽化した設備を点検するため、工場は一週間だけ生産を休止することになった。","exampleZh":"为了检查老化设备，工厂决定只停产一周。","note":"例：\n老朽化した設備を点検するため、工場は一週間だけ生産を休止することになった。\n译：为了检查老化设备，工厂决定只停产一周。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0785","seq":785,"level":"N1","type":"主词条","word":"求人","kana":"きゅうじん","pos":"[名·自動3]","accent":"⓪","meaning":"招聘，招工","example":"求人してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“招聘，招工”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n求人してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“招聘，招工”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0786","seq":786,"level":"N1","type":"主词条","word":"旧知","kana":"きゅうち","pos":"[名]","accent":"①","meaning":"旧友，故交","example":"旧知が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“旧友，故交”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n旧知が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“旧友，故交”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0787","seq":787,"level":"N1","type":"主词条","word":"急騰","kana":"きゅうとう","pos":"[名·自動3]","accent":"⓪","meaning":"暴涨，急剧上升","example":"原材料費が急騰したため、会社は価格を上げる前に仕入れ先の見直しを進めた。","exampleZh":"由于原材料费急剧上涨，公司在提高价格前先推进了供应商的重新审视。","note":"例：\n原材料費が急騰したため、会社は価格を上げる前に仕入れ先の見直しを進めた。\n译：由于原材料费急剧上涨，公司在提高价格前先推进了供应商的重新审视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0788","seq":788,"level":"N1","type":"主词条","word":"窮乏","kana":"きゅうぼう","pos":"[名·自動3]","accent":"⓪","meaning":"贫困","example":"窮乏するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“贫困”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n窮乏するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“贫困”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0789","seq":789,"level":"N1","type":"主词条","word":"究明","kana":"きゅうめい","pos":"[名·他動3]","accent":"⓪","meaning":"研究明白，调查清楚","example":"究明するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。","exampleZh":"他没有只满足于“研究明白，调查清楚”本身，而是进一步思考结果如何连接到现场改善。","note":"例：\n究明するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。\n译：他没有只满足于“研究明白，调查清楚”本身，而是进一步思考结果如何连接到现场改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0790","seq":790,"level":"N1","type":"主词条","word":"急落","kana":"きゅうらく","pos":"[名·自動3]","accent":"⓪","meaning":"暴跌，急剧下跌","example":"急落してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“暴跌，急剧下跌”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n急落してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“暴跌，急剧下跌”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0791","seq":791,"level":"N1","type":"主词条","word":"丘陵","kana":"きゅうりょう","pos":"[名]","accent":"⓪","meaning":"丘陵","example":"丘陵を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“丘陵”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n丘陵を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“丘陵”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0792","seq":792,"level":"N1","type":"主词条","word":"ぎゅっと","kana":"ぎゅっと","pos":"[副]","accent":"①⓪","meaning":"用力地拧（握、捆等）","example":"不安そうな子どもは母親の手をぎゅっと握り、診察室へ入る順番を静かに待っていた。","exampleZh":"看起来不安的孩子紧紧握住母亲的手，安静等待进入诊室的顺序。","note":"例：\n不安そうな子どもは母親の手をぎゅっと握り、診察室へ入る順番を静かに待っていた。\n译：看起来不安的孩子紧紧握住母亲的手，安静等待进入诊室的顺序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0793","seq":793,"level":"N1","type":"主词条","word":"寄与","kana":"きよ","pos":"[名·自動3]","accent":"①","meaning":"贡献","example":"寄与するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“贡献”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n寄与するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“贡献”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0794","seq":794,"level":"N1","type":"主词条","word":"〜橋","kana":"〜きょう","pos":"[接尾]","accent":"","meaning":"……桥","example":"歩道橋を渡って駅へ向かったが、雨で階段が滑りやすく、係員は高齢者に注意を促していた。","exampleZh":"他走过人行天桥前往车站，但雨天台阶容易打滑，工作人员正在提醒老人注意。","note":"例：\n歩道橋を渡って駅へ向かったが、雨で階段が滑りやすく、係員は高齢者に注意を促していた。\n译：他走过人行天桥前往车站，但雨天台阶容易打滑，工作人员正在提醒老人注意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0795","seq":795,"level":"N1","type":"主词条","word":"驚異","kana":"きょうい","pos":"[名]","accent":"①","meaning":"惊异","example":"驚異をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“惊异”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n驚異をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“惊异”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0796","seq":796,"level":"N1","type":"主词条","word":"驚異的","kana":"きょういてき","pos":"[ナ形]","accent":"⓪","meaning":"惊人的","example":"驚異的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“惊人的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n驚異的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“惊人的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0797","seq":797,"level":"N1","type":"主词条","word":"業界","kana":"ぎょうかい","pos":"[名]","accent":"⓪","meaning":"业界","example":"業界を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“业界”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n業界を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“业界”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0798","seq":798,"level":"N1","type":"主词条","word":"共感","kana":"きょうかん","pos":"[名·自動3]","accent":"⓪","meaning":"同感","example":"共感するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“同感”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n共感するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“同感”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0799","seq":799,"level":"N1","type":"主词条","word":"協議","kana":"きょうぎ","pos":"[名]","accent":"①","meaning":"协议","example":"協議をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“协议”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n協議をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“协议”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0800","seq":800,"level":"N1","type":"主词条","word":"境遇","kana":"きょうぐう","pos":"[名]","accent":"⓪③","meaning":"境遇，处境","example":"境遇を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“境遇，处境”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n境遇を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“境遇，处境”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0801","seq":801,"level":"N1","type":"主词条","word":"凝固","kana":"ぎょうこ","pos":"[名·自動3]","accent":"①⓪","meaning":"凝固","example":"温度が下がると液体が凝固し、容器の形のまま固まってしまった。","exampleZh":"温度下降后液体凝固，按照容器的形状硬化了。","note":"例：\n温度が下がると液体が凝固し、容器の形のまま固まってしまった。\n译：温度下降后液体凝固，按照容器的形状硬化了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0802","seq":802,"level":"N1","type":"主词条","word":"強硬","kana":"きょうこう","pos":"[名·ナ形]","accent":"⓪","meaning":"强硬","example":"強硬な姿勢を取り続ければ交渉は進まないため、双方が譲れる点を探る必要がある。","exampleZh":"如果一直采取强硬姿态，谈判就无法推进，双方需要寻找各自可以让步的地方。","note":"例：\n強硬な姿勢を取り続ければ交渉は進まないため、双方が譲れる点を探る必要がある。\n译：如果一直采取强硬姿态，谈判就无法推进，双方需要寻找各自可以让步的地方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0803","seq":803,"level":"N1","type":"主词条","word":"強行","kana":"きょうこう","pos":"[名·他動3]","accent":"⓪","meaning":"强行","example":"強行の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“强行”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n強行の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“强行”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0804","seq":804,"level":"N1","type":"主词条","word":"競合","kana":"きょうごう","pos":"[名·自動3]","accent":"⓪","meaning":"竞争","example":"予期せず競合した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“竞争”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず競合した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“竞争”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0805","seq":805,"level":"N1","type":"主词条","word":"凶作","kana":"きょうさく","pos":"[名]","accent":"⓪","meaning":"歉收","example":"凶作が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“歉收”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n凶作が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“歉收”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0806","seq":806,"level":"N1","type":"主词条","word":"業者","kana":"ぎょうしゃ","pos":"[名]","accent":"①","meaning":"工商业者；同行，同业者","example":"担当者は業者を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“工商业者；同行，同业者”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は業者を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“工商业者；同行，同业者”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0807","seq":807,"level":"N1","type":"主词条","word":"享受","kana":"きょうじゅ","pos":"[名·他動3]","accent":"①","meaning":"享受","example":"享受する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“享受”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n享受する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“享受”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0808","seq":808,"level":"N1","type":"主词条","word":"郷愁","kana":"きょうしゅう","pos":"[名]","accent":"⓪","meaning":"乡愁","example":"その郷愁を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“乡愁”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその郷愁を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“乡愁”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0809","seq":809,"level":"N1","type":"主词条","word":"教職","kana":"きょうしょく","pos":"[名]","accent":"⓪","meaning":"教职","example":"教職を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“教职”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n教職を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“教职”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0810","seq":810,"level":"N1","type":"主词条","word":"興じる","kana":"きょうじる","pos":"[自動2]","accent":"⓪③","meaning":"玩在兴头上，热衷于","example":"興じる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“玩在兴头上，热衷于”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n興じる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“玩在兴头上，热衷于”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0811","seq":811,"level":"N1","type":"主词条","word":"強制","kana":"きょうせい","pos":"[名·他動3]","accent":"⓪","meaning":"强制，强迫","example":"強制の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“强制，强迫”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n強制の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“强制，强迫”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0812","seq":812,"level":"N1","type":"主词条","word":"矯正","kana":"きょうせい","pos":"[名·他動3]","accent":"⓪","meaning":"矫正","example":"彼は矯正を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“矫正”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は矯正を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“矫正”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0813","seq":813,"level":"N1","type":"主词条","word":"業績","kana":"ぎょうせき","pos":"[名]","accent":"⓪","meaning":"业绩","example":"業績に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“业绩”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n業績に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“业绩”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0814","seq":814,"level":"N1","type":"主词条","word":"共存","kana":"きょうそん","pos":"[名·自動3]","accent":"⓪","meaning":"共存","example":"人と自然が共存する地域を目指し、住民は観光開発の範囲を慎重に決めている。","exampleZh":"为了建设人与自然共存的地区，居民们慎重决定观光开发的范围。","note":"例：\n人と自然が共存する地域を目指し、住民は観光開発の範囲を慎重に決めている。\n译：为了建设人与自然共存的地区，居民们慎重决定观光开发的范围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0815","seq":815,"level":"N1","type":"主词条","word":"境地","kana":"きょうち","pos":"[名]","accent":"①","meaning":"处境；境界","example":"長い修行の末に達した境地は、言葉で語るよりも、彼の静かな所作に表れていた。","exampleZh":"经过长期修行后达到的境界，与其用语言讲述，不如说体现在他安静的举止中。","note":"例：\n長い修行の末に達した境地は、言葉で語るよりも、彼の静かな所作に表れていた。\n译：经过长期修行后达到的境界，与其用语言讲述，不如说体现在他安静的举止中。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0816","seq":816,"level":"N1","type":"主词条","word":"協調","kana":"きょうちょう","pos":"[名·自動3]","accent":"⓪","meaning":"合作；协调","example":"協調する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“合作；协调”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n協調する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“合作；协调”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0817","seq":817,"level":"N1","type":"主词条","word":"協定","kana":"きょうてい","pos":"[名·他動3]","accent":"⓪","meaning":"协定","example":"協定した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“协定”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n協定した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“协定”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0818","seq":818,"level":"N1","type":"主词条","word":"強敵","kana":"きょうてき","pos":"[名]","accent":"⓪","meaning":"强敌，劲敌","example":"強敵をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“强敌，劲敌”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n強敵をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“强敌，劲敌”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0819","seq":819,"level":"N1","type":"主词条","word":"仰天","kana":"ぎょうてん","pos":"[名·自動3]","accent":"⓪","meaning":"非常吃惊","example":"予期せず仰天した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“非常吃惊”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず仰天した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“非常吃惊”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0820","seq":820,"level":"N1","type":"主词条","word":"郷土","kana":"きょうど","pos":"[名]","accent":"①","meaning":"乡土，故乡","example":"郷土の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“乡土，故乡”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n郷土の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“乡土，故乡”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0821","seq":821,"level":"N1","type":"主词条","word":"協同","kana":"きょうどう","pos":"[名·自動3]","accent":"⓪","meaning":"协同，合作","example":"協同する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“协同，合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n協同する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“协同，合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0822","seq":822,"level":"N1","type":"主词条","word":"競売","kana":"きょうばい","pos":"[名·他動3]","accent":"⓪","meaning":"拍卖","example":"競売にかけられた古い建物には歴史的価値があり、保存を求める声も少なくなかった。","exampleZh":"被拿去拍卖的老建筑具有历史价值，也有不少声音要求保存。","note":"例：\n競売にかけられた古い建物には歴史的価値があり、保存を求める声も少なくなかった。\n译：被拿去拍卖的老建筑具有历史价值，也有不少声音要求保存。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0823","seq":823,"level":"N1","type":"主词条","word":"脅迫","kana":"きょうはく","pos":"[名·他動3]","accent":"⓪","meaning":"恐吓，威胁","example":"脅迫する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“恐吓，威胁”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n脅迫する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“恐吓，威胁”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0824","seq":824,"level":"N1","type":"主词条","word":"共鳴","kana":"きょうめい","pos":"[名·自動3]","accent":"⓪","meaning":"共鸣","example":"予期せず共鳴した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“共鸣”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず共鳴した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“共鸣”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0825","seq":825,"level":"N1","type":"主词条","word":"教諭","kana":"きょうゆ","pos":"[名]","accent":"⓪","meaning":"教谕；（幼儿园以及小学、中学的）正式教师","example":"教諭に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“教谕；正式教师”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n教諭に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“教谕；正式教师”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0826","seq":826,"level":"N1","type":"主词条","word":"郷里","kana":"きょうり","pos":"[名]","accent":"①","meaning":"故乡，老家","example":"その郷里を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“故乡，老家”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその郷里を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“故乡，老家”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0827","seq":827,"level":"N1","type":"主词条","word":"恐竜","kana":"きょうりゅう","pos":"[名]","accent":"⓪","meaning":"恐龙","example":"恐竜を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“恐龙”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n恐竜を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“恐龙”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0828","seq":828,"level":"N1","type":"主词条","word":"強烈","kana":"きょうれつ","pos":"[名·ナ形]","accent":"⓪","meaning":"强烈","example":"強烈な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“强烈”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n強烈な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“强烈”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0829","seq":829,"level":"N1","type":"主词条","word":"局限","kana":"きょくげん","pos":"[名·他動3]","accent":"⓪","meaning":"局限","example":"議論を一部の専門家だけに局限せず、利用者の声も反映させるべきだ。","exampleZh":"不应把讨论局限在少数专家之中，也应反映使用者的声音。","note":"例：\n議論を一部の専門家だけに局限せず、利用者の声も反映させるべきだ。\n译：不应把讨论局限在少数专家之中，也应反映使用者的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0830","seq":830,"level":"N1","type":"主词条","word":"極端","kana":"きょくたん","pos":"[名·ナ形]","accent":"③","meaning":"极端","example":"極端な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“极端”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n極端な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“极端”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0831","seq":831,"level":"N1","type":"主词条","word":"極力","kana":"きょくりょく","pos":"[副]","accent":"②①","meaning":"极力，尽量","example":"担当者は利用者の負担を極力減らすため、入力項目を整理し、不要な書類を削減した。","exampleZh":"为了尽量减少使用者负担，负责人整理输入项目并削减了不必要的文件。","note":"例：\n担当者は利用者の負担を極力減らすため、入力項目を整理し、不要な書類を削減した。\n译：为了尽量减少使用者负担，负责人整理输入项目并削减了不必要的文件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0832","seq":832,"level":"N1","type":"主词条","word":"去就","kana":"きょしゅう","pos":"[名]","accent":"⓪","meaning":"去留","example":"去就の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“去留”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n去就の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“去留”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0833","seq":833,"level":"N1","type":"主词条","word":"巨匠","kana":"きょしょう","pos":"[名]","accent":"⓪","meaning":"（艺术领域的）巨匠，泰斗","example":"経験豊かな巨匠の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“巨匠，泰斗”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな巨匠の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“巨匠，泰斗”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0834","seq":834,"level":"N1","type":"主词条","word":"拒絶","kana":"きょぜつ","pos":"[名·他動3]","accent":"⓪","meaning":"拒绝","example":"相手を拒絶するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯对对方进行“拒绝”只会加深对立，因此她决定先确认其主张背后的背景。","note":"例：\n相手を拒絶するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯对对方进行“拒绝”只会加深对立，因此她决定先确认其主张背后的背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0835","seq":835,"level":"N1","type":"主词条","word":"漁村","kana":"ぎょそん","pos":"[名]","accent":"⓪","meaning":"渔村","example":"その漁村を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“渔村”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその漁村を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“渔村”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0836","seq":836,"level":"N1","type":"主词条","word":"ぎょっと","kana":"ぎょっと","pos":"[副·自動3]","accent":"⓪①","meaning":"大吃一惊，吓了一跳","example":"突然の物音にぎょっとしたが、その後、彼は表面的な結果だけでなく、そこに至る経緯も丁寧に振り返った。","exampleZh":"他被突然的声响吓了一跳；之后，他不仅回顾了表面结果，也仔细回顾了事情经过。","note":"例：\n突然の物音にぎょっとしたが、その後、彼は表面的な結果だけでなく、そこに至る経緯も丁寧に振り返った。\n译：他被突然的声响吓了一跳；之后，他不仅回顾了表面结果，也仔细回顾了事情经过。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0837","seq":837,"level":"N1","type":"主词条","word":"拠点","kana":"きょてん","pos":"[名]","accent":"⓪","meaning":"基地，据点","example":"拠点に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“基地，据点”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n拠点に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“基地，据点”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0838","seq":838,"level":"N1","type":"主词条","word":"拒否","kana":"きょひ","pos":"[名·他動3]","accent":"①","meaning":"拒绝，否决","example":"相手を拒否するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯对对方进行“拒绝，否决”只会加深对立，因此她决定先确认其主张背后的背景。","note":"例：\n相手を拒否するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯对对方进行“拒绝，否决”只会加深对立，因此她决定先确认其主张背后的背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0839","seq":839,"level":"N1","type":"主词条","word":"許容","kana":"きょよう","pos":"[名·他動3]","accent":"⓪","meaning":"容许，接受","example":"許容する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“容许，接受”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n許容する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“容许，接受”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0840","seq":840,"level":"N1","type":"主词条","word":"清らか","kana":"きよらか","pos":"[ナ形]","accent":"②","meaning":"清白，纯洁；清洁","example":"一度清らかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“清白，纯洁；清洁”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度清らかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“清白，纯洁；清洁”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0841","seq":841,"level":"N1","type":"主词条","word":"煌びやか","kana":"きらびやか","pos":"[ナ形]","accent":"③","meaning":"光辉灿烂，华丽","example":"一見煌びやかな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“光辉灿烂，华丽”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見煌びやかな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“光辉灿烂，华丽”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0842","seq":842,"level":"N1","type":"主词条","word":"煌く","kana":"きらめく","pos":"[自動1]","accent":"③","meaning":"闪耀","example":"煌くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“闪耀”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n煌くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“闪耀”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0843","seq":843,"level":"N1","type":"主词条","word":"切り","kana":"きり","pos":"[名]","accent":"②","meaning":"段落；终结","example":"この仕事は今日中に切りをつけて、明日は新しい案件に集中したい。","exampleZh":"我想今天之内把这项工作告一段落，明天集中精力处理新的案件。","note":"例：\nこの仕事は今日中に切りをつけて、明日は新しい案件に集中したい。\n译：我想今天之内把这项工作告一段落，明天集中精力处理新的案件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0844","seq":844,"level":"N1","type":"主词条","word":"義理","kana":"ぎり","pos":"[名]","accent":"②","meaning":"情理，情面；（没有血缘的）亲戚关系","example":"義理を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。","exampleZh":"如果重视“情理，情面；亲戚关系”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","note":"例：\n義理を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。\n译：如果重视“情理，情面；亲戚关系”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0845","seq":845,"level":"N1","type":"主词条","word":"切り上げる","kana":"きりあげる","pos":"[他動2]","accent":"④⓪","meaning":"结束；进位","example":"切り上げる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“结束；进位”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n切り上げる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“结束；进位”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0846","seq":846,"level":"N1","type":"主词条","word":"切り替える","kana":"きりかえる","pos":"[他動2]","accent":"④③⓪","meaning":"更换，转换","example":"無理に切り替えるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“更换，转换”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に切り替えるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“更换，转换”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0847","seq":847,"level":"N1","type":"主词条","word":"義理堅い","kana":"ぎりがたい","pos":"[イ形]","accent":"④","meaning":"讲义气","example":"義理堅い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“讲义气”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n義理堅い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“讲义气”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0848","seq":848,"level":"N1","type":"主词条","word":"切り抜ける","kana":"きりぬける","pos":"[他動2]","accent":"④⓪","meaning":"摆脱困境","example":"予算不足の危機を切り抜けるため、担当者は不要な支出を見直し、協力会社にも条件変更を相談した。","exampleZh":"为了摆脱预算不足的危机，负责人重新审视不必要支出，并与合作公司商量条件变更。","note":"例：\n予算不足の危機を切り抜けるため、担当者は不要な支出を見直し、協力会社にも条件変更を相談した。\n译：为了摆脱预算不足的危机，负责人重新审视不必要支出，并与合作公司商量条件变更。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0849","seq":849,"level":"N1","type":"主词条","word":"切り開く","kana":"きりひらく","pos":"[他動1]","accent":"④⓪","meaning":"开辟，开创","example":"相手に何かを切り開くなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“开辟，开创”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを切り開くなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“开辟，开创”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0850","seq":850,"level":"N1","type":"主词条","word":"器量","kana":"きりょう","pos":"[名]","accent":"①","meaning":"才能；容貌","example":"器量が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“才能；容貌”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n器量が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“才能；容貌”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0851","seq":851,"level":"N1","type":"主词条","word":"気力","kana":"きりょく","pos":"[名]","accent":"⓪①","meaning":"精力，元气，气力","example":"彼の気力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。","exampleZh":"他的“精力，元气，气力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","note":"例：\n彼の気力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。\n译：他的“精力，元气，气力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0852","seq":852,"level":"N1","type":"主词条","word":"亀裂","kana":"きれつ","pos":"[名]","accent":"⓪","meaning":"裂缝","example":"壁の小さな亀裂を見つけた管理人は、放置せず専門業者に点検を依頼した。","exampleZh":"发现墙上的小裂缝后，管理员没有放任不管，而是委托专业公司检查。","note":"例：\n壁の小さな亀裂を見つけた管理人は、放置せず専門業者に点検を依頼した。\n译：发现墙上的小裂缝后，管理员没有放任不管，而是委托专业公司检查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0853","seq":853,"level":"N1","type":"主词条","word":"切れ目","kana":"きれめ","pos":"[名]","accent":"③","meaning":"断开处；段落；用尽之时","example":"切れ目をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“断开处；段落”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n切れ目をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“断开处；段落”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0854","seq":854,"level":"N1","type":"主词条","word":"切れる","kana":"きれる","pos":"[自動2]","accent":"②","meaning":"能切；断开；头脑敏锐","example":"切れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“能切；断开”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n切れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“能切；断开”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0855","seq":855,"level":"N1","type":"主词条","word":"疑惑","kana":"ぎわく","pos":"[名]","accent":"⓪","meaning":"猜疑，怀疑","example":"疑惑をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“猜疑，怀疑”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n疑惑をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“猜疑，怀疑”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0856","seq":856,"level":"N1","type":"主词条","word":"極めて","kana":"きわめて","pos":"[副]","accent":"②","meaning":"极其，非常","example":"この判断は極めて重要で、短期的な費用だけでなく将来の安全性まで左右する。","exampleZh":"这个判断极其重要，不仅关系到短期费用，也会左右未来的安全性。","note":"例：\nこの判断は極めて重要で、短期的な費用だけでなく将来の安全性まで左右する。\n译：这个判断极其重要，不仅关系到短期费用，也会左右未来的安全性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0857","seq":857,"level":"N1","type":"主词条","word":"極める","kana":"きわめる","pos":"[他動2]","accent":"③","meaning":"达到极点；绝，穷尽","example":"極める前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“达到极点；绝，穷尽”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n極める前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“达到极点；绝，穷尽”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0858","seq":858,"level":"N1","type":"主词条","word":"究める","kana":"きわめる","pos":"[他動2]","accent":"③","meaning":"钻研，弄清","example":"無理に究めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“钻研，弄清”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に究めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“钻研，弄清”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0859","seq":859,"level":"N1","type":"主词条","word":"近郊","kana":"きんこう","pos":"[名]","accent":"⓪","meaning":"近郊，郊区","example":"近郊をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“近郊，郊区”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n近郊をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“近郊，郊区”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0860","seq":860,"level":"N1","type":"主词条","word":"均衡","kana":"きんこう","pos":"[名·自動3]","accent":"⓪","meaning":"均衡","example":"需要と供給の均衡が崩れると、価格は短期間で大きく変動することがある。","exampleZh":"如果需求与供给的均衡被打破，价格有时会在短期内大幅波动。","note":"例：\n需要と供給の均衡が崩れると、価格は短期間で大きく変動することがある。\n译：如果需求与供给的均衡被打破，价格有时会在短期内大幅波动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0861","seq":861,"level":"N1","type":"主词条","word":"均質","kana":"きんしつ","pos":"[名·ナ形]","accent":"⓪","meaning":"均质，等质","example":"一度均質だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“均质，等质”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度均質だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“均质，等质”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0862","seq":862,"level":"N1","type":"主词条","word":"勤続","kana":"きんぞく","pos":"[名·自動3]","accent":"⓪","meaning":"工龄","example":"勤続する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“工龄”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n勤続する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“工龄”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0863","seq":863,"level":"N1","type":"主词条","word":"吟味","kana":"ぎんみ","pos":"[名·他動3]","accent":"①③","meaning":"斟酌，仔细挑选","example":"吟味する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“斟酌，仔细挑选”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n吟味する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“斟酌，仔细挑选”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0864","seq":864,"level":"N1","type":"主词条","word":"緊密","kana":"きんみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"紧密，密切","example":"周囲から緊密だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“紧密，密切”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から緊密だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“紧密，密切”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0865","seq":865,"level":"N1","type":"主词条","word":"禁物","kana":"きんもつ","pos":"[名]","accent":"⓪","meaning":"切忌","example":"禁物の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“切忌”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n禁物の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“切忌”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0866","seq":866,"level":"N1","type":"主词条","word":"苦","kana":"く","pos":"[名]","accent":"①","meaning":"苦，苦难，辛苦","example":"苦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“苦，苦难，辛苦”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n苦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“苦，苦难，辛苦”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0867","seq":867,"level":"N1","type":"主词条","word":"具","kana":"ぐ","pos":"[名]","accent":"⓪","meaning":"菜码；工具，手段","example":"店主は具の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“菜码；工具，手段”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主は具の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“菜码；工具，手段”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0868","seq":868,"level":"N1","type":"主词条","word":"食い違い","kana":"くいちがい","pos":"[名]","accent":"⓪","meaning":"不一致，分歧","example":"食い違いが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“不一致，分歧”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n食い違いが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“不一致，分歧”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0869","seq":869,"level":"N1","type":"主词条","word":"食い違う","kana":"くいちがう","pos":"[自動1]","accent":"④⓪","meaning":"不一致，有分歧","example":"食い違う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“不一致，有分歧”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n食い違う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“不一致，有分歧”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0870","seq":870,"level":"N1","type":"主词条","word":"食い止める","kana":"くいとめる","pos":"[他動2]","accent":"④⓪","meaning":"防止，阻止","example":"感染の拡大を食い止めるには、個人の努力だけでなく、職場全体で休みやすい仕組みを整える必要がある。","exampleZh":"要阻止感染扩大，不能只靠个人努力，还需要整个职场建立容易休假的机制。","note":"例：\n感染の拡大を食い止めるには、個人の努力だけでなく、職場全体で休みやすい仕組みを整える必要がある。\n译：要阻止感染扩大，不能只靠个人努力，还需要整个职场建立容易休假的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0871","seq":871,"level":"N1","type":"主词条","word":"悔いる","kana":"くいる","pos":"[他動2]","accent":"②","meaning":"后悔","example":"悔いる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“后悔”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n悔いる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“后悔”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0872","seq":872,"level":"N1","type":"主词条","word":"空間","kana":"くうかん","pos":"[名]","accent":"⓪","meaning":"空间","example":"空間を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“空间”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n空間を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“空间”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0873","seq":873,"level":"N1","type":"主词条","word":"空白","kana":"くうはく","pos":"[名·ナ形]","accent":"⓪","meaning":"空白","example":"空白な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“空白”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n空白な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“空白”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0874","seq":874,"level":"N1","type":"主词条","word":"空爆","kana":"くうばく","pos":"[名·他動3]","accent":"⓪","meaning":"空袭","example":"初めて空爆する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“空袭”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて空爆する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“空袭”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0875","seq":875,"level":"N1","type":"主词条","word":"クーポン","kana":"くーぽん (coupon)","pos":"[名]","accent":"①","meaning":"联票，优惠券","example":"クーポンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“联票，优惠券”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nクーポンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“联票，优惠券”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0876","seq":876,"level":"N1","type":"主词条","word":"クール","kana":"くーる (cool)","pos":"[ナ形]","accent":"①","meaning":"凉快，冷；冷静","example":"クールな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“凉快，冷；冷静”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nクールな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“凉快，冷；冷静”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0877","seq":877,"level":"N1","type":"主词条","word":"区画","kana":"くかく","pos":"[名·他動3]","accent":"⓪","meaning":"区划，划定地区","example":"新しい住宅地では、防災道路を確保するために区画を広めに取っている。","exampleZh":"新的住宅区为了确保防灾道路，把区划划得比较宽。","note":"例：\n新しい住宅地では、防災道路を確保するために区画を広めに取っている。\n译：新的住宅区为了确保防灾道路，把区划划得比较宽。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0878","seq":878,"level":"N1","type":"主词条","word":"区切り","kana":"くぎり","pos":"[名]","accent":"③⓪","meaning":"段落，阶段","example":"区切りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“段落，阶段”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n区切りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“段落，阶段”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0879","seq":879,"level":"N1","type":"主词条","word":"括る","kana":"くくる","pos":"[他動1]","accent":"⓪","meaning":"捆，扎；括起来，总结；上吊","example":"無理に括るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“捆，扎；括起来，总结”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に括るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“捆，扎；括起来，总结”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0880","seq":880,"level":"N1","type":"主词条","word":"挫く","kana":"くじく","pos":"[他動1]","accent":"②","meaning":"挫，扭；挫败，挫伤","example":"挫くことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“挫，扭；挫败，挫伤”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n挫くことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“挫，扭；挫败，挫伤”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0881","seq":881,"level":"N1","type":"主词条","word":"挫ける","kana":"くじける","pos":"[自動2]","accent":"③","meaning":"受挫；气馁；灰心","example":"挫けるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“受挫；气馁”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n挫けるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“受挫；气馁”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0882","seq":882,"level":"N1","type":"主词条","word":"くしゃくしゃ","kana":"くしゃくしゃ","pos":"[ナ形·副·自動3]","accent":"①②","meaning":"皱巴巴，乱蓬蓬","example":"かばんの底から出てきた紙はくしゃくしゃだったが、大切な連絡先が書かれていたので捨てられなかった。","exampleZh":"从包底翻出来的纸皱巴巴的，但上面写着重要联系方式，所以他舍不得扔。","note":"例：\nかばんの底から出てきた紙はくしゃくしゃだったが、大切な連絡先が書かれていたので捨てられなかった。\n译：从包底翻出来的纸皱巴巴的，但上面写着重要联系方式，所以他舍不得扔。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0883","seq":883,"level":"N1","type":"主词条","word":"苦渋","kana":"くじゅう","pos":"[名·ナ形]","accent":"⓪","meaning":"痛苦，苦恼","example":"苦渋な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“痛苦，苦恼”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n苦渋な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“痛苦，苦恼”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0884","seq":884,"level":"N1","type":"主词条","word":"駆除","kana":"くじょ","pos":"[名·他動3]","accent":"①","meaning":"用药剂等消灭，驱除","example":"彼は駆除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“用药剂等消灭，驱除”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は駆除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“用药剂等消灭，驱除”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0885","seq":885,"level":"N1","type":"主词条","word":"鯨","kana":"くじら","pos":"[名]","accent":"⓪","meaning":"鲸鱼","example":"港町では鯨に関する資料館が整備され、漁の歴史と海との関わりを学ぶことができる。","exampleZh":"港口城市建成了有关鲸鱼的资料馆，可以学习捕鲸历史以及人与海洋的关系。","note":"例：\n港町では鯨に関する資料館が整備され、漁の歴史と海との関わりを学ぶことができる。\n译：港口城市建成了有关鲸鱼的资料馆，可以学习捕鲸历史以及人与海洋的关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0886","seq":886,"level":"N1","type":"主词条","word":"ぐずぐず","kana":"ぐずぐず","pos":"[副·自動3]","accent":"①","meaning":"嘀咕；磨蹭","example":"出発前にぐずぐずしていると、乗り換えに間に合わなくなる。","exampleZh":"出发前磨磨蹭蹭的话，就赶不上换乘了。","note":"例：\n出発前にぐずぐずしていると、乗り換えに間に合わなくなる。\n译：出发前磨磨蹭蹭的话，就赶不上换乘了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0887","seq":887,"level":"N1","type":"主词条","word":"くすぐったい","kana":"くすぐったい","pos":"[イ形]","accent":"⑤⓪","meaning":"发痒；害羞，难为情","example":"くすぐったい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“发痒；害羞，难为情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nくすぐったい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“发痒；害羞，难为情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0888","seq":888,"level":"N1","type":"主词条","word":"くすぐる","kana":"くすぐる","pos":"[他動1]","accent":"⓪","meaning":"使发痒；引起，激发","example":"くすぐることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“使发痒；引起，激发”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\nくすぐることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“使发痒；引起，激发”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0889","seq":889,"level":"N1","type":"主词条","word":"ぐずつく","kana":"ぐずつく","pos":"[自動1]","accent":"⓪③","meaning":"磨蹭，拖拉；天气阴沉","example":"ぐずつく前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“磨蹭，拖拉；天气阴沉”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\nぐずつく前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“磨蹭，拖拉；天气阴沉”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0890","seq":890,"level":"N1","type":"主词条","word":"燻る","kana":"くすぶる","pos":"[自動1]","accent":"③","meaning":"熏黑；拖延不决，纠缠不休；闷在家","example":"燻るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“熏黑；拖延不决，纠缠不休”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n燻るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“熏黑；拖延不决，纠缠不休”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0891","seq":891,"level":"N1","type":"主词条","word":"愚痴","kana":"ぐち","pos":"[名]","accent":"⓪","meaning":"发牢骚，抱怨","example":"愚痴をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“发牢骚，抱怨”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n愚痴をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“发牢骚，抱怨”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0892","seq":892,"level":"N1","type":"主词条","word":"口コミ","kana":"くちこみ","pos":"[名]","accent":"⓪","meaning":"口头传播，街谈巷议","example":"口コミを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“口头传播，街谈巷议”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n口コミを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“口头传播，街谈巷议”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0893","seq":893,"level":"N1","type":"主词条","word":"口ずさむ","kana":"くちずさむ","pos":"[他動1]","accent":"④","meaning":"随兴吟咏","example":"口ずさむことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“随兴吟咏”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n口ずさむことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“随兴吟咏”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0894","seq":894,"level":"N1","type":"主词条","word":"口走る","kana":"くちばしる","pos":"[他動1]","accent":"④","meaning":"说漏嘴","example":"事実を口走る前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“说漏嘴”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を口走る前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“说漏嘴”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0895","seq":895,"level":"N1","type":"主词条","word":"ぐちゃぐちゃ","kana":"ぐちゃぐちゃ","pos":"[ナ形]","accent":"⓪","meaning":"黏黏糊糊；乱七八糟","example":"ぐちゃぐちゃな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“黏黏糊糊；乱七八糟”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\nぐちゃぐちゃな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“黏黏糊糊；乱七八糟”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0896","seq":896,"level":"N1","type":"主词条","word":"朽ちる","kana":"くちる","pos":"[自動2]","accent":"②","meaning":"腐烂；腐朽","example":"朽ちる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“腐烂；腐朽”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n朽ちる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“腐烂；腐朽”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0897","seq":897,"level":"N1","type":"主词条","word":"覆す","kana":"くつがえす","pos":"[他動1]","accent":"③","meaning":"打翻；推翻","example":"既存の評価を覆すには、勢いだけでなく、誰もが納得できる根拠と結果が必要だ。","exampleZh":"要推翻既有评价，不能只凭气势，还需要人人都能接受的依据和结果。","note":"例：\n既存の評価を覆すには、勢いだけでなく、誰もが納得できる根拠と結果が必要だ。\n译：要推翻既有评价，不能只凭气势，还需要人人都能接受的依据和结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0898","seq":898,"level":"N1","type":"主词条","word":"くっきり","kana":"くっきり","pos":"[副]","accent":"③","meaning":"鲜明，清楚","example":"朝日が昇ると山の稜線がくっきり見え、前日の雨で澄んだ空気まで感じられた。","exampleZh":"朝阳升起后，山脊线清晰可见，连前一天雨后澄澈的空气也能感受到。","note":"例：\n朝日が昇ると山の稜線がくっきり見え、前日の雨で澄んだ空気まで感じられた。\n译：朝阳升起后，山脊线清晰可见，连前一天雨后澄澈的空气也能感受到。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0899","seq":899,"level":"N1","type":"主词条","word":"屈指","kana":"くっし","pos":"[名]","accent":"⓪①","meaning":"屈指可数，数一数二","example":"屈指を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“屈指可数，数一数二”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n屈指を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“屈指可数，数一数二”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0900","seq":900,"level":"N1","type":"主词条","word":"ぐっしょり","kana":"ぐっしょり","pos":"[副]","accent":"③","meaning":"湿透，湿漉漉","example":"突然の雨で資料がぐっしょり濡れてしまい、彼は急いでコピーを取り直した。","exampleZh":"资料被突如其来的雨淋得湿透，他急忙重新复印了一份。","note":"例：\n突然の雨で資料がぐっしょり濡れてしまい、彼は急いでコピーを取り直した。\n译：资料被突如其来的雨淋得湿透，他急忙重新复印了一份。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0901","seq":901,"level":"N1","type":"主词条","word":"屈する","kana":"くっする","pos":"[自他動3]","accent":"⓪③","meaning":"弯曲；屈服","example":"屈する場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“弯曲；屈服”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n屈する場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“弯曲；屈服”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0902","seq":902,"level":"N1","type":"主词条","word":"屈折","kana":"くっせつ","pos":"[名·自動3]","accent":"⓪","meaning":"弯曲，曲折；扭曲","example":"屈折する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“弯曲，曲折；扭曲”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n屈折する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“弯曲，曲折；扭曲”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0903","seq":903,"level":"N1","type":"主词条","word":"ぐったり","kana":"ぐったり","pos":"[副]","accent":"③","meaning":"精疲力竭","example":"長時間の移動を終えた子どもたちはぐったりしており、引率者は予定を少し遅らせて休憩を取らせた。","exampleZh":"长时间移动结束后，孩子们精疲力竭，带队者把计划稍微推迟，让他们休息。","note":"例：\n長時間の移動を終えた子どもたちはぐったりしており、引率者は予定を少し遅らせて休憩を取らせた。\n译：长时间移动结束后，孩子们精疲力竭，带队者把计划稍微推迟，让他们休息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0904","seq":904,"level":"N1","type":"主词条","word":"ぐっと","kana":"ぐっと","pos":"[副]","accent":"⓪①","meaning":"一口气；更加，越发；怔住","example":"新しい資料を加えると発表の説得力がぐっと増し、参加者からの質問も具体的になった。","exampleZh":"加入新的资料后，发表的说服力明显增强，参加者提出的问题也变得更具体。","note":"例：\n新しい資料を加えると発表の説得力がぐっと増し、参加者からの質問も具体的になった。\n译：加入新的资料后，发表的说服力明显增强，参加者提出的问题也变得更具体。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0905","seq":905,"level":"N1","type":"主词条","word":"首輪","kana":"くびわ","pos":"[名]","accent":"⓪","meaning":"（动物）脖套；项链","example":"首輪を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“脖套；项链”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n首輪を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“脖套；项链”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0906","seq":906,"level":"N1","type":"主词条","word":"組み込む","kana":"くみこむ","pos":"[他動1]","accent":"③","meaning":"排入，编入","example":"組み込む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“排入，编入”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n組み込む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“排入，编入”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0907","seq":907,"level":"N1","type":"主词条","word":"工面","kana":"くめん","pos":"[名·他動3]","accent":"①⓪","meaning":"设法，筹措","example":"工面の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“设法，筹措”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n工面の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“设法，筹措”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0908","seq":908,"level":"N1","type":"主词条","word":"倉/蔵","kana":"くら","pos":"[名]","accent":"②","meaning":"仓库，库房","example":"倉の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“仓库，库房”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n倉の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“仓库，库房”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0909","seq":909,"level":"N1","type":"主词条","word":"位する","kana":"くらいする","pos":"[自動3]","accent":"⓪","meaning":"位于，居","example":"その町は二つの大都市の中間に位するため、物流拠点として発展してきた。","exampleZh":"那座城镇位于两大城市中间，因此作为物流据点发展起来。","note":"例：\nその町は二つの大都市の中間に位するため、物流拠点として発展してきた。\n译：那座城镇位于两大城市中间，因此作为物流据点发展起来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0910","seq":910,"level":"N1","type":"主词条","word":"クライマックス","kana":"くらいまっくす (climax)","pos":"[名]","accent":"④","meaning":"顶点，最高峰","example":"クライマックスをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“顶点，最高峰”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nクライマックスをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“顶点，最高峰”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0911","seq":911,"level":"N1","type":"主词条","word":"ぐらつく","kana":"ぐらつく","pos":"[自動1]","accent":"⓪","meaning":"摇摆，动摇","example":"自分の道をぐらつくなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“摇摆，动摇”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道をぐらつくなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“摇摆，动摇”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0912","seq":912,"level":"N1","type":"主词条","word":"クリア","kana":"くりあ (clear)","pos":"[名·他動3·ナ形]","accent":"②","meaning":"跳过，跨过；清楚","example":"クリアした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“跳过，跨过；清楚”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\nクリアした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“跳过，跨过；清楚”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0913","seq":913,"level":"N1","type":"主词条","word":"グリーン車","kana":"ぐりーんしゃ","pos":"[名]","accent":"②","meaning":"软座车厢","example":"グリーン車を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“软座车厢”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nグリーン車を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“软座车厢”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0914","seq":914,"level":"N1","type":"主词条","word":"クレーン","kana":"くれーん (crane)","pos":"[名]","accent":"②","meaning":"起重机","example":"クレーンの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“起重机”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nクレーンの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“起重机”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0915","seq":915,"level":"N1","type":"主词条","word":"グローバル","kana":"ぐろーばる (global)","pos":"[ナ形]","accent":"②","meaning":"全球的，全世界的","example":"グローバルな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“全球的，全世界的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nグローバルな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“全球的，全世界的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0916","seq":916,"level":"N1","type":"主词条","word":"企てる","kana":"くわだてる","pos":"[他動2]","accent":"④","meaning":"策划，企图","example":"企てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“策划，企图”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n企てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“策划，企图”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0917","seq":917,"level":"N1","type":"主词条","word":"群集","kana":"ぐんしゅう","pos":"[名·自動3]","accent":"⓪","meaning":"群集，聚集","example":"群集する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“群集，聚集”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n群集する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“群集，聚集”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0918","seq":918,"level":"N1","type":"主词条","word":"群衆","kana":"ぐんしゅう","pos":"[名]","accent":"⓪","meaning":"群众","example":"群衆が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“群众”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n群衆が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“群众”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0919","seq":919,"level":"N1","type":"主词条","word":"〜系","kana":"〜けい","pos":"[接尾]","accent":"","meaning":"……类型，系统","example":"理系の学生だけでなく文系の学生も参加したことで、研究発表には技術と社会の両面から質問が集まった。","exampleZh":"不仅理科学生，文科学生也参加了研究发表，因此问题从技术和社会两个方面集中提出。","note":"例：\n理系の学生だけでなく文系の学生も参加したことで、研究発表には技術と社会の両面から質問が集まった。\n译：不仅理科学生，文科学生也参加了研究发表，因此问题从技术和社会两个方面集中提出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0920","seq":920,"level":"N1","type":"主词条","word":"経緯","kana":"けいい","pos":"[名]","accent":"⓪","meaning":"经纬；事情的经过，原委","example":"トラブルの経緯を整理すると、最初の連絡不足が後の大きな誤解につながっていたことが分かった。","exampleZh":"整理纠纷的经过后，才发现最初联络不足导致了后来严重的误解。","note":"例：\nトラブルの経緯を整理すると、最初の連絡不足が後の大きな誤解につながっていたことが分かった。\n译：整理纠纷的经过后，才发现最初联络不足导致了后来严重的误解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0921","seq":921,"level":"N1","type":"主词条","word":"敬遠","kana":"けいえん","pos":"[名·他動3]","accent":"⓪","meaning":"有意回避","example":"敬遠した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“有意回避”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n敬遠した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“有意回避”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0922","seq":922,"level":"N1","type":"主词条","word":"経過","kana":"けいか","pos":"[名·自動3]","accent":"⓪","meaning":"经过，过程","example":"経過する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“经过，过程”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n経過する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“经过，过程”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0923","seq":923,"level":"N1","type":"主词条","word":"警戒","kana":"けいかい","pos":"[名·他動3]","accent":"⓪","meaning":"警戒，防范","example":"警戒の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“警戒，防范”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n警戒の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“警戒，防范”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0924","seq":924,"level":"N1","type":"主词条","word":"軽快","kana":"けいかい","pos":"[名·ナ形]","accent":"⓪","meaning":"轻快，愉快","example":"周囲から軽快だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“轻快，愉快”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から軽快だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“轻快，愉快”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0925","seq":925,"level":"N1","type":"主词条","word":"軽減","kana":"けいげん","pos":"[名·他動3]","accent":"⓪","meaning":"减轻","example":"オンライン申請を導入することで、窓口職員の負担を大幅に軽減できた。","exampleZh":"通过引入网上申请，大幅减轻了窗口工作人员的负担。","note":"例：\nオンライン申請を導入することで、窓口職員の負担を大幅に軽減できた。\n译：通过引入网上申请，大幅减轻了窗口工作人员的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0926","seq":926,"level":"N1","type":"主词条","word":"掲載","kana":"けいさい","pos":"[名·他動3]","accent":"⓪","meaning":"刊登，登载","example":"掲載する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“刊登，登载”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n掲載する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“刊登，登载”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0927","seq":927,"level":"N1","type":"主词条","word":"計算高い","kana":"けいさんだかい","pos":"[イ形]","accent":"⑤⑥","meaning":"精打细算，精明","example":"計算高い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“精打细算，精明”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n計算高い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“精打细算，精明”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0928","seq":928,"level":"N1","type":"主词条","word":"傾斜","kana":"けいしゃ","pos":"[名·自動3]","accent":"⓪","meaning":"倾斜","example":"傾斜するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“倾斜”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n傾斜するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“倾斜”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0929","seq":929,"level":"N1","type":"主词条","word":"継承","kana":"けいしょう","pos":"[名·他動3]","accent":"⓪","meaning":"继承","example":"継承した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“继承”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n継承した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“继承”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0930","seq":930,"level":"N1","type":"主词条","word":"形成","kana":"けいせい","pos":"[名·他動3]","accent":"⓪","meaning":"形成","example":"初めて形成する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“形成”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて形成する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“形成”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0931","seq":931,"level":"N1","type":"主词条","word":"形勢","kana":"けいせい","pos":"[名]","accent":"⓪","meaning":"形势，局势","example":"形勢をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“形势，局势”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n形勢をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“形势，局势”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0932","seq":932,"level":"N1","type":"主词条","word":"軽率","kana":"けいそつ","pos":"[名·ナ形]","accent":"⓪","meaning":"轻率，草率","example":"軽率な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“轻率，草率”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n軽率な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“轻率，草率”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0933","seq":933,"level":"N1","type":"主词条","word":"形態","kana":"けいたい","pos":"[名]","accent":"⓪","meaning":"形态","example":"形態に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“形态”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n形態に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“形态”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0934","seq":934,"level":"N1","type":"主词条","word":"経費","kana":"けいひ","pos":"[名]","accent":"①","meaning":"经费，开销","example":"新規事業では経費の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“经费，开销”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では経費の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“经费，开销”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0935","seq":935,"level":"N1","type":"主词条","word":"景品","kana":"けいひん","pos":"[名]","accent":"⓪","meaning":"赠品，纪念品","example":"古い景品を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“赠品，纪念品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い景品を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“赠品，纪念品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0936","seq":936,"level":"N1","type":"主词条","word":"軽蔑","kana":"けいべつ","pos":"[名·他動3]","accent":"⓪","meaning":"轻视","example":"チームは軽蔑する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“轻视”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは軽蔑する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“轻视”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0937","seq":937,"level":"N1","type":"主词条","word":"刑務所","kana":"けいむしょ","pos":"[名]","accent":"③⓪","meaning":"监狱","example":"刑務所の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“监狱”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n刑務所の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“监狱”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0938","seq":938,"level":"N1","type":"主词条","word":"経理","kana":"けいり","pos":"[名]","accent":"①","meaning":"财务；会计","example":"担当者は経理を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“财务；会计”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は経理を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“财务；会计”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0939","seq":939,"level":"N1","type":"主词条","word":"経歴","kana":"けいれき","pos":"[名·自動3]","accent":"⓪","meaning":"经历，履历","example":"予期せず経歴した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“经历，履历”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず経歴した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“经历，履历”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0940","seq":940,"level":"N1","type":"主词条","word":"経路","kana":"けいろ","pos":"[名]","accent":"①","meaning":"途径","example":"経路の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“途径”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n経路の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“途径”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0941","seq":941,"level":"N1","type":"主词条","word":"ケーブル","kana":"けーぶる (cable)","pos":"[名]","accent":"①⓪","meaning":"缆绳；缆车","example":"古いケーブルをそのまま使い続けると発熱するおそれがあるため、技術者は交換を勧めた。","exampleZh":"如果继续使用老旧电缆，可能会发热，因此技术人员建议更换。","note":"例：\n古いケーブルをそのまま使い続けると発熱するおそれがあるため、技術者は交換を勧めた。\n译：如果继续使用老旧电缆，可能会发热，因此技术人员建议更换。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0942","seq":942,"level":"N1","type":"主词条","word":"汚らわしい","kana":"けがらわしい","pos":"[イ形]","accent":"⑤","meaning":"污秽，肮脏，不干净","example":"汚らわしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“污秽，肮脏，不干净”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n汚らわしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“污秽，肮脏，不干净”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0943","seq":943,"level":"N1","type":"主词条","word":"劇的","kana":"げきてき","pos":"[ナ形]","accent":"⓪","meaning":"戏剧性的","example":"劇的な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“戏剧性的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n劇的な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“戏剧性的”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0944","seq":944,"level":"N1","type":"主词条","word":"激安","kana":"げきやす","pos":"[名]","accent":"⓪","meaning":"相当便宜","example":"激安を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“相当便宜”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n激安を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“相当便宜”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0945","seq":945,"level":"N1","type":"主词条","word":"激励","kana":"げきれい","pos":"[名·他動3]","accent":"⓪","meaning":"鼓励，鞭策","example":"激励した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“鼓励，鞭策”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n激励した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“鼓励，鞭策”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0946","seq":946,"level":"N1","type":"主词条","word":"ゲスト","kana":"げすと (guest)","pos":"[名]","accent":"①","meaning":"客人；特邀嘉宾","example":"経験豊かなゲストの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“客人；特邀嘉宾”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなゲストの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“客人；特邀嘉宾”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0947","seq":947,"level":"N1","type":"主词条","word":"桁","kana":"けた","pos":"[名]","accent":"⓪","meaning":"位数","example":"桁が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“位数”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n桁が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“位数”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0948","seq":948,"level":"N1","type":"主词条","word":"欠員","kana":"けついん","pos":"[名]","accent":"⓪","meaning":"缺额，空缺","example":"欠員として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“缺额，空缺”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n欠員として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“缺额，空缺”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0949","seq":949,"level":"N1","type":"主词条","word":"血管","kana":"けっかん","pos":"[名]","accent":"⓪","meaning":"血管","example":"血管の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“血管”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n血管の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“血管”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0950","seq":950,"level":"N1","type":"主词条","word":"結合","kana":"けつごう","pos":"[名·自他動3]","accent":"⓪","meaning":"结合","example":"結合する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“结合”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n結合する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“结合”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0951","seq":951,"level":"N1","type":"主词条","word":"決算","kana":"けっさん","pos":"[名·他動3]","accent":"①","meaning":"结账，结算","example":"決算する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“结账，结算”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n決算する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“结账，结算”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0952","seq":952,"level":"N1","type":"主词条","word":"月謝","kana":"げっしゃ","pos":"[名]","accent":"⓪","meaning":"每月的学费","example":"月謝の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“每月的学费”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n月謝の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“每月的学费”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0953","seq":953,"level":"N1","type":"主词条","word":"欠如","kana":"けつじょ","pos":"[名·自動3]","accent":"①","meaning":"缺乏","example":"情報公開の姿勢の欠如は小さな不満を大きな不信に変えるため、組織は対応を改めた。","exampleZh":"缺乏信息公开的姿态会把小小不满变成巨大的不信任，因此组织改正了应对方式。","note":"例：\n情報公開の姿勢の欠如は小さな不満を大きな不信に変えるため、組織は対応を改めた。\n译：缺乏信息公开的姿态会把小小不满变成巨大的不信任，因此组织改正了应对方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0954","seq":954,"level":"N1","type":"主词条","word":"結晶","kana":"けっしょう","pos":"[名·自動3]","accent":"⓪","meaning":"结晶","example":"予期せず結晶した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“结晶”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず結晶した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“结晶”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0955","seq":955,"level":"N1","type":"主词条","word":"結成","kana":"けっせい","pos":"[名·他動3]","accent":"⓪","meaning":"结成，组成","example":"新しい調査チームの結成にあたり、責任者は専門性だけでなく互いに意見を言いやすい雰囲気も重視した。","exampleZh":"在组建新的调查团队时，负责人不仅重视专业性，也重视彼此容易发表意见的氛围。","note":"例：\n新しい調査チームの結成にあたり、責任者は専門性だけでなく互いに意見を言いやすい雰囲気も重視した。\n译：在组建新的调查团队时，负责人不仅重视专业性，也重视彼此容易发表意见的氛围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0956","seq":956,"level":"N1","type":"主词条","word":"結束","kana":"けっそく","pos":"[名·自他動3]","accent":"⓪","meaning":"团结；捆扎","example":"彼は結束を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“团结；捆扎”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は結束を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“团结；捆扎”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0957","seq":957,"level":"N1","type":"主词条","word":"げっそり","kana":"げっそり","pos":"[副·自動3]","accent":"③","meaning":"急剧消瘦；灰心，无精打采","example":"連日の残業で彼はげっそりしていたが、締め切り後はしっかり休むことにした。","exampleZh":"连续加班让他十分憔悴，但他决定截止日期过后好好休息。","note":"例：\n連日の残業で彼はげっそりしていたが、締め切り後はしっかり休むことにした。\n译：连续加班让他十分憔悴，但他决定截止日期过后好好休息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0958","seq":958,"level":"N1","type":"主词条","word":"欠損","kana":"けっそん","pos":"[名·自動3]","accent":"⓪①","meaning":"缺损；亏损","example":"調査データに欠損があると分析結果が偏るため、研究者は収集方法を見直した。","exampleZh":"如果调查数据存在缺损，分析结果会出现偏差，因此研究者重新审视了收集方法。","note":"例：\n調査データに欠損があると分析結果が偏るため、研究者は収集方法を見直した。\n译：如果调查数据存在缺损，分析结果会出现偏差，因此研究者重新审视了收集方法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0959","seq":959,"level":"N1","type":"主词条","word":"決着","kana":"けっちゃく","pos":"[名·自動3]","accent":"⓪","meaning":"作出决定，解决","example":"予期せず決着した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“作出决定，解决”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず決着した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“作出决定，解决”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0960","seq":960,"level":"N1","type":"主词条","word":"ゲット","kana":"げっと (get)","pos":"[名·他動3]","accent":"①","meaning":"得到","example":"ゲットした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“得到”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\nゲットした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“得到”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0961","seq":961,"level":"N1","type":"主词条","word":"月賦","kana":"げっぷ","pos":"[名]","accent":"⓪","meaning":"按月分期付款","example":"月賦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“按月分期付款”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n月賦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“按月分期付款”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0962","seq":962,"level":"N1","type":"主词条","word":"欠乏","kana":"けつぼう","pos":"[名·自動3]","accent":"⓪","meaning":"缺乏，不足","example":"欠乏する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“缺乏，不足”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n欠乏する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“缺乏，不足”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0963","seq":963,"level":"N1","type":"主词条","word":"蹴飛ばす","kana":"けとばす","pos":"[他動1]","accent":"⓪③","meaning":"踢；拒绝","example":"蹴飛ばすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“踢；拒绝”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n蹴飛ばすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“踢；拒绝”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0964","seq":964,"level":"N1","type":"主词条","word":"貶す","kana":"けなす","pos":"[他動1]","accent":"⓪","meaning":"贬低，诋毁","example":"無理に貶すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“贬低，诋毁”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に貶すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“贬低，诋毁”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0965","seq":965,"level":"N1","type":"主词条","word":"煙たい","kana":"けむたい","pos":"[イ形]","accent":"⓪③","meaning":"烟味呛人；难以融洽","example":"煙たい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“烟味呛人；难以融洽”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n煙たい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“烟味呛人；难以融洽”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0966","seq":966,"level":"N1","type":"主词条","word":"煙る","kana":"けむる","pos":"[自動1]","accent":"⓪","meaning":"冒烟，（烟雾）朦胧","example":"煙るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“冒烟，朦胧”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n煙るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“冒烟，朦胧”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0967","seq":967,"level":"N1","type":"主词条","word":"獣","kana":"けもの","pos":"[名]","accent":"⓪","meaning":"禽兽，野兽","example":"獣が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“禽兽，野兽”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n獣が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“禽兽，野兽”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0968","seq":968,"level":"N1","type":"主词条","word":"家来","kana":"けらい","pos":"[名]","accent":"①","meaning":"侍从，仆人","example":"忠実な家来であっても、主君の誤った判断には命をかけてでも諫める覚悟が必要だった。","exampleZh":"即使是忠诚的家臣，也需要有冒着生命危险劝谏主君错误判断的觉悟。","note":"例：\n忠実な家来であっても、主君の誤った判断には命をかけてでも諫める覚悟が必要だった。\n译：即使是忠诚的家臣，也需要有冒着生命危险劝谏主君错误判断的觉悟。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0969","seq":969,"level":"N1","type":"主词条","word":"下落","kana":"げらく","pos":"[名·自動3]","accent":"⓪","meaning":"下跌，跌落","example":"予期せず下落した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“下跌，跌落”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず下落した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“下跌，跌落”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0970","seq":970,"level":"N1","type":"主词条","word":"げらげら","kana":"げらげら","pos":"[副]","accent":"①","meaning":"大笑不止，笑得前仰后合","example":"彼らはくだらない冗談にげらげら笑っていたが、会議が始まるとすぐ真剣な表情に戻った。","exampleZh":"他们为无聊的玩笑哈哈大笑，但会议一开始就立刻恢复了严肃表情。","note":"例：\n彼らはくだらない冗談にげらげら笑っていたが、会議が始まるとすぐ真剣な表情に戻った。\n译：他们为无聊的玩笑哈哈大笑，但会议一开始就立刻恢复了严肃表情。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0971","seq":971,"level":"N1","type":"主词条","word":"〜圏","kana":"〜けん","pos":"[接尾]","accent":"","meaning":"……圈，范围","example":"通勤圏に新しい住宅地が増え、朝の電車は以前より混雑するようになった。","exampleZh":"通勤圈内新的住宅区增多，早上的电车也比以前更加拥挤。","note":"例：\n通勤圏に新しい住宅地が増え、朝の電車は以前より混雑するようになった。\n译：通勤圈内新的住宅区增多，早上的电车也比以前更加拥挤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0972","seq":972,"level":"N1","type":"主词条","word":"権威","kana":"けんい","pos":"[名]","accent":"①","meaning":"权威","example":"権威として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“权威”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n権威として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“权威”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0973","seq":973,"level":"N1","type":"主词条","word":"減益","kana":"げんえき","pos":"[名·自動3]","accent":"⓪","meaning":"收益减少","example":"減益するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“收益减少”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n減益するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“收益减少”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0974","seq":974,"level":"N1","type":"主词条","word":"現役","kana":"げんえき","pos":"[名]","accent":"⓪","meaning":"在职（人员）；应届","example":"経験豊かな現役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“在职；应届”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな現役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“在职；应届”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0975","seq":975,"level":"N1","type":"主词条","word":"検閲","kana":"けんえつ","pos":"[名·他動3]","accent":"⓪","meaning":"审查","example":"検閲する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“审查”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n検閲する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“审查”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0976","seq":976,"level":"N1","type":"主词条","word":"言及","kana":"げんきゅう","pos":"[名·自動3]","accent":"⓪","meaning":"提及，说到","example":"言及した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“提及，说到”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n言及した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“提及，说到”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0977","seq":977,"level":"N1","type":"主词条","word":"減給","kana":"げんきゅう","pos":"[名·自他動3]","accent":"⓪","meaning":"减薪","example":"減給した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“减薪”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n減給した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“减薪”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0978","seq":978,"level":"N1","type":"主词条","word":"兼業","kana":"けんぎょう","pos":"[名·他動3]","accent":"⓪","meaning":"兼营","example":"初めて兼業する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“兼营”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて兼業する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“兼营”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0979","seq":979,"level":"N1","type":"主词条","word":"原形","kana":"げんけい","pos":"[名]","accent":"⓪","meaning":"原形，原样","example":"原形をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“原形，原样”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n原形をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“原形，原样”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0980","seq":980,"level":"N1","type":"主词条","word":"原型","kana":"げんけい","pos":"[名]","accent":"⓪","meaning":"原型","example":"原型だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。","exampleZh":"如果只凭“原型”评价一个人，就会忽视其努力过程和对周围的贡献。","note":"例：\n原型だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。\n译：如果只凭“原型”评价一个人，就会忽视其努力过程和对周围的贡献。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0981","seq":981,"level":"N1","type":"主词条","word":"権限","kana":"けんげん","pos":"[名]","accent":"③","meaning":"权限","example":"権限に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“权限”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n権限に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“权限”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0982","seq":982,"level":"N1","type":"主词条","word":"言行","kana":"げんこう","pos":"[名]","accent":"⓪","meaning":"言行","example":"言行が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“言行”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n言行が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“言行”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0983","seq":983,"level":"N1","type":"主词条","word":"現行","kana":"げんこう","pos":"[名]","accent":"⓪","meaning":"现行","example":"現行を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“现行”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n現行を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“现行”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0984","seq":984,"level":"N1","type":"主词条","word":"原告","kana":"げんこく","pos":"[名]","accent":"⓪","meaning":"原告","example":"原告の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“原告”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n原告の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“原告”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0985","seq":985,"level":"N1","type":"主词条","word":"健在","kana":"けんざい","pos":"[名·ナ形]","accent":"⓪","meaning":"健在","example":"健在な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“健在”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n健在な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“健在”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0986","seq":986,"level":"N1","type":"主词条","word":"原作","kana":"げんさく","pos":"[名]","accent":"⓪","meaning":"原作，原著","example":"映画化された作品を見た後、彼女は原作の小説を読み、結末の違いに深く考えさせられた。","exampleZh":"看完改编成电影的作品后，她阅读了原作小说，并因结局差异而深受触动。","note":"例：\n映画化された作品を見た後、彼女は原作の小説を読み、結末の違いに深く考えさせられた。\n译：看完改编成电影的作品后，她阅读了原作小说，并因结局差异而深受触动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0987","seq":987,"level":"N1","type":"主词条","word":"検察","kana":"けんさつ","pos":"[名·他動3]","accent":"⓪","meaning":"检察","example":"検察の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“检察”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n検察の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“检察”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0988","seq":988,"level":"N1","type":"主词条","word":"減産","kana":"げんさん","pos":"[名·自他動3]","accent":"⓪","meaning":"减产","example":"彼は減産を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“减产”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は減産を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“减产”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0989","seq":989,"level":"N1","type":"主词条","word":"検事","kana":"けんじ","pos":"[名]","accent":"①","meaning":"检察官","example":"経験豊かな検事の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“检察官”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな検事の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“检察官”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0990","seq":990,"level":"N1","type":"主词条","word":"見識","kana":"けんしき","pos":"[名]","accent":"⓪","meaning":"见识，见解，见地","example":"見識が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“见识，见解，见地”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n見識が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“见识，见解，见地”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0991","seq":991,"level":"N1","type":"主词条","word":"現時点","kana":"げんじてん","pos":"[名]","accent":"①","meaning":"目前，现在","example":"現時点では結論を出せないため、委員会は追加調査の結果を待って判断することにした。","exampleZh":"目前还无法作出结论，因此委员会决定等待追加调查结果后再判断。","note":"例：\n現時点では結論を出せないため、委員会は追加調査の結果を待って判断することにした。\n译：目前还无法作出结论，因此委员会决定等待追加调查结果后再判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0992","seq":992,"level":"N1","type":"主词条","word":"元首","kana":"げんしゅ","pos":"[名]","accent":"①","meaning":"元首","example":"元首を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“元首”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n元首を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“元首”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0993","seq":993,"level":"N1","type":"主词条","word":"原書","kana":"げんしょ","pos":"[名]","accent":"⓪","meaning":"原版书，原著","example":"原書を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“原版书，原著”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\n原書を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“原版书，原著”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0994","seq":994,"level":"N1","type":"主词条","word":"健勝","kana":"けんしょう","pos":"[名·ナ形]","accent":"⓪","meaning":"健康，壮健","example":"健勝な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“健康，壮健”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n健勝な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“健康，壮健”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0995","seq":995,"level":"N1","type":"主词条","word":"検証","kana":"けんしょう","pos":"[名·他動3]","accent":"⓪","meaning":"验证","example":"検証の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“验证”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n検証の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“验证”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0996","seq":996,"level":"N1","type":"主词条","word":"原子力","kana":"げんしりょく","pos":"[名]","accent":"③","meaning":"原子能，核能","example":"原子力を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。","exampleZh":"要磨炼“原子能，核能”，不能只依赖才能，还需要细致回顾失败场面的习惯。","note":"例：\n原子力を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。\n译：要磨炼“原子能，核能”，不能只依赖才能，还需要细致回顾失败场面的习惯。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0997","seq":997,"level":"N1","type":"主词条","word":"件数","kana":"けんすう","pos":"[名]","accent":"③","meaning":"件数","example":"件数が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“件数”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n件数が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“件数”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0998","seq":998,"level":"N1","type":"主词条","word":"減税","kana":"げんぜい","pos":"[名·自他動3]","accent":"⓪","meaning":"减税","example":"減税する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“减税”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n減税する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“减税”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-0999","seq":999,"level":"N1","type":"主词条","word":"健全","kana":"けんぜん","pos":"[名·ナ形]","accent":"⓪","meaning":"（身心）健康；（制度等）健全，稳固","example":"健全な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“健康；健全，稳固”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n健全な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“健康；健全，稳固”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1000","seq":1000,"level":"N1","type":"主词条","word":"幻想","kana":"げんそう","pos":"[名·他動3]","accent":"⓪","meaning":"幻想","example":"努力せずに成功できるという幻想を抱いたままでは、現実の厳しさにすぐ行き詰まってしまう。","exampleZh":"如果一直抱着不努力也能成功的幻想，很快就会在现实的严酷面前陷入困境。","note":"例：\n努力せずに成功できるという幻想を抱いたままでは、現実の厳しさにすぐ行き詰まってしまう。\n译：如果一直抱着不努力也能成功的幻想，很快就会在现实的严酷面前陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1001","seq":1001,"level":"N1","type":"主词条","word":"現像","kana":"げんぞう","pos":"[名·他動3]","accent":"⓪","meaning":"显影，冲洗","example":"現像した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“显影，冲洗”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n現像した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“显影，冲洗”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1002","seq":1002,"level":"N1","type":"主词条","word":"見地","kana":"けんち","pos":"[名]","accent":"①","meaning":"见地，角度","example":"見地が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“见地，角度”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n見地が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“见地，角度”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1003","seq":1003,"level":"N1","type":"主词条","word":"顕著","kana":"けんちょ","pos":"[名·ナ形]","accent":"①","meaning":"显著，明显","example":"顕著な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“显著，明显”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n顕著な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“显著，明显”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1004","seq":1004,"level":"N1","type":"主词条","word":"原点","kana":"げんてん","pos":"[名]","accent":"③⓪","meaning":"原点","example":"改革を急ぐほど、なぜその取り組みを始めたのかという原点に立ち返ることが重要になる。","exampleZh":"越是急于改革，越重要的是回到“为什么开始这项举措”的原点。","note":"例：\n改革を急ぐほど、なぜその取り組みを始めたのかという原点に立ち返ることが重要になる。\n译：越是急于改革，越重要的是回到“为什么开始这项举措”的原点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1005","seq":1005,"level":"N1","type":"主词条","word":"言動","kana":"げんどう","pos":"[名]","accent":"⓪","meaning":"言行举止","example":"言動に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“言行举止”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n言動に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“言行举止”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1006","seq":1006,"level":"N1","type":"主词条","word":"原爆","kana":"げんばく","pos":"[名]","accent":"⓪","meaning":"原子弹","example":"原爆が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“原子弹”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n原爆が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“原子弹”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1007","seq":1007,"level":"N1","type":"主词条","word":"見聞","kana":"けんぶん","pos":"[名·他動3]","accent":"⓪","meaning":"见闻，知识","example":"見聞する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“见闻，知识”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n見聞する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“见闻，知识”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1008","seq":1008,"level":"N1","type":"主词条","word":"厳密","kana":"げんみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"严格，严密","example":"厳密な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“严格，严密”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n厳密な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“严格，严密”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1009","seq":1009,"level":"N1","type":"主词条","word":"賢明","kana":"けんめい","pos":"[名·ナ形]","accent":"⓪","meaning":"贤明，明智","example":"周囲から賢明だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“贤明，明智”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から賢明だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“贤明，明智”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1010","seq":1010,"level":"N1","type":"主词条","word":"倹約","kana":"けんやく","pos":"[名·他動3]","accent":"⓪","meaning":"俭约，节俭","example":"初めて倹約する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“俭约，节俭”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて倹約する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“俭约，节俭”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1011","seq":1011,"level":"N1","type":"主词条","word":"原油","kana":"げんゆ","pos":"[名]","accent":"⓪","meaning":"原油","example":"原油をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“原油”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n原油をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“原油”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1012","seq":1012,"level":"N1","type":"主词条","word":"兼用","kana":"けんよう","pos":"[名·他動3]","accent":"⓪","meaning":"兼用，两用","example":"彼は兼用を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“兼用，两用”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は兼用を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“兼用，两用”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1013","seq":1013,"level":"N1","type":"主词条","word":"権力","kana":"けんりょく","pos":"[名]","accent":"①","meaning":"权力","example":"彼の権力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。","exampleZh":"他的“权力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","note":"例：\n彼の権力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。\n译：他的“权力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1014","seq":1014,"level":"N1","type":"主词条","word":"故〜","kana":"こ〜","pos":"[接頭]","accent":"","meaning":"已故的……","example":"故首相をしのぶ式典では、功績だけでなく残された課題についても冷静に語られた。","exampleZh":"追悼已故首相的仪式上，人们不仅谈到功绩，也冷静谈及遗留下来的课题。","note":"例：\n故首相をしのぶ式典では、功績だけでなく残された課題についても冷静に語られた。\n译：追悼已故首相的仪式上，人们不仅谈到功绩，也冷静谈及遗留下来的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1015","seq":1015,"level":"N1","type":"主词条","word":"合意","kana":"ごうい","pos":"[名·自動3]","accent":"①⓪","meaning":"同意，双方意见一致","example":"合意してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“同意，双方意见一致”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n合意してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“同意，双方意见一致”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1016","seq":1016,"level":"N1","type":"主词条","word":"交易","kana":"こうえき","pos":"[名·自動3]","accent":"⓪","meaning":"交易，贸易","example":"交易した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“交易，贸易”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n交易した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“交易，贸易”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1017","seq":1017,"level":"N1","type":"主词条","word":"公演","kana":"こうえん","pos":"[名·自他動3]","accent":"⓪","meaning":"公演，公开演出","example":"公演する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。","exampleZh":"在进行“公演，公开演出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","note":"例：\n公演する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。\n译：在进行“公演，公开演出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1018","seq":1018,"level":"N1","type":"主词条","word":"後援","kana":"こうえん","pos":"[名·自他動3]","accent":"⓪","meaning":"后援，（资金等的）支援","example":"新人を後援する際には、答えをすぐ与えるより、自分で考える余地を残すことも大切だ。","exampleZh":"支援新人时，比起马上给出答案，留下让其自己思考的余地也很重要。","note":"例：\n新人を後援する際には、答えをすぐ与えるより、自分で考える余地を残すことも大切だ。\n译：支援新人时，比起马上给出答案，留下让其自己思考的余地也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1019","seq":1019,"level":"N1","type":"主词条","word":"甲乙","kana":"こうおつ","pos":"[名]","accent":"①","meaning":"优劣，上下","example":"甲乙を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“优劣，上下”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n甲乙を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“优劣，上下”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1020","seq":1020,"level":"N1","type":"主词条","word":"口外","kana":"こうがい","pos":"[名·他動3]","accent":"⓪","meaning":"说出，泄露","example":"彼は口外を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“说出，泄露”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は口外を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“说出，泄露”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1021","seq":1021,"level":"N1","type":"主词条","word":"高額","kana":"こうがく","pos":"[名·ナ形]","accent":"⓪","meaning":"巨额","example":"一度高額だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“巨额”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度高額だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“巨额”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1022","seq":1022,"level":"N1","type":"主词条","word":"好感","kana":"こうかん","pos":"[名]","accent":"⓪","meaning":"好感","example":"胸に残る好感を無理に隠すより、彼女は事実と感情を分けて整理しようとした。","exampleZh":"与其勉强隐藏心中残留的“好感”，她更想把事实和情绪分开整理。","note":"例：\n胸に残る好感を無理に隠すより、彼女は事実と感情を分けて整理しようとした。\n译：与其勉强隐藏心中残留的“好感”，她更想把事实和情绪分开整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1023","seq":1023,"level":"N1","type":"主词条","word":"交換","kana":"こうかん","pos":"[名·他動3]","accent":"⓪","meaning":"交换","example":"交換する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“交换”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n交換する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“交换”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1024","seq":1024,"level":"N1","type":"主词条","word":"合議","kana":"ごうぎ","pos":"[名·自他動3]","accent":"①","meaning":"协议，协商","example":"チームは合議する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“协议，协商”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは合議する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“协议，协商”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1025","seq":1025,"level":"N1","type":"主词条","word":"皇居","kana":"こうきょ","pos":"[名]","accent":"①","meaning":"皇宫","example":"皇居を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“皇宫”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n皇居を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“皇宫”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1026","seq":1026,"level":"N1","type":"主词条","word":"興行","kana":"こうぎょう","pos":"[名·他動3]","accent":"⓪","meaning":"演出，上演，上映","example":"興行する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。","exampleZh":"在进行“演出，上演，上映”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","note":"例：\n興行する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。\n译：在进行“演出，上演，上映”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1027","seq":1027,"level":"N1","type":"主词条","word":"興業","kana":"こうぎょう","pos":"[名]","accent":"⓪","meaning":"振兴事业","example":"地域の興業を支えてきた劇場が閉鎖の危機に陥り、住民たちは存続のために署名を集めた。","exampleZh":"长期支撑地区演艺事业的剧场陷入关闭危机，居民们为争取保留而收集签名。","note":"例：\n地域の興業を支えてきた劇場が閉鎖の危機に陥り、住民たちは存続のために署名を集めた。\n译：长期支撑地区演艺事业的剧场陷入关闭危机，居民们为争取保留而收集签名。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1028","seq":1028,"level":"N1","type":"主词条","word":"高原","kana":"こうげん","pos":"[名]","accent":"⓪","meaning":"高原","example":"高原を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“高原”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n高原を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“高原”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1029","seq":1029,"level":"N1","type":"主词条","word":"口語","kana":"こうご","pos":"[名]","accent":"⓪","meaning":"口语","example":"口語に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“口语”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n口語に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“口语”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1030","seq":1030,"level":"N1","type":"主词条","word":"交互","kana":"こうご","pos":"[副]","accent":"①","meaning":"互相交替","example":"担当者は二つの案を交互に示し、参加者が違いを比べながら判断できるようにした。","exampleZh":"负责人交替展示两个方案，好让参加者一边比较差异一边作出判断。","note":"例：\n担当者は二つの案を交互に示し、参加者が違いを比べながら判断できるようにした。\n译：负责人交替展示两个方案，好让参加者一边比较差异一边作出判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1031","seq":1031,"level":"N1","type":"主词条","word":"煌々","kana":"こうこう","pos":"[副·ナ形]","accent":"⓪","meaning":"光辉，耀眼","example":"深夜の研究室には明かりが煌々とともり、学生たちが発表資料の最終確認をしていた。","exampleZh":"深夜的研究室灯火通明，学生们正在最终确认发表资料。","note":"例：\n深夜の研究室には明かりが煌々とともり、学生たちが発表資料の最終確認をしていた。\n译：深夜的研究室灯火通明，学生们正在最终确认发表资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1032","seq":1032,"level":"N1","type":"主词条","word":"耕作","kana":"こうさく","pos":"[名·他動3]","accent":"⓪","meaning":"耕作","example":"チームは耕作する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“耕作”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは耕作する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“耕作”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1033","seq":1033,"level":"N1","type":"主词条","word":"工作","kana":"こうさく","pos":"[名·自動3]","accent":"⓪","meaning":"制作；活动，工作","example":"工作する前に、彼は材料や手順を確認し、仕上がりにばらつきが出ないよう作業を進めた。","exampleZh":"制作之前，他确认了材料和步骤，并推进作业，以免成品质量出现差异。","note":"例：\n工作する前に、彼は材料や手順を確認し、仕上がりにばらつきが出ないよう作業を進めた。\n译：制作之前，他确认了材料和步骤，并推进作业，以免成品质量出现差异。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1034","seq":1034,"level":"N1","type":"主词条","word":"講習","kana":"こうしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"讲习，讲授","example":"初めて講習する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“讲习，讲授”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて講習する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“讲习，讲授”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1035","seq":1035,"level":"N1","type":"主词条","word":"口述","kana":"こうじゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"口述","example":"口述の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“口述”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n口述の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“口述”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1036","seq":1036,"level":"N1","type":"主词条","word":"控除","kana":"こうじょ","pos":"[名·他動3]","accent":"①","meaning":"扣除","example":"彼は控除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“扣除”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は控除を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“扣除”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1037","seq":1037,"level":"N1","type":"主词条","word":"高尚","kana":"こうしょう","pos":"[名·ナ形]","accent":"⓪","meaning":"高尚，高雅","example":"高尚な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“高尚，高雅”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n高尚な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“高尚，高雅”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1038","seq":1038,"level":"N1","type":"主词条","word":"交渉","kana":"こうしょう","pos":"[名·自動3]","accent":"⓪","meaning":"谈判，交涉","example":"交渉するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“谈判，交涉”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n交渉するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“谈判，交涉”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1039","seq":1039,"level":"N1","type":"主词条","word":"向上","kana":"こうじょう","pos":"[名·自動3]","accent":"⓪","meaning":"向上，提高","example":"予期せず向上した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“向上，提高”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず向上した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“向上，提高”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1040","seq":1040,"level":"N1","type":"主词条","word":"強情","kana":"ごうじょう","pos":"[名·ナ形]","accent":"⓪","meaning":"固执，倔强","example":"強情な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“固执，倔强”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n強情な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“固执，倔强”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1041","seq":1041,"level":"N1","type":"主词条","word":"行進","kana":"こうしん","pos":"[名·自動3]","accent":"⓪","meaning":"行进，游行","example":"雨の中での行進は体力を奪ったが、参加者は互いに声をかけ合いながら最後まで歩き続けた。","exampleZh":"雨中的游行消耗体力，但参加者们互相鼓励，一直走到了最后。","note":"例：\n雨の中での行進は体力を奪ったが、参加者は互いに声をかけ合いながら最後まで歩き続けた。\n译：雨中的游行消耗体力，但参加者们互相鼓励，一直走到了最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1042","seq":1042,"level":"N1","type":"主词条","word":"香辛料","kana":"こうしんりょう","pos":"[名]","accent":"③","meaning":"香辣调味料","example":"店主は香辛料の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“香辣调味料”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主は香辛料の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“香辣调味料”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1043","seq":1043,"level":"N1","type":"主词条","word":"洪水","kana":"こうずい","pos":"[名]","accent":"⓪①","meaning":"洪水","example":"研究者は洪水の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“洪水”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は洪水の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“洪水”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1044","seq":1044,"level":"N1","type":"主词条","word":"厚生","kana":"こうせい","pos":"[名]","accent":"⓪","meaning":"厚生；保健","example":"厚生の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“厚生；保健”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n厚生の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“厚生；保健”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1045","seq":1045,"level":"N1","type":"主词条","word":"合成","kana":"ごうせい","pos":"[名·他動3]","accent":"⓪","meaning":"合成","example":"画像を合成する際には、見た目の自然さだけでなく、誤解を招かない表示方法にも気を配る必要がある。","exampleZh":"合成图像时，不仅要注意外观看起来自然，也需要留心不会招致误解的标注方式。","note":"例：\n画像を合成する際には、見た目の自然さだけでなく、誤解を招かない表示方法にも気を配る必要がある。\n译：合成图像时，不仅要注意外观看起来自然，也需要留心不会招致误解的标注方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1046","seq":1046,"level":"N1","type":"主词条","word":"鉱石","kana":"こうせき","pos":"[名]","accent":"⓪","meaning":"矿石","example":"研究者は鉱石の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“矿石”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は鉱石の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“矿石”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1047","seq":1047,"level":"N1","type":"主词条","word":"公然","kana":"こうぜん","pos":"[副·ナ形]","accent":"⓪","meaning":"公然，公开","example":"彼は会議の場で公然と方針に反対し、代案を示した。","exampleZh":"他在会议上公开反对方针，并提出了替代方案。","note":"例：\n彼は会議の場で公然と方針に反対し、代案を示した。\n译：他在会议上公开反对方针，并提出了替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1048","seq":1048,"level":"N1","type":"主词条","word":"構想","kana":"こうそう","pos":"[名·他動3]","accent":"⓪","meaning":"构想，设想","example":"チームは構想する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“构想，设想”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは構想する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“构想，设想”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1049","seq":1049,"level":"N1","type":"主词条","word":"拘束","kana":"こうそく","pos":"[名·他動3]","accent":"⓪","meaning":"束缚，限制","example":"拘束した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“束缚，限制”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n拘束した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“束缚，限制”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1050","seq":1050,"level":"N1","type":"主词条","word":"後退","kana":"こうたい","pos":"[名·自動3]","accent":"⓪","meaning":"后退，退缩；衰退","example":"後退してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“后退，退缩；衰退”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n後退してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“后退，退缩；衰退”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1051","seq":1051,"level":"N1","type":"主词条","word":"光沢","kana":"こうたく","pos":"[名]","accent":"⓪","meaning":"光泽","example":"光沢の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“光泽”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n光沢の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“光泽”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1052","seq":1052,"level":"N1","type":"主词条","word":"講壇","kana":"こうだん","pos":"[名]","accent":"⓪","meaning":"讲台","example":"講壇を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“讲台”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n講壇を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“讲台”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1053","seq":1053,"level":"N1","type":"主词条","word":"高低","kana":"こうてい","pos":"[名]","accent":"⓪","meaning":"高低","example":"高低に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“高低”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n高低に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“高低”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1054","seq":1054,"level":"N1","type":"主词条","word":"工程","kana":"こうてい","pos":"[名]","accent":"⓪","meaning":"工程，过程","example":"工程が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“工程，过程”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n工程が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“工程，过程”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1055","seq":1055,"level":"N1","type":"主词条","word":"口頭","kana":"こうとう","pos":"[名]","accent":"⓪","meaning":"口头","example":"口頭を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“口头”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n口頭を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“口头”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1056","seq":1056,"level":"N1","type":"主词条","word":"講読","kana":"こうどく","pos":"[名·他動3]","accent":"⓪","meaning":"讲解","example":"チームは講読する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“讲解”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは講読する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“讲解”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1057","seq":1057,"level":"N1","type":"主词条","word":"購読","kana":"こうどく","pos":"[名·他動3]","accent":"⓪","meaning":"购买，订阅","example":"購読した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“购买，订阅”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n購読した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“购买，订阅”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1058","seq":1058,"level":"N1","type":"主词条","word":"構内","kana":"こうない","pos":"[名]","accent":"①","meaning":"某区域范围之内","example":"構内の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“某区域范围之内”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n構内の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“某区域范围之内”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1059","seq":1059,"level":"N1","type":"主词条","word":"公認","kana":"こうにん","pos":"[名·他動3]","accent":"⓪","meaning":"公认，政府承认","example":"公認の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“公认，政府承认”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n公認の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“公认，政府承认”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1060","seq":1060,"level":"N1","type":"主词条","word":"光熱費","kana":"こうねつひ","pos":"[名]","accent":"④③","meaning":"电费和煤气费","example":"担当者は光熱費を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“电费和煤气费”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は光熱費を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“电费和煤气费”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1061","seq":1061,"level":"N1","type":"主词条","word":"高配","kana":"こうはい","pos":"[名]","accent":"⓪","meaning":"关照（尊敬的说法）","example":"皆様のご高配により、困難だった地域支援の計画も少しずつ実現に近づいております。","exampleZh":"承蒙各位关照，原本困难的地区支援计划也正一点点接近实现。","note":"例：\n皆様のご高配により、困難だった地域支援の計画も少しずつ実現に近づいております。\n译：承蒙各位关照，原本困难的地区支援计划也正一点点接近实现。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1062","seq":1062,"level":"N1","type":"主词条","word":"荒廃","kana":"こうはい","pos":"[名·自動3]","accent":"⓪","meaning":"荒芜，荒废；颓废","example":"荒廃する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“荒芜，荒废；颓废”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n荒廃する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“荒芜，荒废；颓废”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1063","seq":1063,"level":"N1","type":"主词条","word":"勾配","kana":"こうばい","pos":"[名]","accent":"⓪③","meaning":"坡度","example":"勾配をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“坡度”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n勾配をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“坡度”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1064","seq":1064,"level":"N1","type":"主词条","word":"購買","kana":"こうばい","pos":"[名·他動3]","accent":"⓪","meaning":"购买","example":"チームは購買する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“购买”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは購買する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“购买”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1065","seq":1065,"level":"N1","type":"主词条","word":"交付","kana":"こうふ","pos":"[名·他動3]","accent":"①⓪","meaning":"发给，颁发","example":"交付した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“发给，颁发”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n交付した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“发给，颁发”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1066","seq":1066,"level":"N1","type":"主词条","word":"降伏","kana":"こうふく","pos":"[名·自動3]","accent":"⓪","meaning":"投降","example":"降伏した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“投降”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n降伏した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“投降”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1067","seq":1067,"level":"N1","type":"主词条","word":"合弁","kana":"ごうべん","pos":"[名]","accent":"⓪","meaning":"合办，合资","example":"海外企業との合弁を成功させるには、契約条件だけでなく、意思決定の速度や文化の違いも確認すべきだ。","exampleZh":"要让与海外企业的合资取得成功，不仅要确认合同条件，也应确认决策速度和文化差异。","note":"例：\n海外企業との合弁を成功させるには、契約条件だけでなく、意思決定の速度や文化の違いも確認すべきだ。\n译：要让与海外企业的合资取得成功，不仅要确认合同条件，也应确认决策速度和文化差异。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1068","seq":1068,"level":"N1","type":"主词条","word":"公募","kana":"こうぼ","pos":"[名·他動3]","accent":"①⓪","meaning":"公开招聘","example":"彼は公募を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“公开招聘”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は公募を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“公开招聘”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1069","seq":1069,"level":"N1","type":"主词条","word":"広報","kana":"こうほう","pos":"[名]","accent":"①","meaning":"宣传","example":"広報が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“宣传”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n広報が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“宣传”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1070","seq":1070,"level":"N1","type":"主词条","word":"巧妙","kana":"こうみょう","pos":"[名·ナ形]","accent":"⓪","meaning":"巧妙","example":"巧妙な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“巧妙”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n巧妙な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“巧妙”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1071","seq":1071,"level":"N1","type":"主词条","word":"被る","kana":"こうむる","pos":"[他動1]","accent":"③","meaning":"蒙受，遭受；受到","example":"相手に何かを被るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“蒙受，遭受；受到”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを被るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“蒙受，遭受；受到”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1072","seq":1072,"level":"N1","type":"主词条","word":"効用","kana":"こうよう","pos":"[名]","accent":"⓪","meaning":"用处；功效","example":"効用の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“用处；功效”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n効用の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“用处；功效”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1073","seq":1073,"level":"N1","type":"主词条","word":"高揚","kana":"こうよう","pos":"[名·自他動3]","accent":"⓪","meaning":"高昂","example":"高揚した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“高昂”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n高揚した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“高昂”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1074","seq":1074,"level":"N1","type":"主词条","word":"公用","kana":"こうよう","pos":"[名]","accent":"⓪","meaning":"公务，公事；公用","example":"公用が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“公务，公事；公用”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n公用が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“公务，公事；公用”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1075","seq":1075,"level":"N1","type":"主词条","word":"行楽","kana":"こうらく","pos":"[名]","accent":"⓪","meaning":"游玩，游览","example":"行楽をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“游玩，游览”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n行楽をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“游玩，游览”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1076","seq":1076,"level":"N1","type":"主词条","word":"小売り","kana":"こうり","pos":"[名·他動3]","accent":"⓪","meaning":"零售","example":"メーカーは小売りの現場で聞いた消費者の声を、次の商品開発に生かしている。","exampleZh":"制造商把在零售现场听到的消费者意见用于下一款商品开发。","note":"例：\nメーカーは小売りの現場で聞いた消費者の声を、次の商品開発に生かしている。\n译：制造商把在零售现场听到的消费者意见用于下一款商品开发。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1077","seq":1077,"level":"N1","type":"主词条","word":"肥える","kana":"こえる","pos":"[自動2]","accent":"②","meaning":"肥胖；肥沃；鉴赏力强","example":"肥えるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“肥胖；肥沃”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n肥えるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“肥胖；肥沃”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1078","seq":1078,"level":"N1","type":"主词条","word":"コード","kana":"こーど (code)","pos":"[名]","accent":"①","meaning":"规则；代码","example":"コードの変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。","exampleZh":"“规则；代码”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","note":"例：\nコードの変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。\n译：“规则；代码”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1079","seq":1079,"level":"N1","type":"主词条","word":"ゴールイン","kana":"ごーるいん (goal in)","pos":"[名·自動3]","accent":"③","meaning":"到达终点；进球；达到目的","example":"ゴールインする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“到达终点；进球”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\nゴールインする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“到达终点；进球”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1080","seq":1080,"level":"N1","type":"主词条","word":"ゴールデンタイム","kana":"ごーるでんたいむ","pos":"[名]","accent":"⑥","meaning":"黄金时间","example":"ゴールデンタイムが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“黄金时间”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nゴールデンタイムが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“黄金时间”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1081","seq":1081,"level":"N1","type":"主词条","word":"小柄","kana":"こがら","pos":"[名·ナ形]","accent":"⓪","meaning":"小花纹；身材矮小","example":"一度小柄だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“小花纹；身材矮小”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度小柄だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“小花纹；身材矮小”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1082","seq":1082,"level":"N1","type":"主词条","word":"小切手","kana":"こぎって","pos":"[名]","accent":"②","meaning":"支票","example":"小切手として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“支票”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n小切手として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“支票”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1083","seq":1083,"level":"N1","type":"主词条","word":"告知","kana":"こくち","pos":"[名·他動3]","accent":"①⓪","meaning":"告知，通报","example":"告知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“告知，通报”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n告知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“告知，通报”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1084","seq":1084,"level":"N1","type":"主词条","word":"告白","kana":"こくはく","pos":"[名·他動3]","accent":"⓪","meaning":"坦白，交代","example":"彼は告白を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“坦白，交代”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は告白を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“坦白，交代”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1085","seq":1085,"level":"N1","type":"主词条","word":"克明","kana":"こくめい","pos":"[名·ナ形]","accent":"⓪","meaning":"认真，细致","example":"克明な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“认真，细致”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n克明な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“认真，细致”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1086","seq":1086,"level":"N1","type":"主词条","word":"極楽","kana":"ごくらく","pos":"[名]","accent":"⓪④","meaning":"天堂","example":"極楽が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“天堂”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n極楽が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“天堂”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1087","seq":1087,"level":"N1","type":"主词条","word":"焦げ茶","kana":"こげちゃ","pos":"[名]","accent":"⓪②","meaning":"深棕色，深咖啡色","example":"焦げ茶の革靴を選んだことで、彼の落ち着いたスーツ姿に少し柔らかな印象が加わった。","exampleZh":"选择深棕色皮鞋后，他沉稳的西装造型增添了些许柔和印象。","note":"例：\n焦げ茶の革靴を選んだことで、彼の落ち着いたスーツ姿に少し柔らかな印象が加わった。\n译：选择深棕色皮鞋后，他沉稳的西装造型增添了些许柔和印象。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1088","seq":1088,"level":"N1","type":"主词条","word":"個々","kana":"ここ","pos":"[名]","accent":"①","meaning":"每个，各自","example":"個々を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“每个，各自”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n個々を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“每个，各自”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1089","seq":1089,"level":"N1","type":"主词条","word":"心地","kana":"ここち","pos":"[名]","accent":"①","meaning":"心情，心境","example":"心地に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“心情，心境”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n心地に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“心情，心境”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1090","seq":1090,"level":"N1","type":"主词条","word":"〜心地","kana":"〜ごこち","pos":"[接尾]","accent":"","meaning":"表示当时的感觉或心情","example":"寝心地のよいベッドを選んだおかげで、出張先でも疲れを翌日に残さず仕事に集中できた。","exampleZh":"多亏选择了睡起来舒适的床，即使在出差地，他也能不把疲劳留到第二天，专心工作。","note":"例：\n寝心地のよいベッドを選んだおかげで、出張先でも疲れを翌日に残さず仕事に集中できた。\n译：多亏选择了睡起来舒适的床，即使在出差地，他也能不把疲劳留到第二天，专心工作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1091","seq":1091,"level":"N1","type":"主词条","word":"心地よい","kana":"ここちよい","pos":"[イ形]","accent":"④","meaning":"惬意的，舒适的","example":"心地よい距離感を保つには、親しさに甘えず、相手が一人でいたい時間も尊重する必要がある。","exampleZh":"要保持舒适的距离感，就不能仗着亲密，而应尊重对方想独处的时间。","note":"例：\n心地よい距離感を保つには、親しさに甘えず、相手が一人でいたい時間も尊重する必要がある。\n译：要保持舒适的距离感，就不能仗着亲密，而应尊重对方想独处的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1092","seq":1092,"level":"N1","type":"主词条","word":"心得る","kana":"こころえる","pos":"[他動2]","accent":"④","meaning":"理解，懂得；精通","example":"案内係は会場の構造をよく心得ており、急な来客にも迷わず適切な席を示した。","exampleZh":"接待员很熟悉会场结构，即使突然来客也能毫不迷惑地指示合适座位。","note":"例：\n案内係は会場の構造をよく心得ており、急な来客にも迷わず適切な席を示した。\n译：接待员很熟悉会场结构，即使突然来客也能毫不迷惑地指示合适座位。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1093","seq":1093,"level":"N1","type":"主词条","word":"心掛け","kana":"こころがけ","pos":"[名]","accent":"⓪","meaning":"留心，注意","example":"心掛けをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“留心，注意”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n心掛けをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“留心，注意”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1094","seq":1094,"level":"N1","type":"主词条","word":"心掛ける","kana":"こころがける","pos":"[他動2]","accent":"⑤","meaning":"留心，注意","example":"相手に何かを心掛けるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“留心，注意”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを心掛けるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“留心，注意”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1095","seq":1095,"level":"N1","type":"主词条","word":"心構え","kana":"こころがまえ","pos":"[名]","accent":"④","meaning":"觉悟，思想准备","example":"心構えを形だけ整えても意味がないため、責任者は期限・担当者・費用を一つずつ具体化した。","exampleZh":"只在形式上做好思想准备没有意义，因此负责人把期限、负责人和费用逐一具体化。","note":"例：\n心構えを形だけ整えても意味がないため、責任者は期限・担当者・費用を一つずつ具体化した。\n译：只在形式上做好思想准备没有意义，因此负责人把期限、负责人和费用逐一具体化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1096","seq":1096,"level":"N1","type":"主词条","word":"志","kana":"こころざし","pos":"[名]","accent":"⓪⑤","meaning":"志向","example":"高い志を持つだけでは足りず、それを実現するための地道な行動を続けることが大切だ。","exampleZh":"仅仅怀有崇高志向还不够，持续采取实现它的踏实行动才重要。","note":"例：\n高い志を持つだけでは足りず、それを実現するための地道な行動を続けることが大切だ。\n译：仅仅怀有崇高志向还不够，持续采取实现它的踏实行动才重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1097","seq":1097,"level":"N1","type":"主词条","word":"志す","kana":"こころざす","pos":"[他動1]","accent":"④","meaning":"立志，以……为目标","example":"医師を志す彼女は、成績だけでなく患者の不安に寄り添う姿勢も大切にしたいと考えている。","exampleZh":"立志成为医生的她认为，不仅成绩重要，贴近患者不安的态度也同样重要。","note":"例：\n医師を志す彼女は、成績だけでなく患者の不安に寄り添う姿勢も大切にしたいと考えている。\n译：立志成为医生的她认为，不仅成绩重要，贴近患者不安的态度也同样重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1098","seq":1098,"level":"N1","type":"主词条","word":"心強い","kana":"こころづよい","pos":"[イ形]","accent":"⑤","meaning":"心里有底，有把握","example":"心強い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“心里有底，有把握”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n心強い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“心里有底，有把握”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1099","seq":1099,"level":"N1","type":"主词条","word":"心細い","kana":"こころぼそい","pos":"[イ形]","accent":"⑤","meaning":"心里没底，没把握","example":"心細い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“心里没底，没把握”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n心細い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“心里没底，没把握”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1100","seq":1100,"level":"N1","type":"主词条","word":"試み","kana":"こころみ","pos":"[名]","accent":"⓪④","meaning":"尝试","example":"試みを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“尝试”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n試みを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“尝试”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1101","seq":1101,"level":"N1","type":"主词条","word":"試みる","kana":"こころみる","pos":"[他動2]","accent":"④","meaning":"试着","example":"試みる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“试着”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n試みる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“试着”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1102","seq":1102,"level":"N1","type":"主词条","word":"快い","kana":"こころよい","pos":"[イ形]","accent":"④","meaning":"惬意的；爽快的","example":"快いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“惬意的；爽快的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n快いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“惬意的；爽快的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1103","seq":1103,"level":"N1","type":"主词条","word":"古今","kana":"ここん","pos":"[名]","accent":"①","meaning":"古今","example":"古今を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“古今”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n古今を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“古今”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1104","seq":1104,"level":"N1","type":"主词条","word":"誤差","kana":"ごさ","pos":"[名]","accent":"①","meaning":"误差","example":"誤差の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“误差”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n誤差の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“误差”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1105","seq":1105,"level":"N1","type":"主词条","word":"誤作動","kana":"ごさどう","pos":"[名·自動3]","accent":"②","meaning":"运转失误，控制失灵","example":"誤作動した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“运转失误，控制失灵”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n誤作動した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“运转失误，控制失灵”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1106","seq":1106,"level":"N1","type":"主词条","word":"〜越し","kana":"〜ごし","pos":"[接尾]","accent":"","meaning":"隔着……；某一期间一直……","example":"窓越しに見える海は穏やかだったが、港では台風に備えて漁船を固定する作業が続いていた。","exampleZh":"隔着窗户看到的大海很平静，但港口仍在进行固定渔船的作业，以防台风到来。","note":"例：\n窓越しに見える海は穏やかだったが、港では台風に備えて漁船を固定する作業が続いていた。\n译：隔着窗户看到的大海很平静，但港口仍在进行固定渔船的作业，以防台风到来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1107","seq":1107,"level":"N1","type":"主词条","word":"ごしごし","kana":"ごしごし","pos":"[副]","accent":"①","meaning":"用力地","example":"子どもは泥だらけになった靴をごしごし洗い、翌日の遠足にも同じ靴を履いて行くと言った。","exampleZh":"孩子用力刷洗沾满泥的鞋子，并说第二天远足还要穿同一双鞋。","note":"例：\n子どもは泥だらけになった靴をごしごし洗い、翌日の遠足にも同じ靴を履いて行くと言った。\n译：孩子用力刷洗沾满泥的鞋子，并说第二天远足还要穿同一双鞋。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1108","seq":1108,"level":"N1","type":"主词条","word":"後日","kana":"ごじつ","pos":"[名]","accent":"①⓪","meaning":"日后，将来；事后","example":"後日の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“日后，将来；事后”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n後日の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“日后，将来；事后”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1109","seq":1109,"level":"N1","type":"主词条","word":"拗らせる","kana":"こじらせる","pos":"[他動2]","accent":"④","meaning":"使复杂、麻烦；使病情加重","example":"相手に何かを拗らせるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“使复杂，麻烦；使病情加重”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを拗らせるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“使复杂，麻烦；使病情加重”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1110","seq":1110,"level":"N1","type":"主词条","word":"拗れる","kana":"こじれる","pos":"[自動2]","accent":"③","meaning":"事态恶化；病情恶化","example":"勢いが少しずつ拗れる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“事态恶化；病情恶化”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ拗れる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“事态恶化；病情恶化”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1111","seq":1111,"level":"N1","type":"主词条","word":"故人","kana":"こじん","pos":"[名]","accent":"①","meaning":"故人","example":"その故人は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“故人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその故人は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“故人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1112","seq":1112,"level":"N1","type":"主词条","word":"小銭","kana":"こぜに","pos":"[名]","accent":"⓪","meaning":"零钱","example":"小銭だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。","exampleZh":"如果只凭“零钱”评价一个人，就会忽视其努力过程和对周围的贡献。","note":"例：\n小銭だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。\n译：如果只凭“零钱”评价一个人，就会忽视其努力过程和对周围的贡献。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1113","seq":1113,"level":"N1","type":"主词条","word":"挙って","kana":"こぞって","pos":"[副]","accent":"②","meaning":"全部，一切","example":"地域の住民が挙って清掃活動に参加し、長年放置されていた公園は見違えるほど明るくなった。","exampleZh":"地区居民全都参加了清扫活动，长期被放置不管的公园变得焕然一新。","note":"例：\n地域の住民が挙って清掃活動に参加し、長年放置されていた公園は見違えるほど明るくなった。\n译：地区居民全都参加了清扫活动，长期被放置不管的公园变得焕然一新。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1114","seq":1114,"level":"N1","type":"主词条","word":"こだわる","kana":"こだわる","pos":"[自動1]","accent":"③","meaning":"拘泥；讲究","example":"こだわるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“拘泥；讲究”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\nこだわるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“拘泥；讲究”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1115","seq":1115,"level":"N1","type":"主词条","word":"誇張","kana":"こちょう","pos":"[名·他動3]","accent":"⓪","meaning":"夸张，夸大","example":"誇張の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“夸张，夸大”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n誇張の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“夸张，夸大”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1116","seq":1116,"level":"N1","type":"主词条","word":"コツ","kana":"こつ","pos":"[名]","accent":"⓪","meaning":"要领，诀窍","example":"コツの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“要领，诀窍”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nコツの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“要领，诀窍”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1117","seq":1117,"level":"N1","type":"主词条","word":"滑稽","kana":"こっけい","pos":"[名·ナ形]","accent":"⓪","meaning":"诙谐，滑稽","example":"滑稽な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“诙谐，滑稽”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n滑稽な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“诙谐，滑稽”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1118","seq":1118,"level":"N1","type":"主词条","word":"国交","kana":"こっこう","pos":"[名]","accent":"⓪","meaning":"邦交","example":"国交をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“邦交”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n国交をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“邦交”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1119","seq":1119,"level":"N1","type":"主词条","word":"骨董","kana":"こっとう","pos":"[名]","accent":"⓪","meaning":"古董","example":"骨董を購入する際には、見た目の古さだけでなく、由来や修復の記録も確かめるべきだ。","exampleZh":"购买古董时，不应只看外观是否古旧，还应确认来历和修复记录。","note":"例：\n骨董を購入する際には、見た目の古さだけでなく、由来や修復の記録も確かめるべきだ。\n译：购买古董时，不应只看外观是否古旧，还应确认来历和修复记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1120","seq":1120,"level":"N1","type":"主词条","word":"固定","kana":"こてい","pos":"[名·自他動3]","accent":"⓪","meaning":"固定","example":"チームは固定する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“固定”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは固定する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“固定”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1121","seq":1121,"level":"N1","type":"主词条","word":"孤独","kana":"こどく","pos":"[名·ナ形]","accent":"⓪","meaning":"孤独","example":"一度孤独だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“孤独”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度孤独だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“孤独”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1122","seq":1122,"level":"N1","type":"主词条","word":"悉く","kana":"ことごとく","pos":"[副]","accent":"③","meaning":"所有，一切","example":"古い記録は悉く失われたと思われていたが、倉庫の奥から当時の写真が数枚見つかった。","exampleZh":"人们原以为旧记录全部遗失了，但在仓库深处找到了几张当时的照片。","note":"例：\n古い記録は悉く失われたと思われていたが、倉庫の奥から当時の写真が数枚見つかった。\n译：人们原以为旧记录全部遗失了，但在仓库深处找到了几张当时的照片。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1123","seq":1123,"level":"N1","type":"主词条","word":"殊更","kana":"ことさら","pos":"[副]","accent":"⓪②","meaning":"特别；故意，特意","example":"彼は自分の功績を殊更強調せず、成功はチーム全員の準備のおかげだと繰り返した。","exampleZh":"他没有刻意强调自己的功绩，而是一再表示成功归功于全队的准备。","note":"例：\n彼は自分の功績を殊更強調せず、成功はチーム全員の準備のおかげだと繰り返した。\n译：他没有刻意强调自己的功绩，而是一再表示成功归功于全队的准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1124","seq":1124,"level":"N1","type":"主词条","word":"言伝","kana":"ことづて","pos":"[名]","accent":"⓪④","meaning":"托人带口信，转达","example":"経験豊かな言伝の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“托人带口信，转达”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな言伝の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“托人带口信，转达”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1125","seq":1125,"level":"N1","type":"主词条","word":"ことによると","kana":"ことによると","pos":"[副]","accent":"⓪","meaning":"或许，说不定","example":"ことによると明日の会議は延期になるかもしれないので、担当者は関係部署に確認を取った。","exampleZh":"明天的会议说不定会延期，所以负责人向相关部门进行了确认。","note":"例：\nことによると明日の会議は延期になるかもしれないので、担当者は関係部署に確認を取った。\n译：明天的会议说不定会延期，所以负责人向相关部门进行了确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1126","seq":1126,"level":"N1","type":"主词条","word":"粉々","kana":"こなごな","pos":"[ナ形]","accent":"⓪","meaning":"粉碎，稀巴烂","example":"一度粉々だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“粉碎，稀巴烂”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度粉々だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“粉碎，稀巴烂”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1127","seq":1127,"level":"N1","type":"主词条","word":"熟す","kana":"こなす","pos":"[他動1]","accent":"⓪","meaning":"做完；掌握，运用自如","example":"大量の依頼を一人で熟すには、優先順位を決め、途中で進み具合を確認する習慣が欠かせない。","exampleZh":"要一个人完成大量委托，必须决定优先顺序，并养成中途确认进度的习惯。","note":"例：\n大量の依頼を一人で熟すには、優先順位を決め、途中で進み具合を確認する習慣が欠かせない。\n译：要一个人完成大量委托，必须决定优先顺序，并养成中途确认进度的习惯。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1128","seq":1128,"level":"N1","type":"主词条","word":"〜こなす","kana":"〜こなす","pos":"[接尾]","accent":"","meaning":"熟练","example":"彼女は難しい曲を見事に弾きこなし、審査員から技術だけでなく表現力も高く評価された。","exampleZh":"她出色地弹奏了那首难曲，评审不仅高度评价她的技术，也评价她的表现力。","note":"例：\n彼女は難しい曲を見事に弾きこなし、審査員から技術だけでなく表現力も高く評価された。\n译：她出色地弹奏了那首难曲，评审不仅高度评价她的技术，也评价她的表现力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1129","seq":1129,"level":"N1","type":"主词条","word":"コネ","kana":"こね","pos":"[名]","accent":"①","meaning":"后门","example":"コネに頼って採用された人は、実力で信頼を得るまで周囲から厳しい目で見られがちだ。","exampleZh":"靠关系被录用的人，在凭实力赢得信任之前，往往会受到周围严厉的目光。","note":"例：\nコネに頼って採用された人は、実力で信頼を得るまで周囲から厳しい目で見られがちだ。\n译：靠关系被录用的人，在凭实力赢得信任之前，往往会受到周围严厉的目光。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1130","seq":1130,"level":"N1","type":"主词条","word":"この方","kana":"このかた","pos":"[名]","accent":"④","meaning":"那时以来，以后","example":"この方をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“那时以来，以后”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nこの方をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“那时以来，以后”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1131","seq":1131,"level":"N1","type":"主词条","word":"好ましい","kana":"このましい","pos":"[イ形]","accent":"④","meaning":"令人满意","example":"好ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“令人满意”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n好ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“令人满意”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1132","seq":1132,"level":"N1","type":"主词条","word":"拒む","kana":"こばむ","pos":"[他動1]","accent":"②","meaning":"拒绝；阻挡","example":"拒む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“拒绝；阻挡”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n拒む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“拒绝；阻挡”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1133","seq":1133,"level":"N1","type":"主词条","word":"媚びる","kana":"こびる","pos":"[自動2]","accent":"②","meaning":"谄媚，巴结","example":"媚びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“谄媚，巴结”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n媚びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“谄媚，巴结”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1134","seq":1134,"level":"N1","type":"主词条","word":"誤魔化す","kana":"ごまかす","pos":"[他動1]","accent":"③","meaning":"蒙骗；敷衍","example":"相手を誤魔化すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。","exampleZh":"用让对方感到“蒙骗；敷衍”的方法即使能一时获利，从长远看也会失去信用。","note":"例：\n相手を誤魔化すような方法では一時的に得をしても、長い目で見れば信用を失ってしまう。\n译：用让对方感到“蒙骗；敷衍”的方法即使能一时获利，从长远看也会失去信用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1135","seq":1135,"level":"N1","type":"主词条","word":"こまめに","kana":"こまめに","pos":"[副]","accent":"①⓪","meaning":"勤快地，经常","example":"機械の異常を早く見つけるには、担当者がこまめに記録を取り、小さな変化を見逃さないことが大切だ。","exampleZh":"要尽早发现机器异常，负责人需要勤做记录，不放过细小变化。","note":"例：\n機械の異常を早く見つけるには、担当者がこまめに記録を取り、小さな変化を見逃さないことが大切だ。\n译：要尽早发现机器异常，负责人需要勤做记录，不放过细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1136","seq":1136,"level":"N1","type":"主词条","word":"細やか","kana":"こまやか","pos":"[ナ形]","accent":"②","meaning":"（情意等）细心，周到；详细","example":"細やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“细心，周到；详细”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n細やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“细心，周到；详细”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1137","seq":1137,"level":"N1","type":"主词条","word":"込み上げる","kana":"こみあげる","pos":"[自動2]","accent":"④⓪","meaning":"往上涌，外溢","example":"込み上げるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“往上涌，外溢”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n込み上げるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“往上涌，外溢”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1138","seq":1138,"level":"N1","type":"主词条","word":"コメント","kana":"こめんと (comment)","pos":"[名·自動3]","accent":"⓪","meaning":"评论，说明","example":"コメントしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“评论，说明”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\nコメントしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“评论，说明”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1139","seq":1139,"level":"N1","type":"主词条","word":"籠もる","kana":"こもる","pos":"[自動1]","accent":"②","meaning":"闭门不出；充满","example":"部屋に籠もる時間が続くと気分まで沈みがちなので、彼は毎朝短く散歩する習慣をつけた。","exampleZh":"长时间闷在房间里，心情也容易低落，所以他养成了每天早晨短暂散步的习惯。","note":"例：\n部屋に籠もる時間が続くと気分まで沈みがちなので、彼は毎朝短く散歩する習慣をつけた。\n译：长时间闷在房间里，心情也容易低落，所以他养成了每天早晨短暂散步的习惯。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1140","seq":1140,"level":"N1","type":"主词条","word":"顧問","kana":"こもん","pos":"[名]","accent":"①","meaning":"顾问","example":"新しい顧問は会議で結論を急がず、若い社員の提案にも最後まで耳を傾けた。","exampleZh":"新顾问在会议上不急于下结论，也把年轻员工的提案听到了最后。","note":"例：\n新しい顧問は会議で結論を急がず、若い社員の提案にも最後まで耳を傾けた。\n译：新顾问在会议上不急于下结论，也把年轻员工的提案听到了最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1141","seq":1141,"level":"N1","type":"主词条","word":"固有","kana":"こゆう","pos":"[名·ナ形]","accent":"⓪","meaning":"固有；特有","example":"一度固有だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“固有；特有”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度固有だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“固有；特有”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1142","seq":1142,"level":"N1","type":"主词条","word":"暦","kana":"こよみ","pos":"[名]","accent":"③⓪","meaning":"日历","example":"暦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“日历”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n暦が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“日历”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1143","seq":1143,"level":"N1","type":"主词条","word":"凝らす","kana":"こらす","pos":"[他動1]","accent":"②","meaning":"集中，一心钻研","example":"無理に凝らすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“集中，一心钻研”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に凝らすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“集中，一心钻研”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1144","seq":1144,"level":"N1","type":"主词条","word":"孤立","kana":"こりつ","pos":"[名·自動3]","accent":"⓪","meaning":"孤立","example":"職場で孤立すると相談の機会が減り、小さな悩みまで抱え込んでしまうことがある。","exampleZh":"如果在职场中陷入孤立，商量的机会会减少，有时连小小烦恼也只能独自抱着。","note":"例：\n職場で孤立すると相談の機会が減り、小さな悩みまで抱え込んでしまうことがある。\n译：如果在职场中陷入孤立，商量的机会会减少，有时连小小烦恼也只能独自抱着。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1145","seq":1145,"level":"N1","type":"主词条","word":"懲りる","kana":"こりる","pos":"[自動2]","accent":"②","meaning":"尝到苦头不想再做","example":"懲りるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“尝到苦头不想再做”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n懲りるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“尝到苦头不想再做”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1146","seq":1146,"level":"N1","type":"主词条","word":"凝る","kana":"こる","pos":"[自動1]","accent":"①","meaning":"肌肉酸痛；热衷；讲究","example":"凝るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“肌肉酸痛；热衷”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n凝るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“肌肉酸痛；热衷”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1147","seq":1147,"level":"N1","type":"主词条","word":"衣替え","kana":"ころもがえ","pos":"[名]","accent":"⓪","meaning":"换季，换装","example":"衣替えを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“换季，换装”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n衣替えを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“换季，换装”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1148","seq":1148,"level":"N1","type":"主词条","word":"根気","kana":"こんき","pos":"[名]","accent":"⓪","meaning":"毅力，耐性","example":"根気を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“毅力，耐性”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n根気を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“毅力，耐性”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1149","seq":1149,"level":"N1","type":"主词条","word":"根拠","kana":"こんきょ","pos":"[名]","accent":"①","meaning":"根据","example":"根拠に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“根据”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n根拠に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“根据”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1150","seq":1150,"level":"N1","type":"主词条","word":"根源","kana":"こんげん","pos":"[名]","accent":"③⓪","meaning":"根源","example":"問題の根源を突き止めなければ、表面的な対策を重ねても同じ失敗が繰り返される。","exampleZh":"如果不查明问题的根源，即使反复采取表面对策，同样失败也会一再发生。","note":"例：\n問題の根源を突き止めなければ、表面的な対策を重ねても同じ失敗が繰り返される。\n译：如果不查明问题的根源，即使反复采取表面对策，同样失败也会一再发生。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1151","seq":1151,"level":"N1","type":"主词条","word":"言語道断","kana":"ごんごどうだん","pos":"[名·ナ形]","accent":"①","meaning":"荒谬绝伦，岂有此理","example":"言語道断な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“荒谬绝伦，岂有此理”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n言語道断な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“荒谬绝伦，岂有此理”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1152","seq":1152,"level":"N1","type":"主词条","word":"根性","kana":"こんじょう","pos":"[名]","accent":"①","meaning":"禀性；毅力，耐性","example":"根性の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“禀性；毅力，耐性”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n根性の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“禀性；毅力，耐性”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1153","seq":1153,"level":"N1","type":"主词条","word":"懇親会","kana":"こんしんかい","pos":"[名]","accent":"③","meaning":"联欢会","example":"懇親会では部署を越えた交流が生まれ、普段話す機会の少ない社員同士が意見を交わした。","exampleZh":"联欢会上产生了跨部门交流，平时很少有机会交谈的员工也交换了意见。","note":"例：\n懇親会では部署を越えた交流が生まれ、普段話す機会の少ない社員同士が意見を交わした。\n译：联欢会上产生了跨部门交流，平时很少有机会交谈的员工也交换了意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1154","seq":1154,"level":"N1","type":"主词条","word":"コンタクト","kana":"こんたくと (contact)","pos":"[名]","accent":"①③","meaning":"接触，联络；隐形眼镜","example":"コンタクトを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“接触，联络；隐形眼镜”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nコンタクトを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“接触，联络；隐形眼镜”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1155","seq":1155,"level":"N1","type":"主词条","word":"根底","kana":"こんてい","pos":"[名]","accent":"⓪","meaning":"根本，基础","example":"制度の根底にある考え方を理解しないまま細部だけを変えても、同じ混乱が繰り返されてしまう。","exampleZh":"如果不理解制度根底中的想法，只改变细节，同样的混乱仍会反复发生。","note":"例：\n制度の根底にある考え方を理解しないまま細部だけを変えても、同じ混乱が繰り返されてしまう。\n译：如果不理解制度根底中的想法，只改变细节，同样的混乱仍会反复发生。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1156","seq":1156,"level":"N1","type":"主词条","word":"コンテナ","kana":"こんてな (container)","pos":"[名]","accent":"①⓪","meaning":"集装箱，货柜","example":"コンテナが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“集装箱，货柜”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nコンテナが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“集装箱，货柜”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1157","seq":1157,"level":"N1","type":"主词条","word":"コントラスト","kana":"こんとらすと (contrast)","pos":"[名]","accent":"①④","meaning":"对比，对照","example":"コントラストに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“对比，对照”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nコントラストに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“对比，对照”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1158","seq":1158,"level":"N1","type":"主词条","word":"コントロール","kana":"こんとろーる (control)","pos":"[名·他動3]","accent":"④","meaning":"控制，调节","example":"初めてコントロールする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“控制，调节”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めてコントロールする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“控制，调节”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1159","seq":1159,"level":"N1","type":"主词条","word":"コンパス","kana":"こんぱす","pos":"[名]","accent":"①","meaning":"步幅；圆规；罗盘","example":"コンパスに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“步幅；圆规”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nコンパスに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“步幅；圆规”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1160","seq":1160,"level":"N1","type":"主词条","word":"コンプレックス","kana":"こんぷれっくす (complex)","pos":"[名]","accent":"④","meaning":"情结；自卑感","example":"コンプレックスが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“情结；自卑感”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nコンプレックスが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“情结；自卑感”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1161","seq":1161,"level":"N1","type":"主词条","word":"梱包","kana":"こんぽう","pos":"[名·他動3]","accent":"⓪","meaning":"包装","example":"梱包した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“包装”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n梱包した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“包装”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1162","seq":1162,"level":"N1","type":"主词条","word":"根本","kana":"こんぽん","pos":"[名]","accent":"⓪③","meaning":"根本","example":"根本が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“根本”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n根本が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“根本”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1163","seq":1163,"level":"N1","type":"主词条","word":"根本的","kana":"こんぽんてき","pos":"[ナ形]","accent":"⓪","meaning":"根本的","example":"周囲から根本的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“根本的”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から根本的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“根本的”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1164","seq":1164,"level":"N1","type":"主词条","word":"コンマ","kana":"こんま (comma)","pos":"[名]","accent":"①","meaning":"逗号；小数点","example":"契約書の数字ではコンマの位置を一つ間違えるだけで、金額の意味が大きく変わってしまう。","exampleZh":"合同数字中只要把逗号位置弄错一处，金额含义就会发生巨大变化。","note":"例：\n契約書の数字ではコンマの位置を一つ間違えるだけで、金額の意味が大きく変わってしまう。\n译：合同数字中只要把逗号位置弄错一处，金额含义就会发生巨大变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1165","seq":1165,"level":"N1","type":"主词条","word":"困惑","kana":"こんわく","pos":"[名·自動3]","accent":"⓪","meaning":"困惑，不知所措","example":"困惑してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“困惑，不知所措”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n困惑してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“困惑，不知所措”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1166","seq":1166,"level":"N1","type":"主词条","word":"サーカス","kana":"さーかす (circus)","pos":"[名]","accent":"①","meaning":"杂技团，马戏团","example":"サーカスの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“杂技团，马戏团”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nサーカスの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“杂技团，马戏团”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1167","seq":1167,"level":"N1","type":"主词条","word":"サービスエリア","kana":"さーびすえりあ (service area)","pos":"[名]","accent":"⑤","meaning":"（广播等）可收听范围；服务区","example":"サービスエリアの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。","exampleZh":"“可收听范围；服务区”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","note":"例：\nサービスエリアの質感は写真だけでは分かりにくいため、彼は実物を確かめてから購入を決めた。\n译：“可收听范围；服务区”的质感仅靠照片难以判断，因此他确认实物后才决定购买。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1168","seq":1168,"level":"N1","type":"主词条","word":"サーフィン","kana":"さーふぃん (surfing)","pos":"[名]","accent":"①","meaning":"冲浪","example":"サーフィンをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“冲浪”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nサーフィンをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“冲浪”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1169","seq":1169,"level":"N1","type":"主词条","word":"財","kana":"ざい","pos":"[名]","accent":"①","meaning":"财富","example":"財の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“财富”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n財の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“财富”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1170","seq":1170,"level":"N1","type":"主词条","word":"〜財","kana":"〜ざい","pos":"[接尾]","accent":"","meaning":"……财富，财产","example":"文化財を守る活動に参加した学生たちは、修復作業の大変さと地域の記憶を残す意味を実感した。","exampleZh":"参加保护文化财产活动的学生们，切身体会到修复工作的艰辛以及保留地区记忆的意义。","note":"例：\n文化財を守る活動に参加した学生たちは、修復作業の大変さと地域の記憶を残す意味を実感した。\n译：参加保护文化财产活动的学生们，切身体会到修复工作的艰辛以及保留地区记忆的意义。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1171","seq":1171,"level":"N1","type":"主词条","word":"最悪","kana":"さいあく","pos":"[名·ナ形]","accent":"⓪","meaning":"最坏，最糟","example":"最悪な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“最坏，最糟”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\n最悪な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“最坏，最糟”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1172","seq":1172,"level":"N1","type":"主词条","word":"細工","kana":"さいく","pos":"[名·他動3]","accent":"⓪","meaning":"工艺，工艺品","example":"彼は細工を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“工艺，工艺品”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は細工を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“工艺，工艺品”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1173","seq":1173,"level":"N1","type":"主词条","word":"採掘","kana":"さいくつ","pos":"[名·他動3]","accent":"⓪","meaning":"开采","example":"山間部での採掘計画には、雇用創出だけでなく環境への影響も考慮する必要がある。","exampleZh":"山区的开采计划不仅要考虑创造就业，也需要考虑对环境的影响。","note":"例：\n山間部での採掘計画には、雇用創出だけでなく環境への影響も考慮する必要がある。\n译：山区的开采计划不仅要考虑创造就业，也需要考虑对环境的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1174","seq":1174,"level":"N1","type":"主词条","word":"サイクル","kana":"さいくる (cycle)","pos":"[名]","accent":"①","meaning":"周期，循环","example":"サイクルの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“周期，循环”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nサイクルの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“周期，循环”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1175","seq":1175,"level":"N1","type":"主词条","word":"採決","kana":"さいけつ","pos":"[名·他動3]","accent":"⓪①","meaning":"表决","example":"採決する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“表决”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n採決する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“表决”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1176","seq":1176,"level":"N1","type":"主词条","word":"裁決","kana":"さいけつ","pos":"[名·他動3]","accent":"⓪","meaning":"裁决，判决","example":"チームは裁決する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“裁决，判决”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは裁決する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“裁决，判决”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1177","seq":1177,"level":"N1","type":"主词条","word":"歳月","kana":"さいげつ","pos":"[名]","accent":"①","meaning":"岁月，年月","example":"限られた歳月の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“岁月，年月”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた歳月の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“岁月，年月”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1178","seq":1178,"level":"N1","type":"主词条","word":"再建","kana":"さいけん","pos":"[名·他動3]","accent":"⓪","meaning":"重建","example":"初めて再建する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“重建”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて再建する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“重建”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1179","seq":1179,"level":"N1","type":"主词条","word":"再現","kana":"さいげん","pos":"[名·自動3]","accent":"⓪","meaning":"再现，模拟","example":"予期せず再現した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“再现，模拟”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず再現した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“再现，模拟”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1180","seq":1180,"level":"N1","type":"主词条","word":"財源","kana":"ざいげん","pos":"[名]","accent":"⓪③","meaning":"财源","example":"財源の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“财源”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n財源の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“财源”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1181","seq":1181,"level":"N1","type":"主词条","word":"在庫","kana":"ざいこ","pos":"[名]","accent":"①","meaning":"库存","example":"担当者は在庫を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“库存”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は在庫を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“库存”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1182","seq":1182,"level":"N1","type":"主词条","word":"最期","kana":"さいご","pos":"[名]","accent":"①","meaning":"临终，临死","example":"最期が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“临终，临死”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n最期が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“临终，临死”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1183","seq":1183,"level":"N1","type":"主词条","word":"採算","kana":"さいさん","pos":"[名]","accent":"⓪","meaning":"核算","example":"採算をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“核算”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n採算をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“核算”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1184","seq":1184,"level":"N1","type":"主词条","word":"採取","kana":"さいしゅ","pos":"[名·他動3]","accent":"①⓪","meaning":"采，拾取；选取","example":"研究者は川の水を採取し、工場排水の影響が出ていないか詳しく調べた。","exampleZh":"研究者采集河水，详细调查是否受到工厂废水的影响。","note":"例：\n研究者は川の水を採取し、工場排水の影響が出ていないか詳しく調べた。\n译：研究者采集河水，详细调查是否受到工厂废水的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1185","seq":1185,"level":"N1","type":"主词条","word":"採集","kana":"さいしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"搜集，采集","example":"採集した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“搜集，采集”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n採集した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“搜集，采集”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1186","seq":1186,"level":"N1","type":"主词条","word":"最上","kana":"さいじょう","pos":"[名]","accent":"⓪","meaning":"最高，最好","example":"最上が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“最高，最好”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n最上が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“最高，最好”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1187","seq":1187,"level":"N1","type":"主词条","word":"細心","kana":"さいしん","pos":"[名·ナ形]","accent":"⓪","meaning":"小心谨慎","example":"細心な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“小心谨慎”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n細心な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“小心谨慎”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1188","seq":1188,"level":"N1","type":"主词条","word":"再生","kana":"さいせい","pos":"[名·自他動3]","accent":"⓪","meaning":"播放；重生，再生","example":"録音を再生してみると、会議中には聞き逃していた発言の細かなニュアンスまで確認できた。","exampleZh":"播放录音后，连会议中漏听的发言细微语气也能确认。","note":"例：\n録音を再生してみると、会議中には聞き逃していた発言の細かなニュアンスまで確認できた。\n译：播放录音后，连会议中漏听的发言细微语气也能确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1189","seq":1189,"level":"N1","type":"主词条","word":"財政","kana":"ざいせい","pos":"[名]","accent":"⓪","meaning":"财政；家计","example":"新規事業では財政の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“财政；家计”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では財政の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“财政；家计”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1190","seq":1190,"level":"N1","type":"主词条","word":"最盛期","kana":"さいせいき","pos":"[名]","accent":"③","meaning":"最繁荣的时期","example":"最盛期をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“最繁荣的时期”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n最盛期をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“最繁荣的时期”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1191","seq":1191,"level":"N1","type":"主词条","word":"最善","kana":"さいぜん","pos":"[名]","accent":"⓪","meaning":"最好；全力","example":"最善をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“最好；全力”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n最善をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“最好；全力”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1192","seq":1192,"level":"N1","type":"主词条","word":"採択","kana":"さいたく","pos":"[名·他動3]","accent":"⓪","meaning":"通过，采纳","example":"委員会は住民の意見を反映した修正案を採択し、計画の実施時期を改めて示した。","exampleZh":"委员会采纳了反映居民意见的修正案，并重新说明了计划实施时期。","note":"例：\n委員会は住民の意見を反映した修正案を採択し、計画の実施時期を改めて示した。\n译：委员会采纳了反映居民意见的修正案，并重新说明了计划实施时期。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1193","seq":1193,"level":"N1","type":"主词条","word":"最適","kana":"さいてき","pos":"[名·ナ形]","accent":"⓪","meaning":"最合适","example":"最適な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“最合适”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n最適な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“最合适”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1194","seq":1194,"level":"N1","type":"主词条","word":"サイト","kana":"さいと (site)","pos":"[名]","accent":"①","meaning":"网站","example":"サイトを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“网站”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nサイトを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“网站”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1195","seq":1195,"level":"N1","type":"主词条","word":"再発","kana":"さいはつ","pos":"[名·自動3]","accent":"⓪","meaning":"（疾病，事故等）复发","example":"再発してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“复发”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n再発してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“复发”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1196","seq":1196,"level":"N1","type":"主词条","word":"細胞","kana":"さいぼう","pos":"[名]","accent":"⓪","meaning":"细胞","example":"細胞を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“细胞”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n細胞を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“细胞”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1197","seq":1197,"level":"N1","type":"主词条","word":"財務","kana":"ざいむ","pos":"[名]","accent":"①","meaning":"财务","example":"財務に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“财务”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n財務に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“财务”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1198","seq":1198,"level":"N1","type":"主词条","word":"在来","kana":"ざいらい","pos":"[名]","accent":"⓪①","meaning":"通常，普通；以往，原有","example":"在来が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“通常，普通；以往，原有”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n在来が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“通常，普通；以往，原有”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1199","seq":1199,"level":"N1","type":"主词条","word":"冴える","kana":"さえる","pos":"[自動2]","accent":"②","meaning":"鲜明，清晰；清醒；高超","example":"冴えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“鲜明，清晰；清醒”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n冴えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“鲜明，清晰；清醒”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1200","seq":1200,"level":"N1","type":"主词条","word":"栄える","kana":"さかえる","pos":"[自動2]","accent":"③②","meaning":"繁荣，兴旺","example":"栄える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“繁荣，兴旺”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n栄える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“繁荣，兴旺”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1201","seq":1201,"level":"N1","type":"主词条","word":"差額","kana":"さがく","pos":"[名]","accent":"⓪","meaning":"差额","example":"新規事業では差額の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“差额”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では差額の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“差额”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1202","seq":1202,"level":"N1","type":"主词条","word":"杯","kana":"さかづき","pos":"[名]","accent":"⓪④","meaning":"酒杯","example":"忙しい日でも杯を上手に取り入れれば、食事の準備に追われすぎず、家族との時間を少し増やせる。","exampleZh":"即使忙碌的日子，如果能巧妙利用杯子，也能不过分被备餐追赶，稍微增加与家人相处的时间。","note":"例：\n忙しい日でも杯を上手に取り入れれば、食事の準備に追われすぎず、家族との時間を少し増やせる。\n译：即使忙碌的日子，如果能巧妙利用杯子，也能不过分被备餐追赶，稍微增加与家人相处的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1203","seq":1203,"level":"N1","type":"主词条","word":"詐欺","kana":"さぎ","pos":"[名]","accent":"①","meaning":"诈骗","example":"詐欺をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“诈骗”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n詐欺をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“诈骗”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1204","seq":1204,"level":"N1","type":"主词条","word":"先送り","kana":"さきおくり","pos":"[名·他動3]","accent":"⓪③","meaning":"拖延，延缓","example":"問題を先送りにすれば、次の担当者がさらに大きな負担を背負うことになる。","exampleZh":"如果把问题拖延下去，下一位负责人将承担更大的负担。","note":"例：\n問題を先送りにすれば、次の担当者がさらに大きな負担を背負うことになる。\n译：如果把问题拖延下去，下一位负责人将承担更大的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1205","seq":1205,"level":"N1","type":"主词条","word":"策","kana":"さく","pos":"[名]","accent":"①②","meaning":"策划，谋略","example":"目先の策に頼るだけでは問題の根本は変わらないため、彼は長期的な方針を示した。","exampleZh":"只依靠眼前的计策并不能改变问题根本，所以他提出了长期方针。","note":"例：\n目先の策に頼るだけでは問題の根本は変わらないため、彼は長期的な方針を示した。\n译：只依靠眼前的计策并不能改变问题根本，所以他提出了长期方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1206","seq":1206,"level":"N1","type":"主词条","word":"〜作","kana":"〜さく","pos":"[接尾]","accent":"","meaning":"……作品；种植……","example":"新作の映画は映像の美しさだけでなく、地方都市で暮らす人々の孤独を丁寧に描いている。","exampleZh":"新作电影不仅影像美丽，也细致描写了生活在地方城市的人们的孤独。","note":"例：\n新作の映画は映像の美しさだけでなく、地方都市で暮らす人々の孤独を丁寧に描いている。\n译：新作电影不仅影像美丽，也细致描写了生活在地方城市的人们的孤独。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1207","seq":1207,"level":"N1","type":"主词条","word":"錯誤","kana":"さくご","pos":"[名]","accent":"①②","meaning":"错误；不相符","example":"小さな錯誤を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“错误；不相符”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな錯誤を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“错误；不相符”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1208","seq":1208,"level":"N1","type":"主词条","word":"作戦","kana":"さくせん","pos":"[名]","accent":"⓪","meaning":"作战；策略","example":"立派な作戦でも、現場の制約を無視すれば実行段階で必ず行き詰まる。","exampleZh":"即使是出色的“作战；策略”，若无视现场限制，在执行阶段也一定会受阻。","note":"例：\n立派な作戦でも、現場の制約を無視すれば実行段階で必ず行き詰まる。\n译：即使是出色的“作战；策略”，若无视现场限制，在执行阶段也一定会受阻。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1209","seq":1209,"level":"N1","type":"主词条","word":"裂ける","kana":"さける","pos":"[自動2]","accent":"②","meaning":"裂开，破裂","example":"裂けるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“裂开，破裂”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n裂けるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“裂开，破裂”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1210","seq":1210,"level":"N1","type":"主词条","word":"捧げる","kana":"ささげる","pos":"[他動2]","accent":"⓪","meaning":"献上；献出","example":"相手に何かを捧げるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“献上；献出”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを捧げるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“献上；献出”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1211","seq":1211,"level":"N1","type":"主词条","word":"差し入れ","kana":"さしいれ","pos":"[名]","accent":"⓪","meaning":"插入，投入；（送）慰劳品","example":"差し入れに支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“插入，投入；慰劳品”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n差し入れに支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“插入，投入；慰劳品”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1212","seq":1212,"level":"N1","type":"主词条","word":"差し掛かる","kana":"さしかかる","pos":"[自動1]","accent":"④⓪","meaning":"靠近；逼近，临近","example":"差し掛かる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“靠近；逼近，临近”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n差し掛かる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“靠近；逼近，临近”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1213","seq":1213,"level":"N1","type":"主词条","word":"指図","kana":"さしず","pos":"[名·他動3]","accent":"①","meaning":"指示，吩咐","example":"細かく指図するより、目的を共有して自分で考えさせたほうが部下は成長する。","exampleZh":"与其细致吩咐，不如共享目标，让部下自己思考，这样更能促使其成长。","note":"例：\n細かく指図するより、目的を共有して自分で考えさせたほうが部下は成長する。\n译：与其细致吩咐，不如共享目标，让部下自己思考，这样更能促使其成长。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1214","seq":1214,"level":"N1","type":"主词条","word":"差し支える","kana":"さしつかえる","pos":"[自動2]","accent":"⑤⓪","meaning":"妨碍","example":"差し支える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“妨碍”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n差し支える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“妨碍”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1215","seq":1215,"level":"N1","type":"主词条","word":"然して","kana":"さして","pos":"[副]","accent":"①","meaning":"（不）那么","example":"その映画は宣伝ほど派手ではないが、物語の構成は然して悪くなく、最後まで静かに引き込まれた。","exampleZh":"那部电影没有宣传中那么华丽，但故事结构并不差，直到最后都能让人安静地被吸引。","note":"例：\nその映画は宣伝ほど派手ではないが、物語の構成は然して悪くなく、最後まで静かに引き込まれた。\n译：那部电影没有宣传中那么华丽，但故事结构并不差，直到最后都能让人安静地被吸引。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1216","seq":1216,"level":"N1","type":"主词条","word":"差し引き","kana":"さしひき","pos":"[名·自他動3]","accent":"②⓪","meaning":"减去，扣除；升降","example":"初めて差し引きする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“减去，扣除；升降”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて差し引きする作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“减去，扣除；升降”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1217","seq":1217,"level":"N1","type":"主词条","word":"査証","kana":"さしょう","pos":"[名]","accent":"⓪","meaning":"签证","example":"査証を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“签证”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n査証を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“签证”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1218","seq":1218,"level":"N1","type":"主词条","word":"授かる","kana":"さずかる","pos":"[他動1]","accent":"③","meaning":"被授予，被赐予","example":"無理に授かるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“被授予，被赐予”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に授かるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“被授予，被赐予”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1219","seq":1219,"level":"N1","type":"主词条","word":"授ける","kana":"さずける","pos":"[他動2]","accent":"③","meaning":"授予，赐给；传授","example":"授けることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“授予，赐给；传授”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n授けることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“授予，赐给；传授”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1220","seq":1220,"level":"N1","type":"主词条","word":"摩る","kana":"さする","pos":"[他動1]","accent":"⓪","meaning":"摸，轻抚","example":"摩ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“摸，轻抚”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n摩ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“摸，轻抚”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1221","seq":1221,"level":"N1","type":"主词条","word":"さぞかし","kana":"さぞかし","pos":"[副]","accent":"①","meaning":"想必，一定","example":"突然の知らせを受けた家族は、さぞかし不安だっただろうと、担当者は慎重に言葉を選んだ。","exampleZh":"负责人斟酌措辞，想到突然收到消息的家人想必一定非常不安。","note":"例：\n突然の知らせを受けた家族は、さぞかし不安だっただろうと、担当者は慎重に言葉を選んだ。\n译：负责人斟酌措辞，想到突然收到消息的家人想必一定非常不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1222","seq":1222,"level":"N1","type":"主词条","word":"定まる","kana":"さだまる","pos":"[自動1]","accent":"③","meaning":"决定；安定，平息","example":"定まる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“决定；安定，平息”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n定まる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“决定；安定，平息”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1223","seq":1223,"level":"N1","type":"主词条","word":"定める","kana":"さだめる","pos":"[他動2]","accent":"③","meaning":"制定；平息","example":"無理に定めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“制定；平息”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に定めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“制定；平息”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1224","seq":1224,"level":"N1","type":"主词条","word":"雑貨","kana":"ざっか","pos":"[名]","accent":"⓪","meaning":"杂货","example":"雑貨の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“杂货”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n雑貨の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“杂货”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1225","seq":1225,"level":"N1","type":"主词条","word":"昨今","kana":"さっこん","pos":"[名]","accent":"①","meaning":"近来，最近","example":"昨今が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“近来，最近”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n昨今が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“近来，最近”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1226","seq":1226,"level":"N1","type":"主词条","word":"察する","kana":"さっする","pos":"[名·他動3]","accent":"⓪③","meaning":"推测，体谅","example":"無理に察すると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“推测，体谅”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に察すると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“推测，体谅”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1227","seq":1227,"level":"N1","type":"主词条","word":"察知","kana":"さっち","pos":"[名·他動3]","accent":"①⓪","meaning":"察觉","example":"察知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“察觉”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n察知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“察觉”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1228","seq":1228,"level":"N1","type":"主词条","word":"殺到","kana":"さっとう","pos":"[名·自動3]","accent":"⓪","meaning":"蜂拥而至","example":"殺到するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“蜂拥而至”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n殺到するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“蜂拥而至”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1229","seq":1229,"level":"N1","type":"主词条","word":"雑費","kana":"ざっぴ","pos":"[名]","accent":"⓪","meaning":"杂费","example":"担当者は雑費を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“杂费”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は雑費を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“杂费”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1230","seq":1230,"level":"N1","type":"主词条","word":"殺風景","kana":"さっぷうけい","pos":"[名·ナ形]","accent":"③","meaning":"煞风景；缺乏情趣；扫兴","example":"一度殺風景だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“煞风景；缺乏情趣”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度殺風景だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“煞风景；缺乏情趣”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1231","seq":1231,"level":"N1","type":"主词条","word":"査定","kana":"さてい","pos":"[名·他動3]","accent":"⓪","meaning":"评估，评定","example":"査定する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“评估，评定”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n査定する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“评估，评定”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1232","seq":1232,"level":"N1","type":"主词条","word":"さては","kana":"さては","pos":"[接]","accent":"①","meaning":"还有，最后还","example":"彼は遅刻し、さては資料まで忘れてきたので、会議の開始が大幅に遅れた。","exampleZh":"他迟到了，最后连资料都忘带，导致会议开始时间大幅延后。","note":"例：\n彼は遅刻し、さては資料まで忘れてきたので、会議の開始が大幅に遅れた。\n译：他迟到了，最后连资料都忘带，导致会议开始时间大幅延后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1233","seq":1233,"level":"N1","type":"主词条","word":"さては","kana":"さては","pos":"[嘆]","accent":"①","meaning":"（用于忽然发觉）原来是，看起来","example":"部屋が妙に静かだ。さては子どもたちが内緒で何か準備しているな。","exampleZh":"房间异常安静。看来孩子们在偷偷准备什么。","note":"例：\n部屋が妙に静かだ。さては子どもたちが内緒で何か準備しているな。\n译：房间异常安静。看来孩子们在偷偷准备什么。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1234","seq":1234,"level":"N1","type":"主词条","word":"作動","kana":"さどう","pos":"[名·自動3]","accent":"⓪","meaning":"发动，启动，运转；","example":"予期せず作動した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“发动，启动，运转”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず作動した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“发动，启动，运转”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1235","seq":1235,"level":"N1","type":"主词条","word":"諭す","kana":"さとす","pos":"[他動1]","accent":"②⓪","meaning":"说明，晓谕；告诫","example":"事実を諭す前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“说明，晓谕；告诫”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を諭す前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“说明，晓谕；告诫”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1236","seq":1236,"level":"N1","type":"主词条","word":"悟る","kana":"さとる","pos":"[他動1]","accent":"⓪②","meaning":"醒悟，领悟；察觉","example":"相手に何かを悟るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“醒悟，领悟；察觉”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを悟るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“醒悟，领悟；察觉”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1237","seq":1237,"level":"N1","type":"主词条","word":"最中","kana":"さなか","pos":"[名]","accent":"①","meaning":"最高潮，最盛期","example":"最中が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“最高潮，最盛期”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n最中が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“最高潮，最盛期”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1238","seq":1238,"level":"N1","type":"主词条","word":"宛ら","kana":"さながら","pos":"[副]","accent":"⓪②","meaning":"宛如，如同","example":"霧に包まれた古い町並みは宛ら映画の一場面のようで、観光客は足を止めて写真を撮っていた。","exampleZh":"被雾笼罩的古老街景宛如电影中的一幕，游客们停下脚步拍照。","note":"例：\n霧に包まれた古い町並みは宛ら映画の一場面のようで、観光客は足を止めて写真を撮っていた。\n译：被雾笼罩的古老街景宛如电影中的一幕，游客们停下脚步拍照。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1239","seq":1239,"level":"N1","type":"主词条","word":"裁く","kana":"さばく","pos":"[他動1]","accent":"②","meaning":"审判；调解","example":"無理に裁くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“审判；调解”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に裁くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“审判；调解”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1240","seq":1240,"level":"N1","type":"主词条","word":"捌く","kana":"さばく","pos":"[他動1]","accent":"②","meaning":"剔下（鸡肉，鱼等）；妥善处理","example":"人や情報を捌く立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“剔下；妥善处理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報を捌く立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“剔下；妥善处理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1241","seq":1241,"level":"N1","type":"主词条","word":"茶飯事","kana":"さはんじ","pos":"[名]","accent":"②","meaning":"司空见惯的事","example":"茶飯事が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“司空见惯的事”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n茶飯事が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“司空见惯的事”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1242","seq":1242,"level":"N1","type":"主词条","word":"サプリメント","kana":"さぷりめんと (supplement)","pos":"[名]","accent":"①","meaning":"营养补品；附录，增刊","example":"サプリメントが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“营养补品；附录，增刊”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nサプリメントが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“营养补品；附录，增刊”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1243","seq":1243,"level":"N1","type":"主词条","word":"サポート","kana":"さぽーと (support)","pos":"[名·他動3]","accent":"②","meaning":"支持，支援","example":"新人をサポートする際には、答えをすぐ教えるより、自分で考える余地を残すことも大切だ。","exampleZh":"支援新人时，比起马上告诉答案，留下让其自己思考的余地也很重要。","note":"例：\n新人をサポートする際には、答えをすぐ教えるより、自分で考える余地を残すことも大切だ。\n译：支援新人时，比起马上告诉答案，留下让其自己思考的余地也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1244","seq":1244,"level":"N1","type":"主词条","word":"さほど","kana":"さほど","pos":"[副]","accent":"⓪","meaning":"（不）那么，（不）怎么","example":"作業はさほど難しくないが、確認を怠ると小さな入力ミスが大きな問題につながる。","exampleZh":"作业并没有那么难，但若怠于确认，小小输入错误也会引发大问题。","note":"例：\n作業はさほど難しくないが、確認を怠ると小さな入力ミスが大きな問題につながる。\n译：作业并没有那么难，但若怠于确认，小小输入错误也会引发大问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1245","seq":1245,"level":"N1","type":"主词条","word":"サボる","kana":"さぼる","pos":"[他動1]","accent":"②","meaning":"怠工，旷课，逃学","example":"自分の道をサボるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“怠工，旷课，逃学”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道をサボるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“怠工，旷课，逃学”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1246","seq":1246,"level":"N1","type":"主词条","word":"様変わり","kana":"さまがわり","pos":"[名·自動3]","accent":"③","meaning":"情况发生变化；行情突变","example":"様変わりするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“情况发生变化；行情突变”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n様変わりするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“情况发生变化；行情突变”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1247","seq":1247,"level":"N1","type":"主词条","word":"さまよう","kana":"さまよう","pos":"[自動1]","accent":"③","meaning":"彷徨，徘徊","example":"さまよう場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“彷徨，徘徊”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\nさまよう場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“彷徨，徘徊”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1248","seq":1248,"level":"N1","type":"主词条","word":"寒気","kana":"さむけ","pos":"[名]","accent":"③","meaning":"发冷，发寒","example":"突然の寒気で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“发冷，发寒”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の寒気で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“发冷，发寒”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1249","seq":1249,"level":"N1","type":"主词条","word":"侍","kana":"さむらい","pos":"[名]","accent":"⓪","meaning":"武士；有骨气的人","example":"侍として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“武士；有骨气的人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n侍として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“武士；有骨气的人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1250","seq":1250,"level":"N1","type":"主词条","word":"さも","kana":"さも","pos":"[副]","accent":"①","meaning":"好像；非常","example":"彼はさも当然のことのように手柄を自分のものにしたが、周囲はその態度に不信感を抱いた。","exampleZh":"他仿佛理所当然地把功劳据为己有，周围人对这种态度产生了不信任感。","note":"例：\n彼はさも当然のことのように手柄を自分のものにしたが、周囲はその態度に不信感を抱いた。\n译：他仿佛理所当然地把功劳据为己有，周围人对这种态度产生了不信任感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1251","seq":1251,"level":"N1","type":"主词条","word":"さもないと","kana":"さもないと","pos":"[接]","accent":"①","meaning":"不然的话，否则","example":"資料は今日中に提出してください。さもないと、明日の審査に間に合いません。","exampleZh":"请在今天之内提交资料。否则就赶不上明天的审查。","note":"例：\n資料は今日中に提出してください。さもないと、明日の審査に間に合いません。\n译：请在今天之内提交资料。否则就赶不上明天的审查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1252","seq":1252,"level":"N1","type":"主词条","word":"作用","kana":"さよう","pos":"[名·自動3]","accent":"①","meaning":"作用","example":"作用する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“作用”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n作用する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“作用”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1253","seq":1253,"level":"N1","type":"主词条","word":"攫う","kana":"さらう","pos":"[他動1]","accent":"⓪","meaning":"夺取，掠夺；取得","example":"攫う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“夺取，掠夺；取得”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n攫う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“夺取，掠夺；取得”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1254","seq":1254,"level":"N1","type":"主词条","word":"浚う","kana":"さらう","pos":"[他動1]","accent":"⓪","meaning":"疏浚，疏通","example":"自分の道を浚うなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“疏浚，疏通”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を浚うなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“疏浚，疏通”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1255","seq":1255,"level":"N1","type":"主词条","word":"さらう","kana":"さらう","pos":"[他動1]","accent":"⓪","meaning":"复习","example":"相手に何かをさらうなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“复习”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かをさらうなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“复习”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1256","seq":1256,"level":"N1","type":"主词条","word":"サラ金","kana":"さらきん","pos":"[名]","accent":"⓪","meaning":"小额高利贷","example":"市場環境が変わるなかでサラ金をどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“小额高利贷”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかでサラ金をどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“小额高利贷”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1257","seq":1257,"level":"N1","type":"主词条","word":"晒す/曝す","kana":"さらす","pos":"[他動1]","accent":"⓪","meaning":"暴晒；暴露于","example":"強い日差しに長時間肌を晒すと、思った以上に体力を奪われるので注意が必要だ。","exampleZh":"如果皮肤长时间暴露在强烈阳光下，会比想象中更消耗体力，因此需要注意。","note":"例：\n強い日差しに長時間肌を晒すと、思った以上に体力を奪われるので注意が必要だ。\n译：如果皮肤长时间暴露在强烈阳光下，会比想象中更消耗体力，因此需要注意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1258","seq":1258,"level":"N1","type":"主词条","word":"更なる","kana":"さらなる","pos":"[連体]","accent":"①","meaning":"进一步，更加","example":"更なる品質向上を目指し、工場では検査工程の見直しが始まった。","exampleZh":"为了进一步提升品质，工厂开始重新审视检查流程。","note":"例：\n更なる品質向上を目指し、工場では検査工程の見直しが始まった。\n译：为了进一步提升品质，工厂开始重新审视检查流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1259","seq":1259,"level":"N1","type":"主词条","word":"障る","kana":"さわる","pos":"[自動1]","accent":"⓪","meaning":"妨碍；危害","example":"障る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“妨碍；危害”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n障る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“妨碍；危害”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1260","seq":1260,"level":"N1","type":"主词条","word":"傘下","kana":"さんか","pos":"[名]","accent":"①","meaning":"系统下，隶属","example":"傘下に頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。","exampleZh":"如果过度依赖“系统下，隶属”，可能忽视细小异常，因此现场仍保留人工确认。","note":"例：\n傘下に頼りすぎると小さな異常を見逃す恐れがあるため、現場では人の確認も残している。\n译：如果过度依赖“系统下，隶属”，可能忽视细小异常，因此现场仍保留人工确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1261","seq":1261,"level":"N1","type":"主词条","word":"山岳","kana":"さんがく","pos":"[名]","accent":"⓪","meaning":"山岳","example":"山岳の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“山岳”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n山岳の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“山岳”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1262","seq":1262,"level":"N1","type":"主词条","word":"産休","kana":"さんきゅう","pos":"[名]","accent":"⓪","meaning":"产假","example":"産休をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“产假”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n産休をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“产假”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1263","seq":1263,"level":"N1","type":"主词条","word":"残金","kana":"ざんきん","pos":"[名]","accent":"①","meaning":"余额；余下的欠款","example":"旅行の残金を確認した彼は、予定外の出費に備えて買い物の優先順位を決め直した。","exampleZh":"确认旅行余款后，他为应对计划外支出，重新决定了购物的优先顺序。","note":"例：\n旅行の残金を確認した彼は、予定外の出費に備えて買い物の優先順位を決め直した。\n译：确认旅行余款后，他为应对计划外支出，重新决定了购物的优先顺序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1264","seq":1264,"level":"N1","type":"主词条","word":"産出","kana":"さんしゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"出产","example":"チームは産出する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“出产”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは産出する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“出产”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1265","seq":1265,"level":"N1","type":"主词条","word":"参照","kana":"さんしょう","pos":"[名·他動3]","accent":"⓪","meaning":"参照","example":"参照した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“参照”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n参照した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“参照”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1266","seq":1266,"level":"N1","type":"主词条","word":"参上","kana":"さんじょう","pos":"[名·自動3]","accent":"⓪","meaning":"拜访","example":"参上した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“拜访”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n参上した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“拜访”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1267","seq":1267,"level":"N1","type":"主词条","word":"残高","kana":"ざんだか","pos":"[名]","accent":"①⓪","meaning":"余额","example":"新規事業では残高の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“余额”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では残高の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“余额”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1268","seq":1268,"level":"N1","type":"主词条","word":"参入","kana":"さんにゅう","pos":"[名·自動3]","accent":"⓪","meaning":"进入，新加入","example":"参入する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“进入，新加入”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n参入する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“进入，新加入”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1269","seq":1269,"level":"N1","type":"主词条","word":"桟橋","kana":"さんばし","pos":"[名]","accent":"⓪","meaning":"码头，栈桥","example":"担当者は桟橋の位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。","exampleZh":"负责人不仅确认“码头，栈桥”的位置，也确认了使用者行走路线和夜间安全性。","note":"例：\n担当者は桟橋の位置だけでなく、利用者が歩く経路や夜間の安全性まで確認した。\n译：负责人不仅确认“码头，栈桥”的位置，也确认了使用者行走路线和夜间安全性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1270","seq":1270,"level":"N1","type":"主词条","word":"賛美","kana":"さんび","pos":"[名·他動3]","accent":"①","meaning":"赞美","example":"賛美する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“赞美”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n賛美する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“赞美”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1271","seq":1271,"level":"N1","type":"主词条","word":"賛否","kana":"さんぴ","pos":"[名]","accent":"①","meaning":"赞成与否","example":"賛否の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“赞成与否”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n賛否の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“赞成与否”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1272","seq":1272,"level":"N1","type":"主词条","word":"産物","kana":"さんぶつ","pos":"[名]","accent":"⓪","meaning":"产物","example":"修繕計画では産物の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。","exampleZh":"修缮计划不仅考虑了“产物”的费用，也考虑了施工期间对周边居民的影响。","note":"例：\n修繕計画では産物の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。\n译：修缮计划不仅考虑了“产物”的费用，也考虑了施工期间对周边居民的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1273","seq":1273,"level":"N1","type":"主词条","word":"山脈","kana":"さんみゃく","pos":"[名]","accent":"⓪","meaning":"山脉","example":"山脈の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“山脉”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n山脈の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“山脉”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1274","seq":1274,"level":"N1","type":"主词条","word":"〜士","kana":"〜し","pos":"[接尾]","accent":"","meaning":"具有特别资格的人，从事特别工作的人","example":"弁護士に契約書を確認してもらったことで、曖昧だった責任範囲がはっきりした。","exampleZh":"请律师确认合同后，此前含糊的责任范围变得清楚了。","note":"例：\n弁護士に契約書を確認してもらったことで、曖昧だった責任範囲がはっきりした。\n译：请律师确认合同后，此前含糊的责任范围变得清楚了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1275","seq":1275,"level":"N1","type":"主词条","word":"〜視","kana":"〜し","pos":"[接尾]","accent":"","meaning":"认为，以为，当做……","example":"彼はその発言を問題視し、個人の感情ではなく組織として再発を防ぐ仕組みを提案した。","exampleZh":"他把那番发言视为问题，并提出了不是基于个人情绪，而是作为组织防止再发的机制。","note":"例：\n彼はその発言を問題視し、個人の感情ではなく組織として再発を防ぐ仕組みを提案した。\n译：他把那番发言视为问题，并提出了不是基于个人情绪，而是作为组织防止再发的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1276","seq":1276,"level":"N1","type":"主词条","word":"〜児","kana":"〜じ","pos":"[接尾]","accent":"","meaning":"儿童，幼儿；人","example":"園児たちが園庭で元気に遊んでいる間、保育士はけがをしやすい場所を注意深く見守っていた。","exampleZh":"幼儿们在园内庭院里精神十足地玩耍时，保育员仔细看护容易受伤的地方。","note":"例：\n園児たちが園庭で元気に遊んでいる間、保育士はけがをしやすい場所を注意深く見守っていた。\n译：幼儿们在园内庭院里精神十足地玩耍时，保育员仔细看护容易受伤的地方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1277","seq":1277,"level":"N1","type":"主词条","word":"仕上げる","kana":"しあげる","pos":"[他動2]","accent":"③","meaning":"完成，做完","example":"無理に仕上げるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“完成，做完”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に仕上げるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“完成，做完”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1278","seq":1278,"level":"N1","type":"主词条","word":"試案","kana":"しあん","pos":"[名]","accent":"⓪","meaning":"试行方案","example":"試案を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“试行方案”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n試案を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“试行方案”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1279","seq":1279,"level":"N1","type":"主词条","word":"CM","kana":"しーえむ","pos":"[名]","accent":"⓪","meaning":"商业广告（多指电视广告）","example":"新規事業ではCMの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“商业广告”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業ではCMの見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“商业广告”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1280","seq":1280,"level":"N1","type":"主词条","word":"強いて","kana":"しいて","pos":"[副]","accent":"①","meaning":"强迫；硬要","example":"強いて欠点を挙げるなら資料が少し長いことだが、内容自体はよく整理されている。","exampleZh":"如果硬要指出缺点，那就是资料稍微有些长，但内容本身整理得很好。","note":"例：\n強いて欠点を挙げるなら資料が少し長いことだが、内容自体はよく整理されている。\n译：如果硬要指出缺点，那就是资料稍微有些长，但内容本身整理得很好。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1281","seq":1281,"level":"N1","type":"主词条","word":"シート","kana":"しーと (seat)","pos":"[名]","accent":"①","meaning":"座位，席位","example":"シートが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“座位，席位”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nシートが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“座位，席位”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1282","seq":1282,"level":"N1","type":"主词条","word":"ジープ","kana":"じーぷ (jeep)","pos":"[名]","accent":"①","meaning":"吉普车","example":"新しいジープが整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。","exampleZh":"新的“吉普车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","note":"例：\n新しいジープが整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。\n译：新的“吉普车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1283","seq":1283,"level":"N1","type":"主词条","word":"強いる","kana":"しいる","pos":"[他動2]","accent":"②","meaning":"强迫，强制","example":"無理に強いるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“强迫，强制”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に強いるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“强迫，强制”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1284","seq":1284,"level":"N1","type":"主词条","word":"仕入れ","kana":"しいれ","pos":"[名]","accent":"⓪","meaning":"采购，买进","example":"仕入れが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“采购，买进”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n仕入れが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“采购，买进”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1285","seq":1285,"level":"N1","type":"主词条","word":"試飲","kana":"しいん","pos":"[名·他動3]","accent":"⓪","meaning":"品尝，试饮","example":"新商品の発売前に、来場者にコーヒーを試飲してもらい、香りや苦味への反応を調べた。","exampleZh":"新商品上市前，让到场者试饮咖啡，以调查他们对香气和苦味的反应。","note":"例：\n新商品の発売前に、来場者にコーヒーを試飲してもらい、香りや苦味への反応を調べた。\n译：新商品上市前，让到场者试饮咖啡，以调查他们对香气和苦味的反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1286","seq":1286,"level":"N1","type":"主词条","word":"シェア","kana":"しぇあ (share)","pos":"[名]","accent":"①","meaning":"市场占有率，份额","example":"市場環境が変わるなかでシェアをどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“市场占有率，份额”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかでシェアをどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“市场占有率，份额”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1287","seq":1287,"level":"N1","type":"主词条","word":"自営","kana":"じえい","pos":"[名·他動3]","accent":"⓪","meaning":"个体经营，独立经营","example":"自営する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“个体经营，独立经营”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n自営する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“个体经营，独立经营”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1288","seq":1288,"level":"N1","type":"主词条","word":"ジェット機","kana":"じぇっとき","pos":"[名]","accent":"③","meaning":"喷气式飞机","example":"ジェット機の騒音を減らすため、空港周辺では離着陸の時間帯が細かく調整されている。","exampleZh":"为了减少喷气式飞机噪音，机场周边对起降时间段进行了细致调整。","note":"例：\nジェット機の騒音を減らすため、空港周辺では離着陸の時間帯が細かく調整されている。\n译：为了减少喷气式飞机噪音，机场周边对起降时间段进行了细致调整。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1289","seq":1289,"level":"N1","type":"主词条","word":"萎れる","kana":"しおれる","pos":"[自動2]","accent":"⓪","meaning":"植物枯萎；灰心丧气，意志消沉","example":"萎れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“植物枯萎；灰心丧气，意志消沉”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n萎れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“植物枯萎；灰心丧气，意志消沉”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1290","seq":1290,"level":"N1","type":"主词条","word":"歯科","kana":"しか","pos":"[名]","accent":"①②","meaning":"牙科","example":"過労が続くと歯科に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。","exampleZh":"过劳持续后，“牙科”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","note":"例：\n過労が続くと歯科に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。\n译：过劳持续后，“牙科”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1291","seq":1291,"level":"N1","type":"主词条","word":"視界","kana":"しかい","pos":"[名]","accent":"⓪","meaning":"视野","example":"視界をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“视野”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n視界をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“视野”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1292","seq":1292,"level":"N1","type":"主词条","word":"市街","kana":"しがい","pos":"[名]","accent":"①","meaning":"城镇，市区；繁华街道","example":"夕方の市街は帰宅する人で混み合い、バス停には長い列ができていた。","exampleZh":"傍晚的市区挤满了回家的人，公交站前排起了长队。","note":"例：\n夕方の市街は帰宅する人で混み合い、バス停には長い列ができていた。\n译：傍晚的市区挤满了回家的人，公交站前排起了长队。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1293","seq":1293,"level":"N1","type":"主词条","word":"仕返し","kana":"しかえし","pos":"[名·自動3]","accent":"⓪","meaning":"报复；重做","example":"仕返しを考えるより、なぜ関係がこじれたのかを冷静に振り返るほうが解決に近づく。","exampleZh":"与其考虑报复，不如冷静回顾关系为什么变僵，这样更接近解决问题。","note":"例：\n仕返しを考えるより、なぜ関係がこじれたのかを冷静に振り返るほうが解決に近づく。\n译：与其考虑报复，不如冷静回顾关系为什么变僵，这样更接近解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1294","seq":1294,"level":"N1","type":"主词条","word":"自覚","kana":"じかく","pos":"[名·他動3]","accent":"⓪","meaning":"自知；觉悟","example":"自覚する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“自知；觉悟”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n自覚する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“自知；觉悟”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1295","seq":1295,"level":"N1","type":"主词条","word":"仕掛け","kana":"しかけ","pos":"[名]","accent":"⓪","meaning":"装置，机关","example":"仕掛けの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“装置，机关”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n仕掛けの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“装置，机关”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1296","seq":1296,"level":"N1","type":"主词条","word":"仕掛ける","kana":"しかける","pos":"[他動2]","accent":"③","meaning":"挑衅；安装","example":"無理に仕掛けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“挑衅；安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に仕掛けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“挑衅；安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1297","seq":1297,"level":"N1","type":"主词条","word":"しかしながら","kana":"しかしながら","pos":"[接]","accent":"④","meaning":"但是，然而","example":"計画はおおむね順調に進んでいる。しかしながら、予算不足という課題はまだ残っている。","exampleZh":"计划大体进展顺利。然而，预算不足这一课题仍然存在。","note":"例：\n計画はおおむね順調に進んでいる。しかしながら、予算不足という課題はまだ残っている。\n译：计划大体进展顺利。然而，预算不足这一课题仍然存在。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1298","seq":1298,"level":"N1","type":"主词条","word":"しがみつく","kana":"しがみつく","pos":"[自動1]","accent":"④","meaning":"紧紧抱住；抓住不放手","example":"しがみつく場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“紧紧抱住；抓住不放手”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\nしがみつく場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“紧紧抱住；抓住不放手”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1299","seq":1299,"level":"N1","type":"主词条","word":"しかるべき","kana":"しかるべき","pos":"[連語]","accent":"④","meaning":"适当的，应有的","example":"苦情が寄せられた以上、しかるべき手続きを経て事実関係を調査する必要がある。","exampleZh":"既然收到了投诉，就有必要经过适当程序调查事实关系。","note":"例：\n苦情が寄せられた以上、しかるべき手続きを経て事実関係を調査する必要がある。\n译：既然收到了投诉，就有必要经过适当程序调查事实关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1300","seq":1300,"level":"N1","type":"主词条","word":"志願","kana":"しがん","pos":"[名·自他動3]","accent":"①","meaning":"志愿；报名，申请","example":"彼は志願を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“志愿；报名，申请”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は志願を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“志愿；报名，申请”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1301","seq":1301,"level":"N1","type":"主词条","word":"敷金","kana":"しききん","pos":"[名]","accent":"②","meaning":"押金，保证金","example":"退去時の敷金をめぐるトラブルを避けるため、入居前に傷や汚れを写真で記録しておいた。","exampleZh":"为了避免退租时围绕押金产生纠纷，入住前就用照片记录了划痕和污渍。","note":"例：\n退去時の敷金をめぐるトラブルを避けるため、入居前に傷や汚れを写真で記録しておいた。\n译：为了避免退租时围绕押金产生纠纷，入住前就用照片记录了划痕和污渍。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1302","seq":1302,"level":"N1","type":"主词条","word":"色彩","kana":"しきさい","pos":"[名]","accent":"⓪","meaning":"色彩，性质，倾向","example":"新しい色彩を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的“色彩，性质，倾向”，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しい色彩を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的“色彩，性质，倾向”，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1303","seq":1303,"level":"N1","type":"主词条","word":"式場","kana":"しきじょう","pos":"[名]","accent":"⓪","meaning":"举行仪式的会场","example":"その式場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“举行仪式的会场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその式場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“举行仪式的会场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1304","seq":1304,"level":"N1","type":"主词条","word":"直訴","kana":"じきそ","pos":"[名·他動3]","accent":"①","meaning":"直接上诉，上告","example":"チームは直訴する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“直接上诉，上告”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは直訴する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“直接上诉，上告”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1305","seq":1305,"level":"N1","type":"主词条","word":"しきたり","kana":"しきたり","pos":"[名]","accent":"⓪","meaning":"惯例，规矩","example":"しきたりを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“惯例，规矩”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nしきたりを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“惯例，规矩”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1306","seq":1306,"level":"N1","type":"主词条","word":"自給","kana":"じきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"自给，自食其力","example":"初めて自給する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“自给，自食其力”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて自給する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“自给，自食其力”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1307","seq":1307,"level":"N1","type":"主词条","word":"仕切り","kana":"しきり","pos":"[名]","accent":"⓪","meaning":"隔开，间隔","example":"仕切りの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“隔开，间隔”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n仕切りの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“隔开，间隔”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1308","seq":1308,"level":"N1","type":"主词条","word":"仕切る","kana":"しきる","pos":"[他動1]","accent":"②","meaning":"隔开；掌管","example":"無理に仕切るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“隔开；掌管”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に仕切るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“隔开；掌管”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1309","seq":1309,"level":"N1","type":"主词条","word":"軸","kana":"じく","pos":"[名]","accent":"②","meaning":"轴，中心，主要","example":"軸の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“轴，中心，主要”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n軸の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“轴，中心，主要”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1310","seq":1310,"level":"N1","type":"主词条","word":"しくじる","kana":"しくじる","pos":"[自動1]","accent":"③","meaning":"失败","example":"しくじるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“失败”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\nしくじるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“失败”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1311","seq":1311,"level":"N1","type":"主词条","word":"仕組む","kana":"しくむ","pos":"[他動1]","accent":"②","meaning":"策划，计划；构思，编写","example":"仕組む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“策划，计划；构思，编写”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n仕組む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“策划，计划；构思，编写”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1312","seq":1312,"level":"N1","type":"主词条","word":"次元","kana":"じげん","pos":"[名]","accent":"⓪","meaning":"水平；立场，着眼点","example":"次元の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“水平；立场，着眼点”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n次元の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“水平；立场，着眼点”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1313","seq":1313,"level":"N1","type":"主词条","word":"嗜好","kana":"しこう","pos":"[名]","accent":"⓪","meaning":"嗜好，爱好","example":"嗜好を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“嗜好，爱好”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n嗜好を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“嗜好，爱好”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1314","seq":1314,"level":"N1","type":"主词条","word":"思考","kana":"しこう","pos":"[名·自他動3]","accent":"⓪","meaning":"思考","example":"初めて思考する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“思考”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて思考する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“思考”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1315","seq":1315,"level":"N1","type":"主词条","word":"施行","kana":"しこう","pos":"[名·他動3]","accent":"⓪","meaning":"实施，施行","example":"施行の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“实施，施行”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n施行の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“实施，施行”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1316","seq":1316,"level":"N1","type":"主词条","word":"試行","kana":"しこう","pos":"[名·他動3]","accent":"⓪","meaning":"试行","example":"彼は試行を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“试行”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は試行を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“试行”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1317","seq":1317,"level":"N1","type":"主词条","word":"試行錯誤","kana":"しこうさくご","pos":"[名]","accent":"④","meaning":"反复试验，反复摸索","example":"試行錯誤を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“反复试验，反复摸索”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n試行錯誤を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“反复试验，反复摸索”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1318","seq":1318,"level":"N1","type":"主词条","word":"示唆","kana":"しさ","pos":"[名·他動3]","accent":"①","meaning":"暗示，启示","example":"示唆する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“暗示，启示”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n示唆する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“暗示，启示”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1319","seq":1319,"level":"N1","type":"主词条","word":"自在","kana":"じざい","pos":"[名·ナ形]","accent":"⓪","meaning":"自如，自在","example":"一見自在な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“自如，自在”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見自在な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“自如，自在”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1320","seq":1320,"level":"N1","type":"主词条","word":"思索","kana":"しさく","pos":"[名·自他動3]","accent":"⓪","meaning":"思考，思索","example":"チームは思索する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“思考，思索”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは思索する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“思考，思索”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1321","seq":1321,"level":"N1","type":"主词条","word":"視察","kana":"しさつ","pos":"[名·他動3]","accent":"⓪","meaning":"视察","example":"視察した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“视察”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n視察した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“视察”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1322","seq":1322,"level":"N1","type":"主词条","word":"自主","kana":"じしゅ","pos":"[名]","accent":"①","meaning":"自主","example":"自主をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“自主”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n自主をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“自主”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1323","seq":1323,"level":"N1","type":"主词条","word":"刺繍","kana":"ししゅう","pos":"[名·他動3]","accent":"⓪","meaning":"刺绣","example":"刺繍の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“刺绣”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n刺繍の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“刺绣”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1324","seq":1324,"level":"N1","type":"主词条","word":"自粛","kana":"じしゅく","pos":"[名·他動3]","accent":"⓪","meaning":"自慎，自我约束","example":"彼は自粛を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“自慎，自我约束”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は自粛を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“自慎，自我约束”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1325","seq":1325,"level":"N1","type":"主词条","word":"史上","kana":"しじょう","pos":"[名]","accent":"⓪","meaning":"历史上","example":"その選手は史上最年少で優勝し、多くの若者に挑戦する勇気を与えた。","exampleZh":"那名选手成为历史上最年轻的冠军，给予许多年轻人挑战的勇气。","note":"例：\nその選手は史上最年少で優勝し、多くの若者に挑戦する勇気を与えた。\n译：那名选手成为历史上最年轻的冠军，给予许多年轻人挑战的勇气。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1326","seq":1326,"level":"N1","type":"主词条","word":"私情","kana":"しじょう","pos":"[名]","accent":"⓪","meaning":"个人的感情；私心","example":"私情として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“个人的感情；私心”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n私情として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“个人的感情；私心”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1327","seq":1327,"level":"N1","type":"主词条","word":"試食","kana":"ししょく","pos":"[名·他動3]","accent":"⓪","meaning":"品尝，试吃","example":"試食する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“品尝，试吃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n試食する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“品尝，试吃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1328","seq":1328,"level":"N1","type":"主词条","word":"自炊","kana":"じすい","pos":"[名·自動3]","accent":"⓪","meaning":"自己做饭","example":"自炊するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“自己做饭”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n自炊するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“自己做饭”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1329","seq":1329,"level":"N1","type":"主词条","word":"滴","kana":"しずく","pos":"[名]","accent":"③","meaning":"水滴","example":"研究者は滴の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“水滴”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は滴の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“水滴”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1330","seq":1330,"level":"N1","type":"主词条","word":"静まり返る","kana":"しずまりかえる","pos":"[自動1]","accent":"⑤③","meaning":"万籁俱寂，静悄悄","example":"発表された数字が予想より悪く、会場は一瞬静まり返ったが、司会者は落ち着いて次の質問を促した。","exampleZh":"公布的数字比预期更糟，会场一瞬间鸦雀无声，但主持人冷静地引导了下一个问题。","note":"例：\n発表された数字が予想より悪く、会場は一瞬静まり返ったが、司会者は落ち着いて次の質問を促した。\n译：公布的数字比预期更糟，会场一瞬间鸦雀无声，但主持人冷静地引导了下一个问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1331","seq":1331,"level":"N1","type":"主词条","word":"持続","kana":"じぞく","pos":"[名·自他動3]","accent":"⓪","meaning":"持续，保持","example":"持続の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“持续，保持”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n持続の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“持续，保持”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1332","seq":1332,"level":"N1","type":"主词条","word":"自尊心","kana":"じそんしん","pos":"[名]","accent":"②","meaning":"自尊心","example":"自尊心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“自尊心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n自尊心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“自尊心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1333","seq":1333,"level":"N1","type":"主词条","word":"辞退","kana":"じたい","pos":"[名·他動3]","accent":"⓪","meaning":"谢绝，婉拒","example":"体調が戻らないため、彼女は残念ながら式典での挨拶を辞退した。","exampleZh":"由于身体状况尚未恢复，她很遗憾地婉拒了在典礼上致辞。","note":"例：\n体調が戻らないため、彼女は残念ながら式典での挨拶を辞退した。\n译：由于身体状况尚未恢复，她很遗憾地婉拒了在典礼上致辞。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1334","seq":1334,"level":"N1","type":"主词条","word":"〜自体","kana":"〜じたい","pos":"[接尾]","accent":"","meaning":"……本身，自身","example":"計画自体に大きな問題はないが、実行する人員と予算をどう確保するかが課題として残っている。","exampleZh":"计划本身没有大问题，但如何确保执行人员和预算仍是课题。","note":"例：\n計画自体に大きな問題はないが、実行する人員と予算をどう確保するかが課題として残っている。\n译：计划本身没有大问题，但如何确保执行人员和预算仍是课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1335","seq":1335,"level":"N1","type":"主词条","word":"慕う","kana":"したう","pos":"[他動1]","accent":"⓪②","meaning":"怀念；追随；景仰","example":"慕うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“怀念；追随”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n慕うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“怀念；追随”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1336","seq":1336,"level":"N1","type":"主词条","word":"下請け","kana":"したうけ","pos":"[名·他動3]","accent":"⓪","meaning":"转包，分包","example":"下請けした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“转包，分包”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n下請けした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“转包，分包”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1337","seq":1337,"level":"N1","type":"主词条","word":"下心","kana":"したごころ","pos":"[名]","accent":"③","meaning":"用心，企图","example":"下心のある親切は、最初は好意に見えても、後から相手の警戒心を強めてしまう。","exampleZh":"带有企图的好意，起初看似善意，之后却会增强对方的戒心。","note":"例：\n下心のある親切は、最初は好意に見えても、後から相手の警戒心を強めてしまう。\n译：带有企图的好意，起初看似善意，之后却会增强对方的戒心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1338","seq":1338,"level":"N1","type":"主词条","word":"下地","kana":"したじ","pos":"[名]","accent":"⓪","meaning":"基础；资质","example":"新人研修で基礎を丁寧に学んだことが、複雑な案件に向き合う下地になった。","exampleZh":"在新人培训中细致学习基础，成为了面对复杂案件的底子。","note":"例：\n新人研修で基礎を丁寧に学んだことが、複雑な案件に向き合う下地になった。\n译：在新人培训中细致学习基础，成为了面对复杂案件的底子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1339","seq":1339,"level":"N1","type":"主词条","word":"下調べ","kana":"したしらべ","pos":"[名·他動3]","accent":"③⓪","meaning":"预先调查","example":"下調べするだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。","exampleZh":"他没有只满足于“预先调查”本身，而是进一步思考结果如何连接到现场改善。","note":"例：\n下調べするだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。\n译：他没有只满足于“预先调查”本身，而是进一步思考结果如何连接到现场改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1340","seq":1340,"level":"N1","type":"主词条","word":"仕立てる","kana":"したてる","pos":"[他動2]","accent":"③","meaning":"缝制衣服；教育，培养；准备","example":"仕立てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“缝制衣服；教育，培养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n仕立てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“缝制衣服；教育，培养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1341","seq":1341,"level":"N1","type":"主词条","word":"下取り","kana":"したどり","pos":"[名·他動3]","accent":"⓪","meaning":"以旧换新","example":"下取りする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“以旧换新”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n下取りする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“以旧换新”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1342","seq":1342,"level":"N1","type":"主词条","word":"下火","kana":"したび","pos":"[名]","accent":"⓪","meaning":"火势渐微；势头衰弱","example":"下火の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“火势渐微；势头衰弱”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n下火の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“火势渐微；势头衰弱”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1343","seq":1343,"level":"N1","type":"主词条","word":"下役","kana":"したやく","pos":"[名]","accent":"⓪","meaning":"部下，下属","example":"経験豊かな下役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“部下，下属”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな下役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“部下，下属”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1344","seq":1344,"level":"N1","type":"主词条","word":"質","kana":"しち","pos":"[名]","accent":"②","meaning":"典当，抵押","example":"質を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“典当，抵押”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n質を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“典当，抵押”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1345","seq":1345,"level":"N1","type":"主词条","word":"質屋","kana":"しちや","pos":"[名]","accent":"②","meaning":"典当业者；当铺","example":"質屋が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“典当业者；当铺”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n質屋が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“典当业者；当铺”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1346","seq":1346,"level":"N1","type":"主词条","word":"試着","kana":"しちゃく","pos":"[名·他動3]","accent":"⓪","meaning":"试穿，试衣","example":"初めて試着する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“试穿，试衣”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて試着する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“试穿，试衣”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1347","seq":1347,"level":"N1","type":"主词条","word":"実","kana":"じつ","pos":"[名]","accent":"⓪","meaning":"实质；真实；亲的（有血缘关系）","example":"長く続いた実でも、一度失われた信頼を取り戻すには、小さな約束を守り続けるしかない。","exampleZh":"即便是长期延续的真实关系，一旦失去信任，也只能靠持续遵守小小约定来挽回。","note":"例：\n長く続いた実でも、一度失われた信頼を取り戻すには、小さな約束を守り続けるしかない。\n译：即便是长期延续的真实关系，一旦失去信任，也只能靠持续遵守小小约定来挽回。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1348","seq":1348,"level":"N1","type":"主词条","word":"実益","kana":"じつえき","pos":"[名]","accent":"⓪","meaning":"实际利益","example":"新規事業では実益の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“实际利益”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では実益の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“实际利益”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1349","seq":1349,"level":"N1","type":"主词条","word":"失格","kana":"しっかく","pos":"[名·自動3]","accent":"⓪","meaning":"不够格；失去资格","example":"予期せず失格した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“不够格；失去资格”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず失格した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“不够格；失去资格”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1350","seq":1350,"level":"N1","type":"主词条","word":"質疑","kana":"しつぎ","pos":"[名·自動3]","accent":"②①","meaning":"质疑，质问","example":"質疑してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“质疑，质问”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n質疑してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“质疑，质问”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1351","seq":1351,"level":"N1","type":"主词条","word":"失脚","kana":"しっきゃく","pos":"[名·自動3]","accent":"⓪","meaning":"失足，下台","example":"失脚した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“失足，下台”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n失脚した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“失足，下台”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1352","seq":1352,"level":"N1","type":"主词条","word":"実況","kana":"じっきょう","pos":"[名]","accent":"⓪","meaning":"实况","example":"実況を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“实况”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n実況を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“实况”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1353","seq":1353,"level":"N1","type":"主词条","word":"シック","kana":"しっく (chic)","pos":"[ナ形]","accent":"①","meaning":"雅致","example":"一見シックな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“雅致”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見シックな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“雅致”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1354","seq":1354,"level":"N1","type":"主词条","word":"躾","kana":"しつけ","pos":"[名]","accent":"⓪","meaning":"（对孩子的）教育，教养","example":"躾として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“教育，教养”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n躾として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“教育，教养”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1355","seq":1355,"level":"N1","type":"主词条","word":"実権","kana":"じっけん","pos":"[名]","accent":"⓪","meaning":"实权","example":"名目上の代表は別にいるが、組織の実権は長年現場を支えてきた副社長が握っている。","exampleZh":"名义上的代表另有其人，但组织的实权掌握在长期支撑现场的副社长手中。","note":"例：\n名目上の代表は別にいるが、組織の実権は長年現場を支えてきた副社長が握っている。\n译：名义上的代表另有其人，但组织的实权掌握在长期支撑现场的副社长手中。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1356","seq":1356,"level":"N1","type":"主词条","word":"失効","kana":"しっこう","pos":"[名·自動3]","accent":"⓪","meaning":"失效，失去效力","example":"失効した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“失效，失去效力”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n失効した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“失效，失去效力”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1357","seq":1357,"level":"N1","type":"主词条","word":"執行","kana":"しっこう","pos":"[名·他動3]","accent":"⓪","meaning":"执行","example":"裁判所の決定に基づき、行政機関は新しい措置を慎重に執行した。","exampleZh":"根据法院的决定，行政机关慎重执行了新的措施。","note":"例：\n裁判所の決定に基づき、行政機関は新しい措置を慎重に執行した。\n译：根据法院的决定，行政机关慎重执行了新的措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1358","seq":1358,"level":"N1","type":"主词条","word":"実在","kana":"じつざい","pos":"[名·自動3]","accent":"⓪","meaning":"实际存在","example":"実在するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“实际存在”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n実在するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“实际存在”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1359","seq":1359,"level":"N1","type":"主词条","word":"実質","kana":"じっしつ","pos":"[名]","accent":"⓪","meaning":"实质","example":"実質をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“实质”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n実質をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“实质”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1360","seq":1360,"level":"N1","type":"主词条","word":"実情","kana":"じつじょう","pos":"[名]","accent":"⓪","meaning":"实际状况","example":"実情に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“实际状况”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n実情に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“实际状况”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1361","seq":1361,"level":"N1","type":"主词条","word":"質素","kana":"しっそ","pos":"[名·ナ形]","accent":"①","meaning":"俭朴，朴素","example":"彼女の暮らしは質素だが、必要なものを丁寧に選ぶ姿勢には豊かさが感じられる。","exampleZh":"她的生活虽然朴素，但从认真选择必要之物的态度中能感到一种富足。","note":"例：\n彼女の暮らしは質素だが、必要なものを丁寧に選ぶ姿勢には豊かさが感じられる。\n译：她的生活虽然朴素，但从认真选择必要之物的态度中能感到一种富足。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1362","seq":1362,"level":"N1","type":"主词条","word":"失調","kana":"しっちょう","pos":"[名]","accent":"⓪","meaning":"失调，失去平衡","example":"失調が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“失调，失去平衡”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n失調が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“失调，失去平衡”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1363","seq":1363,"level":"N1","type":"主词条","word":"嫉妬","kana":"しっと","pos":"[名·他動3]","accent":"①③","meaning":"嫉妒，羡慕","example":"同僚の昇進に嫉妬してしまう自分を認めたうえで、彼は次に必要な努力を考え始めた。","exampleZh":"他承认自己嫉妒同事升职后，开始思考下一步需要付出的努力。","note":"例：\n同僚の昇進に嫉妬してしまう自分を認めたうえで、彼は次に必要な努力を考え始めた。\n译：他承认自己嫉妒同事升职后，开始思考下一步需要付出的努力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1364","seq":1364,"level":"N1","type":"主词条","word":"失念","kana":"しつねん","pos":"[名·他動3]","accent":"⓪","meaning":"遗忘，忘却","example":"彼は失念を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“遗忘，忘却”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は失念を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“遗忘，忘却”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1365","seq":1365,"level":"N1","type":"主词条","word":"実費","kana":"じっぴ","pos":"[名]","accent":"⓪","meaning":"实际费用；原价","example":"市場環境が変わるなかで実費をどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“实际费用；原价”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかで実費をどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“实际费用；原价”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1366","seq":1366,"level":"N1","type":"主词条","word":"執拗","kana":"しつよう","pos":"[名·ナ形]","accent":"⓪","meaning":"固执；纠缠不休","example":"一度執拗だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“固执；纠缠不休”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度執拗だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“固执；纠缠不休”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1367","seq":1367,"level":"N1","type":"主词条","word":"しでかす","kana":"しでかす","pos":"[他動1]","accent":"③","meaning":"做出，干出（不好的事）","example":"無理にしでかすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“做出，干出”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理にしでかすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“做出，干出”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1368","seq":1368,"level":"N1","type":"主词条","word":"指摘","kana":"してき","pos":"[名·他動3]","accent":"⓪","meaning":"指出，指点，指正","example":"部下の誤りを指摘するときは、人格を責めるのではなく、次にどう直すかを一緒に考えるべきだ。","exampleZh":"指出部下错误时，不应责备人格，而应一起思考下次该如何修正。","note":"例：\n部下の誤りを指摘するときは、人格を責めるのではなく、次にどう直すかを一緒に考えるべきだ。\n译：指出部下错误时，不应责备人格，而应一起思考下次该如何修正。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1369","seq":1369,"level":"N1","type":"主词条","word":"視点","kana":"してん","pos":"[名]","accent":"⓪","meaning":"观点，角度","example":"視点が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“观点，角度”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n視点が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“观点，角度”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1370","seq":1370,"level":"N1","type":"主词条","word":"淑やか","kana":"しとやか","pos":"[ナ形]","accent":"②","meaning":"端庄，文静","example":"一度淑やかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“端庄，文静”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度淑やかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“端庄，文静”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1371","seq":1371,"level":"N1","type":"主词条","word":"しどろもどろ","kana":"しどろもどろ","pos":"[ナ形]","accent":"④⓪","meaning":"乱七八糟，语无伦次","example":"しどろもどろな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“乱七八糟，语无伦次”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\nしどろもどろな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“乱七八糟，语无伦次”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1372","seq":1372,"level":"N1","type":"主词条","word":"品薄","kana":"しなうす","pos":"[名·ナ形]","accent":"⓪","meaning":"缺货","example":"品薄な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“缺货”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n品薄な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“缺货”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1373","seq":1373,"level":"N1","type":"主词条","word":"萎びる","kana":"しなびる","pos":"[自動2]","accent":"⓪","meaning":"枯萎，蔫","example":"萎びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“枯萎，蔫”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n萎びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“枯萎，蔫”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1374","seq":1374,"level":"N1","type":"主词条","word":"しなやか","kana":"しなやか","pos":"[ナ形]","accent":"②","meaning":"柔韧；灵活","example":"一度しなやかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“柔韧；灵活”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度しなやかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“柔韧；灵活”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1375","seq":1375,"level":"N1","type":"主词条","word":"シナリオ","kana":"しなりお (scenario)","pos":"[名]","accent":"⓪","meaning":"脚本，剧本","example":"新しいシナリオを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的“脚本，剧本”，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しいシナリオを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的“脚本，剧本”，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1376","seq":1376,"level":"N1","type":"主词条","word":"凌ぐ","kana":"しのぐ","pos":"[他動1]","accent":"②","meaning":"超过；忍受；防御，躲避","example":"相手に何かを凌ぐなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“超过；忍受”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを凌ぐなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“超过；忍受”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1377","seq":1377,"level":"N1","type":"主词条","word":"忍ぶ","kana":"しのぶ","pos":"[自他動1]","accent":"②⓪","meaning":"躲藏，躲避；忍受","example":"忍ぶ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“躲藏，躲避；忍受”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n忍ぶ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“躲藏，躲避；忍受”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1378","seq":1378,"level":"N1","type":"主词条","word":"偲ぶ","kana":"しのぶ","pos":"[他動1]","accent":"②⓪","meaning":"追忆，缅怀","example":"偲ぶ前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“追忆，缅怀”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n偲ぶ前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“追忆，缅怀”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1379","seq":1379,"level":"N1","type":"主词条","word":"暫し","kana":"しばし","pos":"[副]","accent":"①","meaning":"片刻，暂时","example":"発表が終わると会場は暫し静まり返り、その後に大きな拍手が起こった。","exampleZh":"发表结束后，会场一时安静下来，随后响起了热烈掌声。","note":"例：\n発表が終わると会場は暫し静まり返り、その後に大きな拍手が起こった。\n译：发表结束后，会场一时安静下来，随后响起了热烈掌声。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1380","seq":1380,"level":"N1","type":"主词条","word":"市販","kana":"しはん","pos":"[名·他動3]","accent":"⓪","meaning":"在市场公开出售","example":"彼は市販を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“在市场公开出售”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は市販を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“在市场公开出售”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1381","seq":1381,"level":"N1","type":"主词条","word":"シビア","kana":"しびあ (severe)","pos":"[ナ形]","accent":"②①","meaning":"严厉，毫不留情","example":"シビアな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“严厉，毫不留情”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nシビアな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“严厉，毫不留情”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1382","seq":1382,"level":"N1","type":"主词条","word":"耳鼻科","kana":"じびか","pos":"[名]","accent":"⓪","meaning":"耳鼻科","example":"花粉の季節になると耳鼻科の待合室は混み合い、受付では予約時間の確認に追われる。","exampleZh":"一到花粉季节，耳鼻科候诊室就会拥挤，前台忙于确认预约时间。","note":"例：\n花粉の季節になると耳鼻科の待合室は混み合い、受付では予約時間の確認に追われる。\n译：一到花粉季节，耳鼻科候诊室就会拥挤，前台忙于确认预约时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1383","seq":1383,"level":"N1","type":"主词条","word":"持病","kana":"じびょう","pos":"[名]","accent":"⓪①","meaning":"老毛病","example":"過労が続くと持病に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。","exampleZh":"过劳持续后，“老毛病”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","note":"例：\n過労が続くと持病に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。\n译：过劳持续后，“老毛病”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1384","seq":1384,"level":"N1","type":"主词条","word":"渋い","kana":"しぶい","pos":"[イ形]","accent":"②","meaning":"味涩；素雅；不快；吝啬","example":"渋い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“味涩；素雅”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n渋い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“味涩；素雅”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1385","seq":1385,"level":"N1","type":"主词条","word":"私物","kana":"しぶつ","pos":"[名]","accent":"⓪","meaning":"私人物品","example":"経験豊かな私物の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“私人物品”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな私物の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“私人物品”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1386","seq":1386,"level":"N1","type":"主词条","word":"しぶとい","kana":"しぶとい","pos":"[イ形]","accent":"③","meaning":"顽固，倔强","example":"しぶとい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“顽固，倔强”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nしぶとい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“顽固，倔强”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1387","seq":1387,"level":"N1","type":"主词条","word":"始末","kana":"しまつ","pos":"[名·他動3]","accent":"①","meaning":"原委；结果；处理","example":"始末の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“原委；结果”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n始末の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“原委；结果”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1388","seq":1388,"level":"N1","type":"主词条","word":"地道","kana":"じみち","pos":"[名·ナ形]","accent":"⓪","meaning":"踏实","example":"地道な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“踏实”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n地道な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“踏实”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1389","seq":1389,"level":"N1","type":"主词条","word":"染みる","kana":"しみる","pos":"[自動2]","accent":"⓪","meaning":"渗；刺痛；沾染；铭刻，深感","example":"染みるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“渗；刺痛”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n染みるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“渗；刺痛”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1390","seq":1390,"level":"N1","type":"主词条","word":"〜じみる","kana":"〜じみる","pos":"[接尾]","accent":"","meaning":"染上，沾上；看来好像","example":"彼の話し方は少し説教じみているが、後輩の失敗を本気で心配していることも伝わってくる。","exampleZh":"他的说话方式有些像说教，但也能感受到他是真心担心后辈的失败。","note":"例：\n彼の話し方は少し説教じみているが、後輩の失敗を本気で心配していることも伝わってくる。\n译：他的说话方式有些像说教，但也能感受到他是真心担心后辈的失败。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1391","seq":1391,"level":"N1","type":"主词条","word":"締める","kana":"しめる","pos":"[他動2]","accent":"②","meaning":"系，系紧","example":"締める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“系，系紧”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n締める場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“系，系紧”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1392","seq":1392,"level":"N1","type":"主词条","word":"視野","kana":"しや","pos":"[名]","accent":"①","meaning":"视野；眼界，见识","example":"視野が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“视野；眼界，见识”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n視野が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“视野；眼界，见识”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1393","seq":1393,"level":"N1","type":"主词条","word":"ジャーナリスト","kana":"じゃーなりすと (journalist)","pos":"[名]","accent":"④","meaning":"新闻工作者，作者","example":"ジャーナリストを受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“新闻工作者，作者”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\nジャーナリストを受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“新闻工作者，作者”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1394","seq":1394,"level":"N1","type":"主词条","word":"ジャーナリズム","kana":"じゃーなりずむ (journalism)","pos":"[名]","accent":"④","meaning":"新闻业；新闻报道","example":"権力を監視するジャーナリズムの役割は、情報があふれる時代ほど重くなっている。","exampleZh":"新闻报道监督权力的作用，在信息泛滥的时代越发重要。","note":"例：\n権力を監視するジャーナリズムの役割は、情報があふれる時代ほど重くなっている。\n译：新闻报道监督权力的作用，在信息泛滥的时代越发重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1395","seq":1395,"level":"N1","type":"主词条","word":"シャープ","kana":"しゃーぷ (sharp)","pos":"[名·ナ形]","accent":"①","meaning":"尖锐，敏锐；聪明，清楚；＃字","example":"シャープな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“尖锐，敏锐；聪明，清楚”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nシャープな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“尖锐，敏锐；聪明，清楚”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1396","seq":1396,"level":"N1","type":"主词条","word":"謝意","kana":"しゃい","pos":"[名]","accent":"①","meaning":"谢意，歉意","example":"支援を受けた学生たちは、式の最後に謝意を述べ、地域の人々へ深く頭を下げた。","exampleZh":"接受支援的学生们在仪式最后表达谢意，并向地区的人们深深鞠躬。","note":"例：\n支援を受けた学生たちは、式の最後に謝意を述べ、地域の人々へ深く頭を下げた。\n译：接受支援的学生们在仪式最后表达谢意，并向地区的人们深深鞠躬。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1397","seq":1397,"level":"N1","type":"主词条","word":"釈明","kana":"しゃくめい","pos":"[名·他動3]","accent":"⓪","meaning":"申明，辩解","example":"疑惑について釈明するだけでなく、関係資料を公開する姿勢が求められた。","exampleZh":"不仅需要对疑惑进行说明，也被要求公开相关资料。","note":"例：\n疑惑について釈明するだけでなく、関係資料を公開する姿勢が求められた。\n译：不仅需要对疑惑进行说明，也被要求公开相关资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1398","seq":1398,"level":"N1","type":"主词条","word":"社交","kana":"しゃこう","pos":"[名]","accent":"⓪","meaning":"社交，交际","example":"社交が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“社交，交际”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n社交が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“社交，交际”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1399","seq":1399,"level":"N1","type":"主词条","word":"謝罪","kana":"しゃざい","pos":"[名·自他動3]","accent":"⓪","meaning":"谢罪，道歉","example":"謝罪する際には、言い訳を並べるより、相手が受けた損害と自分の責任を明確に認めることが大切だ。","exampleZh":"道歉时，与其罗列借口，不如明确承认对方受到的损害和自己的责任。","note":"例：\n謝罪する際には、言い訳を並べるより、相手が受けた損害と自分の責任を明確に認めることが大切だ。\n译：道歉时，与其罗列借口，不如明确承认对方受到的损害和自己的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1400","seq":1400,"level":"N1","type":"主词条","word":"ジャズ","kana":"じゃず (jazz)","pos":"[名]","accent":"①","meaning":"爵士音乐","example":"新しいジャズを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的“爵士音乐”，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しいジャズを取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的“爵士音乐”，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1401","seq":1401,"level":"N1","type":"主词条","word":"謝絶","kana":"しゃぜつ","pos":"[名·他動3]","accent":"⓪","meaning":"谢绝，拒绝","example":"相手を謝絶するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯对对方进行“谢绝，拒绝”只会加深对立，因此她决定先确认其主张背后的背景。","note":"例：\n相手を謝絶するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯对对方进行“谢绝，拒绝”只会加深对立，因此她决定先确认其主张背后的背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1402","seq":1402,"level":"N1","type":"主词条","word":"遮断","kana":"しゃだん","pos":"[名·他動3]","accent":"⓪","meaning":"切断，阻隔","example":"初めて遮断する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“切断，阻隔”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて遮断する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“切断，阻隔”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1403","seq":1403,"level":"N1","type":"主词条","word":"若干","kana":"じゃっかん","pos":"[名·副]","accent":"⓪","meaning":"若干，多少","example":"計画には若干の修正が必要だが、全体の方向性は参加者の間でおおむね共有されている。","exampleZh":"计划需要若干修正，但整体方向性已大致在参加者之间达成共识。","note":"例：\n計画には若干の修正が必要だが、全体の方向性は参加者の間でおおむね共有されている。\n译：计划需要若干修正，但整体方向性已大致在参加者之间达成共识。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1404","seq":1404,"level":"N1","type":"主词条","word":"三味線","kana":"しゃみせん","pos":"[名]","accent":"⓪","meaning":"三弦（拨弦乐器的一种）","example":"三味線が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“三弦”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n三味線が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“三弦”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1405","seq":1405,"level":"N1","type":"主词条","word":"砂利","kana":"じゃり","pos":"[名]","accent":"⓪","meaning":"小石头，沙砾","example":"砂利の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“小石头，沙砾”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n砂利の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“小石头，沙砾”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1406","seq":1406,"level":"N1","type":"主词条","word":"ジャンパー","kana":"じゃんぱー (jumper)","pos":"[名]","accent":"①","meaning":"宽松夹克衫","example":"ジャンパーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“宽松夹克衫”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nジャンパーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“宽松夹克衫”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1407","seq":1407,"level":"N1","type":"主词条","word":"ジャンプ","kana":"じゃんぷ (jump)","pos":"[名·自動3]","accent":"①","meaning":"跳跃；跳过","example":"予期せずジャンプした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“跳跃；跳过”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せずジャンプした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“跳跃；跳过”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1408","seq":1408,"level":"N1","type":"主词条","word":"ジャンボ","kana":"じゃんぼ (jumbo)","pos":"[名·ナ形]","accent":"①","meaning":"巨大，特大","example":"ジャンボな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“巨大，特大”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nジャンボな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“巨大，特大”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1409","seq":1409,"level":"N1","type":"主词条","word":"ジャンル","kana":"じゃんる","pos":"[名]","accent":"①","meaning":"类别，体裁","example":"ジャンルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“类别，体裁”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nジャンルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“类别，体裁”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1410","seq":1410,"level":"N1","type":"主词条","word":"重圧","kana":"じゅうあつ","pos":"[名]","accent":"⓪","meaning":"重压，沉重的压力","example":"重圧を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。","exampleZh":"如果放任“重压，沉重的压力”不管，不仅现场负担会增加，也可能失去使用者的信任。","note":"例：\n重圧を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。\n译：如果放任“重压，沉重的压力”不管，不仅现场负担会增加，也可能失去使用者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1411","seq":1411,"level":"N1","type":"主词条","word":"収益","kana":"しゅうえき","pos":"[名]","accent":"⓪①","meaning":"收益","example":"収益をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“收益”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n収益をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“收益”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1412","seq":1412,"level":"N1","type":"主词条","word":"周期","kana":"しゅうき","pos":"[名]","accent":"①","meaning":"周期","example":"周期を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“周期”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n周期を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“周期”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1413","seq":1413,"level":"N1","type":"主词条","word":"修業","kana":"しゅうぎょう","pos":"[名·自動3]","accent":"⓪","meaning":"学习学问、技艺等","example":"修業するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“学习学问，技艺等”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n修業するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“学习学问，技艺等”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1414","seq":1414,"level":"N1","type":"主词条","word":"従事","kana":"じゅうじ","pos":"[名·自動3]","accent":"①","meaning":"从事","example":"予期せず従事した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“从事”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず従事した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“从事”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1415","seq":1415,"level":"N1","type":"主词条","word":"終日","kana":"しゅうじつ","pos":"[名·副]","accent":"⓪","meaning":"终日，整天","example":"大雪の影響で空港は終日混雑し、職員は乗客への案内と振り替え手続きに追われた。","exampleZh":"受大雪影响，机场整天拥挤，工作人员忙于为乘客指引和办理改签手续。","note":"例：\n大雪の影響で空港は終日混雑し、職員は乗客への案内と振り替え手続きに追われた。\n译：受大雪影响，机场整天拥挤，工作人员忙于为乘客指引和办理改签手续。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1416","seq":1416,"level":"N1","type":"主词条","word":"終止符","kana":"しゅうしふ","pos":"[名]","accent":"③","meaning":"句号；结局","example":"長く続いた対立に終止符を打つには、勝ち負けを決めるよりも互いの不安を認めることが必要だった。","exampleZh":"要为长期对立画上句号，比起决定胜负，更需要承认彼此的不安。","note":"例：\n長く続いた対立に終止符を打つには、勝ち負けを決めるよりも互いの不安を認めることが必要だった。\n译：要为长期对立画上句号，比起决定胜负，更需要承认彼此的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1417","seq":1417,"level":"N1","type":"主词条","word":"収集","kana":"しゅうしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"收集；收藏","example":"収集した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“收集；收藏”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n収集した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“收集；收藏”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1418","seq":1418,"level":"N1","type":"主词条","word":"十字路","kana":"じゅうじろ","pos":"[名]","accent":"③","meaning":"十字路","example":"十字路をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“十字路”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n十字路をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“十字路”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1419","seq":1419,"level":"N1","type":"主词条","word":"重心","kana":"じゅうしん","pos":"[名]","accent":"⓪","meaning":"重心","example":"重心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“重心”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n重心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“重心”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1420","seq":1420,"level":"N1","type":"主词条","word":"終息","kana":"しゅうそく","pos":"[名·自動3]","accent":"⓪","meaning":"停息，结束","example":"終息してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“停息，结束”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n終息してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“停息，结束”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1421","seq":1421,"level":"N1","type":"主词条","word":"収束","kana":"しゅうそく","pos":"[名·他動3]","accent":"⓪","meaning":"平息，得到解决","example":"感染拡大が収束するまで、病院では面会制限を続けることになった。","exampleZh":"在感染扩散平息之前，医院决定继续限制探视。","note":"例：\n感染拡大が収束するまで、病院では面会制限を続けることになった。\n译：在感染扩散平息之前，医院决定继续限制探视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1422","seq":1422,"level":"N1","type":"主词条","word":"集大成","kana":"しゅうたいせい","pos":"[名·他動3]","accent":"③","meaning":"集大成","example":"集大成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“集大成”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n集大成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“集大成”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1423","seq":1423,"level":"N1","type":"主词条","word":"周知","kana":"しゅうち","pos":"[名]","accent":"⓪","meaning":"周知","example":"周知をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“周知”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n周知をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“周知”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1424","seq":1424,"level":"N1","type":"主词条","word":"執着","kana":"しゅうちゃく","pos":"[名·自動3]","accent":"⓪","meaning":"执著，留恋，贪恋","example":"予期せず執着した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“执著，留恋，贪恋”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず執着した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“执著，留恋，贪恋”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1425","seq":1425,"level":"N1","type":"主词条","word":"柔軟","kana":"じゅうなん","pos":"[名·ナ形]","accent":"⓪","meaning":"柔软；灵活","example":"柔軟な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“柔软；灵活”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n柔軟な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“柔软；灵活”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1426","seq":1426,"level":"N1","type":"主词条","word":"就任","kana":"しゅうにん","pos":"[名·自動3]","accent":"⓪","meaning":"就任","example":"就任した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“就任”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n就任した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“就任”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1427","seq":1427,"level":"N1","type":"主词条","word":"終発","kana":"しゅうはつ","pos":"[名]","accent":"⓪","meaning":"末班车","example":"新しい終発が整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。","exampleZh":"新的“末班车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","note":"例：\n新しい終発が整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。\n译：新的“末班车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1428","seq":1428,"level":"N1","type":"主词条","word":"修復","kana":"しゅうふく","pos":"[名·他動3]","accent":"⓪","meaning":"修复","example":"彼は修復を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“修复”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は修復を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“修复”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1429","seq":1429,"level":"N1","type":"主词条","word":"収容","kana":"しゅうよう","pos":"[名·他動3]","accent":"⓪","meaning":"收入，容纳；收容","example":"避難所は想定以上の住民を収容できるよう、寝具と非常食を追加で備蓄した。","exampleZh":"为了能够容纳超过预想的居民，避难所追加储备了寝具和应急食品。","note":"例：\n避難所は想定以上の住民を収容できるよう、寝具と非常食を追加で備蓄した。\n译：为了能够容纳超过预想的居民，避难所追加储备了寝具和应急食品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1430","seq":1430,"level":"N1","type":"主词条","word":"守衛","kana":"しゅえい","pos":"[名]","accent":"⓪","meaning":"警卫，门卫","example":"古い守衛を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“警卫，门卫”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い守衛を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“警卫，门卫”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1431","seq":1431,"level":"N1","type":"主词条","word":"主演","kana":"しゅえん","pos":"[名·自動3]","accent":"⓪","meaning":"主演","example":"主演した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“主演”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n主演した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“主演”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1432","seq":1432,"level":"N1","type":"主词条","word":"主観","kana":"しゅかん","pos":"[名]","accent":"⓪","meaning":"主观","example":"主観の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“主观”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n主観の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“主观”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1433","seq":1433,"level":"N1","type":"主词条","word":"修行","kana":"しゅぎょう","pos":"[名·自動3]","accent":"⓪","meaning":"修行；修养，钻研","example":"修行するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“修行；修养，钻研”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n修行するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“修行；修养，钻研”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1434","seq":1434,"level":"N1","type":"主词条","word":"祝賀","kana":"しゅくが","pos":"[名·他動3]","accent":"②⓪","meaning":"祝贺，庆祝","example":"初めて祝賀する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“祝贺，庆祝”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて祝賀する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“祝贺，庆祝”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1435","seq":1435,"level":"N1","type":"主词条","word":"熟知","kana":"じゅくち","pos":"[名·他動3]","accent":"①","meaning":"熟悉","example":"熟知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“熟悉”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n熟知の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“熟悉”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1436","seq":1436,"level":"N1","type":"主词条","word":"手芸","kana":"しゅげい","pos":"[名]","accent":"⓪①","meaning":"手工艺，手艺","example":"手芸を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“手工艺，手艺”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n手芸を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“手工艺，手艺”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1437","seq":1437,"level":"N1","type":"主词条","word":"趣旨","kana":"しゅし","pos":"[名]","accent":"①","meaning":"宗旨","example":"制度の趣旨を理解しないまま手続きだけを変えると、利用者にとってかえって分かりにくくなる。","exampleZh":"如果不理解制度宗旨，只改变手续，反而会让使用者更难理解。","note":"例：\n制度の趣旨を理解しないまま手続きだけを変えると、利用者にとってかえって分かりにくくなる。\n译：如果不理解制度宗旨，只改变手续，反而会让使用者更难理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1438","seq":1438,"level":"N1","type":"主词条","word":"種々","kana":"しゅじゅ","pos":"[名·副·ナ形]","accent":"①","meaning":"种种，各种各样","example":"彼は種々結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。","exampleZh":"他没有急于作出“种种，各种各样”的结论，而是在对照资料和现场声音后慎重决定方针。","note":"例：\n彼は種々結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。\n译：他没有急于作出“种种，各种各样”的结论，而是在对照资料和现场声音后慎重决定方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1439","seq":1439,"level":"N1","type":"主词条","word":"主将","kana":"しゅしょう","pos":"[名]","accent":"⓪","meaning":"主将","example":"主将を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“主将”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n主将を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“主将”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1440","seq":1440,"level":"N1","type":"主词条","word":"受診","kana":"じゅしん","pos":"[名·自動3]","accent":"⓪","meaning":"接受诊治","example":"受診してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“接受诊治”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n受診してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“接受诊治”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1441","seq":1441,"level":"N1","type":"主词条","word":"主体","kana":"しゅたい","pos":"[名]","accent":"⓪","meaning":"主体","example":"主体が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“主体”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n主体が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“主体”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1442","seq":1442,"level":"N1","type":"主词条","word":"受注","kana":"じゅちゅう","pos":"[名·他動3]","accent":"⓪","meaning":"接受订货","example":"初めて受注する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“接受订货”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて受注する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“接受订货”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1443","seq":1443,"level":"N1","type":"主词条","word":"出演","kana":"しゅつえん","pos":"[名·自動3]","accent":"⓪","meaning":"演出","example":"出演する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。","exampleZh":"在进行“演出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","note":"例：\n出演する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。\n译：在进行“演出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1444","seq":1444,"level":"N1","type":"主词条","word":"出荷","kana":"しゅっか","pos":"[名·他動3]","accent":"⓪","meaning":"发货；上市，出货","example":"彼は出荷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“发货；上市，出货”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は出荷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“发货；上市，出货”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1445","seq":1445,"level":"N1","type":"主词条","word":"出願","kana":"しゅつがん","pos":"[名·他動3]","accent":"⓪","meaning":"申请","example":"大学院に出願する前に、彼は研究計画書を何度も教授に見てもらった。","exampleZh":"在申请研究生院之前，他多次请教授看自己的研究计划书。","note":"例：\n大学院に出願する前に、彼は研究計画書を何度も教授に見てもらった。\n译：在申请研究生院之前，他多次请教授看自己的研究计划书。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1446","seq":1446,"level":"N1","type":"主词条","word":"出血","kana":"しゅっけつ","pos":"[名·自動3]","accent":"⓪","meaning":"出血；亏本","example":"出血した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“出血；亏本”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n出血した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“出血；亏本”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1447","seq":1447,"level":"N1","type":"主词条","word":"出産","kana":"しゅっさん","pos":"[名·自他動3]","accent":"⓪","meaning":"生育","example":"出産する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“生育”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n出産する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“生育”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1448","seq":1448,"level":"N1","type":"主词条","word":"出社","kana":"しゅっしゃ","pos":"[名·自動3]","accent":"⓪","meaning":"上班","example":"出社するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“上班”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n出社するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“上班”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1449","seq":1449,"level":"N1","type":"主词条","word":"出題","kana":"しゅつだい","pos":"[名·自他動3]","accent":"⓪","meaning":"出题","example":"出題した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“出题”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n出題した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“出题”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1450","seq":1450,"level":"N1","type":"主词条","word":"出店","kana":"しゅってん","pos":"[名·自動3]","accent":"⓪","meaning":"开店","example":"駅前に出店する計画は魅力的だったが、家賃と人手の確保が大きな課題になった。","exampleZh":"在车站前开店的计划很有吸引力，但房租和确保人手成了重大课题。","note":"例：\n駅前に出店する計画は魅力的だったが、家賃と人手の確保が大きな課題になった。\n译：在车站前开店的计划很有吸引力，但房租和确保人手成了重大课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1451","seq":1451,"level":"N1","type":"主词条","word":"出動","kana":"しゅつどう","pos":"[名·自動3]","accent":"⓪","meaning":"出动","example":"出動した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“出动”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n出動した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“出动”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1452","seq":1452,"level":"N1","type":"主词条","word":"出費","kana":"しゅっぴ","pos":"[名·自動3]","accent":"⓪","meaning":"花费，开销","example":"出費する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“花费，开销”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n出費する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“花费，开销”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1453","seq":1453,"level":"N1","type":"主词条","word":"出品","kana":"しゅっぴん","pos":"[名·他動3]","accent":"⓪","meaning":"展出","example":"若手作家が作品を出品できるよう、美術館は審査料を低く設定した。","exampleZh":"为了让年轻作家也能展出作品，美术馆把审查费设得较低。","note":"例：\n若手作家が作品を出品できるよう、美術館は審査料を低く設定した。\n译：为了让年轻作家也能展出作品，美术馆把审查费设得较低。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1454","seq":1454,"level":"N1","type":"主词条","word":"主導","kana":"しゅどう","pos":"[名·他動3]","accent":"⓪","meaning":"主导","example":"主導する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“主导”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n主導する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“主导”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1455","seq":1455,"level":"N1","type":"主词条","word":"主として","kana":"しゅとして","pos":"[副]","accent":"①②","meaning":"主要","example":"この支援制度は主として高齢者を対象にしているが、条件を満たせば若い世帯も利用できる。","exampleZh":"这项支援制度主要面向老年人，但只要满足条件，年轻家庭也可以使用。","note":"例：\nこの支援制度は主として高齢者を対象にしているが、条件を満たせば若い世帯も利用できる。\n译：这项支援制度主要面向老年人，但只要满足条件，年轻家庭也可以使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1456","seq":1456,"level":"N1","type":"主词条","word":"首脳","kana":"しゅのう","pos":"[名]","accent":"⓪","meaning":"首脑","example":"その首脳は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“首脑”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその首脳は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“首脑”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1457","seq":1457,"level":"N1","type":"主词条","word":"守備","kana":"しゅび","pos":"[名·他動3]","accent":"①","meaning":"防备，守卫","example":"守備した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“防备，守卫”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n守備した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“防备，守卫”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1458","seq":1458,"level":"N1","type":"主词条","word":"手法","kana":"しゅほう","pos":"[名]","accent":"⓪","meaning":"手法，方法","example":"手法を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。","exampleZh":"若突然导入“手法，方法”会招致混乱，因此负责人试图具体说明目的和影响范围。","note":"例：\n手法を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。\n译：若突然导入“手法，方法”会招致混乱，因此负责人试图具体说明目的和影响范围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1459","seq":1459,"level":"N1","type":"主词条","word":"樹木","kana":"じゅもく","pos":"[名]","accent":"①","meaning":"树木","example":"樹木の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“树木”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n樹木の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“树木”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1460","seq":1460,"level":"N1","type":"主词条","word":"授与","kana":"じゅよ","pos":"[名·他動3]","accent":"①","meaning":"授予","example":"彼は授与を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“授予”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は授与を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“授予”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1461","seq":1461,"level":"N1","type":"主词条","word":"樹立","kana":"じゅりつ","pos":"[名·他動3]","accent":"⓪","meaning":"树立","example":"新記録を樹立した選手は、勝因を個人の才能ではなくチーム全体の支援だと語った。","exampleZh":"创下新纪录的选手表示，获胜原因不是个人才能，而是整个团队的支持。","note":"例：\n新記録を樹立した選手は、勝因を個人の才能ではなくチーム全体の支援だと語った。\n译：创下新纪录的选手表示，获胜原因不是个人才能，而是整个团队的支持。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1462","seq":1462,"level":"N1","type":"主词条","word":"準じる","kana":"じゅんじる","pos":"[自動2]","accent":"⓪③","meaning":"按照，以……为基准","example":"準じる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“按照，以为基准”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n準じる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“按照，以为基准”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1463","seq":1463,"level":"N1","type":"主词条","word":"私用","kana":"しよう","pos":"[名·他動3]","accent":"⓪","meaning":"私事；私自使用","example":"私用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“私事；私自使用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n私用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“私事；私自使用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1464","seq":1464,"level":"N1","type":"主词条","word":"〜症","kana":"〜しょう","pos":"[接尾]","accent":"","meaning":"病状，病症","example":"花粉症の季節は外出がつらいため、彼女は早めに薬を用意し、窓を開ける時間も短くしている。","exampleZh":"花粉症季节外出很痛苦，所以她提前准备药物，也缩短开窗时间。","note":"例：\n花粉症の季節は外出がつらいため、彼女は早めに薬を用意し、窓を開ける時間も短くしている。\n译：花粉症季节外出很痛苦，所以她提前准备药物，也缩短开窗时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1465","seq":1465,"level":"N1","type":"主词条","word":"情","kana":"じょう","pos":"[名]","accent":"①","meaning":"感情・情感","example":"情が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“感情，情感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n情が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“感情，情感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1466","seq":1466,"level":"N1","type":"主词条","word":"上位","kana":"じょうい","pos":"[名]","accent":"①","meaning":"上位","example":"上位をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“上位”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n上位をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“上位”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1467","seq":1467,"level":"N1","type":"主词条","word":"上演","kana":"じょうえん","pos":"[名·他動3]","accent":"⓪","meaning":"上演","example":"古典劇を現代風に上演することで、若い観客にも登場人物の葛藤が身近に感じられるようになった。","exampleZh":"通过以现代风格上演古典剧，年轻观众也更能切身感受到登场人物的矛盾。","note":"例：\n古典劇を現代風に上演することで、若い観客にも登場人物の葛藤が身近に感じられるようになった。\n译：通过以现代风格上演古典剧，年轻观众也更能切身感受到登场人物的矛盾。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1468","seq":1468,"level":"N1","type":"主词条","word":"消火","kana":"しょうか","pos":"[名·自動3]","accent":"⓪","meaning":"消防，灭火","example":"消火するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“消防，灭火”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n消火するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“消防，灭火”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1469","seq":1469,"level":"N1","type":"主词条","word":"浄化","kana":"じょうか","pos":"[名·他動3]","accent":"①⓪","meaning":"净化","example":"河川を浄化する取り組みとして、住民と企業が協力して清掃活動を続けている。","exampleZh":"作为净化河流的举措，居民和企业合作持续开展清扫活动。","note":"例：\n河川を浄化する取り組みとして、住民と企業が協力して清掃活動を続けている。\n译：作为净化河流的举措，居民和企业合作持续开展清扫活动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1470","seq":1470,"level":"N1","type":"主词条","word":"照会","kana":"しょうかい","pos":"[名·他動3]","accent":"⓪","meaning":"询问，查询","example":"照会する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“询问，查询”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n照会する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“询问，查询”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1471","seq":1471,"level":"N1","type":"主词条","word":"生涯","kana":"しょうがい","pos":"[名·副]","accent":"①","meaning":"一生，生涯","example":"彼は生涯を通じて地域医療に尽くし、退職後も若い医師の相談に乗り続けた。","exampleZh":"他一生致力于地区医疗，退休后仍不断接受年轻医生的咨询。","note":"例：\n彼は生涯を通じて地域医療に尽くし、退職後も若い医師の相談に乗り続けた。\n译：他一生致力于地区医疗，退休后仍不断接受年轻医生的咨询。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1472","seq":1472,"level":"N1","type":"主词条","word":"城下町","kana":"じょうかまち","pos":"[名]","accent":"③","meaning":"城邑","example":"観光客が増えた城下町では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“城邑”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた城下町では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“城邑”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1473","seq":1473,"level":"N1","type":"主词条","word":"上機嫌","kana":"じょうきげん","pos":"[名·ナ形]","accent":"③","meaning":"情绪很好","example":"周囲から上機嫌だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“情绪很好”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から上機嫌だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“情绪很好”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1474","seq":1474,"level":"N1","type":"主词条","word":"昇給","kana":"しょうきゅう","pos":"[名·自動3]","accent":"⓪","meaning":"加薪","example":"昇給が決まった彼は喜ぶだけでなく、期待される役割が大きくなることも意識した。","exampleZh":"确定加薪后，他不只是高兴，也意识到被期待承担的角色会变得更大。","note":"例：\n昇給が決まった彼は喜ぶだけでなく、期待される役割が大きくなることも意識した。\n译：确定加薪后，他不只是高兴，也意识到被期待承担的角色会变得更大。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1475","seq":1475,"level":"N1","type":"主词条","word":"消去","kana":"しょうきょ","pos":"[名·自他動3]","accent":"①","meaning":"消去，消除","example":"消去の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“消去，消除”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n消去の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“消去，消除”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1476","seq":1476,"level":"N1","type":"主词条","word":"上空","kana":"じょうくう","pos":"[名]","accent":"⓪","meaning":"上空，高空","example":"上空を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“上空，高空”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n上空を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“上空，高空”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1477","seq":1477,"level":"N1","type":"主词条","word":"衝撃","kana":"しょうげき","pos":"[名]","accent":"⓪","meaning":"冲击，冲撞；震惊","example":"衝撃が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“冲击，冲撞；震惊”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n衝撃が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“冲击，冲撞；震惊”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1478","seq":1478,"level":"N1","type":"主词条","word":"証言","kana":"しょうげん","pos":"[名·他動3]","accent":"⓪③","meaning":"证言，作证","example":"証言する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“证言，作证”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n証言する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“证言，作证”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1479","seq":1479,"level":"N1","type":"主词条","word":"照合","kana":"しょうごう","pos":"[名·他動3]","accent":"⓪","meaning":"对照核查","example":"照合する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“对照核查”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n照合する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“对照核查”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1480","seq":1480,"level":"N1","type":"主词条","word":"症候群","kana":"しょうこうぐん","pos":"[名]","accent":"③","meaning":"症候群，综合征","example":"症候群を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“症候群，综合征”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n症候群を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“症候群，综合征”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1481","seq":1481,"level":"N1","type":"主词条","word":"詳細","kana":"しょうさい","pos":"[名·ナ形]","accent":"⓪","meaning":"详细，详情","example":"一度詳細だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“详细，详情”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度詳細だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“详细，详情”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1482","seq":1482,"level":"N1","type":"主词条","word":"勝算","kana":"しょうさん","pos":"[名]","accent":"⓪","meaning":"胜算","example":"十分な勝算がないまま事業を広げれば、資金だけでなく社員の士気まで失いかねない。","exampleZh":"如果在胜算不足的情况下扩大业务，可能不仅失去资金，也会失去员工士气。","note":"例：\n十分な勝算がないまま事業を広げれば、資金だけでなく社員の士気まで失いかねない。\n译：如果在胜算不足的情况下扩大业务，可能不仅失去资金，也会失去员工士气。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1483","seq":1483,"level":"N1","type":"主词条","word":"成就","kana":"じょうじゅ","pos":"[名·自他動3]","accent":"①","meaning":"成就，实现","example":"長年の目標を成就するには、努力だけでなく、支えてくれた人への感謝を忘れないことも大切だ。","exampleZh":"要实现长年目标，除了努力，也不能忘记感谢一直支持自己的人。","note":"例：\n長年の目標を成就するには、努力だけでなく、支えてくれた人への感謝を忘れないことも大切だ。\n译：要实现长年目标，除了努力，也不能忘记感谢一直支持自己的人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1484","seq":1484,"level":"N1","type":"主词条","word":"上場","kana":"じょうじょう","pos":"[名·他動3]","accent":"⓪","meaning":"上市","example":"彼は上場を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“上市”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は上場を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“上市”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1485","seq":1485,"level":"N1","type":"主词条","word":"昇進","kana":"しょうしん","pos":"[名·自動3]","accent":"⓪","meaning":"晋升","example":"昇進してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“晋升”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n昇進してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“晋升”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1486","seq":1486,"level":"N1","type":"主词条","word":"称する","kana":"しょうする","pos":"[自他動3]","accent":"③","meaning":"称，名叫……；假称；称赞","example":"彼は自分を専門家と称するが、発言の根拠を尋ねられると曖昧な答えしか返せなかった。","exampleZh":"他自称专家，但一被问到发言依据，就只能给出含糊回答。","note":"例：\n彼は自分を専門家と称するが、発言の根拠を尋ねられると曖昧な答えしか返せなかった。\n译：他自称专家，但一被问到发言依据，就只能给出含糊回答。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1487","seq":1487,"level":"N1","type":"主词条","word":"情勢","kana":"じょうせい","pos":"[名]","accent":"⓪","meaning":"形势","example":"情勢を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“形势”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n情勢を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“形势”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1488","seq":1488,"level":"N1","type":"主词条","word":"消息","kana":"しょうそく","pos":"[名]","accent":"⓪","meaning":"音信；动静，情况","example":"消息の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“音信；动静，情况”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n消息の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“音信；动静，情况”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1489","seq":1489,"level":"N1","type":"主词条","word":"正体","kana":"しょうたい","pos":"[名]","accent":"①","meaning":"真面目；意识，神志","example":"正体が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“真面目；意识，神志”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n正体が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“真面目；意识，神志”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1490","seq":1490,"level":"N1","type":"主词条","word":"承諾","kana":"しょうだく","pos":"[名·他動3]","accent":"⓪","meaning":"应允，同意","example":"初めて承諾する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“应允，同意”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて承諾する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“应允，同意”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1491","seq":1491,"level":"N1","type":"主词条","word":"情緒","kana":"じょうちょ","pos":"[名]","accent":"①","meaning":"情趣，风趣","example":"突然の情緒で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“情趣，风趣”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の情緒で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“情趣，风趣”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1492","seq":1492,"level":"N1","type":"主词条","word":"譲歩","kana":"じょうほ","pos":"[名·自動3]","accent":"①","meaning":"让步","example":"一方が譲歩するだけでは長続きしないため、双方がどこまでなら受け入れられるかを具体的に示した。","exampleZh":"如果只是一方让步，就无法长久持续，因此双方具体说明了各自能够接受到什么程度。","note":"例：\n一方が譲歩するだけでは長続きしないため、双方がどこまでなら受け入れられるかを具体的に示した。\n译：如果只是一方让步，就无法长久持续，因此双方具体说明了各自能够接受到什么程度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1493","seq":1493,"level":"N1","type":"主词条","word":"常務","kana":"じょうむ","pos":"[名]","accent":"①","meaning":"常务董事","example":"常務を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“常务董事”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n常務を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“常务董事”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1494","seq":1494,"level":"N1","type":"主词条","word":"賞与","kana":"しょうよ","pos":"[名]","accent":"①","meaning":"奖金，红利","example":"賞与が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“奖金，红利”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n賞与が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“奖金，红利”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1495","seq":1495,"level":"N1","type":"主词条","word":"常用","kana":"じょうよう","pos":"[名·他動3]","accent":"⓪","meaning":"常用","example":"常用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“常用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n常用する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“常用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1496","seq":1496,"level":"N1","type":"主词条","word":"上陸","kana":"じょうりく","pos":"[名·自動3]","accent":"⓪","meaning":"登陆","example":"上陸した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“登陆”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n上陸した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“登陆”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1497","seq":1497,"level":"N1","type":"主词条","word":"ショーウィンドー","kana":"しょーうぃんどー (show window)","pos":"[名]","accent":"⑤","meaning":"橱窗，陈列窗","example":"ショーウィンドーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“橱窗，陈列窗”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nショーウィンドーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“橱窗，陈列窗”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1498","seq":1498,"level":"N1","type":"主词条","word":"除外","kana":"じょがい","pos":"[名·他動3]","accent":"⓪","meaning":"除外","example":"初めて除外する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“除外”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて除外する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“除外”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1499","seq":1499,"level":"N1","type":"主词条","word":"初期","kana":"しょき","pos":"[名]","accent":"①","meaning":"初期","example":"初期を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“初期”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n初期を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“初期”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1500","seq":1500,"level":"N1","type":"主词条","word":"触発","kana":"しょくはつ","pos":"[名·自他動3]","accent":"⓪","meaning":"（受到）刺激（而去做某事）","example":"先輩の研究発表に触発され、彼女は自分のテーマをもう一度根本から見直すことにした。","exampleZh":"受到前辈研究发表的触动，她决定从根本上重新审视自己的课题。","note":"例：\n先輩の研究発表に触発され、彼女は自分のテーマをもう一度根本から見直すことにした。\n译：受到前辈研究发表的触动，她决定从根本上重新审视自己的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1501","seq":1501,"level":"N1","type":"主词条","word":"助言","kana":"じょげん","pos":"[名·自動3]","accent":"⓪","meaning":"提建议","example":"助言した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“提建议”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n助言した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“提建议”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1502","seq":1502,"level":"N1","type":"主词条","word":"徐行","kana":"じょこう","pos":"[名·自動3]","accent":"⓪","meaning":"慢行","example":"徐行する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“慢行”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n徐行する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“慢行”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1503","seq":1503,"level":"N1","type":"主词条","word":"所在","kana":"しょざい","pos":"[名]","accent":"⓪","meaning":"所在","example":"所在をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“所在”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n所在をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“所在”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1504","seq":1504,"level":"N1","type":"主词条","word":"所持","kana":"しょじ","pos":"[名·他動3]","accent":"①","meaning":"携带","example":"チームは所持する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“携带”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは所持する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“携带”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1505","seq":1505,"level":"N1","type":"主词条","word":"処する","kana":"しょする","pos":"[他動3]","accent":"②","meaning":"置身，处于；处罚","example":"相手に何かを処するなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“置身，处于；处罚”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを処するなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“置身，处于；处罚”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1506","seq":1506,"level":"N1","type":"主词条","word":"所詮","kana":"しょせん","pos":"[副]","accent":"⓪","meaning":"最终，归根结底","example":"見た目だけを整えても、利用者の不便を解決できなければ所詮一時的な対策にすぎない。","exampleZh":"即使只把外观整理好，若不能解决使用者的不便，归根结底也只是临时对策。","note":"例：\n見た目だけを整えても、利用者の不便を解決できなければ所詮一時的な対策にすぎない。\n译：即使只把外观整理好，若不能解决使用者的不便，归根结底也只是临时对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1507","seq":1507,"level":"N1","type":"主词条","word":"所属","kana":"しょぞく","pos":"[名·自動3]","accent":"⓪","meaning":"属于","example":"所属する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“属于”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n所属する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“属于”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1508","seq":1508,"level":"N1","type":"主词条","word":"処置","kana":"しょち","pos":"[名·他動3]","accent":"①","meaning":"处理；措施；（医疗）处理","example":"彼は処置を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“处理；措施”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は処置を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“处理；措施”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1509","seq":1509,"level":"N1","type":"主词条","word":"ショック","kana":"しょっく (shock)","pos":"[名]","accent":"①","meaning":"冲击；打击，震撼；休克","example":"ショックが表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。","exampleZh":"当“冲击；打击，震撼”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","note":"例：\nショックが表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。\n译：当“冲击；打击，震撼”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1510","seq":1510,"level":"N1","type":"主词条","word":"しょっちゅう","kana":"しょっちゅう","pos":"[副]","accent":"①","meaning":"经常","example":"彼はしょっちゅう資料の置き場所を変えるので、周囲は探す時間を減らすため共有ルールを決めた。","exampleZh":"他经常改变资料放置地点，所以周围制定了共享规则，以减少寻找时间。","note":"例：\n彼はしょっちゅう資料の置き場所を変えるので、周囲は探す時間を減らすため共有ルールを決めた。\n译：他经常改变资料放置地点，所以周围制定了共享规则，以减少寻找时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1511","seq":1511,"level":"N1","type":"主词条","word":"所定","kana":"しょてい","pos":"[名]","accent":"⓪","meaning":"所规定的","example":"応募書類は所定の用紙に記入し、締め切りまでに窓口へ提出しなければならない。","exampleZh":"应聘文件必须填写在规定表格上，并在截止日期前提交到窗口。","note":"例：\n応募書類は所定の用紙に記入し、締め切りまでに窓口へ提出しなければならない。\n译：应聘文件必须填写在规定表格上，并在截止日期前提交到窗口。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1512","seq":1512,"level":"N1","type":"主词条","word":"処罰","kana":"しょばつ","pos":"[名·他動3]","accent":"①⓪","meaning":"处罚","example":"処罰を急ぐだけでは再発防止にならないため、委員会は背景にある仕組みも調べた。","exampleZh":"只急于处罚并不能防止再发，所以委员会也调查了背后的机制。","note":"例：\n処罰を急ぐだけでは再発防止にならないため、委員会は背景にある仕組みも調べた。\n译：只急于处罚并不能防止再发，所以委员会也调查了背后的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1513","seq":1513,"level":"N1","type":"主词条","word":"書評","kana":"しょひょう","pos":"[名]","accent":"⓪","meaning":"书评","example":"彼女は書評をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“书评”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は書評をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“书评”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1514","seq":1514,"level":"N1","type":"主词条","word":"処方箋","kana":"しょほうせん","pos":"[名]","accent":"⓪","meaning":"处方，药方","example":"過労が続くと処方箋に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。","exampleZh":"过劳持续后，“处方，药方”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","note":"例：\n過労が続くと処方箋に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。\n译：过劳持续后，“处方，药方”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1515","seq":1515,"level":"N1","type":"主词条","word":"庶民","kana":"しょみん","pos":"[名]","accent":"①","meaning":"百姓，普通人","example":"庶民の暮らしに近い視点を持たなければ、どれほど立派な政策も支持されにくい。","exampleZh":"如果没有贴近普通人生活的视角，再出色的政策也很难获得支持。","note":"例：\n庶民の暮らしに近い視点を持たなければ、どれほど立派な政策も支持されにくい。\n译：如果没有贴近普通人生活的视角，再出色的政策也很难获得支持。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1516","seq":1516,"level":"N1","type":"主词条","word":"庶務","kana":"しょむ","pos":"[名]","accent":"①","meaning":"一般事务","example":"庶務の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“一般事务”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n庶務の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“一般事务”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1517","seq":1517,"level":"N1","type":"主词条","word":"しょんぼり","kana":"しょんぼり","pos":"[副·自動3]","accent":"③","meaning":"无精打采，垂头丧气","example":"試合に負けた子どもはしょんぼりしていたが、監督は最後まで諦めなかった点を褒めた。","exampleZh":"输掉比赛的孩子垂头丧气，但教练表扬了他坚持到最后的态度。","note":"例：\n試合に負けた子どもはしょんぼりしていたが、監督は最後まで諦めなかった点を褒めた。\n译：输掉比赛的孩子垂头丧气，但教练表扬了他坚持到最后的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1518","seq":1518,"level":"N1","type":"主词条","word":"退く","kana":"しりぞく","pos":"[自動1]","accent":"③","meaning":"向后退；辞职，让步","example":"退くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“向后退；辞职，让步”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n退くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“向后退；辞职，让步”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1519","seq":1519,"level":"N1","type":"主词条","word":"自立","kana":"じりつ","pos":"[名·自動3]","accent":"⓪","meaning":"独立","example":"予期せず自立した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“独立”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず自立した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“独立”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1520","seq":1520,"level":"N1","type":"主词条","word":"記す","kana":"しるす","pos":"[他動1]","accent":"⓪②","meaning":"写下，记下","example":"記すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“写下，记下”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n記すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“写下，记下”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1521","seq":1521,"level":"N1","type":"主词条","word":"指令","kana":"しれい","pos":"[名·他動3]","accent":"⓪","meaning":"指令","example":"指令した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“指令”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n指令した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“指令”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1522","seq":1522,"level":"N1","type":"主词条","word":"じれったい","kana":"じれったい","pos":"[イ形]","accent":"④","meaning":"令人着急","example":"じれったい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“令人着急”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\nじれったい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“令人着急”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1523","seq":1523,"level":"N1","type":"主词条","word":"試練","kana":"しれん","pos":"[名]","accent":"①⓪","meaning":"锻炼，考验","example":"試練を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“锻炼，考验”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n試練を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“锻炼，考验”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1524","seq":1524,"level":"N1","type":"主词条","word":"ジレンマ","kana":"じれんま (dilemma)","pos":"[名]","accent":"②","meaning":"困境，进退维谷","example":"ジレンマをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“困境，进退维谷”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nジレンマをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“困境，进退维谷”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1525","seq":1525,"level":"N1","type":"主词条","word":"じろじろ","kana":"じろじろ","pos":"[副]","accent":"①","meaning":"无所顾忌地盯着看","example":"相手をじろじろ見るのは失礼なので、面接では視線を自然に外しながら話を聞くよう心がけた。","exampleZh":"直盯着对方看很失礼，所以面试时他注意自然移开视线来听对方说话。","note":"例：\n相手をじろじろ見るのは失礼なので、面接では視線を自然に外しながら話を聞くよう心がけた。\n译：直盯着对方看很失礼，所以面试时他注意自然移开视线来听对方说话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1526","seq":1526,"level":"N1","type":"主词条","word":"仕分け","kana":"しわけ","pos":"[名·他動3]","accent":"⓪","meaning":"区分，分类","example":"仕分けする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“区分，分类”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n仕分けする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“区分，分类”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1527","seq":1527,"level":"N1","type":"主词条","word":"真","kana":"しん","pos":"[名]","accent":"①","meaning":"真的，真正","example":"真をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“真的，真正”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n真をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“真的，真正”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1528","seq":1528,"level":"N1","type":"主词条","word":"〜心","kana":"〜しん","pos":"[接尾]","accent":"","meaning":"……心理，思想","example":"向上心を持って仕事に取り組む人は、失敗を責められても次の改善点を冷静に探そうとする。","exampleZh":"具有上进心投入工作的人，即使因失败被责备，也会冷静寻找下一步改善点。","note":"例：\n向上心を持って仕事に取り組む人は、失敗を責められても次の改善点を冷静に探そうとする。\n译：具有上进心投入工作的人，即使因失败被责备，也会冷静寻找下一步改善点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1529","seq":1529,"level":"N1","type":"主词条","word":"〜陣","kana":"〜じん","pos":"[接尾]","accent":"","meaning":"……阵容，队伍","example":"今年の講師陣は実務経験が豊富で、教科書だけでは分からない現場の判断まで教えてくれる。","exampleZh":"今年的讲师阵容实践经验丰富，能讲授教科书中学不到的现场判断。","note":"例：\n今年の講師陣は実務経験が豊富で、教科書だけでは分からない現場の判断まで教えてくれる。\n译：今年的讲师阵容实践经验丰富，能讲授教科书中学不到的现场判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1530","seq":1530,"level":"N1","type":"主词条","word":"人格","kana":"じんかく","pos":"[名]","accent":"⓪","meaning":"人格","example":"人格として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“人格”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n人格として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“人格”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1531","seq":1531,"level":"N1","type":"主词条","word":"新型","kana":"しんがた","pos":"[名]","accent":"⓪","meaning":"新型","example":"新型を変えるだけで情報の見え方は大きく変わるため、彼は利用者が迷わない並べ方を考えた。","exampleZh":"只改变新型样式，信息呈现方式也会大大改变，所以他思考了让使用者不迷惑的排列方式。","note":"例：\n新型を変えるだけで情報の見え方は大きく変わるため、彼は利用者が迷わない並べ方を考えた。\n译：只改变新型样式，信息呈现方式也会大大改变，所以他思考了让使用者不迷惑的排列方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1532","seq":1532,"level":"N1","type":"主词条","word":"審議","kana":"しんぎ","pos":"[名·他動3]","accent":"①","meaning":"审议","example":"彼は審議を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“审议”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は審議を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“审议”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1533","seq":1533,"level":"N1","type":"主词条","word":"親近感","kana":"しんきんかん","pos":"[名]","accent":"③","meaning":"亲近感，感到亲近","example":"親近感を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。","exampleZh":"如果重视“亲近感，感到亲近”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","note":"例：\n親近感を大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。\n译：如果重视“亲近感，感到亲近”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1534","seq":1534,"level":"N1","type":"主词条","word":"神経質","kana":"しんけいしつ","pos":"[名·ナ形]","accent":"③","meaning":"神经质；过分在意","example":"神経質な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“神经质；过分在意”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n神経質な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“神经质；过分在意”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1535","seq":1535,"level":"N1","type":"主词条","word":"新興","kana":"しんこう","pos":"[名]","accent":"⓪","meaning":"新兴","example":"新興企業が次々と参入したことで、古い業界にも価格やサービスを見直す動きが広がった。","exampleZh":"新兴企业接连进入市场，老行业中也出现了重新审视价格和服务的动向。","note":"例：\n新興企業が次々と参入したことで、古い業界にも価格やサービスを見直す動きが広がった。\n译：新兴企业接连进入市场，老行业中也出现了重新审视价格和服务的动向。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1536","seq":1536,"level":"N1","type":"主词条","word":"振興","kana":"しんこう","pos":"[名·他動3]","accent":"⓪","meaning":"振兴","example":"チームは振興する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“振兴”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは振興する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“振兴”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1537","seq":1537,"level":"N1","type":"主词条","word":"申告","kana":"しんこく","pos":"[名·他動3]","accent":"⓪","meaning":"申报","example":"申告した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“申报”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n申告した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“申报”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1538","seq":1538,"level":"N1","type":"主词条","word":"人材","kana":"じんざい","pos":"[名]","accent":"⓪","meaning":"人才","example":"優秀な人材を採用するだけでなく、長く働き続けられる環境を整えることが重要だ。","exampleZh":"不仅要录用优秀人才，创造能让他们长期工作的环境也很重要。","note":"例：\n優秀な人材を採用するだけでなく、長く働き続けられる環境を整えることが重要だ。\n译：不仅要录用优秀人才，创造能让他们长期工作的环境也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1539","seq":1539,"level":"N1","type":"主词条","word":"真実","kana":"しんじつ","pos":"[名·ナ形]","accent":"①","meaning":"真实情况","example":"周囲から真実だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“真实情况”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から真実だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“真实情况”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1540","seq":1540,"level":"N1","type":"主词条","word":"信者","kana":"しんじゃ","pos":"[名]","accent":"①","meaning":"信徒","example":"その信者は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“信徒”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその信者は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“信徒”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1541","seq":1541,"level":"N1","type":"主词条","word":"真珠","kana":"しんじゅ","pos":"[名]","accent":"⓪","meaning":"珍珠","example":"真珠を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“珍珠”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n真珠を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“珍珠”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1542","seq":1542,"level":"N1","type":"主词条","word":"心中","kana":"しんじゅう","pos":"[名·自動3]","accent":"⓪","meaning":"（情侣・家人）一同自杀","example":"心中する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“一同自杀”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n心中する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“一同自杀”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1543","seq":1543,"level":"N1","type":"主词条","word":"進出","kana":"しんしゅつ","pos":"[名·自動3]","accent":"⓪","meaning":"进入；进军","example":"進出するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“进入；进军”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n進出するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“进入；进军”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1544","seq":1544,"level":"N1","type":"主词条","word":"心情","kana":"しんじょう","pos":"[名]","accent":"⓪","meaning":"心情","example":"胸に残る心情を無理に隠すより、彼女は事実と感情を分けて整理しようとした。","exampleZh":"与其勉强隐藏心中残留的“心情”，她更想把事实和情绪分开整理。","note":"例：\n胸に残る心情を無理に隠すより、彼女は事実と感情を分けて整理しようとした。\n译：与其勉强隐藏心中残留的“心情”，她更想把事实和情绪分开整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1545","seq":1545,"level":"N1","type":"主词条","word":"親善","kana":"しんぜん","pos":"[名]","accent":"⓪","meaning":"亲善，友好","example":"親善に甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。","exampleZh":"如果仗着“亲善，友好”而怠于确认，小小误解有时会变成很大的不满。","note":"例：\n親善に甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。\n译：如果仗着“亲善，友好”而怠于确认，小小误解有时会变成很大的不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1546","seq":1546,"level":"N1","type":"主词条","word":"真相","kana":"しんそう","pos":"[名]","accent":"⓪","meaning":"真相","example":"真相が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“真相”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n真相が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“真相”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1547","seq":1547,"level":"N1","type":"主词条","word":"迅速","kana":"じんそく","pos":"[名·ナ形]","accent":"⓪","meaning":"迅速","example":"災害時には迅速な判断が求められるが、確認を省けばかえって混乱を広げることもある。","exampleZh":"灾害时需要迅速判断，但如果省略确认，反而可能扩大混乱。","note":"例：\n災害時には迅速な判断が求められるが、確認を省けばかえって混乱を広げることもある。\n译：灾害时需要迅速判断，但如果省略确认，反而可能扩大混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1548","seq":1548,"level":"N1","type":"主词条","word":"新築","kana":"しんちく","pos":"[名·他動3]","accent":"⓪","meaning":"新建","example":"彼は新築を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“新建”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は新築を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“新建”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1549","seq":1549,"level":"N1","type":"主词条","word":"進捗","kana":"しんちょく","pos":"[名·自動3]","accent":"⓪","meaning":"进展","example":"予期せず進捗した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“进展”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず進捗した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“进展”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1550","seq":1550,"level":"N1","type":"主词条","word":"進呈","kana":"しんてい","pos":"[名·他動3]","accent":"⓪","meaning":"奉送，赠送","example":"進呈する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“奉送，赠送”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n進呈する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“奉送，赠送”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1551","seq":1551,"level":"N1","type":"主词条","word":"進展","kana":"しんてん","pos":"[名·自動3]","accent":"⓪","meaning":"进展，发展","example":"進展した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“进展，发展”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n進展した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“进展，发展”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1552","seq":1552,"level":"N1","type":"主词条","word":"しんどい","kana":"しんどい","pos":"[イ形]","accent":"③","meaning":"累，费力","example":"しんどいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“累，费力”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\nしんどいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“累，费力”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1553","seq":1553,"level":"N1","type":"主词条","word":"しんなり","kana":"しんなり","pos":"[副·自動3]","accent":"③","meaning":"变软，蔫","example":"野菜がしんなりするまで炒めると、甘みが増して、少ない調味料でも味がまとまりやすくなる。","exampleZh":"把蔬菜炒到变软后，甜味会增加，即使用较少调味料也更容易让味道协调。","note":"例：\n野菜がしんなりするまで炒めると、甘みが増して、少ない調味料でも味がまとまりやすくなる。\n译：把蔬菜炒到变软后，甜味会增加，即使用较少调味料也更容易让味道协调。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1554","seq":1554,"level":"N1","type":"主词条","word":"信任","kana":"しんにん","pos":"[名·他動3]","accent":"⓪","meaning":"信任","example":"部下から信任を得るには、上司が成果だけでなく失敗したときの責任も引き受ける姿勢を示す必要がある。","exampleZh":"要获得部下信任，上司不仅要看成果，也要表现出愿意承担失败责任的态度。","note":"例：\n部下から信任を得るには、上司が成果だけでなく失敗したときの責任も引き受ける姿勢を示す必要がある。\n译：要获得部下信任，上司不仅要看成果，也要表现出愿意承担失败责任的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1555","seq":1555,"level":"N1","type":"主词条","word":"信念","kana":"しんねん","pos":"[名]","accent":"①","meaning":"信念","example":"周囲に反対されても自分の信念を曲げなかった彼は、同時に他人の意見を聞く姿勢も忘れなかった。","exampleZh":"即使受到周围反对也不改变自己信念的他，同时也没有忘记倾听他人意见的态度。","note":"例：\n周囲に反対されても自分の信念を曲げなかった彼は、同時に他人の意見を聞く姿勢も忘れなかった。\n译：即使受到周围反对也不改变自己信念的他，同时也没有忘记倾听他人意见的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1556","seq":1556,"level":"N1","type":"主词条","word":"神秘","kana":"しんぴ","pos":"[名·ナ形]","accent":"①","meaning":"神秘","example":"一度神秘だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“神秘”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度神秘だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“神秘”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1557","seq":1557,"level":"N1","type":"主词条","word":"辛抱","kana":"しんぼう","pos":"[名·自動3]","accent":"①","meaning":"忍耐","example":"結果が出るまでの辛抱が必要だと分かっていても、彼は不安を抱える部下に進捗をこまめに伝えた。","exampleZh":"即使知道需要忍耐到结果出现，他仍频繁向抱有不安的部下传达进展。","note":"例：\n結果が出るまでの辛抱が必要だと分かっていても、彼は不安を抱える部下に進捗をこまめに伝えた。\n译：即使知道需要忍耐到结果出现，他仍频繁向抱有不安的部下传达进展。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1558","seq":1558,"level":"N1","type":"主词条","word":"辛抱強い","kana":"しんぼうづよい","pos":"[イ形]","accent":"⑥","meaning":"有耐心，能忍耐","example":"辛抱強い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“有耐心，能忍耐”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n辛抱強い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“有耐心，能忍耐”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1559","seq":1559,"level":"N1","type":"主词条","word":"シンポジウム","kana":"しんぽじうむ (symposium)","pos":"[名]","accent":"④","meaning":"研讨会","example":"シンポジウムをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“研讨会”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nシンポジウムをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“研讨会”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1560","seq":1560,"level":"N1","type":"主词条","word":"親密","kana":"しんみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"亲密，密切","example":"親密な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“亲密，密切”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n親密な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“亲密，密切”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1561","seq":1561,"level":"N1","type":"主词条","word":"真理","kana":"しんり","pos":"[名]","accent":"①","meaning":"真理","example":"真理を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“真理”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\n真理を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“真理”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1562","seq":1562,"level":"N1","type":"主词条","word":"尽力","kana":"じんりょく","pos":"[名·自動3]","accent":"①⓪","meaning":"尽力","example":"多くの人の尽力があったからこそ、予算の少ない地域イベントも安全に開催することができた。","exampleZh":"正因为有许多人尽力，预算有限的地区活动才得以安全举办。","note":"例：\n多くの人の尽力があったからこそ、予算の少ない地域イベントも安全に開催することができた。\n译：正因为有许多人尽力，预算有限的地区活动才得以安全举办。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1563","seq":1563,"level":"N1","type":"主词条","word":"粋","kana":"すい","pos":"[名·ナ形]","accent":"①","meaning":"精华","example":"粋な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“精华”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n粋な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“精华”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1564","seq":1564,"level":"N1","type":"主词条","word":"推移","kana":"すいい","pos":"[名·自動3]","accent":"①","meaning":"推移，演变","example":"予期せず推移した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“推移，演变”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず推移した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“推移，演变”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1565","seq":1565,"level":"N1","type":"主词条","word":"水源","kana":"すいげん","pos":"[名]","accent":"⓪","meaning":"水源","example":"研究者は水源の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“水源”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は水源の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“水源”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1566","seq":1566,"level":"N1","type":"主词条","word":"推進","kana":"すいしん","pos":"[名·他動3]","accent":"⓪","meaning":"推进","example":"推進する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“推进”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n推進する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“推进”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1567","seq":1567,"level":"N1","type":"主词条","word":"吹奏","kana":"すいそう","pos":"[名·他動3]","accent":"⓪","meaning":"吹奏","example":"吹奏する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“吹奏”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n吹奏する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“吹奏”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1568","seq":1568,"level":"N1","type":"主词条","word":"推理","kana":"すいり","pos":"[名·他動3]","accent":"①","meaning":"推理","example":"チームは推理する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“推理”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは推理する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“推理”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1569","seq":1569,"level":"N1","type":"主词条","word":"スイング","kana":"すいんぐ (swing)","pos":"[名·他動3]","accent":"②","meaning":"舞动，挥动","example":"スイングの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“舞动，挥动”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\nスイングの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“舞动，挥动”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1570","seq":1570,"level":"N1","type":"主词条","word":"数値","kana":"すうち","pos":"[名]","accent":"①","meaning":"数值","example":"数値が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“数值”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n数値が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“数值”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1571","seq":1571,"level":"N1","type":"主词条","word":"崇拝","kana":"すうはい","pos":"[名·他動3]","accent":"⓪","meaning":"崇拜，崇敬","example":"崇拝の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“崇拜，崇敬”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n崇拝の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“崇拜，崇敬”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1572","seq":1572,"level":"N1","type":"主词条","word":"据え付ける","kana":"すえつける","pos":"[他動2]","accent":"④","meaning":"安装","example":"無理に据え付けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に据え付けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1573","seq":1573,"level":"N1","type":"主词条","word":"据える","kana":"すえる","pos":"[他動2]","accent":"⓪","meaning":"安放，安置；使人就某职位","example":"無理に据えると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“安放，安置；使人就某职位”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に据えると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“安放，安置；使人就某职位”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1574","seq":1574,"level":"N1","type":"主词条","word":"清々しい","kana":"すがすがしい","pos":"[イ形]","accent":"⑤","meaning":"清新舒畅","example":"清々しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“清新舒畅”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n清々しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“清新舒畅”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1575","seq":1575,"level":"N1","type":"主词条","word":"スキャンダル","kana":"すきゃんだる (scandal)","pos":"[名]","accent":"②","meaning":"丑闻","example":"スキャンダルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“丑闻”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nスキャンダルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“丑闻”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1576","seq":1576,"level":"N1","type":"主词条","word":"スケール","kana":"すけーる (scale)","pos":"[名]","accent":"②","meaning":"规模","example":"スケールが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“规模”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nスケールが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“规模”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1577","seq":1577,"level":"N1","type":"主词条","word":"頗る","kana":"すこぶる","pos":"[副]","accent":"③②","meaning":"颇，非常","example":"新しい機械の調子は頗るよく、以前より短い時間で同じ量の作業を終えられるようになった。","exampleZh":"新机器状态非常好，能够用比以前更短的时间完成同样数量的作业。","note":"例：\n新しい機械の調子は頗るよく、以前より短い時間で同じ量の作業を終えられるようになった。\n译：新机器状态非常好，能够用比以前更短的时间完成同样数量的作业。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1578","seq":1578,"level":"N1","type":"主词条","word":"健やか","kana":"すこやか","pos":"[ナ形]","accent":"②","meaning":"健壮，健康","example":"健やかな状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“健壮，健康”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n健やかな状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“健壮，健康”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1579","seq":1579,"level":"N1","type":"主词条","word":"凄まじい","kana":"すさまじい","pos":"[イ形]","accent":"④","meaning":"骇人，惊人；厉害，猛烈","example":"凄まじい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“骇人，惊人；厉害，猛烈”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n凄まじい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“骇人，惊人；厉害，猛烈”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1580","seq":1580,"level":"N1","type":"主词条","word":"すし詰め","kana":"すしづめ","pos":"[名]","accent":"⓪","meaning":"拥挤不堪","example":"すし詰めが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“拥挤不堪”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nすし詰めが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“拥挤不堪”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1581","seq":1581,"level":"N1","type":"主词条","word":"濯ぐ","kana":"すすぐ","pos":"[他動1]","accent":"⓪","meaning":"洗涤，漂洗；洗清，昭雪","example":"無理に濯ぐと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“洗涤，漂洗；洗清，昭雪”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に濯ぐと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“洗涤，漂洗；洗清，昭雪”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1582","seq":1582,"level":"N1","type":"主词条","word":"スタジアム","kana":"すたじあむ (stadium)","pos":"[名]","accent":"②","meaning":"体育场","example":"そのスタジアムを実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“体育场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nそのスタジアムを実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“体育场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1583","seq":1583,"level":"N1","type":"主词条","word":"スタジオ","kana":"すたじお (studio)","pos":"[名]","accent":"⓪","meaning":"演播室，工作室","example":"スタジオが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“演播室，工作室”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nスタジオが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“演播室，工作室”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1584","seq":1584,"level":"N1","type":"主词条","word":"廃れる","kana":"すたれる","pos":"[自動2]","accent":"⓪③","meaning":"衰弱，衰微；过时","example":"廃れる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“衰弱，衰微；过时”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n廃れる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“衰弱，衰微；过时”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1585","seq":1585,"level":"N1","type":"主词条","word":"ステータス","kana":"すてーたす (status)","pos":"[名]","accent":"②","meaning":"社会地位，身份","example":"新しいステータスを運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。","exampleZh":"运用新的“社会地位，身份”时，需要反映当事人的声音，避免负担只偏向一部分人。","note":"例：\n新しいステータスを運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。\n译：运用新的“社会地位，身份”时，需要反映当事人的声音，避免负担只偏向一部分人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1586","seq":1586,"level":"N1","type":"主词条","word":"ステンレス","kana":"すてんれす (stainless)","pos":"[名]","accent":"②","meaning":"不锈钢","example":"ステンレスを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“不锈钢”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nステンレスを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“不锈钢”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1587","seq":1587,"level":"N1","type":"主词条","word":"ストック","kana":"すとっく (stock)","pos":"[名·他動3]","accent":"②","meaning":"储存，库存；股票","example":"災害に備えて食料をストックしておくなら、賞味期限を定期的に確認する必要がある。","exampleZh":"如果要储备食物以备灾害，就需要定期确认保质期。","note":"例：\n災害に備えて食料をストックしておくなら、賞味期限を定期的に確認する必要がある。\n译：如果要储备食物以备灾害，就需要定期确认保质期。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1588","seq":1588,"level":"N1","type":"主词条","word":"ストライキ","kana":"すとらいき (strike)","pos":"[名·自動3]","accent":"③","meaning":"罢工","example":"ストライキした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“罢工”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\nストライキした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“罢工”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1589","seq":1589,"level":"N1","type":"主词条","word":"ストロー","kana":"すとろー (straw)","pos":"[名]","accent":"②","meaning":"吸管；麦杆","example":"ストローをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“吸管；麦杆”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nストローをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“吸管；麦杆”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1590","seq":1590,"level":"N1","type":"主词条","word":"ストロボ","kana":"すとろぼ","pos":"[名]","accent":"⓪","meaning":"闪光灯","example":"研究者はストロボの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“闪光灯”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者はストロボの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“闪光灯”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1591","seq":1591,"level":"N1","type":"主词条","word":"スパイ","kana":"すぱい (spy)","pos":"[名]","accent":"②①","meaning":"间谍","example":"スパイを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“间谍”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\nスパイを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“间谍”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1592","seq":1592,"level":"N1","type":"主词条","word":"すばしこい","kana":"すばしこい","pos":"[イ形]","accent":"④","meaning":"（动作）快速，敏捷","example":"すばしこい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“快速，敏捷”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nすばしこい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“快速，敏捷”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1593","seq":1593,"level":"N1","type":"主词条","word":"ずばり","kana":"ずばり","pos":"[副]","accent":"②","meaning":"一刀切下；击中要害，一针见血","example":"上司は問題の核心をずばり指摘したが、責める口調ではなく改善策を一緒に考えようとした。","exampleZh":"上司一针见血地指出了问题核心，但语气并非责备，而是想一起思考改善方案。","note":"例：\n上司は問題の核心をずばり指摘したが、責める口調ではなく改善策を一緒に考えようとした。\n译：上司一针见血地指出了问题核心，但语气并非责备，而是想一起思考改善方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1594","seq":1594,"level":"N1","type":"主词条","word":"ずぶぬれ","kana":"ずぶぬれ","pos":"[名]","accent":"⓪","meaning":"全身湿透","example":"ずぶぬれの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“全身湿透”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nずぶぬれの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“全身湿透”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1595","seq":1595,"level":"N1","type":"主词条","word":"スプリング","kana":"すぷりんぐ (spring)","pos":"[名]","accent":"⓪","meaning":"弹簧，弹力；春天","example":"スプリングの日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。","exampleZh":"在“弹簧，弹力；春天”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","note":"例：\nスプリングの日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。\n译：在“弹簧，弹力；春天”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1596","seq":1596,"level":"N1","type":"主词条","word":"スペース","kana":"すぺーす (space)","pos":"[名]","accent":"②","meaning":"空间；空白","example":"スペースをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“空间；空白”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nスペースをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“空间；空白”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1597","seq":1597,"level":"N1","type":"主词条","word":"スペシャル","kana":"すぺしゃる (special)","pos":"[名]","accent":"②","meaning":"特别，特制","example":"期間限定のスペシャルメニューは高価だったが、地元の食材を生かした工夫が随所に見られた。","exampleZh":"期间限定的特制菜单虽然价格高，但随处可见活用当地食材的用心。","note":"例：\n期間限定のスペシャルメニューは高価だったが、地元の食材を生かした工夫が随所に見られた。\n译：期间限定的特制菜单虽然价格高，但随处可见活用当地食材的用心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1598","seq":1598,"level":"N1","type":"主词条","word":"スポンサー","kana":"すぽんさー (sponsor)","pos":"[名]","accent":"②⓪","meaning":"赞助者","example":"スポンサーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“赞助者”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nスポンサーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“赞助者”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1599","seq":1599,"level":"N1","type":"主词条","word":"スポンジ","kana":"すぽんじ (sponge)","pos":"[名]","accent":"⓪","meaning":"海绵，海绵状的东西","example":"研究者はスポンジの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“海绵，海绵状的东西”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者はスポンジの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“海绵，海绵状的东西”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1600","seq":1600,"level":"N1","type":"主词条","word":"澄ます","kana":"すます","pos":"[自他動1]","accent":"②","meaning":"装模作样；集中（注意力）","example":"彼は何も知らない顔をして澄ましていたが、机の上のメモから事情を知っていたことは明らかだった。","exampleZh":"他装作什么都不知道的样子故作镇定，但桌上的便条清楚表明他知道内情。","note":"例：\n彼は何も知らない顔をして澄ましていたが、机の上のメモから事情を知っていたことは明らかだった。\n译：他装作什么都不知道的样子故作镇定，但桌上的便条清楚表明他知道内情。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1601","seq":1601,"level":"N1","type":"主词条","word":"速やか","kana":"すみやか","pos":"[ナ形]","accent":"②","meaning":"迅速，及时","example":"速やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“迅速，及时”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n速やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“迅速，及时”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1602","seq":1602,"level":"N1","type":"主词条","word":"ずらっと","kana":"ずらっと","pos":"[副]","accent":"②","meaning":"一长排","example":"会場の入口には新製品がずらっと並び、来場者は特徴を比べながら担当者に質問していた。","exampleZh":"会场入口新产品排成一长排，来场者一边比较特点一边向负责人提问。","note":"例：\n会場の入口には新製品がずらっと並び、来場者は特徴を比べながら担当者に質問していた。\n译：会场入口新产品排成一长排，来场者一边比较特点一边向负责人提问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1603","seq":1603,"level":"N1","type":"主词条","word":"擦り切れる","kana":"すりきれる","pos":"[自動2]","accent":"④⓪","meaning":"磨损，磨破","example":"擦り切れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“磨损，磨破”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n擦り切れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“磨损，磨破”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1604","seq":1604,"level":"N1","type":"主词条","word":"擂り潰す","kana":"すりつぶす","pos":"[他動1]","accent":"④⓪","meaning":"研碎，捣烂，磨碎，碾碎；挥霍一空","example":"無理に擂り潰すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“研碎，捣烂，磨碎，碾碎”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に擂り潰すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“研碎，捣烂，磨碎，碾碎”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1605","seq":1605,"level":"N1","type":"主词条","word":"擦る","kana":"する","pos":"[他動1]","accent":"①","meaning":"用力摩擦；研磨","example":"無理に擦ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“用力摩擦；研磨”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に擦ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“用力摩擦；研磨”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1606","seq":1606,"level":"N1","type":"主词条","word":"ずるずる","kana":"ずるずる","pos":"[副·自動3]","accent":"①","meaning":"拖拉；拖延不决","example":"対応をずるずる先延ばしにした結果、小さな不満が大きな苦情へと膨らんだ。","exampleZh":"由于一直拖延应对，小小的不满最终扩大成了严重投诉。","note":"例：\n対応をずるずる先延ばしにした結果、小さな不満が大きな苦情へと膨らんだ。\n译：由于一直拖延应对，小小的不满最终扩大成了严重投诉。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1607","seq":1607,"level":"N1","type":"主词条","word":"ずれ","kana":"ずれ","pos":"[名]","accent":"②","meaning":"分歧，偏差","example":"ずれを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“分歧，偏差”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nずれを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“分歧，偏差”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1608","seq":1608,"level":"N1","type":"主词条","word":"擦れ合う","kana":"すれあう","pos":"[自動1]","accent":"③⓪","meaning":"互相摩擦；闹矛盾","example":"擦れ合うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“互相摩擦；闹矛盾”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n擦れ合うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“互相摩擦；闹矛盾”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1609","seq":1609,"level":"N1","type":"主词条","word":"擦れ擦れ","kana":"すれすれ","pos":"[名·ナ形]","accent":"⓪","meaning":"贴近，差点撞上；勉强赶上","example":"一度擦れ擦れだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“贴近，差点撞上；勉强赶上”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度擦れ擦れだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“贴近，差点撞上；勉强赶上”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1610","seq":1610,"level":"N1","type":"主词条","word":"擦れる","kana":"すれる","pos":"[自動2]","accent":"②","meaning":"磨损；（久经世故）变得圆滑","example":"勢いが少しずつ擦れる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“磨损；变得圆滑”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ擦れる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“磨损；变得圆滑”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1611","seq":1611,"level":"N1","type":"主词条","word":"スローガン","kana":"すろーがん (slogan)","pos":"[名]","accent":"②","meaning":"标语，口号","example":"スローガンが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“标语，口号”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nスローガンが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“标语，口号”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1612","seq":1612,"level":"N1","type":"主词条","word":"すんなり","kana":"すんなり","pos":"[副·自動3]","accent":"③","meaning":"纤细柔美；顺利，容易","example":"交渉はすんなりまとまったように見えたが、担当者は事前に相手の不安を一つずつ解消していた。","exampleZh":"谈判看似顺利达成，但负责人事先逐一消除了对方的不安。","note":"例：\n交渉はすんなりまとまったように見えたが、担当者は事前に相手の不安を一つずつ解消していた。\n译：谈判看似顺利达成，但负责人事先逐一消除了对方的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1613","seq":1613,"level":"N1","type":"主词条","word":"誠意","kana":"せいい","pos":"[名]","accent":"①","meaning":"诚意","example":"胸に残る誠意を無理に隠すより、彼女は事実と感情を分けて整理しようとした。","exampleZh":"与其勉强隐藏心中残留的“诚意”，她更想把事实和情绪分开整理。","note":"例：\n胸に残る誠意を無理に隠すより、彼女は事実と感情を分けて整理しようとした。\n译：与其勉强隐藏心中残留的“诚意”，她更想把事实和情绪分开整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1614","seq":1614,"level":"N1","type":"主词条","word":"晴雨","kana":"せいう","pos":"[名]","accent":"①","meaning":"晴雨，晴天和雨天","example":"突然の晴雨で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“晴雨，晴天和雨天”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の晴雨で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“晴雨，晴天和雨天”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1615","seq":1615,"level":"N1","type":"主词条","word":"成果","kana":"せいか","pos":"[名]","accent":"①","meaning":"成果","example":"成果をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“成果”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n成果をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“成果”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1616","seq":1616,"level":"N1","type":"主词条","word":"製菓","kana":"せいか","pos":"[名]","accent":"①","meaning":"制作糕点","example":"製菓を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“制作糕点”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n製菓を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“制作糕点”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1617","seq":1617,"level":"N1","type":"主词条","word":"正規","kana":"せいき","pos":"[名·ナ形]","accent":"①","meaning":"正规，正式规定","example":"正規な文章でも、読み手の背景を考えて具体例を添えれば、内容はずっと伝わりやすくなる。","exampleZh":"即便是正规的文章，如果考虑读者背景并附上具体例子，内容也会容易传达得多。","note":"例：\n正規な文章でも、読み手の背景を考えて具体例を添えれば、内容はずっと伝わりやすくなる。\n译：即便是正规的文章，如果考虑读者背景并附上具体例子，内容也会容易传达得多。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1618","seq":1618,"level":"N1","type":"主词条","word":"性急","kana":"せいきゅう","pos":"[名·ナ形]","accent":"⓪","meaning":"性急，急性子；急躁","example":"性急な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“性急，急性子；急躁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n性急な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“性急，急性子；急躁”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1619","seq":1619,"level":"N1","type":"主词条","word":"制御","kana":"せいぎょ","pos":"[名·他動3]","accent":"①","meaning":"控制；调节","example":"制御の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“控制；调节”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n制御の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“控制；调节”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1620","seq":1620,"level":"N1","type":"主词条","word":"精巧","kana":"せいこう","pos":"[名·ナ形]","accent":"⓪","meaning":"精巧","example":"精巧な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“精巧”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n精巧な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“精巧”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1621","seq":1621,"level":"N1","type":"主词条","word":"制裁","kana":"せいさい","pos":"[名·他動3]","accent":"⓪","meaning":"制裁","example":"国際社会は人権侵害を理由に、関係者への経済制裁を検討している。","exampleZh":"国际社会以侵犯人权为由，正在考虑对相关人员实施经济制裁。","note":"例：\n国際社会は人権侵害を理由に、関係者への経済制裁を検討している。\n译：国际社会以侵犯人权为由，正在考虑对相关人员实施经济制裁。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1622","seq":1622,"level":"N1","type":"主词条","word":"精細","kana":"せいさい","pos":"[名·ナ形]","accent":"⓪","meaning":"精细，周密","example":"精細な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“精细，周密”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n精細な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“精细，周密”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1623","seq":1623,"level":"N1","type":"主词条","word":"政策","kana":"せいさく","pos":"[名]","accent":"⓪","meaning":"政策","example":"政策を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。","exampleZh":"若突然导入“政策”会招致混乱，因此负责人试图具体说明目的和影响范围。","note":"例：\n政策を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。\n译：若突然导入“政策”会招致混乱，因此负责人试图具体说明目的和影响范围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1624","seq":1624,"level":"N1","type":"主词条","word":"精算","kana":"せいさん","pos":"[名·他動3]","accent":"⓪","meaning":"精算，细算；补票","example":"チームは精算する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“精算，细算；补票”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは精算する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“精算，细算；补票”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1625","seq":1625,"level":"N1","type":"主词条","word":"精算機","kana":"せいさんき","pos":"[名]","accent":"③","meaning":"补票机","example":"駅の精算機で不足分を支払おうとしたが、観光客は使い方が分からず駅員に助けを求めた。","exampleZh":"游客想在车站补票机上支付不足金额，却不懂使用方法，只好向站员求助。","note":"例：\n駅の精算機で不足分を支払おうとしたが、観光客は使い方が分からず駅員に助けを求めた。\n译：游客想在车站补票机上支付不足金额，却不懂使用方法，只好向站员求助。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1626","seq":1626,"level":"N1","type":"主词条","word":"静止","kana":"せいし","pos":"[名·自動3]","accent":"⓪","meaning":"静止","example":"静止した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“静止”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n静止した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“静止”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1627","seq":1627,"level":"N1","type":"主词条","word":"制止","kana":"せいし","pos":"[名·他動3]","accent":"⓪","meaning":"制止，阻止","example":"制止の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“制止，阻止”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n制止の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“制止，阻止”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1628","seq":1628,"level":"N1","type":"主词条","word":"清純","kana":"せいじゅん","pos":"[名·ナ形]","accent":"⓪","meaning":"清纯，纯洁","example":"彼女の清純な雰囲気は、派手な衣装ではなく自然な表情から生まれていた。","exampleZh":"她清纯的氛围并非来自华丽服装，而是来自自然的表情。","note":"例：\n彼女の清純な雰囲気は、派手な衣装ではなく自然な表情から生まれていた。\n译：她清纯的氛围并非来自华丽服装，而是来自自然的表情。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1629","seq":1629,"level":"N1","type":"主词条","word":"制する","kana":"せいする","pos":"[他動3]","accent":"③","meaning":"抑制；控制，夺取","example":"無理に制すると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“抑制；控制，夺取”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に制すると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“抑制；控制，夺取”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1630","seq":1630,"level":"N1","type":"主词条","word":"整然","kana":"せいぜん","pos":"[副·ナ形]","accent":"⓪","meaning":"井然，整齐","example":"机の上に整然と並んだ資料を見ると、彼女の準備の丁寧さがよく分かる。","exampleZh":"看到桌上整齐摆放的资料，就能清楚看出她准备得很细致。","note":"例：\n机の上に整然と並んだ資料を見ると、彼女の準備の丁寧さがよく分かる。\n译：看到桌上整齐摆放的资料，就能清楚看出她准备得很细致。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1631","seq":1631,"level":"N1","type":"主词条","word":"正装","kana":"せいそう","pos":"[名·自動3]","accent":"⓪","meaning":"正装","example":"正装した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“正装”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n正装した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“正装”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1632","seq":1632,"level":"N1","type":"主词条","word":"盛装","kana":"せいそう","pos":"[名·自動3]","accent":"⓪","meaning":"盛装","example":"盛装する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“盛装”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n盛装する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“盛装”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1633","seq":1633,"level":"N1","type":"主词条","word":"生態","kana":"せいたい","pos":"[名]","accent":"⓪","meaning":"生态；人类的生活现状","example":"その生態は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“生态；人类的生活现状”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその生態は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“生态；人类的生活现状”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1634","seq":1634,"level":"N1","type":"主词条","word":"盛大","kana":"せいだい","pos":"[名·ナ形]","accent":"⓪","meaning":"盛大，规模宏大","example":"周囲から盛大だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“盛大，规模宏大”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から盛大だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“盛大，规模宏大”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1635","seq":1635,"level":"N1","type":"主词条","word":"清聴","kana":"せいちょう","pos":"[名·他動3]","accent":"⓪","meaning":"垂听","example":"清聴の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“垂听”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n清聴の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“垂听”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1636","seq":1636,"level":"N1","type":"主词条","word":"制定","kana":"せいてい","pos":"[名·他動3]","accent":"⓪","meaning":"制定","example":"彼は制定を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“制定”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は制定を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“制定”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1637","seq":1637,"level":"N1","type":"主词条","word":"静的","kana":"せいてき","pos":"[ナ形]","accent":"⓪","meaning":"静态的，静止的；文静的","example":"静的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“静态的，静止的；文静的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n静的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“静态的，静止的；文静的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1638","seq":1638,"level":"N1","type":"主词条","word":"正当","kana":"せいとう","pos":"[名·ナ形]","accent":"⓪","meaning":"正当，合理","example":"正当な理由があるなら、感情的に訴えるより、事実と手順を整理して相手に示すべきだ。","exampleZh":"如果有正当理由，与其情绪化申诉，不如整理事实和步骤后向对方展示。","note":"例：\n正当な理由があるなら、感情的に訴えるより、事実と手順を整理して相手に示すべきだ。\n译：如果有正当理由，与其情绪化申诉，不如整理事实和步骤后向对方展示。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1639","seq":1639,"level":"N1","type":"主词条","word":"整頓","kana":"せいとん","pos":"[名·他動3]","accent":"⓪","meaning":"整理，整顿","example":"誤りを整頓する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。","exampleZh":"在“整理，整顿”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","note":"例：\n誤りを整頓する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。\n译：在“整理，整顿”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1640","seq":1640,"level":"N1","type":"主词条","word":"成否","kana":"せいひ","pos":"[名]","accent":"①","meaning":"成功与否","example":"成否の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“成功与否”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n成否の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“成功与否”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1641","seq":1641,"level":"N1","type":"主词条","word":"製法","kana":"せいほう","pos":"[名]","accent":"⓪","meaning":"制造方法","example":"昔ながらの製法を守る職人は、機械化できない微妙な火加減を経験で見極めている。","exampleZh":"守护传统制造方法的工匠，凭经验判断无法机械化的微妙火候。","note":"例：\n昔ながらの製法を守る職人は、機械化できない微妙な火加減を経験で見極めている。\n译：守护传统制造方法的工匠，凭经验判断无法机械化的微妙火候。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1642","seq":1642,"level":"N1","type":"主词条","word":"精密","kana":"せいみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"精密","example":"精密な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“精密”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n精密な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“精密”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1643","seq":1643,"level":"N1","type":"主词条","word":"税務署","kana":"ぜいむしょ","pos":"[名]","accent":"③④","meaning":"税务署","example":"税務署を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。","exampleZh":"若突然导入“税务署”会招致混乱，因此负责人试图具体说明目的和影响范围。","note":"例：\n税務署を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。\n译：若突然导入“税务署”会招致混乱，因此负责人试图具体说明目的和影响范围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1644","seq":1644,"level":"N1","type":"主词条","word":"声明","kana":"せいめい","pos":"[名·自他動3]","accent":"⓪","meaning":"声明","example":"彼は声明を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“声明”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は声明を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“声明”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1645","seq":1645,"level":"N1","type":"主词条","word":"成約","kana":"せいやく","pos":"[名·自動3]","accent":"⓪","meaning":"订立合同","example":"成約してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“订立合同”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n成約してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“订立合同”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1646","seq":1646,"level":"N1","type":"主词条","word":"制約","kana":"せいやく","pos":"[名·他動3]","accent":"⓪","meaning":"制约","example":"制約する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“制约”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n制約する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“制约”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1647","seq":1647,"level":"N1","type":"主词条","word":"精力","kana":"せいりょく","pos":"[名]","accent":"①","meaning":"精力","example":"精力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。","exampleZh":"感到“精力”不足后，他观察有经验者的做法，并将其纳入每日练习。","note":"例：\n精力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。\n译：感到“精力”不足后，他观察有经验者的做法，并将其纳入每日练习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1648","seq":1648,"level":"N1","type":"主词条","word":"勢力","kana":"せいりょく","pos":"[名]","accent":"①","meaning":"势力","example":"勢力を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。","exampleZh":"要磨炼“势力”，不能只依赖才能，还需要细致回顾失败场面的习惯。","note":"例：\n勢力を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。\n译：要磨炼“势力”，不能只依赖才能，还需要细致回顾失败场面的习惯。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1649","seq":1649,"level":"N1","type":"主词条","word":"整列","kana":"せいれつ","pos":"[名·自動3]","accent":"⓪","meaning":"整队，排队","example":"予期せず整列した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“整队，排队”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず整列した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“整队，排队”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1650","seq":1650,"level":"N1","type":"主词条","word":"セールス","kana":"せーるす (sales)","pos":"[名]","accent":"①","meaning":"推销，销售","example":"担当者はセールスを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“推销，销售”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者はセールスを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“推销，销售”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1651","seq":1651,"level":"N1","type":"主词条","word":"セールスマン","kana":"せーるすまん (salesman)","pos":"[名]","accent":"④","meaning":"推销员","example":"担当者はセールスマンを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“推销员”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者はセールスマンを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“推销员”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1652","seq":1652,"level":"N1","type":"主词条","word":"背負う","kana":"せおう","pos":"[他動1]","accent":"②","meaning":"背；担负","example":"背負う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“背；担负”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n背負う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“背；担负”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1653","seq":1653,"level":"N1","type":"主词条","word":"急かす","kana":"せかす","pos":"[他動1]","accent":"②","meaning":"催，催促","example":"相手の成長を急かすには、結果を急かすだけでなく、自分で考える余白を残す必要がある。","exampleZh":"要催促对方成长，不能只催结果，也需要留下让其自己思考的余地。","note":"例：\n相手の成長を急かすには、結果を急かすだけでなく、自分で考える余白を残す必要がある。\n译：要催促对方成长，不能只催结果，也需要留下让其自己思考的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1654","seq":1654,"level":"N1","type":"主词条","word":"急かせる","kana":"せかせる","pos":"[他動2]","accent":"③","meaning":"催，催促","example":"相手の成長を急かせるには、結果を急かすだけでなく、自分で考える余白を残す必要がある。","exampleZh":"要促使对方成长，不能只催结果，也需要留下让其自己思考的余地。","note":"例：\n相手の成長を急かせるには、結果を急かすだけでなく、自分で考える余白を残す必要がある。\n译：要促使对方成长，不能只催结果，也需要留下让其自己思考的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1655","seq":1655,"level":"N1","type":"主词条","word":"責務","kana":"せきむ","pos":"[名]","accent":"①","meaning":"责任与义务；职责","example":"責務の変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。","exampleZh":"“责任与义务；职责”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","note":"例：\n責務の変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。\n译：“责任与义务；职责”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1656","seq":1656,"level":"N1","type":"主词条","word":"セキュリティー","kana":"せきゅりてぃー (security)","pos":"[名]","accent":"②","meaning":"安全防卫，防御","example":"セキュリティーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“安全防卫，防御”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nセキュリティーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“安全防卫，防御”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1657","seq":1657,"level":"N1","type":"主词条","word":"セクション","kana":"せくしょん (section)","pos":"[名]","accent":"①","meaning":"部门；版面","example":"セクションの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“部门；版面”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\nセクションの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“部门；版面”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1658","seq":1658,"level":"N1","type":"主词条","word":"セクハラ","kana":"せくはら","pos":"[名]","accent":"⓪","meaning":"性骚扰","example":"セクハラの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“性骚扰”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nセクハラの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“性骚扰”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1659","seq":1659,"level":"N1","type":"主词条","word":"是正","kana":"ぜせい","pos":"[名·他動3]","accent":"⓪","meaning":"改正，修正","example":"誤りを是正する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。","exampleZh":"在“改正，修正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","note":"例：\n誤りを是正する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。\n译：在“改正，修正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1660","seq":1660,"level":"N1","type":"主词条","word":"世相","kana":"せそう","pos":"[名]","accent":"⓪②","meaning":"世态，社会情况","example":"新しい世相を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。","exampleZh":"运用新的“世态，社会情况”时，需要反映当事人的声音，避免负担只偏向一部分人。","note":"例：\n新しい世相を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。\n译：运用新的“世态，社会情况”时，需要反映当事人的声音，避免负担只偏向一部分人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1661","seq":1661,"level":"N1","type":"主词条","word":"世帯","kana":"せたい","pos":"[名]","accent":"①②","meaning":"家，户","example":"世帯を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“家，户”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n世帯を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“家，户”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1662","seq":1662,"level":"N1","type":"主词条","word":"切開","kana":"せっかい","pos":"[名·他動3]","accent":"⓪","meaning":"切开（患部）","example":"切開する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“切开”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n切開する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“切开”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1663","seq":1663,"level":"N1","type":"主词条","word":"説教","kana":"せっきょう","pos":"[名·自他動3]","accent":"③①","meaning":"说教","example":"説教する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“说教”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n説教する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“说教”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1664","seq":1664,"level":"N1","type":"主词条","word":"節句","kana":"せっく","pos":"[名]","accent":"⓪","meaning":"传统节日","example":"節句な態度を取り続ければ、正しい意見を述べていても周囲の協力は得にくくなる。","exampleZh":"如果一直采取节日般浮躁的态度，即使提出正确意见，也很难得到周围协作。","note":"例：\n節句な態度を取り続ければ、正しい意見を述べていても周囲の協力は得にくくなる。\n译：如果一直采取节日般浮躁的态度，即使提出正确意见，也很难得到周围协作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1665","seq":1665,"level":"N1","type":"主词条","word":"切実","kana":"せつじつ","pos":"[名·ナ形]","accent":"⓪","meaning":"恳切；切实","example":"切実な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“恳切；切实”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n切実な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“恳切；切实”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1666","seq":1666,"level":"N1","type":"主词条","word":"摂取","kana":"せっしゅ","pos":"[名·他動3]","accent":"①","meaning":"摄取；吸收","example":"栄養を摂取する量だけでなく、食事の時間や睡眠とのバランスも健康には大きく関わる。","exampleZh":"健康不仅与摄取营养的量有关，饮食时间和睡眠之间的平衡也有很大关系。","note":"例：\n栄養を摂取する量だけでなく、食事の時間や睡眠とのバランスも健康には大きく関わる。\n译：健康不仅与摄取营养的量有关，饮食时间和睡眠之间的平衡也有很大关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1667","seq":1667,"level":"N1","type":"主词条","word":"接触","kana":"せっしょく","pos":"[名·自動3]","accent":"⓪","meaning":"接触；联系","example":"感染者と接触した可能性がある人には、保健所から健康観察の連絡が入った。","exampleZh":"可能接触过感染者的人，会接到保健所关于健康观察的联络。","note":"例：\n感染者と接触した可能性がある人には、保健所から健康観察の連絡が入った。\n译：可能接触过感染者的人，会接到保健所关于健康观察的联络。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1668","seq":1668,"level":"N1","type":"主词条","word":"折衷","kana":"せっちゅう","pos":"[名·他動3]","accent":"⓪","meaning":"折中","example":"彼は折衷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“折中”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は折衷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“折中”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1669","seq":1669,"level":"N1","type":"主词条","word":"窃盗","kana":"せっとう","pos":"[名·他動3]","accent":"⓪","meaning":"偷窃","example":"窃盗の被害が相次いだため、商店街では防犯カメラの設置を進めることになった。","exampleZh":"由于偷窃受害事件接连发生，商店街决定推进安装监控摄像头。","note":"例：\n窃盗の被害が相次いだため、商店街では防犯カメラの設置を進めることになった。\n译：由于偷窃受害事件接连发生，商店街决定推进安装监控摄像头。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1670","seq":1670,"level":"N1","type":"主词条","word":"切ない","kana":"せつない","pos":"[イ形]","accent":"③","meaning":"难过，悲痛","example":"切ない状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“难过，悲痛”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n切ない状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“难过，悲痛”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1671","seq":1671,"level":"N1","type":"主词条","word":"切迫","kana":"せっぱく","pos":"[名·自動3]","accent":"⓪","meaning":"逼近、迫近；紧张","example":"切迫した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“逼近，迫近；紧张”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n切迫した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“逼近，迫近；紧张”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1672","seq":1672,"level":"N1","type":"主词条","word":"絶版","kana":"ぜっぱん","pos":"[名]","accent":"⓪","meaning":"绝版","example":"彼女は絶版をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“绝版”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は絶版をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“绝版”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1673","seq":1673,"level":"N1","type":"主词条","word":"切望","kana":"せつぼう","pos":"[名·他動3]","accent":"⓪","meaning":"切盼，殷切期望","example":"切望した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“切盼，殷切期望”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n切望した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“切盼，殷切期望”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1674","seq":1674,"level":"N1","type":"主词条","word":"絶望","kana":"ぜつぼう","pos":"[名·自動3]","accent":"⓪","meaning":"失望，绝望","example":"予期せず絶望した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“失望，绝望”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず絶望した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“失望，绝望”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1675","seq":1675,"level":"N1","type":"主词条","word":"設立","kana":"せつりつ","pos":"[名·他動3]","accent":"⓪","meaning":"设立，成立","example":"設立の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“设立，成立”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n設立の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“设立，成立”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1676","seq":1676,"level":"N1","type":"主词条","word":"蝉","kana":"せみ","pos":"[名]","accent":"⓪","meaning":"蝉","example":"蝉をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“蝉”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n蝉をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“蝉”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1677","seq":1677,"level":"N1","type":"主词条","word":"攻め","kana":"せめ","pos":"[名]","accent":"②","meaning":"进攻","example":"攻めに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“进攻”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n攻めに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“进攻”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1678","seq":1678,"level":"N1","type":"主词条","word":"ゼリー","kana":"ぜりー (jelly)","pos":"[名]","accent":"①","meaning":"果冻，啫喱状物","example":"ゼリーを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“果冻，啫喱状物”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nゼリーを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“果冻，啫喱状物”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1679","seq":1679,"level":"N1","type":"主词条","word":"セルフサービス","kana":"せるふさーびす (self-service)","pos":"[名]","accent":"④","meaning":"自助","example":"セルフサービスの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“自助”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nセルフサービスの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“自助”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1680","seq":1680,"level":"N1","type":"主词条","word":"セレモニー","kana":"せれもにー (ceremony)","pos":"[名]","accent":"①","meaning":"仪式，典礼","example":"セレモニーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“仪式，典礼”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nセレモニーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“仪式，典礼”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1681","seq":1681,"level":"N1","type":"主词条","word":"セロテープ","kana":"せろてーぷ (cello tape)","pos":"[名]","accent":"③","meaning":"透明胶带","example":"セロテープの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“透明胶带”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nセロテープの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“透明胶带”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1682","seq":1682,"level":"N1","type":"主词条","word":"せわしい","kana":"せわしい","pos":"[イ形]","accent":"③","meaning":"忙碌；着急，匆忙","example":"せわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“忙碌；着急，匆忙”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nせわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“忙碌；着急，匆忙”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1683","seq":1683,"level":"N1","type":"主词条","word":"全域","kana":"ぜんいき","pos":"[名]","accent":"⓪","meaning":"整个地区；整个领域","example":"観光客が増えた全域では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“整个地区；整个领域”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた全域では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“整个地区；整个领域”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1684","seq":1684,"level":"N1","type":"主词条","word":"全快","kana":"ぜんかい","pos":"[名·自動3]","accent":"⓪","meaning":"痊愈","example":"予期せず全快した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“痊愈”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず全快した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“痊愈”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1685","seq":1685,"level":"N1","type":"主词条","word":"全額","kana":"ぜんがく","pos":"[名]","accent":"⓪","meaning":"全额","example":"担当者は全額を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“全额”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は全額を数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“全额”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1686","seq":1686,"level":"N1","type":"主词条","word":"先決","kana":"せんけつ","pos":"[名·他動3]","accent":"⓪","meaning":"先决","example":"先決する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“先决”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n先決する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“先决”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1687","seq":1687,"level":"N1","type":"主词条","word":"宣言","kana":"せんげん","pos":"[名·他動3]","accent":"③","meaning":"宣言，宣布","example":"宣言する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“宣言，宣布”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n宣言する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“宣言，宣布”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1688","seq":1688,"level":"N1","type":"主词条","word":"選考","kana":"せんこう","pos":"[名·他動3]","accent":"⓪","meaning":"审查，选拔","example":"チームは選考する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“审查，选拔”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは選考する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“审查，选拔”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1689","seq":1689,"level":"N1","type":"主词条","word":"先行","kana":"せんこう","pos":"[名·自動3]","accent":"⓪","meaning":"先走，先行","example":"予期せず先行した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“先走，先行”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず先行した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“先走，先行”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1690","seq":1690,"level":"N1","type":"主词条","word":"線香","kana":"せんこう","pos":"[名]","accent":"⓪","meaning":"线香","example":"線香が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“线香”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n線香が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“线香”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1691","seq":1691,"level":"N1","type":"主词条","word":"繊細","kana":"せんさい","pos":"[名·ナ形]","accent":"⓪","meaning":"纤细，纤弱；敏感，细腻","example":"一度繊細だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“纤细，纤弱；敏感，细腻”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度繊細だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“纤细，纤弱；敏感，细腻”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1692","seq":1692,"level":"N1","type":"主词条","word":"戦災","kana":"せんさい","pos":"[名]","accent":"⓪","meaning":"战争之灾","example":"戦災の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“战争之灾”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n戦災の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“战争之灾”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1693","seq":1693,"level":"N1","type":"主词条","word":"専修","kana":"せんしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"专修，专攻","example":"大学では経済学を専修し、卒業後は地域金融の研究に携わっている。","exampleZh":"他在大学专修经济学，毕业后从事地域金融研究。","note":"例：\n大学では経済学を専修し、卒業後は地域金融の研究に携わっている。\n译：他在大学专修经济学，毕业后从事地域金融研究。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1694","seq":1694,"level":"N1","type":"主词条","word":"センス","kana":"せんす (sense)","pos":"[名]","accent":"①","meaning":"感觉；品味，审美能力","example":"センスが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“感觉；品味，审美能力”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\nセンスが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“感觉；品味，审美能力”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1695","seq":1695,"level":"N1","type":"主词条","word":"全盛","kana":"ぜんせい","pos":"[名]","accent":"⓪①","meaning":"全盛","example":"全盛をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“全盛”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n全盛をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“全盛”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1696","seq":1696,"level":"N1","type":"主词条","word":"全盛期","kana":"ぜんせいき","pos":"[名]","accent":"③","meaning":"全盛期","example":"全盛期を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“全盛期”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n全盛期を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“全盛期”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1697","seq":1697,"level":"N1","type":"主词条","word":"前線","kana":"ぜんせん","pos":"[名]","accent":"⓪","meaning":"前线","example":"前線を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“前线”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n前線を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“前线”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1698","seq":1698,"level":"N1","type":"主词条","word":"先代","kana":"せんだい","pos":"[名]","accent":"⓪","meaning":"上一代，上一辈","example":"市場環境が変わるなかで先代をどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“上一代，上一辈”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかで先代をどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“上一代，上一辈”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1699","seq":1699,"level":"N1","type":"主词条","word":"先だって","kana":"せんだって","pos":"[名·副]","accent":"⓪","meaning":"前几天，前些日子","example":"先だってお送りした資料に一部誤りがあったため、担当者は修正版を添えて改めて連絡した。","exampleZh":"由于前些日子发送的资料中有部分错误，负责人附上修正版并重新联系了对方。","note":"例：\n先だってお送りした資料に一部誤りがあったため、担当者は修正版を添えて改めて連絡した。\n译：由于前些日子发送的资料中有部分错误，负责人附上修正版并重新联系了对方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1700","seq":1700,"level":"N1","type":"主词条","word":"先天的","kana":"せんてんてき","pos":"[ナ形]","accent":"⓪","meaning":"先天性的","example":"一度先天的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“先天性的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度先天的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“先天性的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1701","seq":1701,"level":"N1","type":"主词条","word":"潜入","kana":"せんにゅう","pos":"[名·自動3]","accent":"⓪","meaning":"潜入","example":"潜入した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“潜入”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n潜入した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“潜入”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1702","seq":1702,"level":"N1","type":"主词条","word":"先入観","kana":"せんにゅうかん","pos":"[名]","accent":"③","meaning":"先入为主的观念","example":"先入観を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“先入为主的观念”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n先入観を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“先入为主的观念”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1703","seq":1703,"level":"N1","type":"主词条","word":"先方","kana":"せんぽう","pos":"[名]","accent":"⓪","meaning":"对面，远方；对方","example":"先方の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“对面，远方；对方”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n先方の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“对面，远方；对方”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1704","seq":1704,"level":"N1","type":"主词条","word":"前方","kana":"ぜんぽう","pos":"[名]","accent":"⓪③","meaning":"前面，前方","example":"前方の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“前面，前方”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n前方の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“前面，前方”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1705","seq":1705,"level":"N1","type":"主词条","word":"全滅","kana":"ぜんめつ","pos":"[名·自他動3]","accent":"⓪","meaning":"全歼，全军覆没","example":"病害虫の影響で作物が全滅する恐れが出たため、農家は早めに専門機関へ相談した。","exampleZh":"由于病虫害影响，作物出现全灭的风险，农户及早向专业机构咨询。","note":"例：\n病害虫の影響で作物が全滅する恐れが出たため、農家は早めに専門機関へ相談した。\n译：由于病虫害影响，作物出现全灭的风险，农户及早向专业机构咨询。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1706","seq":1706,"level":"N1","type":"主词条","word":"占領","kana":"せんりょう","pos":"[名·他動3]","accent":"⓪","meaning":"占领，占据","example":"初めて占領する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“占领，占据”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて占領する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“占领，占据”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1707","seq":1707,"level":"N1","type":"主词条","word":"善良","kana":"ぜんりょう","pos":"[名·ナ形]","accent":"⓪","meaning":"善良","example":"善良な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“善良”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n善良な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“善良”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1708","seq":1708,"level":"N1","type":"主词条","word":"前例","kana":"ぜんれい","pos":"[名]","accent":"⓪","meaning":"前例","example":"前例の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“前例”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n前例の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“前例”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1709","seq":1709,"level":"N1","type":"主词条","word":"添う","kana":"そう","pos":"[自動1]","accent":"⓪①","meaning":"跟随；符合，满足","example":"添う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“跟随；符合，满足”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n添う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“跟随；符合，满足”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1710","seq":1710,"level":"N1","type":"主词条","word":"〜層","kana":"〜そう","pos":"[接尾]","accent":"","meaning":"……层，阶层","example":"若年層の支持を広げるには、短い宣伝文句よりも政策が生活にどう関わるかを具体的に示す必要がある。","exampleZh":"要扩大年轻层的支持，比起简短宣传语，更需要具体说明政策如何关系到生活。","note":"例：\n若年層の支持を広げるには、短い宣伝文句よりも政策が生活にどう関わるかを具体的に示す必要がある。\n译：要扩大年轻层的支持，比起简短宣传语，更需要具体说明政策如何关系到生活。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1711","seq":1711,"level":"N1","type":"主词条","word":"〜像","kana":"〜ぞう","pos":"[接尾]","accent":"","meaning":"形象，样子","example":"理想像を明確にして努力することは大切だが、現実の自分との差を冷静に受け止める姿勢も必要だ。","exampleZh":"明确理想形象并为之努力很重要，但也需要冷静接受它与现实自我之间的差距。","note":"例：\n理想像を明確にして努力することは大切だが、現実の自分との差を冷静に受け止める姿勢も必要だ。\n译：明确理想形象并为之努力很重要，但也需要冷静接受它与现实自我之间的差距。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1712","seq":1712,"level":"N1","type":"主词条","word":"増益","kana":"ぞうえき","pos":"[名·自動3]","accent":"⓪","meaning":"利润增加","example":"増益する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“利润增加”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n増益する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“利润增加”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1713","seq":1713,"level":"N1","type":"主词条","word":"相応","kana":"そうおう","pos":"[名·ナ形·自動3]","accent":"⓪","meaning":"相称","example":"相応するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“相称”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n相応するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“相称”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1714","seq":1714,"level":"N1","type":"主词条","word":"総会","kana":"そうかい","pos":"[名]","accent":"⓪","meaning":"大会，全会","example":"総会が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“大会，全会”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n総会が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“大会，全会”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1715","seq":1715,"level":"N1","type":"主词条","word":"創刊","kana":"そうかん","pos":"[名·他動3]","accent":"⓪","meaning":"创刊","example":"地域の声を届けるために創刊された雑誌は、広告よりも住民の体験談を大切にしている。","exampleZh":"为传达地区声音而创刊的杂志，比起广告，更重视居民的亲身经历。","note":"例：\n地域の声を届けるために創刊された雑誌は、広告よりも住民の体験談を大切にしている。\n译：为传达地区声音而创刊的杂志，比起广告，更重视居民的亲身经历。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1716","seq":1716,"level":"N1","type":"主词条","word":"雑木","kana":"ぞうき","pos":"[名]","accent":"⓪","meaning":"杂木","example":"雑木の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“杂木”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n雑木の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“杂木”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1717","seq":1717,"level":"N1","type":"主词条","word":"早急","kana":"そうきゅう/さっきゅう","pos":"[名·ナ形]","accent":"⓪","meaning":"火速，火急","example":"早急な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“火速，火急”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n早急な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“火速，火急”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1718","seq":1718,"level":"N1","type":"主词条","word":"増強","kana":"ぞうきょう","pos":"[名·他動3]","accent":"⓪","meaning":"增强，加强","example":"増強する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“增强，加强”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n増強する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“增强，加强”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1719","seq":1719,"level":"N1","type":"主词条","word":"壮健","kana":"そうけん","pos":"[名·ナ形]","accent":"⓪","meaning":"健康，硬朗","example":"祖父は九十歳になっても壮健で、毎朝近所の公園まで歩く習慣を続けている。","exampleZh":"祖父即使九十岁仍很硬朗，坚持每天早晨走到附近公园。","note":"例：\n祖父は九十歳になっても壮健で、毎朝近所の公園まで歩く習慣を続けている。\n译：祖父即使九十岁仍很硬朗，坚持每天早晨走到附近公园。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1720","seq":1720,"level":"N1","type":"主词条","word":"走行","kana":"そうこう","pos":"[名]","accent":"⓪","meaning":"行驶，行车","example":"雨の日の高速道路では、走行中に急ブレーキをかけないよう十分な車間距離を保つ必要がある。","exampleZh":"雨天在高速公路行驶时，需要保持足够车距，避免行驶中突然急刹车。","note":"例：\n雨の日の高速道路では、走行中に急ブレーキをかけないよう十分な車間距離を保つ必要がある。\n译：雨天在高速公路行驶时，需要保持足够车距，避免行驶中突然急刹车。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1721","seq":1721,"level":"N1","type":"主词条","word":"捜査","kana":"そうさ","pos":"[名·他動3]","accent":"①","meaning":"搜查","example":"捜査した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“搜查”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n捜査した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“搜查”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1722","seq":1722,"level":"N1","type":"主词条","word":"相殺","kana":"そうさい","pos":"[名·他動3]","accent":"⓪","meaning":"扣除；（功过、优缺点）抵消","example":"初めて相殺する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“扣除；抵消”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて相殺する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“扣除；抵消”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1723","seq":1723,"level":"N1","type":"主词条","word":"惣菜","kana":"そうざい","pos":"[名]","accent":"⓪③","meaning":"家常的熟食","example":"忙しい日は惣菜を上手に利用しながらも、家族の健康を考えて野菜を一品足すようにしている。","exampleZh":"忙碌的日子里即使巧妙利用熟食，也会为了家人健康而加一道蔬菜。","note":"例：\n忙しい日は惣菜を上手に利用しながらも、家族の健康を考えて野菜を一品足すようにしている。\n译：忙碌的日子里即使巧妙利用熟食，也会为了家人健康而加一道蔬菜。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1724","seq":1724,"level":"N1","type":"主词条","word":"捜索","kana":"そうさく","pos":"[名·他動3]","accent":"⓪","meaning":"搜索，搜寻","example":"彼は捜索を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“搜索，搜寻”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は捜索を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“搜索，搜寻”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1725","seq":1725,"level":"N1","type":"主词条","word":"増産","kana":"ぞうさん","pos":"[名·他動3]","accent":"⓪","meaning":"增产","example":"需要の急増を受けて、工場は医療用マスクの増産を決めた。","exampleZh":"由于需求急剧增加，工厂决定增产医用口罩。","note":"例：\n需要の急増を受けて、工場は医療用マスクの増産を決めた。\n译：由于需求急剧增加，工厂决定增产医用口罩。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1726","seq":1726,"level":"N1","type":"主词条","word":"喪失","kana":"そうしつ","pos":"[名·他動3]","accent":"⓪","meaning":"丧失","example":"大切な人を失った喪失感は簡単には消えず、彼は時間をかけて日常を取り戻していった。","exampleZh":"失去重要之人带来的丧失感不会轻易消失，他花了很长时间才逐渐恢复日常。","note":"例：\n大切な人を失った喪失感は簡単には消えず、彼は時間をかけて日常を取り戻していった。\n译：失去重要之人带来的丧失感不会轻易消失，他花了很长时间才逐渐恢复日常。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1727","seq":1727,"level":"N1","type":"主词条","word":"操縦","kana":"そうじゅう","pos":"[名·他動3]","accent":"⓪","meaning":"操纵","example":"操縦する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“操纵”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n操縦する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“操纵”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1728","seq":1728,"level":"N1","type":"主词条","word":"増進","kana":"そうしん","pos":"[名·自他動3]","accent":"⓪","meaning":"增进，促进","example":"チームは増進する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“增进，促进”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは増進する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“增进，促进”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1729","seq":1729,"level":"N1","type":"主词条","word":"増税","kana":"ぞうぜい","pos":"[名·自動3]","accent":"⓪","meaning":"增税","example":"政府が増税を検討するなら、家計への負担だけでなく、社会保障の具体的な使い道も明確に示すべきだ。","exampleZh":"如果政府研究增税，就应不仅说明对家庭经济的负担，也明确展示社会保障的具体用途。","note":"例：\n政府が増税を検討するなら、家計への負担だけでなく、社会保障の具体的な使い道も明確に示すべきだ。\n译：如果政府研究增税，就应不仅说明对家庭经济的负担，也明确展示社会保障的具体用途。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1730","seq":1730,"level":"N1","type":"主词条","word":"相対","kana":"そうたい","pos":"[名]","accent":"⓪","meaning":"面对面；相对","example":"相対をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“面对面；相对”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n相対をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“面对面；相对”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1731","seq":1731,"level":"N1","type":"主词条","word":"早退","kana":"そうたい","pos":"[名·自動3]","accent":"⓪","meaning":"早退","example":"早退した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“早退”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n早退した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“早退”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1732","seq":1732,"level":"N1","type":"主词条","word":"壮大","kana":"そうだい","pos":"[名·ナ形]","accent":"⓪","meaning":"宏伟，宏大","example":"壮大な計画を掲げるだけでは不十分で、実行するための小さな手順を一つずつ固める必要がある。","exampleZh":"仅仅提出宏大计划还不够，还需要逐一巩固执行所需的小步骤。","note":"例：\n壮大な計画を掲げるだけでは不十分で、実行するための小さな手順を一つずつ固める必要がある。\n译：仅仅提出宏大计划还不够，还需要逐一巩固执行所需的小步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1733","seq":1733,"level":"N1","type":"主词条","word":"総長","kana":"そうちょう","pos":"[名]","accent":"①","meaning":"秘书长；综合大学校长","example":"総長の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“秘书长；综合大学校长”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n総長の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“秘书长；综合大学校长”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1734","seq":1734,"level":"N1","type":"主词条","word":"騒動","kana":"そうどう","pos":"[名]","accent":"①","meaning":"闹事，骚动","example":"騒動が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“闹事，骚动”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n騒動が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“闹事，骚动”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1735","seq":1735,"level":"N1","type":"主词条","word":"相場","kana":"そうば","pos":"[名]","accent":"⓪","meaning":"行情","example":"その相場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“行情”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその相場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“行情”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1736","seq":1736,"level":"N1","type":"主词条","word":"装備","kana":"そうび","pos":"[名·他動3]","accent":"①","meaning":"装备","example":"登山に必要な装備を整えずに山へ入れば、天候の急変に対応できなくなるおそれがある。","exampleZh":"如果不备齐登山所需装备就进山，可能无法应对天气突变。","note":"例：\n登山に必要な装備を整えずに山へ入れば、天候の急変に対応できなくなるおそれがある。\n译：如果不备齐登山所需装备就进山，可能无法应对天气突变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1737","seq":1737,"level":"N1","type":"主词条","word":"送付","kana":"そうふ","pos":"[名·他動3]","accent":"①⓪","meaning":"发送，寄出","example":"送付した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“发送，寄出”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n送付した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“发送，寄出”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1738","seq":1738,"level":"N1","type":"主词条","word":"創立","kana":"そうりつ","pos":"[名·他動3]","accent":"⓪","meaning":"创立","example":"初めて創立する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“创立”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて創立する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“创立”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1739","seq":1739,"level":"N1","type":"主词条","word":"添える","kana":"そえる","pos":"[他動2]","accent":"⓪","meaning":"附上，附加；增添","example":"添えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“附上，附加；增添”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n添えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“附上，附加；增添”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1740","seq":1740,"level":"N1","type":"主词条","word":"即座に","kana":"そくざに","pos":"[副]","accent":"①","meaning":"立即，当场","example":"誤った情報が公開されたと分かると、担当者は即座に訂正し、利用者へ謝罪の連絡を送った。","exampleZh":"一发现错误信息已经公开，负责人立即更正，并向使用者发送道歉联络。","note":"例：\n誤った情報が公開されたと分かると、担当者は即座に訂正し、利用者へ謝罪の連絡を送った。\n译：一发现错误信息已经公开，负责人立即更正，并向使用者发送道歉联络。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1741","seq":1741,"level":"N1","type":"主词条","word":"促進","kana":"そくしん","pos":"[名·他動3]","accent":"⓪","meaning":"促进","example":"地域交流を促進するため、市は空き店舗を活用したイベントを始めた。","exampleZh":"为了促进地区交流，市政府开始举办利用空置店铺的活动。","note":"例：\n地域交流を促進するため、市は空き店舗を活用したイベントを始めた。\n译：为了促进地区交流，市政府开始举办利用空置店铺的活动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1742","seq":1742,"level":"N1","type":"主词条","word":"即する","kana":"そくする","pos":"[自動3]","accent":"③","meaning":"适应，结合","example":"即する前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“适应，结合”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n即する前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“适应，结合”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1743","seq":1743,"level":"N1","type":"主词条","word":"ぞくぞく","kana":"ぞくぞく","pos":"[副·自動3]","accent":"①","meaning":"发冷，打寒战","example":"開場時間が近づくと、観客がぞくぞくとホールに集まってきた。","exampleZh":"开场时间临近后，观众接连不断地聚集到大厅。","note":"例：\n開場時間が近づくと、観客がぞくぞくとホールに集まってきた。\n译：开场时间临近后，观众接连不断地聚集到大厅。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1744","seq":1744,"level":"N1","type":"主词条","word":"続々と","kana":"ぞくぞくと","pos":"[副]","accent":"⓪①","meaning":"不断，陆陆续续","example":"開場時間が近づくと参加者が続々と集まり、受付では資料の配布と案内が追いつかなくなった。","exampleZh":"临近开场时间，参加者陆续聚集，前台的资料分发和引导渐渐跟不上。","note":"例：\n開場時間が近づくと参加者が続々と集まり、受付では資料の配布と案内が追いつかなくなった。\n译：临近开场时间，参加者陆续聚集，前台的资料分发和引导渐渐跟不上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1745","seq":1745,"level":"N1","type":"主词条","word":"束縛","kana":"そくばく","pos":"[名·他動3]","accent":"⓪","meaning":"束缚","example":"束縛した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“束缚”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n束縛した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“束缚”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1746","seq":1746,"level":"N1","type":"主词条","word":"側面","kana":"そくめん","pos":"[名]","accent":"⓪③","meaning":"侧面；方面","example":"便利さという側面だけで判断すると、新しい制度が生む負担を見落としてしまう。","exampleZh":"如果只从便利这一侧面判断，就会忽视新制度产生的负担。","note":"例：\n便利さという側面だけで判断すると、新しい制度が生む負担を見落としてしまう。\n译：如果只从便利这一侧面判断，就会忽视新制度产生的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1747","seq":1747,"level":"N1","type":"主词条","word":"損なう","kana":"そこなう","pos":"[他動1]","accent":"③","meaning":"损坏，毁坏，破坏","example":"損なう前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“损坏，毁坏，破坏”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n損なう前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“损坏，毁坏，破坏”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1748","seq":1748,"level":"N1","type":"主词条","word":"〜損なう","kana":"〜そこなう","pos":"[接尾]","accent":"","meaning":"没做成，错过做某事的机会","example":"彼は大事な場面で言い損なったことを後悔し、会議後に改めて関係者へ自分の考えを伝えた。","exampleZh":"他后悔在重要场面没能说出该说的话，会后又重新向相关人员传达了自己的想法。","note":"例：\n彼は大事な場面で言い損なったことを後悔し、会議後に改めて関係者へ自分の考えを伝えた。\n译：他后悔在重要场面没能说出该说的话，会后又重新向相关人员传达了自己的想法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1749","seq":1749,"level":"N1","type":"主词条","word":"素材","kana":"そざい","pos":"[名]","accent":"⓪","meaning":"原材料，素材","example":"修繕計画では素材の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。","exampleZh":"修缮计划不仅考虑了“原材料，素材”的费用，也考虑了施工期间对周边居民的影响。","note":"例：\n修繕計画では素材の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。\n译：修缮计划不仅考虑了“原材料，素材”的费用，也考虑了施工期间对周边居民的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1750","seq":1750,"level":"N1","type":"主词条","word":"阻止","kana":"そし","pos":"[名·他動3]","accent":"①","meaning":"阻止","example":"阻止する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“阻止”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n阻止する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“阻止”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1751","seq":1751,"level":"N1","type":"主词条","word":"素質","kana":"そしつ","pos":"[名]","accent":"⓪","meaning":"禀赋，天资","example":"素質を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“禀赋，天资”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n素質を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“禀赋，天资”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1752","seq":1752,"level":"N1","type":"主词条","word":"訴訟","kana":"そしょう","pos":"[名·自動3]","accent":"⓪","meaning":"诉讼","example":"訴訟する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“诉讼”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n訴訟する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“诉讼”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1753","seq":1753,"level":"N1","type":"主词条","word":"そそる","kana":"そそる","pos":"[他動1]","accent":"②","meaning":"引起，激起（某种感情等）","example":"無理にそそるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“引起，激起”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理にそそるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“引起，激起”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1754","seq":1754,"level":"N1","type":"主词条","word":"措置","kana":"そち","pos":"[名]","accent":"①","meaning":"措施","example":"措置をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“措施”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n措置をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“措施”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1755","seq":1755,"level":"N1","type":"主词条","word":"そっけない","kana":"そっけない","pos":"[イ形]","accent":"④","meaning":"冷淡，无情","example":"そっけないと感じた時点で無理を続けず、彼は予定を調整して早めに休むことにした。","exampleZh":"在感到对方冷淡的时候，他没有继续勉强，而是调整日程，决定早点休息。","note":"例：\nそっけないと感じた時点で無理を続けず、彼は予定を調整して早めに休むことにした。\n译：在感到对方冷淡的时候，他没有继续勉强，而是调整日程，决定早点休息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1756","seq":1756,"level":"N1","type":"主词条","word":"率先","kana":"そっせん","pos":"[名·自動3]","accent":"⓪","meaning":"率先，带头","example":"率先した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“率先，带头”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n率先した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“率先，带头”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1757","seq":1757,"level":"N1","type":"主词条","word":"ぞっと","kana":"ぞっと","pos":"[副·自動3]","accent":"⓪","meaning":"毛骨悚然，哆嗦","example":"夜道で背後から足音が聞こえ、彼女はぞっとして振り返った。","exampleZh":"夜路上听到身后传来脚步声，她毛骨悚然地回头看。","note":"例：\n夜道で背後から足音が聞こえ、彼女はぞっとして振り返った。\n译：夜路上听到身后传来脚步声，她毛骨悚然地回头看。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1758","seq":1758,"level":"N1","type":"主词条","word":"外回り","kana":"そとまわり","pos":"[名]","accent":"③","meaning":"外环，外圈；外勤","example":"外回りをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“外环，外圈；外勤”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n外回りをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“外环，外圈；外勤”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1759","seq":1759,"level":"N1","type":"主词条","word":"備え付ける","kana":"そなえつける","pos":"[他動2]","accent":"⑤⓪","meaning":"设置，安装","example":"無理に備え付けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“设置，安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に備え付けると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“设置，安装”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1760","seq":1760,"level":"N1","type":"主词条","word":"備わる","kana":"そなわる","pos":"[自動1]","accent":"③","meaning":"装有，装备；具有，具备（资质等）","example":"備わる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“装有，装备；具有，具备”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n備わる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“装有，装备；具有，具备”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1761","seq":1761,"level":"N1","type":"主词条","word":"そのもの","kana":"そのもの","pos":"[名]","accent":"④②","meaning":"本身","example":"そのものを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“本身”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nそのものを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“本身”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1762","seq":1762,"level":"N1","type":"主词条","word":"〜そのもの","kana":"〜そのもの","pos":"[接尾]","accent":"","meaning":"非常（强调其前面的词）","example":"この景色は春そのもので、川沿いの桜と柔らかな風が歩く人の表情まで明るくしていた。","exampleZh":"这片景色简直就是春天本身，河边樱花和柔和的风连行人的表情都照亮了。","note":"例：\nこの景色は春そのもので、川沿いの桜と柔らかな風が歩く人の表情まで明るくしていた。\n译：这片景色简直就是春天本身，河边樱花和柔和的风连行人的表情都照亮了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1763","seq":1763,"level":"N1","type":"主词条","word":"聳える","kana":"そびえる","pos":"[自動2]","accent":"③","meaning":"矗立，耸立","example":"聳えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“矗立，耸立”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n聳えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“矗立，耸立”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1764","seq":1764,"level":"N1","type":"主词条","word":"〜そびれる","kana":"〜そびれる","pos":"[接尾]","accent":"","meaning":"失掉机会，错过机会","example":"忙しくて昼食を食べそびれた彼は、夕方の会議で集中力を保つために温かいお茶だけ飲んだ。","exampleZh":"忙得错过午饭的他，为了在傍晚会议中保持注意力，只喝了一杯热茶。","note":"例：\n忙しくて昼食を食べそびれた彼は、夕方の会議で集中力を保つために温かいお茶だけ飲んだ。\n译：忙得错过午饭的他，为了在傍晚会议中保持注意力，只喝了一杯热茶。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1765","seq":1765,"level":"N1","type":"主词条","word":"ソフトウェア","kana":"ソフトウェア (software)","pos":"[名]","accent":"⑤","meaning":"软件","example":"新しいソフトウェアを導入する前に、担当者は操作性だけでなく、故障時の対応手順も確認した。","exampleZh":"导入新软件之前，负责人不仅确认操作性，也确认了故障时的应对步骤。","note":"例：\n新しいソフトウェアを導入する前に、担当者は操作性だけでなく、故障時の対応手順も確認した。\n译：导入新软件之前，负责人不仅确认操作性，也确认了故障时的应对步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1766","seq":1766,"level":"N1","type":"主词条","word":"素朴","kana":"そぼく","pos":"[名·ナ形]","accent":"⓪","meaning":"朴素；单纯，简单","example":"一度素朴だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“朴素；单纯，简单”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度素朴だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“朴素；单纯，简单”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1767","seq":1767,"level":"N1","type":"主词条","word":"背く","kana":"そむく","pos":"[自動1]","accent":"②","meaning":"违背，违反","example":"会社の方針に背く意見であっても、根拠があるなら会議で正面から議論するべきだ。","exampleZh":"即使是违背公司方针的意见，只要有依据，也应在会议上正面讨论。","note":"例：\n会社の方針に背く意見であっても、根拠があるなら会議で正面から議論するべきだ。\n译：即使是违背公司方针的意见，只要有依据，也应在会议上正面讨论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1768","seq":1768,"level":"N1","type":"主词条","word":"逸らす","kana":"そらす","pos":"[他動1]","accent":"②","meaning":"转移","example":"無理に逸らすと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“转移”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に逸らすと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“转移”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1769","seq":1769,"level":"N1","type":"主词条","word":"反らす","kana":"そらす","pos":"[他動1]","accent":"②","meaning":"弄弯；挺起","example":"反らすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“弄弯；挺起”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n反らすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“弄弯；挺起”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1770","seq":1770,"level":"N1","type":"主词条","word":"反る","kana":"そる","pos":"[自動1]","accent":"①","meaning":"弯曲，挺起胸脯","example":"反るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“弯曲，挺起胸脯”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n反るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“弯曲，挺起胸脯”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1771","seq":1771,"level":"N1","type":"主词条","word":"それでいて","kana":"それでいて","pos":"[接]","accent":"⓪","meaning":"表转折，尽管如此，然而","example":"彼は厳しい指導者だ。それでいて、失敗した部下を最後まで見捨てない。","exampleZh":"他是一位严格的指导者。尽管如此，他不会抛弃失败的部下。","note":"例：\n彼は厳しい指導者だ。それでいて、失敗した部下を最後まで見捨てない。\n译：他是一位严格的指导者。尽管如此，他不会抛弃失败的部下。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1772","seq":1772,"level":"N1","type":"主词条","word":"それとなしに","kana":"それとなしに","pos":"[副]","accent":"④","meaning":"婉转地，拐弯抹角地","example":"彼女は相手を傷つけないよう、それとなしに予定の変更を伝え、反応を慎重にうかがった。","exampleZh":"她为了不伤害对方，委婉地告知日程变更，并谨慎观察反应。","note":"例：\n彼女は相手を傷つけないよう、それとなしに予定の変更を伝え、反応を慎重にうかがった。\n译：她为了不伤害对方，委婉地告知日程变更，并谨慎观察反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1773","seq":1773,"level":"N1","type":"主词条","word":"それなり","kana":"それなり","pos":"[名·副]","accent":"⓪④","meaning":"与那相对应的","example":"準備時間は短かったが、各自が役割を工夫したので、それなりに説得力のある発表になった。","exampleZh":"准备时间虽然短，但每个人都在职责上动脑筋，因此发表也有了相应的说服力。","note":"例：\n準備時間は短かったが、各自が役割を工夫したので、それなりに説得力のある発表になった。\n译：准备时间虽然短，但每个人都在职责上动脑筋，因此发表也有了相应的说服力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1774","seq":1774,"level":"N1","type":"主词条","word":"それは","kana":"それは","pos":"[嘆]","accent":"⓪","meaning":"那可真是","example":"それは大変でしたね。まずは少し休んでから、今後の手続きを一緒に確認しましょう。","exampleZh":"那可真辛苦。先稍微休息一下，再一起确认之后的手续吧。","note":"例：\nそれは大変でしたね。まずは少し休んでから、今後の手続きを一緒に確認しましょう。\n译：那可真辛苦。先稍微休息一下，再一起确认之后的手续吧。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1775","seq":1775,"level":"N1","type":"主词条","word":"それはさておき","kana":"それはさておき","pos":"[接]","accent":"⓪","meaning":"此话暂且不提","example":"それはさておき、今日決めるべき議題に戻りましょう。","exampleZh":"那个先暂且不提，我们回到今天必须决定的议题上吧。","note":"例：\nそれはさておき、今日決めるべき議題に戻りましょう。\n译：那个先暂且不提，我们回到今天必须决定的议题上吧。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1776","seq":1776,"level":"N1","type":"主词条","word":"それはそうと","kana":"それはそうと","pos":"[接]","accent":"⓪","meaning":"前话暂不提了，顺便问一下","example":"それはそうと、来週の出張に必要な資料はもう準備できていますか。","exampleZh":"话说回来，下周出差需要的资料已经准备好了吗？","note":"例：\nそれはそうと、来週の出張に必要な資料はもう準備できていますか。\n译：话说回来，下周出差需要的资料已经准备好了吗？","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1777","seq":1777,"level":"N1","type":"主词条","word":"それはそれは","kana":"それはそれは","pos":"[嘆]","accent":"⓪","meaning":"非常，可真是","example":"山頂から見た朝焼けは、それはそれは美しく、言葉を失うほどだった。","exampleZh":"从山顶看到的朝霞非常美，令人几乎说不出话来。","note":"例：\n山頂から見た朝焼けは、それはそれは美しく、言葉を失うほどだった。\n译：从山顶看到的朝霞非常美，令人几乎说不出话来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1778","seq":1778,"level":"N1","type":"主词条","word":"それゆえ","kana":"それゆえ","pos":"[接]","accent":"⓪","meaning":"所以，因此","example":"この道路は通学路である。それゆえ、工事中も歩行者の安全確保を最優先にすべきだ。","exampleZh":"这条道路是上学路。因此，施工期间也应最优先确保行人安全。","note":"例：\nこの道路は通学路である。それゆえ、工事中も歩行者の安全確保を最優先にすべきだ。\n译：这条道路是上学路。因此，施工期间也应最优先确保行人安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1779","seq":1779,"level":"N1","type":"主词条","word":"〜揃い","kana":"〜ぞろい","pos":"[接尾]","accent":"","meaning":"一致，都是，清一色","example":"今年の新人は優秀ぞろいだが、経験が浅い分だけ判断に迷ったときの相談体制を整える必要がある。","exampleZh":"今年的新人个个优秀，但正因为经验尚浅，也需要建立在判断犹豫时可以咨询的体制。","note":"例：\n今年の新人は優秀ぞろいだが、経験が浅い分だけ判断に迷ったときの相談体制を整える必要がある。\n译：今年的新人个个优秀，但正因为经验尚浅，也需要建立在判断犹豫时可以咨询的体制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1780","seq":1780,"level":"N1","type":"主词条","word":"ぞろぞろ","kana":"ぞろぞろ","pos":"[副]","accent":"①","meaning":"一个跟着一个，络绎不绝","example":"雨がやむと観光客がぞろぞろ店の外へ出て、狭い通りはすぐに人でいっぱいになった。","exampleZh":"雨停后，游客一个接一个走出店外，狭窄的街道很快挤满了人。","note":"例：\n雨がやむと観光客がぞろぞろ店の外へ出て、狭い通りはすぐに人でいっぱいになった。\n译：雨停后，游客一个接一个走出店外，狭窄的街道很快挤满了人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1781","seq":1781,"level":"N1","type":"主词条","word":"尊厳","kana":"そんげん","pos":"[名]","accent":"⓪③","meaning":"尊严","example":"尊厳を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“尊严”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n尊厳を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“尊严”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1782","seq":1782,"level":"N1","type":"主词条","word":"ぞんざい","kana":"ぞんざい","pos":"[ナ形]","accent":"③","meaning":"草率，粗鲁","example":"周囲からぞんざいだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“草率，粗鲁”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲からぞんざいだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“草率，粗鲁”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1783","seq":1783,"level":"N1","type":"主词条","word":"存続","kana":"そんぞく","pos":"[名·自動3]","accent":"⓪","meaning":"存续，延续","example":"存続するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“存续，延续”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n存続するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“存续，延续”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1784","seq":1784,"level":"N1","type":"主词条","word":"そんな","kana":"そんな","pos":"[嘆]","accent":"⓪","meaning":"没那回事，不会的","example":"そんな、今さら中止だなんて信じられない。","exampleZh":"怎么会这样，现在才取消实在令人难以相信。","note":"例：\nそんな、今さら中止だなんて信じられない。\n译：怎么会这样，现在才取消实在令人难以相信。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1785","seq":1785,"level":"N1","type":"主词条","word":"ダース","kana":"だーす","pos":"[名]","accent":"①","meaning":"打，12个","example":"ダースが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“打，12个”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nダースが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“打，12个”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1786","seq":1786,"level":"N1","type":"主词条","word":"ターミナル","kana":"たーみなる (terminal)","pos":"[名]","accent":"①","meaning":"（交通线路）终点站，始发站；机场大楼","example":"ターミナルを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“终点站，始发站；机场大楼”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nターミナルを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“终点站，始发站；机场大楼”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1787","seq":1787,"level":"N1","type":"主词条","word":"〜帯","kana":"〜たい","pos":"[接尾]","accent":"","meaning":"……带，区域","example":"この地域は工業地帯として発展した一方で、住民は騒音や交通量の増加にも向き合ってきた。","exampleZh":"这个地区一方面作为工业地带发展，另一方面居民也一直面对噪音和交通量增加的问题。","note":"例：\nこの地域は工業地帯として発展した一方で、住民は騒音や交通量の増加にも向き合ってきた。\n译：这个地区一方面作为工业地带发展，另一方面居民也一直面对噪音和交通量增加的问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1788","seq":1788,"level":"N1","type":"主词条","word":"〜隊","kana":"〜たい","pos":"[接尾]","accent":"","meaning":"……队伍","example":"救助隊がすぐに現場へ駆けつけ、崩れやすい斜面を確認しながら取り残された人を慎重に助け出した。","exampleZh":"救助队立刻赶到现场，一边确认容易崩塌的斜坡，一边谨慎救出被困人员。","note":"例：\n救助隊がすぐに現場へ駆けつけ、崩れやすい斜面を確認しながら取り残された人を慎重に助け出した。\n译：救助队立刻赶到现场，一边确认容易崩塌的斜坡，一边谨慎救出被困人员。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1789","seq":1789,"level":"N1","type":"主词条","word":"体当たり","kana":"たいあたり","pos":"[名·自動3]","accent":"③","meaning":"冲撞；全力以赴","example":"体当たりした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“冲撞；全力以赴”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n体当たりした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“冲撞；全力以赴”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1790","seq":1790,"level":"N1","type":"主词条","word":"対応","kana":"たいおう","pos":"[名·自動3]","accent":"⓪","meaning":"相应；应付","example":"対応してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“相应；应付”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n対応してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“相应；应付”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1791","seq":1791,"level":"N1","type":"主词条","word":"大家","kana":"たいか","pos":"[名]","accent":"①","meaning":"大家，权威；名门","example":"修繕計画では大家の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。","exampleZh":"修缮计划不仅考虑了“大家，权威；名门”的费用，也考虑了施工期间对周边居民的影响。","note":"例：\n修繕計画では大家の費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。\n译：修缮计划不仅考虑了“大家，权威；名门”的费用，也考虑了施工期间对周边居民的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1792","seq":1792,"level":"N1","type":"主词条","word":"退化","kana":"たいか","pos":"[名·自動3]","accent":"①⓪","meaning":"退化；衰弱","example":"退化する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“退化；衰弱”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n退化する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“退化；衰弱”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1793","seq":1793,"level":"N1","type":"主词条","word":"大概","kana":"たいがい","pos":"[名·副]","accent":"⓪","meaning":"多半，大致，大概","example":"大概の問題は現場で解決できるが、今回のように法的判断を伴う案件は専門家の助言が欠かせない。","exampleZh":"大多数问题可以在现场解决，但像这次这样伴随法律判断的案件，专家建议不可或缺。","note":"例：\n大概の問題は現場で解決できるが、今回のように法的判断を伴う案件は専門家の助言が欠かせない。\n译：大多数问题可以在现场解决，但像这次这样伴随法律判断的案件，专家建议不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1794","seq":1794,"level":"N1","type":"主词条","word":"耐久力","kana":"たいきゅうりょく","pos":"[名]","accent":"③","meaning":"耐力，耐用程度","example":"この素材の耐久力を確かめるため、研究チームは高温や強い衝撃を想定した試験を重ねた。","exampleZh":"为了确认这种材料的耐久力，研究团队反复进行了设想高温和强烈冲击的试验。","note":"例：\nこの素材の耐久力を確かめるため、研究チームは高温や強い衝撃を想定した試験を重ねた。\n译：为了确认这种材料的耐久力，研究团队反复进行了设想高温和强烈冲击的试验。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1795","seq":1795,"level":"N1","type":"主词条","word":"対決","kana":"たいけつ","pos":"[名·自動3]","accent":"⓪","meaning":"对决，决战，交锋","example":"対決してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“对决，决战，交锋”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n対決してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“对决，决战，交锋”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1796","seq":1796,"level":"N1","type":"主词条","word":"対抗","kana":"たいこう","pos":"[名·自動3]","accent":"⓪","meaning":"对抗，抗衡","example":"対抗した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“对抗，抗衡”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n対抗した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“对抗，抗衡”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1797","seq":1797,"level":"N1","type":"主词条","word":"代行","kana":"だいこう","pos":"[名·他動3]","accent":"⓪","meaning":"代行，代办","example":"急病の同僚に代わって、彼女が会議での説明を代行した。","exampleZh":"她代替突然生病的同事，在会议上进行了说明。","note":"例：\n急病の同僚に代わって、彼女が会議での説明を代行した。\n译：她代替突然生病的同事，在会议上进行了说明。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1798","seq":1798,"level":"N1","type":"主词条","word":"退治","kana":"たいじ","pos":"[名·他動3]","accent":"①⓪","meaning":"扑灭，消灭","example":"退治する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“扑灭，消灭”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n退治する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“扑灭，消灭”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1799","seq":1799,"level":"N1","type":"主词条","word":"ダイジェスト","kana":"だいじぇすと (digest)","pos":"[名·他動3]","accent":"①","meaning":"摘要","example":"ダイジェストの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“摘要”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\nダイジェストの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“摘要”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1800","seq":1800,"level":"N1","type":"主词条","word":"体質","kana":"たいしつ","pos":"[名]","accent":"⓪","meaning":"体质；（组织、机构等成为问题的）性质","example":"体質を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。","exampleZh":"如果放任“体质；性质”不管，不仅现场负担会增加，也可能失去使用者的信任。","note":"例：\n体質を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。\n译：如果放任“体质；性质”不管，不仅现场负担会增加，也可能失去使用者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1801","seq":1801,"level":"N1","type":"主词条","word":"大衆","kana":"たいしゅう","pos":"[名]","accent":"⓪","meaning":"大众，群众","example":"大衆が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“大众，群众”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n大衆が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“大众，群众”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1802","seq":1802,"level":"N1","type":"主词条","word":"題する","kana":"だいする","pos":"[自他動3]","accent":"③","meaning":"起标题，题名","example":"題する前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“起标题，题名”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n題する前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“起标题，题名”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1803","seq":1803,"level":"N1","type":"主词条","word":"態勢","kana":"たいせい","pos":"[名]","accent":"⓪","meaning":"态势，准备","example":"態勢を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“态势，准备”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n態勢を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“态势，准备”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1804","seq":1804,"level":"N1","type":"主词条","word":"対談","kana":"たいだん","pos":"[名·自動3]","accent":"⓪","meaning":"对谈","example":"予期せず対談した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“对谈”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず対談した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“对谈”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1805","seq":1805,"level":"N1","type":"主词条","word":"大胆","kana":"だいたん","pos":"[名·ナ形]","accent":"③","meaning":"大胆","example":"大胆な改革を進めるには、失敗した場合の影響を小さくする備えも同時に必要だ。","exampleZh":"推进大胆改革时，也同时需要准备好减少失败影响的措施。","note":"例：\n大胆な改革を進めるには、失敗した場合の影響を小さくする備えも同時に必要だ。\n译：推进大胆改革时，也同时需要准备好减少失败影响的措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1806","seq":1806,"level":"N1","type":"主词条","word":"台無し","kana":"だいなし","pos":"[名·ナ形]","accent":"⓪","meaning":"糟蹋，断送","example":"台無しな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“糟蹋，断送”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\n台無しな対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“糟蹋，断送”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1807","seq":1807,"level":"N1","type":"主词条","word":"滞納","kana":"たいのう","pos":"[名·他動3]","accent":"⓪","meaning":"滞纳，拖欠","example":"滞納する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“滞纳，拖欠”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n滞納する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“滞纳，拖欠”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1808","seq":1808,"level":"N1","type":"主词条","word":"対比","kana":"たいひ","pos":"[名·他動3]","accent":"⓪①","meaning":"对照，对比","example":"チームは対比する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“对照，对比”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは対比する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“对照，对比”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1809","seq":1809,"level":"N1","type":"主词条","word":"大部","kana":"たいぶ","pos":"[名]","accent":"①","meaning":"大部头；大部分","example":"大部に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“大部头；大部分”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n大部に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“大部头；大部分”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1810","seq":1810,"level":"N1","type":"主词条","word":"代弁","kana":"だいべん","pos":"[名·他動3]","accent":"⓪","meaning":"代为辩解；代办；替人偿还","example":"初めて代弁する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“代为辩解；代办”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて代弁する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“代为辩解；代办”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1811","seq":1811,"level":"N1","type":"主词条","word":"待望","kana":"たいぼう","pos":"[名·他動3]","accent":"⓪","meaning":"期望，盼望","example":"待望の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“期望，盼望”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n待望の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“期望，盼望”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1812","seq":1812,"level":"N1","type":"主词条","word":"台本","kana":"だいほん","pos":"[名]","accent":"⓪","meaning":"剧本，脚本","example":"新しい台本を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。","exampleZh":"通过引入新的“剧本，脚本”，传统作品中增添了现代感的紧张气氛。","note":"例：\n新しい台本を取り入れることで、昔ながらの作品に現代的な緊張感が加わった。\n译：通过引入新的“剧本，脚本”，传统作品中增添了现代感的紧张气氛。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1813","seq":1813,"level":"N1","type":"主词条","word":"タイマー","kana":"たいまー (timer)","pos":"[名]","accent":"①","meaning":"秒表，定时器","example":"タイマーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“秒表，定时器”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nタイマーをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“秒表，定时器”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1814","seq":1814,"level":"N1","type":"主词条","word":"怠慢","kana":"たいまん","pos":"[名·ナ形]","accent":"⓪","meaning":"怠慢，玩忽","example":"怠慢な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“怠慢，玩忽”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\n怠慢な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“怠慢，玩忽”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1815","seq":1815,"level":"N1","type":"主词条","word":"タイミング","kana":"たいみんぐ (timing)","pos":"[名]","accent":"⓪","meaning":"时机","example":"タイミングが近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。","exampleZh":"越接近“时机”，相关人员越细致地共享彼此作业进度，试图防止返工。","note":"例：\nタイミングが近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。\n译：越接近“时机”，相关人员越细致地共享彼此作业进度，试图防止返工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1816","seq":1816,"level":"N1","type":"主词条","word":"タイムサービス","kana":"たいむさーびす","pos":"[名]","accent":"④","meaning":"限时低价销售","example":"市場環境が変わるなかでタイムサービスをどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“限时低价销售”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかでタイムサービスをどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“限时低价销售”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1817","seq":1817,"level":"N1","type":"主词条","word":"タイムリー","kana":"たいむりー (timely)","pos":"[ナ形]","accent":"①","meaning":"适时，正合时宜","example":"タイムリーな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“适时，正合时宜”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nタイムリーな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“适时，正合时宜”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1818","seq":1818,"level":"N1","type":"主词条","word":"対面","kana":"たいめん","pos":"[名·自動3]","accent":"⓪","meaning":"会面，见面","example":"対面するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“会面，见面”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n対面するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“会面，见面”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1819","seq":1819,"level":"N1","type":"主词条","word":"対話","kana":"たいわ","pos":"[名·自動3]","accent":"⓪","meaning":"对话","example":"予期せず対話した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“对话”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず対話した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“对话”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1820","seq":1820,"level":"N1","type":"主词条","word":"耐える","kana":"たえる","pos":"[自動2]","accent":"②","meaning":"忍受；经得起","example":"耐える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“忍受；经得起”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n耐える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“忍受；经得起”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1821","seq":1821,"level":"N1","type":"主词条","word":"〜高","kana":"〜だか","pos":"[接尾]","accent":"","meaning":"容积，数量；高涨，升值","example":"売上高が前年を上回ったとはいえ、原材料費も上がっているため、利益率の改善にはまだ課題が残る。","exampleZh":"虽说销售额超过去年，但原材料费用也在上涨，因此利润率改善仍有课题。","note":"例：\n売上高が前年を上回ったとはいえ、原材料費も上がっているため、利益率の改善にはまだ課題が残る。\n译：虽说销售额超过去年，但原材料费用也在上涨，因此利润率改善仍有课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1822","seq":1822,"level":"N1","type":"主词条","word":"打開","kana":"だかい","pos":"[名·他動3]","accent":"⓪","meaning":"打开，打破","example":"打開する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“打开，打破”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n打開する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“打开，打破”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1823","seq":1823,"level":"N1","type":"主词条","word":"高が","kana":"たかが","pos":"[副]","accent":"①②","meaning":"至多","example":"高が一枚の書類と思って確認を怠ると、後で申請全体をやり直すことになりかねない。","exampleZh":"如果觉得“不过是一张文件”而怠于确认，之后可能不得不重做整个申请。","note":"例：\n高が一枚の書類と思って確認を怠ると、後で申請全体をやり直すことになりかねない。\n译：如果觉得“不过是一张文件”而怠于确认，之后可能不得不重做整个申请。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1824","seq":1824,"level":"N1","type":"主词条","word":"高台","kana":"たかだい","pos":"[名]","accent":"⓪","meaning":"高地，高岗","example":"高台の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“高地，高岗”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n高台の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“高地，高岗”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1825","seq":1825,"level":"N1","type":"主词条","word":"高々","kana":"たかだか","pos":"[副]","accent":"②⓪","meaning":"高高地；大声地；顶多","example":"参加者は高々十人ほどだったが、意見は多様で、予定していた時間を大きく超えて議論が続いた。","exampleZh":"参加者顶多十人左右，但意见多样，讨论大大超过了预定时间。","note":"例：\n参加者は高々十人ほどだったが、意見は多様で、予定していた時間を大きく超えて議論が続いた。\n译：参加者顶多十人左右，但意见多样，讨论大大超过了预定时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1826","seq":1826,"level":"N1","type":"主词条","word":"高飛車","kana":"たかびしゃ","pos":"[名·ナ形]","accent":"⓪","meaning":"高压，强横、高傲，强硬的姿态","example":"高飛車な態度で要求を押し通そうとすると、正当な意見であっても相手に受け入れられにくい。","exampleZh":"如果用高压态度强行通过要求，即使是正当意见，也很难被对方接受。","note":"例：\n高飛車な態度で要求を押し通そうとすると、正当な意見であっても相手に受け入れられにくい。\n译：如果用高压态度强行通过要求，即使是正当意见，也很难被对方接受。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1827","seq":1827,"level":"N1","type":"主词条","word":"高み","kana":"たかみ","pos":"[名]","accent":"⓪①","meaning":"高处","example":"高みをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“高处”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n高みをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“高处”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1828","seq":1828,"level":"N1","type":"主词条","word":"多岐","kana":"たき","pos":"[名·ナ形]","accent":"①","meaning":"多方面；复杂","example":"多岐な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“多方面；复杂”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n多岐な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“多方面；复杂”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1829","seq":1829,"level":"N1","type":"主词条","word":"妥協","kana":"だきょう","pos":"[名·自動3]","accent":"⓪","meaning":"妥协","example":"予期せず妥協した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“妥协”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず妥協した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“妥协”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1830","seq":1830,"level":"N1","type":"主词条","word":"類","kana":"たぐい","pos":"[名]","accent":"⓪③","meaning":"同类，同种类；匹敌","example":"この類の問題は表面だけ直しても再発するため、仕組み全体を見直す必要がある。","exampleZh":"这类问题只修正表面也会再次发生，因此有必要重新审视整个机制。","note":"例：\nこの類の問題は表面だけ直しても再発するため、仕組み全体を見直す必要がある。\n译：这类问题只修正表面也会再次发生，因此有必要重新审视整个机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1831","seq":1831,"level":"N1","type":"主词条","word":"逞しい","kana":"たくましい","pos":"[イ形]","accent":"④","meaning":"（身体）强壮，魁梧；（意志）刚强","example":"逞しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“强壮，魁梧；刚强”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n逞しい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“强壮，魁梧；刚强”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1832","seq":1832,"level":"N1","type":"主词条","word":"巧み","kana":"たくみ","pos":"[名·ナ形]","accent":"⓪①","meaning":"巧妙","example":"巧みな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“巧妙”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n巧みな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“巧妙”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1833","seq":1833,"level":"N1","type":"主词条","word":"企み","kana":"たくらみ","pos":"[名]","accent":"⓪④","meaning":"阴谋，诡计","example":"彼の笑顔の裏に何か企みがあるのではないかと、同僚たちは慎重に様子を見ていた。","exampleZh":"同事们怀疑他的笑容背后是否有什么企图，因而谨慎观察情况。","note":"例：\n彼の笑顔の裏に何か企みがあるのではないかと、同僚たちは慎重に様子を見ていた。\n译：同事们怀疑他的笑容背后是否有什么企图，因而谨慎观察情况。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1834","seq":1834,"level":"N1","type":"主词条","word":"企む","kana":"たくらむ","pos":"[他動1]","accent":"③","meaning":"谋划，企图","example":"無理に企むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“谋划，企图”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に企むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“谋划，企图”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1835","seq":1835,"level":"N1","type":"主词条","word":"打撃","kana":"だげき","pos":"[名]","accent":"①","meaning":"打击；损害，损失","example":"主要な取引先を失ったことは会社にとって大きな打撃だったが、営業部は新しい市場の開拓に動き出した。","exampleZh":"失去主要客户对公司而言是巨大打击，但营业部已开始开拓新的市场。","note":"例：\n主要な取引先を失ったことは会社にとって大きな打撃だったが、営業部は新しい市場の開拓に動き出した。\n译：失去主要客户对公司而言是巨大打击，但营业部已开始开拓新的市场。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1836","seq":1836,"level":"N1","type":"主词条","word":"妥結","kana":"だけつ","pos":"[名·自動3]","accent":"⓪","meaning":"妥协","example":"妥結した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“妥协”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n妥結した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“妥协”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1837","seq":1837,"level":"N1","type":"主词条","word":"駄作","kana":"ださく","pos":"[名]","accent":"⓪","meaning":"拙劣的作品","example":"その作品では駄作が控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。","exampleZh":"裁剪布料之前，她又一次谨慎确认了纸样方向和缝份。","note":"例：\nその作品では駄作が控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。\n译：裁剪布料之前，她又一次谨慎确认了纸样方向和缝份。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1838","seq":1838,"level":"N1","type":"主词条","word":"打診","kana":"だしん","pos":"[名·他動3]","accent":"⓪","meaning":"打探，试探","example":"打診する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“打探，试探”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n打診する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“打探，试探”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1839","seq":1839,"level":"N1","type":"主词条","word":"多数決","kana":"たすうけつ","pos":"[名]","accent":"②","meaning":"多数表决","example":"多数決の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“多数表决”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n多数決の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“多数表决”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1840","seq":1840,"level":"N1","type":"主词条","word":"携わる","kana":"たずさわる","pos":"[自動1]","accent":"④","meaning":"参与，从事","example":"地域医療に携わる人々は、限られた人員の中でも患者の不安に丁寧に向き合っている。","exampleZh":"从事地区医疗的人们，即使在人手有限的情况下，也细致面对患者的不安。","note":"例：\n地域医療に携わる人々は、限られた人員の中でも患者の不安に丁寧に向き合っている。\n译：从事地区医疗的人们，即使在人手有限的情况下，也细致面对患者的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1841","seq":1841,"level":"N1","type":"主词条","word":"多大","kana":"ただい","pos":"[名·ナ形]","accent":"⓪","meaning":"很大","example":"台風による多大な被害を受けた地域では、住民だけでなく近隣の自治体も復旧作業を支援した。","exampleZh":"受到台风严重灾害的地区，不仅居民，附近自治体也支援了复旧工作。","note":"例：\n台風による多大な被害を受けた地域では、住民だけでなく近隣の自治体も復旧作業を支援した。\n译：受到台风严重灾害的地区，不仅居民，附近自治体也支援了复旧工作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1842","seq":1842,"level":"N1","type":"主词条","word":"ただでさえ","kana":"ただでさえ","pos":"[副]","accent":"①","meaning":"本来就（已经）","example":"ただでさえ人手が足りない時期に急な依頼が重なり、現場では優先順位の見直しが必要になった。","exampleZh":"在人手本来就不足的时期又叠加了紧急委托，现场不得不重新调整优先顺序。","note":"例：\nただでさえ人手が足りない時期に急な依頼が重なり、現場では優先順位の見直しが必要になった。\n译：在人手本来就不足的时期又叠加了紧急委托，现场不得不重新调整优先顺序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1843","seq":1843,"level":"N1","type":"主词条","word":"漂う","kana":"ただよう","pos":"[自動1]","accent":"③","meaning":"漂，漂浮；充满","example":"漂う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“漂，漂浮；充满”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n漂う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“漂，漂浮；充满”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1844","seq":1844,"level":"N1","type":"主词条","word":"質","kana":"たち","pos":"[名]","accent":"①","meaning":"性质；性格，脾气","example":"質をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“性质；性格，脾气”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n質をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“性质；性格，脾气”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1845","seq":1845,"level":"N1","type":"主词条","word":"立ち〜","kana":"たち〜","pos":"[接頭]","accent":"","meaning":"（加强语气）","example":"彼は立ち去る前に深く一礼し、短い挨拶の中にも相手への感謝をきちんと示した。","exampleZh":"他在离开前深深行了一礼，在简短寒暄中也认真表达了对对方的感谢。","note":"例：\n彼は立ち去る前に深く一礼し、短い挨拶の中にも相手への感謝をきちんと示した。\n译：他在离开前深深行了一礼，在简短寒暄中也认真表达了对对方的感谢。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1846","seq":1846,"level":"N1","type":"主词条","word":"立ち会う","kana":"たちあう","pos":"[自動1]","accent":"③⓪","meaning":"见证，在场","example":"立ち会うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“见证，在场”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n立ち会うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“见证，在场”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1847","seq":1847,"level":"N1","type":"主词条","word":"立ち往生","kana":"たちおうじょう","pos":"[名·自動3]","accent":"③","meaning":"进退不得，抛锚","example":"予期せず立ち往生した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“进退不得，抛锚”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず立ち往生した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“进退不得，抛锚”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1848","seq":1848,"level":"N1","type":"主词条","word":"断ち切る","kana":"たちきる","pos":"[他動1]","accent":"③⓪","meaning":"切断，断绝","example":"無理に断ち切ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“切断，断绝”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に断ち切ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“切断，断绝”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1849","seq":1849,"level":"N1","type":"主词条","word":"立ちすくむ","kana":"たちすくむ","pos":"[自動1]","accent":"⓪④","meaning":"（因恐惧等）呆立不动","example":"自分の道を立ちすくむなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“呆立不动”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を立ちすくむなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“呆立不动”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1850","seq":1850,"level":"N1","type":"主词条","word":"立ち退く","kana":"たちのく","pos":"[自動1]","accent":"③⓪","meaning":"离开，搬出","example":"立ち退くとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“离开，搬出”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n立ち退くとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“离开，搬出”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1851","seq":1851,"level":"N1","type":"主词条","word":"断つ","kana":"たつ","pos":"[他動1]","accent":"①","meaning":"断开；戒","example":"悪い習慣を断つには、気合いだけでなく、誘惑に近づかない仕組みを作ることが大切だ。","exampleZh":"要戒掉坏习惯，重要的不只是意志力，还要建立不接近诱惑的机制。","note":"例：\n悪い習慣を断つには、気合いだけでなく、誘惑に近づかない仕組みを作ることが大切だ。\n译：要戒掉坏习惯，重要的不只是意志力，还要建立不接近诱惑的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1852","seq":1852,"level":"N1","type":"主词条","word":"絶つ","kana":"たつ","pos":"[他動1]","accent":"①","meaning":"断绝；结束","example":"絶つ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“断绝；结束”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n絶つ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“断绝；结束”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1853","seq":1853,"level":"N1","type":"主词条","word":"裁つ","kana":"たつ","pos":"[他動1]","accent":"①","meaning":"裁剪","example":"布を裁つ前に、彼女は型紙の向きと縫い代をもう一度慎重に確認した。","exampleZh":"裁剪布料之前，她又一次谨慎确认了纸样方向和缝份。","note":"例：\n布を裁つ前に、彼女は型紙の向きと縫い代をもう一度慎重に確認した。\n译：裁剪布料之前，她又一次谨慎确认了纸样方向和缝份。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1854","seq":1854,"level":"N1","type":"主词条","word":"脱〜","kana":"だつ〜","pos":"[接頭]","accent":"","meaning":"脱离……","example":"脱炭素に向けた取り組みが広がるなか、企業は設備投資だけでなく社員の働き方も見直し始めた。","exampleZh":"在迈向脱碳的行动逐渐扩大的过程中，企业不仅开始重新审视设备投资，也开始重新审视员工的工作方式。","note":"例：\n脱炭素に向けた取り組みが広がるなか、企業は設備投資だけでなく社員の働き方も見直し始めた。\n译：在迈向脱碳的行动逐渐扩大的过程中，企业不仅开始重新审视设备投资，也开始重新审视员工的工作方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1855","seq":1855,"level":"N1","type":"主词条","word":"達者","kana":"たっしゃ","pos":"[名·ナ形]","accent":"⓪","meaning":"精通，熟练；健康","example":"達者な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“精通，熟练；健康”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n達者な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“精通，熟练；健康”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1856","seq":1856,"level":"N1","type":"主词条","word":"脱出","kana":"だっしゅつ","pos":"[名·自動3]","accent":"⓪","meaning":"逃脱，逃出","example":"火災現場から脱出する際には、荷物を取りに戻らず、煙を吸わないよう低い姿勢で移動するべきだ。","exampleZh":"从火灾现场逃生时，不应回头取行李，而应降低姿势移动，避免吸入烟雾。","note":"例：\n火災現場から脱出する際には、荷物を取りに戻らず、煙を吸わないよう低い姿勢で移動するべきだ。\n译：从火灾现场逃生时，不应回头取行李，而应降低姿势移动，避免吸入烟雾。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1857","seq":1857,"level":"N1","type":"主词条","word":"脱する","kana":"だっする","pos":"[自他動3]","accent":"⓪③","meaning":"逃脱；脱离","example":"自分の道を脱するなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“逃脱；脱离”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を脱するなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“逃脱；脱离”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1858","seq":1858,"level":"N1","type":"主词条","word":"脱退","kana":"だったい","pos":"[名·自動3]","accent":"⓪","meaning":"脱离，退出","example":"脱退するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“脱离，退出”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n脱退するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“脱离，退出”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1859","seq":1859,"level":"N1","type":"主词条","word":"立て替える","kana":"たてかえる","pos":"[他動2]","accent":"⓪④③","meaning":"临时垫付","example":"立て替える場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“临时垫付”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n立て替える場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“临时垫付”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1860","seq":1860,"level":"N1","type":"主词条","word":"建前","kana":"たてまえ","pos":"[名]","accent":"②③","meaning":"原则；场面话","example":"建前の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“原则；场面话”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n建前の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“原则；场面话”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1861","seq":1861,"level":"N1","type":"主词条","word":"奉る","kana":"たてまつる","pos":"[他動1]","accent":"④","meaning":"献上；恭维，捧","example":"相手に何かを奉るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“献上；恭维，捧”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを奉るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“献上；恭维，捧”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1862","seq":1862,"level":"N1","type":"主词条","word":"辿り着く","kana":"たどりつく","pos":"[自動1]","accent":"④②","meaning":"好不容易走到，到达目的地","example":"自分の道を辿り着くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“好不容易走到，到达目的地”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を辿り着くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“好不容易走到，到达目的地”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1863","seq":1863,"level":"N1","type":"主词条","word":"辿る","kana":"たどる","pos":"[他動1]","accent":"②⓪","meaning":"沿路前进；追寻；走向","example":"自分の道を辿るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“沿路前进；追寻”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を辿るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“沿路前进；追寻”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1864","seq":1864,"level":"N1","type":"主词条","word":"棚上げ","kana":"たなあげ","pos":"[名·他動3]","accent":"⓪","meaning":"搁置，暂不处理","example":"対立が激しい問題を棚上げにしたままでは、表面上の合意しか得られない。","exampleZh":"若把对立激烈的问题一直搁置，只能获得表面上的一致。","note":"例：\n対立が激しい問題を棚上げにしたままでは、表面上の合意しか得られない。\n译：若把对立激烈的问题一直搁置，只能获得表面上的一致。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1865","seq":1865,"level":"N1","type":"主词条","word":"棚卸し","kana":"たなおろし","pos":"[名·自動3]","accent":"⓪③","meaning":"盘点","example":"棚卸しした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“盘点”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n棚卸しした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“盘点”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1866","seq":1866,"level":"N1","type":"主词条","word":"束ねる","kana":"たばねる","pos":"[他動2]","accent":"③","meaning":"捆，扎，包；管理，整顿","example":"人や情報を束ねる立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“捆，扎，包；管理，整顿”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報を束ねる立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“捆，扎，包；管理，整顿”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1867","seq":1867,"level":"N1","type":"主词条","word":"ダビング","kana":"だびんぐ (dubbing)","pos":"[名·自他動3]","accent":"⓪","meaning":"（电影、广播等）复制，拷贝","example":"古いビデオをダビングしておいたおかげで、貴重な記録を家族で見返すことができた。","exampleZh":"多亏提前复制了旧录像，家人们得以重新观看珍贵记录。","note":"例：\n古いビデオをダビングしておいたおかげで、貴重な記録を家族で見返すことができた。\n译：多亏提前复制了旧录像，家人们得以重新观看珍贵记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1868","seq":1868,"level":"N1","type":"主词条","word":"タブー","kana":"たぶー (taboo)","pos":"[名]","accent":"②①","meaning":"禁忌之物；避讳的事","example":"タブーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“禁忌之物；避讳的事”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nタブーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“禁忌之物；避讳的事”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1869","seq":1869,"level":"N1","type":"主词条","word":"だぶだぶ","kana":"だぶだぶ","pos":"[副·自動3]","accent":"⓪①","meaning":"肥大；满，盈","example":"兄から借りた上着はだぶだぶで、袖を何度も折らないと作業できなかった。","exampleZh":"从哥哥那里借来的上衣肥肥大大，不把袖子折好几次就没法干活。","note":"例：\n兄から借りた上着はだぶだぶで、袖を何度も折らないと作業できなかった。\n译：从哥哥那里借来的上衣肥肥大大，不把袖子折好几次就没法干活。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1870","seq":1870,"level":"N1","type":"主词条","word":"ダブる","kana":"だぶる（double）","pos":"[自動1]","accent":"②","meaning":"重复；双倍","example":"ダブる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“重复；双倍”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\nダブる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“重复；双倍”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1871","seq":1871,"level":"N1","type":"主词条","word":"他方","kana":"たほう","pos":"[名·副]","accent":"②","meaning":"另一方面，其他方面","example":"新制度は利用者の負担を減らす。他方、職員には新しい手続きへの対応が求められる。","exampleZh":"新制度会减少使用者负担。另一方面，职员也需要应对新的手续。","note":"例：\n新制度は利用者の負担を減らす。他方、職員には新しい手続きへの対応が求められる。\n译：新制度会减少使用者负担。另一方面，职员也需要应对新的手续。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1872","seq":1872,"level":"N1","type":"主词条","word":"給う","kana":"たまう","pos":"[他動1]","accent":"②","meaning":"给，赐","example":"給う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“给，赐”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n給う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“给，赐”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1873","seq":1873,"level":"N1","type":"主词条","word":"魂","kana":"たましい","pos":"[名]","accent":"①","meaning":"灵魂","example":"魂の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“灵魂”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n魂の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“灵魂”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1874","seq":1874,"level":"N1","type":"主词条","word":"賜わる","kana":"たまわる","pos":"[他動1]","accent":"③","meaning":"蒙受赏赐；赐予","example":"皆様から温かいご支援を賜わり、今回の企画を無事に実現することができました。","exampleZh":"承蒙各位温暖支持，这次企划得以顺利实现。","note":"例：\n皆様から温かいご支援を賜わり、今回の企画を無事に実現することができました。\n译：承蒙各位温暖支持，这次企划得以顺利实现。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1875","seq":1875,"level":"N1","type":"主词条","word":"たやすい","kana":"たやすい","pos":"[イ形]","accent":"③⓪","meaning":"容易，轻易","example":"たやすい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“容易，轻易”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\nたやすい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“容易，轻易”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1876","seq":1876,"level":"N1","type":"主词条","word":"弛みなく","kana":"たゆみなく","pos":"[副]","accent":"④","meaning":"毫不松懈地","example":"彼女は弛みなく練習を重ね、失敗した箇所を毎回記録して次の改善につなげた。","exampleZh":"她毫不松懈地反复练习，每次都记录失败之处并用于下一步改善。","note":"例：\n彼女は弛みなく練習を重ね、失敗した箇所を毎回記録して次の改善につなげた。\n译：她毫不松懈地反复练习，每次都记录失败之处并用于下一步改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1877","seq":1877,"level":"N1","type":"主词条","word":"弛む","kana":"たゆむ","pos":"[自動1]","accent":"②","meaning":"松弛，松懈","example":"緊張が弛むと小さな確認漏れが増えるため、責任者は作業の終盤ほど声かけを徹底した。","exampleZh":"一旦紧张松懈，小小确认遗漏就会增加，因此负责人越到作业尾声越彻底提醒。","note":"例：\n緊張が弛むと小さな確認漏れが増えるため、責任者は作業の終盤ほど声かけを徹底した。\n译：一旦紧张松懈，小小确认遗漏就会增加，因此负责人越到作业尾声越彻底提醒。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1878","seq":1878,"level":"N1","type":"主词条","word":"多様","kana":"たよう","pos":"[名·ナ形]","accent":"⓪","meaning":"多种多样","example":"多様な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“多种多样”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n多様な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“多种多样”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1879","seq":1879,"level":"N1","type":"主词条","word":"だらしない","kana":"だらしない","pos":"[イ形]","accent":"④","meaning":"散漫的，邋遢的；没规矩的","example":"だらしないと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“散漫的，邋遢的；没规矩的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\nだらしないと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“散漫的，邋遢的；没规矩的”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1880","seq":1880,"level":"N1","type":"主词条","word":"だらだら","kana":"だらだら","pos":"[副]","accent":"①","meaning":"滴滴答答；冗长","example":"会議がだらだら長引くのを避けるため、司会者は議題ごとに終了時刻をあらかじめ決めておいた。","exampleZh":"为了避免会议冗长拖延，主持人事先为每个议题定好了结束时间。","note":"例：\n会議がだらだら長引くのを避けるため、司会者は議題ごとに終了時刻をあらかじめ決めておいた。\n译：为了避免会议冗长拖延，主持人事先为每个议题定好了结束时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1881","seq":1881,"level":"N1","type":"主词条","word":"だるい","kana":"だるい","pos":"[イ形]","accent":"②","meaning":"发倦，慵懒","example":"朝から体がだるく、彼は無理に出勤するよりも早めに休んで回復を優先することにした。","exampleZh":"从早上起身体发倦，他决定与其勉强上班，不如早点休息优先恢复。","note":"例：\n朝から体がだるく、彼は無理に出勤するよりも早めに休んで回復を優先することにした。\n译：从早上起身体发倦，他决定与其勉强上班，不如早点休息优先恢复。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1882","seq":1882,"level":"N1","type":"主词条","word":"弛み","kana":"たるみ","pos":"[名]","accent":"⓪","meaning":"（皮肤等）松弛","example":"医師は弛みの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“松弛”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師は弛みの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“松弛”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1883","seq":1883,"level":"N1","type":"主词条","word":"弛む","kana":"たるむ","pos":"[自動1]","accent":"⓪","meaning":"松弛","example":"緊張が弛むと小さな確認漏れが増えるため、責任者は作業の終盤ほど声かけを徹底した。","exampleZh":"一旦气氛松弛下来，小小确认遗漏就会增加，因此负责人越到作业尾声越彻底提醒。","note":"例：\n緊張が弛むと小さな確認漏れが増えるため、責任者は作業の終盤ほど声かけを徹底した。\n译：一旦气氛松弛下来，小小确认遗漏就会增加，因此负责人越到作业尾声越彻底提醒。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1884","seq":1884,"level":"N1","type":"主词条","word":"タレント","kana":"たれんと (talent)","pos":"[名]","accent":"⓪①","meaning":"演员，表演者，艺人","example":"経験豊かなタレントの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“演员，表演者，艺人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなタレントの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“演员，表演者，艺人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1885","seq":1885,"level":"N1","type":"主词条","word":"〜タワー","kana":"〜たわー (~tower)","pos":"[接尾]","accent":"","meaning":"塔","example":"東京タワーは夜になると美しくライトアップされ、観光客だけでなく仕事帰りの人々も足を止めて眺める。","exampleZh":"东京塔入夜后灯光美丽，不仅游客，连下班路上的人们也会停下脚步观看。","note":"例：\n東京タワーは夜になると美しくライトアップされ、観光客だけでなく仕事帰りの人々も足を止めて眺める。\n译：东京塔入夜后灯光美丽，不仅游客，连下班路上的人们也会停下脚步观看。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1886","seq":1886,"level":"N1","type":"主词条","word":"たわいない","kana":"たわいない","pos":"[イ形]","accent":"④","meaning":"不省人事；一下子就，轻易；不足道","example":"たわいない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“不省人事；一下子就，轻易”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\nたわいない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“不省人事；一下子就，轻易”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1887","seq":1887,"level":"N1","type":"主词条","word":"単一","kana":"たんいつ","pos":"[名·ナ形]","accent":"⓪","meaning":"单一","example":"単一な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“单一”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n単一な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“单一”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1888","seq":1888,"level":"N1","type":"主词条","word":"団塊","kana":"だんかい","pos":"[名]","accent":"⓪","meaning":"块，团","example":"団塊の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“块，团”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n団塊の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“块，团”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1889","seq":1889,"level":"N1","type":"主词条","word":"探究","kana":"たんきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"探求，寻求","example":"真理を探究する姿勢は、すぐ役に立つ成果が見えない時期にも研究者を支えてくれる。","exampleZh":"探求真理的态度，即使在看不见立即成果的时期，也会支撑研究者。","note":"例：\n真理を探究する姿勢は、すぐ役に立つ成果が見えない時期にも研究者を支えてくれる。\n译：探求真理的态度，即使在看不见立即成果的时期，也会支撑研究者。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1890","seq":1890,"level":"N1","type":"主词条","word":"タンク","kana":"たんく (tank)","pos":"[名]","accent":"①","meaning":"坦克；大桶，罐","example":"古い燃料タンクを点検したところ、小さな亀裂が見つかり、事故を防ぐため交換が決まった。","exampleZh":"检查老旧燃料罐时发现了小裂缝，为防止事故决定更换。","note":"例：\n古い燃料タンクを点検したところ、小さな亀裂が見つかり、事故を防ぐため交換が決まった。\n译：检查老旧燃料罐时发现了小裂缝，为防止事故决定更换。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1891","seq":1891,"level":"N1","type":"主词条","word":"団結","kana":"だんけつ","pos":"[名·自動3]","accent":"⓪","meaning":"团结","example":"団結した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“团结”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n団結した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“团结”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1892","seq":1892,"level":"N1","type":"主词条","word":"探検","kana":"たんけん","pos":"[名·他動3]","accent":"⓪","meaning":"探险","example":"彼は探検を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“探险”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は探検を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“探险”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1893","seq":1893,"level":"N1","type":"主词条","word":"断言","kana":"だんげん","pos":"[名·他動3]","accent":"③⓪","meaning":"断言，断定","example":"専門家は、現時点で原因を一つに絞ることはできないと慎重に断言を避けた。","exampleZh":"专家谨慎地避免断言，表示目前还不能把原因限定为一个。","note":"例：\n専門家は、現時点で原因を一つに絞ることはできないと慎重に断言を避けた。\n译：专家谨慎地避免断言，表示目前还不能把原因限定为一个。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1894","seq":1894,"level":"N1","type":"主词条","word":"断固","kana":"だんこ","pos":"[副·ナ形]","accent":"①","meaning":"断然，坚决","example":"彼は不当な要求に対して、断固として応じない姿勢を示した。","exampleZh":"他对不正当要求表现出坚决不接受的态度。","note":"例：\n彼は不当な要求に対して、断固として応じない姿勢を示した。\n译：他对不正当要求表现出坚决不接受的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1895","seq":1895,"level":"N1","type":"主词条","word":"断行","kana":"だんこう","pos":"[名·他動3]","accent":"⓪","meaning":"断然实行","example":"断行する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“断然实行”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n断行する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“断然实行”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1896","seq":1896,"level":"N1","type":"主词条","word":"断然","kana":"だんぜん","pos":"[副]","accent":"⓪","meaning":"断然；决（不）","example":"同じ条件で比べると、今回の案のほうが断然分かりやすく、利用者からの反応も良かった。","exampleZh":"在相同条件下比较，这次方案明显更易懂，使用者反应也更好。","note":"例：\n同じ条件で比べると、今回の案のほうが断然分かりやすく、利用者からの反応も良かった。\n译：在相同条件下比较，这次方案明显更易懂，使用者反应也更好。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1897","seq":1897,"level":"N1","type":"主词条","word":"探知","kana":"たんち","pos":"[名·他動3]","accent":"①","meaning":"探知，探查","example":"探知した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“探知，探查”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n探知した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“探知，探查”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1898","seq":1898,"level":"N1","type":"主词条","word":"探偵","kana":"たんてい","pos":"[名·他動3]","accent":"⓪","meaning":"侦探，侦查","example":"初めて探偵する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“侦探，侦查”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて探偵する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“侦探，侦查”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1899","seq":1899,"level":"N1","type":"主词条","word":"端的","kana":"たんてき","pos":"[ナ形]","accent":"⓪","meaning":"直截了当；明显","example":"周囲から端的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“直截了当；明显”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から端的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“直截了当；明显”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1900","seq":1900,"level":"N1","type":"主词条","word":"単独","kana":"たんどく","pos":"[名·ナ形]","accent":"⓪","meaning":"单独，独自","example":"単独な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“单独，独自”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n単独な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“单独，独自”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1901","seq":1901,"level":"N1","type":"主词条","word":"段取り","kana":"だんどり","pos":"[名]","accent":"④③⓪","meaning":"计划，安排；流程，顺序","example":"段取りを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“计划，安排；流程，顺序”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n段取りを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“计划，安排；流程，顺序”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1902","seq":1902,"level":"N1","type":"主词条","word":"丹念","kana":"たんねん","pos":"[名·ナ形]","accent":"①","meaning":"精心，细心","example":"丹念な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“精心，细心”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n丹念な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“精心，细心”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1903","seq":1903,"level":"N1","type":"主词条","word":"断念","kana":"だんねん","pos":"[名·他動3]","accent":"③","meaning":"死心，放弃","example":"断念する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“死心，放弃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n断念する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“死心，放弃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1904","seq":1904,"level":"N1","type":"主词条","word":"堪能","kana":"たんのう","pos":"[名·ナ形·他動3]","accent":"⓪","meaning":"熟练，擅长；十分满足","example":"チームは堪能する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“熟练，擅长；十分满足”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは堪能する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“熟练，擅长；十分满足”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1905","seq":1905,"level":"N1","type":"主词条","word":"短波","kana":"たんぱ","pos":"[名]","accent":"①","meaning":"短波","example":"短波放送は音質が安定しないこともあるが、遠く離れた地域へ情報を届ける手段として今も使われている。","exampleZh":"短波广播有时音质不稳定，但作为向远方地区传递信息的手段，如今仍在使用。","note":"例：\n短波放送は音質が安定しないこともあるが、遠く離れた地域へ情報を届ける手段として今も使われている。\n译：短波广播有时音质不稳定，但作为向远方地区传递信息的手段，如今仍在使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1906","seq":1906,"level":"N1","type":"主词条","word":"淡白","kana":"たんぱく","pos":"[名·ナ形]","accent":"①","meaning":"淡；淡泊","example":"一度淡白だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“淡；淡泊”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度淡白だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“淡；淡泊”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1907","seq":1907,"level":"N1","type":"主词条","word":"蛋白質","kana":"たんぱくしつ","pos":"[名]","accent":"④③","meaning":"蛋白质","example":"蛋白質の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“蛋白质”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n蛋白質の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“蛋白质”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1908","seq":1908,"level":"N1","type":"主词条","word":"断面","kana":"だんめん","pos":"[名]","accent":"③⓪","meaning":"断面，截面","example":"木材の断面をよく見ると、年輪の幅からその年の気候まで読み取ることができる。","exampleZh":"仔细观察木材截面，就能从年轮宽度读出那一年的气候。","note":"例：\n木材の断面をよく見ると、年輪の幅からその年の気候まで読み取ることができる。\n译：仔细观察木材截面，就能从年轮宽度读出那一年的气候。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1909","seq":1909,"level":"N1","type":"主词条","word":"知育","kana":"ちいく","pos":"[名]","accent":"①","meaning":"智育","example":"知育が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“智育”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n知育が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“智育”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1910","seq":1910,"level":"N1","type":"主词条","word":"チープ","kana":"ちーぷ (cheap)","pos":"[ナ形]","accent":"①","meaning":"廉价，便宜的","example":"一度チープだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“廉价，便宜的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度チープだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“廉价，便宜的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1911","seq":1911,"level":"N1","type":"主词条","word":"チームワーク","kana":"ちーむわーく (teamwork)","pos":"[名]","accent":"④","meaning":"团队合作","example":"チームワークを大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。","exampleZh":"如果重视“团队合作”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","note":"例：\nチームワークを大切にするなら、親しい相手ほど曖昧な約束にせず、期待と役割を言葉で確かめる必要がある。\n译：如果重视“团队合作”，越是亲近的人越不应订下含糊约定，而要用语言确认期待和角色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1912","seq":1912,"level":"N1","type":"主词条","word":"チェーン","kana":"ちぇーん (chain)","pos":"[名]","accent":"①","meaning":"链子，链条；连锁","example":"チェーンが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“链子，链条；连锁”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nチェーンが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“链子，链条；连锁”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1913","seq":1913,"level":"N1","type":"主词条","word":"遅延","kana":"ちえん","pos":"[名·自動3]","accent":"⓪","meaning":"延迟，误点","example":"遅延するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“延迟，误点”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n遅延するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“延迟，误点”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1914","seq":1914,"level":"N1","type":"主词条","word":"チェンジ","kana":"ちぇんじ (change)","pos":"[名·自他動3]","accent":"①","meaning":"改变，变换；交换，兑换","example":"彼はチェンジを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“改变，变换；交换，兑换”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼はチェンジを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“改变，变换；交换，兑换”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1915","seq":1915,"level":"N1","type":"主词条","word":"蓄積","kana":"ちくせき","pos":"[名·自他動3]","accent":"⓪","meaning":"积蓄，积累","example":"蓄積の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“积蓄，积累”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n蓄積の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“积蓄，积累”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1916","seq":1916,"level":"N1","type":"主词条","word":"知性","kana":"ちせい","pos":"[名]","accent":"①②","meaning":"知性，才智，理智","example":"知性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“知性，才智，理智”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n知性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“知性，才智，理智”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1917","seq":1917,"level":"N1","type":"主词条","word":"窒息","kana":"ちっそく","pos":"[名·自動3]","accent":"⓪","meaning":"窒息","example":"窒息する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“窒息”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n窒息する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“窒息”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1918","seq":1918,"level":"N1","type":"主词条","word":"ちっぽけ","kana":"ちっぽけ","pos":"[ナ形]","accent":"③","meaning":"特小，极小","example":"ちっぽけな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“特小，极小”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nちっぽけな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“特小，极小”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1919","seq":1919,"level":"N1","type":"主词条","word":"知的","kana":"ちてき","pos":"[ナ形]","accent":"⓪","meaning":"智慧的，理智的","example":"周囲から知的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“智慧的，理智的”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から知的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“智慧的，理智的”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1920","seq":1920,"level":"N1","type":"主词条","word":"ちなみに","kana":"ちなみに","pos":"[接]","accent":"⓪⓪①","meaning":"顺便，附带","example":"ちなみに、明日の説明会は午後三時からではなく、二時半からに変更されています。","exampleZh":"顺便说一下，明天的说明会不是下午三点开始，而是改为两点半开始。","note":"例：\nちなみに、明日の説明会は午後三時からではなく、二時半からに変更されています。\n译：顺便说一下，明天的说明会不是下午三点开始，而是改为两点半开始。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1921","seq":1921,"level":"N1","type":"主词条","word":"チャージ","kana":"ちゃーじ (charge)","pos":"[名]","accent":"①","meaning":"收费，索价；充电","example":"チャージをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“收费，索价；充电”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nチャージをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“收费，索价；充电”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1922","seq":1922,"level":"N1","type":"主词条","word":"チャーハン","kana":"ちゃーはん","pos":"[名]","accent":"①","meaning":"炒饭","example":"店主はチャーハンの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“炒饭”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主はチャーハンの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“炒饭”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1923","seq":1923,"level":"N1","type":"主词条","word":"チャーミング","kana":"ちゃーみんぐ (charming)","pos":"[ナ形]","accent":"①","meaning":"有魅力，迷人","example":"チャーミングな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“有魅力，迷人”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nチャーミングな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“有魅力，迷人”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1924","seq":1924,"level":"N1","type":"主词条","word":"着手","kana":"ちゃくしゅ","pos":"[名·自動3]","accent":"①⓪","meaning":"着手，开始","example":"予期せず着手した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“着手，开始”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず着手した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“着手，开始”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1925","seq":1925,"level":"N1","type":"主词条","word":"着色","kana":"ちゃくしょく","pos":"[名·自動3]","accent":"⓪","meaning":"着色，上颜色","example":"着色してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“着色，上颜色”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n着色してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“着色，上颜色”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1926","seq":1926,"level":"N1","type":"主词条","word":"着席","kana":"ちゃくせき","pos":"[名·自動3]","accent":"⓪","meaning":"就座，入座","example":"全員が着席してから、司会者は会議の目的と本日の流れを簡潔に確認した。","exampleZh":"全员就座后，主持人简要确认了会议目的和当天流程。","note":"例：\n全員が着席してから、司会者は会議の目的と本日の流れを簡潔に確認した。\n译：全员就座后，主持人简要确认了会议目的和当天流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1927","seq":1927,"level":"N1","type":"主词条","word":"着目","kana":"ちゃくもく","pos":"[名·自動3]","accent":"⓪","meaning":"着眼，注目","example":"着目する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“着眼，注目”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n着目する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“着眼，注目”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1928","seq":1928,"level":"N1","type":"主词条","word":"着陸","kana":"ちゃくりく","pos":"[名·自動3]","accent":"⓪","meaning":"着陆","example":"着陸するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“着陆”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n着陸するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“着陆”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1929","seq":1929,"level":"N1","type":"主词条","word":"着工","kana":"ちゃっこう","pos":"[名·自動3]","accent":"⓪","meaning":"开工，动工","example":"予期せず着工した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“开工，动工”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず着工した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“开工，动工”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1930","seq":1930,"level":"N1","type":"主词条","word":"チャット","kana":"ちゃっと（chat）","pos":"[名·自動3]","accent":"①","meaning":"闲谈，聊天","example":"チャットする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“闲谈，聊天”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\nチャットする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“闲谈，聊天”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1931","seq":1931,"level":"N1","type":"主词条","word":"茶の湯","kana":"ちゃのゆ","pos":"[名]","accent":"⓪","meaning":"茶道，品茶会","example":"茶の湯を選ぶとき、彼女は値段の安さだけでなく、材料の産地や保存方法も確かめるようにしている。","exampleZh":"选择茶道用品时，她不仅看价格是否便宜，也会确认材料产地和保存方法。","note":"例：\n茶の湯を選ぶとき、彼女は値段の安さだけでなく、材料の産地や保存方法も確かめるようにしている。\n译：选择茶道用品时，她不仅看价格是否便宜，也会确认材料产地和保存方法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1932","seq":1932,"level":"N1","type":"主词条","word":"ちやほや","kana":"ちやほや","pos":"[副·他動3]","accent":"①","meaning":"捧，奉承；宠爱，溺爱","example":"幼いころから周囲にちやほやされて育つと、批判を受け止める力が育ちにくいこともある。","exampleZh":"如果从小在周围人的宠爱和奉承中长大，有时会难以培养接受批评的能力。","note":"例：\n幼いころから周囲にちやほやされて育つと、批判を受け止める力が育ちにくいこともある。\n译：如果从小在周围人的宠爱和奉承中长大，有时会难以培养接受批评的能力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1933","seq":1933,"level":"N1","type":"主词条","word":"宙返り","kana":"ちゅうがえり","pos":"[名·自動3]","accent":"③","meaning":"翻筋斗，空手翻","example":"予期せず宙返りした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“翻筋斗，空手翻”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず宙返りした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“翻筋斗，空手翻”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1934","seq":1934,"level":"N1","type":"主词条","word":"中期","kana":"ちゅうき","pos":"[名]","accent":"①","meaning":"中期","example":"中期をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“中期”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n中期をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“中期”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1935","seq":1935,"level":"N1","type":"主词条","word":"中継","kana":"ちゅうけい","pos":"[名·他動3]","accent":"⓪","meaning":"转播","example":"災害現場からの中継では、迫力ある映像よりも被害者の安全と個人情報への配慮が優先される。","exampleZh":"灾害现场转播中，比起有冲击力的影像，更优先的是顾及受害者安全和个人信息。","note":"例：\n災害現場からの中継では、迫力ある映像よりも被害者の安全と個人情報への配慮が優先される。\n译：灾害现场转播中，比起有冲击力的影像，更优先的是顾及受害者安全和个人信息。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1936","seq":1936,"level":"N1","type":"主词条","word":"忠実","kana":"ちゅうじつ","pos":"[名·ナ形]","accent":"⓪","meaning":"忠诚，忠实","example":"一度忠実だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“忠诚，忠实”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度忠実だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“忠诚，忠实”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1937","seq":1937,"level":"N1","type":"主词条","word":"中傷","kana":"ちゅうしょう","pos":"[名·他動3]","accent":"⓪","meaning":"中伤","example":"中傷した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“中伤”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n中傷した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“中伤”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1938","seq":1938,"level":"N1","type":"主词条","word":"中枢","kana":"ちゅうすう","pos":"[名]","accent":"⓪","meaning":"枢纽，关键","example":"中枢が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“枢纽，关键”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n中枢が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“枢纽，关键”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1939","seq":1939,"level":"N1","type":"主词条","word":"抽選","kana":"ちゅうせん","pos":"[名·自動3]","accent":"⓪","meaning":"抽签","example":"予期せず抽選した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“抽签”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず抽選した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“抽签”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1940","seq":1940,"level":"N1","type":"主词条","word":"中断","kana":"ちゅうだん","pos":"[名·自他動3]","accent":"⓪","meaning":"中断，断开","example":"彼は中断を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“中断，断开”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は中断を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“中断，断开”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1941","seq":1941,"level":"N1","type":"主词条","word":"チューブ","kana":"ちゅーぶ（tube）","pos":"[名]","accent":"①","meaning":"管状物，软管，吸管","example":"チューブを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“管状物，软管，吸管”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nチューブを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“管状物，软管，吸管”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1942","seq":1942,"level":"N1","type":"主词条","word":"中腹","kana":"ちゅうふく","pos":"[名]","accent":"⓪","meaning":"半山腰","example":"山の中腹まで登ると急に霧が濃くなり、登山隊は無理をせず予定より早く引き返した。","exampleZh":"爬到山腰时雾突然变浓，登山队没有勉强，提前折返。","note":"例：\n山の中腹まで登ると急に霧が濃くなり、登山隊は無理をせず予定より早く引き返した。\n译：爬到山腰时雾突然变浓，登山队没有勉强，提前折返。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1943","seq":1943,"level":"N1","type":"主词条","word":"中立","kana":"ちゅうりつ","pos":"[名·自動3]","accent":"⓪","meaning":"中立","example":"中立するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“中立”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n中立するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“中立”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1944","seq":1944,"level":"N1","type":"主词条","word":"ちょいちょい","kana":"ちょいちょい","pos":"[副]","accent":"①","meaning":"有时，时常","example":"彼は出張の合間にちょいちょい店へ顔を出し、店主から地域の変化を聞いている。","exampleZh":"他在出差间隙经常到店里露面，向店主了解地区变化。","note":"例：\n彼は出張の合間にちょいちょい店へ顔を出し、店主から地域の変化を聞いている。\n译：他在出差间隙经常到店里露面，向店主了解地区变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1945","seq":1945,"level":"N1","type":"主词条","word":"調印","kana":"ちょういん","pos":"[名·自動3]","accent":"⓪","meaning":"盖印，签字","example":"調印してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“盖印，签字”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n調印してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“盖印，签字”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1946","seq":1946,"level":"N1","type":"主词条","word":"懲役","kana":"ちょうえき","pos":"[名]","accent":"⓪","meaning":"徒刑","example":"経験豊かな懲役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“徒刑”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな懲役の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“徒刑”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1947","seq":1947,"level":"N1","type":"主词条","word":"徴収","kana":"ちょうしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"收取（手续费，会费等）；征收","example":"徴収の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“收取；征收”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n徴収の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“收取；征收”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1948","seq":1948,"level":"N1","type":"主词条","word":"聴診器","kana":"ちょうしんき","pos":"[名]","accent":"③","meaning":"听诊器","example":"聴診器に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。","exampleZh":"他感到“听诊器”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","note":"例：\n聴診器に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。\n译：他感到“听诊器”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1949","seq":1949,"level":"N1","type":"主词条","word":"調達","kana":"ちょうたつ","pos":"[名·他動3]","accent":"⓪","meaning":"筹措，筹备","example":"必要な部品を調達するため、購買部は国内外の取引先に在庫を確認した。","exampleZh":"为筹措必要零部件，采购部向国内外客户确认了库存。","note":"例：\n必要な部品を調達するため、購買部は国内外の取引先に在庫を確認した。\n译：为筹措必要零部件，采购部向国内外客户确认了库存。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1950","seq":1950,"level":"N1","type":"主词条","word":"調停","kana":"ちょうてい","pos":"[名·他動3]","accent":"⓪","meaning":"调停，调解","example":"調停する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“调停，调解”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n調停する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“调停，调解”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1951","seq":1951,"level":"N1","type":"主词条","word":"長編","kana":"ちょうへん","pos":"[名]","accent":"⓪","meaning":"长篇","example":"長編をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“长篇”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n長編をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“长篇”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1952","seq":1952,"level":"N1","type":"主词条","word":"重宝","kana":"ちょうほう","pos":"[名·ナ形·他動3]","accent":"①","meaning":"方便；珍视，爱惜","example":"チームは重宝する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“方便；珍视，爱惜”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは重宝する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“方便；珍视，爱惜”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1953","seq":1953,"level":"N1","type":"主词条","word":"調理","kana":"ちょうり","pos":"[名·他動3]","accent":"①","meaning":"烹饪，做菜","example":"大量の食材を調理する前に、彼女は火の通り方と提供時間を計算し、作業の順番を細かく決めた。","exampleZh":"在烹饪大量食材前，她计算了熟成时间和上菜时间，细致决定作业顺序。","note":"例：\n大量の食材を調理する前に、彼女は火の通り方と提供時間を計算し、作業の順番を細かく決めた。\n译：在烹饪大量食材前，她计算了熟成时间和上菜时间，细致决定作业顺序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1954","seq":1954,"level":"N1","type":"主词条","word":"調和","kana":"ちょうわ","pos":"[名·自動3]","accent":"⓪","meaning":"协调，和谐","example":"個人の自由と組織全体の調和を保つには、規則を押しつけるだけでなく対話の余地を残す必要がある。","exampleZh":"要保持个人自由与组织整体的协调，不能只强加规则，也要留下对话余地。","note":"例：\n個人の自由と組織全体の調和を保つには、規則を押しつけるだけでなく対話の余地を残す必要がある。\n译：要保持个人自由与组织整体的协调，不能只强加规则，也要留下对话余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1955","seq":1955,"level":"N1","type":"主词条","word":"ちょくちょく","kana":"ちょくちょく","pos":"[副]","accent":"①","meaning":"经常，时常","example":"彼女はちょくちょく図書館に通い、論文に使えそうな資料を少しずつ集めている。","exampleZh":"她经常去图书馆，一点点收集可以用于论文的资料。","note":"例：\n彼女はちょくちょく図書館に通い、論文に使えそうな資料を少しずつ集めている。\n译：她经常去图书馆，一点点收集可以用于论文的资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1956","seq":1956,"level":"N1","type":"主词条","word":"直面","kana":"ちょくめん","pos":"[名·自動3]","accent":"⓪","meaning":"面对，直面","example":"直面した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“面对，直面”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n直面した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“面对，直面”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1957","seq":1957,"level":"N1","type":"主词条","word":"ちょこちょこ","kana":"ちょこちょこ","pos":"[副]","accent":"①","meaning":"迈小步走；慌慌张张；常常","example":"子どもが店内をちょこちょこ歩き回るので、店員は熱い飲み物を運ぶとき特に注意していた。","exampleZh":"孩子在店内来回小步走动，店员端热饮时格外注意。","note":"例：\n子どもが店内をちょこちょこ歩き回るので、店員は熱い飲み物を運ぶとき特に注意していた。\n译：孩子在店内来回小步走动，店员端热饮时格外注意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1958","seq":1958,"level":"N1","type":"主词条","word":"著書","kana":"ちょしょ","pos":"[名]","accent":"①","meaning":"著作","example":"著書の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“著作”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n著書の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“著作”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1959","seq":1959,"level":"N1","type":"主词条","word":"貯蓄","kana":"ちょちく","pos":"[名·他動3]","accent":"⓪","meaning":"储存，积蓄","example":"貯蓄する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“储存，积蓄”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n貯蓄する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“储存，积蓄”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1960","seq":1960,"level":"N1","type":"主词条","word":"直感","kana":"ちょっかん","pos":"[名·他動3]","accent":"⓪","meaning":"直觉","example":"チームは直感する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“直觉”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは直感する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“直觉”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1961","seq":1961,"level":"N1","type":"主词条","word":"著名","kana":"ちょめい","pos":"[名·ナ形]","accent":"⓪","meaning":"著名","example":"著名な研究者の意見であっても、根拠を確認せずに受け入れるのは危険だ。","exampleZh":"即使是著名研究者的意见，不确认依据就接受也很危险。","note":"例：\n著名な研究者の意見であっても、根拠を確認せずに受け入れるのは危険だ。\n译：即使是著名研究者的意见，不确认依据就接受也很危险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1962","seq":1962,"level":"N1","type":"主词条","word":"ちらちら","kana":"ちらちら","pos":"[副·自動3]","accent":"①","meaning":"时隐时现；（无意间）听到","example":"窓の外では雪がちらちら降り始め、駅前の街灯の光に白く浮かんでいた。","exampleZh":"窗外开始飘起零星雪花，在车站前路灯的光中泛着白色。","note":"例：\n窓の外では雪がちらちら降り始め、駅前の街灯の光に白く浮かんでいた。\n译：窗外开始飘起零星雪花，在车站前路灯的光中泛着白色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1963","seq":1963,"level":"N1","type":"主词条","word":"ちらっと","kana":"ちらっと","pos":"[副]","accent":"②","meaning":"一晃；偶尔，稍微","example":"廊下ですれ違ったとき彼がちらっとこちらを見たので、彼女は何か言いたいことがあるのだと感じた。","exampleZh":"走廊擦肩而过时，他稍微看了这边一眼，她觉得他可能有话想说。","note":"例：\n廊下ですれ違ったとき彼がちらっとこちらを見たので、彼女は何か言いたいことがあるのだと感じた。\n译：走廊擦肩而过时，他稍微看了这边一眼，她觉得他可能有话想说。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1964","seq":1964,"level":"N1","type":"主词条","word":"塵取り","kana":"ちりとり","pos":"[名]","accent":"③④","meaning":"簸箕","example":"塵取りに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“簸箕”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n塵取りに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“簸箕”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1965","seq":1965,"level":"N1","type":"主词条","word":"賃上げ","kana":"ちんあげ","pos":"[名·自動3]","accent":"⓪","meaning":"加薪","example":"賃上げした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“加薪”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n賃上げした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“加薪”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1966","seq":1966,"level":"N1","type":"主词条","word":"賃下げ","kana":"ちんさげ","pos":"[名·自動3]","accent":"⓪","meaning":"降薪","example":"一方的な賃下げは従業員の不安を招くため、経営側は理由と今後の見通しを具体的に示す必要がある。","exampleZh":"单方面降薪会招致员工不安，因此经营方需要具体说明理由和今后展望。","note":"例：\n一方的な賃下げは従業員の不安を招くため、経営側は理由と今後の見通しを具体的に示す必要がある。\n译：单方面降薪会招致员工不安，因此经营方需要具体说明理由和今后展望。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1967","seq":1967,"level":"N1","type":"主词条","word":"賃貸","kana":"ちんたい","pos":"[名·他動3]","accent":"⓪","meaning":"出租","example":"賃貸する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“出租”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n賃貸する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“出租”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1968","seq":1968,"level":"N1","type":"主词条","word":"チンパンジー","kana":"ちんぱんじー（chimpanzee）","pos":"[名]","accent":"③","meaning":"黑猩猩","example":"チンパンジーの行動を観察すると、人間に近い知性だけでなく、群れの中の複雑な関係も見えてくる。","exampleZh":"观察黑猩猩行为时，不仅能看到接近人类的智慧，也能看到群体内部复杂关系。","note":"例：\nチンパンジーの行動を観察すると、人間に近い知性だけでなく、群れの中の複雑な関係も見えてくる。\n译：观察黑猩猩行为时，不仅能看到接近人类的智慧，也能看到群体内部复杂关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1969","seq":1969,"level":"N1","type":"主词条","word":"沈没","kana":"ちんぼつ","pos":"[名·自動3]","accent":"⓪","meaning":"沉没；烂醉","example":"予期せず沈没した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“沉没；烂醉”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず沈没した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“沉没；烂醉”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1970","seq":1970,"level":"N1","type":"主词条","word":"沈黙","kana":"ちんもく","pos":"[名·自動3]","accent":"⓪","meaning":"沉默","example":"沈黙してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“沉默”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n沈黙してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“沉默”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1971","seq":1971,"level":"N1","type":"主词条","word":"陳列","kana":"ちんれつ","pos":"[名·他動3]","accent":"⓪","meaning":"陈列，展览","example":"陳列の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“陈列，展览”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n陳列の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“陈列，展览”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1972","seq":1972,"level":"N1","type":"主词条","word":"追及","kana":"ついきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"追究，追查","example":"彼は追及を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“追究，追查”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は追及を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“追究，追查”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1973","seq":1973,"level":"N1","type":"主词条","word":"追究","kana":"ついきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"追求，弄清","example":"事故の責任を追究するだけでなく、同じ失敗を防ぐ仕組みを作ることが重要だ。","exampleZh":"不仅要追究事故责任，更重要的是建立防止同样失败的机制。","note":"例：\n事故の責任を追究するだけでなく、同じ失敗を防ぐ仕組みを作ることが重要だ。\n译：不仅要追究事故责任，更重要的是建立防止同样失败的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1974","seq":1974,"level":"N1","type":"主词条","word":"追跡","kana":"ついせき","pos":"[名·他動3]","accent":"⓪","meaning":"追缉，追拿","example":"追跡する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“追缉，追拿”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n追跡する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“追缉，追拿”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1975","seq":1975,"level":"N1","type":"主词条","word":"追放","kana":"ついほう","pos":"[名·他動3]","accent":"⓪","meaning":"驱逐；开除","example":"追放する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“驱逐；开除”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n追放する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“驱逐；开除”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1976","seq":1976,"level":"N1","type":"主词条","word":"墜落","kana":"ついらく","pos":"[名·自動3]","accent":"⓪","meaning":"坠落，掉下","example":"墜落した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“坠落，掉下”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n墜落した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“坠落，掉下”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1977","seq":1977,"level":"N1","type":"主词条","word":"痛感","kana":"つうかん","pos":"[名·他動3]","accent":"⓪","meaning":"深感，深切认识","example":"痛感した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“深感，深切认识”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n痛感した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“深感，深切认识”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1978","seq":1978,"level":"N1","type":"主词条","word":"痛切","kana":"つうせつ","pos":"[名·ナ形]","accent":"⓪","meaning":"痛切，深切","example":"痛切な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“痛切，深切”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n痛切な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“痛切，深切”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1979","seq":1979,"level":"N1","type":"主词条","word":"通達","kana":"つうたつ","pos":"[名·自他動3]","accent":"⓪","meaning":"通达，精通；通告","example":"本社から新しい規則が通達され、各支店は翌日までに従業員へ周知することになった。","exampleZh":"总公司通告了新规定，各分店需在第二天前向员工周知。","note":"例：\n本社から新しい規則が通達され、各支店は翌日までに従業員へ周知することになった。\n译：总公司通告了新规定，各分店需在第二天前向员工周知。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1980","seq":1980,"level":"N1","type":"主词条","word":"通念","kana":"つうねん","pos":"[名]","accent":"①","meaning":"一般想法，普通想法","example":"通念を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“一般想法，普通想法”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\n通念を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“一般想法，普通想法”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1981","seq":1981,"level":"N1","type":"主词条","word":"通報","kana":"つうほう","pos":"[名·他動3]","accent":"⓪","meaning":"通报，通知","example":"不審な物音に気づいた住民が警察へ通報し、大きな被害を未然に防いだ。","exampleZh":"注意到可疑声响的居民向警方通报，防止了更大损失。","note":"例：\n不審な物音に気づいた住民が警察へ通報し、大きな被害を未然に防いだ。\n译：注意到可疑声响的居民向警方通报，防止了更大损失。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1982","seq":1982,"level":"N1","type":"主词条","word":"ツール","kana":"つーる（tool）","pos":"[名]","accent":"①","meaning":"工具","example":"修繕計画ではツールの費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。","exampleZh":"修缮计划不仅考虑了“工具”的费用，也考虑了施工期间对周边居民的影响。","note":"例：\n修繕計画ではツールの費用だけでなく、工事中に周辺住民へ及ぶ影響も考慮された。\n译：修缮计划不仅考虑了“工具”的费用，也考虑了施工期间对周边居民的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1983","seq":1983,"level":"N1","type":"主词条","word":"使いこなす","kana":"つかいこなす","pos":"[他動1]","accent":"⑤","meaning":"熟练掌握，运用自如","example":"相手に何かを使いこなすなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“熟练掌握，运用自如”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを使いこなすなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“熟练掌握，运用自如”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1984","seq":1984,"level":"N1","type":"主词条","word":"支える","kana":"つかえる","pos":"[自動2]","accent":"③②","meaning":"卡，堵塞；阻碍，阻挡","example":"支える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“卡，堵塞；阻碍，阻挡”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n支える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“卡，堵塞；阻碍，阻挡”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1985","seq":1985,"level":"N1","type":"主词条","word":"仕える","kana":"つかえる","pos":"[自動2]","accent":"③⓪","meaning":"服侍，伺候；任职","example":"仕えるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“服侍，伺候；任职”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n仕えるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“服侍，伺候；任职”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1986","seq":1986,"level":"N1","type":"主词条","word":"司る/掌る","kana":"つかさどる","pos":"[他動1]","accent":"④","meaning":"承担，掌管；管理","example":"人や情報を司る立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“承担，掌管；管理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報を司る立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“承担，掌管；管理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1987","seq":1987,"level":"N1","type":"主词条","word":"束の間","kana":"つかのま","pos":"[名]","accent":"⓪","meaning":"短暂","example":"束の間を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“短暂”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n束の間を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“短暂”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1988","seq":1988,"level":"N1","type":"主词条","word":"付き添う","kana":"つきそう","pos":"[自動1]","accent":"③⓪","meaning":"跟随左右，陪伴照顾","example":"付き添うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“跟随左右，陪伴照顾”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n付き添うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“跟随左右，陪伴照顾”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1989","seq":1989,"level":"N1","type":"主词条","word":"突き出す","kana":"つきだす","pos":"[他動1]","accent":"③","meaning":"推出去；强行送往","example":"無理に突き出すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“推出去；强行送往”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に突き出すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“推出去；强行送往”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1990","seq":1990,"level":"N1","type":"主词条","word":"月並み","kana":"つきなみ","pos":"[名·ナ形]","accent":"⓪","meaning":"每月例行；司空见惯","example":"一度月並みだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“每月例行；司空见惯”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度月並みだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“每月例行；司空见惯”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1991","seq":1991,"level":"N1","type":"主词条","word":"付き纏う","kana":"つきまとう","pos":"[自動1]","accent":"④⓪","meaning":"纠缠，甩不掉","example":"成功してからも過去の失敗の記憶が付き纏うため、彼は結果よりも過程を丁寧に振り返るようにしている。","exampleZh":"即使成功以后，过去失败的记忆仍纠缠不去，所以他更注意细致回顾过程而非只看结果。","note":"例：\n成功してからも過去の失敗の記憶が付き纏うため、彼は結果よりも過程を丁寧に振り返るようにしている。\n译：即使成功以后，过去失败的记忆仍纠缠不去，所以他更注意细致回顾过程而非只看结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1992","seq":1992,"level":"N1","type":"主词条","word":"継ぎ目","kana":"つぎめ","pos":"[名]","accent":"⓪","meaning":"接口，焊口","example":"継ぎ目が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“接口，焊口”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n継ぎ目が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“接口，焊口”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1993","seq":1993,"level":"N1","type":"主词条","word":"接ぐ","kana":"つぐ","pos":"[他動1]","accent":"⓪","meaning":"接上，连接","example":"接ぐ前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“接上，连接”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n接ぐ前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“接上，连接”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1994","seq":1994,"level":"N1","type":"主词条","word":"継ぐ","kana":"つぐ","pos":"[他動1]","accent":"⓪","meaning":"接合，接上；补足；继承","example":"家業を継ぐと決めた彼は、昔からの客を大切にしながら、若い世代向けの商品も少しずつ増やした。","exampleZh":"决定继承家业的他，一边珍惜老顾客，一边逐渐增加面向年轻一代的商品。","note":"例：\n家業を継ぐと決めた彼は、昔からの客を大切にしながら、若い世代向けの商品も少しずつ増やした。\n译：决定继承家业的他，一边珍惜老顾客，一边逐渐增加面向年轻一代的商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1995","seq":1995,"level":"N1","type":"主词条","word":"～尽くす","kana":"～つくす","pos":"[接尾]","accent":"","meaning":"……尽，完","example":"彼は全力を出し尽くしたあと、結果を待つ間も仲間への感謝を忘れずに伝えた。","exampleZh":"他倾尽全力之后，即使在等待结果期间，也不忘向伙伴表达感谢。","note":"例：\n彼は全力を出し尽くしたあと、結果を待つ間も仲間への感謝を忘れずに伝えた。\n译：他倾尽全力之后，即使在等待结果期间，也不忘向伙伴表达感谢。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1996","seq":1996,"level":"N1","type":"主词条","word":"つくづく","kana":"つくづく","pos":"[副]","accent":"③②","meaning":"痛切，深切","example":"予想外の事故に対応してみて、日頃から準備しておくことの大切さをつくづく実感した。","exampleZh":"应对意外事故后，他深切体会到平时做好准备的重要性。","note":"例：\n予想外の事故に対応してみて、日頃から準備しておくことの大切さをつくづく実感した。\n译：应对意外事故后，他深切体会到平时做好准备的重要性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1997","seq":1997,"level":"N1","type":"主词条","word":"償い","kana":"つぐない","pos":"[名]","accent":"⓪③","meaning":"补偿，抵偿","example":"償いを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“补偿，抵偿”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n償いを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“补偿，抵偿”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1998","seq":1998,"level":"N1","type":"主词条","word":"繕う","kana":"つくろう","pos":"[他動1]","accent":"③","meaning":"修理，修补；修饰；应付，敷衍","example":"繕う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“修理，修补；修饰”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n繕う前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“修理，修补；修饰”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-1999","seq":1999,"level":"N1","type":"主词条","word":"付け","kana":"つけ","pos":"[名]","accent":"②","meaning":"单据，账单，赊账","example":"行きつけの店で付けを重ねる前に、彼は自分の収入と支出を見直すべきだった。","exampleZh":"在常去的店里继续赊账之前，他本该重新审视自己的收入和支出。","note":"例：\n行きつけの店で付けを重ねる前に、彼は自分の収入と支出を見直すべきだった。\n译：在常去的店里继续赊账之前，他本该重新审视自己的收入和支出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2000","seq":2000,"level":"N1","type":"主词条","word":"～付け","kana":"～つけ","pos":"[接尾]","accent":"","meaning":"经常，习惯于","example":"行きつけの店で昼食を取ると、店主がいつもの席を空けておいてくれたことに気づいた。","exampleZh":"在常去的店里吃午饭时，他发现店主已经为他留好了平时坐的位置。","note":"例：\n行きつけの店で昼食を取ると、店主がいつもの席を空けておいてくれたことに気づいた。\n译：在常去的店里吃午饭时，他发现店主已经为他留好了平时坐的位置。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2001","seq":2001,"level":"N1","type":"主词条","word":"告げる","kana":"つげる","pos":"[他動2]","accent":"⓪","meaning":"（口头）告知；宣告","example":"事実を告げる前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“告知；宣告”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を告げる前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“告知；宣告”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2002","seq":2002,"level":"N1","type":"主词条","word":"つじつま","kana":"つじつま","pos":"[名]","accent":"⓪","meaning":"道理，逻辑","example":"つじつまが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“道理，逻辑”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\nつじつまが蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“道理，逻辑”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2003","seq":2003,"level":"N1","type":"主词条","word":"筒","kana":"つつ","pos":"[名]","accent":"⓪②","meaning":"筒","example":"古い図面は細長い筒に入れて保管されており、開くと紙の端が少し傷んでいた。","exampleZh":"旧图纸被装在细长的筒中保存，打开时纸的边缘已有些破损。","note":"例：\n古い図面は細長い筒に入れて保管されており、開くと紙の端が少し傷んでいた。\n译：旧图纸被装在细长的筒中保存，打开时纸的边缘已有些破损。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2004","seq":2004,"level":"N1","type":"主词条","word":"突く","kana":"つつく","pos":"[他動1]","accent":"②","meaning":"戳；唆使；挑毛病","example":"無理に突くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“戳；唆使”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に突くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“戳；唆使”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2005","seq":2005,"level":"N1","type":"主词条","word":"慎む","kana":"つつしむ","pos":"[他動1]","accent":"③","meaning":"谨慎；节制","example":"慎むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“谨慎；节制”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n慎むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“谨慎；节制”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2006","seq":2006,"level":"N1","type":"主词条","word":"謹んで","kana":"つつしんで","pos":"[副]","accent":"③","meaning":"恭敬地，彬彬有礼地","example":"このたびの受賞を謹んでお受けし、支えてくださった皆さまへの感謝を忘れず活動を続けたい。","exampleZh":"我谨接受此次获奖，并希望继续活动，不忘对支持我的各位表示感谢。","note":"例：\nこのたびの受賞を謹んでお受けし、支えてくださった皆さまへの感謝を忘れず活動を続けたい。\n译：我谨接受此次获奖，并希望继续活动，不忘对支持我的各位表示感谢。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2007","seq":2007,"level":"N1","type":"主词条","word":"突っ突く","kana":"つっつく","pos":"[他動1]","accent":"③","meaning":"捅，戳，啄","example":"無理に突っ突くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“捅，戳，啄”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に突っ突くよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“捅，戳，啄”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2008","seq":2008,"level":"N1","type":"主词条","word":"突っ張る","kana":"つっぱる","pos":"[自他動1]","accent":"③","meaning":"（肌肉）僵硬；坚持己见","example":"自分の意見を突っ張るばかりでは、たとえ正論でも周囲の協力を得ることは難しい。","exampleZh":"如果只是一味坚持自己的意见，即使观点正确，也很难得到周围协作。","note":"例：\n自分の意見を突っ張るばかりでは、たとえ正論でも周囲の協力を得ることは難しい。\n译：如果只是一味坚持自己的意见，即使观点正确，也很难得到周围协作。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2009","seq":2009,"level":"N1","type":"主词条","word":"堤","kana":"つつみ","pos":"[名]","accent":"③","meaning":"堤坝","example":"堤の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“堤坝”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n堤の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“堤坝”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2010","seq":2010,"level":"N1","type":"主词条","word":"勤まる/務まる","kana":"つとまる","pos":"[自動1]","accent":"③","meaning":"能胜任，能完成","example":"勤まる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“能胜任，能完成”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n勤まる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“能胜任，能完成”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2011","seq":2011,"level":"N1","type":"主词条","word":"努めて","kana":"つとめて","pos":"[副]","accent":"②","meaning":"尽量，尽可能","example":"彼は感情的になりそうな場面でも努めて冷静に振る舞い、相手の話を最後まで聞こうとした。","exampleZh":"即使在快要情绪化的场面，他也尽量保持冷静，试图把对方的话听到最后。","note":"例：\n彼は感情的になりそうな場面でも努めて冷静に振る舞い、相手の話を最後まで聞こうとした。\n译：即使在快要情绪化的场面，他也尽量保持冷静，试图把对方的话听到最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2012","seq":2012,"level":"N1","type":"主词条","word":"抓る","kana":"つねる","pos":"[他動1]","accent":"②","meaning":"拧，掐，捏","example":"抓る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“拧，掐，捏”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n抓る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“拧，掐，捏”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2013","seq":2013,"level":"N1","type":"主词条","word":"角","kana":"つの","pos":"[名]","accent":"②","meaning":"角；触角；嫉妒","example":"胸に残る角を無理に隠すより、彼女は事実と感情を分けて整理しようとした。","exampleZh":"与其勉强隐藏心中残留的“角；触角”，她更想把事实和情绪分开整理。","note":"例：\n胸に残る角を無理に隠すより、彼女は事実と感情を分けて整理しようとした。\n译：与其勉强隐藏心中残留的“角；触角”，她更想把事实和情绪分开整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2014","seq":2014,"level":"N1","type":"主词条","word":"募る","kana":"つのる","pos":"[自他動1]","accent":"②","meaning":"招，募集；（某种感觉）越来越厉害","example":"無理に募るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“招，募集；越来越厉害”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に募るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“招，募集；越来越厉害”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2015","seq":2015,"level":"N1","type":"主词条","word":"つぶやく","kana":"つぶやく","pos":"[自動1]","accent":"③","meaning":"发牢骚，嘟囔","example":"つぶやく場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“发牢骚，嘟囔”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\nつぶやく場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“发牢骚，嘟囔”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2016","seq":2016,"level":"N1","type":"主词条","word":"つぶら","kana":"つぶら","pos":"[ナ形]","accent":"⓪①","meaning":"圆溜溜的","example":"つぶらな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“圆溜溜的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\nつぶらな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“圆溜溜的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2017","seq":2017,"level":"N1","type":"主词条","word":"つぶる","kana":"つぶる","pos":"[他動1]","accent":"⓪","meaning":"瞑目，闭眼","example":"つぶる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“瞑目，闭眼”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\nつぶる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“瞑目，闭眼”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2018","seq":2018,"level":"N1","type":"主词条","word":"摘む","kana":"つまむ","pos":"[他動1]","accent":"⓪","meaning":"捏，撮；摘要","example":"摘む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“捏，撮；摘要”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n摘む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“捏，撮；摘要”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2019","seq":2019,"level":"N1","type":"主词条","word":"面","kana":"つら","pos":"[名]","accent":"②","meaning":"脸，颜面","example":"面に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。","exampleZh":"他感到“脸，颜面”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","note":"例：\n面に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。\n译：他感到“脸，颜面”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2020","seq":2020,"level":"N1","type":"主词条","word":"連なる","kana":"つらなる","pos":"[自動1]","accent":"③","meaning":"绵延，相连；参加；关系到","example":"連なる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“绵延，相连；参加”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n連なる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“绵延，相连；参加”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2021","seq":2021,"level":"N1","type":"主词条","word":"貫く","kana":"つらぬく","pos":"[他動1]","accent":"③","meaning":"贯通；贯彻","example":"自分の道を貫くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“贯通；贯彻”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を貫くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“贯通；贯彻”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2022","seq":2022,"level":"N1","type":"主词条","word":"連ねる","kana":"つらねる","pos":"[他動2]","accent":"③","meaning":"连成一排；陪同，联袂","example":"連ねる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“连成一排；陪同，联袂”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n連ねる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“连成一排；陪同，联袂”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2023","seq":2023,"level":"N1","type":"主词条","word":"釣られる","kana":"つられる","pos":"[自動2]","accent":"④⓪","meaning":"被引诱，受影响","example":"釣られる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“被引诱，受影响”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n釣られる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“被引诱，受影响”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2024","seq":2024,"level":"N1","type":"主词条","word":"釣鐘","kana":"つりがね","pos":"[名]","accent":"⓪","meaning":"吊钟","example":"釣鐘を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“吊钟”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n釣鐘を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“吊钟”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2025","seq":2025,"level":"N1","type":"主词条","word":"つるつる","kana":"つるつる","pos":"[副·自動3·ナ形]","accent":"①","meaning":"光滑；哧溜哧溜（吃东西）","example":"雨上がりの石段はつるつるしていて、手すりを持たないと危ない。","exampleZh":"雨后的石阶很滑，不扶着扶手会有危险。","note":"例：\n雨上がりの石段はつるつるしていて、手すりを持たないと危ない。\n译：雨后的石阶很滑，不扶着扶手会有危险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2026","seq":2026,"level":"N1","type":"主词条","word":"手当たり次第","kana":"てあたりしだい","pos":"[副]","accent":"⑤","meaning":"顺手抓到什么就……","example":"彼は手当たり次第に資料を集めるのではなく、必要な情報を絞って効率よく調査を進めた。","exampleZh":"他没有胡乱收集资料，而是筛选必要信息，高效推进调查。","note":"例：\n彼は手当たり次第に資料を集めるのではなく、必要な情報を絞って効率よく調査を進めた。\n译：他没有胡乱收集资料，而是筛选必要信息，高效推进调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2027","seq":2027,"level":"N1","type":"主词条","word":"手当て","kana":"てあて","pos":"[名·他動3]","accent":"①","meaning":"补贴；治疗，护理","example":"彼は手当てを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“补贴；治疗，护理”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は手当てを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“补贴；治疗，护理”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2028","seq":2028,"level":"N1","type":"主词条","word":"提携","kana":"ていけい","pos":"[名·自動3]","accent":"⓪","meaning":"提携，合作","example":"提携する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“提携，合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n提携する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“提携，合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2029","seq":2029,"level":"N1","type":"主词条","word":"締結","kana":"ていけつ","pos":"[名·他動3]","accent":"⓪","meaning":"缔结","example":"両国は長い交渉の末、環境保護に関する新しい協定を締結した。","exampleZh":"两国经过长期谈判，缔结了关于环境保护的新协定。","note":"例：\n両国は長い交渉の末、環境保護に関する新しい協定を締結した。\n译：两国经过长期谈判，缔结了关于环境保护的新协定。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2030","seq":2030,"level":"N1","type":"主词条","word":"体裁","kana":"ていさい","pos":"[名]","accent":"⓪","meaning":"外表；体面","example":"体裁を整えることにばかり気を取られると、利用者が本当に困っている点を見落としてしまう。","exampleZh":"如果只顾整理外表体面，就会忽视使用者真正困扰的地方。","note":"例：\n体裁を整えることにばかり気を取られると、利用者が本当に困っている点を見落としてしまう。\n译：如果只顾整理外表体面，就会忽视使用者真正困扰的地方。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2031","seq":2031,"level":"N1","type":"主词条","word":"提示","kana":"ていじ","pos":"[名·他動3]","accent":"⓪①","meaning":"出示","example":"提示する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“出示”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n提示する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“出示”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2032","seq":2032,"level":"N1","type":"主词条","word":"定食","kana":"ていしょく","pos":"[名]","accent":"⓪","meaning":"套餐","example":"定食の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“套餐”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n定食の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“套餐”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2033","seq":2033,"level":"N1","type":"主词条","word":"ディスプレー","kana":"でぃすぷれー（display）","pos":"[名·他動3]","accent":"④①③","meaning":"陈列；显示屏","example":"店頭のディスプレーを季節感のあるものに変えると、通行人が足を止めるようになった。","exampleZh":"把店头陈列改成带有季节感的样式后，路人开始停下脚步。","note":"例：\n店頭のディスプレーを季節感のあるものに変えると、通行人が足を止めるようになった。\n译：把店头陈列改成带有季节感的样式后，路人开始停下脚步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2034","seq":2034,"level":"N1","type":"主词条","word":"訂正","kana":"ていせい","pos":"[名·他動3]","accent":"⓪","meaning":"订正，改正","example":"誤りを訂正する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。","exampleZh":"在“订正，改正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","note":"例：\n誤りを訂正する際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。\n译：在“订正，改正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2035","seq":2035,"level":"N1","type":"主词条","word":"定説","kana":"ていせつ","pos":"[名]","accent":"⓪","meaning":"定论","example":"定説を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“定论”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\n定説を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“定论”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2036","seq":2036,"level":"N1","type":"主词条","word":"停滞","kana":"ていたい","pos":"[名·自動3]","accent":"⓪","meaning":"停滞，滞留","example":"停滞した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“停滞，滞留”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n停滞した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“停滞，滞留”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2037","seq":2037,"level":"N1","type":"主词条","word":"定着","kana":"ていちゃく","pos":"[名·自動3]","accent":"⓪","meaning":"固定，稳定扎根","example":"定着する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“固定，稳定扎根”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n定着する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“固定，稳定扎根”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2038","seq":2038,"level":"N1","type":"主词条","word":"低迷","kana":"ていめい","pos":"[名·自動3]","accent":"⓪","meaning":"低迷","example":"低迷するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“低迷”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n低迷するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“低迷”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2039","seq":2039,"level":"N1","type":"主词条","word":"手薄","kana":"てうす","pos":"[名·ナ形]","accent":"⓪","meaning":"人手少","example":"周囲から手薄だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“人手少”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から手薄だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“人手少”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2040","seq":2040,"level":"N1","type":"主词条","word":"手遅れ","kana":"ておくれ","pos":"[名]","accent":"②","meaning":"为时已晚","example":"手遅れが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“为时已晚”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n手遅れが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“为时已晚”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2041","seq":2041,"level":"N1","type":"主词条","word":"でかい","kana":"でかい","pos":"[イ形]","accent":"②","meaning":"大，好大","example":"でかい声で主張するだけでは相手を説得できず、根拠を示す落ち着きも必要だ。","exampleZh":"只是大声主张无法说服对方，还需要拿出依据的沉着。","note":"例：\nでかい声で主張するだけでは相手を説得できず、根拠を示す落ち着きも必要だ。\n译：只是大声主张无法说服对方，还需要拿出依据的沉着。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2042","seq":2042,"level":"N1","type":"主词条","word":"手掛り","kana":"てがかり","pos":"[名]","accent":"②","meaning":"线索，头绪","example":"手掛りを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“线索，头绪”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n手掛りを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“线索，头绪”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2043","seq":2043,"level":"N1","type":"主词条","word":"手掛ける","kana":"てがける","pos":"[他動2]","accent":"③","meaning":"亲自动手做；照顾，栽培","example":"自分の道を手掛けるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“亲自动手做；照顾，栽培”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を手掛けるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“亲自动手做；照顾，栽培”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2044","seq":2044,"level":"N1","type":"主词条","word":"手形","kana":"てがた","pos":"[名]","accent":"⓪","meaning":"手印；票据","example":"手形の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“手印；票据”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n手形の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“手印；票据”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2045","seq":2045,"level":"N1","type":"主词条","word":"手堅い","kana":"てがたい","pos":"[イ形]","accent":"③⓪","meaning":"踏实，靠得住","example":"手堅いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“踏实，靠得住”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n手堅いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“踏实，靠得住”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2046","seq":2046,"level":"N1","type":"主词条","word":"手軽","kana":"てがる","pos":"[名·ナ形]","accent":"⓪","meaning":"简单，简便；轻易","example":"手軽な方法に見えても、個人情報を扱う作業では安全性を確認してから使うべきだ。","exampleZh":"即使看似简便，在处理个人信息的作业中也应先确认安全性后再使用。","note":"例：\n手軽な方法に見えても、個人情報を扱う作業では安全性を確認してから使うべきだ。\n译：即使看似简便，在处理个人信息的作业中也应先确认安全性后再使用。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2047","seq":2047,"level":"N1","type":"主词条","word":"適応","kana":"てきおう","pos":"[名·自動3]","accent":"⓪","meaning":"适合，适应","example":"適応する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“适合，适应”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n適応する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“适合，适应”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2048","seq":2048,"level":"N1","type":"主词条","word":"適宜","kana":"てきぎ","pos":"[副·ナ形]","accent":"①⓪","meaning":"酌情；适当","example":"資料の量が多いので、担当者は重要度に応じて適宜内容を整理し、会議では要点だけを共有した。","exampleZh":"资料量很多，负责人根据重要程度适当整理内容，会议上只共享要点。","note":"例：\n資料の量が多いので、担当者は重要度に応じて適宜内容を整理し、会議では要点だけを共有した。\n译：资料量很多，负责人根据重要程度适当整理内容，会议上只共享要点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2049","seq":2049,"level":"N1","type":"主词条","word":"出来心","kana":"できごころ","pos":"[名]","accent":"③","meaning":"起坏心，起歹意","example":"小さな出来心を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“起坏心，起歹意”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな出来心を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“起坏心，起歹意”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2050","seq":2050,"level":"N1","type":"主词条","word":"摘出","kana":"てきしゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"摘除，取出；指出","example":"初めて摘出する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“摘除，取出；指出”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて摘出する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“摘除，取出；指出”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2051","seq":2051,"level":"N1","type":"主词条","word":"適性","kana":"てきせい","pos":"[名]","accent":"⓪","meaning":"适应性","example":"適性を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“适应性”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n適性を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“适应性”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2052","seq":2052,"level":"N1","type":"主词条","word":"てきぱき","kana":"てきぱき","pos":"[副]","accent":"①","meaning":"（说话）直截了当；麻利，利落","example":"彼女は受付で来場者をてきぱき案内し、混雑していた入口の流れを短時間で整えた。","exampleZh":"她在前台麻利地引导来场者，短时间内整理好了拥挤入口的人流。","note":"例：\n彼女は受付で来場者をてきぱき案内し、混雑していた入口の流れを短時間で整えた。\n译：她在前台麻利地引导来场者，短时间内整理好了拥挤入口的人流。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2053","seq":2053,"level":"N1","type":"主词条","word":"出来物","kana":"できもの","pos":"[名]","accent":"③②","meaning":"疙瘩","example":"古い出来物を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“疙瘩”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い出来物を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“疙瘩”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2054","seq":2054,"level":"N1","type":"主词条","word":"手際","kana":"てぎわ","pos":"[名]","accent":"⓪③","meaning":"（处理事物的）方法，技巧","example":"手際をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“方法，技巧”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n手際をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“方法，技巧”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2055","seq":2055,"level":"N1","type":"主词条","word":"手口","kana":"てぐち","pos":"[名]","accent":"①","meaning":"犯罪手法","example":"手口を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。","exampleZh":"若突然导入“犯罪手法”会招致混乱，因此负责人试图具体说明目的和影响范围。","note":"例：\n手口を急に導入すれば混乱を招くため、担当者は目的と影響範囲を具体的に示そうとした。\n译：若突然导入“犯罪手法”会招致混乱，因此负责人试图具体说明目的和影响范围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2056","seq":2056,"level":"N1","type":"主词条","word":"出くわす","kana":"でくわす","pos":"[自動1]","accent":"⓪③","meaning":"偶遇，碰到","example":"出くわすような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“偶遇，碰到”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n出くわすような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“偶遇，碰到”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2057","seq":2057,"level":"N1","type":"主词条","word":"手ごたえ","kana":"てごたえ","pos":"[名]","accent":"⓪","meaning":"（撞击、打击时的）手感；反应","example":"小さな手ごたえを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“手感；反应”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな手ごたえを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“手感；反应”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2058","seq":2058,"level":"N1","type":"主词条","word":"デコレーション","kana":"でこれーしょん（decoration）","pos":"[名]","accent":"③","meaning":"装饰","example":"デコレーションを担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。","exampleZh":"负责“装饰”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","note":"例：\nデコレーションを担当した彼は、観客の目線だけでなく、舞台裏で働く人の動きまで計算に入れていた。\n译：负责“装饰”的他不仅考虑观众视线，也把后台工作人员的动线纳入了计算。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2059","seq":2059,"level":"N1","type":"主词条","word":"手頃","kana":"てごろ","pos":"[名·ナ形]","accent":"⓪","meaning":"适中，适合","example":"周囲から手頃だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“适中，适合”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から手頃だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“适中，适合”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2060","seq":2060,"level":"N1","type":"主词条","word":"手強い","kana":"てごわい","pos":"[イ形]","accent":"③⓪","meaning":"难以战胜，难对付","example":"手強い状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“难以战胜，难对付”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n手強い状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“难以战胜，难对付”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2061","seq":2061,"level":"N1","type":"主词条","word":"デザート","kana":"でざーと（dessert）","pos":"[名]","accent":"②","meaning":"餐后甜点","example":"店主はデザートの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“餐后甜点”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主はデザートの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“餐后甜点”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2062","seq":2062,"level":"N1","type":"主词条","word":"手順","kana":"てじゅん","pos":"[名]","accent":"⓪①","meaning":"顺序，次序","example":"手順を変えるだけで情報の見え方は大きく変わるため、彼は利用者が迷わない並べ方を考えた。","exampleZh":"只改变顺序，信息呈现方式也会大大改变，所以他思考了让使用者不迷惑的排列方式。","note":"例：\n手順を変えるだけで情報の見え方は大きく変わるため、彼は利用者が迷わない並べ方を考えた。\n译：只改变顺序，信息呈现方式也会大大改变，所以他思考了让使用者不迷惑的排列方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2063","seq":2063,"level":"N1","type":"主词条","word":"手錠","kana":"てじょう","pos":"[名]","accent":"⓪","meaning":"手铐","example":"手錠を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“手铐”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n手錠を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“手铐”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2064","seq":2064,"level":"N1","type":"主词条","word":"手数","kana":"てすう","pos":"[名]","accent":"②","meaning":"麻烦，费事","example":"古い手数でも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。","exampleZh":"即使是旧的“麻烦，费事”，只要持续保养，也能长久保持不受潮流左右的品味。","note":"例：\n古い手数でも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。\n译：即使是旧的“麻烦，费事”，只要持续保养，也能长久保持不受潮流左右的品味。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2065","seq":2065,"level":"N1","type":"主词条","word":"手近","kana":"てぢか","pos":"[名·ナ形]","accent":"⓪","meaning":"手边，身边；常见","example":"手近な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“手边，身边；常见”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n手近な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“手边，身边；常见”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2066","seq":2066,"level":"N1","type":"主词条","word":"手違い","kana":"てちがい","pos":"[名]","accent":"⓪","meaning":"错误，差错","example":"手違いを放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。","exampleZh":"如果放任“错误，差错”不管，不仅现场负担会增加，也可能失去使用者的信任。","note":"例：\n手違いを放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。\n译：如果放任“错误，差错”不管，不仅现场负担会增加，也可能失去使用者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2067","seq":2067,"level":"N1","type":"主词条","word":"てっきり","kana":"てっきり","pos":"[副]","accent":"③","meaning":"（认为）一定（其实不然）","example":"彼はてっきり会議が延期になったと思い込んでいたが、開始時刻は予定どおりだった。","exampleZh":"他一直以为会议延期了，但开始时间仍按原计划。","note":"例：\n彼はてっきり会議が延期になったと思い込んでいたが、開始時刻は予定どおりだった。\n译：他一直以为会议延期了，但开始时间仍按原计划。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2068","seq":2068,"level":"N1","type":"主词条","word":"鉄筋","kana":"てっきん","pos":"[名]","accent":"⓪","meaning":"钢筋","example":"古い建物の鉄筋が腐食していないか、専門家は壁を壊さずに検査できる方法を検討した。","exampleZh":"专家研究了无需破墙即可检查旧建筑钢筋是否腐蚀的方法。","note":"例：\n古い建物の鉄筋が腐食していないか、専門家は壁を壊さずに検査できる方法を検討した。\n译：专家研究了无需破墙即可检查旧建筑钢筋是否腐蚀的方法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2069","seq":2069,"level":"N1","type":"主词条","word":"デッサン","kana":"でっさん","pos":"[名]","accent":"①","meaning":"素描，草图","example":"デッサンの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“素描，草图”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\nデッサンの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“素描，草图”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2070","seq":2070,"level":"N1","type":"主词条","word":"徹する","kana":"てっする","pos":"[自他動3]","accent":"⓪③","meaning":"彻底做到；贯通，从头到尾","example":"彼女は会議中ずっと聞き役に徹し、全員の意見が出そろってから初めて自分の提案を述べた。","exampleZh":"会议中她始终专心做倾听者，等全员意见都出来后才第一次提出自己的方案。","note":"例：\n彼女は会議中ずっと聞き役に徹し、全員の意見が出そろってから初めて自分の提案を述べた。\n译：会议中她始终专心做倾听者，等全员意见都出来后才第一次提出自己的方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2071","seq":2071,"level":"N1","type":"主词条","word":"手っ取り早い","kana":"てっとりばやい","pos":"[イ形]","accent":"⑥","meaning":"迅速，简单","example":"手っ取り早い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“迅速，简单”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n手っ取り早い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“迅速，简单”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2072","seq":2072,"level":"N1","type":"主词条","word":"撤廃","kana":"てっぱい","pos":"[名·他動3]","accent":"⓪","meaning":"取消，撤销","example":"チームは撤廃する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“取消，撤销”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは撤廃する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“取消，撤销”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2073","seq":2073,"level":"N1","type":"主词条","word":"天辺","kana":"てっぺん","pos":"[名]","accent":"③","meaning":"头顶；顶峰，最高处","example":"天辺に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“头顶；顶峰，最高处”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n天辺に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“头顶；顶峰，最高处”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2074","seq":2074,"level":"N1","type":"主词条","word":"鉄棒","kana":"てつぼう","pos":"[名]","accent":"⓪","meaning":"铁棒，单杠","example":"鉄棒が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“铁棒，单杠”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n鉄棒が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“铁棒，单杠”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2075","seq":2075,"level":"N1","type":"主词条","word":"手直し","kana":"てなおし","pos":"[名·他動3]","accent":"②","meaning":"修改，修正","example":"誤りを手直しする際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。","exampleZh":"在“修改，修正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","note":"例：\n誤りを手直しする際、彼は単に結果を直すだけでなく、同じ問題が起きた原因も記録に残した。\n译：在“修改，修正”错误时，他不只是修正结果，还把同样问题发生的原因记录下来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2076","seq":2076,"level":"N1","type":"主词条","word":"出直し","kana":"でなおし","pos":"[名·自動3]","accent":"⓪","meaning":"回来再去；重新开始","example":"出直しする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“回来再去；重新开始”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n出直しする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“回来再去；重新开始”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2077","seq":2077,"level":"N1","type":"主词条","word":"出直す","kana":"でなおす","pos":"[自動1]","accent":"③⓪","meaning":"回来再去；重新开始","example":"出直すような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“回来再去；重新开始”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n出直すような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“回来再去；重新开始”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2078","seq":2078,"level":"N1","type":"主词条","word":"手筈","kana":"てはず","pos":"[名]","accent":"①","meaning":"准备；步骤，程序","example":"立派な手筈でも、現場の制約を無視すれば実行段階で必ず行き詰まる。","exampleZh":"即使是出色的“准备；步骤，程序”，若无视现场限制，在执行阶段也一定会受阻。","note":"例：\n立派な手筈でも、現場の制約を無視すれば実行段階で必ず行き詰まる。\n译：即使是出色的“准备；步骤，程序”，若无视现场限制，在执行阶段也一定会受阻。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2079","seq":2079,"level":"N1","type":"主词条","word":"出番","kana":"でばん","pos":"[名]","accent":"②⓪","meaning":"值班；出场（做某事）","example":"自分の出番が来るまで、彼は舞台袖で深呼吸を繰り返し、台詞の最初の一行を確認した。","exampleZh":"在轮到自己出场前，他在舞台侧反复深呼吸，并确认台词第一行。","note":"例：\n自分の出番が来るまで、彼は舞台袖で深呼吸を繰り返し、台詞の最初の一行を確認した。\n译：在轮到自己出场前，他在舞台侧反复深呼吸，并确认台词第一行。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2080","seq":2080,"level":"N1","type":"主词条","word":"手引き","kana":"てびき","pos":"[名·他動3]","accent":"①③","meaning":"引路，向导","example":"新入社員向けの手引きを作る際、彼女は専門用語を減らし、実際の失敗例も加えた。","exampleZh":"制作新员工手册时，她减少专业术语，并加入实际失败例子。","note":"例：\n新入社員向けの手引きを作る際、彼女は専門用語を減らし、実際の失敗例も加えた。\n译：制作新员工手册时，她减少专业术语，并加入实际失败例子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2081","seq":2081,"level":"N1","type":"主词条","word":"デビュー","kana":"でびゅー","pos":"[名·自動3]","accent":"①","meaning":"初次登台，初出茅庐","example":"地方の小さな劇場でデビューした俳優は、失敗を重ねながら少しずつ表現力を磨いていった。","exampleZh":"在地方小剧场初次登台的演员，经历多次失败后逐渐磨练表现力。","note":"例：\n地方の小さな劇場でデビューした俳優は、失敗を重ねながら少しずつ表現力を磨いていった。\n译：在地方小剧场初次登台的演员，经历多次失败后逐渐磨练表现力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2082","seq":2082,"level":"N1","type":"主词条","word":"手ぶら","kana":"てぶら","pos":"[名]","accent":"⓪","meaning":"空手，上门不带礼物","example":"手ぶらで訪問するのは失礼だと思い、彼女は相手の負担にならない小さな菓子折りを用意した。","exampleZh":"她觉得空手拜访很失礼，于是准备了一小盒不会给对方造成负担的点心。","note":"例：\n手ぶらで訪問するのは失礼だと思い、彼女は相手の負担にならない小さな菓子折りを用意した。\n译：她觉得空手拜访很失礼，于是准备了一小盒不会给对方造成负担的点心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2083","seq":2083,"level":"N1","type":"主词条","word":"手回し","kana":"てまわし","pos":"[名·自動3]","accent":"②","meaning":"安排，布置","example":"予期せず手回しした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“安排，布置”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず手回しした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“安排，布置”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2084","seq":2084,"level":"N1","type":"主词条","word":"出回る","kana":"でまわる","pos":"[自動1]","accent":"⓪③","meaning":"上市","example":"出回る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“上市”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n出回る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“上市”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2085","seq":2085,"level":"N1","type":"主词条","word":"出向く","kana":"でむく","pos":"[自動1]","accent":"⓪","meaning":"前往","example":"出向くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“前往”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n出向くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“前往”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2086","seq":2086,"level":"N1","type":"主词条","word":"デメリット","kana":"でめりっと（demerit）","pos":"[名]","accent":"②","meaning":"不利之处","example":"デメリットが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“不利之处”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nデメリットが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“不利之处”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2087","seq":2087,"level":"N1","type":"主词条","word":"デリケート","kana":"でりけーと（delicate）","pos":"[ナ形]","accent":"③","meaning":"纤细，细致；敏感","example":"デリケートな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“纤细，细致；敏感”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nデリケートな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“纤细，细致；敏感”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2088","seq":2088,"level":"N1","type":"主词条","word":"照れくさい","kana":"てれくさい","pos":"[イ形]","accent":"④","meaning":"害羞，难为情","example":"照れくさい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“害羞，难为情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n照れくさい状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“害羞，难为情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2089","seq":2089,"level":"N1","type":"主词条","word":"テロ","kana":"てろ","pos":"[名]","accent":"①","meaning":"恐怖主义，恐怖活动","example":"テロが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“恐怖主义，恐怖活动”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nテロが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“恐怖主义，恐怖活动”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2090","seq":2090,"level":"N1","type":"主词条","word":"手分け","kana":"てわけ","pos":"[名·自動3]","accent":"③","meaning":"分头，分工","example":"資料の確認を手分けして進めたため、短い時間でも見落としをかなり減らすことができた。","exampleZh":"分头确认资料后，即使时间很短，也大幅减少了遗漏。","note":"例：\n資料の確認を手分けして進めたため、短い時間でも見落としをかなり減らすことができた。\n译：分头确认资料后，即使时间很短，也大幅减少了遗漏。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2091","seq":2091,"level":"N1","type":"主词条","word":"転嫁","kana":"てんか","pos":"[名·他動3]","accent":"①","meaning":"转嫁，推诿","example":"転嫁の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“转嫁，推诿”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n転嫁の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“转嫁，推诿”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2092","seq":2092,"level":"N1","type":"主词条","word":"転居","kana":"てんきょ","pos":"[名·自動3]","accent":"⓪①","meaning":"迁居，搬家","example":"転居する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“迁居，搬家”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n転居する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“迁居，搬家”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2093","seq":2093,"level":"N1","type":"主词条","word":"点検","kana":"てんけん","pos":"[名·他動3]","accent":"⓪","meaning":"检查","example":"点検するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。","exampleZh":"他没有只满足于“检查”本身，而是进一步思考结果如何连接到现场改善。","note":"例：\n点検するだけで満足せず、彼は結果が現場の改善にどうつながるかまで考えた。\n译：他没有只满足于“检查”本身，而是进一步思考结果如何连接到现场改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2094","seq":2094,"level":"N1","type":"主词条","word":"添削","kana":"てんさく","pos":"[名·他動3]","accent":"⓪","meaning":"增删，修改","example":"添削する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“增删，修改”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n添削する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“增删，修改”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2095","seq":2095,"level":"N1","type":"主词条","word":"展示","kana":"てんじ","pos":"[名·他動3]","accent":"⓪","meaning":"展示，展出","example":"展示する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。","exampleZh":"在进行“展示，展出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","note":"例：\n展示する前に、担当者は来場者の動線と安全対策を細かく確認し、当日の混乱を防ごうとした。\n译：在进行“展示，展出”之前，负责人细致确认了来场者动线和安全措施，试图防止当天混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2096","seq":2096,"level":"N1","type":"主词条","word":"伝承","kana":"でんしょう","pos":"[名·他動3]","accent":"⓪","meaning":"传承，口传","example":"チームは伝承する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“传承，口传”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは伝承する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“传承，口传”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2097","seq":2097,"level":"N1","type":"主词条","word":"テンション","kana":"てんしょん（tension）","pos":"[名]","accent":"①","meaning":"紧张，兴奋","example":"朝からテンションが高い後輩に対し、先輩は会議では少し落ち着いて話すよう助言した。","exampleZh":"面对从早上起就情绪高涨的后辈，前辈建议他会议上稍微沉稳些讲话。","note":"例：\n朝からテンションが高い後輩に対し、先輩は会議では少し落ち着いて話すよう助言した。\n译：面对从早上起就情绪高涨的后辈，前辈建议他会议上稍微沉稳些讲话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2098","seq":2098,"level":"N1","type":"主词条","word":"転じる","kana":"てんじる","pos":"[自他動2]","accent":"⓪③","meaning":"转换，改変","example":"無理に転じるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“转换，改変”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に転じるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“转换，改変”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2099","seq":2099,"level":"N1","type":"主词条","word":"てんで","kana":"てんで","pos":"[副]","accent":"⓪","meaning":"完全（不）；非常，很","example":"彼の話は専門用語ばかりで、初めて聞く人にはてんで分からなかった。","exampleZh":"他的话全是专业术语，第一次听的人完全听不懂。","note":"例：\n彼の話は専門用語ばかりで、初めて聞く人にはてんで分からなかった。\n译：他的话全是专业术语，第一次听的人完全听不懂。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2100","seq":2100,"level":"N1","type":"主词条","word":"転任","kana":"てんにん","pos":"[名·自動3]","accent":"⓪","meaning":"调任，调动","example":"地方支社へ転任することになり、彼はこれまで担当していた顧客への引き継ぎを丁寧に行った。","exampleZh":"他被调任到地方分公司，于是细致地交接了此前负责的客户。","note":"例：\n地方支社へ転任することになり、彼はこれまで担当していた顧客への引き継ぎを丁寧に行った。\n译：他被调任到地方分公司，于是细致地交接了此前负责的客户。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2101","seq":2101,"level":"N1","type":"主词条","word":"伝票","kana":"でんぴょう","pos":"[名]","accent":"⓪","meaning":"单据，票据","example":"伝票の数字が一つ違っていたため、経理担当者は支払い前に取引先へ確認した。","exampleZh":"因为单据数字有一处不同，会计负责人在付款前向客户确认。","note":"例：\n伝票の数字が一つ違っていたため、経理担当者は支払い前に取引先へ確認した。\n译：因为单据数字有一处不同，会计负责人在付款前向客户确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2102","seq":2102,"level":"N1","type":"主词条","word":"展望","kana":"てんぼう","pos":"[名·他動3]","accent":"⓪","meaning":"瞭望，眺望；展望","example":"展望する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“瞭望，眺望；展望”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n展望する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“瞭望，眺望；展望”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2103","seq":2103,"level":"N1","type":"主词条","word":"天文","kana":"てんもん","pos":"[名]","accent":"⓪","meaning":"天文","example":"天文を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。","exampleZh":"为了避免接收“天文”的一方产生误解，负责人附上简短背景和目的后再共享。","note":"例：\n天文を受け取った側が誤解しないよう、担当者は背景と目的を短く添えて共有した。\n译：为了避免接收“天文”的一方产生误解，负责人附上简短背景和目的后再共享。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2104","seq":2104,"level":"N1","type":"主词条","word":"伝来","kana":"でんらい","pos":"[名·自動3]","accent":"⓪","meaning":"传入；祖传","example":"予期せず伝来した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“传入；祖传”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず伝来した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“传入；祖传”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2105","seq":2105,"level":"N1","type":"主词条","word":"転落","kana":"てんらく","pos":"[名·自動3]","accent":"⓪","meaning":"跌落；落魄","example":"足場から転落すれば命に関わるため、作業員は短時間の作業でも安全帯を必ず着けている。","exampleZh":"从脚手架跌落会危及生命，因此作业人员即使短时间作业也一定系安全带。","note":"例：\n足場から転落すれば命に関わるため、作業員は短時間の作業でも安全帯を必ず着けている。\n译：从脚手架跌落会危及生命，因此作业人员即使短时间作业也一定系安全带。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2106","seq":2106,"level":"N1","type":"主词条","word":"問いただす","kana":"といただす","pos":"[他動1]","accent":"④⓪","meaning":"询问，质疑；盘问","example":"無理に問いただすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“询问，质疑；盘问”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に問いただすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“询问，质疑；盘问”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2107","seq":2107,"level":"N1","type":"主词条","word":"当～","kana":"とう","pos":"[接頭]","accent":"①","meaning":"这个，该……","example":"当社の規定に従って手続きを進める場合でも、利用者に不利益が出ないよう例外条件を丁寧に確認する。","exampleZh":"即使按照本公司规定推进手续，也会细致确认例外条件，避免使用者受不利影响。","note":"例：\n当社の規定に従って手続きを進める場合でも、利用者に不利益が出ないよう例外条件を丁寧に確認する。\n译：即使按照本公司规定推进手续，也会细致确认例外条件，避免使用者受不利影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2108","seq":2108,"level":"N1","type":"主词条","word":"同意","kana":"どうい","pos":"[名·自動3]","accent":"⓪","meaning":"同意，赞成","example":"同意するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“同意，赞成”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n同意するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“同意，赞成”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2109","seq":2109,"level":"N1","type":"主词条","word":"投下","kana":"とうか","pos":"[名·他動3]","accent":"⓪①","meaning":"投下，掷下；投资","example":"新規事業へ資金を投下する前に、市場規模と回収見込みを慎重に検討した。","exampleZh":"在向新事业投入资金前，慎重研究了市场规模和回收预期。","note":"例：\n新規事業へ資金を投下する前に、市場規模と回収見込みを慎重に検討した。\n译：在向新事业投入资金前，慎重研究了市场规模和回收预期。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2110","seq":2110,"level":"N1","type":"主词条","word":"どうかすると","kana":"どうかすると","pos":"[副]","accent":"①","meaning":"有时，依据情况；动不动","example":"疲れがたまっていると、どうかすると同じ入力ミスを繰り返してしまうことがある。","exampleZh":"疲劳积累时，有时会反复犯同样的输入错误。","note":"例：\n疲れがたまっていると、どうかすると同じ入力ミスを繰り返してしまうことがある。\n译：疲劳积累时，有时会反复犯同样的输入错误。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2111","seq":2111,"level":"N1","type":"主词条","word":"同感","kana":"どうかん","pos":"[名·自動3]","accent":"⓪","meaning":"同感，赞同","example":"同感した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“同感，赞同”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n同感した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“同感，赞同”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2112","seq":2112,"level":"N1","type":"主词条","word":"討議","kana":"とうぎ","pos":"[名·自他動3]","accent":"①","meaning":"讨论","example":"チームは討議する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“讨论”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは討議する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“讨论”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2113","seq":2113,"level":"N1","type":"主词条","word":"投球","kana":"とうきゅう","pos":"[名·自動3]","accent":"⓪","meaning":"投球","example":"投球するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“投球”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n投球するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“投球”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2114","seq":2114,"level":"N1","type":"主词条","word":"統合","kana":"とうごう","pos":"[名·他動3]","accent":"⓪","meaning":"统一，合并","example":"情報を統合する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。","exampleZh":"在“统一，合并”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","note":"例：\n情報を統合する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。\n译：在“统一，合并”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2115","seq":2115,"level":"N1","type":"主词条","word":"動向","kana":"どうこう","pos":"[名]","accent":"⓪","meaning":"动向","example":"動向をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“动向”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n動向をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“动向”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2116","seq":2116,"level":"N1","type":"主词条","word":"盗作","kana":"とうさく","pos":"[名·他動3]","accent":"⓪","meaning":"剽窃","example":"彼は盗作を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“剽窃”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は盗作を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“剽窃”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2117","seq":2117,"level":"N1","type":"主词条","word":"倒産","kana":"とうさん","pos":"[名·自動3]","accent":"⓪","meaning":"破产，倒闭","example":"倒産する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“破产，倒闭”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n倒産する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“破产，倒闭”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2118","seq":2118,"level":"N1","type":"主词条","word":"投資","kana":"とうし","pos":"[名·自他動3]","accent":"⓪①","meaning":"投资","example":"投資する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“投资”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n投資する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“投资”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2119","seq":2119,"level":"N1","type":"主词条","word":"踏襲","kana":"とうしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"沿袭，继承；沿用","example":"踏襲する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“沿袭，继承；沿用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n踏襲する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“沿袭，继承；沿用”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2120","seq":2120,"level":"N1","type":"主词条","word":"投書","kana":"とうしょ","pos":"[名·自他動3]","accent":"⓪","meaning":"投稿","example":"チームは投書する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“投稿”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは投書する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“投稿”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2121","seq":2121,"level":"N1","type":"主词条","word":"搭乗","kana":"とうじょう","pos":"[名·自動3]","accent":"⓪","meaning":"搭乘","example":"飛行機に搭乗する前に、彼女は必要な書類と手荷物の制限をもう一度確認した。","exampleZh":"登机前，她再次确认了所需文件和随身行李限制。","note":"例：\n飛行機に搭乗する前に、彼女は必要な書類と手荷物の制限をもう一度確認した。\n译：登机前，她再次确认了所需文件和随身行李限制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2122","seq":2122,"level":"N1","type":"主词条","word":"同情","kana":"どうじょう","pos":"[名·自動3]","accent":"⓪","meaning":"同情","example":"同情する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“同情”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n同情する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“同情”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2123","seq":2123,"level":"N1","type":"主词条","word":"道場","kana":"どうじょう","pos":"[名]","accent":"①","meaning":"道场，修行的地方","example":"道場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“道场，修行的地方”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n道場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“道场，修行的地方”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2124","seq":2124,"level":"N1","type":"主词条","word":"投じる","kana":"とうじる","pos":"[他動2]","accent":"⓪","meaning":"投；献身","example":"難しい仕事を途中で投じるのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。","exampleZh":"面对困难工作，他没有中途“投；献身”，而是分开思考原因，并判断何时寻求帮助。","note":"例：\n難しい仕事を途中で投じるのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。\n译：面对困难工作，他没有中途“投；献身”，而是分开思考原因，并判断何时寻求帮助。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2125","seq":2125,"level":"N1","type":"主词条","word":"統制","kana":"とうせい","pos":"[名·他動3]","accent":"⓪","meaning":"控制，管制","example":"感染症の拡大を防ぐには、情報の統制ではなく、正確で迅速な公開が欠かせない。","exampleZh":"要防止传染病扩散，离不开准确而迅速的信息公开，而不是信息管制。","note":"例：\n感染症の拡大を防ぐには、情報の統制ではなく、正確で迅速な公開が欠かせない。\n译：要防止传染病扩散，离不开准确而迅速的信息公开，而不是信息管制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2126","seq":2126,"level":"N1","type":"主词条","word":"当選","kana":"とうせん","pos":"[名·自動3]","accent":"⓪","meaning":"当选；中彩票，中签","example":"当選した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“当选；中彩票，中签”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n当選した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“当选；中彩票，中签”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2127","seq":2127,"level":"N1","type":"主词条","word":"逃走","kana":"とうそう","pos":"[名·自動3]","accent":"⓪","meaning":"逃跑，逃走","example":"容疑者が逃走したため、警察は周辺の駅や道路で聞き込みを始めた。","exampleZh":"嫌疑人逃走后，警方开始在周边车站和道路进行走访。","note":"例：\n容疑者が逃走したため、警察は周辺の駅や道路で聞き込みを始めた。\n译：嫌疑人逃走后，警方开始在周边车站和道路进行走访。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2128","seq":2128,"level":"N1","type":"主词条","word":"統率","kana":"とうそつ","pos":"[名·他動3]","accent":"⓪","meaning":"统率，率领","example":"チームは統率する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“统率，率领”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは統率する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“统率，率领”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2129","seq":2129,"level":"N1","type":"主词条","word":"到達","kana":"とうたつ","pos":"[名·自動3]","accent":"⓪","meaning":"达到","example":"予期せず到達した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“达到”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず到達した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“达到”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2130","seq":2130,"level":"N1","type":"主词条","word":"同調","kana":"どうちょう","pos":"[名·自動3]","accent":"⓪","meaning":"步调一致；赞同","example":"同調してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“步调一致；赞同”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n同調してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“步调一致；赞同”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2131","seq":2131,"level":"N1","type":"主词条","word":"到底","kana":"とうてい","pos":"[副]","accent":"⓪","meaning":"怎么也（不），无论如何也（不）","example":"利用者に重大な不利益を与える案は、どれほど費用が安くても到底受け入れられない。","exampleZh":"给使用者带来重大不利的方案，无论费用多低也绝不能接受。","note":"例：\n利用者に重大な不利益を与える案は、どれほど費用が安くても到底受け入れられない。\n译：给使用者带来重大不利的方案，无论费用多低也绝不能接受。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2132","seq":2132,"level":"N1","type":"主词条","word":"動的","kana":"どうてき","pos":"[ナ形]","accent":"⓪","meaning":"具有动感的，生动的","example":"動的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“具有动感的，生动的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n動的な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“具有动感的，生动的”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2133","seq":2133,"level":"N1","type":"主词条","word":"尊い/貴い","kana":"とうとい","pos":"[イ形]","accent":"③","meaning":"宝贵，尊贵","example":"命を守るために働く人々の努力は尊いものであり、社会全体で支えていく必要がある。","exampleZh":"为守护生命而工作的人们的努力是宝贵的，需要整个社会一同支持。","note":"例：\n命を守るために働く人々の努力は尊いものであり、社会全体で支えていく必要がある。\n译：为守护生命而工作的人们的努力是宝贵的，需要整个社会一同支持。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2134","seq":2134,"level":"N1","type":"主词条","word":"同等","kana":"どうとう","pos":"[名·ナ形]","accent":"⓪","meaning":"同等","example":"周囲から同等だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“同等”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から同等だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“同等”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2135","seq":2135,"level":"N1","type":"主词条","word":"堂々","kana":"どうどう","pos":"[副·ナ形]","accent":"⓪③","meaning":"堂堂正正，坦荡","example":"彼は批判を恐れず、会議で堂々と自分の意見を述べた。","exampleZh":"他不怕批评，在会议上堂堂正正地表达了自己的意见。","note":"例：\n彼は批判を恐れず、会議で堂々と自分の意見を述べた。\n译：他不怕批评，在会议上堂堂正正地表达了自己的意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2136","seq":2136,"level":"N1","type":"主词条","word":"唐突","kana":"とうとつ","pos":"[名·ナ形]","accent":"⓪","meaning":"唐突，突然，冒昧","example":"会議の終盤で唐突な質問を受けた彼は、一度資料を確認してから落ち着いて答えた。","exampleZh":"会议尾声突然被问到问题的他，先确认了一次资料，再冷静回答。","note":"例：\n会議の終盤で唐突な質問を受けた彼は、一度資料を確認してから落ち着いて答えた。\n译：会议尾声突然被问到问题的他，先确认了一次资料，再冷静回答。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2137","seq":2137,"level":"N1","type":"主词条","word":"尊ぶ","kana":"とうとぶ","pos":"[他動1]","accent":"③","meaning":"尊重，尊崇","example":"互いの文化を尊ぶ姿勢がなければ、国際的な協力は表面的な合意だけで終わってしまう。","exampleZh":"如果没有尊重彼此文化的态度，国际合作只会止于表面的协议。","note":"例：\n互いの文化を尊ぶ姿勢がなければ、国際的な協力は表面的な合意だけで終わってしまう。\n译：如果没有尊重彼此文化的态度，国际合作只会止于表面的协议。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2138","seq":2138,"level":"N1","type":"主词条","word":"どうにか","kana":"どうにか","pos":"[副]","accent":"①⓪","meaning":"总算，勉强；设法","example":"全員で役割を分担した結果、締め切り直前ではあったがどうにか報告書を提出できた。","exampleZh":"全员分担职责后，虽然临近截止，仍总算提交了报告书。","note":"例：\n全員で役割を分担した結果、締め切り直前ではあったがどうにか報告書を提出できた。\n译：全员分担职责后，虽然临近截止，仍总算提交了报告书。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2139","seq":2139,"level":"N1","type":"主词条","word":"どうにかこうにか","kana":"どうにかこうにか","pos":"[副]","accent":"①","meaning":"总算，勉强","example":"機材の不調に悩まされながらも、担当者たちはどうにかこうにか発表を最後までやり遂げた。","exampleZh":"虽然一直受器材故障困扰，负责人们还是勉强把发表坚持到了最后。","note":"例：\n機材の不調に悩まされながらも、担当者たちはどうにかこうにか発表を最後までやり遂げた。\n译：虽然一直受器材故障困扰，负责人们还是勉强把发表坚持到了最后。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2140","seq":2140,"level":"N1","type":"主词条","word":"投入","kana":"とうにゅう","pos":"[名·他動3]","accent":"⓪","meaning":"投入","example":"彼は投入を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“投入”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は投入を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“投入”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2141","seq":2141,"level":"N1","type":"主词条","word":"当人","kana":"とうにん","pos":"[名]","accent":"①","meaning":"当事人，本人","example":"経験豊かな当人の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“当事人，本人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな当人の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“当事人，本人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2142","seq":2142,"level":"N1","type":"主词条","word":"どうのこうの","kana":"どうのこうの","pos":"[副]","accent":"①④","meaning":"说这说那","example":"今さら費用がどうのこうのと言う前に、まず安全を確保するための最低限の対策を取るべきだ。","exampleZh":"事到如今在费用上说这说那之前，首先应该采取确保安全的最低限度对策。","note":"例：\n今さら費用がどうのこうのと言う前に、まず安全を確保するための最低限の対策を取るべきだ。\n译：事到如今在费用上说这说那之前，首先应该采取确保安全的最低限度对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2143","seq":2143,"level":"N1","type":"主词条","word":"同封","kana":"どうふう","pos":"[名·他動3]","accent":"⓪","meaning":"附在信内","example":"同封する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“附在信内”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n同封する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“附在信内”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2144","seq":2144,"level":"N1","type":"主词条","word":"当分","kana":"とうぶん","pos":"[副]","accent":"⓪","meaning":"暂时，目前","example":"復旧には時間がかかるため、当分の間は臨時の窓口で問い合わせを受け付けることになった。","exampleZh":"修复需要时间，因此暂时将由临时窗口受理咨询。","note":"例：\n復旧には時間がかかるため、当分の間は臨時の窓口で問い合わせを受け付けることになった。\n译：修复需要时间，因此暂时将由临时窗口受理咨询。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2145","seq":2145,"level":"N1","type":"主词条","word":"当方","kana":"とうほう","pos":"[名]","accent":"①","meaning":"这一边，我方","example":"当方に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“这一边，我方”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n当方に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“这一边，我方”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2146","seq":2146,"level":"N1","type":"主词条","word":"逃亡","kana":"とうぼう","pos":"[名·自動3]","accent":"⓪","meaning":"逃亡","example":"逃亡した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“逃亡”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n逃亡した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“逃亡”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2147","seq":2147,"level":"N1","type":"主词条","word":"同盟","kana":"どうめい","pos":"[名·自動3]","accent":"⓪","meaning":"同盟","example":"同盟する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“同盟”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n同盟する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“同盟”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2148","seq":2148,"level":"N1","type":"主词条","word":"どうやら","kana":"どうやら","pos":"[副]","accent":"①","meaning":"好不容易才；仿佛","example":"窓の外が急に暗くなってきたので、どうやら夕方には一雨降りそうだ。","exampleZh":"窗外突然暗下来，看样子傍晚会下一场雨。","note":"例：\n窓の外が急に暗くなってきたので、どうやら夕方には一雨降りそうだ。\n译：窗外突然暗下来，看样子傍晚会下一场雨。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2149","seq":2149,"level":"N1","type":"主词条","word":"動揺","kana":"どうよう","pos":"[名·自動3]","accent":"⓪","meaning":"不安，不稳定","example":"予期せず動揺した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“不安，不稳定”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず動揺した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“不安，不稳定”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2150","seq":2150,"level":"N1","type":"主词条","word":"道理で","kana":"どうりで","pos":"[副]","accent":"③①","meaning":"怪不得","example":"受付に人が集まっていると思ったら、道理で今日は申請の締め切り日だった。","exampleZh":"正觉得前台聚了很多人，怪不得今天是申请截止日。","note":"例：\n受付に人が集まっていると思ったら、道理で今日は申請の締め切り日だった。\n译：正觉得前台聚了很多人，怪不得今天是申请截止日。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2151","seq":2151,"level":"N1","type":"主词条","word":"登竜門","kana":"とうりゅうもん","pos":"[名]","accent":"③","meaning":"成功的关键","example":"登竜門の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“成功的关键”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n登竜門の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“成功的关键”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2152","seq":2152,"level":"N1","type":"主词条","word":"登録","kana":"とうろく","pos":"[名·自他動3]","accent":"⓪","meaning":"登记，注册","example":"会員登録をする際には、便利さだけでなく、個人情報がどのように扱われるかも確認したい。","exampleZh":"办理会员注册时，不仅要看便利性，也想确认个人信息将如何被处理。","note":"例：\n会員登録をする際には、便利さだけでなく、個人情報がどのように扱われるかも確認したい。\n译：办理会员注册时，不仅要看便利性，也想确认个人信息将如何被处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2153","seq":2153,"level":"N1","type":"主词条","word":"討論","kana":"とうろん","pos":"[名·自他動3]","accent":"①","meaning":"讨论","example":"討論した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“讨论”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n討論した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“讨论”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2154","seq":2154,"level":"N1","type":"主词条","word":"遠ざかる","kana":"とおざかる","pos":"[自動1]","accent":"④","meaning":"远离，离远；疏远","example":"遠ざかるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“远离，离远；疏远”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n遠ざかるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“远离，离远；疏远”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2155","seq":2155,"level":"N1","type":"主词条","word":"トータル","kana":"とーたる（total）","pos":"[名·他動3·ナ形]","accent":"①","meaning":"合计；整体的","example":"交通費や宿泊費まで含めると、今回の出張費はトータルでかなり高くなる。","exampleZh":"如果连交通费和住宿费都算进去，这次出差费用合计会相当高。","note":"例：\n交通費や宿泊費まで含めると、今回の出張費はトータルでかなり高くなる。\n译：如果连交通费和住宿费都算进去，这次出差费用合计会相当高。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2156","seq":2156,"level":"N1","type":"主词条","word":"遠回り","kana":"とおまわり","pos":"[ナ形·自動3]","accent":"③","meaning":"绕远；绕圈子","example":"近道に見える道が工事中だったため、遠回りでも安全な道を選んだ。","exampleZh":"因为看似近路的道路正在施工，所以选择了绕远但安全的路。","note":"例：\n近道に見える道が工事中だったため、遠回りでも安全な道を選んだ。\n译：因为看似近路的道路正在施工，所以选择了绕远但安全的路。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2157","seq":2157,"level":"N1","type":"主词条","word":"トーン","kana":"とーん（tone）","pos":"[名]","accent":"①","meaning":"音调，色调","example":"トーンが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“音调，色调”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nトーンが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“音调，色调”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2158","seq":2158,"level":"N1","type":"主词条","word":"とかく","kana":"とかく","pos":"[副]","accent":"⓪","meaning":"动不动，总是，往往","example":"人はとかく目先の成果だけを評価しがちだが、地道な準備がなければ長続きしない。","exampleZh":"人往往只评价眼前成果，但没有踏实准备就无法长久。","note":"例：\n人はとかく目先の成果だけを評価しがちだが、地道な準備がなければ長続きしない。\n译：人往往只评价眼前成果，但没有踏实准备就无法长久。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2159","seq":2159,"level":"N1","type":"主词条","word":"咎める","kana":"とがめる","pos":"[自他動2]","accent":"③","meaning":"责备；盘问（自己）","example":"失敗した部下をすぐ咎めるのではなく、上司は原因を一緒に整理して再発防止策を考えた。","exampleZh":"上司没有立刻责备失败的部下，而是一起整理原因并思考防再发对策。","note":"例：\n失敗した部下をすぐ咎めるのではなく、上司は原因を一緒に整理して再発防止策を考えた。\n译：上司没有立刻责备失败的部下，而是一起整理原因并思考防再发对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2160","seq":2160,"level":"N1","type":"主词条","word":"時折","kana":"ときおり","pos":"[副]","accent":"⓪","meaning":"有时，偶尔","example":"会議中、彼女は時折メモに目を落としながら、相手の発言を正確に確認していた。","exampleZh":"会议中，她偶尔低头看笔记，同时准确确认对方发言。","note":"例：\n会議中、彼女は時折メモに目を落としながら、相手の発言を正確に確認していた。\n译：会议中，她偶尔低头看笔记，同时准确确认对方发言。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2161","seq":2161,"level":"N1","type":"主词条","word":"途切れる","kana":"とぎれる","pos":"[自動2]","accent":"③","meaning":"间断，中断","example":"途切れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“间断，中断”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n途切れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“间断，中断”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2162","seq":2162,"level":"N1","type":"主词条","word":"説く","kana":"とく","pos":"[他動1]","accent":"①","meaning":"说明；说服","example":"事実を説く前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“说明；说服”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を説く前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“说明；说服”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2163","seq":2163,"level":"N1","type":"主词条","word":"研ぐ","kana":"とぐ","pos":"[他動1]","accent":"①","meaning":"磨光，磨快；淘（米）","example":"無理に研ぐと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“磨光，磨快；淘”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に研ぐと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“磨光，磨快；淘”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2164","seq":2164,"level":"N1","type":"主词条","word":"特技","kana":"とくぎ","pos":"[名]","accent":"①","meaning":"拿手的技术，特技","example":"特技を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“拿手的技术，特技”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\n特技を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“拿手的技术，特技”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2165","seq":2165,"level":"N1","type":"主词条","word":"独裁","kana":"どくさい","pos":"[名·自動3]","accent":"⓪","meaning":"独裁，专断","example":"独裁が長く続く国では、反対意見を述べるだけでも大きな危険を伴うことがある。","exampleZh":"在独裁长期持续的国家，有时仅仅表达反对意见也伴随巨大危险。","note":"例：\n独裁が長く続く国では、反対意見を述べるだけでも大きな危険を伴うことがある。\n译：在独裁长期持续的国家，有时仅仅表达反对意见也伴随巨大危险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2166","seq":2166,"level":"N1","type":"主词条","word":"特産","kana":"とくさん","pos":"[名]","accent":"⓪","meaning":"特产","example":"特産が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“特产”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n特産が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“特产”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2167","seq":2167,"level":"N1","type":"主词条","word":"特集","kana":"とくしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"特辑，专辑","example":"特集する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“特辑，专辑”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n特集する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“特辑，专辑”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2168","seq":2168,"level":"N1","type":"主词条","word":"独占","kana":"どくせん","pos":"[名·他動3]","accent":"⓪","meaning":"独占，垄断","example":"チームは独占する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“独占，垄断”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは独占する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“独占，垄断”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2169","seq":2169,"level":"N1","type":"主词条","word":"独創","kana":"どくそう","pos":"[名·他動3]","accent":"⓪","meaning":"独创","example":"独創を重んじる研究室では、失敗した実験でも仮説の立て方が鋭ければ丁寧に評価される。","exampleZh":"重视独创性的研究室中，即使实验失败，只要假设建立得敏锐也会被认真评价。","note":"例：\n独創を重んじる研究室では、失敗した実験でも仮説の立て方が鋭ければ丁寧に評価される。\n译：重视独创性的研究室中，即使实验失败，只要假设建立得敏锐也会被认真评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2170","seq":2170,"level":"N1","type":"主词条","word":"とげ","kana":"とげ","pos":"[名]","accent":"②","meaning":"刺，棘；尖酸，带刺儿","example":"とげが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“刺，棘；尖酸，带刺儿”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nとげが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“刺，棘；尖酸，带刺儿”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2171","seq":2171,"level":"N1","type":"主词条","word":"とことんまで","kana":"とことんまで","pos":"[副]","accent":"③","meaning":"直到最后","example":"原因をとことんまで調べた結果、単純な操作ミスではなく仕組み自体に問題があると分かった。","exampleZh":"彻底调查原因后才发现，并非单纯操作失误，而是机制本身存在问题。","note":"例：\n原因をとことんまで調べた結果、単純な操作ミスではなく仕組み自体に問題があると分かった。\n译：彻底调查原因后才发现，并非单纯操作失误，而是机制本身存在问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2172","seq":2172,"level":"N1","type":"主词条","word":"閉じこもる","kana":"とじこもる","pos":"[自動1]","accent":"④⓪","meaning":"闭门不出","example":"閉じこもる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“闭门不出”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n閉じこもる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“闭门不出”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2173","seq":2173,"level":"N1","type":"主词条","word":"年頃","kana":"としごろ","pos":"[名]","accent":"⓪","meaning":"适龄；大约年龄，大约岁数","example":"年頃の子どもに注意するときは、親の正しさを押しつけるより、本人の自尊心にも配慮したい。","exampleZh":"提醒适龄孩子时，比起强压父母的正确性，也想顾及孩子本人的自尊心。","note":"例：\n年頃の子どもに注意するときは、親の正しさを押しつけるより、本人の自尊心にも配慮したい。\n译：提醒适龄孩子时，比起强压父母的正确性，也想顾及孩子本人的自尊心。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2174","seq":2174,"level":"N1","type":"主词条","word":"戸締り","kana":"とじまり","pos":"[名·自他動3]","accent":"②⓪","meaning":"关门窗，锁门","example":"戸締りする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“关门窗，锁门”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n戸締りする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“关门窗，锁门”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2175","seq":2175,"level":"N1","type":"主词条","word":"土砂","kana":"どしゃ","pos":"[名]","accent":"①","meaning":"沙土","example":"土砂を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“沙土”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n土砂を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“沙土”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2176","seq":2176,"level":"N1","type":"主词条","word":"途上","kana":"とじょう","pos":"[名]","accent":"⓪","meaning":"途中，中途","example":"限られた途上の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“途中，中途”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた途上の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“途中，中途”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2177","seq":2177,"level":"N1","type":"主词条","word":"綴じる","kana":"とじる","pos":"[他動2]","accent":"⓪","meaning":"订上","example":"綴じる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“订上”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n綴じる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“订上”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2178","seq":2178,"level":"N1","type":"主词条","word":"土台","kana":"どだい","pos":"[名·副]","accent":"⓪","meaning":"基础；本来，原来","example":"信頼という土台がなければ、どれほど立派な制度を作っても現場では長続きしない。","exampleZh":"如果没有信任这个基础，再出色的制度在现场也难以持久。","note":"例：\n信頼という土台がなければ、どれほど立派な制度を作っても現場では長続きしない。\n译：如果没有信任这个基础，再出色的制度在现场也难以持久。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2179","seq":2179,"level":"N1","type":"主词条","word":"途絶える","kana":"とだえる","pos":"[自動2]","accent":"③","meaning":"中断","example":"途絶える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“中断”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n途絶える場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“中断”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2180","seq":2180,"level":"N1","type":"主词条","word":"土壇場","kana":"どたんば","pos":"[名]","accent":"⓪","meaning":"绝境，最后关头","example":"観光客が増えた土壇場では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“绝境，最后关头”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた土壇場では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“绝境，最后关头”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2181","seq":2181,"level":"N1","type":"主词条","word":"特許","kana":"とっきょ","pos":"[名]","accent":"①⓪","meaning":"专利","example":"特許に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“专利”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n特許に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“专利”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2182","seq":2182,"level":"N1","type":"主词条","word":"とっくに","kana":"とっくに","pos":"[副]","accent":"③⓪","meaning":"早就，老早","example":"彼は資料をまだ読んでいないと思われていたが、実はとっくに内容を確認し、質問まで用意していた。","exampleZh":"大家以为他还没读资料，其实他早已确认内容，甚至准备好了问题。","note":"例：\n彼は資料をまだ読んでいないと思われていたが、実はとっくに内容を確認し、質問まで用意していた。\n译：大家以为他还没读资料，其实他早已确认内容，甚至准备好了问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2183","seq":2183,"level":"N1","type":"主词条","word":"特権","kana":"とっけん","pos":"[名]","accent":"⓪","meaning":"特权","example":"特権の変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。","exampleZh":"“特权”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","note":"例：\n特権の変更は生活に直接影響するため、行政は数字だけでなく住民の不安にも目を向けた。\n译：“特权”的变更会直接影响生活，因此行政部门不仅看数字，也关注居民的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2184","seq":2184,"level":"N1","type":"主词条","word":"とっさ","kana":"とっさ","pos":"[名]","accent":"⓪","meaning":"瞬间","example":"子どもが道路に飛び出した瞬間、彼はとっさの判断で腕を伸ばし、車道へ出るのを防いだ。","exampleZh":"孩子冲到路上的一瞬间，他凭即时判断伸出手，阻止了孩子进入车道。","note":"例：\n子どもが道路に飛び出した瞬間、彼はとっさの判断で腕を伸ばし、車道へ出るのを防いだ。\n译：孩子冲到路上的一瞬间，他凭即时判断伸出手，阻止了孩子进入车道。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2185","seq":2185,"level":"N1","type":"主词条","word":"とっさに","kana":"とっさに","pos":"[副]","accent":"⓪","meaning":"瞬间","example":"棚から箱が落ちそうになった瞬間、彼はとっさに手を伸ばして下にいた子どもを守った。","exampleZh":"箱子快从架子上掉下来的一瞬间，他立刻伸手护住了下方的孩子。","note":"例：\n棚から箱が落ちそうになった瞬間、彼はとっさに手を伸ばして下にいた子どもを守った。\n译：箱子快从架子上掉下来的一瞬间，他立刻伸手护住了下方的孩子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2186","seq":2186,"level":"N1","type":"主词条","word":"突然","kana":"とつじょ","pos":"[副]","accent":"①⓪","meaning":"突然，突如其来","example":"突然の停電で会場は暗くなったが、係員は慌てず参加者を出口へ誘導した。","exampleZh":"突然停电使会场变暗，工作人员没有慌张，而是引导参加者走向出口。","note":"例：\n突然の停電で会場は暗くなったが、係員は慌てず参加者を出口へ誘導した。\n译：突然停电使会场变暗，工作人员没有慌张，而是引导参加者走向出口。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2187","seq":2187,"level":"N1","type":"主词条","word":"とっておき","kana":"とっておき","pos":"[名]","accent":"⓪","meaning":"秘藏，珍藏","example":"とっておきが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“秘藏，珍藏”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nとっておきが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“秘藏，珍藏”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2188","seq":2188,"level":"N1","type":"主词条","word":"突破","kana":"とっぱ","pos":"[名·他動3]","accent":"⓪①","meaning":"突破","example":"彼は突破を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“突破”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は突破を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“突破”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2189","seq":2189,"level":"N1","type":"主词条","word":"突発的","kana":"とっぱつてき","pos":"[ナ形]","accent":"⓪","meaning":"突发的","example":"突発的な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“突发的”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n突発的な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“突发的”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2190","seq":2190,"level":"N1","type":"主词条","word":"突拍子もない","kana":"とっぴょうしもない","pos":"[連語]","accent":"③","meaning":"荒诞，离谱；出乎意料","example":"彼の突拍子もない発想がきっかけで、会議は思いがけず活気づいた。","exampleZh":"他的离奇想法成了契机，会议意外地活跃起来。","note":"例：\n彼の突拍子もない発想がきっかけで、会議は思いがけず活気づいた。\n译：他的离奇想法成了契机，会议意外地活跃起来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2191","seq":2191,"level":"N1","type":"主词条","word":"土手","kana":"どて","pos":"[名]","accent":"⓪","meaning":"堤防","example":"その土手は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“堤防”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその土手は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“堤防”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2192","seq":2192,"level":"N1","type":"主词条","word":"滞る","kana":"とどこおる","pos":"[自動1]","accent":"⓪③","meaning":"拖延，延迟；拖欠","example":"滞るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“拖延，延迟；拖欠”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n滞るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“拖延，延迟；拖欠”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2193","seq":2193,"level":"N1","type":"主词条","word":"留める","kana":"とどめる","pos":"[他動2]","accent":"③","meaning":"留住；保留；止于","example":"無理に留めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“留住；保留”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に留めるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“留住；保留”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2194","seq":2194,"level":"N1","type":"主词条","word":"唱える","kana":"となえる","pos":"[他動2]","accent":"③②","meaning":"诵念；提倡，高呼","example":"唱えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“诵念；提倡，高呼”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n唱えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“诵念；提倡，高呼”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2195","seq":2195,"level":"N1","type":"主词条","word":"とはいえ","kana":"とはいえ","pos":"[接]","accent":"①","meaning":"虽说，然而","example":"彼はまだ新人だ。とはいえ、資料の準備は誰よりも早く、上司からの信頼も厚い。","exampleZh":"他还是新人。虽说如此，资料准备比谁都快，也深受上司信任。","note":"例：\n彼はまだ新人だ。とはいえ、資料の準備は誰よりも早く、上司からの信頼も厚い。\n译：他还是新人。虽说如此，资料准备比谁都快，也深受上司信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2196","seq":2196,"level":"N1","type":"主词条","word":"飛び入り","kana":"とびいり","pos":"[名·自動3]","accent":"⓪","meaning":"中途加人（的人），临时报名参加（的人）","example":"飛び入りする前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“中途加人，临时报名参加”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n飛び入りする前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“中途加人，临时报名参加”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2197","seq":2197,"level":"N1","type":"主词条","word":"土俵","kana":"どひょう","pos":"[名]","accent":"⓪","meaning":"相扑比赛场","example":"専門外の土俵で議論を進めるなら、まず基本的な用語と前提をそろえなければ話がかみ合わない。","exampleZh":"如果要在不熟悉的领域中讨论，首先必须统一基本术语和前提，否则话题无法对上。","note":"例：\n専門外の土俵で議論を進めるなら、まず基本的な用語と前提をそろえなければ話がかみ合わない。\n译：如果要在不熟悉的领域中讨论，首先必须统一基本术语和前提，否则话题无法对上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2198","seq":2198,"level":"N1","type":"主词条","word":"途方もない","kana":"とほうもない","pos":"[イ形]","accent":"⑤","meaning":"岂有此理，荒唐；非常","example":"途方もない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“岂有此理，荒唐；非常”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n途方もない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“岂有此理，荒唐；非常”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2199","seq":2199,"level":"N1","type":"主词条","word":"土木","kana":"どぼく","pos":"[名]","accent":"①","meaning":"土木","example":"土木を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“土木”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n土木を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“土木”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2200","seq":2200,"level":"N1","type":"主词条","word":"惚ける／恍ける","kana":"とぼける","pos":"[自動2]","accent":"③","meaning":"装糊涂；出洋相","example":"惚ける／恍ける場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为应对装糊涂或出洋相的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n惚ける／恍ける場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为应对装糊涂或出洋相的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2201","seq":2201,"level":"N1","type":"主词条","word":"乏しい","kana":"とぼしい","pos":"[イ形]","accent":"③⓪","meaning":"缺乏","example":"乏しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“缺乏”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n乏しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“缺乏”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2202","seq":2202,"level":"N1","type":"主词条","word":"戸惑い","kana":"とまどい","pos":"[名]","accent":"⓪③","meaning":"困惑","example":"戸惑いをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“困惑”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n戸惑いをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“困惑”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2203","seq":2203,"level":"N1","type":"主词条","word":"戸惑う","kana":"とまどう","pos":"[自動1]","accent":"③","meaning":"困惑","example":"戸惑うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“困惑”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n戸惑うとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“困惑”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2204","seq":2204,"level":"N1","type":"主词条","word":"富","kana":"とみ","pos":"[名]","accent":"①","meaning":"财富","example":"富をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“财富”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n富をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“财富”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2205","seq":2205,"level":"N1","type":"主词条","word":"富む","kana":"とむ","pos":"[自動1]","accent":"①","meaning":"富有，富于","example":"富む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“富有，富于”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n富む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“富有，富于”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2206","seq":2206,"level":"N1","type":"主词条","word":"～止め","kana":"～どめ","pos":"[接尾]","accent":"","meaning":"止住，停止","example":"この薬は痛み止めとして使われるが、原因を治すものではないため、症状が続く場合は医師に相談すべきだ。","exampleZh":"这种药可作为止痛药使用，但不能治疗病因，所以症状持续时应咨询医生。","note":"例：\nこの薬は痛み止めとして使われるが、原因を治すものではないため、症状が続く場合は医師に相談すべきだ。\n译：这种药可作为止痛药使用，但不能治疗病因，所以症状持续时应咨询医生。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2207","seq":2207,"level":"N1","type":"主词条","word":"ともあれ","kana":"ともあれ","pos":"[副]","accent":"①","meaning":"无论如何；暂且不论","example":"細かな反省点は残る。ともあれ、大きな事故なく行事を終えられたことは評価してよい。","exampleZh":"细小反省点仍然存在。无论如何，活动没有发生大事故就结束了，这一点可以肯定。","note":"例：\n細かな反省点は残る。ともあれ、大きな事故なく行事を終えられたことは評価してよい。\n译：细小反省点仍然存在。无论如何，活动没有发生大事故就结束了，这一点可以肯定。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2208","seq":2208,"level":"N1","type":"主词条","word":"トライ","kana":"とらい（try）","pos":"[名·自動3]","accent":"②","meaning":"尝试","example":"予期せずトライした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“尝试”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せずトライした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“尝试”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2209","seq":2209,"level":"N1","type":"主词条","word":"ドライ","kana":"どらい（dry）","pos":"[ナ形]","accent":"②","meaning":"干燥；理智，冷冰冰","example":"ドライな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“干燥；理智，冷冰冰”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nドライな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“干燥；理智，冷冰冰”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2210","seq":2210,"level":"N1","type":"主词条","word":"ドライブイン","kana":"どらいぶいん（drive-in）","pos":"[名]","accent":"④⑤","meaning":"免下车服务设施","example":"古いドライブインでも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。","exampleZh":"即使是旧的“免下车服务设施”，只要持续保养，也能长久保持不受潮流左右的品味。","note":"例：\n古いドライブインでも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。\n译：即使是旧的“免下车服务设施”，只要持续保养，也能长久保持不受潮流左右的品味。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2211","seq":2211,"level":"N1","type":"主词条","word":"トラウマ","kana":"とらうま","pos":"[名]","accent":"②⓪","meaning":"（精神）创伤","example":"トラウマを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“创伤”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nトラウマを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“创伤”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2212","seq":2212,"level":"N1","type":"主词条","word":"捕らわれる","kana":"とらわれる","pos":"[自動2]","accent":"④","meaning":"被捕；受束缚","example":"捕らわれる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“被捕；受束缚”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n捕らわれる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“被捕；受束缚”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2213","seq":2213,"level":"N1","type":"主词条","word":"取り扱い","kana":"とりあつかい","pos":"[名]","accent":"⓪","meaning":"对待；处理","example":"取り扱いをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“对待；处理”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n取り扱いをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“对待；处理”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2214","seq":2214,"level":"N1","type":"主词条","word":"取り扱う","kana":"とりあつかう","pos":"[他動1]","accent":"⓪⑤","meaning":"对待；操作，使用；经营","example":"人や情報を取り扱う立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“对待；操作，使用”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報を取り扱う立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“对待；操作，使用”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2215","seq":2215,"level":"N1","type":"主词条","word":"取り組む","kana":"とりくむ","pos":"[自動1]","accent":"③⓪","meaning":"致力于，专心致志","example":"取り組む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“致力于，专心致志”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n取り組む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“致力于，专心致志”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2216","seq":2216,"level":"N1","type":"主词条","word":"取り締まる","kana":"とりしまる","pos":"[他動1]","accent":"④⓪","meaning":"取缔","example":"無理に取り締まるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“取缔”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に取り締まるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“取缔”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2217","seq":2217,"level":"N1","type":"主词条","word":"取り調べる","kana":"とりしらべる","pos":"[他動2]","accent":"⑤⓪","meaning":"详细调查","example":"取り調べることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“详细调查”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n取り調べることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“详细调查”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2218","seq":2218,"level":"N1","type":"主词条","word":"取り立てて","kana":"とりたてて","pos":"[副]","accent":"⓪","meaning":"（并不）值得一提","example":"取り立てて新しい方法ではないが、毎日続けられるという点でこの手順には大きな意味がある。","exampleZh":"这并不是什么特别新颖的方法，但从每天都能坚持这一点来看，这个流程有很大意义。","note":"例：\n取り立てて新しい方法ではないが、毎日続けられるという点でこの手順には大きな意味がある。\n译：这并不是什么特别新颖的方法，但从每天都能坚持这一点来看，这个流程有很大意义。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2219","seq":2219,"level":"N1","type":"主词条","word":"取り立てる","kana":"とりたてる","pos":"[他動2]","accent":"④⓪","meaning":"特別列举；提拔；催收","example":"取り立てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“特別列举；提拔”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n取り立てる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“特別列举；提拔”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2220","seq":2220,"level":"N1","type":"主词条","word":"取り次ぐ","kana":"とりつぐ","pos":"[他動1]","accent":"③⓪","meaning":"传达，转达；转交","example":"事実を取り次ぐ前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“传达，转达；转交”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を取り次ぐ前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“传达，转达；转交”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2221","seq":2221,"level":"N1","type":"主词条","word":"取り除く","kana":"とりのぞく","pos":"[他動1]","accent":"⓪④","meaning":"除掉，去掉","example":"取り除く前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“除掉，去掉”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n取り除く前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“除掉，去掉”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2222","seq":2222,"level":"N1","type":"主词条","word":"取引","kana":"とりひき","pos":"[名·自他動3]","accent":"②","meaning":"交易","example":"取引する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“交易”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n取引する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“交易”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2223","seq":2223,"level":"N1","type":"主词条","word":"取り巻く","kana":"とりまく","pos":"[他動1]","accent":"③⓪","meaning":"围绕","example":"取り巻くことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“围绕”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n取り巻くことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“围绕”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2224","seq":2224,"level":"N1","type":"主词条","word":"取り混ぜる","kana":"とりまぜる","pos":"[他動2]","accent":"④⓪","meaning":"掺杂，掺和","example":"取り混ぜる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“掺杂，掺和”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n取り混ぜる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“掺杂，掺和”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2225","seq":2225,"level":"N1","type":"主词条","word":"取り寄せる","kana":"とりよせる","pos":"[他動2]","accent":"④⓪","meaning":"让人寄来","example":"大切な手紙を相手に取り寄せる前に、彼女は名前と住所を何度も確認した。","exampleZh":"在让对方寄来重要信件前，她反复确认了姓名和地址。","note":"例：\n大切な手紙を相手に取り寄せる前に、彼女は名前と住所を何度も確認した。\n译：在让对方寄来重要信件前，她反复确认了姓名和地址。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2226","seq":2226,"level":"N1","type":"主词条","word":"ドリル","kana":"どりる（drill）","pos":"[名]","accent":"①⓪","meaning":"钻孔器；反复练习","example":"ドリルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“钻孔器；反复练习”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nドリルをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“钻孔器；反复练习”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2227","seq":2227,"level":"N1","type":"主词条","word":"とりわけ","kana":"とりわけ","pos":"[副]","accent":"⓪","meaning":"特别，格外","example":"この地域では高齢者の移動手段が限られており、とりわけ冬場の通院支援が重要な課題になっている。","exampleZh":"在这个地区，老年人的移动手段有限，尤其冬季就医支援成了重要课题。","note":"例：\nこの地域では高齢者の移動手段が限られており、とりわけ冬場の通院支援が重要な課題になっている。\n译：在这个地区，老年人的移动手段有限，尤其冬季就医支援成了重要课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2228","seq":2228,"level":"N1","type":"主词条","word":"蕩ける","kana":"とろける","pos":"[自動2]","accent":"③⓪","meaning":"溶化；陶醉，心荡神驰","example":"蕩ける場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“溶化；陶醉，心荡神驰”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n蕩ける場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“溶化；陶醉，心荡神驰”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2229","seq":2229,"level":"N1","type":"主词条","word":"泥仕合","kana":"どろじあい","pos":"[名]","accent":"③","meaning":"互相揭短","example":"泥仕合が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“互相揭短”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n泥仕合が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“互相揭短”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2230","seq":2230,"level":"N1","type":"主词条","word":"どろどろ","kana":"どろどろ","pos":"[副·自動3]","accent":"①⓪","meaning":"沾满了泥；错综复杂","example":"大雨の後、校庭はどろどろになり、体育の授業は室内に変更された。","exampleZh":"大雨过后，操场变得泥泞不堪，体育课改在室内进行。","note":"例：\n大雨の後、校庭はどろどろになり、体育の授業は室内に変更された。\n译：大雨过后，操场变得泥泞不堪，体育课改在室内进行。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2231","seq":2231,"level":"N1","type":"主词条","word":"度忘れ","kana":"どわすれ","pos":"[名·他動3]","accent":"②","meaning":"一时想不起","example":"チームは度忘れする理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“一时想不起”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは度忘れする理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“一时想不起”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2232","seq":2232,"level":"N1","type":"主词条","word":"鈍感","kana":"どんかん","pos":"[名·ナ形]","accent":"⓪","meaning":"感觉迟钝","example":"鈍感な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“感觉迟钝”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n鈍感な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“感觉迟钝”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2233","seq":2233,"level":"N1","type":"主词条","word":"どん底","kana":"どんぞこ","pos":"[名]","accent":"⓪","meaning":"最差的状态","example":"事業が失敗してどん底に落ちた彼は、支えてくれた人への感謝を忘れず、少しずつ再起を図った。","exampleZh":"事业失败后跌入谷底的他，没有忘记感谢支持自己的人，并一点点谋求东山再起。","note":"例：\n事業が失敗してどん底に落ちた彼は、支えてくれた人への感謝を忘れず、少しずつ再起を図った。\n译：事业失败后跌入谷底的他，没有忘记感谢支持自己的人，并一点点谋求东山再起。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2234","seq":2234,"level":"N1","type":"主词条","word":"とんだ","kana":"とんだ","pos":"[連体]","accent":"⓪","meaning":"意想不到；不可挽回","example":"大事な資料を別の会場へ送ってしまい、担当者はとんだ失敗をしたと顔を青くした。","exampleZh":"把重要资料寄到了别的会场，负责人脸色发青，觉得自己犯了意想不到的大错。","note":"例：\n大事な資料を別の会場へ送ってしまい、担当者はとんだ失敗をしたと顔を青くした。\n译：把重要资料寄到了别的会场，负责人脸色发青，觉得自己犯了意想不到的大错。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2235","seq":2235,"level":"N1","type":"主词条","word":"とんとん拍子","kana":"とんとんびょうし","pos":"[名·ナ形]","accent":"⑤","meaning":"一帆风顺，顺顺当当","example":"周囲からとんとん拍子だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“一帆风顺，顺顺当当”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲からとんとん拍子だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“一帆风顺，顺顺当当”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2236","seq":2236,"level":"N1","type":"主词条","word":"問屋","kana":"とんや","pos":"[名]","accent":"⓪","meaning":"批发商","example":"問屋の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“批发商”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n問屋の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“批发商”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2237","seq":2237,"level":"N1","type":"主词条","word":"どんより","kana":"どんより","pos":"[副·自動3]","accent":"③","meaning":"阴沉；不明亮","example":"空がどんより曇っていたため、遠足の担当者は雨具と屋内で過ごす代替案を用意した。","exampleZh":"天空阴沉沉的，远足负责人准备了雨具和改在室内活动的替代方案。","note":"例：\n空がどんより曇っていたため、遠足の担当者は雨具と屋内で過ごす代替案を用意した。\n译：天空阴沉沉的，远足负责人准备了雨具和改在室内活动的替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2238","seq":2238,"level":"N1","type":"主词条","word":"乃至","kana":"ないし","pos":"[接]","accent":"①","meaning":"至；或者","example":"彼女は失敗の原因を認めた。乃至、同じミスを防ぐための手順もその場で提案した。","exampleZh":"她承认了失败原因。“至；或者”，还当场提出了防止同样错误的流程。","note":"例：\n彼女は失敗の原因を認めた。乃至、同じミスを防ぐための手順もその場で提案した。\n译：她承认了失败原因。“至；或者”，还当场提出了防止同样错误的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2239","seq":2239,"level":"N1","type":"主词条","word":"内緒","kana":"ないしょ","pos":"[名]","accent":"③⓪","meaning":"保密","example":"内緒をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“保密”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n内緒をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“保密”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2240","seq":2240,"level":"N1","type":"主词条","word":"内心","kana":"ないしん","pos":"[名·副]","accent":"⓪","meaning":"内心，暗地里","example":"彼は平気な顔で発表を終えたが、内心では資料の誤りを指摘されないか不安でたまらなかった。","exampleZh":"他若无其事地结束了发表，但内心担心得不得了，怕资料错误被指出。","note":"例：\n彼は平気な顔で発表を終えたが、内心では資料の誤りを指摘されないか不安でたまらなかった。\n译：他若无其事地结束了发表，但内心担心得不得了，怕资料错误被指出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2241","seq":2241,"level":"N1","type":"主词条","word":"ナイター","kana":"ナイター","pos":"[名]","accent":"①","meaning":"夜场比赛","example":"ナイターを有効に使うには、予定を詰め込みすぎず、考えるための余白を残しておくことが大切だ。","exampleZh":"要有效利用夜场比赛，就不要把计划排得太满，而要留下思考的余地。","note":"例：\nナイターを有効に使うには、予定を詰め込みすぎず、考えるための余白を残しておくことが大切だ。\n译：要有效利用夜场比赛，就不要把计划排得太满，而要留下思考的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2242","seq":2242,"level":"N1","type":"主词条","word":"なおさら","kana":"なおさら","pos":"[副]","accent":"⓪","meaning":"更加，越发","example":"一度信頼を失った相手に対しては、なおさら言葉だけでなく行動で誠意を示す必要がある。","exampleZh":"对曾经失去信任的对方，更需要不只用语言，而是用行动表现诚意。","note":"例：\n一度信頼を失った相手に対しては、なおさら言葉だけでなく行動で誠意を示す必要がある。\n译：对曾经失去信任的对方，更需要不只用语言，而是用行动表现诚意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2243","seq":2243,"level":"N1","type":"主词条","word":"ながなが","kana":"ナイター","pos":"[副]","accent":"③","meaning":"长久，冗长；长长地","example":"彼はながながと経緯を話したが、結論を先に示さなかったため聞き手は要点をつかみにくかった。","exampleZh":"他长篇大论地讲了事情经过，但没有先给出结论，所以听者很难抓住要点。","note":"例：\n彼はながながと経緯を話したが、結論を先に示さなかったため聞き手は要点をつかみにくかった。\n译：他长篇大论地讲了事情经过，但没有先给出结论，所以听者很难抓住要点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2244","seq":2244,"level":"N1","type":"主词条","word":"なかほど","kana":"なかほど","pos":"[名]","accent":"⓪②","meaning":"中间，中央；中途","example":"式のなかほどで突然マイクの音が途切れたが、司会者は落ち着いて進行を続けた。","exampleZh":"仪式进行到中途时麦克风突然断音，但主持人镇定地继续推进流程。","note":"例：\n式のなかほどで突然マイクの音が途切れたが、司会者は落ち着いて進行を続けた。\n译：仪式进行到中途时麦克风突然断音，但主持人镇定地继续推进流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2245","seq":2245,"level":"N1","type":"主词条","word":"嘆かわしい","kana":"なげかわしい","pos":"[イ形]","accent":"⑤","meaning":"悲伤的，遗憾的","example":"嘆かわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“悲伤的，遗憾的”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n嘆かわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“悲伤的，遗憾的”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2246","seq":2246,"level":"N1","type":"主词条","word":"嘆く","kana":"なげく","pos":"[自他動1]","accent":"②","meaning":"悲叹，叹惋","example":"相手に何かを嘆くなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“悲叹，叹惋”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを嘆くなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“悲叹，叹惋”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2247","seq":2247,"level":"N1","type":"主词条","word":"投げ出す","kana":"なげだす","pos":"[他動1]","accent":"③⓪","meaning":"中途放弃；抛出，全部拿出","example":"難しい仕事を途中で投げ出すのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。","exampleZh":"面对困难工作，他没有中途“中途放弃；抛出，全部拿出”，而是分开思考原因，并判断何时寻求帮助。","note":"例：\n難しい仕事を途中で投げ出すのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。\n译：面对困难工作，他没有中途“中途放弃；抛出，全部拿出”，而是分开思考原因，并判断何时寻求帮助。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2248","seq":2248,"level":"N1","type":"主词条","word":"投げる","kana":"なげる","pos":"[他動2]","accent":"②","meaning":"提出；放弃","example":"難しい仕事を途中で投げるのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。","exampleZh":"面对困难工作，他没有中途“提出；放弃”，而是分开思考原因，并判断何时寻求帮助。","note":"例：\n難しい仕事を途中で投げるのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。\n译：面对困难工作，他没有中途“提出；放弃”，而是分开思考原因，并判断何时寻求帮助。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2249","seq":2249,"level":"N1","type":"主词条","word":"仲人","kana":"なこうど","pos":"[名]","accent":"⓪","meaning":"媒人，月老","example":"経験豊かな仲人の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“媒人，月老”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな仲人の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“媒人，月老”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2250","seq":2250,"level":"N1","type":"主词条","word":"和やか","kana":"なごやか","pos":"[ナ形]","accent":"②","meaning":"和睦，安详","example":"一度和やかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“和睦，安详”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度和やかだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“和睦，安详”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2251","seq":2251,"level":"N1","type":"主词条","word":"名残","kana":"なごり","pos":"[名]","accent":"③","meaning":"余韵，余音；惜别，留恋","example":"名残をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“余韵，余音；惜别，留恋”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n名残をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“余韵，余音；惜别，留恋”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2252","seq":2252,"level":"N1","type":"主词条","word":"名残惜しい","kana":"なごりおしい","pos":"[イ形]","accent":"⑤","meaning":"依恋，恋恋不舍","example":"名残惜しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“依恋，恋恋不舍”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n名残惜しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“依恋，恋恋不舍”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2253","seq":2253,"level":"N1","type":"主词条","word":"情け","kana":"なさけ","pos":"[名]","accent":"①③","meaning":"人情，情义","example":"情けとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“人情，情义”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n情けとして信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“人情，情义”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2254","seq":2254,"level":"N1","type":"主词条","word":"情けない","kana":"なさけない","pos":"[イ形]","accent":"④","meaning":"可怜，悲惨；无情；无奈，难为情","example":"情けない状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使在“可怜，悲惨；无情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n情けない状況でも、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使在“可怜，悲惨；无情”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2255","seq":2255,"level":"N1","type":"主词条","word":"情け深い","kana":"なさけぶかい","pos":"[イ形]","accent":"⑤","meaning":"仁慈，富于同情心","example":"情け深い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“仁慈，富于同情心”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n情け深い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“仁慈，富于同情心”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2256","seq":2256,"level":"N1","type":"主词条","word":"馴染む","kana":"なじむ","pos":"[自動1]","accent":"②","meaning":"熟，适应；融合，调和","example":"馴染む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“熟，适应；融合，调和”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n馴染む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“熟，适应；融合，调和”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2257","seq":2257,"level":"N1","type":"主词条","word":"詰る","kana":"なじる","pos":"[他動1]","accent":"②","meaning":"指责","example":"相手を詰るだけでは問題は解決しないので、彼は不満を伝える前に事実関係を整理した。","exampleZh":"单纯指责对方无法解决问题，所以他在表达不满前先整理了事实关系。","note":"例：\n相手を詰るだけでは問題は解決しないので、彼は不満を伝える前に事実関係を整理した。\n译：单纯指责对方无法解决问题，所以他在表达不满前先整理了事实关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2258","seq":2258,"level":"N1","type":"主词条","word":"名高い","kana":"なだかい","pos":"[イ形]","accent":"③","meaning":"有名，闻名","example":"名高い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“有名，闻名”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n名高い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“有名，闻名”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2259","seq":2259,"level":"N1","type":"主词条","word":"宥める","kana":"なだめる","pos":"[他動2]","accent":"③","meaning":"抚慰，安抚；劝解","example":"宥めることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“抚慰，安抚；劝解”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n宥めることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“抚慰，安抚；劝解”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2260","seq":2260,"level":"N1","type":"主词条","word":"雪崩","kana":"なだれ","pos":"[名]","accent":"⓪","meaning":"雪崩","example":"朝から雪崩が続いたため、町の人々は予定を少し変え、屋外作業を早めに切り上げた。","exampleZh":"从早上起雪崩接连发生，镇上的人稍微改变计划，提前结束了户外作业。","note":"例：\n朝から雪崩が続いたため、町の人々は予定を少し変え、屋外作業を早めに切り上げた。\n译：从早上起雪崩接连发生，镇上的人稍微改变计划，提前结束了户外作业。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2261","seq":2261,"level":"N1","type":"主词条","word":"捺印","kana":"なついん","pos":"[名·自動3]","accent":"⓪","meaning":"盖印，盖章","example":"捺印した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“盖印，盖章”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n捺印した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“盖印，盖章”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2262","seq":2262,"level":"N1","type":"主词条","word":"懐く","kana":"なつく","pos":"[自動1]","accent":"②","meaning":"亲近","example":"懐くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“亲近”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n懐くような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“亲近”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2263","seq":2263,"level":"N1","type":"主词条","word":"何気ない","kana":"なにげない","pos":"[イ形]","accent":"④","meaning":"若无其事","example":"何気ない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“若无其事”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n何気ない場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“若无其事”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2264","seq":2264,"level":"N1","type":"主词条","word":"なにとぞ","kana":"なにとぞ","pos":"[副]","accent":"⓪","meaning":"请，务必","example":"今回の変更でご不便をおかけしますが、なにとぞご理解くださいますようお願い申し上げます。","exampleZh":"这次变更给各位带来不便，恳请务必予以理解。","note":"例：\n今回の変更でご不便をおかけしますが、なにとぞご理解くださいますようお願い申し上げます。\n译：这次变更给各位带来不便，恳请务必予以理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2265","seq":2265,"level":"N1","type":"主词条","word":"何より","kana":"なにより","pos":"[名·副]","accent":"①⓪","meaning":"比什么（都好），最","example":"この仕事で何より大切なのは、相手の話を最後まで聞き、表面的な要望の奥にある困り事をつかむことだ。","exampleZh":"这项工作中最重要的是把对方的话听到最后，并抓住表面需求背后的困难。","note":"例：\nこの仕事で何より大切なのは、相手の話を最後まで聞き、表面的な要望の奥にある困り事をつかむことだ。\n译：这项工作中最重要的是把对方的话听到最后，并抓住表面需求背后的困难。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2266","seq":2266,"level":"N1","type":"主词条","word":"ナプキン","kana":"なぷきん（napkin）","pos":"[名]","accent":"①","meaning":"餐巾，小毛巾；卫生纸","example":"ナプキンの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“餐巾，小毛巾；卫生纸”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nナプキンの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“餐巾，小毛巾；卫生纸”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2267","seq":2267,"level":"N1","type":"主词条","word":"生臭い","kana":"なまぐさい","pos":"[イ形]","accent":"④","meaning":"腥，膻","example":"生臭い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“腥，膻”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n生臭い印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“腥，膻”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2268","seq":2268,"level":"N1","type":"主词条","word":"生々しい","kana":"なまなましい","pos":"[イ形]","accent":"⑤","meaning":"非常新；生动","example":"生々しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“非常新；生动”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n生々しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“非常新；生动”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2269","seq":2269,"level":"N1","type":"主词条","word":"生温い","kana":"なまぬるい","pos":"[イ形]","accent":"④⓪","meaning":"微温；不严格，不彻底","example":"生温いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“微温；不严格，不彻底”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n生温いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“微温；不严格，不彻底”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2270","seq":2270,"level":"N1","type":"主词条","word":"生身","kana":"なまみ","pos":"[名]","accent":"②⓪","meaning":"肉身，活人","example":"店主は生身の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“肉身，活人”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主は生身の味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“肉身，活人”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2271","seq":2271,"level":"N1","type":"主词条","word":"訛り","kana":"なまり","pos":"[名]","accent":"③","meaning":"乡音，地方口音","example":"観光客が増えた訛りでは、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“乡音，地方口音”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた訛りでは、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“乡音，地方口音”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2272","seq":2272,"level":"N1","type":"主词条","word":"並大抵","kana":"なみたいてい","pos":"[名·ナ形]","accent":"⓪","meaning":"普通，寻常（后多接否定句）","example":"並大抵な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“普通，寻常”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n並大抵な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“普通，寻常”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2273","seq":2273,"level":"N1","type":"主词条","word":"滑らか","kana":"なめらか","pos":"[ナ形]","accent":"②","meaning":"光滑；顺利","example":"周囲から滑らかだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“光滑；顺利”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から滑らかだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“光滑；顺利”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2274","seq":2274,"level":"N1","type":"主词条","word":"舐める/嘗める","kana":"なめる","pos":"[他動2]","accent":"②","meaning":"舔，尝；经历；轻视","example":"舐めることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“舔，尝；经历”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n舐めることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“舔，尝；经历”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2275","seq":2275,"level":"N1","type":"主词条","word":"悩ましい","kana":"なやましい","pos":"[イ形]","accent":"④","meaning":"烦恼的","example":"悩ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“烦恼的”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n悩ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“烦恼的”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2276","seq":2276,"level":"N1","type":"主词条","word":"馴らす","kana":"ならす","pos":"[他動1]","accent":"②","meaning":"驯服，驯养","example":"馴らす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“驯服，驯养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n馴らす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“驯服，驯养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2277","seq":2277,"level":"N1","type":"主词条","word":"慣らす","kana":"ならす","pos":"[他動1]","accent":"②","meaning":"使习惯，使适应","example":"慣らす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“使习惯，使适应”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n慣らす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“使习惯，使适应”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2278","seq":2278,"level":"N1","type":"主词条","word":"～慣らす","kana":"～ならす","pos":"[接尾]","accent":"","meaning":"……惯","example":"新しい靴を少しずつ履き慣らしたおかげで、長距離を歩く本番の日にも足を痛めずに済んだ。","exampleZh":"多亏一点点把新鞋穿惯，正式长距离步行当天也没有磨伤脚。","note":"例：\n新しい靴を少しずつ履き慣らしたおかげで、長距離を歩く本番の日にも足を痛めずに済んだ。\n译：多亏一点点把新鞋穿惯，正式长距离步行当天也没有磨伤脚。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2279","seq":2279,"level":"N1","type":"主词条","word":"ならびに","kana":"ならびに","pos":"[接]","accent":"⓪","meaning":"及，和","example":"彼女は失敗の原因を認めた。ならびに、同じミスを防ぐための手順もその場で提案した。","exampleZh":"她承认了失败原因。“及，和”，还当场提出了防止同样错误的流程。","note":"例：\n彼女は失敗の原因を認めた。ならびに、同じミスを防ぐための手順もその場で提案した。\n译：她承认了失败原因。“及，和”，还当场提出了防止同样错误的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2280","seq":2280,"level":"N1","type":"主词条","word":"鳴り物入り","kana":"なりものいり","pos":"[名]","accent":"⓪","meaning":"敲锣打鼓；大张旗鼓","example":"鳴り物入りで始まった企画ほど、実際の成果を冷静に検証しなければ期待だけが先行してしまう。","exampleZh":"越是大张旗鼓开始的企划，越必须冷静验证实际成果，否则只会让期待先行。","note":"例：\n鳴り物入りで始まった企画ほど、実際の成果を冷静に検証しなければ期待だけが先行してしまう。\n译：越是大张旗鼓开始的企划，越必须冷静验证实际成果，否则只会让期待先行。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2281","seq":2281,"level":"N1","type":"主词条","word":"成り行き","kana":"なりゆき","pos":"[名]","accent":"⓪","meaning":"趋势，推移","example":"成り行きをきっかけに、それまで曖昧だった責任の所在が問われ、組織の対応方針が見直された。","exampleZh":"以事情的推移为契机，此前含糊的责任所在受到追问，组织应对方针被重新审视。","note":"例：\n成り行きをきっかけに、それまで曖昧だった責任の所在が問われ、組織の対応方針が見直された。\n译：以事情的推移为契机，此前含糊的责任所在受到追问，组织应对方针被重新审视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2282","seq":2282,"level":"N1","type":"主词条","word":"なるたけ","kana":"なるたけ","pos":"[副]","accent":"⓪","meaning":"尽量，尽可能","example":"混雑を避けるため、申請書はなるたけ早めに提出し、不備がないか事前に確認しておいたほうがよい。","exampleZh":"为避免拥挤，申请书最好尽早提交，并提前确认是否有缺漏。","note":"例：\n混雑を避けるため、申請書はなるたけ早めに提出し、不備がないか事前に確認しておいたほうがよい。\n译：为避免拥挤，申请书最好尽早提交，并提前确认是否有缺漏。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2283","seq":2283,"level":"N1","type":"主词条","word":"慣れ","kana":"なれ","pos":"[名]","accent":"②","meaning":"习惯","example":"作業への慣れから確認を省いたことが事故につながり、現場では基本手順の大切さが改めて共有された。","exampleZh":"因为习惯作业而省略确认导致事故，现场重新共享了基本步骤的重要性。","note":"例：\n作業への慣れから確認を省いたことが事故につながり、現場では基本手順の大切さが改めて共有された。\n译：因为习惯作业而省略确认导致事故，现场重新共享了基本步骤的重要性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2284","seq":2284,"level":"N1","type":"主词条","word":"馴れ初め","kana":"なれそめ","pos":"[名]","accent":"⓪","meaning":"发生恋爱关系的开端","example":"二人の馴れ初めを聞くと、偶然の出会いの裏に、共通の友人のさりげない気遣いがあった。","exampleZh":"听到两人相识相恋的开端后，才知道偶然相遇背后还有共同朋友不动声色的体贴。","note":"例：\n二人の馴れ初めを聞くと、偶然の出会いの裏に、共通の友人のさりげない気遣いがあった。\n译：听到两人相识相恋的开端后，才知道偶然相遇背后还有共同朋友不动声色的体贴。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2285","seq":2285,"level":"N1","type":"主词条","word":"馴れ馴れしい","kana":"なれなれしい","pos":"[イ形]","accent":"⑤","meaning":"过分亲昵","example":"馴れ馴れしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“过分亲昵”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n馴れ馴れしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“过分亲昵”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2286","seq":2286,"level":"N1","type":"主词条","word":"難航","kana":"なんこう","pos":"[名·自動3]","accent":"⓪","meaning":"进展迟缓","example":"難航した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“进展迟缓”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n難航した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“进展迟缓”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2287","seq":2287,"level":"N1","type":"主词条","word":"難色","kana":"なんしょく","pos":"[名]","accent":"⓪","meaning":"为难的神色","example":"難色をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“为难的神色”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n難色をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“为难的神色”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2288","seq":2288,"level":"N1","type":"主词条","word":"ナンセンス","kana":"なんせんす（nonsense）","pos":"[名·ナ形]","accent":"①","meaning":"无聊，荒谬","example":"一度ナンセンスだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“无聊，荒谬”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度ナンセンスだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“无聊，荒谬”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2289","seq":2289,"level":"N1","type":"主词条","word":"なんだか","kana":"なんだか","pos":"[副]","accent":"①","meaning":"（不知为何）总觉得，不由得","example":"今日はなんだか胸騒ぎがして、彼は出発前にもう一度鍵と資料を確認した。","exampleZh":"今天总觉得心神不宁，他出发前又一次确认了钥匙和资料。","note":"例：\n今日はなんだか胸騒ぎがして、彼は出発前にもう一度鍵と資料を確認した。\n译：今天总觉得心神不宁，他出发前又一次确认了钥匙和资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2290","seq":2290,"level":"N1","type":"主词条","word":"なんだかんだ","kana":"なんだかんだ","pos":"[副]","accent":"④","meaning":"这个那个，这样那样","example":"なんだかんだ言いながらも、彼は最後まで後輩の準備を手伝い、発表を見届けた。","exampleZh":"他嘴上说这说那，但还是一直帮后辈准备到最后，并看完了发表。","note":"例：\nなんだかんだ言いながらも、彼は最後まで後輩の準備を手伝い、発表を見届けた。\n译：他嘴上说这说那，但还是一直帮后辈准备到最后，并看完了发表。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2291","seq":2291,"level":"N1","type":"主词条","word":"なんでもかんでも","kana":"なんでもかんでも","pos":"[副]","accent":"⑤","meaning":"全部；不管怎样","example":"なんでもかんでも上司に確認していては判断力が育たないので、まず自分で根拠を整理することが大切だ。","exampleZh":"如果什么都向上司确认，判断力就培养不起来，所以首先自己整理依据很重要。","note":"例：\nなんでもかんでも上司に確認していては判断力が育たないので、まず自分で根拠を整理することが大切だ。\n译：如果什么都向上司确认，判断力就培养不起来，所以首先自己整理依据很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2292","seq":2292,"level":"N1","type":"主词条","word":"何なりと","kana":"なんなりと","pos":"[副]","accent":"①","meaning":"无论什么","example":"不明な点がありましたら何なりとお尋ねくださいと、担当者は参加者に丁寧に声をかけた。","exampleZh":"负责人礼貌地告诉参加者：“如有不明之处，请随时提问。”","note":"例：\n不明な点がありましたら何なりとお尋ねくださいと、担当者は参加者に丁寧に声をかけた。\n译：负责人礼貌地告诉参加者：“如有不明之处，请随时提问。”","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2293","seq":2293,"level":"N1","type":"主词条","word":"なんら","kana":"なんら","pos":"[副]","accent":"①","meaning":"（后接否定）任何，丝毫","example":"今回の変更は利用者の権利をなんら制限するものではなく、手続きを分かりやすくするためのものだ。","exampleZh":"这次变更绝不会限制使用者权利，而是为了让手续更易懂。","note":"例：\n今回の変更は利用者の権利をなんら制限するものではなく、手続きを分かりやすくするためのものだ。\n译：这次变更绝不会限制使用者权利，而是为了让手续更易懂。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2294","seq":2294,"level":"N1","type":"主词条","word":"なんらか","kana":"なんらか","pos":"[副]","accent":"④①","meaning":"稍微，一些","example":"調査結果から、生活環境の変化が子どもの学習意欲に何らかの影響を与えている可能性が示された。","exampleZh":"调查结果显示，生活环境变化可能对孩子学习积极性产生了某种影响。","note":"例：\n調査結果から、生活環境の変化が子どもの学習意欲に何らかの影響を与えている可能性が示された。\n译：调查结果显示，生活环境变化可能对孩子学习积极性产生了某种影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2295","seq":2295,"level":"N1","type":"主词条","word":"荷","kana":"に","pos":"[名]","accent":"①","meaning":"货物，行李；负担，责任","example":"重い荷を一人で運ぼうとした彼に、同僚が声をかけて台車を用意してくれた。","exampleZh":"看到他想一个人搬重物，同事上前搭话并帮他准备了手推车。","note":"例：\n重い荷を一人で運ぼうとした彼に、同僚が声をかけて台車を用意してくれた。\n译：看到他想一个人搬重物，同事上前搭话并帮他准备了手推车。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2296","seq":2296,"level":"N1","type":"主词条","word":"煮え切らない","kana":"にえきらない","pos":"[連語]","accent":"④","meaning":"暧昧，不干脆","example":"彼の煮え切らない返事に、担当者は期限までに明確な判断を求めた。","exampleZh":"面对他不干脆的回答，负责人要求他在期限前作出明确判断。","note":"例：\n彼の煮え切らない返事に、担当者は期限までに明確な判断を求めた。\n译：面对他不干脆的回答，负责人要求他在期限前作出明确判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2297","seq":2297,"level":"N1","type":"主词条","word":"似通う","kana":"にかよう","pos":"[自動1]","accent":"③","meaning":"相仿，相似","example":"似通うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“相仿，相似”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n似通うような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“相仿，相似”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2298","seq":2298,"level":"N1","type":"主词条","word":"賑わう","kana":"にぎわう","pos":"[自動1]","accent":"③","meaning":"热闹，拥挤；兴盛","example":"祭りの日の商店街は朝から賑わい、普段は閉まっている店にも長い列ができた。","exampleZh":"祭日的商店街从早上起就很热闹，平时关门的店也排起了长队。","note":"例：\n祭りの日の商店街は朝から賑わい、普段は閉まっている店にも長い列ができた。\n译：祭日的商店街从早上起就很热闹，平时关门的店也排起了长队。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2299","seq":2299,"level":"N1","type":"主词条","word":"憎しみ","kana":"にくしみ","pos":"[名]","accent":"⓪④","meaning":"憎恨","example":"憎しみを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“憎恨”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n憎しみを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“憎恨”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2300","seq":2300,"level":"N1","type":"主词条","word":"憎たらしい","kana":"にくたらしい","pos":"[イ形]","accent":"⑤","meaning":"极其可憎，极其可恶","example":"憎たらしいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。","exampleZh":"即使用“极其可憎，极其可恶”的做法获得利益，只要失去对方信任，长期来看就会造成巨大损失。","note":"例：\n憎たらしいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。\n译：即使用“极其可憎，极其可恶”的做法获得利益，只要失去对方信任，长期来看就会造成巨大损失。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2301","seq":2301,"level":"N1","type":"主词条","word":"滲む","kana":"にじむ","pos":"[自動1]","accent":"②","meaning":"渗，渗出","example":"滲む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“渗，渗出”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n滲む場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“渗，渗出”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2302","seq":2302,"level":"N1","type":"主词条","word":"似たり寄ったり","kana":"にたりよったり","pos":"[名·ナ形]","accent":"②④","meaning":"半斤八两，大同小异","example":"似たり寄ったりな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“半斤八两，大同小异”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n似たり寄ったりな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“半斤八两，大同小异”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2303","seq":2303,"level":"N1","type":"主词条","word":"荷造り","kana":"にづくり","pos":"[名·自他動3]","accent":"②","meaning":"打包（行李货物）","example":"引っ越しの荷造りを早めに始めたおかげで、当日は必要な書類を慌てて探さずに済んだ。","exampleZh":"多亏很早开始打包搬家行李，搬家当天不用慌忙寻找必要文件。","note":"例：\n引っ越しの荷造りを早めに始めたおかげで、当日は必要な書類を慌てて探さずに済んだ。\n译：多亏很早开始打包搬家行李，搬家当天不用慌忙寻找必要文件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2304","seq":2304,"level":"N1","type":"主词条","word":"日数","kana":"にっすう","pos":"[名]","accent":"③","meaning":"日数，天数","example":"日数の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“日数，天数”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n日数の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“日数，天数”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2305","seq":2305,"level":"N1","type":"主词条","word":"担う","kana":"になう","pos":"[他動1]","accent":"②","meaning":"担负","example":"担うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“担负”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n担うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“担负”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2306","seq":2306,"level":"N1","type":"主词条","word":"鈍る","kana":"にぶる","pos":"[自動1]","accent":"②","meaning":"（刀具等）变钝；（感觉等）变迟钝；（能力等）变差","example":"勢いが少しずつ鈍る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“变钝；变迟钝”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ鈍る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“变钝；变迟钝”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2307","seq":2307,"level":"N1","type":"主词条","word":"ニュアンス","kana":"にゅあんす","pos":"[名]","accent":"①","meaning":"微妙的感觉","example":"同じ言葉でもニュアンスが少し違うだけで、相手に与える印象は大きく変わる。","exampleZh":"同样的话只要语气细微不同，给对方的印象就会大不相同。","note":"例：\n同じ言葉でもニュアンスが少し違うだけで、相手に与える印象は大きく変わる。\n译：同样的话只要语气细微不同，给对方的印象就会大不相同。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2308","seq":2308,"level":"N1","type":"主词条","word":"入荷","kana":"にゅうか","pos":"[名·他動3]","accent":"⓪","meaning":"进货，到货","example":"彼は入荷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“进货，到货”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は入荷を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“进货，到货”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2309","seq":2309,"level":"N1","type":"主词条","word":"入居","kana":"にゅうきょ","pos":"[名·自動3]","accent":"⓪","meaning":"住进，搬进","example":"予期せず入居した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“住进，搬进”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず入居した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“住进，搬进”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2310","seq":2310,"level":"N1","type":"主词条","word":"入手","kana":"にゅうしゅ","pos":"[名·他動3]","accent":"⓪①","meaning":"得到，到手","example":"入手する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“得到，到手”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n入手する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“得到，到手”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2311","seq":2311,"level":"N1","type":"主词条","word":"入賞","kana":"にゅうしょう","pos":"[名·自動3]","accent":"⓪","meaning":"获奖","example":"入賞した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“获奖”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n入賞した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“获奖”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2312","seq":2312,"level":"N1","type":"主词条","word":"入浴","kana":"にゅうよく","pos":"[名·自動3]","accent":"⓪","meaning":"沐浴，洗澡","example":"入浴する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“沐浴，洗澡”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n入浴する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“沐浴，洗澡”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2313","seq":2313,"level":"N1","type":"主词条","word":"如実","kana":"にょじつ","pos":"[副]","accent":"⓪①","meaning":"真实，如实","example":"この数字は地域による医療格差を如実に示しており、早急な対策の必要性を物語っている。","exampleZh":"这个数字如实显示了地区间医疗差距，也说明了尽快采取对策的必要性。","note":"例：\nこの数字は地域による医療格差を如実に示しており、早急な対策の必要性を物語っている。\n译：这个数字如实显示了地区间医疗差距，也说明了尽快采取对策的必要性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2314","seq":2314,"level":"N1","type":"主词条","word":"人情","kana":"にんじょう","pos":"[名]","accent":"①","meaning":"人情，情义","example":"その人情は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“人情，情义”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその人情は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“人情，情义”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2315","seq":2315,"level":"N1","type":"主词条","word":"忍耐力","kana":"にんたいりょく","pos":"[名]","accent":"③","meaning":"忍耐力","example":"忍耐力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。","exampleZh":"感到“忍耐力”不足后，他观察有经验者的做法，并将其纳入每日练习。","note":"例：\n忍耐力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。\n译：感到“忍耐力”不足后，他观察有经验者的做法，并将其纳入每日练习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2316","seq":2316,"level":"N1","type":"主词条","word":"認知症","kana":"にんちしょう","pos":"[名]","accent":"⓪","meaning":"痴呆症","example":"認知症が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“痴呆症”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n認知症が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“痴呆症”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2317","seq":2317,"level":"N1","type":"主词条","word":"任務","kana":"にんむ","pos":"[名]","accent":"①","meaning":"任务","example":"任務が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“任务”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n任務が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“任务”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2318","seq":2318,"level":"N1","type":"主词条","word":"任命","kana":"にんめい","pos":"[名·他動3]","accent":"⓪","meaning":"任命","example":"任命する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“任命”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n任命する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“任命”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2319","seq":2319,"level":"N1","type":"主词条","word":"抜きん出る","kana":"ぬきんでる","pos":"[自動2]","accent":"④","meaning":"超群，出类拔萃","example":"抜きん出るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“超群，出类拔萃”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n抜きん出るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“超群，出类拔萃”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2320","seq":2320,"level":"N1","type":"主词条","word":"抜け出す","kana":"ぬけだす","pos":"[自動1]","accent":"③","meaning":"偷偷溜走；开始脱落","example":"会議を抜け出すわけにはいかず、彼は急ぎの電話を休憩時間まで待つことにした。","exampleZh":"不能从会议中溜走，他决定把紧急电话等到休息时间再打。","note":"例：\n会議を抜け出すわけにはいかず、彼は急ぎの電話を休憩時間まで待つことにした。\n译：不能从会议中溜走，他决定把紧急电话等到休息时间再打。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2321","seq":2321,"level":"N1","type":"主词条","word":"主","kana":"ぬし","pos":"[名]","accent":"①","meaning":"主人，物主","example":"その主は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“主人，物主”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその主は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“主人，物主”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2322","seq":2322,"level":"N1","type":"主词条","word":"～主","kana":"～ぬし","pos":"[接尾]","accent":"","meaning":"……的拥有者，所有者","example":"土地の持ち主を探している間に、古い登記情報と近所の人の記憶が重要な手がかりになった。","exampleZh":"在寻找土地所有者的过程中，旧登记信息和邻居记忆成了重要线索。","note":"例：\n土地の持ち主を探している間に、古い登記情報と近所の人の記憶が重要な手がかりになった。\n译：在寻找土地所有者的过程中，旧登记信息和邻居记忆成了重要线索。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2323","seq":2323,"level":"N1","type":"主词条","word":"沼","kana":"ぬま","pos":"[名]","accent":"②","meaning":"沼泽","example":"沼が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“沼泽”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n沼が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“沼泽”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2324","seq":2324,"level":"N1","type":"主词条","word":"音","kana":"ね","pos":"[名]","accent":"⓪","meaning":"声音，音色（おと仅表示声响）","example":"音の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“声音，音色”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n音の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“声音，音色”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2325","seq":2325,"level":"N1","type":"主词条","word":"寝入る","kana":"ねいる","pos":"[自動1]","accent":"②","meaning":"睡着，入睡；熟睡","example":"寝入るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“睡着，入睡；熟睡”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n寝入るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“睡着，入睡；熟睡”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2326","seq":2326,"level":"N1","type":"主词条","word":"値打ち","kana":"ねうち","pos":"[名]","accent":"⓪","meaning":"价值","example":"担当者は値打ちを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“价值”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者は値打ちを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“价值”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2327","seq":2327,"level":"N1","type":"主词条","word":"ネーミング","kana":"ねーみんぐ（naming）","pos":"[名]","accent":"⓪","meaning":"名字","example":"商品のネーミングが印象的だったため、広告を見た人の記憶に残りやすかった。","exampleZh":"商品命名很有印象，因此容易留在看到广告的人记忆中。","note":"例：\n商品のネーミングが印象的だったため、広告を見た人の記憶に残りやすかった。\n译：商品命名很有印象，因此容易留在看到广告的人记忆中。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2328","seq":2328,"level":"N1","type":"主词条","word":"ネームバリュー","kana":"ねーむばりゅー","pos":"[名]","accent":"④","meaning":"声誉，名声","example":"ネームバリューを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“声誉，名声”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nネームバリューを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“声誉，名声”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2329","seq":2329,"level":"N1","type":"主词条","word":"ネガ","kana":"ねが","pos":"[名]","accent":"①","meaning":"（相机）底片；否定","example":"ネガの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“底片；否定”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\nネガの安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“底片；否定”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2330","seq":2330,"level":"N1","type":"主词条","word":"値切る","kana":"ねぎる","pos":"[他動1]","accent":"②⓪","meaning":"讲价，还价","example":"相手に何かを値切るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“讲价，还价”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを値切るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“讲价，还价”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2331","seq":2331,"level":"N1","type":"主词条","word":"ねじ回し","kana":"ねじまわし","pos":"[名]","accent":"③","meaning":"螺丝刀，螺丝起子","example":"ねじ回しを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“螺丝刀，螺丝起子”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nねじ回しを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“螺丝刀，螺丝起子”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2332","seq":2332,"level":"N1","type":"主词条","word":"捩れる","kana":"ねじれる","pos":"[自動2]","accent":"③","meaning":"弯曲，扭歪；乖僻","example":"古い配線が無理に曲げられて捩れると、見た目には分からなくても内部で断線していることがある。","exampleZh":"旧电线被勉强弯折扭曲后，即使外观看不出来，内部也可能已经断线。","note":"例：\n古い配線が無理に曲げられて捩れると、見た目には分からなくても内部で断線していることがある。\n译：旧电线被勉强弯折扭曲后，即使外观看不出来，内部也可能已经断线。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2333","seq":2333,"level":"N1","type":"主词条","word":"寝相","kana":"ねぞう","pos":"[名]","accent":"⓪","meaning":"睡觉的姿势，睡相","example":"寝相を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“睡觉的姿势，睡相”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n寝相を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“睡觉的姿势，睡相”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2334","seq":2334,"level":"N1","type":"主词条","word":"妬ましい","kana":"ねたましい","pos":"[イ形]","accent":"④","meaning":"令人嫉妒","example":"妬ましい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“令人嫉妒”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n妬ましい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“令人嫉妒”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2335","seq":2335,"level":"N1","type":"主词条","word":"妬む","kana":"ねたむ","pos":"[他動1]","accent":"②","meaning":"嫉妒","example":"妬むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“嫉妒”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n妬むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“嫉妒”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2336","seq":2336,"level":"N1","type":"主词条","word":"強請る","kana":"ねだる","pos":"[他動1]","accent":"⓪","meaning":"硬要，央求，强求","example":"強請る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“硬要，央求，强求”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n強請る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“硬要，央求，强求”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2337","seq":2337,"level":"N1","type":"主词条","word":"熱意","kana":"ねつい","pos":"[名]","accent":"⓪","meaning":"热情，干劲","example":"熱意が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“热情，干劲”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n熱意が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“热情，干劲”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2338","seq":2338,"level":"N1","type":"主词条","word":"ネック","kana":"ねっく（neck）","pos":"[名]","accent":"①","meaning":"瓶颈，难关","example":"ネックを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“瓶颈，难关”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nネックを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“瓶颈，难关”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2339","seq":2339,"level":"N1","type":"主词条","word":"熱弁","kana":"ねつべん","pos":"[名]","accent":"⓪","meaning":"热情洋溢的讲话","example":"熱弁の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“热情洋溢的讲话”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\n熱弁の内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“热情洋溢的讲话”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2340","seq":2340,"level":"N1","type":"主词条","word":"粘り","kana":"ねばり","pos":"[名]","accent":"③","meaning":"黏性；耐性，毅力","example":"最後まで粘りを見せた交渉担当者は、相手の妥協点を丁寧に探り、契約成立にこぎつけた。","exampleZh":"显示出坚持到底毅力的谈判负责人，细致寻找对方妥协点，最终促成合同成立。","note":"例：\n最後まで粘りを見せた交渉担当者は、相手の妥協点を丁寧に探り、契約成立にこぎつけた。\n译：显示出坚持到底毅力的谈判负责人，细致寻找对方妥协点，最终促成合同成立。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2341","seq":2341,"level":"N1","type":"主词条","word":"粘り強い","kana":"ねばりづよい","pos":"[イ形]","accent":"⑤","meaning":"黏性大；坚韧，有毅力","example":"粘り強い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“黏性大；坚韧，有毅力”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n粘り強い状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“黏性大；坚韧，有毅力”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2342","seq":2342,"level":"N1","type":"主词条","word":"粘る","kana":"ねばる","pos":"[自動1]","accent":"②","meaning":"发黏；坚持不懈；赖着不走","example":"自分の道を粘るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“发黏；坚持不懈”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を粘るなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“发黏；坚持不懈”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2343","seq":2343,"level":"N1","type":"主词条","word":"根回し","kana":"ねまわし","pos":"[名·自動3]","accent":"②","meaning":"事前疏通","example":"予期せず根回しした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“事前疏通”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず根回しした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“事前疏通”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2344","seq":2344,"level":"N1","type":"主词条","word":"練る","kana":"ねる","pos":"[自他動1]","accent":"①","meaning":"推敲，研究","example":"企画を練る段階で反対意見も取り入れたため、最終案には現場の不安がかなり反映された。","exampleZh":"在推敲企划阶段也吸收了反对意见，因此最终方案相当程度反映了现场不安。","note":"例：\n企画を練る段階で反対意見も取り入れたため、最終案には現場の不安がかなり反映された。\n译：在推敲企划阶段也吸收了反对意见，因此最终方案相当程度反映了现场不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2345","seq":2345,"level":"N1","type":"主词条","word":"念","kana":"ねん","pos":"[名]","accent":"①⓪","meaning":"念头；注意，用心","example":"念に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“念头；注意，用心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n念に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“念头；注意，用心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2346","seq":2346,"level":"N1","type":"主词条","word":"念入り","kana":"ねんいり","pos":"[名·ナ形]","accent":"⓪④","meaning":"周到，细致","example":"念入りな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“周到，细致”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n念入りな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“周到，细致”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2347","seq":2347,"level":"N1","type":"主词条","word":"年賀","kana":"ねんが","pos":"[名]","accent":"①⓪","meaning":"贺新年","example":"年賀の挨拶を送る相手を見直し、彼は形式だけの関係を少しずつ整理することにした。","exampleZh":"他重新审视了要寄送新年问候的对象，决定逐渐整理只剩形式的人际关系。","note":"例：\n年賀の挨拶を送る相手を見直し、彼は形式だけの関係を少しずつ整理することにした。\n译：他重新审视了要寄送新年问候的对象，决定逐渐整理只剩形式的人际关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2348","seq":2348,"level":"N1","type":"主词条","word":"念願","kana":"ねんがん","pos":"[名·他動3]","accent":"⓪③","meaning":"愿望，心愿","example":"彼は念願を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“愿望，心愿”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は念願を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“愿望，心愿”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2349","seq":2349,"level":"N1","type":"主词条","word":"年功序列","kana":"ねんこうじょれつ","pos":"[名]","accent":"⓪⑤","meaning":"按资排辈","example":"年功序列を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“按资排辈”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n年功序列を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“按资排辈”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2350","seq":2350,"level":"N1","type":"主词条","word":"捻出","kana":"ねんしゅつ","pos":"[名·他動3]","accent":"⓪","meaning":"想出；筹措","example":"捻出する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“想出；筹措”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n捻出する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“想出；筹措”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2351","seq":2351,"level":"N1","type":"主词条","word":"燃焼","kana":"ねんしょう","pos":"[名·自他動3]","accent":"⓪","meaning":"燃烧","example":"燃焼する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“燃烧”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n燃焼する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“燃烧”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2352","seq":2352,"level":"N1","type":"主词条","word":"粘着","kana":"ねんちゃく","pos":"[名·自動3]","accent":"⓪","meaning":"黏着","example":"粘着する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“黏着”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n粘着する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“黏着”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2353","seq":2353,"level":"N1","type":"主词条","word":"年長","kana":"ねんちょう","pos":"[名·ナ形]","accent":"⓪","meaning":"年长","example":"年長の社員だからといって経験を押しつけず、彼は若い人の新しい発想にも耳を傾けた。","exampleZh":"他没有因为自己年长就把经验强加给别人，也倾听年轻人的新想法。","note":"例：\n年長の社員だからといって経験を押しつけず、彼は若い人の新しい発想にも耳を傾けた。\n译：他没有因为自己年长就把经验强加给别人，也倾听年轻人的新想法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2354","seq":2354,"level":"N1","type":"主词条","word":"ノイローゼ","kana":"のいろーぜ","pos":"[名]","accent":"③","meaning":"神经衰弱","example":"ノイローゼを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“神经衰弱”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nノイローゼを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“神经衰弱”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2355","seq":2355,"level":"N1","type":"主词条","word":"納期","kana":"のうき","pos":"[名]","accent":"①","meaning":"交货期","example":"納期をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“交货期”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n納期をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“交货期”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2356","seq":2356,"level":"N1","type":"主词条","word":"納入","kana":"のうにゅう","pos":"[名·他動3]","accent":"⓪","meaning":"缴纳，上缴","example":"彼は納入を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“缴纳，上缴”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は納入を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“缴纳，上缴”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2357","seq":2357,"level":"N1","type":"主词条","word":"ノウハウ","kana":"のうはう（know-how）","pos":"[名]","accent":"①","meaning":"技术窍门，技术秘诀","example":"長年現場で蓄積されたノウハウは、マニュアルに書き切れない判断の細部にこそ表れている。","exampleZh":"多年在现场积累的诀窍，恰恰体现在手册写不尽的判断细节中。","note":"例：\n長年現場で蓄積されたノウハウは、マニュアルに書き切れない判断の細部にこそ表れている。\n译：多年在现场积累的诀窍，恰恰体现在手册写不尽的判断细节中。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2358","seq":2358,"level":"N1","type":"主词条","word":"納品","kana":"のうひん","pos":"[名·自他動3]","accent":"⓪","meaning":"交货","example":"納品する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“交货”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n納品する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“交货”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2359","seq":2359,"level":"N1","type":"主词条","word":"濃密","kana":"のうみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"浓厚，浓密","example":"周囲から濃密だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“浓厚，浓密”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から濃密だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“浓厚，浓密”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2360","seq":2360,"level":"N1","type":"主词条","word":"逃す","kana":"のがす","pos":"[他動1]","accent":"②","meaning":"放跑；漏掉，错过","example":"無理に逃すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“放跑；漏掉，错过”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に逃すと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“放跑；漏掉，错过”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2361","seq":2361,"level":"N1","type":"主词条","word":"逃れる","kana":"のがれる","pos":"[自動2]","accent":"③","meaning":"逃脱，摆脱","example":"自分の道を逃れるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“逃脱，摆脱”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を逃れるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“逃脱，摆脱”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2362","seq":2362,"level":"N1","type":"主词条","word":"軒並み","kana":"のきなみ","pos":"[名·副]","accent":"⓪","meaning":"鳞次栉比；每家每户；都","example":"原材料費の高騰を受けて、近所の飲食店は軒並みメニューの価格を見直さざるを得なくなった。","exampleZh":"受原材料费高涨影响，附近餐饮店几乎都不得不重新审视菜单价格。","note":"例：\n原材料費の高騰を受けて、近所の飲食店は軒並みメニューの価格を見直さざるを得なくなった。\n译：受原材料费高涨影响，附近餐饮店几乎都不得不重新审视菜单价格。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2363","seq":2363,"level":"N1","type":"主词条","word":"望ましい","kana":"のぞましい","pos":"[イ形]","accent":"④⓪","meaning":"所希望的，理想的","example":"望ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“所希望的，理想的”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n望ましい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“所希望的，理想的”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2364","seq":2364,"level":"N1","type":"主词条","word":"臨む","kana":"のぞむ","pos":"[自動1]","accent":"⓪","meaning":"面临；参加，出席","example":"臨むとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“面临；参加，出席”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n臨むとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“面临；参加，出席”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2365","seq":2365,"level":"N1","type":"主词条","word":"乗っ取る","kana":"のっとる","pos":"[他動1]","accent":"③","meaning":"攻占，篡夺；劫持","example":"乗っ取る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“攻占，篡夺；劫持”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n乗っ取る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“攻占，篡夺；劫持”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2366","seq":2366,"level":"N1","type":"主词条","word":"長閑","kana":"のどか","pos":"[ナ形]","accent":"①","meaning":"恬静，和煦","example":"一度長閑だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“恬静，和煦”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度長閑だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“恬静，和煦”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2367","seq":2367,"level":"N1","type":"主词条","word":"罵る","kana":"ののしる","pos":"[他動1]","accent":"③","meaning":"谩骂","example":"罵る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“谩骂”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n罵る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“谩骂”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2368","seq":2368,"level":"N1","type":"主词条","word":"飲み込む","kana":"のみこむ","pos":"[他動1]","accent":"③⓪","meaning":"咽下，喝下；吞噬；理解","example":"飲み込むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“咽下，喝下；吞噬”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n飲み込むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“咽下，喝下；吞噬”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2369","seq":2369,"level":"N1","type":"主词条","word":"乗り出す","kana":"のりだす","pos":"[自他動1]","accent":"③","meaning":"乘（车船等）探出身体；着手","example":"相手に何かを乗り出すなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“乘探出身体；着手”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを乗り出すなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“乘探出身体；着手”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2370","seq":2370,"level":"N1","type":"主词条","word":"ノルマ","kana":"のるま","pos":"[名]","accent":"①","meaning":"指标","example":"ノルマをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“指标”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nノルマをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“指标”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2371","seq":2371,"level":"N1","type":"主词条","word":"～派","kana":"～は","pos":"[接尾]","accent":"","meaning":"……派，派别","example":"彼は改革派の政治家として知られているが、急激な変更には慎重な姿勢も見せている。","exampleZh":"他以改革派政治家闻名，但对急剧变更也表现出慎重态度。","note":"例：\n彼は改革派の政治家として知られているが、急激な変更には慎重な姿勢も見せている。\n译：他以改革派政治家闻名，但对急剧变更也表现出慎重态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2372","seq":2372,"level":"N1","type":"主词条","word":"把握","kana":"はあく","pos":"[名·他動3]","accent":"⓪","meaning":"掌握，理解","example":"彼は把握を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“掌握，理解”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は把握を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“掌握，理解”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2373","seq":2373,"level":"N1","type":"主词条","word":"バージョンアップ","kana":"ばーじょんあっぷ（version up）","pos":"[名·自他動3]","accent":"⑤","meaning":"版本升级","example":"バージョンアップの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“版本升级”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\nバージョンアップの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“版本升级”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2374","seq":2374,"level":"N1","type":"主词条","word":"場当たり","kana":"ばあたり","pos":"[名·ナ形]","accent":"②⓪","meaning":"即兴；临时，权宜","example":"一度場当たりだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“即兴；临时，权宜”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度場当たりだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“即兴；临时，权宜”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2375","seq":2375,"level":"N1","type":"主词条","word":"パートナー","kana":"ぱーとなー（partner）","pos":"[名]","accent":"①","meaning":"伙伴，合伙人；配偶","example":"経験豊かなパートナーの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“伙伴，合伙人；配偶”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなパートナーの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“伙伴，合伙人；配偶”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2376","seq":2376,"level":"N1","type":"主词条","word":"ハードル","kana":"はーどる（hurdle）","pos":"[名]","accent":"⓪","meaning":"跨栏；难关","example":"ハードルをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“跨栏；难关”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nハードルをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“跨栏；难关”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2377","seq":2377,"level":"N1","type":"主词条","word":"廃棄","kana":"はいき","pos":"[名·他動3]","accent":"①⓪","meaning":"废弃，废除","example":"廃棄した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“废弃，废除”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n廃棄した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“废弃，废除”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2378","seq":2378,"level":"N1","type":"主词条","word":"配給","kana":"はいきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"分配（物资）","example":"初めて配給する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“分配”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて配給する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“分配”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2379","seq":2379,"level":"N1","type":"主词条","word":"背景","kana":"はいけい","pos":"[名]","accent":"⓪","meaning":"背景；布景；（社会）背景","example":"古い背景でも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。","exampleZh":"即使是旧的“背景；布景”，只要持续保养，也能长久保持不受潮流左右的品味。","note":"例：\n古い背景でも手入れを続ければ、流行に左右されない品のよさを長く保つことができる。\n译：即使是旧的“背景；布景”，只要持续保养，也能长久保持不受潮流左右的品味。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2380","seq":2380,"level":"N1","type":"主词条","word":"背後","kana":"はいご","pos":"[名]","accent":"①","meaning":"背后","example":"背後の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“背后”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n背後の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“背后”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2381","seq":2381,"level":"N1","type":"主词条","word":"敗戦","kana":"はいせん","pos":"[名·自動3]","accent":"⓪","meaning":"战败","example":"敗戦した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“战败”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n敗戦した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“战败”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2382","seq":2382,"level":"N1","type":"主词条","word":"配線","kana":"はいせん","pos":"[名·自動3]","accent":"⓪","meaning":"配线，架线","example":"配線する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“配线，架线”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n配線する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“配线，架线”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2383","seq":2383,"level":"N1","type":"主词条","word":"配置","kana":"はいち","pos":"[名·他動3]","accent":"⓪①","meaning":"配置，布置","example":"情報を配置する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。","exampleZh":"在“配置，布置”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","note":"例：\n情報を配置する際には、見た目の整え方だけでなく、利用者が迷わず比較できる流れも重要だ。\n译：在“配置，布置”信息时，不仅要注意外观整理，也要重视让使用者能够顺畅比较的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2384","seq":2384,"level":"N1","type":"主词条","word":"ハイテク","kana":"はいてく","pos":"[名]","accent":"⓪","meaning":"高新技术","example":"ハイテクを身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“高新技术”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\nハイテクを身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“高新技术”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2385","seq":2385,"level":"N1","type":"主词条","word":"ハイビジョン","kana":"はいびじょん","pos":"[名]","accent":"③","meaning":"高清电视","example":"ハイビジョンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“高清电视”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nハイビジョンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“高清电视”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2386","seq":2386,"level":"N1","type":"主词条","word":"配付","kana":"はいふ","pos":"[名·他動3]","accent":"⓪①","meaning":"分配，分发（给某个固定群体）","example":"会議資料を配付する前に、担当者はページ番号と印刷漏れがないかを確認した。","exampleZh":"分发会议资料前，负责人确认了页码和是否有漏印。","note":"例：\n会議資料を配付する前に、担当者はページ番号と印刷漏れがないかを確認した。\n译：分发会议资料前，负责人确认了页码和是否有漏印。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2387","seq":2387,"level":"N1","type":"主词条","word":"配布","kana":"はいふ","pos":"[名·他動3]","accent":"⓪①","meaning":"散发，广为分发","example":"配布の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“散发，广为分发”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n配布の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“散发，广为分发”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2388","seq":2388,"level":"N1","type":"主词条","word":"配分","kana":"はいぶん","pos":"[名·他動3]","accent":"⓪","meaning":"分配，分摊","example":"彼は配分を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“分配，分摊”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は配分を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“分配，分摊”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2389","seq":2389,"level":"N1","type":"主词条","word":"敗北","kana":"はいぼく","pos":"[名·自動3]","accent":"⓪","meaning":"战败，（比赛）失败","example":"予期せず敗北した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“战败，失败”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず敗北した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“战败，失败”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2390","seq":2390,"level":"N1","type":"主词条","word":"配列","kana":"はいれつ","pos":"[名·他動3]","accent":"⓪","meaning":"排列，排布","example":"データの配列を少し変えるだけで傾向が見やすくなり、会議での検討も格段に進めやすくなった。","exampleZh":"只要稍微改变数据排列，趋势就更容易看清，会议讨论也明显更容易推进。","note":"例：\nデータの配列を少し変えるだけで傾向が見やすくなり、会議での検討も格段に進めやすくなった。\n译：只要稍微改变数据排列，趋势就更容易看清，会议讨论也明显更容易推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2391","seq":2391,"level":"N1","type":"主词条","word":"映える","kana":"はえる","pos":"[自動2]","accent":"②","meaning":"照耀；显眼，显得好看","example":"映えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“照耀；显眼，显得好看”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n映えるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“照耀；显眼，显得好看”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2392","seq":2392,"level":"N1","type":"主词条","word":"捗る","kana":"はかどる","pos":"[自動1]","accent":"③","meaning":"进展顺利","example":"捗るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“进展顺利”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n捗るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“进展顺利”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2393","seq":2393,"level":"N1","type":"主词条","word":"果敢ない","kana":"はかない","pos":"[イ形]","accent":"③","meaning":"短暂，无常","example":"果敢ない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“短暂，无常”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n果敢ない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“短暂，无常”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2394","seq":2394,"level":"N1","type":"主词条","word":"はかばかしい","kana":"はかばかしい","pos":"[イ形]","accent":"⑤","meaning":"顺利进行","example":"はかばかしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“顺利进行”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\nはかばかしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“顺利进行”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2395","seq":2395,"level":"N1","type":"主词条","word":"ばかばかしい","kana":"ばかばかしい","pos":"[イ形]","accent":"⑤","meaning":"愚蠢；过分；非常","example":"ばかばかしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“愚蠢；过分”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nばかばかしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“愚蠢；过分”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2396","seq":2396,"level":"N1","type":"主词条","word":"計り知れない","kana":"はかりしれない","pos":"[イ形]","accent":"⓪⑤","meaning":"不可估量","example":"計り知れない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“不可估量”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\n計り知れない印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“不可估量”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2397","seq":2397,"level":"N1","type":"主词条","word":"諮る","kana":"はかる","pos":"[他動1]","accent":"②","meaning":"咨询，协商","example":"諮る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“咨询，协商”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n諮る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“咨询，协商”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2398","seq":2398,"level":"N1","type":"主词条","word":"破棄","kana":"はき","pos":"[名·他動3]","accent":"①","meaning":"毁约，作废","example":"破棄する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“毁约，作废”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n破棄する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“毁约，作废”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2399","seq":2399,"level":"N1","type":"主词条","word":"波及","kana":"はきゅう","pos":"[名·自動3]","accent":"⓪","meaning":"波及，影响","example":"予期せず波及した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“波及，影响”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず波及した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“波及，影响”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2400","seq":2400,"level":"N1","type":"主词条","word":"破局","kana":"はきょく","pos":"[名·自動3]","accent":"⓪","meaning":"不可收拾的局面","example":"破局してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“不可收拾的局面”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n破局してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“不可收拾的局面”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2401","seq":2401,"level":"N1","type":"主词条","word":"歯切れ","kana":"はぎれ","pos":"[名]","accent":"⓪","meaning":"食物脆；发音，口齿","example":"店主は歯切れの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“食物脆；发音，口齿”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主は歯切れの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“食物脆；发音，口齿”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2402","seq":2402,"level":"N1","type":"主词条","word":"剥ぐ","kana":"はぐ","pos":"[他動1]","accent":"①","meaning":"剥，扒；剥夺","example":"剥ぐ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“剥，扒；剥夺”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n剥ぐ場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“剥，扒；剥夺”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2403","seq":2403,"level":"N1","type":"主词条","word":"育む","kana":"はぐくむ","pos":"[他動1]","accent":"③","meaning":"孵蛋；养育，培养","example":"育む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“孵蛋；养育，培养”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n育む前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“孵蛋；养育，培养”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2404","seq":2404,"level":"N1","type":"主词条","word":"薄弱","kana":"はくじゃく","pos":"[名·ナ形]","accent":"⓪","meaning":"薄弱；（证据等）不充足","example":"周囲から薄弱だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“薄弱；不充足”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から薄弱だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“薄弱；不充足”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2405","seq":2405,"level":"N1","type":"主词条","word":"白状","kana":"はくじょう","pos":"[名·他動3]","accent":"①","meaning":"坦白，招供","example":"彼は隠していたミスを白状し、上司に今後の対応を相談した。","exampleZh":"他坦白了自己隐瞒的失误，并向上司商量之后的应对。","note":"例：\n彼は隠していたミスを白状し、上司に今後の対応を相談した。\n译：他坦白了自己隐瞒的失误，并向上司商量之后的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2406","seq":2406,"level":"N1","type":"主词条","word":"漠然","kana":"ばくぜん","pos":"[副·ナ形]","accent":"⓪","meaning":"漠然，模糊","example":"将来への不安が漠然としているうちは、何が心配なのかを紙に書き出すだけでも整理しやすい。","exampleZh":"对未来的不安还很模糊时，仅仅把担心什么写在纸上，也会更容易整理。","note":"例：\n将来への不安が漠然としているうちは、何が心配なのかを紙に書き出すだけでも整理しやすい。\n译：对未来的不安还很模糊时，仅仅把担心什么写在纸上，也会更容易整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2407","seq":2407,"level":"N1","type":"主词条","word":"爆破","kana":"ばくは","pos":"[名·他動3]","accent":"⓪①","meaning":"爆破","example":"古い建物を爆破して解体する計画では、周辺住民への影響と安全確認が何より重視された。","exampleZh":"爆破拆除老旧建筑的计划中，最被重视的是对周边居民的影响和安全确认。","note":"例：\n古い建物を爆破して解体する計画では、周辺住民への影響と安全確認が何より重視された。\n译：爆破拆除老旧建筑的计划中，最被重视的是对周边居民的影响和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2408","seq":2408,"level":"N1","type":"主词条","word":"迫力","kana":"はくりょく","pos":"[名]","accent":"⓪①","meaning":"感染力","example":"彼の迫力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。","exampleZh":"他的“感染力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","note":"例：\n彼の迫力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。\n译：他的“感染力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2409","seq":2409,"level":"N1","type":"主词条","word":"暴露","kana":"ばくろ","pos":"[名·自他動3]","accent":"①","meaning":"暴露，揭露","example":"内部情報を暴露する前に、彼は公益性と関係者への影響を慎重に考えた。","exampleZh":"在揭露内部信息之前，他慎重考虑了公益性以及对相关人员的影响。","note":"例：\n内部情報を暴露する前に、彼は公益性と関係者への影響を慎重に考えた。\n译：在揭露内部信息之前，他慎重考虑了公益性以及对相关人员的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2410","seq":2410,"level":"N1","type":"主词条","word":"励む","kana":"はげむ","pos":"[自動1]","accent":"②","meaning":"勤奋，努力","example":"励むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“勤奋，努力”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n励むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“勤奋，努力”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2411","seq":2411,"level":"N1","type":"主词条","word":"剥げる","kana":"はげる","pos":"[自動2]","accent":"②","meaning":"褪色；剥落","example":"勢いが少しずつ剥げる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“褪色；剥落”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ剥げる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“褪色；剥落”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2412","seq":2412,"level":"N1","type":"主词条","word":"禿げる","kana":"はげる","pos":"[自動2]","accent":"②","meaning":"（山）秃；秃，脱发","example":"禿げる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“秃；秃，脱发”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n禿げる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“秃；秃，脱发”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2413","seq":2413,"level":"N1","type":"主词条","word":"化ける","kana":"ばける","pos":"[自動2]","accent":"②","meaning":"乔装；完全变样","example":"地味に見えた企画でも、視点を少し変えるだけで多くの人を引きつける内容に化けることがある。","exampleZh":"即使是看似朴素的企划，只要稍微改变视角，有时也会变成吸引许多人的内容。","note":"例：\n地味に見えた企画でも、視点を少し変えるだけで多くの人を引きつける内容に化けることがある。\n译：即使是看似朴素的企划，只要稍微改变视角，有时也会变成吸引许多人的内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2414","seq":2414,"level":"N1","type":"主词条","word":"弾く","kana":"はじく","pos":"[他動1]","accent":"②","meaning":"弹；防（水）；打（算盘）","example":"古いピアノを弾く前に、彼女は音の狂いを確かめ、発表会で使える状態か慎重に判断した。","exampleZh":"弹奏旧钢琴前，她确认了音准偏差，谨慎判断它是否处于可用于发表会的状态。","note":"例：\n古いピアノを弾く前に、彼女は音の狂いを確かめ、発表会で使える状態か慎重に判断した。\n译：弹奏旧钢琴前，她确认了音准偏差，谨慎判断它是否处于可用于发表会的状态。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2415","seq":2415,"level":"N1","type":"主词条","word":"恥らう","kana":"はじらう","pos":"[自動1]","accent":"③","meaning":"害羞","example":"恥らうとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“害羞”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n恥らうとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“害羞”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2416","seq":2416,"level":"N1","type":"主词条","word":"恥じる","kana":"はじる","pos":"[自他動2]","accent":"②","meaning":"羞耻，羞愧","example":"恥じる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“羞耻，羞愧”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n恥じる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“羞耻，羞愧”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2417","seq":2417,"level":"N1","type":"主词条","word":"弾む","kana":"はずむ","pos":"[自動1]","accent":"⓪","meaning":"起劲；情绪高涨","example":"久しぶりに友人と会うと会話が弾み、気づけば閉店時間を過ぎていた。","exampleZh":"久违地见到朋友后，谈话十分热烈，回过神来已过了闭店时间。","note":"例：\n久しぶりに友人と会うと会話が弾み、気づけば閉店時間を過ぎていた。\n译：久违地见到朋友后，谈话十分热烈，回过神来已过了闭店时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2418","seq":2418,"level":"N1","type":"主词条","word":"～外れ","kana":"～はずれ","pos":"[接尾]","accent":"","meaning":"偏离","example":"期待外れの結果に終わったとしても、準備の過程で得た知識は次の挑戦に必ず生かせる。","exampleZh":"即使结果不如期待，准备过程中获得的知识也一定能用于下一次挑战。","note":"例：\n期待外れの結果に終わったとしても、準備の過程で得た知識は次の挑戦に必ず生かせる。\n译：即使结果不如期待，准备过程中获得的知识也一定能用于下一次挑战。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2419","seq":2419,"level":"N1","type":"主词条","word":"破損","kana":"はそん","pos":"[名·自他動3]","accent":"⓪","meaning":"破损，损坏","example":"輸送中に商品の破損が見つかったため、会社は梱包方法と検品手順を見直すことにした。","exampleZh":"运输过程中发现商品破损，所以公司决定重新审视包装方法和检验流程。","note":"例：\n輸送中に商品の破損が見つかったため、会社は梱包方法と検品手順を見直すことにした。\n译：运输过程中发现商品破损，所以公司决定重新审视包装方法和检验流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2420","seq":2420,"level":"N1","type":"主词条","word":"叩く","kana":"はたく","pos":"[他動1]","accent":"②","meaning":"拍打；敲打；全部拿出","example":"古い扉を軽く叩くと、中から祖母の懐かしい声が聞こえてきた。","exampleZh":"轻轻敲响旧门后，从里面传来了祖母令人怀念的声音。","note":"例：\n古い扉を軽く叩くと、中から祖母の懐かしい声が聞こえてきた。\n译：轻轻敲响旧门后，从里面传来了祖母令人怀念的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2421","seq":2421,"level":"N1","type":"主词条","word":"肌寒い","kana":"はださむい","pos":"[イ形]","accent":"④","meaning":"略感寒意的；毛骨悚然的","example":"夕方になると急に肌寒くなり、川沿いを歩いていた人々は上着を羽織り始めた。","exampleZh":"到了傍晚突然有些冷，沿河散步的人们开始披上外套。","note":"例：\n夕方になると急に肌寒くなり、川沿いを歩いていた人々は上着を羽織り始めた。\n译：到了傍晚突然有些冷，沿河散步的人们开始披上外套。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2422","seq":2422,"level":"N1","type":"主词条","word":"裸足","kana":"はだし","pos":"[名]","accent":"⓪","meaning":"光脚；不及，敌不过","example":"海岸を裸足で歩くと気持ちはよいが、割れた貝殻や熱い砂でけがをしないよう注意が必要だ。","exampleZh":"光脚走在海岸上感觉很好，但要注意不要被碎贝壳或滚烫沙子弄伤。","note":"例：\n海岸を裸足で歩くと気持ちはよいが、割れた貝殻や熱い砂でけがをしないよう注意が必要だ。\n译：光脚走在海岸上感觉很好，但要注意不要被碎贝壳或滚烫沙子弄伤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2423","seq":2423,"level":"N1","type":"主词条","word":"破綻","kana":"はたん","pos":"[名·自動3]","accent":"⓪","meaning":"失败，破裂；破产","example":"破綻するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“失败，破裂；破产”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n破綻するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“失败，破裂；破产”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2424","seq":2424,"level":"N1","type":"主词条","word":"場違い","kana":"ばちがい","pos":"[名·ナ形]","accent":"②","meaning":"不合时宜，与周围气氛不符","example":"場違いな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“不合时宜，与周围气氛不符”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n場違いな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“不合时宜，与周围气氛不符”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2425","seq":2425,"level":"N1","type":"主词条","word":"発育","kana":"はついく","pos":"[名·自動3]","accent":"⓪","meaning":"发育","example":"子どもの発育には個人差があるため、数字だけで不安をあおらず、生活全体を見て判断する必要がある。","exampleZh":"孩子发育存在个体差异，因此不应只用数字煽动不安，而应看整体生活来判断。","note":"例：\n子どもの発育には個人差があるため、数字だけで不安をあおらず、生活全体を見て判断する必要がある。\n译：孩子发育存在个体差异，因此不应只用数字煽动不安，而应看整体生活来判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2426","seq":2426,"level":"N1","type":"主词条","word":"バック","kana":"ばっく（back）","pos":"[名·自他動3]","accent":"①","meaning":"背景；靠山；后退","example":"バックの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“背景；靠山”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\nバックの進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“背景；靠山”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2427","seq":2427,"level":"N1","type":"主词条","word":"発掘","kana":"はっくつ","pos":"[名·他動3]","accent":"⓪","meaning":"发掘，挖掘","example":"発掘の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“发掘，挖掘”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n発掘の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“发掘，挖掘”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2428","seq":2428,"level":"N1","type":"主词条","word":"抜群","kana":"ばつぐん","pos":"[名·ナ形]","accent":"⓪","meaning":"超群","example":"抜群な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“超群”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n抜群な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“超群”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2429","seq":2429,"level":"N1","type":"主词条","word":"パッケージ","kana":"ぱっけーじ（package）","pos":"[名·他動3]","accent":"①","meaning":"包装","example":"チームはパッケージする理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“包装”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームはパッケージする理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“包装”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2430","seq":2430,"level":"N1","type":"主词条","word":"発散","kana":"はっさん","pos":"[名·自他動3]","accent":"⓪","meaning":"发散，消散","example":"発散する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“发散，消散”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n発散する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“发散，消散”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2431","seq":2431,"level":"N1","type":"主词条","word":"抜粋","kana":"ばっすい","pos":"[名·他動3]","accent":"⓪","meaning":"摘录，集锦","example":"長い報告書から重要な部分を抜粋する際、彼女は結論だけでなく根拠も残すようにした。","exampleZh":"从长篇报告中摘录重要部分时，她不仅保留结论，也保留了依据。","note":"例：\n長い報告書から重要な部分を抜粋する際、彼女は結論だけでなく根拠も残すようにした。\n译：从长篇报告中摘录重要部分时，她不仅保留结论，也保留了依据。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2432","seq":2432,"level":"N1","type":"主词条","word":"発する","kana":"はっする","pos":"[他動3]","accent":"⓪","meaning":"发，发出；发表","example":"事実を発する前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“发，发出；发表”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を発する前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“发，发出；发表”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2433","seq":2433,"level":"N1","type":"主词条","word":"発注","kana":"はっちゅう","pos":"[名·他動3]","accent":"⓪","meaning":"订货，订购","example":"発注した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“订货，订购”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n発注した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“订货，订购”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2434","seq":2434,"level":"N1","type":"主词条","word":"バッテリー","kana":"ばってりー（battery）","pos":"[名]","accent":"①⓪","meaning":"蓄电池；投接手（棒球）","example":"バッテリーが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“蓄电池；投接手”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nバッテリーが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“蓄电池；投接手”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2435","seq":2435,"level":"N1","type":"主词条","word":"バッテリーカー","kana":"ばってりーかー","pos":"[名]","accent":"⑥","meaning":"电瓶车","example":"バッテリーカーを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“电瓶车”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nバッテリーカーを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“电瓶车”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2436","seq":2436,"level":"N1","type":"主词条","word":"バット","kana":"ばっと（bat）","pos":"[名]","accent":"①","meaning":"球棒","example":"バットが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“球棒”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nバットが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“球棒”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2437","seq":2437,"level":"N1","type":"主词条","word":"発病","kana":"はつびょう","pos":"[名·自動3]","accent":"⓪","meaning":"发病，得病","example":"発病する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“发病，得病”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n発病する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“发病，得病”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2438","seq":2438,"level":"N1","type":"主词条","word":"初耳","kana":"はつみみ","pos":"[名]","accent":"⓪","meaning":"初次听到","example":"初耳をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“初次听到”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n初耳をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“初次听到”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2439","seq":2439,"level":"N1","type":"主词条","word":"果て","kana":"はて","pos":"[名]","accent":"②","meaning":"尽头；止境；结局","example":"長い旅の果てにたどり着いた村で、彼は初めて自分の故郷を外から見直すことができた。","exampleZh":"在漫长旅途尽头抵达的村庄里，他第一次能够从外部重新审视自己的故乡。","note":"例：\n長い旅の果てにたどり着いた村で、彼は初めて自分の故郷を外から見直すことができた。\n译：在漫长旅途尽头抵达的村庄里，他第一次能够从外部重新审视自己的故乡。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2440","seq":2440,"level":"N1","type":"主词条","word":"～はてる","kana":"～はてる","pos":"[接尾]","accent":"","meaning":"……之极，完全……","example":"彼は困り果てて助けを求めたが、事情を整理して話すうちに解決の糸口が少しずつ見えてきた。","exampleZh":"他困窘到极点而求助，但在整理并讲述情况的过程中，解决线索逐渐显现。","note":"例：\n彼は困り果てて助けを求めたが、事情を整理して話すうちに解決の糸口が少しずつ見えてきた。\n译：他困窘到极点而求助，但在整理并讲述情况的过程中，解决线索逐渐显现。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2441","seq":2441,"level":"N1","type":"主词条","word":"果てる","kana":"はてる","pos":"[自動2]","accent":"②","meaning":"终了，完毕","example":"果てるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“终了，完毕”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n果てるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“终了，完毕”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2442","seq":2442,"level":"N1","type":"主词条","word":"ばてる","kana":"ばてる","pos":"[自動2]","accent":"②","meaning":"（俗语）累垮，累坏","example":"ばてる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“累垮，累坏”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\nばてる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“累垮，累坏”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2443","seq":2443,"level":"N1","type":"主词条","word":"歯止め","kana":"はどめ","pos":"[名]","accent":"⓪③","meaning":"制动装置止动器；遏制，控制","example":"歯止めを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“制动装置止动器；遏制，控制”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n歯止めを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“制动装置止动器；遏制，控制”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2444","seq":2444,"level":"N1","type":"主词条","word":"パトロール","kana":"ぱとろーる（patrol）","pos":"[名·自動3]","accent":"③","meaning":"巡逻，巡警","example":"パトロールする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“巡逻，巡警”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\nパトロールする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“巡逻，巡警”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2445","seq":2445,"level":"N1","type":"主词条","word":"バトンタッチ","kana":"ばとんたっち","pos":"[名·自動3]","accent":"④","meaning":"递交接力棒；交接","example":"予期せずバトンタッチした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“递交接力棒；交接”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せずバトンタッチした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“递交接力棒；交接”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2446","seq":2446,"level":"N1","type":"主词条","word":"甚だ","kana":"はなはだ","pos":"[副]","accent":"⓪","meaning":"甚，极其","example":"利用者への連絡が遅れたことは甚だ遺憾であり、担当部署は再発防止策をすぐに示すべきだ。","exampleZh":"给使用者的联络延迟是极其遗憾的，负责部门应立即提出防止再发措施。","note":"例：\n利用者への連絡が遅れたことは甚だ遺憾であり、担当部署は再発防止策をすぐに示すべきだ。\n译：给使用者的联络延迟是极其遗憾的，负责部门应立即提出防止再发措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2447","seq":2447,"level":"N1","type":"主词条","word":"華々しい","kana":"はなばなしい","pos":"[イ形]","accent":"⑤","meaning":"华丽，华美","example":"華々しい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“华丽，华美”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n華々しい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“华丽，华美”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2448","seq":2448,"level":"N1","type":"主词条","word":"花弁","kana":"はなびら","pos":"[名]","accent":"③⓪","meaning":"花瓣","example":"雨上がりの花弁には小さな水滴が残り、朝の光を受けて細かく輝いていた。","exampleZh":"雨后花瓣上残留着小水滴，在晨光照射下细细闪耀。","note":"例：\n雨上がりの花弁には小さな水滴が残り、朝の光を受けて細かく輝いていた。\n译：雨后花瓣上残留着小水滴，在晨光照射下细细闪耀。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2449","seq":2449,"level":"N1","type":"主词条","word":"華やか","kana":"はなやか","pos":"[ナ形]","accent":"②","meaning":"华丽；辉煌","example":"一見華やかな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“华丽；辉煌”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見華やかな印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“华丽；辉煌”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2450","seq":2450,"level":"N1","type":"主词条","word":"離れ離れ","kana":"はなればなれ","pos":"[名·ナ形]","accent":"④","meaning":"离散，分离","example":"離れ離れな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“离散，分离”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n離れ離れな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“离散，分离”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2451","seq":2451,"level":"N1","type":"主词条","word":"はねる","kana":"はねる","pos":"[他動2]","accent":"⓪","meaning":"撞，压；挑出去，淘汰","example":"はねる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“撞，压；挑出去，淘汰”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\nはねる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“撞，压；挑出去，淘汰”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2452","seq":2452,"level":"N1","type":"主词条","word":"憚る","kana":"はばかる","pos":"[他動1]","accent":"③⓪","meaning":"怕，顾忌","example":"憚る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“怕，顾忌”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n憚る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“怕，顾忌”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2453","seq":2453,"level":"N1","type":"主词条","word":"幅広い","kana":"はばひろい","pos":"[イ形]","accent":"④","meaning":"广泛，丰富","example":"幅広いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“广泛，丰富”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n幅広いと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“广泛，丰富”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2454","seq":2454,"level":"N1","type":"主词条","word":"阻む","kana":"はばむ","pos":"[他動1]","accent":"②","meaning":"阻挡，阻止；阻碍","example":"無理に阻むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“阻挡，阻止；阻碍”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に阻むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“阻挡，阻止；阻碍”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2455","seq":2455,"level":"N1","type":"主词条","word":"バブル","kana":"ばぶる（bubble）","pos":"[名]","accent":"①","meaning":"泡沫","example":"バブルを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“泡沫”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\nバブルを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“泡沫”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2456","seq":2456,"level":"N1","type":"主词条","word":"嵌る","kana":"はまる","pos":"[自動1]","accent":"⓪","meaning":"吻合，正好合适；中圈套；热衷","example":"嵌るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“吻合，正好合适；中圈套”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n嵌るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“吻合，正好合适；中圈套”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2457","seq":2457,"level":"N1","type":"主词条","word":"早いこと","kana":"はやいこと","pos":"[副]","accent":"②","meaning":"迅速","example":"雨が強くなる前に早いこと荷物を運び入れないと、せっかく準備した資料まで濡れてしまう。","exampleZh":"如果不趁雨势变强前赶紧把行李搬进去，连好不容易准备好的资料都会被淋湿。","note":"例：\n雨が強くなる前に早いこと荷物を運び入れないと、せっかく準備した資料まで濡れてしまう。\n译：如果不趁雨势变强前赶紧把行李搬进去，连好不容易准备好的资料都会被淋湿。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2458","seq":2458,"level":"N1","type":"主词条","word":"早いところ","kana":"はやいところ","pos":"[副]","accent":"②","meaning":"赶紧，赶快","example":"問題が大きくなる前に早いところ関係者を集め、事実関係を確認して対応を決める必要がある。","exampleZh":"在问题扩大前，需要赶紧召集相关人员，确认事实关系并决定应对方式。","note":"例：\n問題が大きくなる前に早いところ関係者を集め、事実関係を確認して対応を決める必要がある。\n译：在问题扩大前，需要赶紧召集相关人员，确认事实关系并决定应对方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2459","seq":2459,"level":"N1","type":"主词条","word":"生やす","kana":"はやす","pos":"[他動1]","accent":"②","meaning":"使生长；留","example":"生やすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“使生长；留”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n生やすことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“使生长；留”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2460","seq":2460,"level":"N1","type":"主词条","word":"腹が立つ","kana":"はらがたつ","pos":"[連語]","accent":"","meaning":"生气","example":"約束を破られて腹が立ったが、彼女はまず事実を確認してから抗議することにした。","exampleZh":"被人违背约定让她很生气，但她决定先确认事实后再提出抗议。","note":"例：\n約束を破られて腹が立ったが、彼女はまず事実を確認してから抗議することにした。\n译：被人违背约定让她很生气，但她决定先确认事实后再提出抗议。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2461","seq":2461,"level":"N1","type":"主词条","word":"晴らす","kana":"はらす","pos":"[他動1]","accent":"②","meaning":"消除，解除","example":"晴らす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“消除，解除”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n晴らす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“消除，解除”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2462","seq":2462,"level":"N1","type":"主词条","word":"ばらす","kana":"ばらす","pos":"[他動1]","accent":"②","meaning":"泄露","example":"ばらす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“泄露”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\nばらす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“泄露”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2463","seq":2463,"level":"N1","type":"主词条","word":"腹立たしい","kana":"はらだたしい","pos":"[イ形]","accent":"⑤","meaning":"令人气愤","example":"腹立たしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“令人气愤”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n腹立たしいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“令人气愤”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2464","seq":2464,"level":"N1","type":"主词条","word":"原っぱ","kana":"はらっぱ","pos":"[名]","accent":"⓪","meaning":"（杂草丛生的）空地","example":"研究者は原っぱの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“空地”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は原っぱの状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“空地”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2465","seq":2465,"level":"N1","type":"主词条","word":"はらはら","kana":"はらはら","pos":"[副·自動3]","accent":"①⓪","meaning":"担心；轻轻飘落的样子","example":"綱渡りのような交渉を、彼女ははらはらしながら見守り、無事に合意が成立すると胸をなで下ろした。","exampleZh":"她提心吊胆地看着这场像走钢丝一样的谈判，顺利达成协议后才松了一口气。","note":"例：\n綱渡りのような交渉を、彼女ははらはらしながら見守り、無事に合意が成立すると胸をなで下ろした。\n译：她提心吊胆地看着这场像走钢丝一样的谈判，顺利达成协议后才松了一口气。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2466","seq":2466,"level":"N1","type":"主词条","word":"ばらまく","kana":"ばらまく","pos":"[他動1]","accent":"③","meaning":"播撒；散财","example":"根拠のない情報をSNSでばらまくと、訂正しても不安や誤解だけが残ってしまう。","exampleZh":"如果在社交媒体上散布毫无根据的信息，即使之后更正，也只会留下不安和误解。","note":"例：\n根拠のない情報をSNSでばらまくと、訂正しても不安や誤解だけが残ってしまう。\n译：如果在社交媒体上散布毫无根据的信息，即使之后更正，也只会留下不安和误解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2467","seq":2467,"level":"N1","type":"主词条","word":"孕む","kana":"はらむ","pos":"[他動1]","accent":"②","meaning":"怀孕；内含，孕育","example":"孕む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“怀孕；内含，孕育”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n孕む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“怀孕；内含，孕育”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2468","seq":2468,"level":"N1","type":"主词条","word":"張り合い","kana":"はりあい","pos":"[名]","accent":"⓪","meaning":"竞争，对抗；劲头","example":"張り合いが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“竞争，对抗；劲头”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n張り合いが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“竞争，对抗；劲头”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2469","seq":2469,"level":"N1","type":"主词条","word":"張り合う","kana":"はりあう","pos":"[自他動1]","accent":"③","meaning":"竞争，争夺","example":"相手に何かを張り合うなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“竞争，争夺”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを張り合うなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“竞争，争夺”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2470","seq":2470,"level":"N1","type":"主词条","word":"バリアフリー","kana":"ばりあふりー（barrier free）","pos":"[名]","accent":"⑤","meaning":"无障碍设施","example":"バリアフリーをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“无障碍设施”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nバリアフリーをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“无障碍设施”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2471","seq":2471,"level":"N1","type":"主词条","word":"張り紙/貼り紙","kana":"はりがみ","pos":"[名]","accent":"⓪","meaning":"招贴，广告；标签","example":"市場環境が変わるなかで張り紙をどう確保するかが、経営会議で最も重要な課題になった。","exampleZh":"在市场环境变化中，如何确保“招贴，广告；标签”成了经营会议上最重要的课题。","note":"例：\n市場環境が変わるなかで張り紙をどう確保するかが、経営会議で最も重要な課題になった。\n译：在市场环境变化中，如何确保“招贴，广告；标签”成了经营会议上最重要的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2472","seq":2472,"level":"N1","type":"主词条","word":"～張る","kana":"～ばる","pos":"[接尾]","accent":"","meaning":"拘泥于……","example":"形式ばった挨拶は省略し、参加者が本音を話しやすいよう司会者は柔らかい雰囲気づくりに努めた。","exampleZh":"主持人省略了拘泥形式的寒暄，努力营造柔和氛围，让参加者更容易说出真心话。","note":"例：\n形式ばった挨拶は省略し、参加者が本音を話しやすいよう司会者は柔らかい雰囲気づくりに努めた。\n译：主持人省略了拘泥形式的寒暄，努力营造柔和氛围，让参加者更容易说出真心话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2473","seq":2473,"level":"N1","type":"主词条","word":"はるか","kana":"はるか","pos":"[ナ形·副]","accent":"①","meaning":"（时间或距离）相隔很远；（程度）相差很大","example":"彼ははるか結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。","exampleZh":"他没有急于作出“相隔很远；相差很大”的结论，而是在对照资料和现场声音后慎重决定方针。","note":"例：\n彼ははるか結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。\n译：他没有急于作出“相隔很远；相差很大”的结论，而是在对照资料和现场声音后慎重决定方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2474","seq":2474,"level":"N1","type":"主词条","word":"腫れ上がる","kana":"はれあがる","pos":"[自動1]","accent":"④","meaning":"肿起来","example":"腫れ上がる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“肿起来”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n腫れ上がる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“肿起来”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2475","seq":2475,"level":"N1","type":"主词条","word":"パレード","kana":"ぱれーど（parade）","pos":"[名·自動3]","accent":"②①","meaning":"盛装游行；阅兵式","example":"パレードする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“盛装游行；阅兵式”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\nパレードする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“盛装游行；阅兵式”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2476","seq":2476,"level":"N1","type":"主词条","word":"破裂","kana":"はれつ","pos":"[名·自動3]","accent":"⓪","meaning":"破裂","example":"破裂した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“破裂”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n破裂した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“破裂”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2477","seq":2477,"level":"N1","type":"主词条","word":"晴れ晴れしい","kana":"はればれしい","pos":"[イ形]","accent":"⑤","meaning":"晴朗；开朗；华丽","example":"晴れ晴れしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“晴朗；开朗”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n晴れ晴れしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“晴朗；开朗”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2478","seq":2478,"level":"N1","type":"主词条","word":"腫れる","kana":"はれる","pos":"[自動2]","accent":"⓪","meaning":"肿胀","example":"腫れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“肿胀”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n腫れる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“肿胀”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2479","seq":2479,"level":"N1","type":"主词条","word":"ばれる","kana":"ばれる","pos":"[自動2]","accent":"②","meaning":"（坏事，秘密等）败露","example":"ばれるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“败露”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\nばれるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“败露”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2480","seq":2480,"level":"N1","type":"主词条","word":"晴れ渡る","kana":"はれわたる","pos":"[自動1]","accent":"④⓪","meaning":"完全放晴；（心情）舒畅","example":"晴れ渡るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“完全放晴；舒畅”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n晴れ渡るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“完全放晴；舒畅”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2481","seq":2481,"level":"N1","type":"主词条","word":"パワー","kana":"ぱわー（power）","pos":"[名]","accent":"①","meaning":"力量","example":"パワーが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“力量”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nパワーが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“力量”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2482","seq":2482,"level":"N1","type":"主词条","word":"版","kana":"はん","pos":"[名]","accent":"①","meaning":"版（组合后多读ばん）","example":"改訂版を出す際には、誤植を直すだけでなく、読者から寄せられた疑問点も反映させた。","exampleZh":"出修订版时，他不仅修正了错字，也反映了读者提出的疑问点。","note":"例：\n改訂版を出す際には、誤植を直すだけでなく、読者から寄せられた疑問点も反映させた。\n译：出修订版时，他不仅修正了错字，也反映了读者提出的疑问点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2483","seq":2483,"level":"N1","type":"主词条","word":"ハンガー","kana":"はんがー（hanger）","pos":"[名]","accent":"①","meaning":"衣架","example":"式典に着ていくハンガーを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“衣架”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていくハンガーを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“衣架”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2484","seq":2484,"level":"N1","type":"主词条","word":"反感","kana":"はんかん","pos":"[名]","accent":"⓪","meaning":"反感","example":"反感が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“反感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n反感が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“反感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2485","seq":2485,"level":"N1","type":"主词条","word":"反響","kana":"はんきょう","pos":"[名·自動3]","accent":"⓪","meaning":"反响","example":"反響してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“反响”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n反響してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“反响”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2486","seq":2486,"level":"N1","type":"主词条","word":"パンク","kana":"パンク","pos":"[名·自動3]","accent":"⓪","meaning":"爆胎；超负荷，崩溃；破产；","example":"帰宅途中に自転車のタイヤがパンクし、彼は急な坂道を押して歩くことになった。","exampleZh":"回家途中自行车轮胎爆了，他只好推着车走上陡坡。","note":"例：\n帰宅途中に自転車のタイヤがパンクし、彼は急な坂道を押して歩くことになった。\n译：回家途中自行车轮胎爆了，他只好推着车走上陡坡。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2487","seq":2487,"level":"N1","type":"主词条","word":"繁盛","kana":"はんじょう","pos":"[名·ナ形·自動3]","accent":"①","meaning":"繁荣昌盛，兴隆","example":"繁盛する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“繁荣昌盛，兴隆”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n繁盛する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“繁荣昌盛，兴隆”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2488","seq":2488,"level":"N1","type":"主词条","word":"半製品","kana":"はんせいひん","pos":"[名]","accent":"③","meaning":"半成品","example":"古い半製品を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“半成品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い半製品を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“半成品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2489","seq":2489,"level":"N1","type":"主词条","word":"伴奏","kana":"ばんそう","pos":"[名·自動3]","accent":"⓪","meaning":"伴奏","example":"予期せず伴奏した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“伴奏”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず伴奏した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“伴奏”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2490","seq":2490,"level":"N1","type":"主词条","word":"反則","kana":"はんそく","pos":"[名·自動3]","accent":"⓪","meaning":"违法，违章；犯规","example":"反則してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“违法，违章；犯规”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n反則してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“违法，违章；犯规”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2491","seq":2491,"level":"N1","type":"主词条","word":"ハンデ","kana":"はんで","pos":"[名]","accent":"①","meaning":"障碍，不利条件","example":"ハンデを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“障碍，不利条件”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\nハンデを正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“障碍，不利条件”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2492","seq":2492,"level":"N1","type":"主词条","word":"バンド","kana":"ばんど（band）","pos":"[名]","accent":"⓪","meaning":"皮带，胶带；乐团","example":"バンドに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“皮带，胶带；乐团”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nバンドに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“皮带，胶带；乐团”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2493","seq":2493,"level":"N1","type":"主词条","word":"万人","kana":"ばんにん","pos":"[名]","accent":"⓪③","meaning":"万人，大众","example":"万人として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“万人，大众”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n万人として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“万人，大众”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2494","seq":2494,"level":"N1","type":"主词条","word":"番人","kana":"ばんにん","pos":"[名]","accent":"③","meaning":"值班人，看守人","example":"その番人は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“值班人，看守人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nその番人は肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“值班人，看守人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2495","seq":2495,"level":"N1","type":"主词条","word":"反応","kana":"はんのう","pos":"[名·自動3]","accent":"⓪","meaning":"反应；反响，效果","example":"反応してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“反应；反响，效果”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n反応してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“反应；反响，效果”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2496","seq":2496,"level":"N1","type":"主词条","word":"半端","kana":"はんぱ","pos":"[名·ナ形]","accent":"⓪","meaning":"尾数；不彻底","example":"一度半端だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“尾数；不彻底”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度半端だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“尾数；不彻底”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2497","seq":2497,"level":"N1","type":"主词条","word":"反発","kana":"はんぱつ","pos":"[名·自他動3]","accent":"⓪","meaning":"排斥；反感；反弹","example":"反発した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“排斥；反感”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n反発した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“排斥；反感”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2498","seq":2498,"level":"N1","type":"主词条","word":"反乱","kana":"はんらん","pos":"[名·自動3]","accent":"⓪","meaning":"叛乱","example":"反乱するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“叛乱”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n反乱するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“叛乱”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2499","seq":2499,"level":"N1","type":"主词条","word":"氾濫","kana":"はんらん","pos":"[名·自動3]","accent":"⓪","meaning":"泛滥","example":"予期せず氾濫した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“泛滥”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず氾濫した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“泛滥”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2500","seq":2500,"level":"N1","type":"主词条","word":"販路","kana":"はんろ","pos":"[名]","accent":"①","meaning":"销路","example":"海外での販路を確保するため、営業部は展示会だけでなく現地代理店との関係づくりにも力を入れた。","exampleZh":"为了确保海外销路，营业部不仅参加展会，也致力于与当地代理商建立关系。","note":"例：\n海外での販路を確保するため、営業部は展示会だけでなく現地代理店との関係づくりにも力を入れた。\n译：为了确保海外销路，营业部不仅参加展会，也致力于与当地代理商建立关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2501","seq":2501,"level":"N1","type":"主词条","word":"PR","kana":"ピーアール","pos":"[名]","accent":"③","meaning":"宣传广告活动，公关活动","example":"担当者はPRを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。","exampleZh":"负责人没有只用数字判断“宣传广告活动，公关活动”，还比较了与客户的信任关系以及未来风险。","note":"例：\n担当者はPRを数字だけで判断せず、取引先との信頼関係や将来のリスクまで比較した。\n译：负责人没有只用数字判断“宣传广告活动，公关活动”，还比较了与客户的信任关系以及未来风险。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2502","seq":2502,"level":"N1","type":"主词条","word":"ピーク","kana":"ぴーく（peak）","pos":"[名]","accent":"①","meaning":"最高峰","example":"ピークをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“最高峰”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nピークをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“最高峰”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2503","seq":2503,"level":"N1","type":"主词条","word":"ひいては","kana":"ひいては","pos":"[副]","accent":"①③","meaning":"进而，甚至","example":"小さな改善を積み重ねることが、職場の安全性を高め、ひいては利用者の信頼にもつながる。","exampleZh":"积累小小改善会提高职场安全性，进而连接到使用者的信任。","note":"例：\n小さな改善を積み重ねることが、職場の安全性を高め、ひいては利用者の信頼にもつながる。\n译：积累小小改善会提高职场安全性，进而连接到使用者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2504","seq":2504,"level":"N1","type":"主词条","word":"ピーナッツ","kana":"ぴーなっつ（peanuts）","pos":"[名]","accent":"①","meaning":"花生仁，花生米","example":"店主はピーナッツの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。","exampleZh":"店主不仅考虑“花生仁，花生米”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","note":"例：\n店主はピーナッツの味だけでなく、冷めたときの食感や持ち帰りやすさまで考えて商品を改良した。\n译：店主不仅考虑“花生仁，花生米”的味道，还连同冷掉后的口感和外带便利性一起改良了商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2505","seq":2505,"level":"N1","type":"主词条","word":"控え室","kana":"ひかえしつ","pos":"[名]","accent":"③②","meaning":"等候室，休息室","example":"限られた控え室の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“等候室，休息室”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた控え室の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“等候室，休息室”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2506","seq":2506,"level":"N1","type":"主词条","word":"控えめ","kana":"ひかえめ","pos":"[名·ナ形]","accent":"⓪④","meaning":"拘谨；节制","example":"控えめな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“拘谨；节制”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n控えめな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“拘谨；节制”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2507","seq":2507,"level":"N1","type":"主词条","word":"控える","kana":"ひかえる","pos":"[自他動2]","accent":"③②","meaning":"等候；节制；记下；临近","example":"控える前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“等候；节制”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n控える前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“等候；节制”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2508","seq":2508,"level":"N1","type":"主词条","word":"日陰","kana":"ひかげ","pos":"[名]","accent":"⓪","meaning":"背阴处，阴凉处","example":"日陰の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“背阴处，阴凉处”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n日陰の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“背阴处，阴凉处”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2509","seq":2509,"level":"N1","type":"主词条","word":"悲観","kana":"ひかん","pos":"[名·自他動3]","accent":"⓪","meaning":"悲观","example":"数字だけを見ると厳しい状況だが、まだ対策の余地はあるので悲観しすぎる必要はない。","exampleZh":"只看数字形势确实严峻，但仍有采取对策的余地，所以不必过分悲观。","note":"例：\n数字だけを見ると厳しい状況だが、まだ対策の余地はあるので悲観しすぎる必要はない。\n译：只看数字形势确实严峻，但仍有采取对策的余地，所以不必过分悲观。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2510","seq":2510,"level":"N1","type":"主词条","word":"悲観的","kana":"ひかんてき","pos":"[ナ形]","accent":"⓪","meaning":"悲观的","example":"一度悲観的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“悲观的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度悲観的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“悲观的”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2511","seq":2511,"level":"N1","type":"主词条","word":"率いる","kana":"ひきいる","pos":"[他動2]","accent":"③","meaning":"带领，率领","example":"率いる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“带领，率领”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n率いる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“带领，率领”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2512","seq":2512,"level":"N1","type":"主词条","word":"引きずる","kana":"ひきずる","pos":"[自他動1]","accent":"⓪","meaning":"拖，垂至地面；拖延，拖长","example":"無理に引きずるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“拖，垂至地面；拖延，拖长”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に引きずるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“拖，垂至地面；拖延，拖长”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2513","seq":2513,"level":"N1","type":"主词条","word":"引き継ぐ","kana":"ひきつぐ","pos":"[他動1]","accent":"③","meaning":"接替，交接；继承","example":"引き継ぐことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“接替，交接；继承”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n引き継ぐことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“接替，交接；继承”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2514","seq":2514,"level":"N1","type":"主词条","word":"引き取る","kana":"ひきとる","pos":"[自他動1]","accent":"③","meaning":"拿回，取回，领回","example":"相手に何かを引き取るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“拿回，取回，领回”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを引き取るなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“拿回，取回，领回”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2515","seq":2515,"level":"N1","type":"主词条","word":"びくとも","kana":"びくとも","pos":"[副·自動3]","accent":"①","meaning":"一点也（不），丝毫（不）","example":"強い風が吹いても古い門はびくともせず、職人の仕事の確かさを感じさせた。","exampleZh":"即使强风吹来，那扇旧门也纹丝不动，让人感受到工匠手艺的可靠。","note":"例：\n強い風が吹いても古い門はびくともせず、職人の仕事の確かさを感じさせた。\n译：即使强风吹来，那扇旧门也纹丝不动，让人感受到工匠手艺的可靠。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2516","seq":2516,"level":"N1","type":"主词条","word":"否決","kana":"ひけつ","pos":"[名·他動3]","accent":"⓪","meaning":"否决","example":"相手を否決するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯对对方进行“否决”只会加深对立，因此她决定先确认其主张背后的背景。","note":"例：\n相手を否決するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯对对方进行“否决”只会加深对立，因此她决定先确认其主张背后的背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2517","seq":2517,"level":"N1","type":"主词条","word":"引け目","kana":"ひけめ","pos":"[名]","accent":"⓪","meaning":"自卑感","example":"引け目が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“自卑感”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n引け目が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“自卑感”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2518","seq":2518,"level":"N1","type":"主词条","word":"久しい","kana":"ひさしい","pos":"[イ形]","accent":"③","meaning":"（相隔）好久，许久","example":"久しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“好久，许久”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n久しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“好久，许久”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2519","seq":2519,"level":"N1","type":"主词条","word":"非常勤","kana":"ひじょうきん","pos":"[名]","accent":"②","meaning":"兼职，兼任","example":"非常勤の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“兼职，兼任”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n非常勤の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“兼职，兼任”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2520","seq":2520,"level":"N1","type":"主词条","word":"ビジョン","kana":"びじょん（vision）","pos":"[名]","accent":"①","meaning":"愿景；视觉；景象","example":"ビジョンをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“愿景；视觉”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nビジョンをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“愿景；视觉”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2521","seq":2521,"level":"N1","type":"主词条","word":"歪む","kana":"ひずむ","pos":"[自動1]","accent":"⓪②","meaning":"变形，歪斜","example":"勢いが少しずつ歪む前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“变形，歪斜”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ歪む前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“变形，歪斜”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2522","seq":2522,"level":"N1","type":"主词条","word":"比する","kana":"ひする","pos":"[他動3]","accent":"②","meaning":"比较","example":"比する前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“比较”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n比する前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“比较”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2523","seq":2523,"level":"N1","type":"主词条","word":"ひそか","kana":"ひそか","pos":"[ナ形]","accent":"②①","meaning":"暗中，偷偷","example":"彼女はひそかに準備を進め、皆が諦めかけていた企画を別の形で実現させた。","exampleZh":"她暗中推进准备，把大家几乎放弃的企划以另一种形式实现了。","note":"例：\n彼女はひそかに準備を進め、皆が諦めかけていた企画を別の形で実現させた。\n译：她暗中推进准备，把大家几乎放弃的企划以另一种形式实现了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2524","seq":2524,"level":"N1","type":"主词条","word":"潜む","kana":"ひそむ","pos":"[自動1]","accent":"②","meaning":"躲藏，潜伏；蕴藏，潜藏","example":"潜むとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“躲藏，潜伏；蕴藏，潜藏”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n潜むとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“躲藏，潜伏；蕴藏，潜藏”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2525","seq":2525,"level":"N1","type":"主词条","word":"浸す","kana":"ひたす","pos":"[他動1]","accent":"⓪②","meaning":"浸泡，浸湿","example":"乾いた豆を一晩水に浸すと、火の通りがよくなり、翌日の調理時間を短くできる。","exampleZh":"把干豆子在水里浸泡一晚，受热会更容易，第二天的烹调时间也能缩短。","note":"例：\n乾いた豆を一晩水に浸すと、火の通りがよくなり、翌日の調理時間を短くできる。\n译：把干豆子在水里浸泡一晚，受热会更容易，第二天的烹调时间也能缩短。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2526","seq":2526,"level":"N1","type":"主词条","word":"ひたすら","kana":"ひたすら","pos":"[副]","accent":"⓪②","meaning":"一个劲儿，一心一意","example":"彼は評価を気にせず、ひたすら目の前の患者に向き合い、必要な支援を一つずつ続けた。","exampleZh":"他不在意评价，只是一心面对眼前的患者，一项一项持续提供必要支援。","note":"例：\n彼は評価を気にせず、ひたすら目の前の患者に向き合い、必要な支援を一つずつ続けた。\n译：他不在意评价，只是一心面对眼前的患者，一项一项持续提供必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2527","seq":2527,"level":"N1","type":"主词条","word":"浸る","kana":"ひたる","pos":"[自動1]","accent":"⓪②","meaning":"浸，泡；沉迷；沉浸","example":"浸る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“浸，泡；沉迷”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n浸る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“浸，泡；沉迷”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2528","seq":2528,"level":"N1","type":"主词条","word":"引っかく","kana":"ひっかく","pos":"[他動1]","accent":"③","meaning":"（用力）挠，搔","example":"引っかくことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“挠，搔”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n引っかくことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“挠，搔”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2529","seq":2529,"level":"N1","type":"主词条","word":"ひっきりなしに","kana":"ひっきりなしに","pos":"[副]","accent":"⑤④","meaning":"接连不断","example":"新商品の発売日には問い合わせの電話がひっきりなしに鳴り、担当者は昼食を取る暇もなかった。","exampleZh":"新商品发售当天，咨询电话响个不停，负责人连吃午饭的空闲都没有。","note":"例：\n新商品の発売日には問い合わせの電話がひっきりなしに鳴り、担当者は昼食を取る暇もなかった。\n译：新商品发售当天，咨询电话响个不停，负责人连吃午饭的空闲都没有。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2530","seq":2530,"level":"N1","type":"主词条","word":"必修","kana":"ひっしゅう","pos":"[名]","accent":"⓪","meaning":"必修","example":"必修が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“必修”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n必修が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“必修”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2531","seq":2531,"level":"N1","type":"主词条","word":"必然","kana":"ひつぜん","pos":"[名]","accent":"⓪","meaning":"必然","example":"必然を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“必然”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n必然を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“必然”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2532","seq":2532,"level":"N1","type":"主词条","word":"ひっそり","kana":"ひっそり","pos":"[副]","accent":"③","meaning":"寂静；默默地","example":"駅裏の小さな店はひっそり営業しているが、丁寧な接客を求めて遠方から訪れる客もいる。","exampleZh":"车站后面的小店安静地营业着，但也有顾客为寻求细致服务从远方前来。","note":"例：\n駅裏の小さな店はひっそり営業しているが、丁寧な接客を求めて遠方から訪れる客もいる。\n译：车站后面的小店安静地营业着，但也有顾客为寻求细致服务从远方前来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2533","seq":2533,"level":"N1","type":"主词条","word":"匹敵","kana":"ひってき","pos":"[名·自動3]","accent":"⓪","meaning":"匹敌，比得上","example":"地方の小さな企業でも、独自の技術を磨けば大手に匹敵する品質の商品を生み出せる。","exampleZh":"即使是地方小企业，只要磨炼独自技术，也能生产出质量足以匹敌大企业的商品。","note":"例：\n地方の小さな企業でも、独自の技術を磨けば大手に匹敵する品質の商品を生み出せる。\n译：即使是地方小企业，只要磨炼独自技术，也能生产出质量足以匹敌大企业的商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2534","seq":2534,"level":"N1","type":"主词条","word":"ヒット","kana":"ひっと（hit）","pos":"[名·自動3]","accent":"①","meaning":"打中；大受欢迎","example":"ヒットしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“打中；大受欢迎”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\nヒットしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“打中；大受欢迎”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2535","seq":2535,"level":"N1","type":"主词条","word":"日照り","kana":"ひでり","pos":"[名]","accent":"⓪③","meaning":"干旱；缺乏，不足","example":"医師は日照りの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“干旱；缺乏，不足”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師は日照りの状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“干旱；缺乏，不足”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2536","seq":2536,"level":"N1","type":"主词条","word":"一息","kana":"ひといき","pos":"[名]","accent":"②","meaning":"歇口气；（稍加）一把劲","example":"長い坂道を登り切ったところで一息つき、彼は振り返って町の景色を眺めた。","exampleZh":"爬完漫长坡道后，他歇了一口气，回头眺望城镇景色。","note":"例：\n長い坂道を登り切ったところで一息つき、彼は振り返って町の景色を眺めた。\n译：爬完漫长坡道后，他歇了一口气，回头眺望城镇景色。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2537","seq":2537,"level":"N1","type":"主词条","word":"人影","kana":"ひとかげ","pos":"[名]","accent":"⓪③","meaning":"人影","example":"研究者は人影の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“人影”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は人影の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“人影”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2538","seq":2538,"level":"N1","type":"主词条","word":"人柄","kana":"ひとがら","pos":"[名]","accent":"⓪","meaning":"人品","example":"人柄として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“人品”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n人柄として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“人品”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2539","seq":2539,"level":"N1","type":"主词条","word":"ひときわ","kana":"ひときわ","pos":"[副]","accent":"⓪②","meaning":"格外，分外","example":"夕暮れの空を背景に、古い塔の輪郭がひときわ美しく浮かび上がって見えた。","exampleZh":"在夕阳天空的映衬下，古塔的轮廓显得格外美丽。","note":"例：\n夕暮れの空を背景に、古い塔の輪郭がひときわ美しく浮かび上がって見えた。\n译：在夕阳天空的映衬下，古塔的轮廓显得格外美丽。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2540","seq":2540,"level":"N1","type":"主词条","word":"ひと括り","kana":"ひとくくり","pos":"[名]","accent":"②③","meaning":"归结为一起","example":"ひと括りが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“归结为一起”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nひと括りが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“归结为一起”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2541","seq":2541,"level":"N1","type":"主词条","word":"人気","kana":"ひとけ","pos":"[名]","accent":"⓪","meaning":"人影，有人的样子","example":"山奥の道には人気がなく、彼は念のため家族に現在地を知らせてから歩き続けた。","exampleZh":"深山道路上没有人影，他为了保险起见，先把当前位置告诉家人后才继续走。","note":"例：\n山奥の道には人気がなく、彼は念のため家族に現在地を知らせてから歩き続けた。\n译：深山道路上没有人影，他为了保险起见，先把当前位置告诉家人后才继续走。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2542","seq":2542,"level":"N1","type":"主词条","word":"一頃","kana":"ひところ","pos":"[名]","accent":"②","meaning":"曾有一时","example":"一頃が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“曾有一时”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n一頃が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“曾有一时”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2543","seq":2543,"level":"N1","type":"主词条","word":"人質","kana":"ひとじち","pos":"[名]","accent":"⓪","meaning":"人质","example":"経験豊かな人質の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“人质”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな人質の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“人质”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2544","seq":2544,"level":"N1","type":"主词条","word":"一筋に","kana":"ひとすじに","pos":"[副]","accent":"②","meaning":"一心一意，致力于","example":"彼女は研究一筋に歩んできたが、学生の相談にも時間を惜しまず丁寧に向き合っている。","exampleZh":"她一路一心投入研究，但对学生咨询也毫不吝惜时间，细致应对。","note":"例：\n彼女は研究一筋に歩んできたが、学生の相談にも時間を惜しまず丁寧に向き合っている。\n译：她一路一心投入研究，但对学生咨询也毫不吝惜时间，细致应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2545","seq":2545,"level":"N1","type":"主词条","word":"人並み","kana":"ひとなみ","pos":"[名·ナ形]","accent":"⓪","meaning":"普通，寻常","example":"人並みの生活を送ることさえ難しかった時期を、彼は家族の支えで何とか乗り越えた。","exampleZh":"在连普通生活都难以维持的时期，他靠家人的支持总算挺了过来。","note":"例：\n人並みの生活を送ることさえ難しかった時期を、彼は家族の支えで何とか乗り越えた。\n译：在连普通生活都难以维持的时期，他靠家人的支持总算挺了过来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2546","seq":2546,"level":"N1","type":"主词条","word":"人任せ","kana":"ひとまかせ","pos":"[名·ナ形]","accent":"③⓪","meaning":"委托给别人","example":"人任せな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“委托给别人”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n人任せな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“委托给别人”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2547","seq":2547,"level":"N1","type":"主词条","word":"一目ぼれ","kana":"ひとめぼれ","pos":"[名·自動3]","accent":"⓪","meaning":"一见钟情","example":"予期せず一目ぼれした場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“一见钟情”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず一目ぼれした場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“一见钟情”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2548","seq":2548,"level":"N1","type":"主词条","word":"日取り","kana":"ひどり","pos":"[名]","accent":"⓪","meaning":"日期，日子","example":"日取りを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“日期，日子”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n日取りを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“日期，日子”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2549","seq":2549,"level":"N1","type":"主词条","word":"一人ぼっち","kana":"ひとりぼっち","pos":"[名]","accent":"④","meaning":"孤单一人","example":"経験豊かな一人ぼっちの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“孤单一人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな一人ぼっちの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“孤单一人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2550","seq":2550,"level":"N1","type":"主词条","word":"独り身","kana":"ひとりみ","pos":"[名]","accent":"③⓪","meaning":"单身，独身","example":"独り身をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“单身，独身”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n独り身をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“单身，独身”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2551","seq":2551,"level":"N1","type":"主词条","word":"日向","kana":"ひなた","pos":"[名]","accent":"⓪","meaning":"向阳处","example":"日向をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“向阳处”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n日向をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“向阳处”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2552","seq":2552,"level":"N1","type":"主词条","word":"非難","kana":"ひなん","pos":"[名·他動3]","accent":"①","meaning":"非难，责难","example":"チームは非難する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“非难，责难”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは非難する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“非难，责难”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2553","seq":2553,"level":"N1","type":"主词条","word":"避難","kana":"ひなん","pos":"[名·自動3]","accent":"①","meaning":"避难，逃难","example":"津波警報が出たら、住民は荷物を取りに戻らず高台へ避難するよう訓練されている。","exampleZh":"一旦发布海啸警报，居民接受训练，应不回去取行李，而是前往高地避难。","note":"例：\n津波警報が出たら、住民は荷物を取りに戻らず高台へ避難するよう訓練されている。\n译：一旦发布海啸警报，居民接受训练，应不回去取行李，而是前往高地避难。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2554","seq":2554,"level":"N1","type":"主词条","word":"悲鳴","kana":"ひめい","pos":"[名·自動3]","accent":"⓪","meaning":"悲鸣，惊叫；叫苦声","example":"予期せず悲鳴した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“悲鸣，惊叫；叫苦声”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず悲鳴した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“悲鸣，惊叫；叫苦声”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2555","seq":2555,"level":"N1","type":"主词条","word":"秘める","kana":"ひめる","pos":"[他動2]","accent":"②","meaning":"隐藏，隐秘","example":"相手に何かを秘めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“隐藏，隐秘”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを秘めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“隐藏，隐秘”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2556","seq":2556,"level":"N1","type":"主词条","word":"冷やかす","kana":"ひやかす","pos":"[他動1]","accent":"③","meaning":"戏弄，嘲弄；逛（只看而不买）","example":"冷やかす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“戏弄，嘲弄；逛”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n冷やかす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“戏弄，嘲弄；逛”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2557","seq":2557,"level":"N1","type":"主词条","word":"ひょいと","kana":"ひょいと","pos":"[副]","accent":"①③","meaning":"出乎意料；偶然；轻松","example":"彼は重そうな箱をひょいと持ち上げ、周囲が驚くほど軽々と倉庫まで運んでいった。","exampleZh":"他轻轻松松地把看起来很重的箱子举起，轻快地搬到了仓库，令周围人吃惊。","note":"例：\n彼は重そうな箱をひょいと持ち上げ、周囲が驚くほど軽々と倉庫まで運んでいった。\n译：他轻轻松松地把看起来很重的箱子举起，轻快地搬到了仓库，令周围人吃惊。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2558","seq":2558,"level":"N1","type":"主词条","word":"氷河期","kana":"ひょうがき","pos":"[名]","accent":"③","meaning":"冰河期","example":"氷河期を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“冰河期”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n氷河期を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“冰河期”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2559","seq":2559,"level":"N1","type":"主词条","word":"表彰","kana":"ひょうしょう","pos":"[名·他動3]","accent":"⓪","meaning":"表彰","example":"表彰する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“表彰”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n表彰する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“表彰”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2560","seq":2560,"level":"N1","type":"主词条","word":"表する","kana":"ひょうする","pos":"[他動3]","accent":"③","meaning":"表示","example":"相手に何かを表するなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“表示”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを表するなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“表示”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2561","seq":2561,"level":"N1","type":"主词条","word":"病棟","kana":"びょうとう","pos":"[名]","accent":"⓪","meaning":"病房","example":"病棟に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。","exampleZh":"他感到“病房”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","note":"例：\n病棟に違和感を覚えた彼は、無理を続けず、予定を調整して早めに専門家へ相談した。\n译：他感到“病房”有些不对劲后，没有继续硬撑，而是调整日程并尽早咨询专家。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2562","seq":2562,"level":"N1","type":"主词条","word":"ひょっとすると","kana":"ひょっとすると","pos":"[副]","accent":"⓪","meaning":"或许，说不定","example":"ひょっとすると会議の前提が間違っているかもしれないと考え、彼は資料を最初から確認し直した。","exampleZh":"他想到会议的前提或许有误，于是从头重新确认了资料。","note":"例：\nひょっとすると会議の前提が間違っているかもしれないと考え、彼は資料を最初から確認し直した。\n译：他想到会议的前提或许有误，于是从头重新确认了资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2563","seq":2563,"level":"N1","type":"主词条","word":"びら","kana":"びら","pos":"[名]","accent":"⓪","meaning":"传单，招贴","example":"びらをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“传单，招贴”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nびらをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“传单，招贴”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2564","seq":2564,"level":"N1","type":"主词条","word":"平たい","kana":"ひらたい","pos":"[イ形]","accent":"⓪","meaning":"扁，扁平；浅显易懂","example":"平たいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。","exampleZh":"即使用“扁，扁平；浅显易懂”的做法获得利益，只要失去对方信任，长期来看就会造成巨大损失。","note":"例：\n平たいやり方で利益を得ても、相手の信頼を失えば長期的には大きな損失になる。\n译：即使用“扁，扁平；浅显易懂”的做法获得利益，只要失去对方信任，长期来看就会造成巨大损失。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2565","seq":2565,"level":"N1","type":"主词条","word":"閃く","kana":"ひらめく","pos":"[自動1]","accent":"③","meaning":"闪烁；（旗帜等）飘动；闪念","example":"自分の道を閃くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“闪烁；飘动”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を閃くなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“闪烁；飘动”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2566","seq":2566,"level":"N1","type":"主词条","word":"びり","kana":"びり","pos":"[名]","accent":"①","meaning":"倒数第一","example":"徒競走でびりになった少年は悔しそうだったが、最後まで走り切ったことを先生に褒められた。","exampleZh":"赛跑中拿了倒数第一的少年显得很懊悔，但老师表扬了他坚持跑完全程。","note":"例：\n徒競走でびりになった少年は悔しそうだったが、最後まで走り切ったことを先生に褒められた。\n译：赛跑中拿了倒数第一的少年显得很懊悔，但老师表扬了他坚持跑完全程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2567","seq":2567,"level":"N1","type":"主词条","word":"非力","kana":"ひりき","pos":"[名·ナ形]","accent":"⓪①","meaning":"力量薄弱，没有实力","example":"非力な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“力量薄弱，没有实力”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n非力な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“力量薄弱，没有实力”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2568","seq":2568,"level":"N1","type":"主词条","word":"微量","kana":"びりょう","pos":"[名]","accent":"⓪","meaning":"微量，少量","example":"微量の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“微量，少量”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n微量の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“微量，少量”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2569","seq":2569,"level":"N1","type":"主词条","word":"～びる","kana":"～びる","pos":"[接尾]","accent":"","meaning":"带有……的样子，看上去……","example":"彼の態度は少し大人びているが、失敗したときには年相応に悔しそうな表情を見せる。","exampleZh":"他的态度有些成熟，但失败时也会露出符合年龄的懊悔表情。","note":"例：\n彼の態度は少し大人びているが、失敗したときには年相応に悔しそうな表情を見せる。\n译：他的态度有些成熟，但失败时也会露出符合年龄的懊悔表情。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2570","seq":2570,"level":"N1","type":"主词条","word":"疲労","kana":"ひろう","pos":"[名·自動3]","accent":"⓪","meaning":"疲劳","example":"疲労してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“疲劳”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n疲労してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“疲劳”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2571","seq":2571,"level":"N1","type":"主词条","word":"ピンからキリまで","kana":"ぴんからきりまで","pos":"[副]","accent":"①⑤","meaning":"从最好的到最坏的","example":"同じ修理といっても料金はピンからキリまであるため、見積もりの内訳を確認してから依頼したほうがよい。","exampleZh":"同样是修理，价格也从高到低差别很大，所以最好确认报价明细后再委托。","note":"例：\n同じ修理といっても料金はピンからキリまであるため、見積もりの内訳を確認してから依頼したほうがよい。\n译：同样是修理，价格也从高到低差别很大，所以最好确认报价明细后再委托。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2572","seq":2572,"level":"N1","type":"主词条","word":"貧血","kana":"ひんけつ","pos":"[名·自動3]","accent":"⓪","meaning":"贫血","example":"貧血する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“贫血”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n貧血する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“贫血”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2573","seq":2573,"level":"N1","type":"主词条","word":"貧弱","kana":"ひんじゃく","pos":"[名·ナ形]","accent":"⓪","meaning":"寒碜，贫弱；内容贫乏","example":"貧弱な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“寒碜，贫弱；内容贫乏”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n貧弱な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“寒碜，贫弱；内容贫乏”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2574","seq":2574,"level":"N1","type":"主词条","word":"瀕する","kana":"ひんする","pos":"[自動3]","accent":"③","meaning":"濒临","example":"瀕する前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“濒临”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n瀕する前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“濒临”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2575","seq":2575,"level":"N1","type":"主词条","word":"ピンチ","kana":"ぴんち（pinch）","pos":"[名]","accent":"①","meaning":"紧急关头，危机","example":"ピンチが表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。","exampleZh":"当“紧急关头，危机”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","note":"例：\nピンチが表面化した時点で、責任者は隠すのではなく、影響の範囲と再発防止策を共有した。\n译：当“紧急关头，危机”表面化时，负责人没有隐瞒，而是共享了影响范围和防止再发措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2576","seq":2576,"level":"N1","type":"主词条","word":"ぴんと","kana":"ぴんと","pos":"[副]","accent":"⓪①","meaning":"立刻领会","example":"資料を読んだだけではぴんとこなかったが、現場を見学してようやく問題の深刻さが分かった。","exampleZh":"只看资料时还没有立刻领会，但参观现场后终于明白了问题的严重性。","note":"例：\n資料を読んだだけではぴんとこなかったが、現場を見学してようやく問題の深刻さが分かった。\n译：只看资料时还没有立刻领会，但参观现场后终于明白了问题的严重性。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2577","seq":2577,"level":"N1","type":"主词条","word":"頻繁","kana":"ひんぱん","pos":"[名·ナ形]","accent":"⓪","meaning":"频繁","example":"頻繁な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“频繁”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n頻繁な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“频繁”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2578","seq":2578,"level":"N1","type":"主词条","word":"ぴんぴん","kana":"ぴんぴん","pos":"[副·自動3]","accent":"①","meaning":"活蹦乱跳；硬朗；强烈地","example":"祖父は八十歳を過ぎてもぴんぴんしており、毎朝の散歩と畑仕事を欠かさない。","exampleZh":"祖父过了八十岁仍很硬朗，每天早晨散步和下地干活从不间断。","note":"例：\n祖父は八十歳を過ぎてもぴんぴんしており、毎朝の散歩と畑仕事を欠かさない。\n译：祖父过了八十岁仍很硬朗，每天早晨散步和下地干活从不间断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2579","seq":2579,"level":"N1","type":"主词条","word":"貧乏","kana":"びんぼう","pos":"[名·ナ形]","accent":"①","meaning":"贫穷","example":"学生時代は貧乏だったが、彼は図書館を活用して学び続け、研究者になる夢を諦めなかった。","exampleZh":"学生时代虽然贫穷，但他利用图书馆持续学习，没有放弃成为研究者的梦想。","note":"例：\n学生時代は貧乏だったが、彼は図書館を活用して学び続け、研究者になる夢を諦めなかった。\n译：学生时代虽然贫穷，但他利用图书馆持续学习，没有放弃成为研究者的梦想。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2580","seq":2580,"level":"N1","type":"主词条","word":"ひんやり","kana":"ひんやり","pos":"[副·自動3]","accent":"③","meaning":"阴凉，凉爽","example":"早朝の森はひんやりしていて、歩き始めたばかりの彼らは上着の襟を立てた。","exampleZh":"清晨的森林有些凉，刚开始步行的他们竖起了外套领子。","note":"例：\n早朝の森はひんやりしていて、歩き始めたばかりの彼らは上着の襟を立てた。\n译：清晨的森林有些凉，刚开始步行的他们竖起了外套领子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2581","seq":2581,"level":"N1","type":"主词条","word":"無愛想","kana":"ぶあいそう","pos":"[名·ナ形]","accent":"②","meaning":"简慢，冷淡","example":"無愛想な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“简慢，冷淡”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n無愛想な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“简慢，冷淡”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2582","seq":2582,"level":"N1","type":"主词条","word":"ファイト","kana":"ふぁいと（fight）","pos":"[名]","accent":"①⓪","meaning":"精力，斗志；加油","example":"ファイトの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“精力，斗志；加油”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nファイトの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“精力，斗志；加油”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2583","seq":2583,"level":"N1","type":"主词条","word":"不案内","kana":"ふあんない","pos":"[名·ナ形]","accent":"②","meaning":"不熟悉，不了解","example":"周囲から不案内だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“不熟悉，不了解”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から不案内だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“不熟悉，不了解”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2584","seq":2584,"level":"N1","type":"主词条","word":"不意","kana":"ふい","pos":"[名·ナ形]","accent":"⓪","meaning":"意外，想不到，突然","example":"不意に名前を呼ばれ、彼は返事に詰まったが、すぐに落ち着いて要件を確認した。","exampleZh":"突然被叫到名字，他一时答不上来，但很快冷静下来确认了事项。","note":"例：\n不意に名前を呼ばれ、彼は返事に詰まったが、すぐに落ち着いて要件を確認した。\n译：突然被叫到名字，他一时答不上来，但很快冷静下来确认了事项。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2585","seq":2585,"level":"N1","type":"主词条","word":"フィクション","kana":"フィクション（fiction）","pos":"[名]","accent":"①","meaning":"虚构","example":"フィクションに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“虚构”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nフィクションに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“虚构”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2586","seq":2586,"level":"N1","type":"主词条","word":"フィルター","kana":"ふぃるたー（filter）","pos":"[名]","accent":"⓪①","meaning":"过滤器，过滤嘴","example":"フィルターに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“过滤器，过滤嘴”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nフィルターに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“过滤器，过滤嘴”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2587","seq":2587,"level":"N1","type":"主词条","word":"封鎖","kana":"ふうさ","pos":"[名·他動3]","accent":"⓪①","meaning":"封锁","example":"封鎖の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“封锁”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n封鎖の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“封锁”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2588","seq":2588,"level":"N1","type":"主词条","word":"風俗","kana":"ふうぞく","pos":"[名]","accent":"①","meaning":"风俗，习俗","example":"風俗の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。","exampleZh":"在“风俗，习俗”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","note":"例：\n風俗の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。\n译：在“风俗，习俗”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2589","seq":2589,"level":"N1","type":"主词条","word":"不得手","kana":"ふえて","pos":"[名·ナ形]","accent":"②①","meaning":"不擅长","example":"不得手な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“不擅长”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n不得手な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“不擅长”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2590","seq":2590,"level":"N1","type":"主词条","word":"無遠慮","kana":"ぶえんりょ","pos":"[名·ナ形]","accent":"②","meaning":"不客气，直率","example":"一度無遠慮だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“不客气，直率”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度無遠慮だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“不客气，直率”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2591","seq":2591,"level":"N1","type":"主词条","word":"フォーム","kana":"ふぉーむ（form）","pos":"[名]","accent":"①","meaning":"姿势；形态","example":"フォームが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“姿势；形态”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nフォームが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“姿势；形态”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2592","seq":2592,"level":"N1","type":"主词条","word":"フォロー","kana":"ふぉろー（follow）","pos":"[名·他動3]","accent":"①","meaning":"帮助，援助；跟踪","example":"新人をフォローする際には、答えをすぐ与えるより、自分で考える余地を残すことも大切だ。","exampleZh":"支援新人时，与其立刻给出答案，有时保留让他自己思考的余地也很重要。","note":"例：\n新人をフォローする際には、答えをすぐ与えるより、自分で考える余地を残すことも大切だ。\n译：支援新人时，与其立刻给出答案，有时保留让他自己思考的余地也很重要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2593","seq":2593,"level":"N1","type":"主词条","word":"不穏","kana":"ふおん","pos":"[名·ナ形]","accent":"⓪","meaning":"不稳定","example":"不穏な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“不稳定”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n不穏な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“不稳定”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2594","seq":2594,"level":"N1","type":"主词条","word":"不可解","kana":"ふかかい","pos":"[名·ナ形]","accent":"②","meaning":"难以理解","example":"不可解な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“难以理解”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n不可解な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“难以理解”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2595","seq":2595,"level":"N1","type":"主词条","word":"不可避","kana":"ふかひ","pos":"[名·ナ形]","accent":"②","meaning":"不可避免","example":"一度不可避だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“不可避免”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度不可避だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“不可避免”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2596","seq":2596,"level":"N1","type":"主词条","word":"ぶかぶか","kana":"ぶかぶか","pos":"[ナ形·副]","accent":"⓪","meaning":"宽松肥大","example":"彼はぶかぶか結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。","exampleZh":"他没有急于作出“宽松肥大”的结论，而是在对照资料和现场声音后慎重决定方针。","note":"例：\n彼はぶかぶか結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。\n译：他没有急于作出“宽松肥大”的结论，而是在对照资料和现场声音后慎重决定方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2597","seq":2597,"level":"N1","type":"主词条","word":"深み","kana":"ふかみ","pos":"[名]","accent":"③⓪","meaning":"深处；深度","example":"深みを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“深处；深度”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n深みを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“深处；深度”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2598","seq":2598,"level":"N1","type":"主词条","word":"不吉","kana":"ふきつ","pos":"[名·ナ形]","accent":"⓪","meaning":"不吉利","example":"不吉な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“不吉利”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n不吉な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“不吉利”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2599","seq":2599,"level":"N1","type":"主词条","word":"複合","kana":"ふくごう","pos":"[名·自他動3]","accent":"⓪","meaning":"复合","example":"複合的な要因が絡んでいるため、担当者は一つの部署だけで問題を解決しようとはしなかった。","exampleZh":"由于多种复合因素交织在一起，负责人没有试图只靠一个部门来解决问题。","note":"例：\n複合的な要因が絡んでいるため、担当者は一つの部署だけで問題を解決しようとはしなかった。\n译：由于多种复合因素交织在一起，负责人没有试图只靠一个部门来解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2600","seq":2600,"level":"N1","type":"主词条","word":"副作用","kana":"ふくさよう","pos":"[名]","accent":"③","meaning":"副作用","example":"副作用に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“副作用”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n副作用に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“副作用”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2601","seq":2601,"level":"N1","type":"主词条","word":"服する","kana":"ふくする","pos":"[自動3]","accent":"③","meaning":"服从；从事","example":"服するような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“服从；从事”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n服するような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“服从；从事”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2602","seq":2602,"level":"N1","type":"主词条","word":"覆面","kana":"ふくめん","pos":"[名·自動3]","accent":"⓪","meaning":"蒙面；匿名","example":"覆面する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“蒙面；匿名”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n覆面する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“蒙面；匿名”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2603","seq":2603,"level":"N1","type":"主词条","word":"福利","kana":"ふくり","pos":"[名]","accent":"②","meaning":"福利","example":"福利を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“福利”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n福利を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“福利”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2604","seq":2604,"level":"N1","type":"主词条","word":"耽る","kana":"ふける","pos":"[自動1]","accent":"②","meaning":"沉溺，入迷","example":"耽るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“沉溺，入迷”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n耽るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“沉溺，入迷”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2605","seq":2605,"level":"N1","type":"主词条","word":"富豪","kana":"ふごう","pos":"[名]","accent":"⓪","meaning":"富豪","example":"富豪が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“富豪”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n富豪が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“富豪”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2606","seq":2606,"level":"N1","type":"主词条","word":"布告","kana":"ふこく","pos":"[名·他動3]","accent":"⓪","meaning":"布告","example":"布告する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“布告”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n布告する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“布告”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2607","seq":2607,"level":"N1","type":"主词条","word":"負債","kana":"ふさい","pos":"[名]","accent":"⓪","meaning":"负债","example":"負債をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“负债”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n負債をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“负债”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2608","seq":2608,"level":"N1","type":"主词条","word":"不在","kana":"ふざい","pos":"[名]","accent":"⓪","meaning":"不在，不在场","example":"不在の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“不在，不在场”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n不在の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“不在，不在场”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2609","seq":2609,"level":"N1","type":"主词条","word":"ふさわしい","kana":"ふさわしい","pos":"[イ形]","accent":"④","meaning":"合适，相称","example":"ふさわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“合适，相称”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nふさわしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“合适，相称”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2610","seq":2610,"level":"N1","type":"主词条","word":"不治","kana":"ふじ","pos":"[名]","accent":"②①","meaning":"不治，治不好","example":"不治が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“不治，治不好”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n不治が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“不治，治不好”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2611","seq":2611,"level":"N1","type":"主词条","word":"不順","kana":"ふじゅん","pos":"[名·ナ形]","accent":"⓪","meaning":"不顺利，不正常","example":"一度不順だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“不顺利，不正常”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度不順だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“不顺利，不正常”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2612","seq":2612,"level":"N1","type":"主词条","word":"不祥事","kana":"ふしょうじ","pos":"[名]","accent":"②","meaning":"丑闻，坏事","example":"不祥事を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。","exampleZh":"如果放任“丑闻，坏事”不管，不仅现场负担会增加，也可能失去使用者的信任。","note":"例：\n不祥事を放置すれば現場の負担が増えるだけでなく、利用者からの信頼も失われかねない。\n译：如果放任“丑闻，坏事”不管，不仅现场负担会增加，也可能失去使用者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2613","seq":2613,"level":"N1","type":"主词条","word":"侮辱","kana":"ぶじょく","pos":"[名·他動3]","accent":"⓪","meaning":"侮辱","example":"人前で同僚を侮辱するような発言は、本人だけでなく職場全体の信頼関係を傷つける。","exampleZh":"当众侮辱同事的发言，不仅会伤害本人，也会损害整个职场的信任关系。","note":"例：\n人前で同僚を侮辱するような発言は、本人だけでなく職場全体の信頼関係を傷つける。\n译：当众侮辱同事的发言，不仅会伤害本人，也会损害整个职场的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2614","seq":2614,"level":"N1","type":"主词条","word":"不振","kana":"ふしん","pos":"[名·ナ形]","accent":"⓪","meaning":"不兴旺，不兴隆；萧条","example":"周囲から不振だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“不兴旺，不兴隆；萧条”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から不振だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“不兴旺，不兴隆；萧条”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2615","seq":2615,"level":"N1","type":"主词条","word":"不審","kana":"ふしん","pos":"[名·ナ形]","accent":"⓪","meaning":"怀疑，疑惑","example":"不審な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“怀疑，疑惑”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n不審な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“怀疑，疑惑”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2616","seq":2616,"level":"N1","type":"主词条","word":"不信感","kana":"ふしんかん","pos":"[名]","accent":"②","meaning":"不信任的感觉","example":"一度生まれた不信感を消すには、口先の約束ではなく、小さな改善を継続して示すしかない。","exampleZh":"要消除一旦产生的不信任感，不能靠口头承诺，只能持续展示小小的改善。","note":"例：\n一度生まれた不信感を消すには、口先の約束ではなく、小さな改善を継続して示すしかない。\n译：要消除一旦产生的不信任感，不能靠口头承诺，只能持续展示小小的改善。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2617","seq":2617,"level":"N1","type":"主词条","word":"不摂生","kana":"ふせっせい","pos":"[名·ナ形]","accent":"②","meaning":"不健康，不注意养生","example":"不摂生な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。","exampleZh":"要保持“不健康，不注意养生”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","note":"例：\n不摂生な状態を保つには、無理を重ねてから休むのではなく、日頃の小さな変化に早く気づくことが大切だ。\n译：要保持“不健康，不注意养生”的状态，重要的不是过度勉强之后再休息，而是平日里及早察觉细小变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2618","seq":2618,"level":"N1","type":"主词条","word":"伏せる","kana":"ふせる","pos":"[他動2]","accent":"②","meaning":"趴下，朝下；掩盖，不公开","example":"事実を伏せる前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。","exampleZh":"在“趴下，朝下；掩盖，不公开”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","note":"例：\n事実を伏せる前に、彼は関係者が受ける影響と伝える時期を慎重に考えた。\n译：在“趴下，朝下；掩盖，不公开”事实之前，他慎重考虑了相关人员会受到的影响以及传达时机。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2619","seq":2619,"level":"N1","type":"主词条","word":"普段着","kana":"ふだんぎ","pos":"[名]","accent":"②⓪","meaning":"便服，便装","example":"式典に着ていく普段着を選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“便服，便装”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていく普段着を選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“便服，便装”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2620","seq":2620,"level":"N1","type":"主词条","word":"不調","kana":"ふちょう","pos":"[名·ナ形]","accent":"⓪","meaning":"（谈判等）破裂；状态不佳","example":"機械の動きが不調で、担当者は本番前に部品の交換と再点検を急いだ。","exampleZh":"机器运转状态不佳，负责人在正式开始前急忙更换零件并重新检查。","note":"例：\n機械の動きが不調で、担当者は本番前に部品の交換と再点検を急いだ。\n译：机器运转状态不佳，负责人在正式开始前急忙更换零件并重新检查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2621","seq":2621,"level":"N1","type":"主词条","word":"復活","kana":"ふっかつ","pos":"[名·自他動3]","accent":"⓪","meaning":"复活，复兴","example":"地元の祭りを復活させるため、若者たちは古い資料を集め、年配者から手順を聞き取った。","exampleZh":"为了复兴当地祭典，年轻人收集旧资料，并向年长者询问流程。","note":"例：\n地元の祭りを復活させるため、若者たちは古い資料を集め、年配者から手順を聞き取った。\n译：为了复兴当地祭典，年轻人收集旧资料，并向年长者询问流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2622","seq":2622,"level":"N1","type":"主词条","word":"物議","kana":"ぶつぎ","pos":"[名]","accent":"①","meaning":"纷纷议论","example":"物議が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“纷纷议论”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n物議が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“纷纷议论”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2623","seq":2623,"level":"N1","type":"主词条","word":"復旧","kana":"ふっきゅう","pos":"[名·自他動3]","accent":"⓪","meaning":"复原，恢复原状","example":"台風で止まっていた電力が復旧し、避難所にはようやく明かりが戻った。","exampleZh":"因台风中断的电力恢复后，避难所终于重新亮了起来。","note":"例：\n台風で止まっていた電力が復旧し、避難所にはようやく明かりが戻った。\n译：因台风中断的电力恢复后，避难所终于重新亮了起来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2624","seq":2624,"level":"N1","type":"主词条","word":"物件","kana":"ぶっけん","pos":"[名]","accent":"⓪","meaning":"房产，地产；物品","example":"古い物件を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“房产，地产；物品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古い物件を不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“房产，地产；物品”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2625","seq":2625,"level":"N1","type":"主词条","word":"物件費","kana":"ぶっけんひ","pos":"[名]","accent":"③","meaning":"物品费","example":"新規事業では物件費の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。","exampleZh":"在新业务中，如果对“物品费”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","note":"例：\n新規事業では物件費の見通しが甘いと、最初は順調に見えても資金繰りがすぐに行き詰まる。\n译：在新业务中，如果对“物品费”的预估过于乐观，即使起初看似顺利，资金周转也会很快陷入困境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2626","seq":2626,"level":"N1","type":"主词条","word":"復興","kana":"ふっこう","pos":"[名·自他動3]","accent":"⓪","meaning":"复兴","example":"初めて復興する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“复兴”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて復興する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“复兴”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2627","seq":2627,"level":"N1","type":"主词条","word":"物資","kana":"ぶっし","pos":"[名]","accent":"①","meaning":"物资","example":"物資を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“物资”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n物資を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“物资”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2628","seq":2628,"level":"N1","type":"主词条","word":"物色","kana":"ぶっしょく","pos":"[名·他動3]","accent":"⓪","meaning":"物色，选择","example":"彼は物色を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“物色，选择”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は物色を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“物色，选择”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2629","seq":2629,"level":"N1","type":"主词条","word":"不当","kana":"ふとう","pos":"[名·ナ形]","accent":"⓪","meaning":"不正当，非法","example":"周囲から不当だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“不正当，非法”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から不当だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“不正当，非法”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2630","seq":2630,"level":"N1","type":"主词条","word":"無難","kana":"ぶなん","pos":"[名·ナ形]","accent":"⓪①","meaning":"无可非议","example":"無難な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“无可非议”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n無難な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“无可非议”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2631","seq":2631,"level":"N1","type":"主词条","word":"赴任","kana":"ふにん","pos":"[名·自動3]","accent":"⓪","meaning":"赴任","example":"地方へ赴任した彼は、まず土地の習慣を学び、前任者のやり方を急に変えないよう心がけた。","exampleZh":"赴任到地方的他，首先学习当地习惯，并注意不要突然改变前任的做法。","note":"例：\n地方へ赴任した彼は、まず土地の習慣を学び、前任者のやり方を急に変えないよう心がけた。\n译：赴任到地方的他，首先学习当地习惯，并注意不要突然改变前任的做法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2632","seq":2632,"level":"N1","type":"主词条","word":"不備","kana":"ふび","pos":"[名·ナ形]","accent":"①","meaning":"不完备","example":"申請書に不備があったため、窓口の職員は足りない書類を分かりやすく伝えた。","exampleZh":"由于申请书存在不完备之处，窗口工作人员清楚说明了缺少的文件。","note":"例：\n申請書に不備があったため、窓口の職員は足りない書類を分かりやすく伝えた。\n译：由于申请书存在不完备之处，窗口工作人员清楚说明了缺少的文件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2633","seq":2633,"level":"N1","type":"主词条","word":"不評","kana":"ふひょう","pos":"[名·ナ形]","accent":"⓪","meaning":"评价不高，声誉不好","example":"不評な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“评价不高，声誉不好”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n不評な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“评价不高，声誉不好”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2634","seq":2634,"level":"N1","type":"主词条","word":"不服","kana":"ふふく","pos":"[名·ナ形]","accent":"⓪","meaning":"异议；不服，不满","example":"周囲から不服だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“异议；不服，不满”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から不服だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“异议；不服，不满”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2635","seq":2635,"level":"N1","type":"主词条","word":"不本意","kana":"ふほんい","pos":"[名·ナ形]","accent":"②","meaning":"不情愿，不是出于本意","example":"一度不本意だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“不情愿，不是出于本意”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度不本意だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“不情愿，不是出于本意”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2636","seq":2636,"level":"N1","type":"主词条","word":"踏まえる","kana":"ふまえる","pos":"[他動2]","accent":"③②","meaning":"根据","example":"踏まえる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“根据”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n踏まえる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“根据”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2637","seq":2637,"level":"N1","type":"主词条","word":"踏み込む","kana":"ふみこむ","pos":"[自他動1]","accent":"③","meaning":"用力踩；闯入，深入","example":"無理に踏み込むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“用力踩；闯入，深入”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に踏み込むよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“用力踩；闯入，深入”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2638","seq":2638,"level":"N1","type":"主词条","word":"踏み場","kana":"ふみば","pos":"[名]","accent":"⓪","meaning":"落脚处","example":"踏み場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“落脚处”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n踏み場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“落脚处”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2639","seq":2639,"level":"N1","type":"主词条","word":"不眠症","kana":"ふみんしょう","pos":"[名]","accent":"⓪②","meaning":"失眠症","example":"不眠症の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“失眠症”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n不眠症の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“失眠症”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2640","seq":2640,"level":"N1","type":"主词条","word":"ふやける","kana":"ふやける","pos":"[自動2]","accent":"③","meaning":"泡涨；懒散","example":"ふやけるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“泡涨；懒散”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\nふやけるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“泡涨；懒散”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2641","seq":2641,"level":"N1","type":"主词条","word":"冬山","kana":"ふゆやま","pos":"[名]","accent":"⓪","meaning":"冬天的山","example":"冬山に入る前には、天気の急変に備えて装備と撤退ルートを必ず確認するべきだ。","exampleZh":"进入冬季山地前，应务必确认装备和撤退路线，以防天气骤变。","note":"例：\n冬山に入る前には、天気の急変に備えて装備と撤退ルートを必ず確認するべきだ。\n译：进入冬季山地前，应务必确认装备和撤退路线，以防天气骤变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2642","seq":2642,"level":"N1","type":"主词条","word":"扶養","kana":"ふよう","pos":"[名·他動3]","accent":"⓪","meaning":"抚养，赡养","example":"初めて扶養する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“抚养，赡养”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて扶養する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“抚养，赡养”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2643","seq":2643,"level":"N1","type":"主词条","word":"不要","kana":"ふよう","pos":"[名·ナ形]","accent":"⓪","meaning":"不要，不需要","example":"不要な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“不要，不需要”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n不要な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“不要，不需要”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2644","seq":2644,"level":"N1","type":"主词条","word":"プライド","kana":"ぷらいど（pride）","pos":"[名]","accent":"⓪","meaning":"自尊心，自豪感","example":"プライドが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“自尊心，自豪感”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nプライドが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“自尊心，自豪感”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2645","seq":2645,"level":"N1","type":"主词条","word":"プライバシー","kana":"ぷらいばしー（privacy）","pos":"[名]","accent":"②","meaning":"隐私","example":"プライバシーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“隐私”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nプライバシーに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“隐私”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2646","seq":2646,"level":"N1","type":"主词条","word":"ふらふら","kana":"ふらふら","pos":"[副·自動3]","accent":"①","meaning":"摇晃；不坚定","example":"高熱で足元がふらふらするなら、無理に出勤せず病院で診てもらったほうがよい。","exampleZh":"如果高烧到脚步发飘，就不要勉强上班，最好去医院看看。","note":"例：\n高熱で足元がふらふらするなら、無理に出勤せず病院で診てもらったほうがよい。\n译：如果高烧到脚步发飘，就不要勉强上班，最好去医院看看。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2647","seq":2647,"level":"N1","type":"主词条","word":"ぶらぶら","kana":"ぶらぶら","pos":"[副·自動3]","accent":"①","meaning":"闲逛；赋闲，无所事事","example":"休日の午後、彼は目的もなく商店街をぶらぶら歩き、気になる古書店に立ち寄った。","exampleZh":"休日下午，他漫无目的地在商店街闲逛，顺路走进了一家感兴趣的旧书店。","note":"例：\n休日の午後、彼は目的もなく商店街をぶらぶら歩き、気になる古書店に立ち寄った。\n译：休日下午，他漫无目的地在商店街闲逛，顺路走进了一家感兴趣的旧书店。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2648","seq":2648,"level":"N1","type":"主词条","word":"ブランク","kana":"ぶらんく（blank）","pos":"[名]","accent":"②","meaning":"空白，空白期","example":"ブランクが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“空白，空白期”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nブランクが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“空白，空白期”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2649","seq":2649,"level":"N1","type":"主词条","word":"ブランド","kana":"ぶらんど（brand）","pos":"[名]","accent":"⓪","meaning":"商标，品牌","example":"ブランドを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“商标，品牌”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nブランドを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“商标，品牌”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2650","seq":2650,"level":"N1","type":"主词条","word":"フリーズ","kana":"ふりーず（freeze）","pos":"[名·自他動3]","accent":"②","meaning":"结冰，冷冻；死机","example":"彼はフリーズを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“结冰，冷冻；死机”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼はフリーズを急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“结冰，冷冻；死机”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2651","seq":2651,"level":"N1","type":"主词条","word":"振り替え","kana":"ふりかえ","pos":"[名]","accent":"⓪","meaning":"（临时）更换，调换；转账","example":"振り替えが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“更换，调换；转账”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n振り替えが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“更换，调换；转账”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2652","seq":2652,"level":"N1","type":"主词条","word":"振り返る","kana":"ふりかえる","pos":"[他動1]","accent":"③","meaning":"回头看；回顾","example":"無理に振り返るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“回头看；回顾”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に振り返るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“回头看；回顾”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2653","seq":2653,"level":"N1","type":"主词条","word":"振り込み","kana":"ふりこみ","pos":"[名]","accent":"⓪","meaning":"存入","example":"振り込みをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“存入”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n振り込みをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“存入”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2654","seq":2654,"level":"N1","type":"主词条","word":"振り出し","kana":"ふりだし","pos":"[名]","accent":"⓪","meaning":"原来的状态，起点","example":"振り出しの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“原来的状态，起点”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n振り出しの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“原来的状态，起点”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2655","seq":2655,"level":"N1","type":"主词条","word":"武力","kana":"ぶりょく","pos":"[名]","accent":"①","meaning":"武力","example":"武力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。","exampleZh":"感到“武力”不足后，他观察有经验者的做法，并将其纳入每日练习。","note":"例：\n武力が不足していると感じた彼は、経験者のやり方を観察し、毎日の練習に取り入れた。\n译：感到“武力”不足后，他观察有经验者的做法，并将其纳入每日练习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2656","seq":2656,"level":"N1","type":"主词条","word":"フル","kana":"ふる（full）","pos":"[名·ナ形]","accent":"①","meaning":"充分；全部","example":"一度フルだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“充分；全部”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度フルだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“充分；全部”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2657","seq":2657,"level":"N1","type":"主词条","word":"～ぶる","kana":"～ぶる","pos":"[接尾]","accent":"","meaning":"装作……的样子，摆……架子","example":"彼は偉ぶるところがなく、若い社員の意見にも最後まで耳を傾けるため、現場から信頼されている。","exampleZh":"他没有摆架子的地方，对年轻员工的意见也会听到最后，因此深受现场信任。","note":"例：\n彼は偉ぶるところがなく、若い社員の意見にも最後まで耳を傾けるため、現場から信頼されている。\n译：他没有摆架子的地方，对年轻员工的意见也会听到最后，因此深受现场信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2658","seq":2658,"level":"N1","type":"主词条","word":"古めかしい","kana":"ふるめかしい","pos":"[イ形]","accent":"⑤","meaning":"古老，古色古香","example":"古めかしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“古老，古色古香”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n古めかしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“古老，古色古香”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2659","seq":2659,"level":"N1","type":"主词条","word":"触れ合い","kana":"ふれあい","pos":"[名]","accent":"⓪","meaning":"互相接触，交流","example":"触れ合いに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“互相接触，交流”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n触れ合いに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“互相接触，交流”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2660","seq":2660,"level":"N1","type":"主词条","word":"無礼講","kana":"ぶれいこう","pos":"[名]","accent":"⓪","meaning":"开怀畅饮","example":"無礼講に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“开怀畅饮”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n無礼講に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“开怀畅饮”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2661","seq":2661,"level":"N1","type":"主词条","word":"ブレーク","kana":"ぶれーく（break）","pos":"[名·自動3]","accent":"②","meaning":"短暂休息；受欢迎","example":"長時間の作業では短いブレークを入れるだけで、集中力と判断の正確さがかなり戻る。","exampleZh":"长时间作业中只要加入短暂休息，集中力和判断准确度就能相当程度地恢复。","note":"例：\n長時間の作業では短いブレークを入れるだけで、集中力と判断の正確さがかなり戻る。\n译：长时间作业中只要加入短暂休息，集中力和判断准确度就能相当程度地恢复。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2662","seq":2662,"level":"N1","type":"主词条","word":"プレゼンテーション","kana":"ぷれぜんてーしょん（presentation）","pos":"[名]","accent":"⑤","meaning":"公开演示，发表","example":"説得力のあるプレゼンテーションにするには、派手な資料よりも聞き手が知りたい論点を先に示すことが大切だ。","exampleZh":"要做有说服力的发表，比起华丽资料，更重要的是先提出听众想知道的论点。","note":"例：\n説得力のあるプレゼンテーションにするには、派手な資料よりも聞き手が知りたい論点を先に示すことが大切だ。\n译：要做有说服力的发表，比起华丽资料，更重要的是先提出听众想知道的论点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2663","seq":2663,"level":"N1","type":"主词条","word":"プレッシャー","kana":"ぷれっしゃー（pressure）","pos":"[名]","accent":"②","meaning":"（精神方面的）压力，压迫","example":"大きなプレッシャーを感じても、彼女は深呼吸をして、練習どおり最初の一言を発した。","exampleZh":"即使感到巨大压力，她也深呼吸后，按练习时那样说出了第一句话。","note":"例：\n大きなプレッシャーを感じても、彼女は深呼吸をして、練習どおり最初の一言を発した。\n译：即使感到巨大压力，她也深呼吸后，按练习时那样说出了第一句话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2664","seq":2664,"level":"N1","type":"主词条","word":"付録","kana":"ふろく","pos":"[名]","accent":"⓪","meaning":"附录，增刊","example":"付録の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“附录，增刊”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n付録の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“附录，增刊”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2665","seq":2665,"level":"N1","type":"主词条","word":"プロセス","kana":"ぷろせす（process）","pos":"[名]","accent":"②","meaning":"手续，程序；过程","example":"プロセスをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“手续，程序；过程”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nプロセスをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“手续，程序；过程”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2666","seq":2666,"level":"N1","type":"主词条","word":"ブロック","kana":"ぶろっく（block）","pos":"[名]","accent":"②","meaning":"街区","example":"ブロックの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“街区”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\nブロックの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“街区”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2667","seq":2667,"level":"N1","type":"主词条","word":"憤慨","kana":"ふんがい","pos":"[名·自他動3]","accent":"⓪","meaning":"愤慨","example":"憤慨の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“愤慨”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n憤慨の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“愤慨”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2668","seq":2668,"level":"N1","type":"主词条","word":"分業","kana":"ぶんぎょう","pos":"[名·自動3]","accent":"⓪","meaning":"分工","example":"分業するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“分工”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n分業するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“分工”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2669","seq":2669,"level":"N1","type":"主词条","word":"分散","kana":"ぶんさん","pos":"[名·自他動3]","accent":"⓪","meaning":"分散","example":"リスクを分散しておけば、一つの取引先で問題が起きても事業全体への影響を抑えられる。","exampleZh":"只要分散风险，即使某个客户发生问题，也能抑制对整体业务的影响。","note":"例：\nリスクを分散しておけば、一つの取引先で問題が起きても事業全体への影響を抑えられる。\n译：只要分散风险，即使某个客户发生问题，也能抑制对整体业务的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2670","seq":2670,"level":"N1","type":"主词条","word":"奮闘","kana":"ふんとう","pos":"[名·自動3]","accent":"⓪","meaning":"奋战","example":"奮闘してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“奋战”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n奮闘してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“奋战”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2671","seq":2671,"level":"N1","type":"主词条","word":"粉末","kana":"ふんまつ","pos":"[名]","accent":"⓪","meaning":"粉末","example":"限られた粉末の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“粉末”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた粉末の中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“粉末”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2672","seq":2672,"level":"N1","type":"主词条","word":"分裂","kana":"ぶんれつ","pos":"[名·自動3]","accent":"⓪","meaning":"分裂","example":"分裂する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“分裂”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n分裂する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“分裂”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2673","seq":2673,"level":"N1","type":"主词条","word":"ペア","kana":"ぺあ（pair）","pos":"[名]","accent":"①","meaning":"一双，一对","example":"ペアに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“一双，一对”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nペアに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“一双，一对”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2674","seq":2674,"level":"N1","type":"主词条","word":"弊害","kana":"へいがい","pos":"[名]","accent":"⓪","meaning":"危害，弊病","example":"医師は弊害の状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。","exampleZh":"医生没有只凭“危害，弊病”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","note":"例：\n医師は弊害の状態だけで判断せず、痛みが出た時期や仕事中の姿勢まで詳しく聞き取った。\n译：医生没有只凭“危害，弊病”的状态判断，还详细询问了疼痛出现的时间和工作时的姿势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2675","seq":2675,"level":"N1","type":"主词条","word":"平衡","kana":"へいこう","pos":"[名]","accent":"⓪","meaning":"平衡","example":"心と体の平衡を保つには、仕事の量だけでなく、休む時間の取り方も意識する必要がある。","exampleZh":"要保持身心平衡，不仅要注意工作量，也要有意识地安排休息时间。","note":"例：\n心と体の平衡を保つには、仕事の量だけでなく、休む時間の取り方も意識する必要がある。\n译：要保持身心平衡，不仅要注意工作量，也要有意识地安排休息时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2676","seq":2676,"level":"N1","type":"主词条","word":"並行","kana":"へいこう","pos":"[名·自動3]","accent":"⓪","meaning":"并行；并进，同时进行","example":"並行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“并行；并进，同时进行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n並行した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“并行；并进，同时进行”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2677","seq":2677,"level":"N1","type":"主词条","word":"平常","kana":"へいじょう","pos":"[名·副]","accent":"⓪","meaning":"平常，平时","example":"災害時こそ平常の手順を守ることで、慌てた判断による二次的な混乱を防ぐことができる。","exampleZh":"正是在灾害时遵守平时的步骤，才能防止慌乱判断造成二次混乱。","note":"例：\n災害時こそ平常の手順を守ることで、慌てた判断による二次的な混乱を防ぐことができる。\n译：正是在灾害时遵守平时的步骤，才能防止慌乱判断造成二次混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2678","seq":2678,"level":"N1","type":"主词条","word":"平常心","kana":"へいじょうしん","pos":"[名]","accent":"③","meaning":"平常心","example":"平常心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“平常心”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n平常心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“平常心”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2679","seq":2679,"level":"N1","type":"主词条","word":"平静","kana":"へいせい","pos":"[名·ナ形]","accent":"⓪","meaning":"平静，镇静","example":"突然の知らせにも平静を保ち、彼女はまず家族の安全を確認する電話をかけた。","exampleZh":"面对突然的消息，她仍保持平静，首先打电话确认家人安全。","note":"例：\n突然の知らせにも平静を保ち、彼女はまず家族の安全を確認する電話をかけた。\n译：面对突然的消息，她仍保持平静，首先打电话确认家人安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2680","seq":2680,"level":"N1","type":"主词条","word":"平年","kana":"へいねん","pos":"[名]","accent":"⓪","meaning":"普通年份，常年，往年","example":"平年の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“普通年份，常年，往年”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n平年の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“普通年份，常年，往年”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2681","seq":2681,"level":"N1","type":"主词条","word":"並列","kana":"へいれつ","pos":"[名·自動3]","accent":"⓪","meaning":"并列，并排","example":"並列した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“并列，并排”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n並列した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“并列，并排”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2682","seq":2682,"level":"N1","type":"主词条","word":"ベース","kana":"べーす（base）","pos":"[名]","accent":"①⓪","meaning":"基本，基础","example":"ベースをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“基本，基础”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nベースをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“基本，基础”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2683","seq":2683,"level":"N1","type":"主词条","word":"ペース","kana":"ぺーす（pace）","pos":"[名]","accent":"①","meaning":"步调，步伐；速度，进度","example":"自分のペースを守って勉強を続けたことで、彼は試験直前になっても落ち着いて復習できた。","exampleZh":"通过按照自己的节奏持续学习，他即使在考试前夕也能冷静复习。","note":"例：\n自分のペースを守って勉強を続けたことで、彼は試験直前になっても落ち着いて復習できた。\n译：通过按照自己的节奏持续学习，他即使在考试前夕也能冷静复习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2684","seq":2684,"level":"N1","type":"主词条","word":"辟易","kana":"へきえき","pos":"[名·自動3]","accent":"⓪","meaning":"退缩，畏缩；束手无策","example":"予期せず辟易した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“退缩，畏缩；束手无策”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず辟易した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“退缩，畏缩；束手无策”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2685","seq":2685,"level":"N1","type":"主词条","word":"ぺこぺこ","kana":"ぺこぺこ","pos":"[副·ナ形·自動3]","accent":"①","meaning":"凹陷；（肚子）饿，空；点头哈腰","example":"朝から何も食べていなかったので、お腹がぺこぺこで会議に集中できなかった。","exampleZh":"从早上起什么都没吃，肚子饿得咕咕叫，无法集中参加会议。","note":"例：\n朝から何も食べていなかったので、お腹がぺこぺこで会議に集中できなかった。\n译：从早上起什么都没吃，肚子饿得咕咕叫，无法集中参加会议。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2686","seq":2686,"level":"N1","type":"主词条","word":"ベスト","kana":"べすと（best）","pos":"[名]","accent":"①","meaning":"最好；全力","example":"ベストを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“最好；全力”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\nベストを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“最好；全力”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2687","seq":2687,"level":"N1","type":"主词条","word":"別居","kana":"べっきょ","pos":"[名·自動3]","accent":"⓪","meaning":"分居","example":"別居する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“分居”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n別居する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“分居”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2688","seq":2688,"level":"N1","type":"主词条","word":"べらべら","kana":"べらべら","pos":"[副·自動3]","accent":"①","meaning":"喋喋不休，口若悬河","example":"彼は初対面の相手にもべらべら話すが、肝心な点を説明し忘れることがある。","exampleZh":"他即使面对初次见面的人也滔滔不绝，但有时会忘记说明关键点。","note":"例：\n彼は初対面の相手にもべらべら話すが、肝心な点を説明し忘れることがある。\n译：他即使面对初次见面的人也滔滔不绝，但有时会忘记说明关键点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2689","seq":2689,"level":"N1","type":"主词条","word":"謙る","kana":"へりくだる","pos":"[自動1]","accent":"④⓪","meaning":"谦虚，谦恭","example":"謙る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“谦虚，谦恭”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n謙る場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“谦虚，谦恭”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2690","seq":2690,"level":"N1","type":"主词条","word":"経る","kana":"へる","pos":"[自動2]","accent":"①","meaning":"经过；经历","example":"経るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“经过；经历”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n経るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“经过；经历”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2691","seq":2691,"level":"N1","type":"主词条","word":"弁解","kana":"べんかい","pos":"[名·自他動3]","accent":"⓪","meaning":"辩解","example":"弁解の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“辩解”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n弁解の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“辩解”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2692","seq":2692,"level":"N1","type":"主词条","word":"返還","kana":"へんかん","pos":"[名·他動3]","accent":"⓪","meaning":"归还，退还","example":"彼は返還を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“归还，退还”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は返還を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“归还，退还”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2693","seq":2693,"level":"N1","type":"主词条","word":"便宜","kana":"べんぎ","pos":"[名]","accent":"①","meaning":"方便，特别处理","example":"便宜を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“方便，特别处理”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n便宜を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“方便，特别处理”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2694","seq":2694,"level":"N1","type":"主词条","word":"返却","kana":"へんきゃく","pos":"[名·他動3]","accent":"⓪","meaning":"归还，退还","example":"返却する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“归还，退还”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n返却する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“归还，退还”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2695","seq":2695,"level":"N1","type":"主词条","word":"変形","kana":"へんけい","pos":"[名·自他動3]","accent":"⓪","meaning":"变形","example":"高温の場所に置いていた容器が変形し、ふたがきちんと閉まらなくなった。","exampleZh":"放在高温处的容器变形了，盖子无法严丝合缝地关上。","note":"例：\n高温の場所に置いていた容器が変形し、ふたがきちんと閉まらなくなった。\n译：放在高温处的容器变形了，盖子无法严丝合缝地关上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2696","seq":2696,"level":"N1","type":"主词条","word":"偏見","kana":"へんけん","pos":"[名]","accent":"⓪","meaning":"偏见","example":"偏見を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“偏见”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n偏見を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“偏见”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2697","seq":2697,"level":"N1","type":"主词条","word":"弁護","kana":"べんご","pos":"[名·他動3]","accent":"①","meaning":"辩护","example":"弁護した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“辩护”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n弁護した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“辩护”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2698","seq":2698,"level":"N1","type":"主词条","word":"偏向","kana":"へんこう","pos":"[名·自動3]","accent":"⓪","meaning":"偏向","example":"偏向するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“偏向”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n偏向するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“偏向”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2699","seq":2699,"level":"N1","type":"主词条","word":"返済","kana":"へんさい","pos":"[名·他動3]","accent":"⓪","meaning":"还，偿还","example":"返済の計画を立てる際には、毎月の収入だけでなく、急な出費に備える余裕も残しておくべきだ。","exampleZh":"制定偿还计划时，不仅要考虑每月收入，也应留下应对突发支出的余地。","note":"例：\n返済の計画を立てる際には、毎月の収入だけでなく、急な出費に備える余裕も残しておくべきだ。\n译：制定偿还计划时，不仅要考虑每月收入，也应留下应对突发支出的余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2700","seq":2700,"level":"N1","type":"主词条","word":"返上","kana":"へんじょう","pos":"[名·他動3]","accent":"⓪","meaning":"奉还，归还","example":"彼は返上を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“奉还，归还”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は返上を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“奉还，归还”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2701","seq":2701,"level":"N1","type":"主词条","word":"弁償","kana":"べんしょう","pos":"[名·他動3]","accent":"⓪","meaning":"赔偿（损失）；偿还（债务）","example":"友人のカメラを壊してしまったため、彼は修理代を全額弁償することにした。","exampleZh":"由于弄坏了朋友的相机，他决定全额赔偿修理费。","note":"例：\n友人のカメラを壊してしまったため、彼は修理代を全額弁償することにした。\n译：由于弄坏了朋友的相机，他决定全额赔偿修理费。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2702","seq":2702,"level":"N1","type":"主词条","word":"変身","kana":"へんしん","pos":"[名·自動3]","accent":"⓪","meaning":"乔装打扮；变成","example":"変身する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“乔装打扮；变成”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n変身する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“乔装打扮；变成”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2703","seq":2703,"level":"N1","type":"主词条","word":"編成","kana":"へんせい","pos":"[名·他動3]","accent":"⓪","meaning":"编成，组成","example":"編成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“编成，组成”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n編成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“编成，组成”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2704","seq":2704,"level":"N1","type":"主词条","word":"変遷","kana":"へんせん","pos":"[名·自動3]","accent":"⓪","meaning":"变迁","example":"予期せず変遷した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“变迁”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず変遷した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“变迁”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2705","seq":2705,"level":"N1","type":"主词条","word":"偏重","kana":"へんちょう","pos":"[名·他動3]","accent":"⓪","meaning":"偏重","example":"偏重した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“偏重”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n偏重した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“偏重”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2706","seq":2706,"level":"N1","type":"主词条","word":"返答","kana":"へんとう","pos":"[名·自動3]","accent":"③⓪","meaning":"回答，回话","example":"すぐに返答できない質問には、彼は期限を明確にしてから改めて調べると約束した。","exampleZh":"对于不能马上回答的问题，他明确期限，并承诺之后重新调查。","note":"例：\nすぐに返答できない質問には、彼は期限を明確にしてから改めて調べると約束した。\n译：对于不能马上回答的问题，他明确期限，并承诺之后重新调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2707","seq":2707,"level":"N1","type":"主词条","word":"返品","kana":"へんぴん","pos":"[名·他動3]","accent":"⓪","meaning":"退货","example":"返品の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“退货”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n返品の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“退货”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2708","seq":2708,"level":"N1","type":"主词条","word":"変容","kana":"へんよう","pos":"[名·自動3]","accent":"⓪","meaning":"变样，改观","example":"変容するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“变样，改观”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n変容するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“变样，改观”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2709","seq":2709,"level":"N1","type":"主词条","word":"穂","kana":"ほ","pos":"[名]","accent":"①","meaning":"穗；枪头，穗状物的尖端","example":"穂を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“穗；枪头，穗状物的尖端”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n穂を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“穗；枪头，穗状物的尖端”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2710","seq":2710,"level":"N1","type":"主词条","word":"ボイコット","kana":"ぼいこっと（boycott）","pos":"[名·他動3]","accent":"③","meaning":"抵制，联合抵制","example":"ボイコットした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“抵制，联合抵制”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\nボイコットした結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“抵制，联合抵制”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2711","seq":2711,"level":"N1","type":"主词条","word":"防衛","kana":"ぼうえい","pos":"[名·他動3]","accent":"⓪","meaning":"防卫","example":"国を防衛する議論では、軍事力だけでなく、外交や市民生活への影響も考えなければならない。","exampleZh":"讨论国家防卫时，不仅要考虑军事力量，也必须考虑外交和市民生活受到的影响。","note":"例：\n国を防衛する議論では、軍事力だけでなく、外交や市民生活への影響も考えなければならない。\n译：讨论国家防卫时，不仅要考虑军事力量，也必须考虑外交和市民生活受到的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2712","seq":2712,"level":"N1","type":"主词条","word":"崩壊","kana":"ほうかい","pos":"[名·自動3]","accent":"⓪","meaning":"崩溃，垮台","example":"崩壊する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“崩溃，垮台”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n崩壊する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“崩溃，垮台”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2713","seq":2713,"level":"N1","type":"主词条","word":"妨害","kana":"ぼうがい","pos":"[名·他動3]","accent":"⓪","meaning":"妨碍，妨害","example":"妨害した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“妨碍，妨害”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n妨害した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“妨碍，妨害”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2714","seq":2714,"level":"N1","type":"主词条","word":"放棄","kana":"ほうき","pos":"[名·他動3]","accent":"①","meaning":"放弃","example":"初めて放棄する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“放弃”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて放棄する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“放弃”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2715","seq":2715,"level":"N1","type":"主词条","word":"方策","kana":"ほうさく","pos":"[名]","accent":"⓪","meaning":"方法，策略","example":"方策を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“方法，策略”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n方策を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“方法，策略”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2716","seq":2716,"level":"N1","type":"主词条","word":"奉仕","kana":"ほうし","pos":"[名·自動3]","accent":"①⓪","meaning":"服务，效劳；廉价销售","example":"奉仕した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“服务，效劳；廉价销售”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n奉仕した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“服务，效劳；廉价销售”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2717","seq":2717,"level":"N1","type":"主词条","word":"放射","kana":"ほうしゃ","pos":"[名·他動3]","accent":"⓪","meaning":"放射，辐射","example":"放射線を扱う施設では、作業時間と防護具の管理が厳しく定められている。","exampleZh":"在处理放射线的设施中，作业时间和防护用具的管理都有严格规定。","note":"例：\n放射線を扱う施設では、作業時間と防護具の管理が厳しく定められている。\n译：在处理放射线的设施中，作业时间和防护用具的管理都有严格规定。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2718","seq":2718,"level":"N1","type":"主词条","word":"報酬","kana":"ほうしゅう","pos":"[名]","accent":"⓪","meaning":"报酬","example":"報酬が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“报酬”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n報酬が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“报酬”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2719","seq":2719,"level":"N1","type":"主词条","word":"放出","kana":"ほうしゅつ","pos":"[名·自他動3]","accent":"⓪","meaning":"放出","example":"放出する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“放出”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n放出する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“放出”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2720","seq":2720,"level":"N1","type":"主词条","word":"報じる","kana":"ほうじる","pos":"[自他動2]","accent":"⓪③","meaning":"报答；通知，报告","example":"自分の道を報じるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“报答；通知，报告”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を報じるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“报答；通知，报告”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2721","seq":2721,"level":"N1","type":"主词条","word":"法人","kana":"ほうじん","pos":"[名]","accent":"⓪","meaning":"法人","example":"法人として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“法人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n法人として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“法人”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2722","seq":2722,"level":"N1","type":"主词条","word":"邦人","kana":"ほうじん","pos":"[名]","accent":"⓪","meaning":"（侨居国外的）日本人","example":"その邦人を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“日本人”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその邦人を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“日本人”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2723","seq":2723,"level":"N1","type":"主词条","word":"呆然","kana":"ぼうぜん","pos":"[副·ナ形]","accent":"⓪","meaning":"愕然，吃惊","example":"突然の倒産の知らせに、社員たちはしばらく呆然として言葉を失った。","exampleZh":"面对突然传来的倒闭消息，员工们一时愕然，失去了言语。","note":"例：\n突然の倒産の知らせに、社員たちはしばらく呆然として言葉を失った。\n译：面对突然传来的倒闭消息，员工们一时愕然，失去了言语。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2724","seq":2724,"level":"N1","type":"主词条","word":"放置","kana":"ほうち","pos":"[名·他動3]","accent":"①⓪","meaning":"搁置，置之不理","example":"彼は放置を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“搁置，置之不理”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は放置を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“搁置，置之不理”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2725","seq":2725,"level":"N1","type":"主词条","word":"膨張／膨脹","kana":"ぼうちょう","pos":"[名·自動3]","accent":"⓪","meaning":"膨胀；增加","example":"膨張／膨脹するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"物体膨胀时周围也会受到影响，因此负责人事先整理了联络渠道和替代方案。","note":"例：\n膨張／膨脹するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：物体膨胀时周围也会受到影响，因此负责人事先整理了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2726","seq":2726,"level":"N1","type":"主词条","word":"ぼうっと","kana":"ぼうっと","pos":"[副·自動3]","accent":"⓪","meaning":"模糊，精神恍惚","example":"寝不足で頭がぼうっとしていたため、彼は重要なメールを送る前に同僚へ確認を頼んだ。","exampleZh":"由于睡眠不足头脑恍惚，他在发送重要邮件前请同事帮忙确认。","note":"例：\n寝不足で頭がぼうっとしていたため、彼は重要なメールを送る前に同僚へ確認を頼んだ。\n译：由于睡眠不足头脑恍惚，他在发送重要邮件前请同事帮忙确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2727","seq":2727,"level":"N1","type":"主词条","word":"法廷","kana":"ほうてい","pos":"[名]","accent":"⓪","meaning":"法庭","example":"法廷をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“法庭”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n法廷をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“法庭”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2728","seq":2728,"level":"N1","type":"主词条","word":"冒頭","kana":"ぼうとう","pos":"[名]","accent":"⓪","meaning":"开头，开端","example":"冒頭の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“开头，开端”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n冒頭の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“开头，开端”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2729","seq":2729,"level":"N1","type":"主词条","word":"暴騰","kana":"ぼうとう","pos":"[名·自動3]","accent":"⓪","meaning":"暴涨","example":"予期せず暴騰した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“暴涨”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず暴騰した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“暴涨”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2730","seq":2730,"level":"N1","type":"主词条","word":"暴動","kana":"ぼうどう","pos":"[名]","accent":"⓪","meaning":"暴动","example":"暴動が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“暴动”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n暴動が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“暴动”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2731","seq":2731,"level":"N1","type":"主词条","word":"褒美","kana":"ほうび","pos":"[名·他動3]","accent":"⓪","meaning":"赞美，表扬","example":"小さな褒美を用意したことで、子どもたちは片づけを競争ではなく楽しい習慣として受け止めた。","exampleZh":"准备小小奖励后，孩子们把整理看作有趣习惯，而不是竞争。","note":"例：\n小さな褒美を用意したことで、子どもたちは片づけを競争ではなく楽しい習慣として受け止めた。\n译：准备小小奖励后，孩子们把整理看作有趣习惯，而不是竞争。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2732","seq":2732,"level":"N1","type":"主词条","word":"葬る","kana":"ほうむる","pos":"[他動1]","accent":"③","meaning":"埋葬；掩埋","example":"無理に葬ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“埋葬；掩埋”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に葬ると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“埋葬；掩埋”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2733","seq":2733,"level":"N1","type":"主词条","word":"放り込む","kana":"ほうりこむ","pos":"[他動1]","accent":"④","meaning":"扔进去","example":"難しい仕事を途中で放り込むのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。","exampleZh":"面对困难工作，他没有中途“扔进去”，而是分开思考原因，并判断何时寻求帮助。","note":"例：\n難しい仕事を途中で放り込むのではなく、彼は原因を分けて考え、助けを求めるタイミングを見極めた。\n译：面对困难工作，他没有中途“扔进去”，而是分开思考原因，并判断何时寻求帮助。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2734","seq":2734,"level":"N1","type":"主词条","word":"飽和","kana":"ほうわ","pos":"[名·自動3]","accent":"⓪","meaning":"饱和","example":"予期せず飽和した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“饱和”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず飽和した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“饱和”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2735","seq":2735,"level":"N1","type":"主词条","word":"ポーズ","kana":"ぽーず（pose）","pos":"[名]","accent":"①","meaning":"姿势，形态；造型，摆姿势","example":"ポーズの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“姿势，形态；造型，摆姿势”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nポーズの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“姿势，形态；造型，摆姿势”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2736","seq":2736,"level":"N1","type":"主词条","word":"ホームシック","kana":"ほーむしっく（homesick）","pos":"[名]","accent":"④","meaning":"想家，思念故乡","example":"そのホームシックを実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“想家，思念故乡”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nそのホームシックを実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“想家，思念故乡”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2737","seq":2737,"level":"N1","type":"主词条","word":"ホームレス","kana":"ほーむれす（homeless）","pos":"[名]","accent":"①","meaning":"无家可归的人","example":"そのホームレスは肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。","exampleZh":"那位“无家可归的人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","note":"例：\nそのホームレスは肩書きだけに頼らず、現場の声を聞きながら責任ある判断を下そうとした。\n译：那位“无家可归的人”没有只依赖头衔，而是一边倾听现场声音，一边试图作出负责任的判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2738","seq":2738,"level":"N1","type":"主词条","word":"捕獲","kana":"ほかく","pos":"[名·他動3]","accent":"⓪","meaning":"捕获","example":"初めて捕獲する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“捕获”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて捕獲する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“捕获”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2739","seq":2739,"level":"N1","type":"主词条","word":"補給","kana":"ほきゅう","pos":"[名·他動3]","accent":"⓪","meaning":"补给","example":"補給の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“补给”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n補給の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“补给”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2740","seq":2740,"level":"N1","type":"主词条","word":"補強","kana":"ほきょう","pos":"[名·他動3]","accent":"⓪","meaning":"加强，强化","example":"彼は補強を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“加强，强化”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は補強を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“加强，强化”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2741","seq":2741,"level":"N1","type":"主词条","word":"募金","kana":"ぼきん","pos":"[名·自動3]","accent":"⓪","meaning":"募捐","example":"募金した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“募捐”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n募金した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“募捐”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2742","seq":2742,"level":"N1","type":"主词条","word":"ボクシング","kana":"ぼくしんぐ（boxing）","pos":"[名]","accent":"①","meaning":"拳击","example":"ボクシングに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“拳击”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\nボクシングに触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“拳击”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2743","seq":2743,"level":"N1","type":"主词条","word":"ぼけ","kana":"ぼけ","pos":"[名]","accent":"②","meaning":"脑子糊涂，痴呆","example":"ぼけをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“脑子糊涂，痴呆”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nぼけをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“脑子糊涂，痴呆”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2744","seq":2744,"level":"N1","type":"主词条","word":"惚ける","kana":"ぼける","pos":"[自動2]","accent":"②","meaning":"（头脑）迟钝；（精神）恍惚","example":"祖父は時々惚けることがあるが、家族は責めずに予定を紙に書いて一緒に確認している。","exampleZh":"祖父偶尔会犯糊涂，但家人不责备他，而是把日程写在纸上一同确认。","note":"例：\n祖父は時々惚けることがあるが、家族は責めずに予定を紙に書いて一緒に確認している。\n译：祖父偶尔会犯糊涂，但家人不责备他，而是把日程写在纸上一同确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2745","seq":2745,"level":"N1","type":"主词条","word":"綻びる","kana":"ほころびる","pos":"[自動2]","accent":"④","meaning":"开绽；（花蕾）微开；微笑","example":"綻びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“开绽；微开”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n綻びるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“开绽；微开”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2746","seq":2746,"level":"N1","type":"主词条","word":"～干","kana":"～ぼし","pos":"[接尾]","accent":"","meaning":"……干","example":"梅干しを弁当に入れた祖母は、暑い日でも食欲が落ちないよう小さな工夫を欠かさない。","exampleZh":"祖母把梅干放进便当里，即使在炎热日子也不忘用小办法维持食欲。","note":"例：\n梅干しを弁当に入れた祖母は、暑い日でも食欲が落ちないよう小さな工夫を欠かさない。\n译：祖母把梅干放进便当里，即使在炎热日子也不忘用小办法维持食欲。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2747","seq":2747,"level":"N1","type":"主词条","word":"ポジション","kana":"ぽじしょん（position）","pos":"[名]","accent":"②","meaning":"地位，职位","example":"ポジションをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“地位，职位”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nポジションをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“地位，职位”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2748","seq":2748,"level":"N1","type":"主词条","word":"補充","kana":"ほじゅう","pos":"[名·他動3]","accent":"⓪","meaning":"补充","example":"彼は補充を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“补充”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は補充を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“补充”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2749","seq":2749,"level":"N1","type":"主词条","word":"補助","kana":"ほじょ","pos":"[名·他動3]","accent":"①","meaning":"补助，辅助","example":"市は家賃の一部を補助し、若い世代が地域に住み続けられるよう支援している。","exampleZh":"市政府补助一部分房租，支持年轻一代继续居住在当地。","note":"例：\n市は家賃の一部を補助し、若い世代が地域に住み続けられるよう支援している。\n译：市政府补助一部分房租，支持年轻一代继续居住在当地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2750","seq":2750,"level":"N1","type":"主词条","word":"補償","kana":"ほしょう","pos":"[名·他動3]","accent":"⓪","meaning":"补偿，赔偿","example":"補償する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“补偿，赔偿”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n補償する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“补偿，赔偿”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2751","seq":2751,"level":"N1","type":"主词条","word":"ホステス","kana":"ほすてす（hostess）","pos":"[名]","accent":"①","meaning":"女主人，女招待","example":"経験豊かなホステスの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“女主人，女招待”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなホステスの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“女主人，女招待”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2752","seq":2752,"level":"N1","type":"主词条","word":"ホスト","kana":"ほすと（host）","pos":"[名]","accent":"①","meaning":"主人，男主人，男招待","example":"経験豊かなホストの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“主人，男主人，男招待”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなホストの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“主人，男主人，男招待”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2753","seq":2753,"level":"N1","type":"主词条","word":"補足","kana":"ほそく","pos":"[名·他動3]","accent":"⓪","meaning":"补足，补充","example":"補足した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“补足，补充”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n補足した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“补足，补充”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2754","seq":2754,"level":"N1","type":"主词条","word":"ぼそぼそ","kana":"ぼそぼそ","pos":"[副·自動3]","accent":"①","meaning":"叽叽咕咕（小声说话）；干巴巴","example":"彼は自信がないのか、報告内容をぼそぼそと小さな声で読み上げた。","exampleZh":"他也许是没有自信，用很小的声音含含糊糊地读出了报告内容。","note":"例：\n彼は自信がないのか、報告内容をぼそぼそと小さな声で読み上げた。\n译：他也许是没有自信，用很小的声音含含糊糊地读出了报告内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2755","seq":2755,"level":"N1","type":"主词条","word":"ぼちぼち","kana":"ぼちぼち","pos":"[副]","accent":"①","meaning":"一点点，渐渐","example":"彼はぼちぼち結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。","exampleZh":"他没有急于作出“一点点，渐渐”的结论，而是在对照资料和现场声音后慎重决定方针。","note":"例：\n彼はぼちぼち結論を急がず、資料と現場の声を照らし合わせてから慎重に方針を決めた。\n译：他没有急于作出“一点点，渐渐”的结论，而是在对照资料和现场声音后慎重决定方针。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2756","seq":2756,"level":"N1","type":"主词条","word":"歩調","kana":"ほちょう","pos":"[名]","accent":"⓪","meaning":"步调，步伐","example":"歩調を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“步调，步伐”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n歩調を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“步调，步伐”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2757","seq":2757,"level":"N1","type":"主词条","word":"発作","kana":"ほっさ","pos":"[名·自動3]","accent":"⓪","meaning":"（疾病）发作","example":"発作する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“发作”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n発作する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“发作”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2758","seq":2758,"level":"N1","type":"主词条","word":"没収","kana":"ぼっしゅう","pos":"[名·他動3]","accent":"⓪","meaning":"没收，查抄","example":"没収する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“没收，查抄”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n没収する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“没收，查抄”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2759","seq":2759,"level":"N1","type":"主词条","word":"発足","kana":"ほっそく","pos":"[名·自動3]","accent":"⓪","meaning":"（组织等）成立，开始活动","example":"新しい委員会が発足し、地域の防災計画を一から見直す作業が始まった。","exampleZh":"新的委员会成立后，从零开始重新审视地区防灾计划的工作开始了。","note":"例：\n新しい委員会が発足し、地域の防災計画を一から見直す作業が始まった。\n译：新的委员会成立后，从零开始重新审视地区防灾计划的工作开始了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2760","seq":2760,"level":"N1","type":"主词条","word":"発端","kana":"ほったん","pos":"[名]","accent":"⓪","meaning":"发端，起因","example":"発端の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“发端，起因”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n発端の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“发端，起因”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2761","seq":2761,"level":"N1","type":"主词条","word":"ぼっと","kana":"ぼっと","pos":"[副·自動3]","accent":"③⓪","meaning":"模糊","example":"暗い倉庫の奥で火がぼっと燃え上がり、作業員はすぐに消火器を取りに走った。","exampleZh":"昏暗仓库深处火焰突然燃起，作业员立刻跑去拿灭火器。","note":"例：\n暗い倉庫の奥で火がぼっと燃え上がり、作業員はすぐに消火器を取りに走った。\n译：昏暗仓库深处火焰突然燃起，作业员立刻跑去拿灭火器。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2762","seq":2762,"level":"N1","type":"主词条","word":"没頭","kana":"ぼっとう","pos":"[名·自動3]","accent":"⓪","meaning":"埋头，专心致志","example":"没頭する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“埋头，专心致志”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n没頭する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“埋头，专心致志”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2763","seq":2763,"level":"N1","type":"主词条","word":"ぼつぼつ","kana":"ぼつぼつ","pos":"[副]","accent":"⓪","meaning":"星星点点散布的样子；慢慢，一点点","example":"雨がぼつぼつ降り始めたので、彼らは屋外の作業を切り上げ、道具を急いで片づけた。","exampleZh":"雨开始星星点点地下起来，于是他们停止户外作业，急忙收拾工具。","note":"例：\n雨がぼつぼつ降り始めたので、彼らは屋外の作業を切り上げ、道具を急いで片づけた。\n译：雨开始星星点点地下起来，于是他们停止户外作业，急忙收拾工具。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2764","seq":2764,"level":"N1","type":"主词条","word":"没落","kana":"ぼつらく","pos":"[名·自動3]","accent":"⓪","meaning":"没落","example":"予期せず没落した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“没落”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず没落した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“没落”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2765","seq":2765,"level":"N1","type":"主词条","word":"解ける","kana":"ほどける","pos":"[自動2]","accent":"③","meaning":"解开，松开；缓和","example":"靴ひもが解けると危ないので、子どもは出発前にもう一度しっかり結び直した。","exampleZh":"鞋带松开很危险，所以孩子出发前又重新认真系好。","note":"例：\n靴ひもが解けると危ないので、子どもは出発前にもう一度しっかり結び直した。\n译：鞋带松开很危险，所以孩子出发前又重新认真系好。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2766","seq":2766,"level":"N1","type":"主词条","word":"施す","kana":"ほどこす","pos":"[他動1]","accent":"③⓪","meaning":"施行；施舍；施加；采取某种手段","example":"相手に何かを施すなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“施行；施舍”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを施すなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“施行；施舍”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2767","seq":2767,"level":"N1","type":"主词条","word":"褒め称える","kana":"ほめたたえる","pos":"[他動2]","accent":"⑤④⓪","meaning":"极力称赞","example":"褒め称えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“极力称赞”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n褒め称えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“极力称赞”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2768","seq":2768,"level":"N1","type":"主词条","word":"ぼやく","kana":"ぼやく","pos":"[自他動1]","accent":"②","meaning":"嘟哝，发牢骚","example":"彼は仕事量の多さをぼやく一方で、締め切りに遅れないよう黙々と手を動かしていた。","exampleZh":"他一边抱怨工作量太多，一边为了不拖延截止日期默默动手做事。","note":"例：\n彼は仕事量の多さをぼやく一方で、締め切りに遅れないよう黙々と手を動かしていた。\n译：他一边抱怨工作量太多，一边为了不拖延截止日期默默动手做事。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2769","seq":2769,"level":"N1","type":"主词条","word":"ぼやける","kana":"ぼやける","pos":"[自動2]","accent":"③","meaning":"模糊","example":"ぼやける前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“模糊”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\nぼやける前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“模糊”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2770","seq":2770,"level":"N1","type":"主词条","word":"保養","kana":"ほよう","pos":"[名·自動3]","accent":"⓪","meaning":"疗养，休养；消遣","example":"保養してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“疗养，休养；消遣”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n保養してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“疗养，休养；消遣”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2771","seq":2771,"level":"N1","type":"主词条","word":"ホルモン","kana":"ほるもん","pos":"[名]","accent":"①","meaning":"荷尔蒙","example":"ホルモンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“荷尔蒙”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nホルモンが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“荷尔蒙”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2772","seq":2772,"level":"N1","type":"主词条","word":"滅びる","kana":"ほろびる","pos":"[自動2]","accent":"③⓪","meaning":"消亡，灭亡","example":"勢いが少しずつ滅びる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“消亡，灭亡”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ滅びる前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“消亡，灭亡”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2773","seq":2773,"level":"N1","type":"主词条","word":"滅ぶ","kana":"ほろぶ","pos":"[自動1]","accent":"②⓪","meaning":"灭亡","example":"伝統が滅ぶのを防ぐには、昔の形を守るだけでなく、若い世代が参加しやすい仕組みも必要だ。","exampleZh":"要防止传统消亡，不仅要守住旧形式，也需要建立年轻一代容易参与的机制。","note":"例：\n伝統が滅ぶのを防ぐには、昔の形を守るだけでなく、若い世代が参加しやすい仕組みも必要だ。\n译：要防止传统消亡，不仅要守住旧形式，也需要建立年轻一代容易参与的机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2774","seq":2774,"level":"N1","type":"主词条","word":"滅ぼす","kana":"ほろぼす","pos":"[他動1]","accent":"③⓪","meaning":"毁灭，使灭亡","example":"勢いが少しずつ滅ぼす前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“毁灭，使灭亡”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ滅ぼす前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“毁灭，使灭亡”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2775","seq":2775,"level":"N1","type":"主词条","word":"ぼろぼろ","kana":"ぼろぼろ","pos":"[副·ナ形]","accent":"①⓪","meaning":"扑扑簌簌；破烂","example":"長年使ってきた地図はぼろぼろだったが、旅の記憶が詰まっていて捨てられなかった。","exampleZh":"用了多年的地图已经破破烂烂，但里面满是旅行回忆，舍不得扔掉。","note":"例：\n長年使ってきた地図はぼろぼろだったが、旅の記憶が詰まっていて捨てられなかった。\n译：用了多年的地图已经破破烂烂，但里面满是旅行回忆，舍不得扔掉。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2776","seq":2776,"level":"N1","type":"主词条","word":"本気","kana":"ほんき","pos":"[名·ナ形]","accent":"⓪","meaning":"真的；认真","example":"一度本気だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“真的；认真”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度本気だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“真的；认真”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2777","seq":2777,"level":"N1","type":"主词条","word":"本筋","kana":"ほんすじ","pos":"[名]","accent":"⓪","meaning":"主要情节；主线，正题","example":"本筋を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“主要情节；主线，正题”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n本筋を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“主要情节；主线，正题”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2778","seq":2778,"level":"N1","type":"主词条","word":"本音","kana":"ほんね","pos":"[名]","accent":"⓪","meaning":"真心话","example":"本音を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“真心话”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n本音を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“真心话”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2779","seq":2779,"level":"N1","type":"主词条","word":"本能","kana":"ほんのう","pos":"[名]","accent":"①⓪","meaning":"本能","example":"本能を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。","exampleZh":"要磨炼“本能”，不能只依赖才能，还需要细致回顾失败场面的习惯。","note":"例：\n本能を磨くには才能だけに頼らず、失敗した場面を細かく振り返る習慣が必要だ。\n译：要磨炼“本能”，不能只依赖才能，还需要细致回顾失败场面的习惯。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2780","seq":2780,"level":"N1","type":"主词条","word":"本場","kana":"ほんば","pos":"[名]","accent":"⓪","meaning":"原产地；正宗，地道","example":"本場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。","exampleZh":"“原产地；正宗，地道”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","note":"例：\n本場の雰囲気は再開発で大きく変わったが、昔からの住民は小さな店のつながりを今も大切にしている。\n译：“原产地；正宗，地道”的氛围因再开发而大幅改变，但老居民至今仍珍惜小店之间的联系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2781","seq":2781,"level":"N1","type":"主词条","word":"ポンプ","kana":"ぽんぷ（pump）","pos":"[名]","accent":"①","meaning":"水泵","example":"ポンプの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“水泵”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\nポンプの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“水泵”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2782","seq":2782,"level":"N1","type":"主词条","word":"本名","kana":"ほんみょう","pos":"[名]","accent":"①","meaning":"本名，真名","example":"本名が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“本名，真名”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n本名が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“本名，真名”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2783","seq":2783,"level":"N1","type":"主词条","word":"マイ～","kana":"まい～（my～）","pos":"[接頭]","accent":"","meaning":"我的，自己的","example":"彼女はマイペースで勉強を続けているが、締め切りだけは必ず守るので周囲から信頼されている。","exampleZh":"她按照自己的节奏持续学习，但截止日期一定会遵守，因此受到周围人的信赖。","note":"例：\n彼女はマイペースで勉強を続けているが、締め切りだけは必ず守るので周囲から信頼されている。\n译：她按照自己的节奏持续学习，但截止日期一定会遵守，因此受到周围人的信赖。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2784","seq":2784,"level":"N1","type":"主词条","word":"舞い上がる","kana":"まいあがる","pos":"[自動1]","accent":"④","meaning":"飞舞；忘乎所以","example":"舞い上がる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“飞舞；忘乎所以”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n舞い上がる前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“飞舞；忘乎所以”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2785","seq":2785,"level":"N1","type":"主词条","word":"マイクロ～","kana":"まいくろ～（micro～）","pos":"[接頭]","accent":"","meaning":"微型~，百万分之一","example":"マイクロチップを使った製品が増えるにつれ、企業には安全性と個人情報保護への責任も求められる。","exampleZh":"随着使用微芯片的产品增多，企业也被要求承担安全性和个人信息保护责任。","note":"例：\nマイクロチップを使った製品が増えるにつれ、企業には安全性と個人情報保護への責任も求められる。\n译：随着使用微芯片的产品增多，企业也被要求承担安全性和个人信息保护责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2786","seq":2786,"level":"N1","type":"主词条","word":"埋蔵","kana":"まいぞう","pos":"[名·他動3]","accent":"⓪","meaning":"埋藏，蕴藏","example":"初めて埋蔵する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“埋藏，蕴藏”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて埋蔵する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“埋藏，蕴藏”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2787","seq":2787,"level":"N1","type":"主词条","word":"舞う","kana":"まう","pos":"[自動1]","accent":"⓪","meaning":"跳舞；飘舞","example":"舞う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“跳舞；飘舞”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n舞う前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“跳舞；飘舞”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2788","seq":2788,"level":"N1","type":"主词条","word":"真上","kana":"まうえ","pos":"[名]","accent":"③","meaning":"正上方","example":"真上の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“正上方”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n真上の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“正上方”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2789","seq":2789,"level":"N1","type":"主词条","word":"前売り","kana":"まえうり","pos":"[名·他動3]","accent":"⓪","meaning":"预售","example":"前売りする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“预售”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n前売りする前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“预售”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2790","seq":2790,"level":"N1","type":"主词条","word":"前置き","kana":"まえおき","pos":"[名·自動3]","accent":"⓪","meaning":"序言，开场白","example":"前置きした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“序言，开场白”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n前置きした後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“序言，开场白”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2791","seq":2791,"level":"N1","type":"主词条","word":"前書き","kana":"まえがき","pos":"[名]","accent":"⓪","meaning":"序言","example":"前書きを読むと、著者がなぜそのテーマを選んだのかが分かり、本文の理解も深まった。","exampleZh":"读了序言后，可以明白作者为什么选择这个主题，也能加深对正文的理解。","note":"例：\n前書きを読むと、著者がなぜそのテーマを選んだのかが分かり、本文の理解も深まった。\n译：读了序言后，可以明白作者为什么选择这个主题，也能加深对正文的理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2792","seq":2792,"level":"N1","type":"主词条","word":"前向き","kana":"まえむき","pos":"[名·ナ形]","accent":"⓪","meaning":"积极","example":"前向きな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“积极”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n前向きな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“积极”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2793","seq":2793,"level":"N1","type":"主词条","word":"前もって","kana":"まえもって","pos":"[副]","accent":"③⓪","meaning":"预先，事先","example":"会議の資料を前もって読んでおけば、当日は細かな確認ではなく本質的な議論に時間を使える。","exampleZh":"如果事先读过会议资料，当天就能把时间用于本质讨论，而不是细节确认。","note":"例：\n会議の資料を前もって読んでおけば、当日は細かな確認ではなく本質的な議論に時間を使える。\n译：如果事先读过会议资料，当天就能把时间用于本质讨论，而不是细节确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2794","seq":2794,"level":"N1","type":"主词条","word":"任す","kana":"まかす","pos":"[他動1]","accent":"②","meaning":"任凭；委托，托付","example":"無理に任すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“任凭；委托，托付”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に任すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“任凭；委托，托付”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2795","seq":2795,"level":"N1","type":"主词条","word":"賄う","kana":"まかなう","pos":"[他動1]","accent":"③","meaning":"供给（饭食）；维持","example":"賄うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“供给；维持”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n賄うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“供给；维持”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2796","seq":2796,"level":"N1","type":"主词条","word":"紛らわしい","kana":"まぎらわしい","pos":"[イ形]","accent":"⑤","meaning":"容易混淆","example":"紛らわしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“容易混淆”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n紛らわしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“容易混淆”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2797","seq":2797,"level":"N1","type":"主词条","word":"紛れる","kana":"まぎれる","pos":"[自動2]","accent":"③","meaning":"混淆；混进；排解郁闷或烦恼","example":"紛れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“混淆；混进”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n紛れるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“混淆；混进”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2798","seq":2798,"level":"N1","type":"主词条","word":"間際","kana":"まぎわ","pos":"[名]","accent":"①","meaning":"正要……的时候，快要……之前","example":"間際を有効に使うには、予定を詰め込みすぎず、考えるための余白を残しておくことが大切だ。","exampleZh":"要有效利用临近最后的时间，重要的是不要把计划排得太满，而要留下思考余地。","note":"例：\n間際を有効に使うには、予定を詰め込みすぎず、考えるための余白を残しておくことが大切だ。\n译：要有效利用临近最后的时间，重要的是不要把计划排得太满，而要留下思考余地。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2799","seq":2799,"level":"N1","type":"主词条","word":"真心","kana":"まごころ","pos":"[名]","accent":"②","meaning":"真心，诚意","example":"真心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“真心，诚意”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n真心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“真心，诚意”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2800","seq":2800,"level":"N1","type":"主词条","word":"まごつく","kana":"まごつく","pos":"[自動1]","accent":"⓪","meaning":"徘徊，彷徨","example":"まごつくような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“徘徊，彷徨”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\nまごつくような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“徘徊，彷徨”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2801","seq":2801,"level":"N1","type":"主词条","word":"正しく","kana":"まさしく","pos":"[副]","accent":"②","meaning":"的确，确实","example":"彼の指摘は正しく問題の核心を突いており、反対していた参加者も最後には納得した。","exampleZh":"他的指摘确实切中了问题核心，连原本反对的参加者最后也接受了。","note":"例：\n彼の指摘は正しく問題の核心を突いており、反対していた参加者も最後には納得した。\n译：他的指摘确实切中了问题核心，连原本反对的参加者最后也接受了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2802","seq":2802,"level":"N1","type":"主词条","word":"勝る","kana":"まさる","pos":"[自動1]","accent":"②⓪","meaning":"胜过","example":"勝るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“胜过”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n勝るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“胜过”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2803","seq":2803,"level":"N1","type":"主词条","word":"～増し","kana":"～まし","pos":"[接尾]","accent":"","meaning":"增加，增多","example":"この料理は辛さ増しで注文できるが、初めて来た客には店員が辛さの目安を丁寧に伝えている。","exampleZh":"这道料理可以加辣点单，但店员会向初次来的客人细致说明辣度标准。","note":"例：\nこの料理は辛さ増しで注文できるが、初めて来た客には店員が辛さの目安を丁寧に伝えている。\n译：这道料理可以加辣点单，但店员会向初次来的客人细致说明辣度标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2804","seq":2804,"level":"N1","type":"主词条","word":"交える","kana":"まじえる","pos":"[他動2]","accent":"③","meaning":"掺杂，夹杂；交叉；交换","example":"交えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“掺杂，夹杂；交叉”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n交えることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“掺杂，夹杂；交叉”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2805","seq":2805,"level":"N1","type":"主词条","word":"真下","kana":"ました","pos":"[名]","accent":"③","meaning":"正下方","example":"真下に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“正下方”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n真下に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“正下方”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2806","seq":2806,"level":"N1","type":"主词条","word":"まして","kana":"まして","pos":"[副]","accent":"①","meaning":"何况，况且","example":"経験者でも難しい作業なのだから、まして初めて担当する人には十分な案内と練習が必要だ。","exampleZh":"连有经验的人都觉得困难，更何况第一次负责的人，更需要充分说明和练习。","note":"例：\n経験者でも難しい作業なのだから、まして初めて担当する人には十分な案内と練習が必要だ。\n译：连有经验的人都觉得困难，更何况第一次负责的人，更需要充分说明和练习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2807","seq":2807,"level":"N1","type":"主词条","word":"交わる","kana":"まじわる","pos":"[自動1]","accent":"③","meaning":"（数学）相交；交往；交叉；混杂，掺杂","example":"交わるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“相交；交往”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n交わるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“相交；交往”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2808","seq":2808,"level":"N1","type":"主词条","word":"跨る","kana":"またがる","pos":"[自動1]","accent":"③","meaning":"跨，乘，骑；横跨，跨越","example":"跨るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“跨，乘，骑；横跨，跨越”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n跨るとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“跨，乘，骑；横跨，跨越”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2809","seq":2809,"level":"N1","type":"主词条","word":"瞬く","kana":"またたく","pos":"[自動1]","accent":"③","meaning":"闪烁；眨眼","example":"瞬く場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“闪烁；眨眼”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n瞬く場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“闪烁；眨眼”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2810","seq":2810,"level":"N1","type":"主词条","word":"マタニティー","kana":"またにてぃー（maternity）","pos":"[名]","accent":"②","meaning":"孕妇的","example":"マタニティーが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“孕妇的”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\nマタニティーが思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“孕妇的”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2811","seq":2811,"level":"N1","type":"主词条","word":"待ち遠しい","kana":"まちどおしい","pos":"[イ形]","accent":"⑤","meaning":"急切等待，盼望已久","example":"待ち遠しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“急切等待，盼望已久”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n待ち遠しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“急切等待，盼望已久”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2812","seq":2812,"level":"N1","type":"主词条","word":"まちまち","kana":"まちまち","pos":"[名·ナ形]","accent":"②⓪","meaning":"各式各样，形形色色","example":"参加者の経験はまちまちだったため、講師は同じ内容を複数の例で示しながら進めた。","exampleZh":"参加者经验各不相同，因此讲师用多个例子展示同一内容来推进课程。","note":"例：\n参加者の経験はまちまちだったため、講師は同じ内容を複数の例で示しながら進めた。\n译：参加者经验各不相同，因此讲师用多个例子展示同一内容来推进课程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2813","seq":2813,"level":"N1","type":"主词条","word":"～末","kana":"～まつ","pos":"[接尾]","accent":"","meaning":"……末","example":"月末に報告書を提出するため、担当者は週の前半から資料の抜け漏れを確認していた。","exampleZh":"为了在月末提交报告书，负责人从一周前半就开始确认资料是否有遗漏。","note":"例：\n月末に報告書を提出するため、担当者は週の前半から資料の抜け漏れを確認していた。\n译：为了在月末提交报告书，负责人从一周前半就开始确认资料是否有遗漏。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2814","seq":2814,"level":"N1","type":"主词条","word":"末期","kana":"まっき","pos":"[名]","accent":"①","meaning":"末期，晚期","example":"末期が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。","exampleZh":"越接近“末期，晚期”，相关人员越细致地共享彼此作业进度，试图防止返工。","note":"例：\n末期が近づくほど、関係者は互いの作業状況を細かく共有し、手戻りを防ごうとした。\n译：越接近“末期，晚期”，相关人员越细致地共享彼此作业进度，试图防止返工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2815","seq":2815,"level":"N1","type":"主词条","word":"全うする","kana":"まっとうする","pos":"[他動3]","accent":"⓪","meaning":"完成；保全","example":"全うする場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“完成；保全”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n全うする場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“完成；保全”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2816","seq":2816,"level":"N1","type":"主词条","word":"真っ二つ","kana":"まっぷたつ","pos":"[名]","accent":"③④","meaning":"刚好分成两半","example":"真っ二つが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“刚好分成两半”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n真っ二つが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“刚好分成两半”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2817","seq":2817,"level":"N1","type":"主词条","word":"的","kana":"まと","pos":"[名]","accent":"⓪","meaning":"靶子；目标，目的","example":"立派な的でも、現場の制約を無視すれば実行段階で必ず行き詰まる。","exampleZh":"即使是出色的“靶子；目标，目的”，若无视现场限制，在执行阶段也一定会受阻。","note":"例：\n立派な的でも、現場の制約を無視すれば実行段階で必ず行き詰まる。\n译：即使是出色的“靶子；目标，目的”，若无视现场限制，在执行阶段也一定会受阻。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2818","seq":2818,"level":"N1","type":"主词条","word":"まとまり","kana":"まとまり","pos":"[名]","accent":"⓪","meaning":"一贯性；解决","example":"まとまりの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“一贯性；解决”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nまとまりの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“一贯性；解决”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2819","seq":2819,"level":"N1","type":"主词条","word":"まとも","kana":"まとも","pos":"[名·ナ形]","accent":"⓪","meaning":"正经，认真；正面","example":"まともな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“正经，认真；正面”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nまともな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“正经，认真；正面”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2820","seq":2820,"level":"N1","type":"主词条","word":"眼差し","kana":"まなざし","pos":"[名]","accent":"⓪④","meaning":"目光，眼神","example":"眼差しの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“目光，眼神”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n眼差しの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“目光，眼神”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2821","seq":2821,"level":"N1","type":"主词条","word":"マニア","kana":"まにあ（mania）","pos":"[名]","accent":"①","meaning":"……迷","example":"マニアをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“迷”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nマニアをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“迷”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2822","seq":2822,"level":"N1","type":"主词条","word":"免れる","kana":"まぬがれる","pos":"[他動2]","accent":"④","meaning":"避免；摆脱","example":"免れる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“避免；摆脱”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n免れる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“避免；摆脱”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2823","seq":2823,"level":"N1","type":"主词条","word":"瞬き","kana":"まばたき","pos":"[名·自動3]","accent":"②","meaning":"眨眼，闪烁","example":"瞬きするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“眨眼，闪烁”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n瞬きするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“眨眼，闪烁”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2824","seq":2824,"level":"N1","type":"主词条","word":"まばら","kana":"まばら","pos":"[ナ形]","accent":"⓪","meaning":"稀疏，零星","example":"まばらな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“稀疏，零星”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nまばらな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“稀疏，零星”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2825","seq":2825,"level":"N1","type":"主词条","word":"麻痺","kana":"まひ","pos":"[名·自動3]","accent":"①","meaning":"麻痹，瘫痪","example":"麻痺してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“麻痹，瘫痪”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n麻痺してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“麻痹，瘫痪”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2826","seq":2826,"level":"N1","type":"主词条","word":"眉毛","kana":"まゆげ","pos":"[名]","accent":"①","meaning":"眉毛","example":"眉毛が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“眉毛”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n眉毛が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“眉毛”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2827","seq":2827,"level":"N1","type":"主词条","word":"まるきり","kana":"まるきり","pos":"[副]","accent":"⓪","meaning":"完全，全然，一概（接否定）","example":"彼はその分野の知識がまるきりないわけではなく、基礎を学べば十分に対応できる。","exampleZh":"他并非完全没有那个领域的知识，只要学习基础就足以应对。","note":"例：\n彼はその分野の知識がまるきりないわけではなく、基礎を学べば十分に対応できる。\n译：他并非完全没有那个领域的知识，只要学习基础就足以应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2828","seq":2828,"level":"N1","type":"主词条","word":"マルチ～","kana":"まるち～（multi～）","pos":"[接頭]","accent":"①","meaning":"多……（复数意味，如多媒体，多模态，多才艺）","example":"彼はマルチタスクをこなすのが得意だが、重要な判断をするときは一つの作業に集中するようにしている。","exampleZh":"他擅长多任务处理，但进行重要判断时会尽量集中在一项工作上。","note":"例：\n彼はマルチタスクをこなすのが得意だが、重要な判断をするときは一つの作業に集中するようにしている。\n译：他擅长多任务处理，但进行重要判断时会尽量集中在一项工作上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2829","seq":2829,"level":"N1","type":"主词条","word":"丸々","kana":"まるまる","pos":"[副]","accent":"⓪","meaning":"胖墩墩；全部，整个","example":"丸々一日かけて資料を整理したおかげで、複雑だった経緯が誰にでも追える形になった。","exampleZh":"多亏花了整整一天整理资料，原本复杂的经过变成了谁都能追踪的形式。","note":"例：\n丸々一日かけて資料を整理したおかげで、複雑だった経緯が誰にでも追える形になった。\n译：多亏花了整整一天整理资料，原本复杂的经过变成了谁都能追踪的形式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2830","seq":2830,"level":"N1","type":"主词条","word":"丸める","kana":"まるめる","pos":"[他動2]","accent":"⓪","meaning":"卷起来；笼络；剃头","example":"相手に何かを丸めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“卷起来；笼络”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを丸めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“卷起来；笼络”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2831","seq":2831,"level":"N1","type":"主词条","word":"回りくどい","kana":"まわりくどい","pos":"[イ形]","accent":"⑤","meaning":"转弯抹角","example":"回りくどいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“转弯抹角”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n回りくどいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“转弯抹角”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2832","seq":2832,"level":"N1","type":"主词条","word":"満喫","kana":"まんきつ","pos":"[名·他動3]","accent":"⓪","meaning":"吃饱喝足；充分享受","example":"チームは満喫する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“吃饱喝足；充分享受”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは満喫する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“吃饱喝足；充分享受”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2833","seq":2833,"level":"N1","type":"主词条","word":"満月","kana":"まんげつ","pos":"[名]","accent":"①","meaning":"满月，圆月","example":"満月が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“满月，圆月”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n満月が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“满月，圆月”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2834","seq":2834,"level":"N1","type":"主词条","word":"漫才","kana":"まんざい","pos":"[名]","accent":"⓪","meaning":"（日本）相声","example":"漫才をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“相声”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n漫才をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“相声”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2835","seq":2835,"level":"N1","type":"主词条","word":"まんざら","kana":"まんざら","pos":"[副]","accent":"⓪","meaning":"（后接否定）并非完全，未必","example":"厳しい評価を受けた彼だったが、表情を見る限りその結果にまんざら不満でもなさそうだった。","exampleZh":"受到严厉评价的他，从表情看似乎也并非完全不满那个结果。","note":"例：\n厳しい評価を受けた彼だったが、表情を見る限りその結果にまんざら不満でもなさそうだった。\n译：受到严厉评价的他，从表情看似乎也并非完全不满那个结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2836","seq":2836,"level":"N1","type":"主词条","word":"満場","kana":"まんじょう","pos":"[名]","accent":"⓪","meaning":"全场","example":"その満場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“全场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその満場を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“全场”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2837","seq":2837,"level":"N1","type":"主词条","word":"マンネリ","kana":"まんねり","pos":"[名]","accent":"⓪","meaning":"因循守旧，一成不变","example":"マンネリをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“因循守旧，一成不变”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\nマンネリをめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“因循守旧，一成不变”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2838","seq":2838,"level":"N1","type":"主词条","word":"万引き","kana":"まんびき","pos":"[名·他動3]","accent":"⓪④","meaning":"（在商店等场所）偷窃","example":"万引きする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“偷窃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n万引きする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“偷窃”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2839","seq":2839,"level":"N1","type":"主词条","word":"真ん丸い","kana":"まんまるい","pos":"[イ形]","accent":"⓪④","meaning":"溜圆，形容特别圆的样子","example":"真ん丸い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“溜圆，形容特别圆的样子”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n真ん丸い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“溜圆，形容特别圆的样子”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2840","seq":2840,"level":"N1","type":"主词条","word":"～身","kana":"～み","pos":"[接尾]","accent":"","meaning":"部分，人，处境，立场","example":"彼は親身になって相談に乗ってくれたため、相手は初めて自分の不安を率直に話すことができた。","exampleZh":"他亲身贴近对方并提供咨询，因此对方第一次坦率说出了自己的不安。","note":"例：\n彼は親身になって相談に乗ってくれたため、相手は初めて自分の不安を率直に話すことができた。\n译：他亲身贴近对方并提供咨询，因此对方第一次坦率说出了自己的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2841","seq":2841,"level":"N1","type":"主词条","word":"見当たる","kana":"みあたる","pos":"[自動1]","accent":"⓪③","meaning":"看到，找到","example":"探していた資料は机の上には見当たらず、彼は昨日使った会議室まで戻って確認した。","exampleZh":"要找的资料在桌上没有看到，他又回到昨天用过的会议室确认。","note":"例：\n探していた資料は机の上には見当たらず、彼は昨日使った会議室まで戻って確認した。\n译：要找的资料在桌上没有看到，他又回到昨天用过的会议室确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2842","seq":2842,"level":"N1","type":"主词条","word":"見合わせる","kana":"みあわせる","pos":"[他動2]","accent":"④⓪","meaning":"互相看；推迟，暂缓","example":"締め切りを見合わせるには、都合のよい理由だけでなく、関係者が納得できる根拠を示さなければならない。","exampleZh":"若要推迟截止日期，不能只提出方便自己的理由，还必须给出相关人员能接受的依据。","note":"例：\n締め切りを見合わせるには、都合のよい理由だけでなく、関係者が納得できる根拠を示さなければならない。\n译：若要推迟截止日期，不能只提出方便自己的理由，还必须给出相关人员能接受的依据。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2843","seq":2843,"level":"N1","type":"主词条","word":"見入る","kana":"みいる","pos":"[自他動1]","accent":"②⓪","meaning":"注视，看得入神","example":"無理に見入るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“注视，看得入神”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に見入るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“注视，看得入神”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2844","seq":2844,"level":"N1","type":"主词条","word":"見失う","kana":"みうしなう","pos":"[他動1]","accent":"⓪④","meaning":"迷失；看丢","example":"見失うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“迷失；看丢”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n見失うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“迷失；看丢”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2845","seq":2845,"level":"N1","type":"主词条","word":"見落とす","kana":"みおとす","pos":"[他動1]","accent":"⓪③","meaning":"看漏，忽略过去","example":"見落とす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“看漏，忽略过去”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n見落とす場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“看漏，忽略过去”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2846","seq":2846,"level":"N1","type":"主词条","word":"見劣り","kana":"みおとり","pos":"[名·自動3]","accent":"⓪","meaning":"逊色","example":"見劣りする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“逊色”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n見劣りする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“逊色”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2847","seq":2847,"level":"N1","type":"主词条","word":"未開","kana":"みかい","pos":"[名]","accent":"⓪","meaning":"未开垦；未知","example":"未開をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“未开垦；未知”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n未開をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“未开垦；未知”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2848","seq":2848,"level":"N1","type":"主词条","word":"幹","kana":"みき","pos":"[名]","accent":"①⓪","meaning":"树干；主要部分","example":"幹を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“树干；主要部分”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n幹を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“树干；主要部分”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2849","seq":2849,"level":"N1","type":"主词条","word":"見極める","kana":"みきわめる","pos":"[他動2]","accent":"④⓪","meaning":"确认；看清；辨别","example":"相手に何かを見極めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“确认；看清”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを見極めるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“确认；看清”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2850","seq":2850,"level":"N1","type":"主词条","word":"見苦しい","kana":"みぐるしい","pos":"[イ形]","accent":"④","meaning":"难看，寒碜，丢脸","example":"会議で責任を押しつけ合う姿は見苦しく、参加者の信頼を大きく損なった。","exampleZh":"在会议上互相推卸责任的样子很难看，极大损害了参加者的信任。","note":"例：\n会議で責任を押しつけ合う姿は見苦しく、参加者の信頼を大きく損なった。\n译：在会议上互相推卸责任的样子很难看，极大损害了参加者的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2851","seq":2851,"level":"N1","type":"主词条","word":"ミクロ","kana":"みくろ（micro）","pos":"[名]","accent":"①","meaning":"微小；微观","example":"ミクロの視点で細部を観察すると、全体の問題だと思っていた現象にも別の原因が見えてくる。","exampleZh":"从微观视角观察细节后，原以为是整体问题的现象也显现出其他原因。","note":"例：\nミクロの視点で細部を観察すると、全体の問題だと思っていた現象にも別の原因が見えてくる。\n译：从微观视角观察细节后，原以为是整体问题的现象也显现出其他原因。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2852","seq":2852,"level":"N1","type":"主词条","word":"身ごなし","kana":"みごなし","pos":"[名]","accent":"⓪②","meaning":"举止","example":"身ごなしが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“举止”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n身ごなしが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“举止”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2853","seq":2853,"level":"N1","type":"主词条","word":"見込み","kana":"みこみ","pos":"[名]","accent":"⓪","meaning":"希望；可能性；预料","example":"見込みが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“希望；可能性”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n見込みが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“希望；可能性”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2854","seq":2854,"level":"N1","type":"主词条","word":"見込む","kana":"みこむ","pos":"[他動1]","accent":"⓪②","meaning":"预料，估计；认为有希望","example":"見込むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“预料，估计；认为有希望”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n見込むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“预料，估计；认为有希望”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2855","seq":2855,"level":"N1","type":"主词条","word":"未熟","kana":"みじゅく","pos":"[名·ナ形]","accent":"⓪①","meaning":"未熟，不成熟","example":"未熟な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“未熟，不成熟”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n未熟な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“未熟，不成熟”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2856","seq":2856,"level":"N1","type":"主词条","word":"微塵も","kana":"みじんも","pos":"[副]","accent":"⓪","meaning":"一点也（不），丝毫（没有）","example":"彼は自分だけが評価されようという考えを微塵も見せず、成果はチーム全体のものだと強調した。","exampleZh":"他丝毫没有表现出想让自己独占评价的想法，而是强调成果属于整个团队。","note":"例：\n彼は自分だけが評価されようという考えを微塵も見せず、成果はチーム全体のものだと強調した。\n译：他丝毫没有表现出想让自己独占评价的想法，而是强调成果属于整个团队。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2857","seq":2857,"level":"N1","type":"主词条","word":"ミス","kana":"みす（miss）","pos":"[名·自動3]","accent":"①","meaning":"失误，错误","example":"ミスする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“失误，错误”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\nミスする可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“失误，错误”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2858","seq":2858,"level":"N1","type":"主词条","word":"水気","kana":"みずけ","pos":"[名]","accent":"⓪","meaning":"水分","example":"研究者は水気の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。","exampleZh":"研究者没有只看一次“水分”的状态就下判断，而是连同季节和周边环境的关系一起调查。","note":"例：\n研究者は水気の状態を一度見ただけで決めつけず、季節や周辺環境との関係まで調べた。\n译：研究者没有只看一次“水分”的状态就下判断，而是连同季节和周边环境的关系一起调查。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2859","seq":2859,"level":"N1","type":"主词条","word":"水溜り","kana":"みずたまり","pos":"[名]","accent":"⓪","meaning":"水洼，积水处","example":"水溜りの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“水洼，积水处”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n水溜りの変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“水洼，积水处”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2860","seq":2860,"level":"N1","type":"主词条","word":"ミスプリント","kana":"みすぷりんと（misprint）","pos":"[名]","accent":"④","meaning":"印刷错误","example":"試験問題にミスプリントが見つかったため、監督者は受験者全員に訂正内容をはっきり伝えた。","exampleZh":"考试题中发现印刷错误，监考人员明确向全体考生传达了订正内容。","note":"例：\n試験問題にミスプリントが見つかったため、監督者は受験者全員に訂正内容をはっきり伝えた。\n译：考试题中发现印刷错误，监考人员明确向全体考生传达了订正内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2861","seq":2861,"level":"N1","type":"主词条","word":"みすぼらしい","kana":"みすぼらしい","pos":"[イ形]","accent":"⑤⓪","meaning":"寒碜，衣衫褴褛","example":"古い上着はみすぼらしい見た目だったが、祖父が大切に使ってきた思い出が詰まっていた。","exampleZh":"那件旧上衣外观看起来很寒酸，却装满了祖父珍惜使用的回忆。","note":"例：\n古い上着はみすぼらしい見た目だったが、祖父が大切に使ってきた思い出が詰まっていた。\n译：那件旧上衣外观看起来很寒酸，却装满了祖父珍惜使用的回忆。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2862","seq":2862,"level":"N1","type":"主词条","word":"水増し","kana":"みずまし","pos":"[名·自他動3]","accent":"⓪","meaning":"掺水，加水；虚报","example":"水増しする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“掺水，加水；虚报”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n水増しする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“掺水，加水；虚报”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2863","seq":2863,"level":"N1","type":"主词条","word":"みずみずしい","kana":"みずみずしい","pos":"[イ形]","accent":"⑤","meaning":"水灵灵，新鲜，鲜嫩","example":"みずみずしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“水灵灵，新鲜，鲜嫩”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nみずみずしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“水灵灵，新鲜，鲜嫩”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2864","seq":2864,"level":"N1","type":"主词条","word":"見せびらかす","kana":"みせびらかす","pos":"[他動1]","accent":"⑤","meaning":"卖弄，炫耀","example":"知識を見せびらかすだけでは相手の信頼は得られず、分かりやすく役立つ形で伝える力が求められる。","exampleZh":"仅仅炫耀知识无法获得对方信任，需要以易懂且有用的方式传达。","note":"例：\n知識を見せびらかすだけでは相手の信頼は得られず、分かりやすく役立つ形で伝える力が求められる。\n译：仅仅炫耀知识无法获得对方信任，需要以易懂且有用的方式传达。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2865","seq":2865,"level":"N1","type":"主词条","word":"見世物","kana":"みせもの","pos":"[名]","accent":"③④","meaning":"小节目；出洋相","example":"彼女は見世物をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“小节目；出洋相”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は見世物をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“小节目；出洋相”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2866","seq":2866,"level":"N1","type":"主词条","word":"溝","kana":"みぞ","pos":"[名]","accent":"⓪","meaning":"水沟，水渠；隔阂","example":"世代間の溝を埋めるには、どちらかが一方的に我慢するのではなく、互いの不安を言葉にする必要がある。","exampleZh":"要填平世代之间的隔阂，不能只让某一方单方面忍耐，而需要把彼此的不安说出来。","note":"例：\n世代間の溝を埋めるには、どちらかが一方的に我慢するのではなく、互いの不安を言葉にする必要がある。\n译：要填平世代之间的隔阂，不能只让某一方单方面忍耐，而需要把彼此的不安说出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2867","seq":2867,"level":"N1","type":"主词条","word":"乱す","kana":"みだす","pos":"[他動1]","accent":"②","meaning":"弄乱；扰乱；蛊惑","example":"乱す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“弄乱；扰乱”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n乱す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“弄乱；扰乱”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2868","seq":2868,"level":"N1","type":"主词条","word":"満たない","kana":"みたない","pos":"[連語]","accent":"②","meaning":"不满，不足","example":"参加者は十人に満たないものの、議論は深く、次回につながる具体案も出された。","exampleZh":"虽然参加者不足十人，但讨论很深入，也提出了能连接到下次的具体方案。","note":"例：\n参加者は十人に満たないものの、議論は深く、次回につながる具体案も出された。\n译：虽然参加者不足十人，但讨论很深入，也提出了能连接到下次的具体方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2869","seq":2869,"level":"N1","type":"主词条","word":"身近","kana":"みぢか","pos":"[名·ナ形]","accent":"⓪","meaning":"身边，近旁；切身","example":"周囲から身近だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“身边，近旁；切身”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から身近だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“身边，近旁；切身”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2870","seq":2870,"level":"N1","type":"主词条","word":"道連れ","kana":"みちづれ","pos":"[名]","accent":"⓪","meaning":"旅伴","example":"道連れをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“旅伴”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n道連れをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“旅伴”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2871","seq":2871,"level":"N1","type":"主词条","word":"道程","kana":"みちのり","pos":"[名]","accent":"⓪","meaning":"路程","example":"道程をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“路程”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n道程をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“路程”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2872","seq":2872,"level":"N1","type":"主词条","word":"導く","kana":"みちびく","pos":"[他動1]","accent":"③","meaning":"引路，指导；导致，造成；推导","example":"無理に導くと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“引路，指导；导致，造成”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に導くと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“引路，指导；导致，造成”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2873","seq":2873,"level":"N1","type":"主词条","word":"三日坊主","kana":"みっかぼうず","pos":"[名]","accent":"④","meaning":"三天打鱼两天晒网的人","example":"彼は三日坊主にならないよう、毎朝の勉強時間を十分だけに絞り、達成した日をカレンダーに記録した。","exampleZh":"为了不三天打鱼两天晒网，他把每天早上的学习时间限定为十分钟，并在日历上记录完成的日子。","note":"例：\n彼は三日坊主にならないよう、毎朝の勉強時間を十分だけに絞り、達成した日をカレンダーに記録した。\n译：为了不三天打鱼两天晒网，他把每天早上的学习时间限定为十分钟，并在日历上记录完成的日子。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2874","seq":2874,"level":"N1","type":"主词条","word":"密集","kana":"みっしゅう","pos":"[名·自動3]","accent":"⓪","meaning":"密集","example":"予期せず密集した場合に備え、チームは連絡先と対応手順を共有していた。","exampleZh":"为了应对意外出现与“密集”有关的情况，团队提前共享了联系方式和处理流程。","note":"例：\n予期せず密集した場合に備え、チームは連絡先と対応手順を共有していた。\n译：为了应对意外出现与“密集”有关的情况，团队提前共享了联系方式和处理流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2875","seq":2875,"level":"N1","type":"主词条","word":"密接","kana":"みっせつ","pos":"[名·ナ形·自動3]","accent":"⓪","meaning":"密切；紧贴，紧连","example":"地域医療と交通手段は密接に関わっており、病院を増やすだけでは通院の不安は解消しない。","exampleZh":"地区医疗和交通方式密切相关，只增加医院并不能消除就医的不安。","note":"例：\n地域医療と交通手段は密接に関わっており、病院を増やすだけでは通院の不安は解消しない。\n译：地区医疗和交通方式密切相关，只增加医院并不能消除就医的不安。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2876","seq":2876,"level":"N1","type":"主词条","word":"密着","kana":"みっちゃく","pos":"[名·自動3]","accent":"⓪","meaning":"紧贴","example":"密着した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“紧贴”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n密着した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“紧贴”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2877","seq":2877,"level":"N1","type":"主词条","word":"密度","kana":"みつど","pos":"[名]","accent":"①","meaning":"密度","example":"密度に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“密度”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n密度に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“密度”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2878","seq":2878,"level":"N1","type":"主词条","word":"見積もる","kana":"みつもる","pos":"[他動1]","accent":"⓪③","meaning":"粗略估算；估价","example":"見積もることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“粗略估算；估价”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n見積もることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“粗略估算；估价”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2879","seq":2879,"level":"N1","type":"主词条","word":"未定","kana":"みてい","pos":"[名·ナ形]","accent":"⓪","meaning":"未定","example":"周囲から未定だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“未定”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から未定だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“未定”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2880","seq":2880,"level":"N1","type":"主词条","word":"見通し","kana":"みとおし","pos":"[名]","accent":"⓪","meaning":"眺望；预期","example":"見通しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“眺望；预期”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n見通しが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“眺望；预期”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2881","seq":2881,"level":"N1","type":"主词条","word":"見所","kana":"みどころ","pos":"[名]","accent":"⓪②","meaning":"值得一看的地方","example":"その見所を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“值得一看的地方”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその見所を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“值得一看的地方”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2882","seq":2882,"level":"N1","type":"主词条","word":"漲る","kana":"みなぎる","pos":"[自動1]","accent":"③","meaning":"溢出；充满","example":"漲るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“溢出；充满”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n漲るような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“溢出；充满”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2883","seq":2883,"level":"N1","type":"主词条","word":"見なす","kana":"みなす","pos":"[他動1]","accent":"⓪②","meaning":"看作","example":"無理に見なすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“看作”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に見なすよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“看作”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2884","seq":2884,"level":"N1","type":"主词条","word":"源","kana":"みなもと","pos":"[名]","accent":"⓪","meaning":"水源；起源","example":"源を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“水源；起源”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n源を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“水源；起源”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2885","seq":2885,"level":"N1","type":"主词条","word":"見習う","kana":"みならう","pos":"[他動1]","accent":"⓪③","meaning":"学习，模仿","example":"相手に何かを見習うなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“学习，模仿”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを見習うなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“学习，模仿”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2886","seq":2886,"level":"N1","type":"主词条","word":"身なり","kana":"みなり","pos":"[名]","accent":"①","meaning":"装束，打扮","example":"式典に着ていく身なりを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“装束，打扮”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていく身なりを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“装束，打扮”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2887","seq":2887,"level":"N1","type":"主词条","word":"身の上","kana":"みのうえ","pos":"[名]","accent":"⓪④","meaning":"境遇，身世；命运","example":"身の上を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“境遇，身世；命运”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n身の上を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“境遇，身世；命运”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2888","seq":2888,"level":"N1","type":"主词条","word":"見逃す","kana":"みのがす","pos":"[他動1]","accent":"⓪③","meaning":"看漏，错过；宽恕","example":"無理に見逃すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“看漏，错过；宽恕”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に見逃すよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“看漏，错过；宽恕”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2889","seq":2889,"level":"N1","type":"主词条","word":"身の回り","kana":"みのまわり","pos":"[名]","accent":"⓪","meaning":"身边；日常生活","example":"身の回りを整えるだけでも気持ちに余裕が生まれ、忙しい日ほど小さな片づけの効果を実感する。","exampleZh":"只是整理身边环境也会让心情更有余裕，越忙的日子越能感受到小整理的效果。","note":"例：\n身の回りを整えるだけでも気持ちに余裕が生まれ、忙しい日ほど小さな片づけの効果を実感する。\n译：只是整理身边环境也会让心情更有余裕，越忙的日子越能感受到小整理的效果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2890","seq":2890,"level":"N1","type":"主词条","word":"見栄え","kana":"みばえ","pos":"[名]","accent":"⓪③","meaning":"好看，美观","example":"見栄えを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“好看，美观”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n見栄えを前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“好看，美观”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2891","seq":2891,"level":"N1","type":"主词条","word":"見計らう","kana":"みはからう","pos":"[他動1]","accent":"⓪④","meaning":"斟酌，瞧着办；适当估计","example":"見計らう前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“斟酌，瞧着办；适当估计”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n見計らう前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“斟酌，瞧着办；适当估计”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2892","seq":2892,"level":"N1","type":"主词条","word":"見晴らし","kana":"みはらし","pos":"[名]","accent":"⓪","meaning":"眺望","example":"見晴らしをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“眺望”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n見晴らしをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“眺望”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2893","seq":2893,"level":"N1","type":"主词条","word":"見張る","kana":"みはる","pos":"[他動1]","accent":"⓪","meaning":"瞠目而视；监视，看守，警戒","example":"無理に見張るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“瞠目而视；监视，看守，警戒”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に見張るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“瞠目而视；监视，看守，警戒”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2894","seq":2894,"level":"N1","type":"主词条","word":"身振り","kana":"みぶり","pos":"[名]","accent":"①","meaning":"姿态，动作","example":"身振りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“姿态，动作”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n身振りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“姿态，动作”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2895","seq":2895,"level":"N1","type":"主词条","word":"身元","kana":"みもと","pos":"[名]","accent":"⓪","meaning":"出身，来历；身份","example":"身元をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“出身，来历；身份”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n身元をどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“出身，来历；身份”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2896","seq":2896,"level":"N1","type":"主词条","word":"見破る","kana":"みやぶる","pos":"[他動1]","accent":"⓪③","meaning":"看穿，识破","example":"見破る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“看穿，识破”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n見破る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“看穿，识破”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2897","seq":2897,"level":"N1","type":"主词条","word":"魅了","kana":"みりょう","pos":"[名·他動3]","accent":"⓪","meaning":"使人入迷","example":"魅了した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。","exampleZh":"不能只看“使人入迷”之后的结果，还需要回顾此前的准备以及责任分工。","note":"例：\n魅了した結果だけを見るのではなく、そこに至る準備と責任の分担まで振り返る必要がある。\n译：不能只看“使人入迷”之后的结果，还需要回顾此前的准备以及责任分工。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2898","seq":2898,"level":"N1","type":"主词条","word":"未練","kana":"みれん","pos":"[名·ナ形]","accent":"①⓪","meaning":"依恋，不死心","example":"未練な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“依恋，不死心”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n未練な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“依恋，不死心”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2899","seq":2899,"level":"N1","type":"主词条","word":"未練がましい","kana":"みれんがましい","pos":"[イ形]","accent":"⑥","meaning":"恋恋不舍，不干脆","example":"未練がましい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“恋恋不舍，不干脆”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n未練がましい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“恋恋不舍，不干脆”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2900","seq":2900,"level":"N1","type":"主词条","word":"民宿","kana":"みんしゅく","pos":"[名]","accent":"⓪","meaning":"民宿","example":"海沿いの民宿では、宿の主人が朝早く市場で仕入れた魚を夕食に出してくれた。","exampleZh":"海边民宿的主人把清早在市场采购的鱼做成晚餐端了上来。","note":"例：\n海沿いの民宿では、宿の主人が朝早く市場で仕入れた魚を夕食に出してくれた。\n译：海边民宿的主人把清早在市场采购的鱼做成晚餐端了上来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2901","seq":2901,"level":"N1","type":"主词条","word":"ムード","kana":"むーど（mood）","pos":"[名]","accent":"①","meaning":"气氛；心情","example":"ムードが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“气氛；心情”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nムードが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“气氛；心情”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2902","seq":2902,"level":"N1","type":"主词条","word":"むかむか","kana":"むかむか","pos":"[副·自動3]","accent":"①","meaning":"怒火直冒；恶心，作呕","example":"油っこい料理を食べ過ぎて胃がむかむかし、彼は昼休みに少し外の空気を吸いに出た。","exampleZh":"吃了太多油腻食物胃里发恶心，他午休时出去稍微透了透气。","note":"例：\n油っこい料理を食べ過ぎて胃がむかむかし、彼は昼休みに少し外の空気を吸いに出た。\n译：吃了太多油腻食物胃里发恶心，他午休时出去稍微透了透气。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2903","seq":2903,"level":"N1","type":"主词条","word":"無気力","kana":"むきりょく","pos":"[名·ナ形]","accent":"②","meaning":"没精神，缺乏朝气；消极","example":"周囲から無気力だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“没精神，缺乏朝气；消极”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から無気力だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“没精神，缺乏朝气；消极”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2904","seq":2904,"level":"N1","type":"主词条","word":"報いる","kana":"むくいる","pos":"[自他動1]","accent":"③⓪","meaning":"报答","example":"支えてくれた人の期待に報いるため、彼は最後まで準備の手を抜かなかった。","exampleZh":"为了回报支持自己的人的期待，他直到最后都没有在准备上松懈。","note":"例：\n支えてくれた人の期待に報いるため、彼は最後まで準備の手を抜かなかった。\n译：为了回报支持自己的人的期待，他直到最后都没有在准备上松懈。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2905","seq":2905,"level":"N1","type":"主词条","word":"報う","kana":"むくう","pos":"[自他動1]","accent":"②⓪","meaning":"报偿，报答","example":"報うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“报偿，报答”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n報うことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“报偿，报答”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2906","seq":2906,"level":"N1","type":"主词条","word":"無口","kana":"むくち","pos":"[名·ナ形]","accent":"①","meaning":"沉默寡言","example":"一度無口だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“沉默寡言”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度無口だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“沉默寡言”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2907","seq":2907,"level":"N1","type":"主词条","word":"無効","kana":"むこう","pos":"[名·ナ形]","accent":"⓪","meaning":"没效果；（法律上）不生效","example":"無効な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“没效果；不生效”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n無効な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“没效果；不生效”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2908","seq":2908,"level":"N1","type":"主词条","word":"無言","kana":"むごん","pos":"[名]","accent":"⓪","meaning":"无言，沉默","example":"無言の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“无言，沉默”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n無言の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“无言，沉默”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2909","seq":2909,"level":"N1","type":"主词条","word":"むさ苦しい","kana":"むさくるしい","pos":"[イ形]","accent":"⑤","meaning":"不整洁，邋遢","example":"長旅の後でむさ苦しい格好をしていた彼は、面接の前に急いで着替えた。","exampleZh":"长途旅行后他衣着邋遢，于是在面试前急忙换了衣服。","note":"例：\n長旅の後でむさ苦しい格好をしていた彼は、面接の前に急いで着替えた。\n译：长途旅行后他衣着邋遢，于是在面试前急忙换了衣服。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2910","seq":2910,"level":"N1","type":"主词条","word":"貪る","kana":"むさぼる","pos":"[他動1]","accent":"③","meaning":"贪婪，贪图","example":"貪ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“贪婪，贪图”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n貪ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“贪婪，贪图”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2911","seq":2911,"level":"N1","type":"主词条","word":"無残","kana":"むざん","pos":"[名·ナ形]","accent":"①","meaning":"悲惨；残酷，残忍","example":"一度無残だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“悲惨；残酷，残忍”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度無残だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“悲惨；残酷，残忍”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2912","seq":2912,"level":"N1","type":"主词条","word":"無実","kana":"むじつ","pos":"[名]","accent":"①","meaning":"无根据；冤枉","example":"無実を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“无根据；冤枉”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n無実を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“无根据；冤枉”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2913","seq":2913,"level":"N1","type":"主词条","word":"毟る","kana":"むしる","pos":"[他動1]","accent":"⓪","meaning":"揪，拔；撕成碎块","example":"毟る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“揪，拔；撕成碎块”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n毟る前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“揪，拔；撕成碎块”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2914","seq":2914,"level":"N1","type":"主词条","word":"結び付き","kana":"むすびつき","pos":"[名]","accent":"⓪","meaning":"关系，关联","example":"結び付きに甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。","exampleZh":"如果仗着“关系，关联”而怠于确认，小小误解有时会变成很大的不满。","note":"例：\n結び付きに甘えて確認を怠ると、ささいな誤解が大きな不満に変わることがある。\n译：如果仗着“关系，关联”而怠于确认，小小误解有时会变成很大的不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2915","seq":2915,"level":"N1","type":"主词条","word":"無茶","kana":"むちゃ","pos":"[名·ナ形]","accent":"①","meaning":"没道理，不合理；荒唐","example":"無茶な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“没道理，不合理；荒唐”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n無茶な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“没道理，不合理；荒唐”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2916","seq":2916,"level":"N1","type":"主词条","word":"無茶苦茶","kana":"むちゃくちゃ","pos":"[名·ナ形]","accent":"⓪","meaning":"没道理，荒唐；过分，过度","example":"無茶苦茶な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“没道理，荒唐；过分，过度”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n無茶苦茶な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“没道理，荒唐；过分，过度”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2917","seq":2917,"level":"N1","type":"主词条","word":"空しい","kana":"むなしい","pos":"[イ形]","accent":"③⓪","meaning":"空洞；变幻无常","example":"空しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。","exampleZh":"越是在感到“空洞；变幻无常”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","note":"例：\n空しいと感じたときほど、彼はすぐに結論を出さず、相手の意図と背景を確かめるようにしている。\n译：越是在感到“空洞；变幻无常”的时候，他越不会立刻下结论，而会确认对方的意图和背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2918","seq":2918,"level":"N1","type":"主词条","word":"無念","kana":"むねん","pos":"[名·ナ形]","accent":"①","meaning":"万念俱空；懊悔，遗憾","example":"無念な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“万念俱空；懊悔，遗憾”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n無念な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“万念俱空；懊悔，遗憾”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2919","seq":2919,"level":"N1","type":"主词条","word":"無能","kana":"むのう","pos":"[名·ナ形]","accent":"⓪","meaning":"无能","example":"周囲から無能だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“无能”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から無能だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“无能”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2920","seq":2920,"level":"N1","type":"主词条","word":"無謀","kana":"むぼう","pos":"[名·ナ形]","accent":"⓪","meaning":"鲁莽，欠斟酌","example":"無謀な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“鲁莽，欠斟酌”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n無謀な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“鲁莽，欠斟酌”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2921","seq":2921,"level":"N1","type":"主词条","word":"無闇","kana":"むやみ","pos":"[名·ナ形]","accent":"①","meaning":"胡乱，随便；过分，过度","example":"無闇な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。","exampleZh":"如果放任“胡乱，随便；过分，过度”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","note":"例：\n無闇な対応を放置すると、問題そのものよりも組織の誠実さを疑われることになりかねない。\n译：如果放任“胡乱，随便；过分，过度”的应对不管，受到质疑的可能不只是问题本身，还有组织的诚实态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2922","seq":2922,"level":"N1","type":"主词条","word":"斑","kana":"むら","pos":"[名]","accent":"②","meaning":"颜色不均匀；不稳定","example":"斑を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“颜色不均匀；不稳定”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n斑を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“颜色不均匀；不稳定”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2923","seq":2923,"level":"N1","type":"主词条","word":"群がる","kana":"むらがる","pos":"[自動1]","accent":"③","meaning":"群聚，聚集","example":"群がるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“群聚，聚集”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n群がるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“群聚，聚集”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2924","seq":2924,"level":"N1","type":"主词条","word":"無論","kana":"むろん","pos":"[副]","accent":"⓪","meaning":"不用说，当然","example":"安全確認は無論のこと、利用者への事前連絡も欠かせないと責任者は繰り返し述べた。","exampleZh":"安全确认当然不用说，向使用者事先联络也不可或缺，负责人反复这样强调。","note":"例：\n安全確認は無論のこと、利用者への事前連絡も欠かせないと責任者は繰り返し述べた。\n译：安全确认当然不用说，向使用者事先联络也不可或缺，负责人反复这样强调。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2925","seq":2925,"level":"N1","type":"主词条","word":"目当て","kana":"めあて","pos":"[名]","accent":"①","meaning":"着眼点，目标","example":"目当てを形だけ整えても意味がないため、責任者は期限・担当者・費用を一つずつ具体化した。","exampleZh":"目标若只是形式上整理好就没有意义，因此负责人把期限、负责人与费用逐一具体化。","note":"例：\n目当てを形だけ整えても意味がないため、責任者は期限・担当者・費用を一つずつ具体化した。\n译：目标若只是形式上整理好就没有意义，因此负责人把期限、负责人与费用逐一具体化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2926","seq":2926,"level":"N1","type":"主词条","word":"明暗","kana":"めいあん","pos":"[名]","accent":"⓪","meaning":"明暗；浓淡","example":"明暗が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“明暗；浓淡”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n明暗が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“明暗；浓淡”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2927","seq":2927,"level":"N1","type":"主词条","word":"明白","kana":"めいはく","pos":"[名·ナ形]","accent":"⓪","meaning":"明白，明确","example":"明白な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“明白，明确”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n明白な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“明白，明确”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2928","seq":2928,"level":"N1","type":"主词条","word":"名簿","kana":"めいぼ","pos":"[名]","accent":"⓪","meaning":"名单，名册","example":"名簿の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“名单，名册”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n名簿の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“名单，名册”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2929","seq":2929,"level":"N1","type":"主词条","word":"名誉","kana":"めいよ","pos":"[名·ナ形]","accent":"①","meaning":"名誉","example":"周囲から名誉だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“名誉”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から名誉だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“名誉”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2930","seq":2930,"level":"N1","type":"主词条","word":"明瞭","kana":"めいりょう","pos":"[名·ナ形]","accent":"⓪","meaning":"清楚，明了","example":"明瞭な文章を書くには、難しい表現を並べるより、結論と根拠の関係をはっきりさせることが大切だ。","exampleZh":"要写出清晰文章，比起堆砌困难表达，更重要的是明确结论与依据之间的关系。","note":"例：\n明瞭な文章を書くには、難しい表現を並べるより、結論と根拠の関係をはっきりさせることが大切だ。\n译：要写出清晰文章，比起堆砌困难表达，更重要的是明确结论与依据之间的关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2931","seq":2931,"level":"N1","type":"主词条","word":"明朗","kana":"めいろう","pos":"[名·ナ形]","accent":"⓪","meaning":"开朗；正当，公平","example":"一度明朗だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“开朗；正当，公平”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度明朗だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“开朗；正当，公平”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2932","seq":2932,"level":"N1","type":"主词条","word":"めきめき","kana":"めきめき","pos":"[副]","accent":"①","meaning":"（提高）显著，迅速","example":"入社当初は戸惑っていた彼も、先輩の助言を受けながらめきめき実力を伸ばしていった。","exampleZh":"入职之初还很困惑的他，在前辈建议下能力迅速提高。","note":"例：\n入社当初は戸惑っていた彼も、先輩の助言を受けながらめきめき実力を伸ばしていった。\n译：入职之初还很困惑的他，在前辈建议下能力迅速提高。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2933","seq":2933,"level":"N1","type":"主词条","word":"恵み","kana":"めぐみ","pos":"[名]","accent":"⓪","meaning":"恩惠","example":"山から流れる水の恵みを守るため、住民は観光開発と森林保全のバランスを慎重に考えた。","exampleZh":"为了守护山间流下的水的恩惠，居民慎重考虑观光开发与森林保护的平衡。","note":"例：\n山から流れる水の恵みを守るため、住民は観光開発と森林保全のバランスを慎重に考えた。\n译：为了守护山间流下的水的恩惠，居民慎重考虑观光开发与森林保护的平衡。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2934","seq":2934,"level":"N1","type":"主词条","word":"巡らす","kana":"めぐらす","pos":"[他動1]","accent":"⓪③","meaning":"围上，绕上；动脑筋，思考","example":"自分の道を巡らすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“围上，绕上；动脑筋，思考”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を巡らすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“围上，绕上；动脑筋，思考”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2935","seq":2935,"level":"N1","type":"主词条","word":"捲る","kana":"めくる","pos":"[他動1]","accent":"⓪","meaning":"翻起，揭起","example":"捲ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“翻起，揭起”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n捲ることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“翻起，揭起”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2936","seq":2936,"level":"N1","type":"主词条","word":"目先","kana":"めさき","pos":"[名]","accent":"③⓪","meaning":"眼前；预见","example":"目先を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“眼前；预见”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n目先を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“眼前；预见”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2937","seq":2937,"level":"N1","type":"主词条","word":"目覚しい","kana":"めざましい","pos":"[イ形]","accent":"④","meaning":"惊人的","example":"目覚しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“惊人的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n目覚しい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“惊人的”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2938","seq":2938,"level":"N1","type":"主词条","word":"召す","kana":"めす","pos":"[他動1]","accent":"①","meaning":"感冒；上年纪；喜好（尊他语）","example":"召す前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“感冒；上年纪”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n召す前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“感冒；上年纪”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2939","seq":2939,"level":"N1","type":"主词条","word":"メッセージ","kana":"めっせーじ（message）","pos":"[名]","accent":"①","meaning":"口信，留言；传达的信息；消息","example":"メッセージの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。","exampleZh":"“口信，留言；传达的信息”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","note":"例：\nメッセージの内容は一見穏やかだったが、読み進めるほど当事者の怒りと戸惑いがにじみ出ていた。\n译：“口信，留言；传达的信息”的内容乍看很平静，但越读下去，越能感到当事人的愤怒和困惑逐渐渗出。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2940","seq":2940,"level":"N1","type":"主词条","word":"目処","kana":"めど","pos":"[名]","accent":"①","meaning":"目标，眉目，头绪","example":"目処を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“目标，眉目，头绪”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\n目処を立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“目标，眉目，头绪”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2941","seq":2941,"level":"N1","type":"主词条","word":"目まぐるしい","kana":"めまぐるしい","pos":"[イ形]","accent":"⑤","meaning":"瞬息万变","example":"目まぐるしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“瞬息万变”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n目まぐるしい場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“瞬息万变”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2942","seq":2942,"level":"N1","type":"主词条","word":"目盛り","kana":"めもり","pos":"[名]","accent":"③⓪","meaning":"度数，刻度","example":"目盛りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“度数，刻度”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\n目盛りをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“度数，刻度”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2943","seq":2943,"level":"N1","type":"主词条","word":"メリット","kana":"めりっと（merit）","pos":"[名]","accent":"①","meaning":"优点，好处","example":"メリットを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“优点，好处”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nメリットを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“优点，好处”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2944","seq":2944,"level":"N1","type":"主词条","word":"メロディー","kana":"めろでぃー（melody）","pos":"[名]","accent":"①","meaning":"旋律，曲调","example":"その作品ではメロディーが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。","exampleZh":"那部作品中“旋律，曲调”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","note":"例：\nその作品ではメロディーが控えめに使われているが、場面が進むにつれて人物の孤独を強く印象づける。\n译：那部作品中“旋律，曲调”被克制地使用，但随着场面推进，更强烈地凸显了人物的孤独。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2945","seq":2945,"level":"N1","type":"主词条","word":"面会","kana":"めんかい","pos":"[名·自動3]","accent":"⓪","meaning":"见面，会面","example":"面会してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“见面，会面”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n面会してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“见面，会面”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2946","seq":2946,"level":"N1","type":"主词条","word":"免除","kana":"めんじょ","pos":"[名·他動3]","accent":"①","meaning":"免除","example":"初めて免除する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。","exampleZh":"由于这是第一次进行“免除”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","note":"例：\n初めて免除する作業だったため、彼は経験者に確認しながら小さな工程に分けて進めた。\n译：由于这是第一次进行“免除”的作业，他一边向有经验的人确认，一边把流程拆成小步骤推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2947","seq":2947,"level":"N1","type":"主词条","word":"免じる","kana":"めんじる","pos":"[他動2]","accent":"⓪③","meaning":"免除；看在……的面子上","example":"免じる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“免除；看在的面子上”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\n免じる前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“免除；看在的面子上”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2948","seq":2948,"level":"N1","type":"主词条","word":"面する","kana":"めんする","pos":"[自動3]","accent":"③","meaning":"面对；面向","example":"海に面する町では観光が盛んな一方、台風の季節には避難経路の確認が欠かせない。","exampleZh":"面向大海的城镇观光兴盛，但台风季节确认避难路线也不可或缺。","note":"例：\n海に面する町では観光が盛んな一方、台風の季節には避難経路の確認が欠かせない。\n译：面向大海的城镇观光兴盛，但台风季节确认避难路线也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2949","seq":2949,"level":"N1","type":"主词条","word":"面目","kana":"めんぼく／めんもく","pos":"[名]","accent":"⓪","meaning":"脸面，体面","example":"過労が続くと面目に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。","exampleZh":"过劳持续后，“脸面，体面”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","note":"例：\n過労が続くと面目に小さな変化が現れるため、彼女は睡眠時間と食事の内容を見直した。\n译：过劳持续后，“脸面，体面”会出现细小变化，因此她重新审视了睡眠时间和饮食内容。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2950","seq":2950,"level":"N1","type":"主词条","word":"綿密","kana":"めんみつ","pos":"[名·ナ形]","accent":"⓪","meaning":"周密，仔细","example":"綿密な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“周密，仔细”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n綿密な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“周密，仔细”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2951","seq":2951,"level":"N1","type":"主词条","word":"猛～","kana":"もう～","pos":"[接頭]","accent":"","meaning":"强烈，猛烈","example":"猛暑のため外出を控える人が増え、自治体は高齢者へ水分補給と冷房の利用を呼びかけた。","exampleZh":"由于酷暑，减少外出的人增多，自治体呼吁老年人补充水分并使用空调。","note":"例：\n猛暑のため外出を控える人が増え、自治体は高齢者へ水分補給と冷房の利用を呼びかけた。\n译：由于酷暑，减少外出的人增多，自治体呼吁老年人补充水分并使用空调。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2952","seq":2952,"level":"N1","type":"主词条","word":"～網","kana":"～もう","pos":"[接尾]","accent":"","meaning":"……网","example":"連絡網を使って全員に知らせたことで、急な予定変更にも大きな混乱は起きなかった。","exampleZh":"通过使用联络网通知所有人，突然变更日程也没有造成大的混乱。","note":"例：\n連絡網を使って全員に知らせたことで、急な予定変更にも大きな混乱は起きなかった。\n译：通过使用联络网通知所有人，突然变更日程也没有造成大的混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2953","seq":2953,"level":"N1","type":"主词条","word":"設ける","kana":"もうける","pos":"[他動2]","accent":"③","meaning":"准备；设立，制定","example":"無理に設けるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“准备；设立，制定”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に設けるよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“准备；设立，制定”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2954","seq":2954,"level":"N1","type":"主词条","word":"申し入れる","kana":"もうしいれる","pos":"[他動2]","accent":"⑤⓪","meaning":"提议，要求","example":"申し入れる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“提议，要求”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n申し入れる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“提议，要求”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2955","seq":2955,"level":"N1","type":"主词条","word":"申し出る","kana":"もうしでる","pos":"[他動2]","accent":"④","meaning":"提出，申请","example":"申し出る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“提出，申请”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n申し出る場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“提出，申请”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2956","seq":2956,"level":"N1","type":"主词条","word":"申し分","kana":"もうしぶん","pos":"[名]","accent":"⓪③","meaning":"可挑剔的地方；意见","example":"設備には申し分がなかったが、利用者の案内が不十分だったため、初日は小さな混乱が起きた。","exampleZh":"设备本身无可挑剔，但由于对使用者的指引不充分，第一天出现了小混乱。","note":"例：\n設備には申し分がなかったが、利用者の案内が不十分だったため、初日は小さな混乱が起きた。\n译：设备本身无可挑剔，但由于对使用者的指引不充分，第一天出现了小混乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2957","seq":2957,"level":"N1","type":"主词条","word":"盲点","kana":"もうてん","pos":"[名]","accent":"①③","meaning":"盲点，漏洞","example":"盲点を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“盲点，漏洞”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n盲点を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“盲点，漏洞”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2958","seq":2958,"level":"N1","type":"主词条","word":"盲目的","kana":"もうもくてき","pos":"[ナ形]","accent":"⓪","meaning":"盲目的","example":"周囲から盲目的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“盲目的”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から盲目的だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“盲目的”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2959","seq":2959,"level":"N1","type":"主词条","word":"猛烈","kana":"もうれつ","pos":"[名·ナ形]","accent":"⓪","meaning":"猛烈，激烈","example":"周囲から猛烈だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“猛烈，激烈”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から猛烈だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“猛烈，激烈”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2960","seq":2960,"level":"N1","type":"主词条","word":"モーテル","kana":"もーてる（motel）","pos":"[名]","accent":"①","meaning":"汽车旅馆","example":"モーテルを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“汽车旅馆”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\nモーテルを利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“汽车旅馆”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2961","seq":2961,"level":"N1","type":"主词条","word":"もがく","kana":"もがく","pos":"[自動1]","accent":"②","meaning":"挣扎；焦急","example":"もがくような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“挣扎；焦急”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\nもがくような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“挣扎；焦急”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2962","seq":2962,"level":"N1","type":"主词条","word":"もぎ取る","kana":"もぎとる","pos":"[他動1]","accent":"③⓪","meaning":"摘，拧；夺取","example":"無理にもぎ取るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“摘，拧；夺取”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理にもぎ取るよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“摘，拧；夺取”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2963","seq":2963,"level":"N1","type":"主词条","word":"黙々","kana":"もくもく","pos":"[副]","accent":"⓪","meaning":"默默，不声不响","example":"彼女は人前で成果を誇ることなく、毎朝早くから黙々と実験の準備を続けている。","exampleZh":"她不在人前夸耀成果，而是每天清晨默默持续准备实验。","note":"例：\n彼女は人前で成果を誇ることなく、毎朝早くから黙々と実験の準備を続けている。\n译：她不在人前夸耀成果，而是每天清晨默默持续准备实验。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2964","seq":2964,"level":"N1","type":"主词条","word":"目録","kana":"もくろく","pos":"[名]","accent":"⓪","meaning":"目录","example":"目録の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“目录”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n目録の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“目录”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2965","seq":2965,"level":"N1","type":"主词条","word":"目論見","kana":"もくろみ","pos":"[名]","accent":"⓪④","meaning":"计划，企图","example":"立派な目論見でも、現場の制約を無視すれば実行段階で必ず行き詰まる。","exampleZh":"即使是出色的“计划，企图”，若无视现场限制，在执行阶段也一定会受阻。","note":"例：\n立派な目論見でも、現場の制約を無視すれば実行段階で必ず行き詰まる。\n译：即使是出色的“计划，企图”，若无视现场限制，在执行阶段也一定会受阻。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2966","seq":2966,"level":"N1","type":"主词条","word":"目論む","kana":"もくろむ","pos":"[他動1]","accent":"③","meaning":"计划；企图","example":"目論む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“计划；企图”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n目論む場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“计划；企图”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2967","seq":2967,"level":"N1","type":"主词条","word":"模型","kana":"もけい","pos":"[名]","accent":"⓪","meaning":"模型","example":"担当者は模型の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。","exampleZh":"负责人明确了“模型”的标准，并留下记录，以便任何人查看时都能作出相同判断。","note":"例：\n担当者は模型の基準を明確にし、誰が見ても同じ判断になるよう記録を残した。\n译：负责人明确了“模型”的标准，并留下记录，以便任何人查看时都能作出相同判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2968","seq":2968,"level":"N1","type":"主词条","word":"模索","kana":"もさく","pos":"[名·他動3]","accent":"⓪","meaning":"摸索，探寻","example":"チームは模索する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“摸索，探寻”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは模索する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“摸索，探寻”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2969","seq":2969,"level":"N1","type":"主词条","word":"もしくは","kana":"もしくは","pos":"[接]","accent":"①","meaning":"或者","example":"彼女は失敗の原因を認めた。もしくは、同じミスを防ぐための手順もその場で提案した。","exampleZh":"她承认了失败原因。“或者”，还当场提出了防止同样错误的流程。","note":"例：\n彼女は失敗の原因を認めた。もしくは、同じミスを防ぐための手順もその場で提案した。\n译：她承认了失败原因。“或者”，还当场提出了防止同样错误的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2970","seq":2970,"level":"N1","type":"主词条","word":"もじもじ","kana":"もじもじ","pos":"[副·自動3]","accent":"①","meaning":"扭扭捏捏，手足无措","example":"子どもは発表の順番が近づくにつれてもじもじし始め、先生がそっと励ました。","exampleZh":"随着发表顺序临近，孩子开始扭扭捏捏，老师轻声鼓励了他。","note":"例：\n子どもは発表の順番が近づくにつれてもじもじし始め、先生がそっと励ました。\n译：随着发表顺序临近，孩子开始扭扭捏捏，老师轻声鼓励了他。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2971","seq":2971,"level":"N1","type":"主词条","word":"もたらす","kana":"もたらす","pos":"[他動1]","accent":"③","meaning":"带来；招致，造成","example":"もたらす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。","exampleZh":"在“带来；招致，造成”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","note":"例：\nもたらす前に、彼は相手が受け取る意味と自分の責任を一度立ち止まって考えた。\n译：在“带来；招致，造成”之前，他停下来思考了对方会如何理解以及自己应承担的责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2972","seq":2972,"level":"N1","type":"主词条","word":"持ち切り","kana":"もちきり","pos":"[名]","accent":"⓪","meaning":"一直在议论某件事","example":"持ち切りが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“一直在议论某件事”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n持ち切りが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“一直在议论某件事”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2973","seq":2973,"level":"N1","type":"主词条","word":"目下","kana":"もっか","pos":"[名·副]","accent":"①","meaning":"当前，目前","example":"目下の課題は人員の確保であり、設備投資の判断は採用状況を見てから行うことになった。","exampleZh":"当前课题是确保人员，设备投资的判断将根据招聘情况来进行。","note":"例：\n目下の課題は人員の確保であり、設備投資の判断は採用状況を見てから行うことになった。\n译：当前课题是确保人员，设备投资的判断将根据招聘情况来进行。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2974","seq":2974,"level":"N1","type":"主词条","word":"もって","kana":"もって","pos":"[連語]","accent":"①","meaning":"以，用；凭；到","example":"本日の会議をもって、この委員会は一度解散し、来月から新しい体制で活動を始める。","exampleZh":"以今天的会议为节点，这个委员会暂时解散，下个月起以新体制开始活动。","note":"例：\n本日の会議をもって、この委員会は一度解散し、来月から新しい体制で活動を始める。\n译：以今天的会议为节点，这个委员会暂时解散，下个月起以新体制开始活动。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2975","seq":2975,"level":"N1","type":"主词条","word":"もってこい","kana":"もってこい","pos":"[連語]","accent":"④","meaning":"再好不过，理想","example":"駅に近くて静かなこの部屋は、在宅勤務をする人にはもってこいだ。","exampleZh":"这个房间离车站近又安静，对于居家办公的人来说再合适不过。","note":"例：\n駅に近くて静かなこの部屋は、在宅勤務をする人にはもってこいだ。\n译：这个房间离车站近又安静，对于居家办公的人来说再合适不过。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2976","seq":2976,"level":"N1","type":"主词条","word":"もってのほか","kana":"もってのほか","pos":"[名·ナ形]","accent":"③⓪","meaning":"荒谬，岂有此理","example":"もってのほかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“荒谬，岂有此理”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nもってのほかな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“荒谬，岂有此理”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2977","seq":2977,"level":"N1","type":"主词条","word":"専ら","kana":"もっぱら","pos":"[名·副]","accent":"⓪①","meaning":"专门","example":"この部署では専ら利用者からの問い合わせを扱っており、職員には丁寧な聞き取り能力が求められる。","exampleZh":"这个部门专门处理来自使用者的咨询，职员需要具备细致倾听能力。","note":"例：\nこの部署では専ら利用者からの問い合わせを扱っており、職員には丁寧な聞き取り能力が求められる。\n译：这个部门专门处理来自使用者的咨询，职员需要具备细致倾听能力。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2978","seq":2978,"level":"N1","type":"主词条","word":"もつれる","kana":"もつれる","pos":"[自動2]","accent":"③⓪","meaning":"纠缠在一起；纠葛；（手脚等）不听使唤","example":"もつれるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“纠缠在一起；纠葛”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\nもつれるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“纠缠在一起；纠葛”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2979","seq":2979,"level":"N1","type":"主词条","word":"持て余す","kana":"もてあます","pos":"[他動1]","accent":"④⓪","meaning":"难于处理，无法对付","example":"人や情報を持て余す立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“难于处理，无法对付”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報を持て余す立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“难于处理，无法对付”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2980","seq":2980,"level":"N1","type":"主词条","word":"持て成す","kana":"もてなす","pos":"[他動1]","accent":"③","meaning":"招待，接待","example":"持て成す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“招待，接待”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n持て成す場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“招待，接待”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2981","seq":2981,"level":"N1","type":"主词条","word":"持てる/モテる","kana":"モテる","pos":"[自動2]","accent":"②","meaning":"受欢迎，有人缘","example":"持てるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“受欢迎，有人缘”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n持てるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“受欢迎，有人缘”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2982","seq":2982,"level":"N1","type":"主词条","word":"モニター","kana":"モニター（monitor）","pos":"[名]","accent":"①","meaning":"监视器；试用顾客","example":"経験豊かなモニターの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“监视器；试用顾客”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなモニターの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“监视器；试用顾客”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2983","seq":2983,"level":"N1","type":"主词条","word":"物好き","kana":"ものずき","pos":"[名·ナ形]","accent":"③②","meaning":"好奇，好事","example":"周囲から物好きだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“好奇，好事”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から物好きだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“好奇，好事”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2984","seq":2984,"level":"N1","type":"主词条","word":"物足りない","kana":"ものたりない","pos":"[イ形]","accent":"⓪⑤","meaning":"不够满意，感到欠缺","example":"物足りない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“不够满意，感到欠缺”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n物足りない状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“不够满意，感到欠缺”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2985","seq":2985,"level":"N1","type":"主词条","word":"もはや","kana":"もはや","pos":"[副]","accent":"①","meaning":"已经","example":"問題がここまで大きくなった以上、もはや一つの部署だけで対応できる段階ではない。","exampleZh":"问题已经扩大到这个程度，已不再是一个部门可以独自应对的阶段。","note":"例：\n問題がここまで大きくなった以上、もはや一つの部署だけで対応できる段階ではない。\n译：问题已经扩大到这个程度，已不再是一个部门可以独自应对的阶段。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2986","seq":2986,"level":"N1","type":"主词条","word":"模範","kana":"もはん","pos":"[名]","accent":"⓪","meaning":"模范","example":"模範が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“模范”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\n模範が問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“模范”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2987","seq":2987,"level":"N1","type":"主词条","word":"模倣","kana":"もほう","pos":"[名·他動3]","accent":"⓪","meaning":"模仿，效仿","example":"模倣の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“模仿，效仿”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n模倣の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“模仿，效仿”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2988","seq":2988,"level":"N1","type":"主词条","word":"揉め事","kana":"もめごと","pos":"[名]","accent":"⓪","meaning":"纠纷，争吵","example":"小さな揉め事を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“纠纷，争吵”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな揉め事を見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“纠纷，争吵”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2989","seq":2989,"level":"N1","type":"主词条","word":"揉める","kana":"もめる","pos":"[自動2]","accent":"⓪","meaning":"发生争执；心神不定","example":"同じ問題が揉める前に、担当者は現場の小さな兆候を拾い上げ、早めに対策を打った。","exampleZh":"在同样的问题引发争执前，负责人捕捉到现场的小迹象并及早采取了对策。","note":"例：\n同じ問題が揉める前に、担当者は現場の小さな兆候を拾い上げ、早めに対策を打った。\n译：在同样的问题引发争执前，负责人捕捉到现场的小迹象并及早采取了对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2990","seq":2990,"level":"N1","type":"主词条","word":"催す","kana":"もよおす","pos":"[他動1]","accent":"③⓪","meaning":"举办；感觉（要……）","example":"行事を催すなら、参加者の安全や会場周辺への影響まで考えて準備を進める必要がある。","exampleZh":"若要举办活动，就需要连参加者安全和会场周边影响都考虑进去推进准备。","note":"例：\n行事を催すなら、参加者の安全や会場周辺への影響まで考えて準備を進める必要がある。\n译：若要举办活动，就需要连参加者安全和会场周边影响都考虑进去推进准备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2991","seq":2991,"level":"N1","type":"主词条","word":"最寄り","kana":"もより","pos":"[名]","accent":"⓪","meaning":"最近处，附近","example":"最寄りの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“最近处，附近”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n最寄りの背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“最近处，附近”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2992","seq":2992,"level":"N1","type":"主词条","word":"漏らす","kana":"もらす","pos":"[他動1]","accent":"②","meaning":"泄露；遗漏；流露，说出","example":"自分の道を漏らすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“泄露；遗漏”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を漏らすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“泄露；遗漏”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2993","seq":2993,"level":"N1","type":"主词条","word":"～漏らす","kana":"～もらす","pos":"[接尾]","accent":"","meaning":"……漏掉","example":"大切な点を聞き漏らした彼は、会議後に録音を確認し、次回からメモの取り方を改めることにした。","exampleZh":"他漏听了重要内容，会后确认了录音，并决定下次改善记笔记的方法。","note":"例：\n大切な点を聞き漏らした彼は、会議後に録音を確認し、次回からメモの取り方を改めることにした。\n译：他漏听了重要内容，会后确认了录音，并决定下次改善记笔记的方法。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2994","seq":2994,"level":"N1","type":"主词条","word":"盛り付け","kana":"もりつけ","pos":"[名]","accent":"⓪","meaning":"装盘摆设","example":"料理の盛り付けを少し工夫するだけで、同じ食材でも印象が大きく変わる。","exampleZh":"只要稍微在摆盘上下功夫，即使用同样食材，印象也会大不相同。","note":"例：\n料理の盛り付けを少し工夫するだけで、同じ食材でも印象が大きく変わる。\n译：只要稍微在摆盘上下功夫，即使用同样食材，印象也会大不相同。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2995","seq":2995,"level":"N1","type":"主词条","word":"漏る","kana":"もる","pos":"[自動1]","accent":"①","meaning":"漏，泄漏","example":"漏る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。","exampleZh":"如果能在“漏，泄漏”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","note":"例：\n漏る前に小さな兆候をつかめれば、周囲の混乱や負担をかなり減らすことができる。\n译：如果能在“漏，泄漏”之前抓住细小征兆，就能大幅减少周围的混乱和负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2996","seq":2996,"level":"N1","type":"主词条","word":"漏れる","kana":"もれる","pos":"[自動2]","accent":"②","meaning":"漏，泄露；遗漏","example":"漏れる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“漏，泄露；遗漏”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n漏れる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“漏，泄露；遗漏”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2997","seq":2997,"level":"N1","type":"主词条","word":"脆い","kana":"もろい","pos":"[イ形]","accent":"②","meaning":"脆，易碎；脆弱，不坚强","example":"脆い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。","exampleZh":"在涉及“脆，易碎；脆弱，不坚强”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","note":"例：\n脆い場面では無理に取り繕うより、原因を認めて早めに対応するほうが信頼を保てる。\n译：在涉及“脆，易碎；脆弱，不坚强”的场面中，与其勉强掩饰，不如承认原因并尽早应对，这样更能保持信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2998","seq":2998,"level":"N1","type":"主词条","word":"もろに","kana":"もろに","pos":"[副]","accent":"⓪","meaning":"直接，正面","example":"強い風をもろに受けた看板が倒れかけ、通行人の安全を確保するため道路が一時閉鎖された。","exampleZh":"受到强风正面吹袭的招牌险些倒下，为确保行人安全，道路一度封闭。","note":"例：\n強い風をもろに受けた看板が倒れかけ、通行人の安全を確保するため道路が一時閉鎖された。\n译：受到强风正面吹袭的招牌险些倒下，为确保行人安全，道路一度封闭。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-2999","seq":2999,"level":"N1","type":"主词条","word":"矢","kana":"や","pos":"[名]","accent":"①","meaning":"箭，矢","example":"放たれた矢は強い風に流され、的の中心からわずかに外れた場所へ突き刺さった。","exampleZh":"射出的箭被强风吹偏，插在离靶心略有偏离的位置。","note":"例：\n放たれた矢は強い風に流され、的の中心からわずかに外れた場所へ突き刺さった。\n译：射出的箭被强风吹偏，插在离靶心略有偏离的位置。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3000","seq":3000,"level":"N1","type":"主词条","word":"やけに","kana":"やけに","pos":"[副]","accent":"⓪","meaning":"非常，特别","example":"今日は会議室がやけに静かで、参加者はいつもより慎重に言葉を選んでいるようだった。","exampleZh":"今天会议室异常安静，与会者似乎比平时更谨慎地斟酌用词。","note":"例：\n今日は会議室がやけに静かで、参加者はいつもより慎重に言葉を選んでいるようだった。\n译：今天会议室异常安静，与会者似乎比平时更谨慎地斟酌用词。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3001","seq":3001,"level":"N1","type":"主词条","word":"屋敷","kana":"やしき","pos":"[名]","accent":"③","meaning":"宅邸","example":"屋敷が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“宅邸”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n屋敷が関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“宅邸”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3002","seq":3002,"level":"N1","type":"主词条","word":"養う","kana":"やしなう","pos":"[他動1]","accent":"③⓪","meaning":"抚养；培育，培养","example":"養う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“抚养；培育，培养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n養う場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“抚养；培育，培养”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3003","seq":3003,"level":"N1","type":"主词条","word":"野心","kana":"やしん","pos":"[名]","accent":"①⓪","meaning":"野心，抱负","example":"野心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“野心，抱负”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n野心が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“野心，抱负”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3004","seq":3004,"level":"N1","type":"主词条","word":"屋台","kana":"やたい","pos":"[名]","accent":"①","meaning":"流动摊位","example":"屋台の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。","exampleZh":"在探寻“流动摊位”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","note":"例：\n屋台の背景を探るうちに、表には出てこない努力や小さな葛藤が少しずつ見えてきた。\n译：在探寻“流动摊位”背景的过程中，那些不显于表面的努力和小小挣扎逐渐浮现出来。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3005","seq":3005,"level":"N1","type":"主词条","word":"やたら","kana":"やたら","pos":"[副·ナ形]","accent":"⓪","meaning":"胡乱，任意；特别","example":"彼はやたらと専門用語を使うため、初めて聞く人には話の要点がかえって伝わりにくい。","exampleZh":"他过于频繁使用专业术语，反而让第一次听的人难以抓住要点。","note":"例：\n彼はやたらと専門用語を使うため、初めて聞く人には話の要点がかえって伝わりにくい。\n译：他过于频繁使用专业术语，反而让第一次听的人难以抓住要点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3006","seq":3006,"level":"N1","type":"主词条","word":"やってのける","kana":"やってのける","pos":"[他動2]","accent":"④⑤","meaning":"（出色地）做完，干完","example":"やってのけることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“做完，干完”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\nやってのけることの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“做完，干完”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3007","seq":3007,"level":"N1","type":"主词条","word":"山崩れ","kana":"やまくずれ","pos":"[名·自動3]","accent":"③","meaning":"山崩，山体滑坡","example":"山崩れするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“山崩，山体滑坡”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n山崩れするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“山崩，山体滑坡”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3008","seq":3008,"level":"N1","type":"主词条","word":"山積み","kana":"やまづみ","pos":"[名·自他動3]","accent":"⓪","meaning":"堆积，堆积如山","example":"机の上には未処理の書類が山積みになっており、彼は優先順位を決めて一つずつ片づけ始めた。","exampleZh":"桌上堆满了未处理文件，他开始决定优先顺序并逐一整理。","note":"例：\n机の上には未処理の書類が山積みになっており、彼は優先順位を決めて一つずつ片づけ始めた。\n译：桌上堆满了未处理文件，他开始决定优先顺序并逐一整理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3009","seq":3009,"level":"N1","type":"主词条","word":"闇","kana":"やみ","pos":"[名]","accent":"②","meaning":"黑夜；不可预测；非法","example":"政治と金をめぐる闇を明らかにするには、噂ではなく、記録と証言を丁寧に積み重ねる必要がある。","exampleZh":"要揭开围绕政治与金钱的黑暗面，需要细致积累记录和证言，而不是依赖传言。","note":"例：\n政治と金をめぐる闇を明らかにするには、噂ではなく、記録と証言を丁寧に積み重ねる必要がある。\n译：要揭开围绕政治与金钱的黑暗面，需要细致积累记录和证言，而不是依赖传言。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3010","seq":3010,"level":"N1","type":"主词条","word":"病む","kana":"やむ","pos":"[他動1]","accent":"①","meaning":"生病；担心，惦念","example":"病むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“生病；担心，惦念”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n病むことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“生病；担心，惦念”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3011","seq":3011,"level":"N1","type":"主词条","word":"やむを得ず","kana":"やむをえず","pos":"[副]","accent":"④","meaning":"不得已，只好","example":"台風で交通機関が止まったため、主催者はやむを得ず事前相談会をオンライン開催に切り替えた。","exampleZh":"由于台风导致交通停运，主办方不得已把事前咨询会改为线上举办。","note":"例：\n台風で交通機関が止まったため、主催者はやむを得ず事前相談会をオンライン開催に切り替えた。\n译：由于台风导致交通停运，主办方不得已把事前咨询会改为线上举办。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3012","seq":3012,"level":"N1","type":"主词条","word":"ややこしい","kana":"ややこしい","pos":"[イ形]","accent":"④","meaning":"麻烦，复杂","example":"ややこしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“麻烦，复杂”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\nややこしい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“麻烦，复杂”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3013","seq":3013,"level":"N1","type":"主词条","word":"やり繰り","kana":"やりくり","pos":"[名·他動3]","accent":"②⓪","meaning":"安排，筹划","example":"やり繰りする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“安排，筹划”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\nやり繰りする場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“安排，筹划”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3014","seq":3014,"level":"N1","type":"主词条","word":"やりこなす","kana":"やりこなす","pos":"[他動1]","accent":"④","meaning":"妥善处理","example":"人や情報をやりこなす立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。","exampleZh":"如果处在需要“妥善处理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","note":"例：\n人や情報をやりこなす立場にあるなら、効率だけでなく、相手の尊厳と公平さにも配慮すべきだ。\n译：如果处在需要“妥善处理”人员或信息的立场，就不仅要考虑效率，也应照顾对方的尊严和公平。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3015","seq":3015,"level":"N1","type":"主词条","word":"和らげる","kana":"やわらげる","pos":"[他動2]","accent":"④","meaning":"使缓和","example":"患者の不安を和らげるため、看護師は治療の流れを短く伝え、質問できる時間を十分に取った。","exampleZh":"为了缓解患者不安，护士简短说明治疗流程，并留出充分时间让患者提问。","note":"例：\n患者の不安を和らげるため、看護師は治療の流れを短く伝え、質問できる時間を十分に取った。\n译：为了缓解患者不安，护士简短说明治疗流程，并留出充分时间让患者提问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3016","seq":3016,"level":"N1","type":"主词条","word":"ヤング","kana":"やんぐ（young）","pos":"[名]","accent":"①","meaning":"年轻；年轻人","example":"経験豊かなヤングの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“年轻；年轻人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かなヤングの助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“年轻；年轻人”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3017","seq":3017,"level":"N1","type":"主词条","word":"やんわり","kana":"やんわり","pos":"[副·自動3]","accent":"③","meaning":"柔软地；委婉地","example":"彼は相手の努力を認めたうえで、計画の甘さをやんわり指摘し、修正案を一緒に考えた。","exampleZh":"他先认可对方的努力，再委婉指出计划中的不足，并一起思考修正方案。","note":"例：\n彼は相手の努力を認めたうえで、計画の甘さをやんわり指摘し、修正案を一緒に考えた。\n译：他先认可对方的努力，再委婉指出计划中的不足，并一起思考修正方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3018","seq":3018,"level":"N1","type":"主词条","word":"優位","kana":"ゆうい","pos":"[名·ナ形]","accent":"①","meaning":"优势","example":"優位な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“优势”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n優位な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“优势”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3019","seq":3019,"level":"N1","type":"主词条","word":"ゆううつ","kana":"ゆううつ","pos":"[名·ナ形]","accent":"⓪","meaning":"忧郁，忧虑不安","example":"一度ゆううつだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“忧郁，忧虑不安”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度ゆううつだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“忧郁，忧虑不安”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3020","seq":3020,"level":"N1","type":"主词条","word":"有益","kana":"ゆうえき","pos":"[名·ナ形]","accent":"⓪","meaning":"有益，有意义","example":"有益な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“有益，有意义”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n有益な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“有益，有意义”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3021","seq":3021,"level":"N1","type":"主词条","word":"優越","kana":"ゆうえつ","pos":"[名·自動3]","accent":"⓪","meaning":"优越","example":"優越した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。","exampleZh":"考虑到“优越”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","note":"例：\n優越した後の影響まで考え、責任者は関係者への連絡と安全確認を同時に進めた。\n译：考虑到“优越”之后可能产生的影响，负责人同时推进了对相关人员的联络和安全确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3022","seq":3022,"level":"N1","type":"主词条","word":"勇敢","kana":"ゆうかん","pos":"[名·ナ形]","accent":"⓪","meaning":"勇敢，无所畏惧","example":"勇敢な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“勇敢，无所畏惧”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n勇敢な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“勇敢，无所畏惧”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3023","seq":3023,"level":"N1","type":"主词条","word":"遊興","kana":"ゆうきょう","pos":"[名·自動3]","accent":"⓪","meaning":"游乐，饮酒作乐","example":"遊興するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“游乐，饮酒作乐”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n遊興するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“游乐，饮酒作乐”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3024","seq":3024,"level":"N1","type":"主词条","word":"ユーザー","kana":"ゆーざー（user）","pos":"[名]","accent":"①","meaning":"用户","example":"ユーザーをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“用户”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\nユーザーをきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“用户”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3025","seq":3025,"level":"N1","type":"主词条","word":"融資","kana":"ゆうし","pos":"[名·自動3]","accent":"①⓪","meaning":"融资，贷款","example":"融資してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“融资，贷款”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n融資してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“融资，贷款”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3026","seq":3026,"level":"N1","type":"主词条","word":"有数","kana":"ゆうすう","pos":"[名·ナ形]","accent":"⓪","meaning":"屈指可数","example":"この地域は国内有数の豪雪地帯であり、冬の交通対策と高齢者の見守りが欠かせない。","exampleZh":"这一地区是国内屈指可数的豪雪地带，冬季交通对策和老年人看护不可或缺。","note":"例：\nこの地域は国内有数の豪雪地帯であり、冬の交通対策と高齢者の見守りが欠かせない。\n译：这一地区是国内屈指可数的豪雪地带，冬季交通对策和老年人看护不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3027","seq":3027,"level":"N1","type":"主词条","word":"融通","kana":"ゆうずう","pos":"[名·他動3]","accent":"⓪","meaning":"借贷，筹款；随机应变","example":"融通の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。","exampleZh":"如果要改变“借贷，筹款；随机应变”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","note":"例：\n融通の進め方を変えるなら、担当者は現場の負担と利用者への影響を同時に考えなければならない。\n译：如果要改变“借贷，筹款；随机应变”的推进方式，负责人必须同时考虑现场负担和对使用者的影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3028","seq":3028,"level":"N1","type":"主词条","word":"有する","kana":"ゆうする","pos":"[他動3]","accent":"③","meaning":"持有，拥有","example":"無理に有するよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。","exampleZh":"与其勉强推进“持有，拥有”，他更愿意分情况思考，选择对方能够接受的推进方式。","note":"例：\n無理に有するよりも、彼は状況を分けて考え、相手が納得できる進め方を選んだ。\n译：与其勉强推进“持有，拥有”，他更愿意分情况思考，选择对方能够接受的推进方式。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3029","seq":3029,"level":"N1","type":"主词条","word":"優勢","kana":"ゆうせい","pos":"[名·ナ形]","accent":"⓪","meaning":"优势","example":"周囲から優勢だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“优势”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から優勢だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“优势”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3030","seq":3030,"level":"N1","type":"主词条","word":"優先","kana":"ゆうせん","pos":"[名·自動3]","accent":"⓪","meaning":"优先","example":"優先してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“优先”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n優先してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“优先”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3031","seq":3031,"level":"N1","type":"主词条","word":"誘致","kana":"ゆうち","pos":"[名·他動3]","accent":"①","meaning":"招揽","example":"誘致する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“招揽”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n誘致する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“招揽”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3032","seq":3032,"level":"N1","type":"主词条","word":"誘導","kana":"ゆうどう","pos":"[名·他動3]","accent":"⓪","meaning":"引导，诱导","example":"チームは誘導する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“引导，诱导”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは誘導する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“引导，诱导”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3033","seq":3033,"level":"N1","type":"主词条","word":"優美","kana":"ゆうび","pos":"[名·ナ形]","accent":"①","meaning":"优美","example":"一見優美な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。","exampleZh":"乍看给人“优美”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","note":"例：\n一見優美な印象を受けるが、細部を見ると、使う人への配慮が丁寧に積み重ねられている。\n译：乍看给人“优美”的印象，但细看之下，能发现对使用者的体贴被细致地层层积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3034","seq":3034,"level":"N1","type":"主词条","word":"裕福","kana":"ゆうふく","pos":"[名·ナ形]","accent":"①⓪","meaning":"富裕","example":"裕福な家庭に生まれたとしても、他人の苦労を想像する力がなければ信頼は得られない。","exampleZh":"即使出生在富裕家庭，如果没有想象他人辛苦的能力，也无法获得信任。","note":"例：\n裕福な家庭に生まれたとしても、他人の苦労を想像する力がなければ信頼は得られない。\n译：即使出生在富裕家庭，如果没有想象他人辛苦的能力，也无法获得信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3035","seq":3035,"level":"N1","type":"主词条","word":"有望","kana":"ゆうぼう","pos":"[名·ナ形]","accent":"⓪","meaning":"有望，有好的前景","example":"有望な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“有望，有好的前景”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n有望な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“有望，有好的前景”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3036","seq":3036,"level":"N1","type":"主词条","word":"夕焼け","kana":"ゆうやけ","pos":"[名]","accent":"⓪","meaning":"晚霞","example":"夕焼けが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“晚霞”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\n夕焼けが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“晚霞”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3037","seq":3037,"level":"N1","type":"主词条","word":"夕闇","kana":"ゆうやみ","pos":"[名]","accent":"⓪","meaning":"暮色，黄昏，黑暗","example":"夕闇の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“暮色，黄昏，黑暗”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n夕闇の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“暮色，黄昏，黑暗”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3038","seq":3038,"level":"N1","type":"主词条","word":"猶予","kana":"ゆうよ","pos":"[名·自動3]","accent":"①","meaning":"延期，缓期","example":"納期の猶予を求めるなら、相手の負担を減らす代替案も同時に示すべきだ。","exampleZh":"若要求延缓交期，也应同时提出能减轻对方负担的替代方案。","note":"例：\n納期の猶予を求めるなら、相手の負担を減らす代替案も同時に示すべきだ。\n译：若要求延缓交期，也应同时提出能减轻对方负担的替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3039","seq":3039,"level":"N1","type":"主词条","word":"有力","kana":"ゆうりょく","pos":"[名·ナ形]","accent":"⓪","meaning":"有力，有势力；有希望","example":"周囲から有力だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“有力，有势力；有希望”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から有力だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“有力，有势力；有希望”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3040","seq":3040,"level":"N1","type":"主词条","word":"誘惑","kana":"ゆうわく","pos":"[名·他動3]","accent":"⓪","meaning":"诱惑","example":"チームは誘惑する理由を共有し、後から検証できるよう判断の根拠を記録に残した。","exampleZh":"团队共享了进行“诱惑”的理由，并把判断依据留成记录，以便之后验证。","note":"例：\nチームは誘惑する理由を共有し、後から検証できるよう判断の根拠を記録に残した。\n译：团队共享了进行“诱惑”的理由，并把判断依据留成记录，以便之后验证。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3041","seq":3041,"level":"N1","type":"主词条","word":"ゆえに","kana":"ゆえに","pos":"[接]","accent":"②","meaning":"所以，故而","example":"情報が十分に共有されていなかった。ゆえに、現場では誤解が生じた。","exampleZh":"信息没有被充分共享。因此，现场产生了误解。","note":"例：\n情報が十分に共有されていなかった。ゆえに、現場では誤解が生じた。\n译：信息没有被充分共享。因此，现场产生了误解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3042","seq":3042,"level":"N1","type":"主词条","word":"歪む","kana":"ゆがむ","pos":"[自動1]","accent":"⓪②","meaning":"歪斜；心术不正","example":"歪むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“歪斜；心术不正”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n歪むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“歪斜；心术不正”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3043","seq":3043,"level":"N1","type":"主词条","word":"行き届く","kana":"ゆきとどく","pos":"[自動1]","accent":"④","meaning":"周到，无微不至","example":"行き届く場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“周到，无微不至”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n行き届く場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“周到，无微不至”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3044","seq":3044,"level":"N1","type":"主词条","word":"行く手","kana":"ゆくて","pos":"[名]","accent":"⓪③","meaning":"去处，去路","example":"濃い霧が行く手を遮ったため、登山隊は無理に進まず安全な場所で天候の回復を待った。","exampleZh":"浓雾挡住去路，登山队没有勉强前进，而是在安全地点等待天气恢复。","note":"例：\n濃い霧が行く手を遮ったため、登山隊は無理に進まず安全な場所で天候の回復を待った。\n译：浓雾挡住去路，登山队没有勉强前进，而是在安全地点等待天气恢复。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3045","seq":3045,"level":"N1","type":"主词条","word":"揺さぶる","kana":"ゆさぶる","pos":"[他動1]","accent":"⓪","meaning":"摇动；震撼；动摇","example":"自分の道を揺さぶるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“摇动；震撼”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を揺さぶるなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“摇动；震撼”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3046","seq":3046,"level":"N1","type":"主词条","word":"委ねる","kana":"ゆだねる","pos":"[他動2]","accent":"③","meaning":"委托；委身","example":"委ねる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“委托；委身”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n委ねる場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“委托；委身”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3047","seq":3047,"level":"N1","type":"主词条","word":"ゆとり","kana":"ゆとり","pos":"[名]","accent":"⓪","meaning":"宽裕，余裕","example":"ゆとりの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“宽裕，余裕”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nゆとりの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“宽裕，余裕”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3048","seq":3048,"level":"N1","type":"主词条","word":"ユニフォーム","kana":"ゆにふぉーむ（uniform）","pos":"[名]","accent":"①③","meaning":"制服","example":"式典に着ていくユニフォームを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。","exampleZh":"选择参加典礼穿的“制服”时，她比起华丽，更重视符合场合的沉稳感。","note":"例：\n式典に着ていくユニフォームを選ぶ際、彼女は華やかさよりも場にふさわしい落ち着きを重視した。\n译：选择参加典礼穿的“制服”时，她比起华丽，更重视符合场合的沉稳感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3049","seq":3049,"level":"N1","type":"主词条","word":"指差す","kana":"ゆびさす","pos":"[他動1]","accent":"③","meaning":"指方向，用手指指着","example":"指差すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。","exampleZh":"考虑到“指方向，用手指指着”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","note":"例：\n指差すことの影響を考え、彼女は勢いだけで動かず、必要な確認を先に済ませた。\n译：考虑到“指方向，用手指指着”所带来的影响，她没有凭一时冲动行动，而是先完成了必要确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3050","seq":3050,"level":"N1","type":"主词条","word":"ゆゆしい","kana":"ゆゆしい","pos":"[イ形]","accent":"③","meaning":"严重，重大（用于消极意义）","example":"ゆゆしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。","exampleZh":"即使感到“严重，重大”的印象，他也没有只凭表面话语断定对方的处境。","note":"例：\nゆゆしい印象を受けたとしても、彼は表面的な言葉だけで相手の事情を決めつけなかった。\n译：即使感到“严重，重大”的印象，他也没有只凭表面话语断定对方的处境。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3051","seq":3051,"level":"N1","type":"主词条","word":"揺らぐ","kana":"ゆらぐ","pos":"[自動1]","accent":"②⓪","meaning":"摇晃；动摇","example":"一度信頼が揺らぐと、元に戻すには以前よりも丁寧な報告と小さな約束の積み重ねが必要になる。","exampleZh":"一旦信任动摇，要恢复就需要比以前更细致的报告和小小承诺的积累。","note":"例：\n一度信頼が揺らぐと、元に戻すには以前よりも丁寧な報告と小さな約束の積み重ねが必要になる。\n译：一旦信任动摇，要恢复就需要比以前更细致的报告和小小承诺的积累。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3052","seq":3052,"level":"N1","type":"主词条","word":"ゆらゆら","kana":"ゆらゆら","pos":"[副·自動3]","accent":"①","meaning":"轻轻摇动","example":"湖面に映った灯りがゆらゆら揺れ、夜の港は静かな雰囲気に包まれていた。","exampleZh":"映在湖面上的灯光轻轻摇曳，夜晚的港口笼罩在静谧氛围中。","note":"例：\n湖面に映った灯りがゆらゆら揺れ、夜の港は静かな雰囲気に包まれていた。\n译：映在湖面上的灯光轻轻摇曳，夜晚的港口笼罩在静谧氛围中。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3053","seq":3053,"level":"N1","type":"主词条","word":"揺るがす","kana":"ゆるがす","pos":"[他動1]","accent":"③⓪","meaning":"摇动；震撼","example":"自分の道を揺るがすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。","exampleZh":"在走向属于自己的“摇动；震撼”过程中，他比起捷径，更珍惜从失败中学习的时间。","note":"例：\n自分の道を揺るがすなかで、彼は近道よりも、失敗から学ぶ時間を大切にしてきた。\n译：在走向属于自己的“摇动；震撼”过程中，他比起捷径，更珍惜从失败中学习的时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3054","seq":3054,"level":"N1","type":"主词条","word":"緩む","kana":"ゆるむ","pos":"[自動1]","accent":"②","meaning":"宽松；疏忽；缓和","example":"緩むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“宽松；疏忽”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n緩むような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“宽松；疏忽”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3055","seq":3055,"level":"N1","type":"主词条","word":"緩める","kana":"ゆるめる","pos":"[他動2]","accent":"③","meaning":"放松；放慢；疏忽","example":"無理に緩めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“放松；放慢”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に緩めると事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“放松；放慢”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3056","seq":3056,"level":"N1","type":"主词条","word":"緩やか","kana":"ゆるやか","pos":"[ナ形]","accent":"②","meaning":"平缓；舒畅；不严格，宽大","example":"緩やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“平缓；舒畅”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n緩やかな状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“平缓；舒畅”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3057","seq":3057,"level":"N1","type":"主词条","word":"世","kana":"よ","pos":"[名]","accent":"①","meaning":"社会，人世间","example":"経験豊かな世の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“社会，人世间”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな世の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“社会，人世间”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3058","seq":3058,"level":"N1","type":"主词条","word":"余～","kana":"よ～","pos":"[接頭]","accent":"","meaning":"余下的……","example":"余白に大事なメモを書き込んだおかげで、後から資料を読み返したときに議論の流れを思い出せた。","exampleZh":"多亏在空白处写下重要备忘，之后重读资料时想起了讨论的流程。","note":"例：\n余白に大事なメモを書き込んだおかげで、後から資料を読み返したときに議論の流れを思い出せた。\n译：多亏在空白处写下重要备忘，之后重读资料时想起了讨论的流程。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3059","seq":3059,"level":"N1","type":"主词条","word":"要因","kana":"よういん","pos":"[名]","accent":"⓪","meaning":"主要原因","example":"要因を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“主要原因”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n要因を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“主要原因”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3060","seq":3060,"level":"N1","type":"主词条","word":"容赦","kana":"ようしゃ","pos":"[名·他動3]","accent":"①","meaning":"宽恕，姑息","example":"彼は容赦を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。","exampleZh":"他没有急着处理“宽恕，姑息”，而是先了解相关人员真正需要什么，并备齐必要资料。","note":"例：\n彼は容赦を急がず、まず関係者が何を求めているのかを聞き取り、必要な資料をそろえた。\n译：他没有急着处理“宽恕，姑息”，而是先了解相关人员真正需要什么，并备齐必要资料。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3061","seq":3061,"level":"N1","type":"主词条","word":"要する","kana":"ようする","pos":"[他動3]","accent":"③","meaning":"需要","example":"要する場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。","exampleZh":"在涉及“需要”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","note":"例：\n要する場面では、短期的な都合よりも、後で責任を持てる手順を選ぶことが大切だ。\n译：在涉及“需要”的场面中，比起短期便利，更重要的是选择日后能够负责的程序。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3062","seq":3062,"level":"N1","type":"主词条","word":"要請","kana":"ようせい","pos":"[名·他動3]","accent":"⓪","meaning":"请求，要求","example":"要請する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“请求，要求”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n要請する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“请求，要求”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3063","seq":3063,"level":"N1","type":"主词条","word":"養成","kana":"ようせい","pos":"[名·他動3]","accent":"⓪","meaning":"培训，培养","example":"養成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“培训，培养”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n養成する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“培训，培养”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3064","seq":3064,"level":"N1","type":"主词条","word":"様相","kana":"ようそう","pos":"[名]","accent":"⓪","meaning":"外观，状态","example":"様相の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。","exampleZh":"为了确认“外观，状态”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","note":"例：\n様相の安全性を確かめるため、専門家は見た目だけでなく内部の劣化や過去の修理記録も調べた。\n译：为了确认“外观，状态”的安全性，专家不仅查看外观，还调查了内部老化情况和过去的维修记录。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3065","seq":3065,"level":"N1","type":"主词条","word":"用法","kana":"ようほう","pos":"[名]","accent":"⓪","meaning":"用法","example":"薬の用法を守らずに量を増やすと、副作用が強く出るおそれがあるため注意が必要だ。","exampleZh":"如果不遵守药物用法而增加剂量，可能出现更强副作用，因此需要注意。","note":"例：\n薬の用法を守らずに量を増やすと、副作用が強く出るおそれがあるため注意が必要だ。\n译：如果不遵守药物用法而增加剂量，可能出现更强副作用，因此需要注意。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3066","seq":3066,"level":"N1","type":"主词条","word":"予感","kana":"よかん","pos":"[名]","accent":"⓪","meaning":"预感","example":"予感が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。","exampleZh":"“预感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","note":"例：\n予感が強いほど、相手の言葉を悪意として受け取りやすくなるので、彼は第三者の意見も聞いた。\n译：“预感”越强，就越容易把对方的话理解成恶意，因此他也听取了第三方意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3067","seq":3067,"level":"N1","type":"主词条","word":"余興","kana":"よきょう","pos":"[名]","accent":"⓪","meaning":"余兴，余兴节目","example":"彼女は余興をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“余兴，余兴节目”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は余興をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“余兴，余兴节目”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3068","seq":3068,"level":"N1","type":"主词条","word":"抑圧","kana":"よくあつ","pos":"[名·他動3]","accent":"⓪","meaning":"压迫，压制","example":"相手を抑圧するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。","exampleZh":"单纯对对方进行“压迫，压制”只会加深对立，因此她决定先确认其主张背后的背景。","note":"例：\n相手を抑圧するだけでは対立が深まるため、彼女はまず主張の背景を確かめることにした。\n译：单纯对对方进行“压迫，压制”只会加深对立，因此她决定先确认其主张背后的背景。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3069","seq":3069,"level":"N1","type":"主词条","word":"抑制","kana":"よくせい","pos":"[名·他動3]","accent":"⓪","meaning":"抑制，制止","example":"物価の急上昇を抑制するため、政府は補助金と規制の見直しを同時に進めた。","exampleZh":"为了抑制物价急剧上涨，政府同时推进补助金和规制的重新审视。","note":"例：\n物価の急上昇を抑制するため、政府は補助金と規制の見直しを同時に進めた。\n译：为了抑制物价急剧上涨，政府同时推进补助金和规制的重新审视。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3070","seq":3070,"level":"N1","type":"主词条","word":"欲深い","kana":"よくぶかい","pos":"[イ形]","accent":"④","meaning":"贪婪","example":"欲深い投資家に言い寄られても、彼は短期的な利益より会社の信用を守ることを選んだ。","exampleZh":"即使被贪婪的投资者游说，他也选择守护公司信用，而不是短期利益。","note":"例：\n欲深い投資家に言い寄られても、彼は短期的な利益より会社の信用を守ることを選んだ。\n译：即使被贪婪的投资者游说，他也选择守护公司信用，而不是短期利益。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3071","seq":3071,"level":"N1","type":"主词条","word":"予言","kana":"よげん","pos":"[名·他動3]","accent":"⓪","meaning":"预言","example":"予言する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“预言”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n予言する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“预言”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3072","seq":3072,"level":"N1","type":"主词条","word":"横たわる","kana":"よこたわる","pos":"[自動1]","accent":"④","meaning":"躺下；横亘；横在面前","example":"横たわるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。","exampleZh":"在像“躺下；横亘”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","note":"例：\n横たわるような状況では、表面的な変化だけで判断せず、背景にある事情を確かめる必要がある。\n译：在像“躺下；横亘”这样的情况下，不能只凭表面变化判断，还需要确认背后的原因和情形。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3073","seq":3073,"level":"N1","type":"主词条","word":"横道","kana":"よこみち","pos":"[名]","accent":"⓪","meaning":"岔道，歧路","example":"その横道を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。","exampleZh":"实际走过那片“岔道，歧路”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","note":"例：\nその横道を実際に歩いてみると、地図や統計だけでは見えない暮らしの不便さが少しずつ分かってきた。\n译：实际走过那片“岔道，歧路”之后，才渐渐明白仅凭地图和统计看不出的生活不便。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3074","seq":3074,"level":"N1","type":"主词条","word":"良し悪し","kana":"よしあし","pos":"[名]","accent":"①②","meaning":"好坏，善恶","example":"小さな良し悪しを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。","exampleZh":"由于忽视了细小的“好坏，善恶”，后续工序需要大幅修正，整个团队的计划也被打乱。","note":"例：\n小さな良し悪しを見過ごした結果、後の工程で大きな修正が必要になり、チーム全体の予定が崩れた。\n译：由于忽视了细小的“好坏，善恶”，后续工序需要大幅修正，整个团队的计划也被打乱。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3075","seq":3075,"level":"N1","type":"主词条","word":"攀じ登る","kana":"よじのぼる","pos":"[自動1]","accent":"④⓪","meaning":"攀登，往上爬","example":"急な岩場を攀じ登るには、腕力だけでなく足を置く位置を冷静に見極める必要がある。","exampleZh":"攀登陡峭岩场时，不仅需要臂力，也要冷静判断落脚位置。","note":"例：\n急な岩場を攀じ登るには、腕力だけでなく足を置く位置を冷静に見極める必要がある。\n译：攀登陡峭岩场时，不仅需要臂力，也要冷静判断落脚位置。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3076","seq":3076,"level":"N1","type":"主词条","word":"装う","kana":"よそおう","pos":"[他動1]","accent":"③","meaning":"装饰；装扮；假装","example":"無理に装うと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。","exampleZh":"若勉强进行“装饰；装扮”，可能导致事故，因此作业人员确认了步骤和周围安全。","note":"例：\n無理に装うと事故につながる恐れがあるため、作業員は手順と周囲の安全を確かめた。\n译：若勉强进行“装饰；装扮”，可能导致事故，因此作业人员确认了步骤和周围安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3077","seq":3077,"level":"N1","type":"主词条","word":"余所見","kana":"よそみ","pos":"[名·自動3]","accent":"②③","meaning":"斜视，往旁处看","example":"余所見するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“斜视，往旁处看”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n余所見するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“斜视，往旁处看”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3078","seq":3078,"level":"N1","type":"主词条","word":"余地","kana":"よち","pos":"[名]","accent":"①","meaning":"余地","example":"余地が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。","exampleZh":"由于“余地”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","note":"例：\n余地が思わぬ形で影響したため、チームは計画を修正し、確認の手順を増やした。\n译：由于“余地”以意想不到的形式产生了影响，团队修改了计划，并增加了确认步骤。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3079","seq":3079,"level":"N1","type":"主词条","word":"欲求","kana":"よっきゅう","pos":"[名]","accent":"⓪","meaning":"欲求，欲望","example":"欲求をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“欲求，欲望”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n欲求をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“欲求，欲望”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3080","seq":3080,"level":"N1","type":"主词条","word":"よって","kana":"よって","pos":"[接]","accent":"⓪","meaning":"故而，因此","example":"提出期限を過ぎている。よって、追加資料は参考扱いとする。","exampleZh":"已经超过提交期限。因此，追加资料将作为参考处理。","note":"例：\n提出期限を過ぎている。よって、追加資料は参考扱いとする。\n译：已经超过提交期限。因此，追加资料将作为参考处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3081","seq":3081,"level":"N1","type":"主词条","word":"夜更け","kana":"よふけ","pos":"[名]","accent":"③","meaning":"深夜","example":"限られた夜更けの中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。","exampleZh":"即使在有限的“深夜”之中，他也没有急于判断，而是先把优先顺序写在纸上。","note":"例：\n限られた夜更けの中でも、彼は焦って判断せず、最初に優先順位を紙に書き出した。\n译：即使在有限的“深夜”之中，他也没有急于判断，而是先把优先顺序写在纸上。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3082","seq":3082,"level":"N1","type":"主词条","word":"余程","kana":"よほど","pos":"[副]","accent":"⓪","meaning":"很，相当","example":"彼は余程疲れていたのか、いつもなら気づく小さな入力ミスを何度も見落としていた。","exampleZh":"也许他相当疲惫，平时能发现的小输入错误也反复漏看。","note":"例：\n彼は余程疲れていたのか、いつもなら気づく小さな入力ミスを何度も見落としていた。\n译：也许他相当疲惫，平时能发现的小输入错误也反复漏看。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3083","seq":3083,"level":"N1","type":"主词条","word":"読み上げる","kana":"よみあげる","pos":"[他動2]","accent":"④⓪","meaning":"朗读；读完","example":"相手に何かを読み上げるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。","exampleZh":"如果要对对方做出“朗读；读完”，就不应只看结果，还要考虑之后留下的信任关系。","note":"例：\n相手に何かを読み上げるなら、結果だけでなく、その後に残る信頼関係まで考えるべきだ。\n译：如果要对对方做出“朗读；读完”，就不应只看结果，还要考虑之后留下的信任关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3084","seq":3084,"level":"N1","type":"主词条","word":"蘇る","kana":"よみがえる","pos":"[自動1]","accent":"③⓪","meaning":"复活；恢复","example":"勢いが少しずつ蘇る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“复活；恢复”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ蘇る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“复活；恢复”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3085","seq":3085,"level":"N1","type":"主词条","word":"よもや","kana":"よもや","pos":"[副]","accent":"①","meaning":"（常与否定相呼应）未必，难道","example":"よもや全員が同じ資料を読み違えていたとは思わず、責任者は確認方法そのものを見直した。","exampleZh":"负责人没想到全员竟会误读同一份资料，于是重新审视了确认方法本身。","note":"例：\nよもや全員が同じ資料を読み違えていたとは思わず、責任者は確認方法そのものを見直した。\n译：负责人没想到全员竟会误读同一份资料，于是重新审视了确认方法本身。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3086","seq":3086,"level":"N1","type":"主词条","word":"寄り掛かる","kana":"よりかかる","pos":"[自動1]","accent":"④","meaning":"靠，倚靠；依靠","example":"寄り掛かる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“靠，倚靠；依靠”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n寄り掛かる場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“靠，倚靠；依靠”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3087","seq":3087,"level":"N1","type":"主词条","word":"寄り添う","kana":"よりそう","pos":"[自動1]","accent":"③","meaning":"贴近，挨近","example":"寄り添う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。","exampleZh":"为了应对涉及“贴近，挨近”的场面，负责人事先共享了联系方式和判断标准。","note":"例：\n寄り添う場面に備えて、担当者は連絡先と判断基準を事前に共有しておいた。\n译：为了应对涉及“贴近，挨近”的场面，负责人事先共享了联系方式和判断标准。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3088","seq":3088,"level":"N1","type":"主词条","word":"弱気","kana":"よわき","pos":"[名·ナ形]","accent":"⓪","meaning":"怯弱，胆怯","example":"弱気な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“怯弱，胆怯”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\n弱気な対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“怯弱，胆怯”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3089","seq":3089,"level":"N1","type":"主词条","word":"弱音","kana":"よわね","pos":"[名]","accent":"⓪","meaning":"泄气的话","example":"責任者だからといって弱音を一切吐けない職場では、問題が表に出る前に人が疲れ切ってしまう。","exampleZh":"如果身为负责人就完全不能说泄气话，问题还没浮上台面，人就会先疲惫不堪。","note":"例：\n責任者だからといって弱音を一切吐けない職場では、問題が表に出る前に人が疲れ切ってしまう。\n译：如果身为负责人就完全不能说泄气话，问题还没浮上台面，人就会先疲惫不堪。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3090","seq":3090,"level":"N1","type":"主词条","word":"弱まる","kana":"よわまる","pos":"[自動1]","accent":"③","meaning":"变弱；衰弱","example":"雨が弱まるのを待ってから出発したため、参加者はほとんど濡れずに会場へ到着できた。","exampleZh":"等雨势减弱后再出发，参加者几乎没被淋湿就到达了会场。","note":"例：\n雨が弱まるのを待ってから出発したため、参加者はほとんど濡れずに会場へ到着できた。\n译：等雨势减弱后再出发，参加者几乎没被淋湿就到达了会场。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3091","seq":3091,"level":"N1","type":"主词条","word":"弱る","kana":"よわる","pos":"[自動1]","accent":"②","meaning":"身体变弱；为难，尴尬","example":"勢いが少しずつ弱る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。","exampleZh":"在势头逐渐“身体变弱；为难，尴尬”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","note":"例：\n勢いが少しずつ弱る前に、関係者は原因を見直し、次の世代へつなぐ方法を考えた。\n译：在势头逐渐“身体变弱；为难，尴尬”之前，相关人员重新审视原因，并思考如何把经验传给下一代。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3092","seq":3092,"level":"N1","type":"主词条","word":"来場","kana":"らいじょう","pos":"[名·自動3]","accent":"⓪","meaning":"出席，到场","example":"来場する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“出席，到场”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n来場する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“出席，到场”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3093","seq":3093,"level":"N1","type":"主词条","word":"ライセンス","kana":"らいせんす（license）","pos":"[名]","accent":"①","meaning":"许可证，执照","example":"ライセンスの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“许可证，执照”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\nライセンスの扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“许可证，执照”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3094","seq":3094,"level":"N1","type":"主词条","word":"ライフスタイル","kana":"らいふすたいる（lifestyle）","pos":"[名]","accent":"⑤","meaning":"生活方式","example":"ライフスタイルをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。","exampleZh":"对“生活方式”的理解会因立场而异，因此他没有只依据一种意见就下结论。","note":"例：\nライフスタイルをどう受け止めるかは立場によって異なるため、彼は一つの意見だけで結論を出さなかった。\n译：对“生活方式”的理解会因立场而异，因此他没有只依据一种意见就下结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3095","seq":3095,"level":"N1","type":"主词条","word":"来訪","kana":"らいほう","pos":"[名·自動3]","accent":"⓪","meaning":"来访","example":"来訪してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“来访”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n来訪してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“来访”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3096","seq":3096,"level":"N1","type":"主词条","word":"落書き","kana":"らくがき","pos":"[名·自動3]","accent":"⓪","meaning":"涂鸦，乱涂乱画","example":"歴史ある壁に落書きした人がいると分かり、地域の住民は保存活動の難しさを改めて感じた。","exampleZh":"得知有人在历史悠久的墙壁上乱涂乱画，地区居民再次感受到保存活动的困难。","note":"例：\n歴史ある壁に落書きした人がいると分かり、地域の住民は保存活動の難しさを改めて感じた。\n译：得知有人在历史悠久的墙壁上乱涂乱画，地区居民再次感受到保存活动的困难。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3097","seq":3097,"level":"N1","type":"主词条","word":"落胆","kana":"らくたん","pos":"[名·自動3]","accent":"⓪","meaning":"沮丧","example":"落胆する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“沮丧”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n落胆する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“沮丧”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3098","seq":3098,"level":"N1","type":"主词条","word":"酪農","kana":"らくのう","pos":"[名]","accent":"⓪","meaning":"乳畜业","example":"酪農をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“乳畜业”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n酪農をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“乳畜业”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3099","seq":3099,"level":"N1","type":"主词条","word":"ラグビー","kana":"らぐびー（rugby）","pos":"[名]","accent":"①","meaning":"橄榄球","example":"ラグビーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“橄榄球”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nラグビーを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“橄榄球”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3100","seq":3100,"level":"N1","type":"主词条","word":"ラスト","kana":"らすと（last）","pos":"[名]","accent":"①","meaning":"最后，最终","example":"ラストを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“最后，最终”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\nラストを無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“最后，最终”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3101","seq":3101,"level":"N1","type":"主词条","word":"拉致","kana":"らち","pos":"[名·他動3]","accent":"①","meaning":"强行拉走，绑架","example":"子どもの拉致を防ぐため、学校は登下校時の見守り体制を強化した。","exampleZh":"为了防止儿童被绑架，学校加强了上下学时的看护体制。","note":"例：\n子どもの拉致を防ぐため、学校は登下校時の見守り体制を強化した。\n译：为了防止儿童被绑架，学校加强了上下学时的看护体制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3102","seq":3102,"level":"N1","type":"主词条","word":"落下","kana":"らっか","pos":"[名·自動3]","accent":"⓪①","meaning":"落下，掉下","example":"落下する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。","exampleZh":"既然存在发生“落下，掉下”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","note":"例：\n落下する可能性がある以上、担当者は小さな変化を見逃さず、早めに次の手を打つ必要があった。\n译：既然存在发生“落下，掉下”的可能，负责人就必须不放过细小变化，并及早采取下一步措施。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3103","seq":3103,"level":"N1","type":"主词条","word":"ラッキー","kana":"らっきー（lucky）","pos":"[名·ナ形]","accent":"①","meaning":"幸运","example":"ラッキーな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“幸运”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\nラッキーな印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“幸运”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3104","seq":3104,"level":"N1","type":"主词条","word":"ラフ","kana":"らふ（rough）","pos":"[ナ形]","accent":"①","meaning":"粗略，粗糙，随便","example":"周囲からラフだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“粗略，粗糙，随便”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲からラフだと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“粗略，粗糙，随便”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3105","seq":3105,"level":"N1","type":"主词条","word":"ランク","kana":"らんく（rank）","pos":"[名·他動3]","accent":"①","meaning":"（排）次序","example":"ホテルのランクだけで選ぶのではなく、立地やスタッフの対応まで確認してから予約を決めた。","exampleZh":"他没有只按酒店等级选择，而是确认位置和工作人员服务后才决定预订。","note":"例：\nホテルのランクだけで選ぶのではなく、立地やスタッフの対応まで確認してから予約を決めた。\n译：他没有只按酒店等级选择，而是确认位置和工作人员服务后才决定预订。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3106","seq":3106,"level":"N1","type":"主词条","word":"濫用／乱用","kana":"らんよう","pos":"[名·他動3]","accent":"⓪","meaning":"滥用","example":"権限を濫用／乱用すれば、一時的に目的を達成できても組織への信頼は失われる。","exampleZh":"如果滥用权限，即使一时达成目的，也会失去对组织的信任。","note":"例：\n権限を濫用／乱用すれば、一時的に目的を達成できても組織への信頼は失われる。\n译：如果滥用权限，即使一时达成目的，也会失去对组织的信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3107","seq":3107,"level":"N1","type":"主词条","word":"リーダー","kana":"りーだー（leader）","pos":"[名]","accent":"①","meaning":"领导","example":"リーダーが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“领导”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nリーダーが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“领导”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3108","seq":3108,"level":"N1","type":"主词条","word":"リード","kana":"りーど（lead）","pos":"[名·自他動3]","accent":"①","meaning":"领导，带领；领先","example":"経験豊富な先輩が議論をリードしたことで、短時間で結論をまとめることができた。","exampleZh":"经验丰富的前辈带领讨论，使大家能在短时间内总结出结论。","note":"例：\n経験豊富な先輩が議論をリードしたことで、短時間で結論をまとめることができた。\n译：经验丰富的前辈带领讨论，使大家能在短时间内总结出结论。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3109","seq":3109,"level":"N1","type":"主词条","word":"リクエスト","kana":"りくえすと（request）","pos":"[名·他動3]","accent":"③","meaning":"要求；（听众、观众）点播节目","example":"視聴者からのリクエストが多かった曲を流すと、番組には昔の思い出を語るメールが次々に届いた。","exampleZh":"播放观众点播较多的歌曲后，节目接连收到讲述往日回忆的邮件。","note":"例：\n視聴者からのリクエストが多かった曲を流すと、番組には昔の思い出を語るメールが次々に届いた。\n译：播放观众点播较多的歌曲后，节目接连收到讲述往日回忆的邮件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3110","seq":3110,"level":"N1","type":"主词条","word":"陸上","kana":"りくじょう","pos":"[名]","accent":"⓪","meaning":"地上；田径赛","example":"陸上をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。","exampleZh":"以“地上；田径赛”为契机，此前含糊不清的责任分工和判断标准再次被追问。","note":"例：\n陸上をきっかけに、今まで曖昧だった責任の分担や判断基準が改めて問われることになった。\n译：以“地上；田径赛”为契机，此前含糊不清的责任分工和判断标准再次被追问。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3111","seq":3111,"level":"N1","type":"主词条","word":"理屈","kana":"りくつ","pos":"[名]","accent":"⓪","meaning":"道理，理由，理论；歪理，诡辩","example":"理屈が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“道理，理由，理论；歪理，诡辩”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n理屈が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“道理，理由，理论；歪理，诡辩”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3112","seq":3112,"level":"N1","type":"主词条","word":"理屈っぽい","kana":"りくつっぽい","pos":"[イ形]","accent":"⑤","meaning":"好讲理，爱诡辩","example":"理屈っぽい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。","exampleZh":"即使处在“好讲理，爱诡辩”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","note":"例：\n理屈っぽい状況に置かれても、彼女は感情だけで動かず、まず事実を整理して次の一手を考えた。\n译：即使处在“好讲理，爱诡辩”的状况下，她也没有只凭情绪行动，而是先整理事实，再思考下一步。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3113","seq":3113,"level":"N1","type":"主词条","word":"リコール","kana":"りこーる（recall）","pos":"[名·他動3]","accent":"②","meaning":"召回；罢免","example":"欠陥が見つかった製品をリコールすることで、会社は利用者の安全を最優先する姿勢を示した。","exampleZh":"通过召回发现缺陷的产品，公司表现出把使用者安全放在首位的态度。","note":"例：\n欠陥が見つかった製品をリコールすることで、会社は利用者の安全を最優先する姿勢を示した。\n译：通过召回发现缺陷的产品，公司表现出把使用者安全放在首位的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3114","seq":3114,"level":"N1","type":"主词条","word":"利己的","kana":"りこてき","pos":"[ナ形]","accent":"⓪","meaning":"自私自利","example":"利己的な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。","exampleZh":"越是给人“自私自利”印象的事物，越应确认背后的条件和例外后再作评价。","note":"例：\n利己的な印象を与えるものほど、背景にある条件や例外を確認してから評価したい。\n译：越是给人“自私自利”印象的事物，越应确认背后的条件和例外后再作评价。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3115","seq":3115,"level":"N1","type":"主词条","word":"利潤","kana":"りじゅん","pos":"[名]","accent":"⓪","meaning":"利润","example":"利潤をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。","exampleZh":"围绕“利润”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","note":"例：\n利潤をめぐって迷ったとき、彼女は自分の都合よりも相手に残る負担を先に考えた。\n译：围绕“利润”犹豫不决时，她先考虑的不是自己的方便，而是对方之后可能承担的负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3116","seq":3116,"level":"N1","type":"主词条","word":"理性","kana":"りせい","pos":"[名]","accent":"①⓪","meaning":"理性","example":"理性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“理性”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n理性を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“理性”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3117","seq":3117,"level":"N1","type":"主词条","word":"理知","kana":"りち","pos":"[名]","accent":"①","meaning":"理智","example":"感情が高ぶる場面でこそ理知を働かせ、彼は相手を責める前に事実関係を一つずつ確かめた。","exampleZh":"越是在情绪高涨的场面，越要发挥理智；他在责备对方前逐一确认事实关系。","note":"例：\n感情が高ぶる場面でこそ理知を働かせ、彼は相手を責める前に事実関係を一つずつ確かめた。\n译：越是在情绪高涨的场面，越要发挥理智；他在责备对方前逐一确认事实关系。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3118","seq":3118,"level":"N1","type":"主词条","word":"立食","kana":"りっしょく","pos":"[名]","accent":"⓪","meaning":"站着吃","example":"立食を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。","exampleZh":"使用“站着吃”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","note":"例：\n立食を利用する人が増えたため、自治体は混雑する時間帯の案内と安全対策を見直した。\n译：使用“站着吃”的人增加后，地方政府重新审视了拥挤时段的引导和安全对策。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3119","seq":3119,"level":"N1","type":"主词条","word":"立体","kana":"りったい","pos":"[名]","accent":"⓪","meaning":"立体","example":"立体を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“立体”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n立体を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“立体”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3120","seq":3120,"level":"N1","type":"主词条","word":"利点","kana":"りてん","pos":"[名]","accent":"⓪","meaning":"长处，优点","example":"利点の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。","exampleZh":"如果对“长处，优点”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","note":"例：\n利点の扱いを誤ると小さな不満が残るため、担当者は最初の確認を丁寧に行った。\n译：如果对“长处，优点”处理不当，就会留下细小不满，因此负责人细致完成了最初确认。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3121","seq":3121,"level":"N1","type":"主词条","word":"理念","kana":"りねん","pos":"[名]","accent":"①","meaning":"理念","example":"理念に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“理念”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n理念に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“理念”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3122","seq":3122,"level":"N1","type":"主词条","word":"リハビリ","kana":"りはびり","pos":"[名]","accent":"⓪","meaning":"医疗指导，康复训练","example":"リハビリを身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“医疗指导，康复训练”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\nリハビリを身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“医疗指导，康复训练”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3123","seq":3123,"level":"N1","type":"主词条","word":"理不尽","kana":"りふじん","pos":"[名·ナ形]","accent":"②","meaning":"不讲理","example":"理不尽な扱いを受けたと感じても、彼は感情的に反論せず、事実を整理して冷静に抗議した。","exampleZh":"即使觉得受到了不讲理的对待，他也没有情绪化反驳，而是整理事实后冷静抗议。","note":"例：\n理不尽な扱いを受けたと感じても、彼は感情的に反論せず、事実を整理して冷静に抗議した。\n译：即使觉得受到了不讲理的对待，他也没有情绪化反驳，而是整理事实后冷静抗议。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3124","seq":3124,"level":"N1","type":"主词条","word":"リフレッシュ","kana":"りふれっしゅ（refresh）","pos":"[名·自動3]","accent":"③","meaning":"放松，恢复精神","example":"リフレッシュするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“放松，恢复精神”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\nリフレッシュするときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“放松，恢复精神”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3125","seq":3125,"level":"N1","type":"主词条","word":"リミット","kana":"りみっと（limit）","pos":"[名]","accent":"①","meaning":"限度，界限；极限","example":"締め切りのリミットが近づくほど、彼は作業を増やすのではなく、やるべきことを絞り込んだ。","exampleZh":"截止期限越临近，他越不是增加作业，而是压缩必须做的事项。","note":"例：\n締め切りのリミットが近づくほど、彼は作業を増やすのではなく、やるべきことを絞り込んだ。\n译：截止期限越临近，他越不是增加作业，而是压缩必须做的事项。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3126","seq":3126,"level":"N1","type":"主词条","word":"略奪","kana":"りゃくだつ","pos":"[名·他動3]","accent":"⓪","meaning":"掠夺","example":"略奪する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。","exampleZh":"在进行“掠夺”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","note":"例：\n略奪する前に、担当者は必要な条件を洗い出し、結果が誰に影響するかを整理した。\n译：在进行“掠夺”之前，负责人先梳理了必要条件，并确认结果会影响到哪些人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3127","seq":3127,"level":"N1","type":"主词条","word":"流暢","kana":"りゅうちょう","pos":"[名·ナ形]","accent":"①","meaning":"流畅，流利","example":"流暢な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“流畅，流利”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n流暢な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“流畅，流利”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3128","seq":3128,"level":"N1","type":"主词条","word":"流通","kana":"りゅうつう","pos":"[名·自動3]","accent":"⓪","meaning":"流通","example":"商品の流通が滞ると、店頭の価格だけでなく、家庭の食卓にもすぐに影響が及ぶ。","exampleZh":"商品流通停滞后，不仅店头价格，连家庭餐桌也会立刻受到影响。","note":"例：\n商品の流通が滞ると、店頭の価格だけでなく、家庭の食卓にもすぐに影響が及ぶ。\n译：商品流通停滞后，不仅店头价格，连家庭餐桌也会立刻受到影响。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3129","seq":3129,"level":"N1","type":"主词条","word":"領域","kana":"りょういき","pos":"[名]","accent":"⓪","meaning":"领域","example":"専門外の領域に踏み込むときほど、彼は経験者の助言を聞き、思い込みで判断しないようにしている。","exampleZh":"越是踏入专业外领域，他越会听取有经验者的建议，避免凭臆测判断。","note":"例：\n専門外の領域に踏み込むときほど、彼は経験者の助言を聞き、思い込みで判断しないようにしている。\n译：越是踏入专业外领域，他越会听取有经验者的建议，避免凭臆测判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3130","seq":3130,"level":"N1","type":"主词条","word":"領海","kana":"りょうかい","pos":"[名]","accent":"⓪","meaning":"领海","example":"領海の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。","exampleZh":"每年记录“领海”的变化，就会注意到气候和地区生活正在一点点改变。","note":"例：\n領海の変化を毎年記録しておくと、気候や地域の暮らしが少しずつ変わっていることに気づく。\n译：每年记录“领海”的变化，就会注意到气候和地区生活正在一点点改变。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3131","seq":3131,"level":"N1","type":"主词条","word":"両極","kana":"りょうきょく","pos":"[名]","accent":"⓪","meaning":"两极","example":"両極を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。","exampleZh":"面对“两极”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","note":"例：\n両極を前にして、彼女は過去の経験だけに頼らず、関係者の声を聞き直した。\n译：面对“两极”时，她没有只依靠过去经验，而是重新倾听了相关人员的声音。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3132","seq":3132,"level":"N1","type":"主词条","word":"良好","kana":"りょうこう","pos":"[名·ナ形]","accent":"⓪","meaning":"良好","example":"良好な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“良好”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n良好な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“良好”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3133","seq":3133,"level":"N1","type":"主词条","word":"量産","kana":"りょうさん","pos":"[名·他動3]","accent":"⓪","meaning":"批量生产","example":"試作品の評価が高かったため、会社は来年度からその部品を量産する方針を決めた。","exampleZh":"由于试制品评价很高，公司决定从下一年度起量产该零件。","note":"例：\n試作品の評価が高かったため、会社は来年度からその部品を量産する方針を決めた。\n译：由于试制品评价很高，公司决定从下一年度起量产该零件。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3134","seq":3134,"level":"N1","type":"主词条","word":"良識","kana":"りょうしき","pos":"[名]","accent":"⓪","meaning":"正确的判断力","example":"彼は良識を深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。","exampleZh":"为了加深对“正确的判断力”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","note":"例：\n彼は良識を深めるため、専門書を読むだけでなく、現場で経験を重ねて理解を確かめた。\n译：为了加深对“正确的判断力”的理解，他不仅阅读专业书，也在现场积累经验来确认认识。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3135","seq":3135,"level":"N1","type":"主词条","word":"了承","kana":"りょうしょう","pos":"[名·他動3]","accent":"⓪","meaning":"明白，谅解，同意","example":"了承する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“明白，谅解，同意”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n了承する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“明白，谅解，同意”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3136","seq":3136,"level":"N1","type":"主词条","word":"良心","kana":"りょうしん","pos":"[名]","accent":"①","meaning":"良心","example":"良心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。","exampleZh":"如果在被“良心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","note":"例：\n良心に支配されたまま言い返すと、解決できる問題までこじれるため、彼は少し時間を置くことにした。\n译：如果在被“良心”支配的状态下回嘴，连本可解决的问题也会复杂化，因此他决定稍微放一段时间。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3137","seq":3137,"level":"N1","type":"主词条","word":"領地","kana":"りょうち","pos":"[名]","accent":"①","meaning":"领地","example":"領地を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“领地”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n領地を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“领地”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3138","seq":3138,"level":"N1","type":"主词条","word":"領土","kana":"りょうど","pos":"[名]","accent":"①","meaning":"领土","example":"領土を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“领土”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\n領土を守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“领土”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3139","seq":3139,"level":"N1","type":"主词条","word":"量販","kana":"りょうはん","pos":"[名·他動3]","accent":"⓪","meaning":"量贩","example":"量販店では同じ商品を大量に仕入れることで、通常より安い価格を実現している。","exampleZh":"量贩店通过大量采购同一商品，实现比通常更低的价格。","note":"例：\n量販店では同じ商品を大量に仕入れることで、通常より安い価格を実現している。\n译：量贩店通过大量采购同一商品，实现比通常更低的价格。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3140","seq":3140,"level":"N1","type":"主词条","word":"両立","kana":"りょうりつ","pos":"[名·自動3]","accent":"⓪","meaning":"并存，兼顾","example":"両立してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“并存，兼顾”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\n両立してから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“并存，兼顾”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3141","seq":3141,"level":"N1","type":"主词条","word":"旅券","kana":"りょけん","pos":"[名]","accent":"⓪","meaning":"护照","example":"旅券に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。","exampleZh":"接触到“护照”之后，他开始注意到平时可能忽略的细微不协调感。","note":"例：\n旅券に触れたことで、彼は普段なら見過ごしていた小さな違和感にも注意を向けるようになった。\n译：接触到“护照”之后，他开始注意到平时可能忽略的细微不协调感。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3142","seq":3142,"level":"N1","type":"主词条","word":"リラックス","kana":"りらっくす（relax）","pos":"[名·自動3]","accent":"②","meaning":"放松，松弛","example":"リラックスしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。","exampleZh":"为了避免等到“放松，松弛”之后才慌张，他及早察觉征兆，并确保了必要支援。","note":"例：\nリラックスしてから慌てないよう、彼は兆候を早めに察知し、必要な支援を確保した。\n译：为了避免等到“放松，松弛”之后才慌张，他及早察觉征兆，并确保了必要支援。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3143","seq":3143,"level":"N1","type":"主词条","word":"リレー","kana":"りれー（relay）","pos":"[名·他動3]","accent":"⓪①","meaning":"接力，传递","example":"部署を越えたリレー形式で作業を進めたため、担当者は次の人が困らないよう記録を丁寧に残した。","exampleZh":"以跨部门接力形式推进作业，因此负责人细致留下记录，避免下一位接手者困扰。","note":"例：\n部署を越えたリレー形式で作業を進めたため、担当者は次の人が困らないよう記録を丁寧に残した。\n译：以跨部门接力形式推进作业，因此负责人细致留下记录，避免下一位接手者困扰。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3144","seq":3144,"level":"N1","type":"主词条","word":"理論","kana":"りろん","pos":"[名]","accent":"①","meaning":"理论","example":"理論が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。","exampleZh":"“理论”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","note":"例：\n理論が蓄積されるほど、組織は個人の勘に頼らず、再現性のある方法で問題を解決できるようになる。\n译：“理论”积累得越多，组织就越能不依赖个人直觉，而以可复现的方法解决问题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3145","seq":3145,"level":"N1","type":"主词条","word":"輪郭","kana":"りんかく","pos":"[名]","accent":"⓪","meaning":"轮廓，外形；概要","example":"彼女は輪郭をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“轮廓，外形；概要”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は輪郭をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“轮廓，外形；概要”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3146","seq":3146,"level":"N1","type":"主词条","word":"倫理","kana":"りんり","pos":"[名]","accent":"①","meaning":"伦理，人伦","example":"経験豊かな倫理の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。","exampleZh":"在经验丰富的“伦理，人伦”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","note":"例：\n経験豊かな倫理の助言によって、若い担当者は問題を一面的に見ていたことに気づいた。\n译：在经验丰富的“伦理，人伦”提出建议后，年轻负责人意识到自己此前把问题看得过于片面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3147","seq":3147,"level":"N1","type":"主词条","word":"類","kana":"るい","pos":"[名]","accent":"①","meaning":"同类，同伴","example":"この類の問題は表面だけ直しても再発するため、仕組み全体を見直す必要がある。","exampleZh":"这类问题只修补表面也会复发，因此有必要重新审视整个机制。","note":"例：\nこの類の問題は表面だけ直しても再発するため、仕組み全体を見直す必要がある。\n译：这类问题只修补表面也会复发，因此有必要重新审视整个机制。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3148","seq":3148,"level":"N1","type":"主词条","word":"～類","kana":"～るい","pos":"[接尾]","accent":"","meaning":"……类别，类型","example":"書類を分類して保管する際は、提出期限と担当部署がすぐ分かるよう見出しを付けておくとよい。","exampleZh":"分类保管文件时，如果加上能立刻看出提交期限和负责部门的标题会更好。","note":"例：\n書類を分類して保管する際は、提出期限と担当部署がすぐ分かるよう見出しを付けておくとよい。\n译：分类保管文件时，如果加上能立刻看出提交期限和负责部门的标题会更好。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3149","seq":3149,"level":"N1","type":"主词条","word":"類型","kana":"るいけい","pos":"[名]","accent":"⓪","meaning":"类型","example":"類型だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。","exampleZh":"如果只凭“类型”评价一个人，就会忽视其努力过程和对周围的贡献。","note":"例：\n類型だけで人を評価すると、努力の過程や周囲への貢献を見落としてしまう。\n译：如果只凭“类型”评价一个人，就会忽视其努力过程和对周围的贡献。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3150","seq":3150,"level":"N1","type":"主词条","word":"類型的","kana":"るいけいてき","pos":"[ナ形]","accent":"⓪","meaning":"刻板，公式化","example":"一度類型的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“刻板，公式化”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度類型的だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“刻板，公式化”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3151","seq":3151,"level":"N1","type":"主词条","word":"類する","kana":"るいする","pos":"[自動3]","accent":"③","meaning":"相似，类似","example":"過去の事故に類する例を調べることで、今回の不具合が偶然ではない可能性が見えてきた。","exampleZh":"调查类似过去事故的案例后，可以看出这次故障可能并非偶然。","note":"例：\n過去の事故に類する例を調べることで、今回の不具合が偶然ではない可能性が見えてきた。\n译：调查类似过去事故的案例后，可以看出这次故障可能并非偶然。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3152","seq":3152,"level":"N1","type":"主词条","word":"ルーズ","kana":"るーず（loose）","pos":"[名·ナ形]","accent":"①","meaning":"懒散","example":"ルーズな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“懒散”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nルーズな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“懒散”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3153","seq":3153,"level":"N1","type":"主词条","word":"ルーツ","kana":"るーつ（roots）","pos":"[名]","accent":"①","meaning":"根源，起源；发祥地","example":"ルーツが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“根源，起源；发祥地”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nルーツが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“根源，起源；发祥地”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3154","seq":3154,"level":"N1","type":"主词条","word":"ルート","kana":"るーと（route）","pos":"[名]","accent":"①","meaning":"路线；途径，门路","example":"古いルートを不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。","exampleZh":"如果随意移动旧的“路线；途径，门路”可能导致事故，因此作业人员确认步骤后才谨慎处理。","note":"例：\n古いルートを不用意に動かすと事故につながるため、作業員は手順を確認してから慎重に扱った。\n译：如果随意移动旧的“路线；途径，门路”可能导致事故，因此作业人员确认步骤后才谨慎处理。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3155","seq":3155,"level":"N1","type":"主词条","word":"冷夏","kana":"れいか","pos":"[名]","accent":"①","meaning":"夏季异常低温","example":"冷夏の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。","exampleZh":"在“夏季异常低温”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","note":"例：\n冷夏の日には気分まで明るくなるが、彼は油断せず午後の天候の変化も確認した。\n译：在“夏季异常低温”的日子里，连心情都会明朗起来，但他没有大意，也确认了下午天气变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3156","seq":3156,"level":"N1","type":"主词条","word":"冷害","kana":"れいがい","pos":"[名]","accent":"⓪","meaning":"（夏天）低温灾害","example":"突然の冷害で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。","exampleZh":"突如其来的“低温灾害”导致交通混乱，负责人立即通知参加者改到替代集合地点。","note":"例：\n突然の冷害で交通が乱れ、担当者は参加者に代替の集合場所をすぐに知らせた。\n译：突如其来的“低温灾害”导致交通混乱，负责人立即通知参加者改到替代集合地点。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3157","seq":3157,"level":"N1","type":"主词条","word":"冷酷","kana":"れいこく","pos":"[名·ナ形]","accent":"⓪","meaning":"冷酷","example":"冷酷な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。","exampleZh":"如果“冷酷”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","note":"例：\n冷酷な状態が続けば小さな不満が積み重なるため、責任者は早めに話し合いの場を設けた。\n译：如果“冷酷”的状态持续下去，小小不满也会逐渐累积，因此负责人尽早安排了沟通机会。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3158","seq":3158,"level":"N1","type":"主词条","word":"零細","kana":"れいさい","pos":"[名·ナ形]","accent":"⓪","meaning":"零碎；规模小","example":"零細企業が新しい市場に参入するには、大手にはない柔軟さを強みにする必要がある。","exampleZh":"零细企业要进入新市场，需要把大企业没有的灵活性作为优势。","note":"例：\n零細企業が新しい市場に参入するには、大手にはない柔軟さを強みにする必要がある。\n译：零细企业要进入新市场，需要把大企业没有的灵活性作为优势。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3159","seq":3159,"level":"N1","type":"主词条","word":"冷淡","kana":"れいたん","pos":"[名·ナ形]","accent":"⓪","meaning":"冷漠，不关心","example":"周囲から冷淡だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“冷漠，不关心”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から冷淡だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“冷漠，不关心”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3160","seq":3160,"level":"N1","type":"主词条","word":"レーザー","kana":"れーざー（laser）","pos":"[名]","accent":"①","meaning":"激光，激光器","example":"レーザーを守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。","exampleZh":"守护“激光，激光器”的活动看似朴素，却也关系到地区安全和孩子们的学习。","note":"例：\nレーザーを守る活動は地味に見えるが、地域の安全や子どもたちの学びにもつながっている。\n译：守护“激光，激光器”的活动看似朴素，却也关系到地区安全和孩子们的学习。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3161","seq":3161,"level":"N1","type":"主词条","word":"レール","kana":"れーる（rail）","pos":"[名]","accent":"⓪","meaning":"轨道；事先的准备","example":"レールを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。","exampleZh":"如果在制定“轨道；事先的准备”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","note":"例：\nレールを立てる段階で利用者の声を聞いておけば、開始後の混乱をかなり減らせるはずだ。\n译：如果在制定“轨道；事先的准备”的阶段就听取使用者声音，开始后的混乱应该会大幅减少。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3162","seq":3162,"level":"N1","type":"主词条","word":"歴然","kana":"れきぜん","pos":"[副·ナ形]","accent":"⓪","meaning":"明显，分明","example":"同じ研修を受けても、経験の差は歴然としており、現場での判断速度に大きな違いが出た。","exampleZh":"即使接受同样培训，经验差异也十分明显，现场判断速度会产生很大不同。","note":"例：\n同じ研修を受けても、経験の差は歴然としており、現場での判断速度に大きな違いが出た。\n译：即使接受同样培训，经验差异也十分明显，现场判断速度会产生很大不同。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3163","seq":3163,"level":"N1","type":"主词条","word":"レギュラー","kana":"れぎゅらー（regular）","pos":"[名]","accent":"①","meaning":"正式，普通，一般","example":"レギュラーが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“正式，普通，一般”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nレギュラーが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“正式，普通，一般”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3164","seq":3164,"level":"N1","type":"主词条","word":"～レス","kana":"～れす（less）","pos":"[接尾]","accent":"①","meaning":"无……","example":"ペーパーレス化を進めているとはいえ、高齢の利用者には紙の案内も残すなど柔軟な対応が必要だ。","exampleZh":"虽说在推进无纸化，但对老年使用者仍保留纸质说明等灵活应对也很必要。","note":"例：\nペーパーレス化を進めているとはいえ、高齢の利用者には紙の案内も残すなど柔軟な対応が必要だ。\n译：虽说在推进无纸化，但对老年使用者仍保留纸质说明等灵活应对也很必要。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3165","seq":3165,"level":"N1","type":"主词条","word":"レセプション","kana":"れせぷしょん（reception）","pos":"[名]","accent":"②","meaning":"欢迎会，宴会","example":"レセプションが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。","exampleZh":"在涉及“欢迎会，宴会”的场面中，比起便利性，更需要不忽视后续影响的态度。","note":"例：\nレセプションが関係する場面では、便利さよりも後に残る影響を見落とさない姿勢が必要だ。\n译：在涉及“欢迎会，宴会”的场面中，比起便利性，更需要不忽视后续影响的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3166","seq":3166,"level":"N1","type":"主词条","word":"劣等","kana":"れっとう","pos":"[名·ナ形]","accent":"⓪","meaning":"劣等，低劣","example":"一度劣等だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“劣等，低劣”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度劣等だと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“劣等，低劣”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3167","seq":3167,"level":"N1","type":"主词条","word":"レバー","kana":"ればー（lever）","pos":"[名]","accent":"①","meaning":"控制杆，操纵杆","example":"機械のレバーを操作する前に、作業員は周囲に人がいないか声をかけて確認した。","exampleZh":"操作机器操纵杆前，作业人员出声确认了周围是否有人。","note":"例：\n機械のレバーを操作する前に、作業員は周囲に人がいないか声をかけて確認した。\n译：操作机器操纵杆前，作业人员出声确认了周围是否有人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3168","seq":3168,"level":"N1","type":"主词条","word":"連携","kana":"れんけい","pos":"[名·自動3]","accent":"⓪","meaning":"合作","example":"連携する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n連携する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“合作”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3169","seq":3169,"level":"N1","type":"主词条","word":"連帯","kana":"れんたい","pos":"[名·自動3]","accent":"⓪","meaning":"协作，联合；连带","example":"連帯する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。","exampleZh":"在进行“协作，联合；连带”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","note":"例：\n連帯する前に、彼は目的と条件を整理し、無理なく責任を果たせるかを慎重に考えた。\n译：在进行“协作，联合；连带”之前，他整理了目的和条件，并慎重考虑自己能否在不过度勉强的情况下履行责任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3170","seq":3170,"level":"N1","type":"主词条","word":"レンタカー","kana":"れんたかー（rent-a-car）","pos":"[名]","accent":"③④","meaning":"租车","example":"新しいレンタカーが整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。","exampleZh":"新的“租车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","note":"例：\n新しいレンタカーが整備されると物流は便利になる一方、周辺の生活道路に負担が集中する恐れもある。\n译：新的“租车”建成后物流会更便利，但周边生活道路也可能承受集中负担。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3171","seq":3171,"level":"N1","type":"主词条","word":"連中","kana":"れんちゅう","pos":"[名]","accent":"⓪","meaning":"伙伴，同伙","example":"連中として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。","exampleZh":"要作为“伙伴，同伙”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","note":"例：\n連中として信頼されるには、目立つ成果だけでなく、失敗したときの誠実な対応も欠かせない。\n译：要作为“伙伴，同伙”获得信任，不仅需要醒目的成果，失败时诚实应对也不可或缺。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3172","seq":3172,"level":"N1","type":"主词条","word":"連邦","kana":"れんぽう","pos":"[名]","accent":"⓪","meaning":"联邦","example":"新しい連邦を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。","exampleZh":"运用新的“联邦”时，需要反映当事人的声音，避免负担只偏向一部分人。","note":"例：\n新しい連邦を運用する際には、一部の人だけに負担が偏らないよう、当事者の声を反映させる必要がある。\n译：运用新的“联邦”时，需要反映当事人的声音，避免负担只偏向一部分人。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3173","seq":3173,"level":"N1","type":"主词条","word":"老衰","kana":"ろうすい","pos":"[名·自動3]","accent":"⓪","meaning":"衰老，老死","example":"老衰するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。","exampleZh":"进行“衰老，老死”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","note":"例：\n老衰するときは周囲にも変化が及ぶため、担当者は事前に連絡経路と代替案を整えた。\n译：进行“衰老，老死”时会影响周围，因此负责人事先准备好了联络渠道和替代方案。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3174","seq":3174,"level":"N1","type":"主词条","word":"老若男女","kana":"ろうにゃくなんにょ","pos":"[名]","accent":"⑤","meaning":"男女老少","example":"老若男女を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。","exampleZh":"要正确理解和处理“男女老少”，不能只知道名称，还要观察它被使用的场面以及周围反应。","note":"例：\n老若男女を正しく扱うには、名前だけを知るのではなく、使われる場面と周囲の反応を見ることが大切だ。\n译：要正确理解和处理“男女老少”，不能只知道名称，还要观察它被使用的场面以及周围反应。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3175","seq":3175,"level":"N1","type":"主词条","word":"朗報","kana":"ろうほう","pos":"[名]","accent":"⓪","meaning":"好消息，喜讯","example":"彼女は朗報をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。","exampleZh":"她没有照单全收“好消息，喜讯”，而是连发布者立场和公开时间都确认后再作判断。","note":"例：\n彼女は朗報をそのまま信じず、発信者の立場や公開された時期まで確認してから判断した。\n译：她没有照单全收“好消息，喜讯”，而是连发布者立场和公开时间都确认后再作判断。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3176","seq":3176,"level":"N1","type":"主词条","word":"労力","kana":"ろうりょく","pos":"[名]","accent":"①","meaning":"费力；劳动力","example":"彼の労力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。","exampleZh":"他的“费力；劳动力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","note":"例：\n彼の労力は派手ではないが、難しい状況でも相手の意図を読み取り、確実に結果へつなげている。\n译：他的“费力；劳动力”并不张扬，却能在困难局面中读懂对方意图，并切实导向结果。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3177","seq":3177,"level":"N1","type":"主词条","word":"ロープ","kana":"ろーぷ（rope）","pos":"[名]","accent":"①","meaning":"绳索，钢缆","example":"ロープが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。","exampleZh":"当“绳索，钢缆”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","note":"例：\nロープが問題になったとき、彼は印象だけで反応せず、具体的に誰が困るのかを考えた。\n译：当“绳索，钢缆”成为问题时，他没有只凭印象反应，而是具体思考谁会因此受困。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3178","seq":3178,"level":"N1","type":"主词条","word":"ろく","kana":"ろく","pos":"[ナ形]","accent":"⓪","meaning":"像样，令人满意","example":"ろくな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。","exampleZh":"在需要“像样，令人满意”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","note":"例：\nろくな対応が求められる場面では、形式だけでなく相手がどう受け取るかまで考える必要がある。\n译：在需要“像样，令人满意”应对的场面中，不仅要看形式，还要考虑对方会如何理解。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3179","seq":3179,"level":"N1","type":"主词条","word":"露骨","kana":"ろこつ","pos":"[名·ナ形]","accent":"⓪","meaning":"露骨，直率","example":"周囲から露骨だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。","exampleZh":"为了不让周围人把它理解成“露骨，直率”，他先整理依据和步骤，然后才表达意见。","note":"例：\n周囲から露骨だと受け取られないよう、彼は根拠と手順を整理してから意見を伝えた。\n译：为了不让周围人把它理解成“露骨，直率”，他先整理依据和步骤，然后才表达意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3180","seq":3180,"level":"N1","type":"主词条","word":"路地","kana":"ろじ","pos":"[名]","accent":"⓪","meaning":"胡同，小巷","example":"観光客が増えた路地では、便利さと静かな生活をどう両立させるかが新しい課題になっている。","exampleZh":"在游客增多的“胡同，小巷”，如何兼顾便利与安静生活成了新的课题。","note":"例：\n観光客が増えた路地では、便利さと静かな生活をどう両立させるかが新しい課題になっている。\n译：在游客增多的“胡同，小巷”，如何兼顾便利与安静生活成了新的课题。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3181","seq":3181,"level":"N1","type":"主词条","word":"ロス","kana":"ろす（loss）","pos":"[名·他動3]","accent":"①","meaning":"浪费，损耗","example":"食品ロスを減らすため、店は閉店前の商品を割引して販売する取り組みを始めた。","exampleZh":"为了减少食品损耗，店铺开始在闭店前打折销售商品。","note":"例：\n食品ロスを減らすため、店は閉店前の商品を割引して販売する取り組みを始めた。\n译：为了减少食品损耗，店铺开始在闭店前打折销售商品。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3182","seq":3182,"level":"N1","type":"主词条","word":"ロマンチック","kana":"ろまんちっく（romantic）","pos":"[ナ形]","accent":"④","meaning":"浪漫","example":"一度ロマンチックだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。","exampleZh":"一旦被判断为“浪漫”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","note":"例：\n一度ロマンチックだと判断されると信頼を戻すのは難しいため、彼女は最初の対応を特に丁寧にした。\n译：一旦被判断为“浪漫”，要恢复信任就很困难，因此她格外谨慎地处理最初的应对。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3183","seq":3183,"level":"N1","type":"主词条","word":"論議","kana":"ろんぎ","pos":"[名·自他動3]","accent":"①","meaning":"讨论，议论","example":"論議する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。","exampleZh":"在需要处理“讨论，议论”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","note":"例：\n論議する場面では手順を急がず、相手の理解と安全を確かめてから進めるべきだ。\n译：在需要处理“讨论，议论”的场景中，不应急于推进步骤，而应先确认对方的理解和安全。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3184","seq":3184,"level":"N1","type":"主词条","word":"論理","kana":"ろんり","pos":"[名]","accent":"①","meaning":"道理，逻辑","example":"論理を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。","exampleZh":"要掌握“道理，逻辑”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","note":"例：\n論理を身につけるには、答えを覚えるだけでなく、自分の失敗を振り返って次に生かす姿勢が欠かせない。\n译：要掌握“道理，逻辑”，不能只是记住答案，还必须具备回顾自身失败并用于下一次的态度。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3185","seq":3185,"level":"N1","type":"主词条","word":"沸き上がる","kana":"わきあがる","pos":"[自動1]","accent":"④","meaning":"煮开；狂热，沸腾","example":"沸き上がるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。","exampleZh":"在出现“煮开；狂热，沸腾”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","note":"例：\n沸き上がるとき、彼は慌てて結論を出さず、まず何が変わったのかを静かに整理した。\n译：在出现“煮开；狂热，沸腾”的时候，他没有慌忙下结论，而是先冷静梳理发生了什么变化。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3186","seq":3186,"level":"N1","type":"主词条","word":"枠","kana":"わく","pos":"[名]","accent":"②","meaning":"轮廓，框；限制，范围","example":"枠を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。","exampleZh":"如果无视“轮廓，框；限制，范围”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","note":"例：\n枠を無視して進めれば、短期的には楽でも、後で関係者の不信を招くおそれがある。\n译：如果无视“轮廓，框；限制，范围”而继续推进，短期内也许轻松，之后却可能招致相关人员的不信任。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3187","seq":3187,"level":"N1","type":"主词条","word":"わくわく","kana":"わくわく","pos":"[副·自動3]","accent":"①","meaning":"（因兴奋或期待）心扑通扑通跳","example":"初めての海外研修を前に、彼女は期待で胸がわくわくしていた。","exampleZh":"第一次海外研修前，她满怀期待，心情兴奋。","note":"例：\n初めての海外研修を前に、彼女は期待で胸がわくわくしていた。\n译：第一次海外研修前，她满怀期待，心情兴奋。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3188","seq":3188,"level":"N1","type":"主词条","word":"わざとらしい","kana":"わざとらしい","pos":"[イ形]","accent":"⑤","meaning":"做作","example":"わざとらしい笑顔でごまかそうとしても、相手には不満を隠していることがすぐに伝わる。","exampleZh":"即使用做作的笑容试图蒙混过去，对方也马上能看出他隐藏着不满。","note":"例：\nわざとらしい笑顔でごまかそうとしても、相手には不満を隠していることがすぐに伝わる。\n译：即使用做作的笑容试图蒙混过去，对方也马上能看出他隐藏着不满。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3189","seq":3189,"level":"N1","type":"主词条","word":"わざわざ","kana":"わざわざ","pos":"[副]","accent":"①","meaning":"特意；故意","example":"遠いところをわざわざ訪ねてくれた友人に、彼は心から感謝の言葉を伝えた。","exampleZh":"朋友特意远道来访，他真心表达了感谢。","note":"例：\n遠いところをわざわざ訪ねてくれた友人に、彼は心から感謝の言葉を伝えた。\n译：朋友特意远道来访，他真心表达了感谢。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3190","seq":3190,"level":"N1","type":"主词条","word":"患う","kana":"わずらう","pos":"[他動1]","accent":"⓪③","meaning":"生病","example":"祖母は長い間病を患っていたが、家族の支えを受けながら穏やかに日々を過ごしていた。","exampleZh":"祖母长期患病，但在家人支持下平静地度过每一天。","note":"例：\n祖母は長い間病を患っていたが、家族の支えを受けながら穏やかに日々を過ごしていた。\n译：祖母长期患病，但在家人支持下平静地度过每一天。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3191","seq":3191,"level":"N1","type":"主词条","word":"～煩う","kana":"～わずらう","pos":"[接尾]","accent":"","meaning":"犹豫不决，不爽快","example":"彼は返事を言いわずらって黙ってしまったが、相手は急かさず静かに次の言葉を待った。","exampleZh":"他犹豫着说不出口而沉默下来，对方没有催促，只是静静等待他下一句话。","note":"例：\n彼は返事を言いわずらって黙ってしまったが、相手は急かさず静かに次の言葉を待った。\n译：他犹豫着说不出口而沉默下来，对方没有催促，只是静静等待他下一句话。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3192","seq":3192,"level":"N1","type":"主词条","word":"煩わしい","kana":"わずらわしい","pos":"[イ形]","accent":"⑤⓪","meaning":"烦琐，麻烦","example":"煩わしい手続きでも、後のトラブルを防ぐためには一つずつ確認して進める必要がある。","exampleZh":"即使手续繁琐，为了防止之后出现问题，也需要逐项确认并推进。","note":"例：\n煩わしい手続きでも、後のトラブルを防ぐためには一つずつ確認して進める必要がある。\n译：即使手续繁琐，为了防止之后出现问题，也需要逐项确认并推进。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3193","seq":3193,"level":"N1","type":"主词条","word":"～渡る","kana":"～わたる","pos":"[接尾]","accent":"","meaning":"完全，全面","example":"鐘の音が町中に鳴り渡ると、祭りの始まりを待っていた人々が一斉に広場へ集まり始めた。","exampleZh":"钟声响彻全城后，等待祭典开始的人们一齐聚集到广场。","note":"例：\n鐘の音が町中に鳴り渡ると、祭りの始まりを待っていた人々が一斉に広場へ集まり始めた。\n译：钟声响彻全城后，等待祭典开始的人们一齐聚集到广场。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3194","seq":3194,"level":"N1","type":"主词条","word":"ワット","kana":"わっと（watt）","pos":"[名]","accent":"①","meaning":"瓦特，瓦","example":"消費電力が六十ワットの電球に替えたところ、廊下が以前より明るくなった。","exampleZh":"换成耗电六十瓦的灯泡后，走廊比以前明亮了。","note":"例：\n消費電力が六十ワットの電球に替えたところ、廊下が以前より明るくなった。\n译：换成耗电六十瓦的灯泡后，走廊比以前明亮了。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3195","seq":3195,"level":"N1","type":"主词条","word":"和風","kana":"わふう","pos":"[名]","accent":"⓪","meaning":"日式","example":"和風の庭に置かれた石灯籠が、雨上がりの静けさをいっそう引き立てていた。","exampleZh":"日式庭园中的石灯笼，更加衬托出雨后宁静的氛围。","note":"例：\n和風の庭に置かれた石灯籠が、雨上がりの静けさをいっそう引き立てていた。\n译：日式庭园中的石灯笼，更加衬托出雨后宁静的氛围。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3196","seq":3196,"level":"N1","type":"主词条","word":"割り当て","kana":"わりあて","pos":"[名]","accent":"⓪","meaning":"分配，分摊","example":"各部署への予算の割り当てを見直したことで、現場が本当に必要としている設備に資金を回せた。","exampleZh":"通过重新审视分配给各部门的预算，资金得以用于现场真正需要的设备。","note":"例：\n各部署への予算の割り当てを見直したことで、現場が本当に必要としている設備に資金を回せた。\n译：通过重新审视分配给各部门的预算，资金得以用于现场真正需要的设备。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3197","seq":3197,"level":"N1","type":"主词条","word":"割り当てる","kana":"わりあてる","pos":"[他動2]","accent":"④","meaning":"分配，分摊","example":"責任者は作業量が偏らないよう役割を全員に割り当て、進み具合を毎日確認した。","exampleZh":"负责人为避免作业量偏向某些人，把职责分配给全员，并每天确认进展。","note":"例：\n責任者は作業量が偏らないよう役割を全員に割り当て、進み具合を毎日確認した。\n译：负责人为避免作业量偏向某些人，把职责分配给全员，并每天确认进展。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3198","seq":3198,"level":"N1","type":"主词条","word":"割り込む","kana":"わりこむ","pos":"[自動1]","accent":"③","meaning":"挤入，插队；插嘴","example":"列に割り込む人を見ても、彼女は感情的に責めず、後ろに並ぶよう静かに伝えた。","exampleZh":"看到有人插队，她没有情绪化责备，而是平静地请对方排到后面。","note":"例：\n列に割り込む人を見ても、彼女は感情的に責めず、後ろに並ぶよう静かに伝えた。\n译：看到有人插队，她没有情绪化责备，而是平静地请对方排到后面。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3199","seq":3199,"level":"N1","type":"主词条","word":"我","kana":"われ","pos":"[名]","accent":"①","meaning":"自己，自身","example":"議論で我を通すばかりでは周囲の協力を得られないため、彼は反対意見にも耳を傾けた。","exampleZh":"讨论中只是一味坚持自我无法获得周围协作，因此他也倾听反对意见。","note":"例：\n議論で我を通すばかりでは周囲の協力を得られないため、彼は反対意見にも耳を傾けた。\n译：讨论中只是一味坚持自我无法获得周围协作，因此他也倾听反对意见。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3200","seq":3200,"level":"N1","type":"主词条","word":"ワンパターン","kana":"わんぱたーん","pos":"[名·ナ形]","accent":"④","meaning":"老一套，千篇一律","example":"ワンパターンの企画ばかりでは読者に飽きられるため、編集部は取材先を広げることにした。","exampleZh":"如果企划总是千篇一律，读者会感到厌倦，因此编辑部决定扩大采访对象。","note":"例：\nワンパターンの企画ばかりでは読者に飽きられるため、編集部は取材先を広げることにした。\n译：如果企划总是千篇一律，读者会感到厌倦，因此编辑部决定扩大采访对象。","bookPage":"","source":"红书N1","status":"内置"},{"id":"n1-redbook-3201","seq":3201,"level":"N1","type":"主词条","word":"～ん坊","kana":"～んぼう","pos":"[接尾]","accent":"","meaning":"……人，……孩子","example":"甘えん坊の弟は母のそばを離れないが、幼稚園では少しずつ友達と遊ぶ時間も増えてきた。","exampleZh":"爱撒娇的弟弟虽然离不开母亲身边，但在幼儿园里也逐渐增加了和朋友一起玩的时间。","note":"例：\n甘えん坊の弟は母のそばを離れないが、幼稚園では少しずつ友達と遊ぶ時間も増えてきた。\n译：爱撒娇的弟弟虽然离不开母亲身边，但在幼儿园里也逐渐增加了和朋友一起玩的时间。","bookPage":"","source":"红书N1","status":"内置"}];
